--
-- Name: array_diff(anyarray, anyarray); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.array_diff(array1 anyarray, array2 anyarray) RETURNS anyarray
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT coalesce(array_agg(elem), '{}')
    FROM unnest(array1) elem
    WHERE elem <> ALL(array2)
$$;


ALTER FUNCTION public.array_diff(array1 anyarray, array2 anyarray) OWNER TO cppoltp;

--
-- Name: array_intersect(anyarray, anyarray); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.array_intersect(anyarray, anyarray) RETURNS anyarray
    LANGUAGE sql
    AS $_$
SELECT ARRAY(
        SELECT UNNEST($1)
        INTERSECT
        SELECT UNNEST($2)
    );
$_$;


ALTER FUNCTION public.array_intersect(anyarray, anyarray) OWNER TO cppoltp;

