--
-- Name: sp_add_admin(text, text, text, text, bigint, bigint, public.en_product_group_type[], text, integer, text, text, text, text, integer, integer, text, text, text, boolean, text, boolean); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_admin(i_login_admin_id text, i_admin_id text, i_password text, i_name text, i_privilege_profile_id bigint, i_manager_group_id bigint, i_product_auth public.en_product_group_type[], i_admin_group text, i_pw_due integer, i_connect_ip_range text, i_connect_dofw text, i_connect_time_start text, i_connect_time_end text, i_timeout_value integer, i_auth_wait_time integer, i_computer_name text, i_email text, i_phone text, i_use_otp boolean, i_description text, i_use_connect_ip boolean) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_profile_type              en_privilege_profile_type;
  v_admin_profile_type        en_privilege_profile_type;
  v_top_group_id              bigint;
  v_admin_group               text := i_admin_group;
  v_manager_group_id          bigint := i_manager_group_id;
  v_privilege_profile_id      bigint := i_privilege_profile_id;
BEGIN

  -- login_admin_id 의 권한 가져오기
  v_profile_type := sp_get_admin_privilege_type( i_login_admin_id );

  IF v_profile_type = 'TEMP_ADMIN' THEN
    IF i_login_admin_id <> 'cpp' THEN
      RAISE EXCEPTION 'You do not have permission.' USING HINT = 'DB-00022';
    END IF;
  ELSIF v_profile_type <> 'ROOT_ADMIN' THEN
    RAISE EXCEPTION 'You do not have permission.' USING HINT = 'DB-00022';
  END IF;


  -- admin_id 체크
  IF (EXISTS (SELECT 1 FROM tb_admin AS a WHERE a.admin_id = i_admin_id)) THEN
    RAISE EXCEPTION 'Registered ID already registered.(%)', i_admin_id USING HINT = 'DB-00015';
  END IF;

  -- 최상위 그룹 가져오기
  SELECT g.group_id INTO v_top_group_id FROM tb_group AS g WHERE g.group_type = 'TOP' LIMIT 1;

  -- 등록할 사용자의 권한을 가져온다.
  SELECT p.profile_type INTO v_admin_profile_type
  FROM tb_privilege_profile AS p
  WHERE p.privilege_profile_id = v_privilege_profile_id;

  --  부서관리자, 보안 관리자, 라이선스 관리자는 1.0.11 부터 생성, 수정을 지원하지 않는다.
  IF v_admin_profile_type IN ('DEPT_ADMIN', 'SECMGR_ADMIN', 'PRODUCT_ADMIN') THEN
    RAISE EXCEPTION 'DEPT_ADMIN and SECMGR_ADMIN are users that are no longer supported.' USING HINT = 'DB-00082';
  END IF;

  IF v_admin_profile_type = 'CUSTOM_ADMIN' THEN
    IF (SELECT EXISTS (SELECT 1 FROM tb_manager_group WHERE group_id = v_manager_group_id)) = FALSE THEN
      RAISE EXCEPTION 'Manager Group does not exist.' USING HINT = 'DB-00086';
    END IF;

    IF v_manager_group_id = 1 THEN
      RAISE EXCEPTION 'Custom admin cannot be assigned manager group id 1' USING HINT = 'DB-00087';
    END IF;

    v_admin_group := (SELECT node_group FROM tb_manager_group WHERE group_id = v_manager_group_id);
  END IF;

  -- 사용자정의관리자가 아니면 사용자그룹을 최상위로 셋팅한다.
  IF v_admin_profile_type = 'CUSTOM_ADMIN' THEN
    IF v_admin_group IS NULL OR v_admin_group = '' THEN
      RAISE EXCEPTION 'Management department code does not exist.' USING HINT = 'DB-00016';
    ELSIF v_top_group_id = ANY( SELECT t.group_id FROM UNNEST(STRING_TO_ARRAY(i_admin_group, ',')::bigint[]) AS t(group_id) ) THEN
      RAISE EXCEPTION 'This is the top-level department code.(%)', i_admin_group USING HINT = 'DB-00017';
    END IF;
  ELSE
    v_admin_group := v_top_group_id;
  END IF;

  -- 초기 사용자 ,서버관리자(최상위) ,정책관리자 , 일반관리자는 manager_group_id 를 1로 설정한다.
  IF v_admin_profile_type IN ('TEMP_ADMIN', 'ROOT_ADMIN', 'POLICY_ADMIN', 'MONITOR_ADMIN') THEN
    v_manager_group_id := 1;
  END IF;

    admin_id, name, password, pw_due, pw_modify_time
    , privilege_profile_id, product_auth, admin_group
    , connect_ip_range, connect_dofw, connect_time_start, connect_time_end
    , timeout_value, auth_wait_time, computer_name
    , email, phone, use_otp, description, modified_time, use_connect_ip, manager_group_id
  ) VALUES(
    i_admin_id, i_name, i_password, i_pw_due, now()
    , v_privilege_profile_id, null, v_admin_group
    , i_connect_ip_range, i_connect_dofw, i_connect_time_start, i_connect_time_end
    , i_timeout_value, i_auth_wait_time, i_computer_name
    , i_email, i_phone, i_use_otp, i_description, now(), i_use_connect_ip, v_manager_group_id
  );

END;
$$;


ALTER FUNCTION public.sp_add_admin(i_login_admin_id text, i_admin_id text, i_password text, i_name text, i_privilege_profile_id bigint, i_manager_group_id bigint, i_product_auth public.en_product_group_type[], i_admin_group text, i_pw_due integer, i_connect_ip_range text, i_connect_dofw text, i_connect_time_start text, i_connect_time_end text, i_timeout_value integer, i_auth_wait_time integer, i_computer_name text, i_email text, i_phone text, i_use_otp boolean, i_description text, i_use_connect_ip boolean) OWNER TO cppoltp;

