-- Name: sp_add_agent_policy(text, text, text, text, boolean, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_agent_policy(i_policy_name text, i_description text, i_online_policy_body text, i_offline_policy_body text, i_use_offline_policy boolean, i_hash text, i_admin_id text) RETURNS TABLE(policy_id bigint, policy_name text, product_feature_id public.en_product_feature_id_type, description text, online_policy_body text, offline_policy_body text, use_offline_policy text, hash text)
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_privilege_profile_auth boolean;
BEGIN

SELECT
    EXISTS (
        SELECT
            1
        FROM
            tb_admin ta
        INNER JOIN
            tb_privilege_profile tpp
        ON
            ta.privilege_profile_id = tpp.privilege_profile_id 
        WHERE
            tpp.profile_body LIKE '%"/policy/policy_SA_W"%'
        AND
            ta.admin_id = i_admin_id
    ) INTO v_privilege_profile_auth;

IF v_privilege_profile_auth = FALSE THEN
  RAISE EXCEPTION 'You do not have permission to write policy' USING HINT = 'DB-00084';
END IF;

RETURN QUERY
SELECT p.policy_id AS policy_id
      ,p.policy_name AS policy_name
      ,p.product_feature_id AS product_feature_id
      ,p.description AS description
      ,p.online_policy_body AS online_policy_body
      ,p.offline_policy_body AS offline_policy_body
      ,p.use_offline_policy AS use_offline_policy
      ,p.hash AS hash
FROM sp_add_policy(i_policy_name, 'AGENT_MGMT', i_description, i_online_policy_body,
                   i_offline_policy_body, i_use_offline_policy, i_hash, null, i_admin_id) p;

END;
$$;


