--
-- Name: sp_add_beginning_admin(text, text, text, text, text, text, integer, integer, integer, boolean, text, boolean, text[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_beginning_admin(i_admin_id text, i_password text, i_name text, i_email text, i_phone text, i_connect_ip_range text, i_timeout_value integer, i_auth_wait_time integer, i_pw_due integer, i_use_otp boolean, i_description text, i_use_connect_ip boolean, i_ems_admin_id text[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_privilege_profile_id      bigint;
  v_product_auth              en_product_group_type[];
  v_admin_group               text := NULL;
  v_connect_dofw              text := 'SUN,MON,TUE,WED,THU,FRI,SAT';
  v_connect_time_start        text := '0';
  v_connect_time_end          text := '24';
  v_computer_name             text := NULL;
BEGIN


  SELECT p.privilege_profile_id INTO v_privilege_profile_id FROM tb_privilege_profile AS p WHERE p.profile_type = 'ROOT_ADMIN' LIMIT 1;

  -- 첫 계정 생성.
  PERFORM sp_add_admin(
    i_ems_admin_id[1],
    i_admin_id,
    i_password,
    i_name,
    v_privilege_profile_id,
    1,
    v_product_auth,
    v_admin_group,
    i_pw_due,
    i_connect_ip_range,
    v_connect_dofw,
    v_connect_time_start,
    v_connect_time_end,
    i_timeout_value,
    i_auth_wait_time,
    v_computer_name,
    i_email,
    i_phone,
    i_use_otp,
    i_description,
    i_use_connect_ip
  );

  -- 임시아이디 삭제
  PERFORM sp_remove_admin(i_ems_admin_id[1], i_ems_admin_id);

  -- 환경값 셋팅
  ON CONFLICT(config_group, key) DO UPDATE SET value = EXCLUDED.value, modified_time = EXCLUDED.modified_time;

END;
$$;


ALTER FUNCTION public.sp_add_beginning_admin(i_admin_id text, i_password text, i_name text, i_email text, i_phone text, i_connect_ip_range text, i_timeout_value integer, i_auth_wait_time integer, i_pw_due integer, i_use_otp boolean, i_description text, i_use_connect_ip boolean, i_ems_admin_id text[]) OWNER TO cppoltp;

