--
-- Name: sp_add_child_policy_task(bigint, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_child_policy_task(i_policy_id bigint, i_admin_id text, i_logical_target text, i_target_filter text, i_schedule_detail text, i_internal_payload text) RETURNS TABLE(job_id bigint, task_id bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_logical_payload text;
  v_internal_payload text;
  v_job_id bigint[];
  v_child_policy_id bigint;
  v_child_job_id bigint;
  v_schedule boolean;

BEGIN

  FOR v_child_policy_id IN

    SELECT policy_id
    FROM tb_policy
    WHERE ppolicy_id = i_policy_id

  LOOP

    IF i_schedule_detail IS NULL THEN

      v_schedule := false;

    ELSE

      v_schedule := true;

    END IF;

    SELECT row_to_json(p)::text
    INTO v_logical_payload
    FROM (SELECT product_feature_id
          FROM tb_policy
          WHERE policy_id = v_child_policy_id) p;

    SELECT jsonb_set(i_internal_payload::jsonb, '{"policy_id"}', v_child_policy_id::text::jsonb)::text
    INTO v_internal_payload;

                is_schedule, schedule_detail, admin_id, logical_target, onoff, visible, create_time, modified_time, target_filter)
        VALUES (v_schedule, i_schedule_detail, i_admin_id, i_logical_target, v_schedule, false, now(), now(), i_target_filter)
    RETURNING tb_job.job_id INTO v_child_job_id;

                job_id, task_type, logical_payload, internal_payload, task_order, modified_time, create_time)
    SELECT v_child_job_id
          ,'APPLY_POLICY'
          ,v_logical_payload
          ,v_internal_payload
          ,1
          ,now()
          ,now();

    SELECT array_append(v_job_id, v_child_job_id)
    INTO v_job_id;

  END LOOP;

  RETURN QUERY
  SELECT t.job_id
        ,t.task_id
  FROM tb_task t
  WHERE t.job_id IN (SELECT * FROM unnest(v_job_id));

END;
$$;


ALTER FUNCTION public.sp_add_child_policy_task(i_policy_id bigint, i_admin_id text, i_logical_target text, i_target_filter text, i_schedule_detail text, i_internal_payload text) OWNER TO cppoltp;

--
-- Name: sp_add_config_server(text, text, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_config_server(i_name text, i_ip text, i_server_key text, i_current_version text) RETURNS TABLE(server_id bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  -- 서버 IP 체크
  IF (EXISTS (SELECT 1 FROM tb_server AS s WHERE s.ip = i_ip)) THEN
    RAISE EXCEPTION 'The server IP already exists.' USING HINT = 'DB-00021';
  END IF;

  RETURN QUERY
      name
      , ip
      , server_key
      , current_version
      , server_status
      , modified_time
    ) VALUES(
      i_name
      , i_ip
      , i_server_key
      , i_current_version
      , 'ROLE_PENDING'
      , now()
    )
    RETURNING tb_server.server_id;

END;
$$;


