--
-- Name: sp_add_correlation_task_target(bigint, bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_correlation_task_target(i_job_id bigint, i_correlation_rule_id bigint, i_target_list bigint[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_payload_json_param TEXT;
  v_logical_target TEXT;
 
  v_product_id en_product_id_type;
  v_task_id int;
  
BEGIN
  -- CWPP-6633 : V3 수동 업데이트는 대응 화면에서 제품 이름을 표기해야 하므로 각 플랫폼마다 Task 생성  
  IF (SELECT EXISTS (SELECT 1 FROM tb_correlation_task WHERE correlation_rule_id = i_correlation_rule_id AND task_type = 'UPDATE_PRODUCT')) THEN  
    FOREACH v_product_id IN ARRAY '{V3NET_LU, V3NET_9.0, AMC_CLIENT}'::en_product_id_type[] LOOP 
        job_id
        , task_type
        , logical_payload
        , task_order
        , create_time
        , modified_time
        , console_context_payload
      )
      SELECT
        i_job_id
        , task_type
        , payload_params
        , task_order
        , now()
        , now()
        , '{"deploy_file_name" : "' || v_product_id || '"}'
      FROM tb_correlation_task
      WHERE correlation_rule_id = i_correlation_rule_id
      AND task_type = 'UPDATE_PRODUCT'
      RETURNING task_id INTO v_task_id;
      
      SELECT
        t.task_id
        , sp_get_correlation_task_payload(cr.payload_params, cr.task_type)
        , target
        , now()
      FROM tb_task_type tt
      JOIN tb_correlation_task cr ON tt.task_type = cr.task_type
      JOIN tb_task t ON t.task_type = cr.task_type AND t.job_id = i_job_id AND cr.task_order = t.task_order
      CROSS JOIN (
        SELECT DISTINCT node_id AS target FROM tb_product_info WHERE node_id = ANY(i_target_list) AND product_id = v_product_id
      ) target
      WHERE cr.correlation_rule_id = i_correlation_rule_id AND t.task_id = v_task_id;
    END LOOP;

      job_id
      , task_type
      , logical_payload
      , task_order
      , create_time
      , modified_time)
    SELECT
      i_job_id
      , task_type
      , payload_params
      , task_order
      , now()
      , now()
    FROM tb_correlation_task
    WHERE correlation_rule_id = i_correlation_rule_id
    AND task_type != 'UPDATE_PRODUCT';

    SELECT
      t.task_id
      , sp_get_correlation_task_payload(cr.payload_params, cr.task_type)
      , target
      , now()
    FROM tb_task_type tt
    JOIN tb_correlation_task cr ON tt.task_type = cr.task_type
    JOIN tb_task t ON t.task_type = cr.task_type AND t.job_id = i_job_id AND cr.task_order = t.task_order
    CROSS JOIN (SELECT DISTINCT target FROM unnest(i_target_list) target) target
    WHERE cr.correlation_rule_id = i_correlation_rule_id
    AND tt.task_type != 'UPDATE_PRODUCT'

    /* EMS5-2602 : 대응 명령이 AGENT가 아닐경우 실제 target들의 설치된 제품과 매칭하여 유효한 대응 명령어만 취급하여 target을 생성한다.
     * shkang, 2018. 7. 26
     */
    AND true = (
      CASE
        WHEN tt.task_target_product_id <> 'AGENT' THEN
          (
            SELECT
              (CASE WHEN EXISTS(SELECT pi.node_id, p.product_group
                                FROM tb_product_info pi JOIN tb_product p ON pi.product_id = p.product_id
                                WHERE pi.node_id = target AND p.product_group = tt.task_target_product_id::en_product_group_type)
                        THEN true ELSE false END)
          )
        WHEN tt.task_target_product_id = 'AGENT' THEN true
      ELSE
        false
      END
    )
  ;  
  
  ELSE 
    -- V3 수동 업데이트를 제외한 나머지 Task 생성
    -- EMS5-2563 : logical_payload 에 무조건 공백을 넣는 것에서 tb_correlation_task.payload_params 값을 셋팅함으로 변경
      job_id
      , task_type
      , logical_payload
      , task_order
      , create_time
      , modified_time)
    SELECT
      i_job_id
      , task_type
      , payload_params
      , task_order
      , now()
      , now()
    FROM tb_correlation_task
    WHERE correlation_rule_id = i_correlation_rule_id;

    SELECT
      t.task_id
      , sp_get_correlation_task_payload(cr.payload_params, cr.task_type)
      , target
      , now()
    FROM tb_task_type tt
    JOIN tb_correlation_task cr ON tt.task_type = cr.task_type
    JOIN tb_task t ON t.task_type = cr.task_type AND t.job_id = i_job_id AND cr.task_order = t.task_order
    CROSS JOIN (SELECT DISTINCT target FROM unnest(i_target_list) target) target
    WHERE cr.correlation_rule_id = i_correlation_rule_id

    /* EMS5-2602 : 대응 명령이 AGENT가 아닐경우 실제 target들의 설치된 제품과 매칭하여 유효한 대응 명령어만 취급하여 target을 생성한다.
     * shkang, 2018. 7. 26
     */
    AND true = (
      CASE
        WHEN tt.task_target_product_id <> 'AGENT' THEN
          (
            SELECT
              (CASE WHEN EXISTS(SELECT pi.node_id, p.product_group
                                FROM tb_product_info pi JOIN tb_product p ON pi.product_id = p.product_id
                                WHERE pi.node_id = target AND p.product_group = tt.task_target_product_id::en_product_group_type)
                        THEN true ELSE false END)
          )
        WHEN tt.task_target_product_id = 'AGENT' THEN true
      ELSE
        false
      END
    )
  ;  
  END IF;
 
END;
$$;


ALTER FUNCTION public.sp_add_correlation_task_target(i_job_id bigint, i_correlation_rule_id bigint, i_target_list bigint[]) OWNER TO cppoltp;

--
-- Name: sp_add_custom_privilege_profile(text, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_custom_privilege_profile(i_profile_name text, i_description text, i_profile_body text) RETURNS TABLE(privilege_profile_id bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  IF (EXISTS (SELECT 1 FROM tb_privilege_profile AS p WHERE p.profile_name = i_profile_name)) THEN
    RAISE EXCEPTION 'The name is already registered.(%)', i_profile_name USING HINT = 'DB-00037';
  END IF;

  RETURN QUERY
      profile_type
      , profile_name
      , description
      , profile_body
      , modified_time
    ) VALUES(
      'CUSTOM_ADMIN'
      , i_profile_name
      , i_description
      , i_profile_body
      , now()
    )
    RETURNING tb_privilege_profile.privilege_profile_id;

END;
$$;


