--
-- Name: sp_add_enum_value(text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_enum_value(i_typename text, i_value text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN

-- development helper proc
IF (NOT EXISTS (SELECT 1 FROM pg_enum WHERE enumtypid = i_typename::regtype::OID AND enumlabel = i_value)) THEN
  SELECT i_typename::regtype::oid, i_value, ( SELECT coalesce(MAX(enumsortorder) + 1, 1) FROM pg_enum WHERE enumtypid = i_typename::regtype );
END IF;

END;
$$;


ALTER FUNCTION public.sp_add_enum_value(i_typename text, i_value text) OWNER TO cppoltp;

--
-- Name: sp_add_general_correlation_send_mail(text, bigint, bigint, bigint[], public.en_correlation_condition_id_type[], text[], text, text, text, text, text, bigint, boolean); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_general_correlation_send_mail(i_login_admin_id text, i_job_id bigint, i_correlation_rule_id bigint, i_target_list bigint[], i_macro_type_list public.en_correlation_condition_id_type[], i_macro_value_list text[], i_mail_body text, i_correlation_name text, i_correlation_condition text, i_mail_image text, i_custom_email text, i_custom bigint, i_send_mail_to_target boolean) RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_payload_format TEXT;
  v_task_id BIGINT;

BEGIN

  SELECT
    tt.payload_format INTO v_payload_format
  FROM
    tb_task_type tt
  WHERE
    tt.task_type = 'SEND_MAIL'
  ;

  VALUES(i_job_id, 'SEND_MAIL', '', 1, now(), now())
  RETURNING tb_task.task_id INTO v_task_id;


  task_id
  , payload
  , target_id
  , modified_time
)

  SELECT
    v_task_id AS task_id
    , concat('[', string_agg(format(v_payload_format, t.email, i_correlation_name, sp_base64_encode(t.mail_body), i_mail_image), ','), ']') AS payload
    , 0::bigint AS target_id
    , now()::timestamp AS modified_time
  FROM (

    /* custom email */
    SELECT
      e.email AS email
      , c.mail_contents AS mail_body
    FROM
      UNNEST(CONCAT('{', i_custom_email, '}')::TEXT[]) e(email)
      CROSS JOIN
        sp_make_email_contents(
          i_login_admin_id
          , i_target_list
          , i_macro_type_list
          , i_macro_value_list
          , i_mail_body
          , i_correlation_name
          , i_correlation_condition
          , CONCAT('{', i_custom_email, '}')::TEXT[] -- i_send_mail_list text[]
          , TRUE -- i_is_admin boolean
      ) AS c
    WHERE
      i_custom > 0


    /* 담당 관리자/발생 에이전트 체크시 */

    /* root admin email */
    UNION ALL
    SELECT
      org.email
      , org.mail_body
    FROM(
      WITH root_admin_email AS(
        SELECT
         a.email AS email
        FROM
          tb_admin a
          JOIN tb_privilege_profile pp ON a.privilege_profile_id = pp.privilege_profile_id
        WHERE
          pp.profile_type = 'ROOT_ADMIN'::en_privilege_profile_type
      )
      SELECT
        e.email AS email
        , c.mail_contents AS mail_body
      FROM
        root_admin_email e
        CROSS JOIN
          sp_make_email_contents(
            i_login_admin_id
            , i_target_list
            , i_macro_type_list
            , i_macro_value_list
            , i_mail_body
            , i_correlation_name
            , i_correlation_condition
            , (SELECT ARRAY_AGG(email) FROM root_admin_email) -- i_send_mail_list text[]
            , TRUE -- i_is_admin boolean
        ) AS c
    ) org
    WHERE
      i_send_mail_to_target IS TRUE


    /* 부서별, 제품별, 특수관리자 이메일 전송 */
    UNION ALL
    SELECT
      org.email
      , c.mail_contents
    FROM(
      WITH target_list AS(
        SELECT
          t.node_id::bigint AS target_id
          , t.correlation_condition_id::en_correlation_condition_id_type as macro
          , t.value::text AS value
          , con.product_group
          , n.group_id
        FROM
          UNNEST(
            i_target_list
            , i_macro_type_list
            , i_macro_value_list
          ) t(node_id, correlation_condition_id, value)
        JOIN tb_correlation_condition con on t.correlation_condition_id::en_correlation_condition_id_type = con.correlation_condition_id
        JOIN tb_node n on t.node_id::bigint = n.node_id
        WHERE
          i_send_mail_to_target IS TRUE
      )

      , dept_admin_list AS(
        SELECT
          org.admin_id
          , org.email
          , ARRAY_AGG(org.target_id) AS target_id
          , ARRAY_AGG(org.macro) AS macro
          , ARRAY_AGG(org.value) AS value
        FROM(
          WITH recursive dept AS(
            SELECT
              a.admin_id
              , unnest(string_to_array(a.admin_group, ','))::bigint as group_id
            FROM
              tb_admin a
              JOIN tb_privilege_profile pp ON a.privilege_profile_id = pp.privilege_profile_id
            WHERE
              pp.profile_type = 'DEPT_ADMIN'::en_privilege_profile_type

            UNION ALL
            SELECT
              d.admin_id
              , g.group_id
            FROM
              tb_group g
              JOIN dept d ON g.pgroup_id = d.group_id
          )
          SELECT DISTINCT
            d.admin_id
            , a.email
            , t.target_id
            , t.macro
            , t.value
          FROM
            dept d
            JOIN tb_admin a ON d.admin_id = a.admin_id
            JOIN target_list t ON d.group_id = t.group_id
        ) org
        GROUP BY
          org.admin_id
          , org.email
      )

      , product_admin_list as(
        SELECT
          product_admin.admin_id
          , product_admin.email
          , array_agg(t.target_id) AS target_id
          , array_agg(t.macro) AS macro
          , array_agg(t.value) AS value
        FROM (
            SELECT
              a.admin_id
              , a.email
              , unnest(string_to_array(a.product_auth, ','))::en_product_group_type as product_group
            FROM
              tb_admin a
              join tb_privilege_profile pp ON a.privilege_profile_id = pp.privilege_profile_id
            WHERE
              pp.profile_type = 'PRODUCT_ADMIN'::en_privilege_profile_type
        )
          product_admin
          JOIN target_list t ON product_admin.product_group = t.product_group
        GROUP BY
          product_admin.admin_id
          , product_admin.email
      )

    , special_admin_data as(

      SELECT
        sp.admin_id
        , sp.email
        , unnest(string_to_array(sp.admin_group, ','))::bigint as group_id
        , sp.product_group
      FROM (
        SELECT
            a.admin_id
            , a.email
            , unnest(string_to_array(a.product_auth, ','))::en_product_group_type as product_group
            , a.admin_group

          FROM
            tb_admin a
            JOIN tb_privilege_profile pp ON a.privilege_profile_id = pp.privilege_profile_id
          WHERE
            pp.profile_type = ANY(
            array[
              'SECMGR_ADMIN'::en_privilege_profile_type
            ]
            )
      ) sp

      /* 공통 연계규칙도 대상이기 때문에 주석처리
      WHERE
        sp.product_group <> 'EMS'
      */


    )
    ,  special_admin_mgmt_group AS (
      SELECT
        a.admin_id
        , a.email
        , array_agg(a.target_id) AS target_id
        , array_agg(a.macro) AS macro
        , array_agg(a.value) AS value
      FROM(
        SELECT DISTINCT
          a.admin_id
          , a.email
          , (t.target_id) AS target_id
            , (t.macro) AS macro
            , (t.value) AS value
        FROM(
          WITH RECURSIVE mgmt_group AS(
            SELECT
              a.admin_id
              , a.group_id
            FROM
              special_admin_data a
            UNION ALL
            SELECT
              m.admin_id
              , g.group_id
            FROM
              tb_group g
              JOIN mgmt_group m ON g.pgroup_id = m.group_id
          )
          SELECT
            m.admin_id
            , m.group_id
            , d.email
            , d.product_group
          FROM
            mgmt_group m
            JOIN special_admin_data d on m.admin_id = d.admin_id
        ) a
        JOIN target_list t ON a.product_group = t.product_group AND a.group_id = t.group_id
      ) a
      GROUP BY
        a.admin_id
        , a.email

    )
      SELECT da.admin_id, da.email, da.target_id, da.macro, da.value FROM dept_admin_list AS da
      UNION ALL
      SELECT pa.admin_id, pa.email, pa.target_id, pa.macro, pa.value FROM product_admin_list AS pa
      UNION ALL
      SELECT sa.admin_id, sa.email, sa.target_id, sa.macro, sa.value FROM special_admin_mgmt_group AS sa
    ) org
    CROSS JOIN
      sp_make_email_contents(
        i_login_admin_id
        , org.target_id::bigint[]
        , org.macro::en_correlation_condition_id_type[]
        , org.value::text[]
        , i_mail_body
        , i_correlation_name
        , i_correlation_condition
        , array[org.email] -- i_send_mail_list text[]
        , TRUE -- i_is_admin boolean
    ) AS c


    /* 발생에이전트 개별 전송 */
    UNION ALL
    SELECT
      org.email
      , c.mail_contents
    FROM(
      SELECT
        u.email
        , n.node_id
        , t.correlation_condition_id AS macro_key
        , t.value AS macro_value
      FROM
        UNNEST(
          i_target_list
          , i_macro_type_list
          , i_macro_value_list
        ) t(node_id, correlation_condition_id, value)
        JOIN tb_node n ON t.node_id = n.node_id
        JOIN tb_user u ON n.node_id = u.node_id
      WHERE
        i_send_mail_to_target IS TRUE
    ) org
    CROSS JOIN
      sp_make_email_contents(
        i_login_admin_id
        , ARRAY[org.node_id]
        , ARRAY[org.macro_key]
        , ARRAY[org.macro_value]
        , i_mail_body
        , i_correlation_name
        , i_correlation_condition
        , ARRAY[org.email] -- i_send_mail_list text[]
        , FALSE -- i_is_admin boolean
    ) AS c


  ) t;


END;
$$;


ALTER FUNCTION public.sp_add_general_correlation_send_mail(i_login_admin_id text, i_job_id bigint, i_correlation_rule_id bigint, i_target_list bigint[], i_macro_type_list public.en_correlation_condition_id_type[], i_macro_value_list text[], i_mail_body text, i_correlation_name text, i_correlation_condition text, i_mail_image text, i_custom_email text, i_custom bigint, i_send_mail_to_target boolean) OWNER TO cppoltp;

--
-- Name: sp_add_group(text, bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_group(i_name text, i_pgroup_id bigint) RETURNS TABLE(group_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_duplicate_count bigint;
  v_group_type en_group_type;
  v_pgroup_type en_group_type;
  v_max_depth bigint;
  v_depth bigint;
  v_space boolean;
  v_group_order bigint;
  v_new_group_position text;
  v_group_id bigint;

BEGIN

SELECT count(dgn.group_id)
      ,dgn.group_type
INTO v_duplicate_count
    ,v_group_type
FROM sp_get_duplicate_group_name(i_pgroup_id, i_name) dgn
GROUP BY dgn.group_type;

SELECT COALESCE(REPLACE(i_name, ' ', ''), '') = ''
INTO v_space;

SELECT g.group_type
INTO v_pgroup_type
FROM tb_group g
WHERE g.group_id = i_pgroup_id;

SELECT gl.lvl + 2::bigint
INTO v_depth
FROM sp_get_group_list(1, true, 'ASC', null) gl
WHERE gl.group_id = i_pgroup_id;

SELECT value
INTO v_max_depth
FROM tb_config
WHERE config_group = 'GENERAL'
  AND key = 'group_depth';

IF v_pgroup_type IS NULL THEN

  RAISE EXCEPTION 'group does not exist.' USING HINT = 'DB-00011';

ELSIF v_group_type = 'TOP' THEN

  RAISE EXCEPTION 'group name already in use for top group.' USING HINT = 'DB-00007';

ELSIF v_duplicate_count > 0 THEN

  RAISE EXCEPTION 'group name already exist.' USING HINT = 'DB-00005';

ELSIF v_space THEN

  RAISE EXCEPTION 'group name cannot include space.' USING HINT = 'DB-00009';

ELSIF v_pgroup_type NOT IN ('PHYSICAL','GENERAL') THEN

  RAISE EXCEPTION 'group type cannot have child group.' USING HINT = 'DB-00006';

ELSIF v_max_depth < v_depth THEN

  RAISE EXCEPTION 'max depth is (%).', v_max_depth USING HINT = 'DB-00001';

ELSE

  SELECT value
  INTO v_new_group_position
  FROM tb_config
  WHERE config_group = 'GROUP_ORDER'
    AND key = 'new_group_position';

  IF v_new_group_position = 'FRONT' THEN
    v_group_order = -1;
  ELSE
    v_group_order = -2;
  END IF;

  -- 그룹 INSERT
              name, pgroup_id, group_type, is_removed, group_order)
      VALUES (i_name, i_pgroup_id, 'GENERAL', false, v_group_order)
  RETURNING tb_group.group_id INTO v_group_id;

  -- 상위 지정 보조 업데이트 설정 따라가기
  IF EXISTS (SELECT 1 FROM tb_file_update_server AS f WHERE f.target_type = 'GROUP' AND f.target_id = i_pgroup_id) THEN
      SELECT v_group_id, 'GROUP', f.server_id, specified
      FROM tb_file_update_server AS f
      WHERE f.target_id = i_pgroup_id
    ON CONFLICT(target_id, target_type, server_id) DO NOTHING;
  END IF;

  -- 그룹 정렬 flag ON
  UPDATE tb_config
  SET value = 'ON'
  WHERE config_group = 'GROUP_ORDER'
    AND key = 'update_flag';

  -- 그룹정책 INSERT
              group_id, product_feature_id, policy_id, modified_time)
  SELECT v_group_id
        ,p.product_feature_id
        ,p.policy_id
        ,now()
  FROM tb_policy p
  WHERE p.policy_type = 'DEFAULT';


  RETURN QUERY SELECT v_group_id::text;

END IF;

END;
$$;


ALTER FUNCTION public.sp_add_group(i_name text, i_pgroup_id bigint) OWNER TO cppoltp;

--
-- Name: sp_add_group_node(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_group_node(i_group_id bigint, i_node_id bigint[]) RETURNS TABLE(group_id text, product_feature_id text, policy_id text, node_ids text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_apply_policy_on_group_change text;

BEGIN
  UPDATE tb_node
  SET group_id = i_group_id
  WHERE tb_node.node_id = ANY(SELECT UNNEST(i_node_id));

  PERFORM sp_change_file_update_server(i_node_id, i_group_id);

  -- (CWPP-6425) 설정 > 그룹 설정 > 기본 그룹 설정 > 그룹 정책 설정 에 따른 조건 처리
  SELECT value INTO v_apply_policy_on_group_change
  FROM sp_get_config_group('GROUPING'::en_config_group, 'apply_policy_on_group_change');

  RETURN QUERY
    SELECT
      ARRAY_AGG(gp.group_id)::TEXT AS group_id
      , gp.product_feature_id::TEXT AS product_feature_id
      , gp.policy_id::TEXT AS policy_id
      , ARRAY_AGG(node_policy.node_id)::TEXT AS node_ids
    FROM
      tb_group_policy gp
      INNER JOIN (
        SELECT tb_node_policy.node_id, tb_node_policy.product_feature_id, tb_node_policy.policy_id
        FROM tb_node_policy
        WHERE
          node_id = ANY(SELECT UNNEST(i_node_id))
          AND
            CASE WHEN v_apply_policy_on_group_change = 'all_but_agent_policy'	-- '기존 개별 정책 유지' 인 경우
                THEN keep_agent_policy IS FALSE   -- 개별 정책을 사용하지 않는 건만 추출
                ELSE TRUE END
      ) node_policy ON node_policy.product_feature_id = gp.product_feature_id
    WHERE
      gp.group_id = i_group_id
      -- (기존 : CWPP-4160) 정책 적용 상태가 존재하는 건만 추출
      -- (변경 : CWPP-7282) 라이선스 존재 유무로 조건 변경
      AND EXISTS (
        SELECT 1
        FROM (
          SELECT DISTINCT tb_product_feature_map.product_feature_id
          FROM tb_product_feature_map
          WHERE
            EXISTS (SELECT 1 FROM tb_multi_license
                  WHERE (CASE WHEN tb_multi_license.product_id = 'EMS' THEN 'AGENT' ELSE tb_multi_license.product_id END) = tb_product_feature_map.product_id)
            AND tb_product_feature_map.product_feature_id != 'V3NET_LU_UPDATE'
        ) AS product_feature_id_list
        WHERE
          product_feature_id_list.product_feature_id = gp.product_feature_id
      )
    GROUP BY
        gp.product_feature_id
        , gp.policy_id
  ;

END;
$$;


