--
-- Name: sp_add_license(text, public.en_product_id_type, public.en_license_sub_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_license(i_license_no text, i_product_id public.en_product_id_type, i_sub_type public.en_license_sub_type) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_expire_date               timestamp := NULL;
  v_virtual_default_group_id BIGINT;
  v_node_id BIGINT[];

BEGIN

  -- 제품 구분 체크 (중복 등록 불가 - CWPP-2477)
  IF (EXISTS (SELECT 1 FROM tb_product_license pl INNER JOIN tb_product p ON pl.product_id = p.product_id WHERE p.product_id = i_product_id)) THEN
    RAISE EXCEPTION 'The Product is already registered with the license.(%)', i_product_id USING HINT = 'DB-00062';
  END IF;

  IF i_product_id = 'EMS' THEN
    v_expire_date := now() + Interval '7 days';
  END IF;

    VALUES( i_license_no, i_product_id, TRUE, now(), i_sub_type, v_expire_date );

END;
$$;


ALTER FUNCTION public.sp_add_license(i_license_no text, i_product_id public.en_product_id_type, i_sub_type public.en_license_sub_type) OWNER TO cppoltp;

--
-- Name: sp_add_multi_admin(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_multi_admin() RETURNS TABLE(admin_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  -- 등록
    admin_id, name
    , password, pw_due, pw_modify_time
    , privilege_profile_id, product_auth, admin_group
    , connect_ip_range, connect_dofw
    , connect_time_start, connect_time_end
    , timeout_value, auth_wait_time
    , computer_name, email, phone
    , use_otp, description
    , modified_time
  )
  SELECT t.admin_id, t.name
    , t.admin_pwd, t.pw_due, now()
    , t.privilege_profile_id, null, t.admin_group
    , t.connect_ip_range, t.connect_dofw
    , t.connect_time_start, t.connect_time_end
    , t.timeout_value, t.auth_wait_time
    , t.computer_name, t.email, t.phone
    , t.use_otp, t.description
    , now()
  FROM tb_temp_admin_temp AS t
  WHERE LENGTH(COALESCE(t.current_pwd,'')) = 0;

  -- 수정시에 패스워드 수정
    SELECT t.admin_id, t.current_pwd, now()
    FROM tb_temp_admin_temp AS t
    WHERE LENGTH(COALESCE(t.current_pwd,'')) > 0 AND LENGTH(COALESCE(t.admin_pwd,'')) > 0;

  -- 수정
  UPDATE tb_admin
    SET name = t.name                                 /* 관리자 이름 */
      , password = CASE WHEN LENGTH(COALESCE(t.admin_pwd,'')) = 0 THEN tb_admin.password ELSE t.admin_pwd END
      , pw_modify_time = CASE WHEN LENGTH(COALESCE(t.admin_pwd,'')) = 0 THEN tb_admin.pw_modify_time ELSE now() END
      , pw_due = t.pw_due                             /* 패스워드 만료 기간 */
      , admin_group = t.admin_group                   /* 사용자 그룹 */
      , connect_ip_range = t.connect_ip_range         /* 접속 가능 IP 주소 범위 */
      , connect_dofw = t.connect_dofw                 /* 접속 가능 요일 */
      , connect_time_start = t.connect_time_start     /* 접속 가능 시작 시간 */
      , connect_time_end = t.connect_time_end         /* 접속 가능 종료 시간 */
      , timeout_value = t.timeout_value               /* 접속 Timeout 시간 */
      , auth_wait_time = t.auth_wait_time             /* 로그인 인증 보류 시간 */
      , computer_name = t.computer_name               /* 관리자 컴퓨터 이름 */
      , email = t.email                               /* 관리자 Email */
      , phone = t.phone                               /* 관리자 핸드폰 */
      , use_otp = t.use_otp                           /* OTP 사용여부 */
      , description = t.description                   /* 설명 */
      , modified_time = now()                         /* 데이터 갱신 최종 시간 */
  FROM (
    SELECT t.admin_id, t.name, t.admin_pwd, t.pw_due, t.admin_group
        , t.connect_ip_range, t.connect_dofw, t.connect_time_start, t.connect_time_end
        , t.timeout_value, t.auth_wait_time, t.computer_name
        , t.email, t.phone, t.use_otp, t.description
    FROM tb_temp_admin_temp AS t
    WHERE LENGTH(COALESCE(t.current_pwd,'')) > 0 ) AS t
  WHERE tb_admin.admin_id = t.admin_id;

  -- 수정시에 패스워드 수정
    SELECT t.admin_id, t.current_pwd, now()
    FROM tb_temp_admin_temp AS t
    WHERE LENGTH(COALESCE(t.current_pwd,'')) > 0 AND LENGTH(COALESCE(t.admin_pwd,'')) > 0;


  RETURN QUERY
    SELECT t.admin_id FROM tb_temp_admin_temp AS t;

END;
$$;


