--
-- Name: sp_add_policy(text, public.en_product_feature_id_type, text, text, text, boolean, text, bigint, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_policy(i_policy_name text, i_product_feature_id public.en_product_feature_id_type, i_description text, i_online_policy_body text, i_offline_policy_body text, i_use_offline_policy boolean, i_hash text, i_ppolicy_id bigint, i_admin_id text) RETURNS TABLE(policy_id bigint, policy_name text, product_feature_id public.en_product_feature_id_type, description text, online_policy_body text, offline_policy_body text, use_offline_policy text, hash text)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_policy_id bigint;
  v_policy_name text;
  v_manager_group_id bigint;

BEGIN

  IF (SELECT count(*) FROM tb_policy WHERE name = i_policy_name) > 0 THEN

    SELECT i_policy_name || to_char(now(), '.YYYYMMDD.HH24MISS') INTO v_policy_name;

  ELSE

    SELECT i_policy_name INTO v_policy_name;

  END IF;

  SELECT manager_group_id INTO v_manager_group_id FROM tb_admin WHERE admin_id = i_admin_id AND manager_group_id != 1;

  --정책 추가
              name, product_feature_id, description, online_policy_body,
              offline_policy_body, use_offline_policy, policy_type, modified_time, ppolicy_id, is_updated, manager_group_id)
      VALUES (v_policy_name, i_product_feature_id, i_description, i_online_policy_body,
              i_offline_policy_body, i_use_offline_policy, 'GENERAL', now(), i_ppolicy_id, true, v_manager_group_id)
      RETURNING tb_policy.policy_id INTO v_policy_id;

  UPDATE tb_policy p
  SET hash = concat(i_hash,v_policy_id::TEXT)
  WHERE p.policy_id = v_policy_id;

  RETURN QUERY
  SELECT p.policy_id AS policy_id
        ,p.name AS policy_name
        ,p.product_feature_id AS product_feature_id
        ,p.description AS description
        ,p.online_policy_body AS online_policy_body
        ,COALESCE(p.offline_policy_body, '') AS offline_policy_body
        ,COALESCE(p.use_offline_policy, false)::integer::text AS use_offline_policy
        ,COALESCE(p.hash, '') AS hash
  FROM tb_policy p
  WHERE p.policy_id = v_policy_id;

END;
$$;


