--
-- Name: sp_add_policy_task(bigint, bigint[], text, text, boolean); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_policy_task(i_policy_id bigint, i_target_id bigint[], i_type text, i_admin_id text, i_keep_policy boolean) RETURNS TABLE(job_id bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_logical_target text;
  v_logical_payload text;
  v_internal_payload text;
  v_target_filter text;
  v_job_id bigint;
  v_type text := CASE WHEN i_type = 'GROUP_ALL' THEN 'GROUP'
                      WHEN i_type = 'GROUP_ONLY' THEN 'GROUP'  
                      WHEN i_type = 'NODE_REMOVED' THEN 'NODE' 
                      ELSE i_type END;

BEGIN

  IF (v_type = 'NODE') THEN
    SELECT array_to_json(array_agg(row_to_json(p)))::text
    INTO v_logical_target
    FROM (SELECT v_type AS type, i_target_id AS target, (SELECT array_to_json(array_agg(ip)) FROM tb_node WHERE node_id = ANY(i_target_id)) AS target_name) p;
  ELSEIF (v_type = 'GROUP' OR v_type = 'GROUP_ALL' OR v_type = 'GROUP_ONLY') THEN
    SELECT array_to_json(array_agg(row_to_json(p)))::text
    INTO v_logical_target
    FROM (SELECT v_type AS type, i_target_id AS target, (SELECT array_to_json(array_agg(name)) FROM tb_group WHERE group_id = ANY(i_target_id)) as target_name) p;
  ELSE
    SELECT array_to_json(array_agg(row_to_json(p)))::text
    INTO v_logical_target
    FROM (SELECT v_type AS type, i_target_id AS target) p;
  END IF;
  
  SELECT row_to_json(p)::text
  INTO v_logical_payload
  FROM (SELECT product_feature_id
        FROM tb_policy
        WHERE policy_id = i_policy_id) p;

  SELECT row_to_json(p)::text
  INTO v_internal_payload
  FROM (SELECT i_policy_id AS policy_id
              ,is_updated
              ,CASE WHEN i_type = 'GROUP_ALL' THEN true ELSE false END AS is_all
              ,CASE WHEN i_type = 'NODE' THEN i_keep_policy ELSE false END AS is_keep_agent_policy
        FROM tb_policy
        WHERE policy_id = i_policy_id) p;

  SELECT t.target_filter
  INTO v_target_filter
  FROM sp_get_policy_target_filter(i_policy_id) t;

  --정책 적용 배포t_poli
              is_schedule, admin_id, logical_target, onoff, visible, create_time, modified_time, target_filter)
      VALUES (false, i_admin_id, v_logical_target, false, true, now(), now(), v_target_filter)
  RETURNING tb_job.job_id INTO v_job_id;

              job_id, task_type, logical_payload, internal_payload, task_order, modified_time, create_time)
  SELECT v_job_id
        ,'APPLY_POLICY'
        ,v_logical_payload
        ,v_internal_payload
        ,1
        ,now()
        ,now();

  RETURN QUERY
  SELECT j.job_id
  FROM tb_job j
  WHERE j.job_id = v_job_id
  UNION ALL
  SELECT cj.job_id
  FROM sp_add_child_policy_task(i_policy_id, i_admin_id, v_logical_target, v_target_filter, NULL, v_internal_payload) cj;

END;
$$;


ALTER FUNCTION public.sp_add_policy_task(i_policy_id bigint, i_target_id bigint[], i_type text, i_admin_id text, i_keep_policy boolean) OWNER TO cppoltp;

--
-- Name: sp_add_product_server(public.en_product_group_type, text, bigint, boolean, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_product_server(i_product_group public.en_product_group_type, i_ip text, i_port bigint, i_is_used boolean, i_admin_id text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE

BEGIN

  IF (NOT EXISTS (SELECT 1 FROM tb_server s WHERE (s.ip = i_ip OR public_ip = i_ip))) THEN
      product_group
      , ip
      , port
      , is_used
      , admin_id
      , modified_time
    )
    VALUES(
      i_product_group
      , i_ip
      , i_port
      , i_is_used
      , i_admin_id
      , current_timestamp
    )
    ON CONFLICT(product_group)
    DO UPDATE
    SET
      ip = EXCLUDED.ip
      , port = EXCLUDED.port
      , is_used = EXCLUDED.is_used
      , admin_id = EXCLUDED.admin_id
      , modified_time = EXCLUDED.modified_time;
  ELSE
    RAISE EXCEPTION 'The server IP already exists.' USING HINT = 'DB-00052';
  END IF;

END;
$$;


