--
-- Name: sp_add_query_report(text, text, text, text[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_query_report(i_login_admin_id text, i_name text, i_description text, i_query_report_item text[]) RETURNS TABLE(query_report_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query_report_id           bigint;
  row_query_report_item       text[];
  idx                         integer := 0;

  con_column_length           CONSTANT integer := 6;
  con_report_item_type        CONSTANT integer := 1;
  con_report_graph_type       CONSTANT integer := 2;
  con_query                   CONSTANT integer := 3;
  con_db_type                 CONSTANT integer := 4;
  con_graph_title             CONSTANT integer := 5;
  con_graph_color             CONSTANT integer := 6;
BEGIN

  --컬럼 길이 체크하기
  IF ARRAY_LENGTH(i_query_report_item, 2) <> con_column_length THEN
    RAISE EXCEPTION 'Different column array lengths.' USING HINT = 'DB-00020';
  END IF;

  -- 명칭 중복 체크
  IF (EXISTS (SELECT 1 FROM tb_query_report AS q WHERE q.admin_id = i_login_admin_id AND q.name = i_name)) THEN
    RAISE EXCEPTION 'The name is already registered.(%)', i_name USING HINT = 'DB-00037';
  END IF;

  -- tb_query_report 등록
    name, description, admin_id, create_time
  ) VALUES(
    i_name, i_description, i_login_admin_id, now()
  )
  RETURNING tb_query_report.query_report_id INTO v_query_report_id;


  -- tb_query_report_item 등록
  FOREACH row_query_report_item SLICE 1 IN ARRAY i_query_report_item LOOP
    idx := idx + 1;

      query_report_id, item_order
      , report_item_type, report_graph_type, query
      , db_type, graph_title, graph_color
    ) VALUES(
      v_query_report_id, idx
      , row_query_report_item[con_report_item_type]::en_report_item_type, row_query_report_item[con_report_graph_type]::en_report_graph_type, row_query_report_item[con_query]
      , row_query_report_item[con_db_type]::en_db_type, row_query_report_item[con_graph_title], row_query_report_item[con_graph_color]
    );

  END LOOP;

  -- v_query_report_id를 리턴한다.
  RETURN QUERY
    SELECT v_query_report_id::text;

END;
$$;


