--
-- Name: sp_add_report_schedule(text, text, text, public.en_report_type, public.en_base_report_id_type, bigint, public.en_schedule_period_type, timestamp without time zone, timestamp without time zone, text[], text, bigint, text, boolean, public.en_schedule_type, text, boolean, boolean); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_report_schedule(i_login_admin_id text, i_name text, i_description text, i_report_type public.en_report_type, i_base_report_id public.en_base_report_id_type, i_query_report_id bigint, i_period_type public.en_schedule_period_type, i_period_start timestamp without time zone, i_period_end timestamp without time zone, i_params text[], i_target text, i_correlation_rule_id bigint, i_schedule text, i_mail_alarm boolean, i_schedule_type public.en_schedule_type, i_user_mail text, i_is_admin_mail boolean, i_is_user_mail boolean) RETURNS TABLE(report_schedule_id bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  IF (i_correlation_rule_id IS NULL OR EXISTS (SELECT 1 FROM tb_correlation_rule cr WHERE cr.correlation_rule_id = i_correlation_rule_id AND cr.correlation_type = 'GENERAL')) THEN
    RETURN QUERY
              report_type, base_report_id, query_report_id,
              admin_id, period_type, period_start, period_end, params, schedule, mail_alarm, modified_time,
              target, correlation_rule_id, name, description, is_removed, schedule_type, user_mail, is_admin_mail, is_user_mail)
      VALUES (i_report_type, i_base_report_id, i_query_report_id,
              i_login_admin_id, COALESCE(i_period_type, COALESCE((SELECT default_period_type FROM tb_base_report WHERE base_report_id = i_base_report_id),'LATEST')), i_period_start, i_period_end, i_params, i_schedule, i_mail_alarm, now(),
              i_target, i_correlation_rule_id, i_name, i_description, false, i_schedule_type, i_user_mail, i_is_admin_mail, i_is_user_mail)
      RETURNING tb_report_schedule.report_schedule_id;
  ELSE
    RAISE EXCEPTION 'Correlation type is not general.' USING HINT = 'DB-00061';
  END IF;

END;
$$;


