--
-- Name: sp_add_schedule_trigger(text, bigint, public.en_schedule_job_type, bigint, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_schedule_trigger(i_trigger_time text, i_job_id bigint, i_job_type public.en_schedule_job_type, i_tenant_server bigint, i_reference_value text) RETURNS TABLE(trigger_id bigint, reference_value text)
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_license			BOOL := TRUE;
	v_tenant_server		BIGINT;
	v_reference_value	TEXT;
	v_execute_status	en_execute_status;
	v_schedule_code		TEXT;
	v_without_duple		TEXT;
BEGIN

	v_tenant_server = i_tenant_server;
	IF i_tenant_server = 0 THEN
		WITH schedule_trigger AS (
			SELECT tenant_server
			FROM tb_schedule_trigger
			GROUP BY tenant_server
			ORDER BY COUNT(*)
			LIMIT 1
		)
		, target_server AS (
			SELECT schedule_trigger.tenant_server
			FROM schedule_trigger
			UNION ALL
			SELECT server_id AS tenant_server
			FROM tb_service
			WHERE service_status = 'NORMAL'
				AND service_type = 'SCHEDULER'
				AND NOT EXISTS (SELECT schedule_trigger.tenant_server FROM schedule_trigger)
			LIMIT 1
		)
		SELECT
			target_server.tenant_server
			INTO v_tenant_server
		FROM
			target_server;
	END IF;

	IF i_job_type = 'UNITY_JOB' THEN
		v_license = FALSE;

		SELECT
        	(product_license.expire_date > now())
        	, schedule.reference_value
        	, schedule_code :: TEXT
        	, schedule :: json ->> 'without_duple' AS without_duple
        	INTO v_license, v_reference_value, v_schedule_code, v_without_duple
        FROM tb_schedule schedule
      	INNER JOIN tb_product product ON schedule.product_group = product.product_group
      	INNER JOIN tb_product_license product_license ON product_license.product_id = product.product_id
      	WHERE schedule.schedule_id = i_job_id
        	AND schedule.enabled = TRUE
        	;
	END IF
	;

  IF v_schedule_code = 'EPP_UPDATE' THEN
    v_license = TRUE;
  END IF
	;

	v_execute_status = 'READY';

	IF v_reference_value = 'RUN_TIME' THEN
		v_execute_status = 'RUN_TIME';

		UPDATE tb_schedule
		SET enabled = FALSE
		WHERE schedule_id = i_job_id;
	ELSEIF v_without_duple = 'true'
		AND EXISTS (SELECT 1 FROM tb_schedule_trigger
						WHERE job_id = i_job_id
						AND job_type = i_job_type
						AND execute_status = 'PROGRESS'
						AND tenant_server = v_tenant_server
						)THEN
			v_execute_status = 'DUPLE_SKIP';
	END IF;


		trigger_time
		, job_id
		, job_type
		, tenant_server
		, reference_value
		, execute_status
		, modified_time
		, created_time
	)
	SELECT
		i_trigger_time
		, i_job_id
		, i_job_type
		, v_tenant_server
		, i_reference_value
		, v_execute_status
		, to_timestamp(substr(i_trigger_time,1,12), 'YYYYMMDDHH24MI')
		, to_timestamp(substr(i_trigger_time,1,12), 'YYYYMMDDHH24MI')
	FROM (
		SELECT
			count(sch.trigger_time) AS trigger_cnt
		FROM tb_schedule_trigger AS sch
		WHERE sch.trigger_time = i_trigger_time
			AND sch.job_id = i_job_id
			AND sch.job_type = i_job_type
	) exist_chk
	WHERE exist_chk.trigger_cnt = 0
	ON CONFLICT ON CONSTRAINT tb_schedule_trigger_ukey DO NOTHING;

    RETURN QUERY
    	SELECT
    		rst.trigger_id
    		, rst.reference_value
    	FROM tb_schedule_trigger rst
    	WHERE rst.trigger_time = i_trigger_time
			AND rst.job_id = i_job_id
			AND rst.job_type = i_job_type
	;

END;
$$;


ALTER FUNCTION public.sp_add_schedule_trigger(i_trigger_time text, i_job_id bigint, i_job_type public.en_schedule_job_type, i_tenant_server bigint, i_reference_value text) OWNER TO cppoltp;

