--

CREATE FUNCTION public.sp_add_server_key(i_name text, i_ip text, i_server_key text) RETURNS TABLE(server_id bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  -- 서버 IP 체크
  IF (SELECT EXISTS (SELECT 1 FROM tb_server AS s WHERE s.ip = i_ip)) = true THEN
    RAISE EXCEPTION 'The server IP already exists.' USING HINT = 'DB-00021';
  END IF;

  RETURN QUERY
    VALUES (i_name, i_ip, i_server_key, 'ADDING', now() )
    RETURNING tb_server.server_id;

END;
$$;


