--
-- Name: sp_add_system_correlation_send_mail(bigint, bigint, public.en_correlation_condition_id_type[], text[], text, text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_system_correlation_send_mail(i_job_id bigint, i_correlation_rule_id bigint, i_macro_type_list public.en_correlation_condition_id_type[], i_macro_value_list text[], i_mail_body text, i_correlation_name text, i_mail_image text, i_custom_email text, i_custom bigint) RETURNS void
    LANGUAGE plpgsql
    AS $_$
DECLARE
v_mail_body TEXT;
v_payload_format TEXT;
v_task_id BIGINT;
BEGIN

SELECT REPLACE(i_mail_body,'${TITLE}',i_correlation_name) INTO v_mail_body;

SELECT tt.payload_format INTO v_payload_format
FROM tb_task_type tt
WHERE tt.task_type = 'SEND_MAIL';

VALUES(i_job_id, 'SEND_MAIL', '', 1, now(), now())
RETURNING tb_task.task_id INTO v_task_id;


SELECT v_task_id, concat('[', string_agg(format(v_payload_format, t.email, i_correlation_name, sp_base64_encode(t.mail_body), i_mail_image), ','), ']'), 0, now()
FROM (
  -- custom email  EMS5-1421 적용

  SELECT
    a.email
    , replace_recursive(v_mail_body, array_agg(array[org.cr_macro, org.cr_value])) AS mail_body
  FROM(
  SELECT
    CONCAT('${', cr_macro, '}') as cr_macro
    , cr_value
  FROM
    UNNEST(
      i_macro_type_list
      , i_macro_value_list
    ) t(cr_macro, cr_value)
  WHERE cr_value IS NOT NULL

  UNION ALL
  SELECT
    CONCAT('${', t.macro, '}') as cr_macro
    , '' AS cr_value
  FROM
    UNNEST(ENUM_RANGE(NULL::en_correlation_condition_id_type)) t(macro)
  WHERE
    NOT EXISTS(
      SELECT cr.macro FROM UNNEST( i_macro_type_list ) cr(macro) WHERE t.macro = cr.macro
  )
  ) org
  CROSS JOIN(
  SELECT DISTINCT a.email
      FROM tb_admin a
      WHERE EXISTS(
      SELECT 1 FROM unnest(concat('{', i_custom_email, '}')::TEXT[]) t(admin_id)
      WHERE t.admin_id = a.admin_id
      )
  ) a
  GROUP BY a.email

) t;

END;
$_$;


ALTER FUNCTION public.sp_add_system_correlation_send_mail(i_job_id bigint, i_correlation_rule_id bigint, i_macro_type_list public.en_correlation_condition_id_type[], i_macro_value_list text[], i_mail_body text, i_correlation_name text, i_mail_image text, i_custom_email text, i_custom bigint) OWNER TO cppoltp;

--
-- Name: sp_add_task_instance(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_task_instance(i_task_id bigint) RETURNS TABLE(instance_id text)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_instance_id bigint;

BEGIN

  IF (SELECT is_schedule FROM tb_job j JOIN tb_task t ON j.job_id = t.job_id AND t.task_id = i_task_id) THEN

        VALUES (i_task_id, now())
        RETURNING tb_task_instance.instance_id INTO v_instance_id;

  ELSE

    v_instance_id = 0;

  END IF;

  RETURN QUERY SELECT v_instance_id::text;

END;
$$;


ALTER FUNCTION public.sp_add_task_instance(i_task_id bigint) OWNER TO cppoltp;

--
-- Name: sp_add_task_realtime(public.en_task_type, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_task_realtime(i_task_type public.en_task_type, i_logical_target text, i_target_filter text, i_logical_payload text, i_internal_payload text, i_server_context text, i_console_context text, i_admin_id text) RETURNS TABLE(job_id text, task_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_job_id  bigint;
  v_task_id bigint;
    v_task_target_type en_task_target_type;

BEGIN

  IF i_task_type = 'APPLY_POLICY' THEN
  CASE
  WHEN  (COALESCE(i_internal_payload, '')='') OR (COALESCE((i_internal_payload::json ->> 'policy_id'), '')='')
  THEN i_target_filter := '[]';
  ELSE i_target_filter := sp_get_policy_target_filter((i_internal_payload::json ->> 'policy_id')::bigint);
  END CASE;
  END IF;

  -- taks target type
  SELECT task_target_type
    INTO v_task_target_type
    FROM tb_task_type ttt
   WHERE task_type = i_task_type
   ;

    is_schedule,
    schedule_detail,
    admin_id,
    logical_target,
    correlation_rule_id,
    onoff,
    visible,
    create_time,
    modified_time,
    target_filter
  )
  VALUES
  (
    false,
    null,
    i_admin_id,
    i_logical_target,
    null,
    true,
    v_task_target_type != 'SERVER' AND i_task_type != 'APPLY_MERGEABLE_POLICY', /* 서버 명령인 경우 visible 을 false 로 처리.  2018/06/18 task_type 이 APPLY_MERGEABLE_POLICY 인 경우 visible 을 false 로 처리. */
    now(),
    now(),
    i_target_filter

  )
  RETURNING j.job_id INTO v_job_id;


      job_id,
      task_type,
      logical_payload,
      task_order,
      create_time,
      modified_time,
      internal_payload,
      server_context_payload,
      console_context_payload
    )
    VALUES
    (
      v_job_id,
      i_task_type,
      i_logical_payload,
      1,
      now(),
      now(),
      i_internal_payload,
      i_server_context,
      i_console_context
    )
    RETURNING t.task_id INTO v_task_id;

RETURN QUERY
select  v_job_id::text, v_task_id::text;

END;
$$;


ALTER FUNCTION public.sp_add_task_realtime(i_task_type public.en_task_type, i_logical_target text, i_target_filter text, i_logical_payload text, i_internal_payload text, i_server_context text, i_console_context text, i_admin_id text) OWNER TO cppoltp;

--
-- Name: sp_add_task_schedule(public.en_task_type, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_task_schedule(i_task_type public.en_task_type, i_logical_target text, i_target_filter text, i_schedule_detail text, i_logical_payload text, i_internal_payload text, i_server_context text, i_console_context text, i_admin_id text) RETURNS TABLE(job_id text, task_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_job_id  bigint;
  v_task_id bigint;
  v_policy_id bigint;
  v_task_target_type en_task_target_type;
  v_internal_payload TEXT := i_internal_payload;
BEGIN

  IF i_task_type = 'APPLY_POLICY' THEN
  CASE
  WHEN  (COALESCE(v_internal_payload, '')='') OR (COALESCE((v_internal_payload::json ->> 'policy_id'), '')='')
  THEN i_target_filter := '[]';
  ELSE
    i_target_filter := sp_get_policy_target_filter((v_internal_payload::json ->> 'policy_id')::bigint);
    v_policy_id := (v_internal_payload::json ->> 'policy_id')::bigint;

    v_internal_payload := (v_internal_payload::jsonb || ('{"is_updated":false,"is_all":false,"is_keep_agent_policy":' || CASE WHEN (SELECT (json_array_elements(i_logical_target::json) ->> 'type') = 'GROUP') THEN 'false' ELSE 'true' END || '}')::jsonb)::text;

  END CASE;
  END IF;
  -- taks target type
  SELECT task_target_type
    INTO v_task_target_type
    FROM tb_task_type ttt
   WHERE task_type = i_task_type
   ;

    is_schedule,
    schedule_detail,
    admin_id,
    logical_target,
    correlation_rule_id,
    onoff,
    visible,
    create_time,
    modified_time,
    target_filter
  )
  VALUES
  (
    true,
    i_schedule_detail,
    i_admin_id,
    i_logical_target,
    null,
    true,
    v_task_target_type != 'SERVER' AND i_task_type != 'APPLY_MERGEABLE_POLICY', /* 서버 명령인 경우 visible 을 false 로 처리.  2018/06/18 task_type 이 APPLY_MERGEABLE_POLICY 인 경우 visible 을 false 로 처리. */
    now(),
    now(),
    i_target_filter
  )
  RETURNING j.job_id INTO v_job_id;

  --RETURN QUERY
      job_id,
      task_type,
      logical_payload,
      task_order,
      create_time,
      modified_time,
      internal_payload,
      server_context_payload,
      console_context_payload
    )
    VALUES
    (
      v_job_id,
      i_task_type,
      i_logical_payload,
      1,
      now(),
      now(),
      v_internal_payload,
      i_server_context,
      i_console_context
    )
    RETURNING tb_task.task_id INTO v_task_id;

  RETURN QUERY
  SELECT t.job_id::text, t.task_id::text
  FROM tb_task t
  WHERE t.task_id = v_task_id
  UNION ALL
  SELECT cj.job_id::text, cj.task_id::text
  FROM sp_add_child_policy_task(v_policy_id, i_admin_id, i_logical_target, i_target_filter, i_schedule_detail, v_internal_payload) cj;

END;
$$;


ALTER FUNCTION public.sp_add_task_schedule(i_task_type public.en_task_type, i_logical_target text, i_target_filter text, i_schedule_detail text, i_logical_payload text, i_internal_payload text, i_server_context text, i_console_context text, i_admin_id text) OWNER TO cppoltp;

--
-- Name: sp_add_task_target_status(bigint, public.en_task_type, public.en_task_target_type, bigint[], bigint, public.en_task_status, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_task_target_status(i_task_id bigint, i_task_type public.en_task_type, i_task_target_type public.en_task_target_type, i_target_id bigint[], i_instance_id bigint, i_task_status public.en_task_status, i_task_error text) RETURNS TABLE(err_code text, err_msg text)
    LANGUAGE plpgsql
    AS $$

BEGIN

  SELECT d.task_id AS task_id
        ,i_task_type
        ,i_task_target_type
        ,d.target_id AS target_id
        ,d.instance_id AS instance_id
        ,i_task_status
        ,i_task_error
        ,now() AS server_time
  FROM (SELECT i_task_id AS task_id
              ,unnest(i_target_id) AS target_id
              ,i_instance_id AS instance_id
       ) d
  ON CONFLICT (task_id, task_target_type, target_id, instance_id) DO
  UPDATE
  SET task_status = EXCLUDED.task_status
     ,task_error = EXCLUDED.task_error
     ,server_time = EXCLUDED.server_time;

  RETURN QUERY SELECT 'DB-00000'::text, 'success'::text;

END;
$$;


ALTER FUNCTION public.sp_add_task_target_status(i_task_id bigint, i_task_type public.en_task_type, i_task_target_type public.en_task_target_type, i_target_id bigint[], i_instance_id bigint, i_task_status public.en_task_status, i_task_error text) OWNER TO cppoltp;

