-- Name: sp_add_unity_schedule(public.en_product_group_type, public.en_schedule_code, integer, text, boolean, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_unity_schedule(i_product_group public.en_product_group_type, i_schedule_code public.en_schedule_code, i_schedule_code_index integer, i_schedule text, i_work_all boolean, i_execute_uri text, i_reference_value text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_schedule_id               text;
BEGIN

    VALUES( i_product_group, i_schedule_code, i_schedule_code_index, i_schedule, i_work_all, i_execute_uri, i_reference_value, true, now() )
  ON CONFLICT ON CONSTRAINT tb_schedule_schedule_code_ukey DO UPDATE SET product_group = EXCLUDED.product_group, schedule = EXCLUDED.schedule, work_all = EXCLUDED.work_all
      , execute_uri = EXCLUDED.execute_uri, reference_value = EXCLUDED.reference_value, enabled = EXCLUDED.enabled, modified_time = EXCLUDED.modified_time
  RETURNING tb_schedule.schedule_id::text INTO v_schedule_id;

  RETURN v_schedule_id;

END;
$$;


