--
-- Name: sp_add_upload_file_from_agent(text, text, text, bigint, public.en_upload_file_type, text, bigint, bigint, bigint, timestamp with time zone, timestamp with time zone, timestamp with time zone, bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_upload_file_from_agent(i_file_name text, i_file_uri text, i_file_path text, i_file_size bigint, i_file_type public.en_upload_file_type, i_file_hash text, i_node_id bigint, i_task_id bigint, i_instance_id bigint, i_collect_time timestamp with time zone, i_file_create_time timestamp with time zone, i_file_modify_time timestamp with time zone, i_tz_offset bigint, i_server_id bigint, i_ahnreport_file_url text) RETURNS TABLE(file_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
      file_name
      , file_uri
      , file_path
      , file_size
      , file_type
      , file_hash
      , modified_time
      , node_id
      , task_id
      , instance_id
      , collect_time
      , file_create_time
      , file_modify_time
      , tz_offset
      , server_id
      , ahnreport_file_url
    ) VALUES(
      i_file_name
      , i_file_uri
      , i_file_path
      , i_file_size
      , i_file_type
      , i_file_hash
      , now()
      , i_node_id
      , i_task_id
      , i_instance_id
      , i_collect_time
      , i_file_create_time
      , i_file_modify_time
      , i_tz_offset
      , i_server_id
      , i_ahnreport_file_url
    )
    RETURNING tb_upload_file.file_id::text;

END;
$$;


ALTER FUNCTION public.sp_add_upload_file_from_agent(i_file_name text, i_file_uri text, i_file_path text, i_file_size bigint, i_file_type public.en_upload_file_type, i_file_hash text, i_node_id bigint, i_task_id bigint, i_instance_id bigint, i_collect_time timestamp with time zone, i_file_create_time timestamp with time zone, i_file_modify_time timestamp with time zone, i_tz_offset bigint, i_server_id bigint, i_ahnreport_file_url text) OWNER TO cppoltp;

--
-- Name: sp_add_v3_linux_policy(text, text, text, text, boolean, text, text, boolean, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_v3_linux_policy(i_policy_name text, i_description text, i_online_policy_body text, i_offline_policy_body text, i_use_offline_policy boolean, i_update_online_policy_body text, i_update_offline_policy_body text, i_use_update_offline_policy boolean, i_hash text, i_admin_id text) RETURNS TABLE(policy_id bigint, policy_name text, product_feature_id public.en_product_feature_id_type, description text, online_policy_body text, offline_policy_body text, use_offline_policy text, hash text)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_policy_id bigint;
  v_privilege_profile_auth boolean;

BEGIN

SELECT p.policy_id AS policy_id
INTO v_policy_id
FROM sp_add_policy(i_policy_name, 'V3NET_LU_AV', i_description, i_online_policy_body,
                   i_offline_policy_body, i_use_offline_policy, i_hash, null, i_admin_id) p;

SELECT
    EXISTS (
        SELECT
            1
        FROM
            tb_admin ta
        INNER JOIN
            tb_privilege_profile tpp
        ON
            ta.privilege_profile_id = tpp.privilege_profile_id 
        WHERE
            tpp.profile_body LIKE '%"/policy/policy_V3L_W"%'
        AND
            ta.admin_id = i_admin_id
    ) INTO v_privilege_profile_auth;
	
	
IF v_privilege_profile_auth = FALSE THEN
  RAISE EXCEPTION 'You do not have permission to write policy' USING HINT = 'DB-00084';
END IF;

RETURN QUERY
SELECT p.policy_id AS policy_id
      ,p.name AS policy_name
      ,p.product_feature_id AS product_feature_id
      ,p.description AS description
      ,p.online_policy_body AS online_policy_body
      ,COALESCE(p.offline_policy_body, '') AS offline_policy_body
      ,COALESCE(p.use_offline_policy, false)::integer::text AS use_offline_policy
      ,COALESCE(p.hash, '') AS hash
FROM tb_policy p
WHERE p.policy_id = v_policy_id
UNION ALL
SELECT up.policy_id AS policy_id
      ,up.policy_name AS policy_name
      ,up.product_feature_id AS product_feature_id
      ,up.description AS description
      ,up.online_policy_body AS online_policy_body
      ,up.offline_policy_body AS offline_policy_body
      ,up.use_offline_policy AS use_offline_policy
      ,up.hash AS hash
FROM sp_add_policy(i_policy_name || '_update', 'V3NET_LU_UPDATE', i_description || '_update', i_update_online_policy_body,
                   i_update_offline_policy_body, i_use_update_offline_policy, (i_hash || '1')::text, v_policy_id, i_admin_id) up;

END;
$$;


