--
-- Name: sp_add_widget(text[], text[], bigint[], bigint[], text[], text[], text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_add_widget(i_widget_layout text[], i_name text[], i_group_id bigint[], i_correlation_rule_id bigint[], i_widget_item_type text[], i_widget_item_layout text[], i_admin_id text) RETURNS TABLE(widget_id text)
    LANGUAGE plpgsql
    AS $$

DECLARE
  v_widget_id         bigint    DEFAULT 0;
  v_widget_item_type_array  text[];
  v_widget_item_layout_array  text[];

BEGIN
  --widget 컬럼 길이 체크하기
  IF ARRAY_LENGTH(i_widget_layout, 1) <> ARRAY_LENGTH(i_name, 1)
     AND ARRAY_LENGTH(i_name, 1) <> ARRAY_LENGTH(i_group_id, 1)
  THEN
    RAISE EXCEPTION 'Different column array lengths.' USING HINT = 'DB-00020';
  END IF;


  FOR i IN 1..array_length(i_widget_layout, 1)
  LOOP

  v_widget_item_type_array := regexp_split_to_array(replace(i_widget_item_type[i], ' ', ''), '\|');
  v_widget_item_layout_array := regexp_split_to_array(replace(i_widget_item_layout[i], ' ', ''), '\|');

  IF ARRAY_LENGTH(v_widget_item_type_array, 1) <> ARRAY_LENGTH(v_widget_item_layout_array, 1)
  THEN
    RAISE EXCEPTION 'Different column array lengths.' USING HINT = 'DB-00020';
  END IF;


  --tb_widget insert
     name
    ,group_id
    ,layout
    ,correlation_rule_id
    ,admin_id)
  VALUES  (i_name[i]
          ,i_group_id[i]
    ,i_widget_layout[i]
    ,COALESCE(i_correlation_rule_id[i], 0)
    ,i_admin_id)
  RETURNING tb_widget.widget_id INTO v_widget_id;

  --tb_widget_item insert
     widget_id
    ,widget_item_type
    ,layout
    ,modified_time)
  SELECT v_widget_id
        ,t.widget_item_type::en_widget_item_type
        ,t.layout
        ,now()
    FROM unnest(
         v_widget_item_type_array
        ,v_widget_item_layout_array)
      AS t(widget_item_type
          ,layout);

  END LOOP;

  RETURN QUERY SELECT v_widget_id::text;
END;
$$;


ALTER FUNCTION public.sp_add_widget(i_widget_layout text[], i_name text[], i_group_id bigint[], i_correlation_rule_id bigint[], i_widget_item_type text[], i_widget_item_layout text[], i_admin_id text) OWNER TO cppoltp;

