CREATE FUNCTION public.sp_authenticate_node(i_node_id bigint, i_machine_uuid text, i_machine_type public.en_machine_type) RETURNS TABLE(node_id bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE

BEGIN
  -- PERFORM sp_check_agent_id( i_node_id, i_machine_uuid );
  -- 기본 등록여부 판단
  RETURN QUERY
    SELECT
    n.node_id
  FROM tb_node AS n
  WHERE n.node_id = i_node_id
    AND n.machine_uuid = i_machine_uuid
    -- AND n.machine_type = i_machine_type -- CWPP-2916 :  machine_type 조건 제거
    AND n.is_removed = FALSE
  LIMIT 1;

END;
$$;


