--
-- Name: sp_auto_groupping(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_auto_groupping(i_node_id bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE

  -- auto_grouping_type
  v_final_ipv4_c_class text := 'cclass_ip';
  v_final_ipv4_b_class text := 'bclass_ip';
  v_final_ipv4_b_c_class text := 'bcclass_ip';
  v_final_domain text := 'domain';
  v_final_dept text := 'dept';
  v_final_imported_group_info text := 'group_info';

  -- auto_grouping_target
  v_final_connected_agent text := 'connected_agent';
  v_final_default_group_agent text := 'default_group_agent';

  -- auto_grouping_condition
  v_final_connected_ip text := 'connected_ip';
  v_final_ip text := 'ip';


  v_config json;
  v_target bigint[];
  v_is_group_connect_ip bool;
  v_auto_grouping_path text;


BEGIN

  SELECT jsonb_object_agg(key, value) INTO v_config FROM sp_get_config_group_list('GROUPING'::en_config_group);

  -- 자동 그룹화 사용
  IF (v_config->>'auto_grouping_use' = 'true') THEN

    -- target 추출
    IF (v_config->>'auto_grouping_target' = v_final_connected_agent) THEN
      v_target := array[i_node_id]::bigint[];
    ELSEIF (v_config->>'auto_grouping_target' = v_final_default_group_agent AND EXISTS(SELECT 1 FROM tb_node n JOIN tb_group g ON n.group_id = g.group_id AND g.group_type = 'DEFAULT' AND n.node_id = i_node_id)) THEN
      v_target := array[i_node_id]::bigint[];
    END IF;

    IF v_target IS NULL THEN
      RETURN;
    END IF;

    -- is group by connected ip
    CASE v_config->>'auto_grouping_condition'
      WHEN v_final_connected_ip THEN
        v_is_group_connect_ip  = true;

      WHEN v_final_ip THEN
        v_is_group_connect_ip  = false;
    END CASE;

    -- auto grouping path
    v_auto_grouping_path := v_config->>'auto_grouping_path';

    -- 그룹화 방법별 수행
    CASE v_config->>'auto_grouping_type'
      WHEN v_final_ipv4_c_class THEN
        PERFORM sp_group_node_by_ipv4_c_class(v_auto_grouping_path, v_target, v_is_group_connect_ip);

      WHEN v_final_ipv4_b_class THEN
        PERFORM sp_group_node_by_ipv4_b_class(v_auto_grouping_path, v_target, v_is_group_connect_ip);

      WHEN v_final_ipv4_b_c_class THEN
        PERFORM sp_group_node_by_ipv4_b_c_class(v_auto_grouping_path, v_target, v_is_group_connect_ip);

      WHEN v_final_dept  THEN
        PERFORM sp_group_node_by_dept(v_auto_grouping_path, v_target);

    END CASE;


    -- 보조 서버 업데이트
      SELECT n.node_id, 'NODE', f.server_id, false
      FROM tb_node AS n
      JOIN (
        SELECT f.target_id AS group_id, f.server_id
        FROM tb_file_update_server AS f
        WHERE f.target_type = 'GROUP'
      ) AS f ON n.group_id = f.group_id AND n.node_id = i_node_id
    ON CONFLICT(target_id, target_type, server_id) DO NOTHING;


  END IF;

END;
$$;


ALTER FUNCTION public.sp_auto_groupping(i_node_id bigint) OWNER TO cppoltp;

