CREATE FUNCTION public.sp_base64_decode(i_text text) RETURNS text
    LANGUAGE plpgsql
    AS $$
BEGIN

RETURN convert_from(decode(i_text, 'base64'), 'UTF-8');

END;
$$;


ALTER FUNCTION public.sp_base64_decode(i_text text) OWNER TO cppoltp;

--
-- Name: sp_base64_encode(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_base64_encode(i_text text) RETURNS text
    LANGUAGE plpgsql
    AS $$
BEGIN

RETURN regexp_replace(encode(REPLACE(i_text, '\', '\\')::BYTEA, 'base64'), E'[\\n\\r]+', '', 'g' );

END;
$$;


