--
-- Name: sp_change_file_update_server(bigint[], bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_change_file_update_server(i_node_id bigint[], i_target_group bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_server_id                 bigint[] := NULL;
BEGIN

  -- delete
  DELETE FROM tb_file_update_server
  WHERE target_id = ANY(i_node_id)
    AND target_type = 'NODE'
    AND specified = false;

  -- target group
  SELECT ARRAY_AGG(server_id) INTO v_server_id
  FROM tb_file_update_server
  WHERE target_id = i_target_group
    AND target_type = 'GROUP';

  IF v_server_id IS NOT NULL THEN
      SELECT t.node_id, 'NODE', s.server_id, false
      FROM UNNEST(i_node_id) AS t(node_id)
      CROSS JOIN UNNEST(v_server_id) AS s(server_id)
      WHERE NOT(t.node_id = ANY(SELECT f.target_id FROM tb_file_update_server AS f WHERE f.target_id = ANY(i_node_id) AND target_type = 'NODE' AND specified = TRUE))
    ON CONFLICT(target_id, target_type, server_id) DO NOTHING;
  END IF;


END;
$$;


ALTER FUNCTION public.sp_change_file_update_server(i_node_id bigint[], i_target_group bigint) OWNER TO cppoltp;

--
-- Name: sp_change_pg_status(text, integer, public.en_pg_service_status, integer); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_change_pg_status(i_ip text, i_port integer, i_pg_service_status public.en_pg_service_status, i_processed_packet integer) RETURNS TABLE(v_pg_server_id bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
v_pg_server_id bigint;
v_r RECORD;
BEGIN

  IF ( SELECT count(1) FROM tb_pg_server WHERE ip = i_ip) >= 1 THEN
    UPDATE tb_pg_server SET pg_service_status = i_pg_service_status, processed_packet = i_processed_packet WHERE ip = i_ip;
    SELECT pg_server_id INTO v_pg_server_id FROM tb_pg_server WHERE ip = i_ip;

  ELSEIF ( SELECT count(1) FROM tb_pg_server WHERE ip = i_ip ) = 0 THEN
    VALUES ( i_ip, i_port, i_pg_service_status, i_processed_packet, now() )
    RETURNING pg_server_id INTO v_pg_server_id;

    RETURN QUERY
      SELECT v_pg_server_id::bigint;
  END IF;
END;
$$;


ALTER FUNCTION public.sp_change_pg_status(i_ip text, i_port integer, i_pg_service_status public.en_pg_service_status, i_processed_packet integer) OWNER TO cppoltp;

