CREATE FUNCTION public.sp_check_agent_id(i_node_id bigint, i_machine_uuid text) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
  if (false = (select exists (select 1 from tb_node n where n.node_id = i_node_id and n.machine_uuid = i_machine_uuid AND n.is_removed = false))) then
    RAISE EXCEPTION 'Invalid node_id(%) for machine_uuid(%)', i_node_id, i_machine_uuid using HINT = 'DB-99999';
  end if;
end;
$$;


