--
-- Name: sp_check_connect_cloud(text, public.en_machine_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_check_connect_cloud(i_machine_uuid text, i_machine_type public.en_machine_type) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_result boolean;

BEGIN
	
	IF i_machine_type = 'CLOUD_AWS' THEN
		SELECT COUNT(1) > 0 INTO v_result
		FROM tb_cloud_aws_instance
		WHERE instance_id ILIKE i_machine_uuid;
	ELSEIF i_machine_type = 'CLOUD_AZURE' THEN
		SELECT COUNT(1) > 0 INTO v_result
		FROM tb_cloud_azure_vm
		WHERE vm_id ILIKE i_machine_uuid;
	ELSEIF i_machine_type = 'CLOUD_ALIBABA' THEN
		SELECT COUNT(1) > 0 INTO v_result
		FROM tb_cloud_alibaba_instance
		WHERE instance_id ILIKE i_machine_uuid;
	ELSE
		v_result = false;
	END IF;

  RETURN v_result;

END;
$$;


