CREATE FUNCTION public.sp_check_file_sync(i_product_id public.en_product_id_type) RETURNS TABLE(check_count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
   SELECT count(server_id)
FROM tb_service ts
WHERE ts.service_type = 'FILESERVER-UPLOAD'
  AND ts.enabled = true
  AND ts.server_id NOT IN
    (SELECT tps.server_id
     FROM tb_pkg_server tps
     JOIN tb_product_pkg tpp ON tps.product_pkg_id = tpp.product_pkg_id and tpp.is_removed is false
     WHERE tpp.product_id = i_product_id);
END;
$$;


