--

CREATE FUNCTION public.sp_check_license(i_product_group public.en_product_group_type) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_result                    boolean;
BEGIN

  SELECT COUNT(1) > 0 INTO v_result
  FROM tb_product AS p
  JOIN tb_product_license AS pl ON p.product_id = pl.product_id AND pl.expire_date > now()
  WHERE p.product_group = i_product_group;

  RETURN v_result;

END;
$$;


