--
-- Name: sp_check_multi_admin(public.en_privilege_profile_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_check_multi_admin(i_profile_type public.en_privilege_profile_type) RETURNS TABLE(admin_id text, error_message text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_top_group_id              bigint;
BEGIN

  UPDATE tb_temp_admin_temp AS t SET error_message = '' WHERE t.error_message IS NULL;

  -- 입력이 중복된 아이디 체크
  UPDATE tb_temp_admin_temp AS t
    SET error_message = t.error_message || ',DUPLICATE_ADMIN_ID'
  WHERE EXISTS (
    SELECT 1
    FROM (
      SELECT ta.admin_id, COUNT(1) AS cnt
      FROM tb_temp_admin_temp AS ta
      GROUP BY ta.admin_id
    ) AS ta
    WHERE ta.cnt > 1 AND ta.admin_id = t.admin_id
  );

  -- 중복된 아이디 체크(데이타 베이스와 비교)
  IF i_profile_type = 'DEPT_ADMIN' THEN
    UPDATE tb_temp_admin_temp AS t
      SET error_message = t.error_message || ',REGISTERED_ADMIN_ID'
    WHERE EXISTS (
      SELECT 1
      FROM tb_admin AS a
      JOIN tb_privilege_profile AS p ON p.privilege_profile_id = a.privilege_profile_id
      WHERE p.profile_type <> i_profile_type
        AND a.admin_id = t.admin_id
    );
  ELSE
    UPDATE tb_temp_admin_temp AS t
      SET error_message = t.error_message || ',REGISTERED_ADMIN_ID'
    WHERE EXISTS (
      SELECT 1
      FROM tb_admin AS a
      WHERE a.admin_id = t.admin_id
    );
  END IF;

  -- 아이디 길이 체크(5-10자)
  UPDATE tb_temp_admin_temp AS t
    SET error_message = t.error_message || ',ADMIN_ID_LENGTH'
  WHERE LENGTH(t.admin_id) < 5 OR LENGTH(t.admin_id) > 10;

  -- 패스워드  길이 체크(9-30자)
  UPDATE tb_temp_admin_temp AS t
    SET error_message = t.error_message || ',PASSWORD_LENGTH'
  WHERE LENGTH(t.password) < 9 OR LENGTH(t.password) > 30;

  -- OTP 사용인디 이메일이 없는것
  UPDATE tb_temp_admin_temp AS t
    SET error_message = t.error_message || ',EMAIL_NOT_NULL'
  WHERE t.use_otp = TRUE AND LENGTH(COALESCE(t.email, '')) = 0;

  -- 최상위 그룹 가져오기
  SELECT g.group_id INTO v_top_group_id FROM tb_group AS g WHERE g.is_removed = FALSE AND g.group_type = 'TOP' LIMIT 1;

  IF i_profile_type = 'DEPT_ADMIN' THEN
    -- 부서 정보가 존재 하지 않으면 에러
    UPDATE tb_temp_admin_temp AS t
      SET error_message = t.error_message || ',DEPT_CODE_NOT_NULL'
    WHERE LENGTH(COALESCE(t.admin_group, '')) = 0;

    -- 최상위 부서 입력시
    UPDATE tb_temp_admin_temp AS t
      SET error_message = t.error_message || ',DEPT_CODE_TOP_LEVEL'
    WHERE EXISTS (
      SELECT 1
      FROM tb_temp_admin_temp AS at
      WHERE v_top_group_id = ANY( SELECT s.group_id FROM UNNEST(STRING_TO_ARRAY(at.admin_group, ',')::bigint[]) AS s(group_id) )
        AND t.admin_id = at.admin_id
        AND t.admin_group = at.admin_group
        AND LENGTH(COALESCE(at.admin_group, '')) > 0
    );
  ELSE
    UPDATE tb_temp_admin_temp SET admin_group = v_top_group_id;
  END IF;

  UPDATE tb_temp_admin_temp AS t
    SET error_message = SUBSTRING(t.error_message, 2, LENGTH(t.error_message) - 1)
  WHERE SUBSTRING(t.error_message, 1, 1) = ',';

  RETURN QUERY
    SELECT t.admin_id, t.error_message
    FROM tb_temp_admin_temp AS t
    WHERE LENGTH(t.error_message) > 0;

END;
$$;


