-- Name: sp_check_product_registered(public.en_pkg_type, public.en_product_id_type, bigint, public.en_service_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_check_product_registered(i_pkg_type public.en_pkg_type, i_product_id public.en_product_id_type, i_server_id bigint, i_service_type public.en_service_type) RETURNS TABLE(check_count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
   SELECT count(tpp.product_pkg_id) AS check_count
  FROM tb_product_pkg tpp
  JOIN tb_pkg_server tps ON tpp.product_pkg_id = tps.product_pkg_id
  JOIN tb_service ts ON tps.server_id = ts.server_id
  WHERE tpp.pkg_type = i_pkg_type
    AND tpp.product_id = i_product_id
    AND tpp.is_removed is false
    AND tpp.pkg_status = 'SUCCESS'
    AND ts.server_id = i_server_id
    AND ts.service_type = i_service_type;
END;
$$;


