--
-- Name: sp_check_removed_group(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_check_removed_group(i_group_id bigint) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_result	BOOLEAN;
BEGIN
	 
    WITH RECURSIVE pgroup_list (group_id, pgroup_id, is_removed) AS (
      SELECT     group_id, pgroup_id, is_removed
      FROM       tb_group g 
      WHERE      group_id = i_group_id
      UNION ALL
      SELECT     g.group_id, g.pgroup_id, g.is_removed 
      FROM       tb_group g
      INNER JOIN pgroup_list pgl 
      ON         pgl.pgroup_id = g.group_id
    )
    SELECT COUNT(1) > 0 INTO v_result FROM pgroup_list WHERE is_removed <> FALSE;
   
   RETURN v_result;
END;
$$;


