--
-- Name: sp_check_report_status(text, bigint, integer, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_check_report_status(i_login_admin_id text, i_report_schedule_id bigint, i_item_order integer, i_create_time text) RETURNS TABLE(report_type text, report_schedule_id text, item_order text, create_time text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_profile_type              en_privilege_profile_type;
  v_report_type               text := '';
BEGIN

  -- login_admin_id 의 권한 가져오기
  v_profile_type := sp_get_admin_privilege_type( i_login_admin_id );

  -- 권한 체크
  IF v_profile_type IS NULL OR v_profile_type <> 'ROOT_ADMIN' THEN
    IF (EXISTS (SELECT 1 FROM tb_report_schedule AS r WHERE r.report_schedule_id = i_report_schedule_id AND r.admin_id <> i_login_admin_id)) THEN
      RAISE EXCEPTION 'You do not have permission.(%)', i_report_schedule_id USING HINT = 'DB-00022';
    END IF;
  END IF;

  SELECT r.report_type::text INTO v_report_type
  FROM tb_report_schedule AS r
  WHERE r.report_schedule_id = i_report_schedule_id;

  RETURN QUERY
    SELECT
      v_report_type
      , i_report_schedule_id::text
      , i_item_order::text
      , i_create_time;

END;
$$;


