-- Name: sp_check_report_status_list(text, bigint[], integer[], text[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_check_report_status_list(i_login_admin_id text, i_report_schedule_id bigint[], i_item_order integer[], i_create_time text[]) RETURNS TABLE(report_type public.en_report_type, report_schedule_id text, item_order text, create_time text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_profile_type              en_privilege_profile_type;
BEGIN

  -- login_admin_id 의 권한 가져오기
  v_profile_type := sp_get_admin_privilege_type( i_login_admin_id );

  -- 권한 체크
  IF v_profile_type IS NULL OR v_profile_type <> 'ROOT_ADMIN' THEN
    IF (EXISTS (SELECT 1 FROM tb_report_schedule AS r WHERE r.report_schedule_id = ANY(i_report_schedule_id) AND r.admin_id <> i_login_admin_id)) THEN
      RAISE EXCEPTION 'You do not have permission.(%)', i_report_schedule_id USING HINT = 'DB-00022';
    END IF;
  END IF;


  RETURN QUERY
    SELECT
      r.report_type
      , t.report_schedule_id::text
      , t.item_order::text
      , t.create_time
    FROM tb_report_schedule AS r
    CROSS JOIN UNNEST(i_report_schedule_id, i_item_order, i_create_time) AS t(report_schedule_id, item_order, create_time)
    WHERE r.report_schedule_id = ANY(i_report_schedule_id);

END;
$$;


