--
-- Name: sp_check_task(text, bigint[], text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_check_task(i_login_admin_id text, i_task_id bigint[], i_check_type text DEFAULT 'RETRY'::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_profile_type              en_privilege_profile_type;
  v_job_id                    text;
  v_job_id_array              bigint[];
  v_response_retry_interval   integer;
BEGIN

  BEGIN
    SELECT STRING_AGG(t.job_id::text, ',') INTO v_job_id
    FROM tb_task AS t
    WHERE t.task_id = ANY(i_task_id);
  EXCEPTION
    WHEN OTHERS THEN
      v_job_id := '';
  END;

  IF v_job_id <> '' THEN
    v_job_id_array := STRING_TO_ARRAY(v_job_id, ',')::bigint[];

    -- login_admin_id 의 권한 가져오기
    v_profile_type := sp_get_admin_privilege_type( i_login_admin_id );

    -- 권한 체크
    IF v_profile_type IS NULL OR v_profile_type <> 'ROOT_ADMIN' THEN
      IF (EXISTS (SELECT 1 FROM tb_job AS j WHERE j.job_id = ANY(v_job_id_array) AND j.admin_id <> i_login_admin_id)) THEN
        RAISE EXCEPTION 'You do not have permission.(%)', ARRAY_TO_STRING(i_task_id::text[], ',') USING HINT = 'DB-00022';
      END IF;
    END IF;

    -- 예약작업인지 체크
    IF (EXISTS (SELECT 1 FROM tb_job AS j WHERE j.job_id = ANY(v_job_id_array) AND j.is_schedule = true)) THEN
      RAISE EXCEPTION 'You can not retry a schedule operation.(%)', ARRAY_TO_STRING(i_task_id::text[], ',') USING HINT = 'DB-00023';
    END IF;

    -- 연계규칙인지 체크
    IF (EXISTS (SELECT 1 FROM tb_job AS j WHERE j.job_id = ANY(v_job_id_array) AND j.correlation_rule_id > 0)) THEN
      RAISE EXCEPTION 'You can not retry a correlation task.(%)', ARRAY_TO_STRING(i_task_id::text[], ',') USING HINT = 'DB-00024';
    END IF;

    IF i_check_type <> 'CANCEL' THEN
      -- 대응 기간 체크
      SELECT c.value::integer INTO v_response_retry_interval
      FROM tb_config AS c
      WHERE c.config_group = 'SYS_INFO'
        AND c.key = 'response_retry_interval';

      IF (EXISTS (SELECT 1 FROM tb_task AS t WHERE t.task_id = ANY(i_task_id) AND (now()::date - t.modified_time::date) > v_response_retry_interval)) THEN
        RAISE EXCEPTION 'You can not retry the operation of a response period.(%)', ARRAY_TO_STRING(i_task_id::text[], ',') USING HINT = 'DB-00025';
      END IF;
    END IF;
  END IF;

END;
$$;


