--
-- Name: sp_clean_empty_group(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_clean_empty_group() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_group_id BIGINT[];
BEGIN

  SELECT
    ARRAY_AGG(tot.group_id) INTO v_group_id
  FROM
    (
      WITH RECURSIVE group_list (group_id, group_type, name, is_removed, grp_path, agent_cnt)
      AS (
        SELECT
          g.group_id
          , g.group_type
          , g.name
          , g.is_removed
          , ARRAY[g.group_id]
          , (SELECT COUNT(*) FROM tb_node n WHERE n.group_id = (SELECT sg.group_id FROM tb_group sg WHERE sg.group_type = 'DEFAULT') AND n.is_removed IS FALSE AND n.platform_id IS NOT NULL)
        FROM
          tb_group g
        WHERE
          g.group_type = 'TOP'
        UNION ALL
        SELECT
          g.group_id
          , g.group_type
          , g.name
          , g.is_removed
          , gl.grp_path || g.group_id
          , COALESCE(n.agent_cnt, 0)
        FROM
          tb_group g
          JOIN group_list gl ON g.pgroup_id = gl.group_id
          LEFT JOIN (
            SELECT
              COUNT(*) AS agent_cnt ,n.group_id
            FROM
              tb_node n
            WHERE
              n.is_removed IS FALSE
              AND n.platform_id IS NOT NULL
            GROUP BY
              n.group_id) n ON g.group_id = n.group_id
      )
      SELECT
        gl.group_id AS group_id
        , gl.group_type AS group_type
        , gl.name AS name
        , gls.agent_cnt AS agent_cnt
      FROM
        group_list gl
        JOIN (
          SELECT
            UNNEST(gls.grp_path) AS grp_path
            , SUM(gls.agent_cnt) AS agent_cnt
          FROM
            group_list gls
          GROUP BY
            UNNEST(gls.grp_path)
        ) gls ON gl.group_id = gls.grp_path
    ) tot
  WHERE
    tot.agent_cnt = 0
    AND tot.group_type = 'GENERAL'
    AND
      NOT EXISTS (SELECT 1 FROM tb_group WHERE group_id = tot.group_id AND "name" = '%DEFAULT_RISK_GROUP_NAME%')
  ;

  UPDATE
    tb_group
  SET
    is_removed = TRUE
  WHERE
    group_id = ANY(v_group_id);

END;
$$;


ALTER FUNCTION public.sp_clean_empty_group() OWNER TO cppoltp;

