--
-- Name: sp_cleanup_db(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_cleanup_db() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_db_old_log_date           timestamp;
  v_db_delete_date            timestamp;
BEGIN
    SELECT log_time INTO v_db_old_log_date FROM tb_server_resource ORDER BY log_time LIMIT 1;

    IF ( v_db_old_log_date < current_date - 90 ) THEN
      SELECT timetable.log_time INTO v_db_delete_date
      FROM ( SELECT log_time FROM tb_server_resource ORDER BY log_time LIMIT (SELECT count(*)/10 FROM tb_server_resource) ) AS timetable
      ORDER BY timetable.log_time DESC LIMIT 1;

      DELETE FROM tb_server_resource WHERE log_time < v_db_delete_date;
      DELETE FROM tb_task_target_status WHERE server_time < v_db_delete_date;
    END IF;
END;
$$;


ALTER FUNCTION public.sp_cleanup_db() OWNER TO cppoltp;

--
-- Name: sp_create_appkey(character varying, character varying, character varying, timestamp without time zone, bigint, character varying, public.en_db_type, character varying, character varying, public.en_supply_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_create_appkey(i_app_type character varying, i_app_id character varying, i_app_key character varying, i_expire_date timestamp without time zone, i_session_timeout bigint, i_connect_ip character varying, i_db_type public.en_db_type, i_query character varying, i_description character varying, i_supply_type public.en_supply_type) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
  IF (i_app_type = 'INTERNAL' ) THEN
    IF (SELECT EXISTS (SELECT 1 FROM tb_application_auth WHERE app_type = 'INTERNAL' and app_id = i_app_id)) THEN
      UPDATE tb_application_auth
        SET app_key = i_app_key, modified_time = now()
      WHERE app_type = 'INTERNAL' and app_id = i_app_id;
    ELSE
    END IF;
  ELSE
    IF (SELECT EXISTS (SELECT 1 FROM tb_application_auth WHERE app_type = 'EXTERNAL' and app_id = i_app_id)) THEN
      UPDATE tb_application_auth
        SET app_key = i_app_key, to_date = i_expire_date, expire_time = i_session_timeout, connect_ipaddr = COALESCE(NULLIF(i_connect_ip,''),'{}')::text[],
        db_type = i_db_type, query = i_query, description = i_description, supply_type = i_supply_type, modified_time = now()
      WHERE app_type = 'EXTERNAL' and app_id = i_app_id;
    ELSE
      VALUES (i_app_id, i_app_key, 'EXTERNAL', now(), i_expire_date, i_session_timeout, COALESCE(NULLIF(i_connect_ip,''),'{}')::text[], i_db_type, i_query, i_description, i_supply_type, now());
    END IF;
  END IF;
END;
$$;


