--
-- Name: sp_del_db_mgmt(public.en_db_mgmt_type, public.en_db_type, character varying, character varying); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_del_db_mgmt(i_db_mgmt_type public.en_db_mgmt_type, i_db_type public.en_db_type, i_server_ip character varying, i_file_path character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_server_id bigint;
BEGIN
  select server_id into v_server_id from tb_server where tb_server.ip = i_server_ip;

  IF( v_server_id IS NOT NULL ) THEN
    IF( i_db_mgmt_type = 'BACKUP' ) THEN
      DELETE FROM tb_db_mgmt where db_mgmt_type = 'BACKUP' and db_type = i_db_type and server_id = v_server_id and file_path = i_file_path;
    END IF;
  END IF;

END;
$$;


ALTER FUNCTION public.sp_del_db_mgmt(i_db_mgmt_type public.en_db_mgmt_type, i_db_type public.en_db_type, i_server_ip character varying, i_file_path character varying) OWNER TO cppoltp;

