--
-- Name: sp_exist_license(public.en_product_group_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_exist_license(i_product_group public.en_product_group_type) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_result                    boolean;
BEGIN

  SELECT COUNT(1) > 0 INTO v_result
  FROM tb_product AS p
  JOIN tb_product_license AS pl ON p.product_id = pl.product_id AND pl.expire_date IS NOT NULL
  WHERE p.product_group = i_product_group;

  RETURN v_result;

END;
$$;


ALTER FUNCTION public.sp_exist_license(i_product_group public.en_product_group_type) OWNER TO cppoltp;

--
-- Name: sp_exist_product_license(public.en_product_id_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_exist_product_license(i_product_id public.en_product_id_type) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_result                    boolean;
BEGIN

  SELECT COUNT(1) > 0 INTO v_result
  FROM tb_product p
  JOIN tb_product_license pl ON p.product_id = pl.product_id AND pl.expire_date IS NOT NULL
  WHERE p.product_id = CASE WHEN i_product_id = 'AGENT' THEN 'EMS' ELSE i_product_id END;

  RETURN v_result;

END;
$$;


ALTER FUNCTION public.sp_exist_product_license(i_product_id public.en_product_id_type) OWNER TO cppoltp;

