--
-- Name: sp_get_ac_agent_policy_detail(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_ac_agent_policy_detail(i_policy_id bigint) RETURNS TABLE(product_feature_id public.en_product_feature_id_type, product_feature_name text, policy_id bigint, policy_name text, description text, policy_type public.en_policy_type, online_policy_body text, offline_policy_body text, use_offline_policy text, hash text, modified_time timestamp without time zone, group_id_array bigint[])
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_product_feature_id en_product_feature_id_type;

BEGIN

SELECT p.product_feature_id
INTO v_product_feature_id
FROM tb_policy p
WHERE p.policy_id = i_policy_id;

IF v_product_feature_id IS NULL THEN

  RAISE EXCEPTION 'policy_id (%) does not exist.', i_policy_id USING HINT = 'DB-00031';

ELSIF v_product_feature_id <> 'AC_AGENT' THEN

  RAISE EXCEPTION 'policy_id (%) is not AC_AGENT policy.', i_policy_id USING HINT = 'DB-00030';

END IF;

RETURN QUERY

--정책 상세
SELECT p.product_feature_id AS product_feature_id
      ,p.product_feature_name AS product_feature_name
      ,p.policy_id AS policy_id
      ,p.policy_name AS policy_name
      ,p.description AS description
      ,p.policy_type AS policy_type
      ,p.online_policy_body AS online_policy_body
      ,p.offline_policy_body AS offline_policy_body
      ,p.use_offline_policy AS use_offline_policy
      ,p.hash AS hash
      ,p.modified_time AS modified_time
      ,p.group_id_array AS group_id_array
FROM sp_get_policy_detail(i_policy_id) p
;

END;
$$;


ALTER FUNCTION public.sp_get_ac_agent_policy_detail(i_policy_id bigint) OWNER TO cppoltp;

