--
-- Name: sp_get_ac_status(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_ac_status() RETURNS TABLE(product_id public.en_product_id_type, os_type text, status public.en_ac_operation_status, count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
  RETURN QUERY
  SELECT
    tas.product_id
		, CASE
			WHEN tn.platform_id::text = 'UNKNOWN' THEN 'etc'
			WHEN tn.platform_id::text LIKE '%WINDOWS%' THEN 'WINDOWS'
			ELSE 'LINUX_UNIX'
		END AS os_type
		, tas.ac_status AS status
		, COUNT(*)
	FROM
		tb_ac_status tas
	INNER JOIN
		tb_node tn
	ON
		tas.node_id = tn.node_id
	AND
		tn.is_removed IS FALSE
	GROUP BY
		tas.product_id, tas.ac_status, os_type;

END;
$$;


ALTER FUNCTION public.sp_get_ac_status() OWNER TO cppoltp;

--
-- Name: sp_get_action_map(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_action_map(i_service_target text) RETURNS TABLE(action_name text, revision integer, procedure text, db_type public.en_db_type, db_method public.en_db_method)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
    SELECT
      m.action_name, m.revision, m.procedure, m.db_type, m.db_method
    FROM
      tb_action_map m
    WHERE
      CASE WHEN i_service_target IS NULL OR i_service_target = 'ALL' THEN TRUE
      ELSE service_target = i_service_target::en_service_target END
    ;
END;
$$;


ALTER FUNCTION public.sp_get_action_map(i_service_target text) OWNER TO cppoltp;

--
-- Name: sp_get_action_map_audit_log(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_action_map_audit_log() RETURNS TABLE(sp_name text, action_name text, revision integer, audit_target text, audit_type text, audit_include_data text, db_type public.en_db_type, db_method public.en_db_method)
    LANGUAGE plpgsql
    AS $$
BEGIN
RETURN QUERY
	SELECT
		(CASE WHEN (tam.db_type = 'OLTP')
		THEN substring(PROCEDURE from 0 for position('(' in PROCEDURE))
		ELSE PROCEDURE END) AS sp_name
		, tam.action_name
		, tam.revision
		, tam.audit_target::TEXT
		, tam.audit_type::TEXT
		, tam.audit_include_data::TEXT
		, tam.db_type
		, tam.db_method
	FROM tb_action_map tam
	WHERE tam.db_type = 'OLTP'
	  AND tam.audit_target = TRUE
	UNION ALL
	SELECT
		substring(tam.procedure from position('sp_' in tam.procedure) for (position('(' in PROCEDURE) - position('sp_' in tam.procedure))) AS sp_name
		, tam.action_name
		, tam.revision
		, tam.audit_target::TEXT
		, tam.audit_type::TEXT
		, tam.audit_include_data::TEXT
		, tam.db_type
		, tam.db_method
	FROM tb_action_map tam
	WHERE tam.db_type NOT IN ('OLTP', 'NONE')
	  AND tam.procedure LIKE '%sp\_%'
	  AND tam.audit_target = TRUE;
END;
$$;


ALTER FUNCTION public.sp_get_action_map_audit_log() OWNER TO cppoltp;

