    LANGUAGE plpgsql
    AS $$
BEGIN
RETURN QUERY
SELECT am.action_name, am.revision::text, am.procedure, am.db_type::text, am.db_method::text, am.check_target::text, amf.feature_name, am.product_group::text, am.read_only::text, amf.uri
FROM tb_action_map am JOIN tb_action_map_feature amf
ON am.action_name = amf.action_name AND am.revision = amf.revision;

END;
$$;


