--
-- Name: sp_get_action_map_procedure(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_action_map_procedure(i_action_name text) RETURNS TABLE(procedure text)
    LANGUAGE plpgsql
    AS $$
BEGIN

  RETURN QUERY
  SELECT m.procedure
  FROM tb_action_map m
  WHERE m.action_name = i_action_name;

END;
$$;


ALTER FUNCTION public.sp_get_action_map_procedure(i_action_name text) OWNER TO cppoltp;

--
-- Name: sp_get_action_revision(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_action_revision() RETURNS TABLE(action text, revision integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT t.action_name, t.revision
    FROM (
      SELECT am.action_name, am.revision, ROW_number() over (partition BY am.action_name ORDER BY am.revision DESC) row_num
      FROM tb_action_map am
      WHERE am.service_target = 'AGENT'
    ) t
    WHERE t.row_num = 1;

END;
$$;


