--
-- Name: sp_get_admin(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_admin(i_admin_id text) RETURNS TABLE(name text, privilege_profile_id bigint, product_auth text, admin_group text, pw_due integer, connect_ip_range text, connect_dofw text, connect_time_start text, connect_time_end text, timeout_value integer, auth_wait_time integer, computer_name text, email text, phone text, use_otp text, dashboard_layout text, description text, connect_ipaddr inet, use_connect_ip boolean, manager_group_id bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT
      a.name                                      /* 관리자 이름 */
      , a.privilege_profile_id                    /* 권한 코드 ID */
      , a.product_auth
      , a.admin_group                             /* 사용자 그룹 */
      , a.pw_due                                  /* 패스워드 만료 기간 */
      , a.connect_ip_range                        /* 접속 가능 IP 주소 범위 */
      , a.connect_dofw                            /* 접속 가능 요일 */
      , a.connect_time_start                      /* 접속 가능 시작 시간 */
      , a.connect_time_end                        /* 접속 가능 종료 시간 */
      , a.timeout_value                           /* 접속 Timeout 시간 */
      , a.auth_wait_time                          /* 로그인 인증 보류 시간 */
      , a.computer_name                           /* 관리자 컴퓨터 이름 */
      , a.email                                   /* 관리자 Email */
      , a.phone                                   /* 관리자 핸드폰 */
      , a.use_otp::text                           /* 사용여부 */
      , a.dashboard_layout                        /* 대시보드 레이아웃 */
      , a.description                             /* 설명 */
      , a.connect_ipaddr                          /* 접속 IP 주소 */
      , COALESCE(a.use_connect_ip,TRUE)::BOOLEAN AS use_connect_ip  /* 로그인 허용 IP 제한 사용 여부 */
      , a.manager_group_id
    FROM
      tb_admin AS a
    WHERE
      a.admin_id = i_admin_id;

END;
$$;


