CREATE FUNCTION public.sp_get_admin_cache(i_admin_id text) RETURNS TABLE(password text, profile_type public.en_privilege_profile_type, privilege_profile_id bigint, product_auth text, admin_group text, pw_due integer, connect_ip_range text, connect_dofw text, connect_time_start text, connect_time_end text, timeout_value integer, auth_wait_time integer, use_otp text, email text, cnapp_k8s_info text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT
      a.password
      , p.profile_type
      , a.privilege_profile_id                    /* 권한 코드 ID */
      , a.product_auth
      , a.admin_group                             /* 사용자 그룹 */
      , a.pw_due                                  /* 패스워드 만료 기간 */
      , a.connect_ip_range                        /* 접속 가능 IP 주소 범위 */
      , a.connect_dofw                            /* 접속 가능 요일 */
      , a.connect_time_start                      /* 접속 가능 시작 시간 */
      , a.connect_time_end                        /* 접속 가능 종료 시간 */
      , a.timeout_value                           /* 접속 Timeout 시간 */
      , a.auth_wait_time                          /* 로그인 인증 보류 시간 */
      , a.use_otp::text                           /* 사용여부 */
      , a.email                                   /* E-Mail */
      , sp_base64_decode(tmg.cnapp_k8s_info) AS cnapp_k8s_info          /* CNAPP의 클러스터, 네임스페이스 json 정보 */
    FROM tb_admin AS a
    JOIN tb_privilege_profile AS p ON a.privilege_profile_id = p.privilege_profile_id
    LEFT JOIN tb_manager_group AS tmg ON tmg.group_id = a.manager_group_id
    WHERE a.admin_id = i_admin_id;

END;
$$;


