--

CREATE FUNCTION public.sp_get_admin_ip(i_admin_id text, i_connect_ipaddr text) RETURNS TABLE(value text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT (COUNT(1) > 0)::text
    FROM tb_admin AS a
    WHERE a.admin_id = i_admin_id
      AND STRING_TO_ARRAY(a.connect_ipaddr, ',') = any(array[i_connect_ipaddr]);

END;
$$;


