--
-- Name: sp_get_admin_list(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_admin_list(i_login_admin_id text) RETURNS TABLE(profile_type public.en_privilege_profile_type, profile_name text, manager_group_name text, admin_id text, name text, email text, description text, login_time timestamp without time zone, lock_status boolean, lock_type text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_profile_type              en_privilege_profile_type;
  v_product_auth              en_product_group_type[];
  v_profile_type_array        en_privilege_profile_type[] := ARRAY['SECMGR_ADMIN']::en_privilege_profile_type[];
BEGIN

  -- login_admin_id 의 권한 가져오기
  v_profile_type := sp_get_admin_privilege_type( i_login_admin_id );

  IF v_profile_type = 'ROOT_ADMIN' THEN
    RETURN QUERY
      SELECT
        p.profile_type
        , CASE WHEN p.profile_type = 'CUSTOM_ADMIN' THEN p.profile_name ELSE '' END AS profile_name
        , CASE WHEN p.profile_type = 'CUSTOM_ADMIN' AND m.name IS NOT NULL THEN m.name ELSE '' END AS manager_group_name
        , a.admin_id
        , a.name
        , a.email
        , a.description
		    , a.login_time
        , COALESCE(a.lock_status, false) AS lock_status
        , COALESCE(a.lock_type, '') AS lock_type
      FROM tb_admin AS a
      JOIN tb_privilege_profile AS p ON a.privilege_profile_id = p.privilege_profile_id
      LEFT JOIN tb_manager_group AS m ON a.manager_group_id = m.group_id;
  ELSIF v_profile_type = 'PRODUCT_ADMIN' THEN
    SELECT STRING_TO_ARRAY(REPLACE(a.product_auth, ' ', ''), ',')::en_product_group_type[] INTO v_product_auth
    FROM tb_admin a WHERE a.admin_id = i_login_admin_id;

    RETURN QUERY
      SELECT
        p.profile_type
        , CASE WHEN p.profile_type = 'CUSTOM_ADMIN' THEN p.profile_name ELSE '' END AS profile_name
        , CASE WHEN p.profile_type = 'CUSTOM_ADMIN' AND m.name IS NOT NULL THEN m.name ELSE '' END AS manager_group_name
        , a.admin_id
        , a.name
        , a.email
        , a.description
		    , a.login_time
        , COALESCE(a.lock_status, false) AS lock_status
        , COALESCE(a.lock_type, '') AS lock_type
      FROM tb_admin AS a
      JOIN tb_privilege_profile AS p ON a.privilege_profile_id = p.privilege_profile_id
      LEFT JOIN tb_manager_group AS m ON a.manager_group_id = m.group_id
      WHERE (a.admin_id = i_login_admin_id OR p.profile_type = ANY(v_profile_type_array));
  ELSE
    RETURN QUERY
      SELECT
        p.profile_type
        , CASE WHEN p.profile_type = 'CUSTOM_ADMIN' THEN p.profile_name ELSE '' END AS profile_name
        , CASE WHEN p.profile_type = 'CUSTOM_ADMIN' AND m.name IS NOT NULL THEN m.name ELSE '' END AS manager_group_name
        , a.admin_id
        , a.name
        , a.email
        , a.description
		    , a.login_time
        , COALESCE(a.lock_status, false) AS lock_status
        , COALESCE(a.lock_type, '') AS lock_type
      FROM tb_admin AS a
      JOIN tb_privilege_profile AS p ON a.privilege_profile_id = p.privilege_profile_id
      LEFT JOIN tb_manager_group AS m ON a.manager_group_id = m.group_id
      WHERE a.admin_id = i_login_admin_id;
  END IF;

END;
$$;


ALTER FUNCTION public.sp_get_admin_list(i_login_admin_id text) OWNER TO cppoltp;

