    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT
      l.admin_id
    FROM tb_login_status AS l
    WHERE EXISTS (
      SELECT 1 FROM UNNEST(i_admin_id) AS t(admin_id) WHERE t.admin_id = l.admin_id
    );

END;
$$;


