--
-- Name: sp_get_admin_privilege_profile_list(text, public.en_privilege_profile_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_admin_privilege_profile_list(i_login_admin_id text, i_profile_type public.en_privilege_profile_type) RETURNS TABLE(profile_type public.en_privilege_profile_type, profile_name text, privilege_profile_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  IF i_profile_type IS NULL THEN

    RETURN QUERY
      SELECT
        t.profile_type
        , null::text
        , p.privilege_profile_id::text
      FROM UNNEST(ENUM_RANGE(null::en_privilege_profile_type)) AS t(profile_type)
      LEFT JOIN (
        SELECT
          p.profile_type
          , MIN(p.privilege_profile_id) AS privilege_profile_id
        FROM tb_privilege_profile AS p
        GROUP BY p.profile_type
      ) AS p ON t.profile_type = p.profile_type
      WHERE t.profile_type <> 'TEMP_ADMIN'
      ORDER BY 3;

  ELSE

    RETURN QUERY
      SELECT
        p.profile_type
        , p.profile_name
        , p.privilege_profile_id::text
      FROM tb_privilege_profile AS p
      WHERE p.profile_type = i_profile_type
      ORDER BY p.profile_name;

  END IF;

END;
$$;


