--
-- Name: sp_get_admin_pw_list(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_admin_pw_list(i_admin_id text) RETURNS TABLE(type text, password text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT a.type, a.password
    FROM (
      SELECT 1 AS seq, 'CURRENT' AS type, a.password FROM tb_admin AS a WHERE a.admin_id = i_admin_id
      UNION ALL
      SELECT (ROW_NUMBER() over(ORDER BY a.time DESC)) + 10 AS seq, 'HISTORY' AS type, a.password FROM tb_admin_pw_history AS a WHERE a.admin_id = i_admin_id
    ) a
    ORDER BY a.seq LIMIT 3;

END;
$$;


