--
-- Name: sp_get_admin_pwd(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_admin_pwd(i_admin_id text) RETURNS TABLE(admin_id text, name text, password text, pw_due integer, connect_ip_range text, connect_dofw text, connect_time_start text, connect_time_end text, timeout_value integer, auth_wait_time integer, privilege_profile_id bigint, profile_type public.en_privilege_profile_type, profile_body text, computer_name text, connect_ipaddr text, login_time timestamp without time zone, logout_time timestamp without time zone, admin_group text, pw_modify_time timestamp without time zone, email text, phone text, dashboard_layout text, modified_time timestamp without time zone, description text, use_otp boolean, product_auth text, use_connect_ip text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT
      a.admin_id        /*관리자 ID*/
      ,a.name         /*관리자 이름 */
      ,a.password       /*관리자 패스워드 */
      ,a.pw_due       /*패스워드 만료 기간 */
      ,a.connect_ip_range   /*접속 가능 IP 주소 범위 */
      ,a.connect_dofw     /*접속 가능 요일 */
      ,a.connect_time_start /*접속 가능 시작 시간 */
      ,a.connect_time_end   /*접속 가능 종료 시간 */
      ,a.timeout_value      /*접속 Timeout 시간  */
      ,a.auth_wait_time   /*로그인 인증 보류 시간 */
      ,a.privilege_profile_id /*권한 코드 ID */
      , (SELECT tpp.profile_type FROM tb_privilege_profile tpp WHERE tpp.privilege_profile_id = a.privilege_profile_id) AS profile_type /*권한 TYPE */
      , (SELECT tpp.profile_body FROM tb_privilege_profile tpp WHERE tpp.privilege_profile_id = a.privilege_profile_id) AS profile_body /*권한 BODY */
      ,a.computer_name      /*관리자 컴퓨터 이름 */
      ,a.connect_ipaddr::text   /*접속 IP 주소 */
      ,a.login_time     /*로그인 시간 */
      ,a.logout_time      /*로그 아웃 시간 */
      ,a.admin_group      /*관리 대상 그룹 */
      ,a.pw_modify_time   /*비밀번호 변경 시간 */
      ,a.email          /*관리자 Email */
      ,a.phone          /*관리자 핸드폰 */
      ,a.dashboard_layout   /*대시보드 레이아웃 */
      ,a.modified_time      /*데이터 갱신 최종 시간 */
      ,a.description      /*설명 */
      ,a.use_otp        /*OTP 사용여부 */
      ,a.product_auth     /*제품 권한 */
      ,COALESCE(a.use_connect_ip,TRUE)::TEXT AS use_connect_ip /* 로그인 허용 IP 제한 사용여부 */
    FROM
      tb_admin AS a
    WHERE
      a.admin_id = i_admin_id;

END;
$$;


