-- Name: sp_get_agent_ac_status_link_list(bigint[], text, text, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_ac_status_link_list(i_node_id_arr bigint[], i_filter_json text, i_product_auth text, i_dashboard_layout text, i_admin_group text) RETURNS TABLE(node_id bigint, connection_status public.en_connection_status, ac_status text, product_version text, engine_version text, ckl_version text, service_status text, engine_state text, im_enable text, im_enable_real_time text, im_engine_version text, im_manual_time text, license_code text, ac_agent_policy_name text, ac_agent_policy_status text, ac_mgmt_policy_name text, ac_mgmt_policy_status text, im_mgmt_policy_name text, im_mgmt_policy_status text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_node_id_arr bigint[];

BEGIN
    v_node_id_arr := sp_get_agent_status_filter(i_node_id_arr, i_filter_json, i_product_auth, i_dashboard_layout, i_admin_group);

    RETURN QUERY
    SELECT
        node.node_id AS node_id -- 노드 아이디
      , COALESCE(node_status.connection_status, 'UNINSTALLED') AS connection_status -- 노드 연결 상태    
      , CASE 
          WHEN node.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS FALSE THEN 'UNSUPPORTED'
          WHEN product_info.product_id IS NULL THEN 'NONE'
          ELSE ac_status.ac_status::TEXT
        END AS ac_status -- AC 상태
      , CASE 
          WHEN product_info.product_id IS NULL THEN ''
          ELSE ac_status.product_version 
        END AS product_version -- AC 버전
      , CASE 
          WHEN product_info.product_id IS NULL THEN ''
          ELSE ac_status.engine_version 
        END AS engine_version -- AC 제품 버전
      , CASE 
          WHEN product_info.product_id IS NULL THEN ''
          ELSE ac_status.ckl_version 
        END AS ckl_version -- 커널패키지 버전
      , CASE WHEN product_info.product_id IS NULL THEN
            'NOT_INSTALLED'
        ELSE COALESCE(ac_status.service_status::TEXT, 'NOT_INSTALLED') END AS service_status -- AC 서비스 상태
      , CASE 
          WHEN product_info.product_id IS NULL THEN ''
          ELSE ac_status.engine_state::TEXT 
        END AS engine_state
      , CASE 
          WHEN product_info.product_id IS NULL THEN ''
          ELSE ac_status.im_enable::TEXT 
        END AS im_enable
      , CASE 
          WHEN product_info.product_id IS NULL THEN ''
          ELSE ac_status.im_enable_real_time::TEXT 
        END AS im_enable_real_time
      , CASE 
          WHEN product_info.product_id IS NULL THEN ''
          ELSE ac_status.im_engine_version::TEXT 
        END AS im_engine_version 
      , CASE
          WHEN product_info.product_id IS NULL THEN ''
          ELSE 
            CASE
              WHEN ac_status.im_manual_time IS NULL THEN ''
              ELSE TO_CHAR(ac_status.im_manual_time::TIMESTAMP + (INTERVAL '1 HOURS' * ac_status.tz_offset), 'YYYY-MM-DD HH24:MI:SS')
            END
        END AS im_manual_time
      , CASE
          WHEN product_info.product_id IS NULL THEN ''
          WHEN ac_status.activation_code IS NOT NULL AND ac_status.activation_code != '' THEN ac_status.activation_code 
          WHEN ac_status.license_no IS NOT NULL AND ac_status.license_no != '' THEN ac_status.license_no
          ELSE NULL
          END AS license_code
      , ac_agent_policy.policy_name AS ac_agent_policy_name
      , CASE WHEN node.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS FALSE THEN 'UNSUPPORTED'::text
             ELSE ac_agent_policy.policy_status::text
             END AS ac_agent_policy_status
      , ac_mgmt_policy.policy_name AS ac_mgmt_policy_name
      , CASE WHEN node.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS FALSE THEN 'UNSUPPORTED'::text
             ELSE ac_mgmt_policy.policy_status::text
             END AS ac_mgmt_policy_status
      , im_mgmt_policy.policy_name AS im_mgmt_policy_name
      , CASE WHEN node.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS FALSE THEN 'UNSUPPORTED'::text
             ELSE im_mgmt_policy.policy_status::text
             END AS im_mgmt_policy_status
      FROM
      tb_node node
      LEFT JOIN tb_node_status node_status ON node_status.node_id = node.node_id
      LEFT JOIN tb_product_info product_info ON product_info.node_id = node.node_id AND product_info.product_id = 'AC_CLIENT'
      LEFT JOIN tb_ac_status ac_status ON ac_status.node_id = node.node_id
      LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = node.container_service_type
      LEFT JOIN (
          SELECT
            tpi.node_id AS node_id
            , tp.name AS policy_name
            , COALESCE(tps.policy_status, 'APPLYING') AS policy_status
          FROM tb_product_info tpi
          INNER JOIN tb_product p ON p.product_id = tpi.product_id AND p.product_group = 'AC'
          INNER JOIN tb_product_feature_map tpfm ON tpfm.product_id = p.product_id AND tpfm.product_feature_id = 'AC_AGENT'
          INNER JOIN tb_node tn ON tpi.node_id = tn.node_id AND tn.is_removed IS FALSE
          LEFT JOIN tb_node_policy tnp ON tnp.node_id = tpi.node_id AND tnp.product_feature_id = 'AC_AGENT'
          LEFT JOIN tb_policy tp ON tnp.policy_id = tp.policy_id AND tnp.product_feature_id = tp.product_feature_id
          LEFT JOIN tb_policy_status tps ON tps.node_id = tpi.node_id AND tps.product_feature_id = 'AC_AGENT' 
      ) AS ac_agent_policy
      ON node.node_id = ac_agent_policy.node_id
      LEFT JOIN (
          SELECT
            tpi.node_id AS node_id
            , tp.name AS policy_name
            , COALESCE(tps.policy_status, 'APPLYING') AS policy_status
          FROM tb_product_info tpi
          INNER JOIN tb_product p ON p.product_id = tpi.product_id AND p.product_group = 'AC'
          INNER JOIN tb_product_feature_map tpfm ON tpfm.product_id = p.product_id AND tpfm.product_feature_id = 'AC_MGMT'
          INNER JOIN tb_node tn ON tpi.node_id = tn.node_id AND tn.is_removed IS FALSE
          LEFT JOIN tb_node_policy tnp ON tnp.node_id = tpi.node_id AND tnp.product_feature_id = 'AC_MGMT'
          LEFT JOIN tb_policy tp ON tnp.policy_id = tp.policy_id AND tnp.product_feature_id = tp.product_feature_id
          LEFT JOIN tb_policy_status tps ON tps.node_id = tpi.node_id AND tps.product_feature_id = 'AC_MGMT' 
      ) AS ac_mgmt_policy
      ON node.node_id = ac_mgmt_policy.node_id
      LEFT JOIN (
          SELECT
            tpi.node_id AS node_id
            , tp.name AS policy_name
            , COALESCE(tps.policy_status, 'APPLYING') AS policy_status
          FROM tb_product_info tpi
          INNER JOIN tb_product p ON p.product_id = tpi.product_id AND p.product_group = 'AC'
          INNER JOIN tb_product_feature_map tpfm ON tpfm.product_id = p.product_id AND tpfm.product_feature_id = 'IM_MGMT'
          INNER JOIN tb_node tn ON tpi.node_id = tn.node_id AND tn.is_removed IS FALSE
          LEFT JOIN tb_node_policy tnp ON tnp.node_id = tpi.node_id AND tnp.product_feature_id = 'IM_MGMT'
          LEFT JOIN tb_policy tp ON tnp.policy_id = tp.policy_id AND tnp.product_feature_id = tp.product_feature_id
          LEFT JOIN tb_policy_status tps ON tps.node_id = tpi.node_id AND tps.product_feature_id = 'IM_MGMT' 
      ) AS im_mgmt_policy
      ON node.node_id = im_mgmt_policy.node_id
    WHERE
        node.node_id = ANY(v_node_id_arr)
        AND node.is_removed IS FALSE
    ORDER BY
      node.node_id DESC
      ;
END;
$$;


ALTER FUNCTION public.sp_get_agent_ac_status_link_list(i_node_id_arr bigint[], i_filter_json text, i_product_auth text, i_dashboard_layout text, i_admin_group text) OWNER TO cppoltp;

