--
-- Name: sp_get_agent_applied_policy(bigint[], public.en_product_feature_id_type[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_applied_policy(i_node_id bigint[], i_product_feature_id public.en_product_feature_id_type[]) RETURNS TABLE(node_id text, product_feature_id text, policy_id text)
    LANGUAGE plpgsql
    AS $$
BEGIN

  RETURN QUERY
  SELECT array_agg(np.node_id)::text AS node_id
        ,np.product_feature_id::text AS product_feature_id
        ,np.policy_id::text AS policy_id
  FROM tb_node_policy np
  WHERE np.node_id IN (SELECT * FROM unnest(i_node_id))
    AND np.product_feature_id IN (SELECT * FROM unnest(i_product_feature_id))
  GROUP BY
        np.product_feature_id
       ,np.policy_id;

END;
$$;


ALTER FUNCTION public.sp_get_agent_applied_policy(i_node_id bigint[], i_product_feature_id public.en_product_feature_id_type[]) OWNER TO cppoltp;

--
-- Name: sp_get_agent_command(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_command(i_node_id bigint, i_task_id bigint[]) RETURNS TABLE(request_format_version text, request_from text, request_name text, interface_id bigint, task_encoding text, task text)
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_set_server_count bigint;
  v_machine_uuid text;
  v_machine_type en_machine_type;

BEGIN

  -- 통신서버 변경
  SELECT count(t.task_id)
  INTO v_set_server_count
  FROM tb_task t
  JOIN tb_task_target tta
  ON t.task_id = tta.task_id
    AND tta.target_id = i_node_id
  WHERE t.task_id IN (SELECT * FROM unnest(i_task_id))
    AND t.task_type = 'SET_SERVER';

  IF v_set_server_count > 0 THEN

    SELECT machine_uuid
          ,machine_type
    INTO v_machine_uuid
        ,v_machine_type
    FROM tb_node
    WHERE node_id = i_node_id;

    PERFORM sp_unregister_node(i_node_id, v_machine_uuid, v_machine_type);

  END IF;

  -- 실시간 명령
  RETURN QUERY
  SELECT tt.request_format_version AS request_format_version
        ,tt.request_from AS request_from
        ,tt.request_name AS request_name
        ,COALESCE(tt.interface_id, '0')::BIGINT AS interface_id
        ,tt.task_encoding::text AS task_encoding
        ,tta.payload AS task
  FROM tb_task t
  JOIN tb_task_target tta
  ON t.task_id = tta.task_id
    AND tta.target_id = i_node_id
  JOIN tb_node n
  ON tta.target_id = n.node_id
  JOIN tb_task_type tt
  ON tt.task_type = t.task_type
  WHERE t.task_id IN (SELECT * FROM unnest(i_task_id))
  ORDER BY
        t.task_id
       ,t.task_order;

END;
$$;


ALTER FUNCTION public.sp_get_agent_command(i_node_id bigint, i_task_id bigint[]) OWNER TO cppoltp;

--
-- Name: sp_get_agent_command_target(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_command_target(i_node_id bigint) RETURNS TABLE(task_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_task_id text;

BEGIN

  SELECT array_agg(DISTINCT tts.task_id)::text
  INTO v_task_id
  FROM tb_task_target_status tts
  WHERE tts.target_id = i_node_id
    AND tts.task_status IN ('SENT','SENT_FAIL');

  UPDATE tb_task_target_status tts
  SET task_status = (CASE WHEN tt.update_task_result::boolean THEN 'GET' ELSE 'FINISH' END)::en_task_status
     ,product_id = 'AGENT'
  FROM tb_task_type tt
  WHERE tts.target_id = i_node_id
    AND tts.task_type = tt.task_type
    AND tts.task_status IN ('SENT','SENT_FAIL');

  RETURN QUERY
  SELECT v_task_id;

END;
$$;


ALTER FUNCTION public.sp_get_agent_command_target(i_node_id bigint) OWNER TO cppoltp;

--
-- Name: sp_get_agent_detail_hw_info(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_detail_hw_info(i_node_id bigint) RETURNS TABLE(node_id bigint, cpu text, cpu_detail text, cpu_version text, cpu_speed bigint, physical_memory bigint, virtual_memory bigint, hdd1_total bigint, hdd1_free bigint, hdd2_total bigint, hdd2_free bigint, hdd3_total bigint, hdd3_free bigint, vga_type text, vga_chipset text, vga_memory bigint, monitor_resolution text, bios_name text, bios_vendor text, os_install_time timestamp with time zone, os_version text, os_platform text, os_platform_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
  SELECT
    hw.node_id ,
    hw.cpu ,
    hw.cpu_detail ,
    hw.cpu_version ,
    hw.cpu_speed ,
    hw.physical_memory ,
    hw.virtual_memory ,
    hw.hdd1_total ,
    hw.hdd1_free ,
    hw.hdd2_total ,
    hw.hdd2_free ,
    hw.hdd3_total ,
    hw.hdd3_free ,
    hw.vga_type ,
    hw.vga_chipset ,
    hw.vga_memory ,
    hw.monitor_resolution ,
    hw.bios_name ,
    hw.bios_vendor ,
    hw.os_install_time ,
    hw.os_version ,
    hw.os_platform ,
    hw.os_platform_id
  FROM tb_node_hw hw
  WHERE hw.node_id = i_node_id
  ;

END;
$$;


ALTER FUNCTION public.sp_get_agent_detail_hw_info(i_node_id bigint) OWNER TO cppoltp;

--
-- Name: sp_get_agent_detail_sw_info(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_detail_sw_info(i_node_id bigint) RETURNS TABLE(node_id bigint, sw_name text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
  SELECT
    sw.node_id,
    sw.sw_name
  FROM tb_node_sw sw
  WHERE sw.node_id = i_node_id
    AND EXISTS (SELECT 1 FROM tb_node n WHERE n.node_id = sw.node_id AND is_removed is false)
  ;

END;
$$;


ALTER FUNCTION public.sp_get_agent_detail_sw_info(i_node_id bigint) OWNER TO cppoltp;

