--
-- Name: sp_get_agent_distribute_status(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_distribute_status(i_node_id bigint) RETURNS TABLE(distribute_type text, is_distributed boolean, update_time timestamp with time zone, result_code text, name text)
    LANGUAGE plpgsql
    AS $$
BEGIN

  RETURN QUERY

        SELECT  CASE WHEN task_id IS NULL THEN 'REAL_TIME' ELSE 'POLICY' END AS distribute_type
              , nd.is_distributed  -- 배포 결과
              , nd.client_time  -- 업데이트 시간
              , nd.result_code -- 작업결과
              , pp.name  --패키지 이름
          FROM tb_node_distribution_status nd
          JOIN tb_product_pkg pp
            ON nd.product_pkg_id::bigint = pp.product_pkg_id AND pp.is_removed is false
         WHERE nd.node_id = i_node_id
            ;

END;
$$;


ALTER FUNCTION public.sp_get_agent_distribute_status(i_node_id bigint) OWNER TO cppoltp;

--
-- Name: sp_get_agent_hips_status_link_list(bigint[], text, text, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_hips_status_link_list(i_node_id_arr bigint[], i_filter_json text, i_product_auth text, i_dashboard_layout text, i_admin_group text) RETURNS TABLE(node_id bigint, connection_status public.en_connection_status, product_version text, ips_status public.en_hips_status, fw_status public.en_fw_status, engine_version text, signature_version text, service_status text, engine_state text, ssl_inspection_status text, license_code text, hips_agent_policy_name text, hips_agent_policy_status text, hips_mgmt_policy_name text, hips_mgmt_policy_status text, hips_fw_policy_name text, hips_fw_policy_status text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_node_id_arr bigint[];

BEGIN
    v_node_id_arr := sp_get_agent_status_filter(i_node_id_arr, i_filter_json, i_product_auth, i_dashboard_layout, i_admin_group);

    RETURN QUERY
    SELECT
      node.node_id AS node_id
      , COALESCE(node_status.connection_status, 'UNINSTALLED') AS connection_status
      , CASE 
          WHEN product_info.product_id IS NULL THEN ''
          ELSE hips_status.product_version 
        END AS product_version
      , CASE 
          WHEN product_info.product_id IS NULL THEN 'NONE'
          ELSE hips_status.ips_status 
        END AS ips_status
      , CASE 
          WHEN product_info.product_id IS NULL THEN 'NONE'
          ELSE hips_status.fw_status 
        END AS fw_status
      , CASE 
          WHEN product_info.product_id IS NULL THEN ''
          ELSE hips_status.engine_version 
        END AS engine_version
      , CASE 
          WHEN product_info.product_id IS NULL THEN ''
          ELSE hips_status.signature_version 
        END AS signature_version
       , CASE WHEN product_info.product_id IS NULL THEN
             'NOT_INSTALLED'
       ELSE COALESCE(hips_status.service_status::TEXT, 'NOT_INSTALLED') END AS service_status -- HIPS 서비스 상태
      , CASE 
          WHEN product_info.product_id IS NULL THEN ''
          ELSE hips_status.engine_state::TEXT
        END AS engine_state
      , CASE
          WHEN product_info.product_id IS NULL THEN ''
          ELSE COALESCE(hips_status.ssl_inspection_running, 'SSL_OFF')
        END AS ssl_inspection_status
      , CASE
          WHEN product_info.product_id IS NULL THEN ''
          WHEN hips_status.activation_code IS NOT NULL AND hips_status.activation_code != '' THEN hips_status.activation_code 
          WHEN hips_status.license_no IS NOT NULL AND hips_status.license_no != '' THEN hips_status.license_no
          ELSE NULL
          END AS license_code
      , hips_agent_policy.policy_name AS hips_agent_policy_name
      , CASE WHEN node.machine_type = 'CONTAINER' AND tcp.is_hips_supported IS FALSE THEN 'UNSUPPORTED'::text
             ELSE hips_agent_policy.policy_status::text
             END AS hips_agent_policy_status
      , hips_mgmt_policy.policy_name AS  hips_mgmt_policy_name
      , CASE WHEN node.machine_type = 'CONTAINER' AND tcp.is_hips_supported IS FALSE THEN 'UNSUPPORTED'::text
             ELSE hips_mgmt_policy.policy_status::text
             END AS hips_mgmt_policy_status
      , hips_fw_policy.policy_name AS  hips_fw_policy_name
      , CASE WHEN node.machine_type = 'CONTAINER' AND tcp.is_hips_supported IS FALSE THEN 'UNSUPPORTED'::text
             ELSE hips_fw_policy.policy_status::text
             END AS hips_fw_policy_status
    FROM
      tb_node node
      LEFT JOIN tb_node_status node_status ON node_status.node_id = node.node_id
      LEFT JOIN tb_product_info product_info ON product_info.node_id = node.node_id AND product_info.product_id = 'HIPS_CLIENT'
      LEFT JOIN tb_hips_status hips_status ON hips_status.node_id = node.node_id
      LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = node.container_service_type
      LEFT JOIN (
          SELECT
            tpi.node_id AS node_id
            , tp.name AS policy_name
            , COALESCE(tps.policy_status, 'APPLYING') AS policy_status
          FROM tb_product_info tpi
          INNER JOIN tb_product p ON p.product_id = tpi.product_id AND p.product_group = 'HIPS'
          INNER JOIN tb_product_feature_map tpfm ON tpfm.product_id = p.product_id AND tpfm.product_feature_id = 'HIPS_AGENT'
          INNER JOIN tb_node tn ON tpi.node_id = tn.node_id AND tn.is_removed IS FALSE
          LEFT JOIN tb_node_policy tnp ON tnp.node_id = tpi.node_id AND tnp.product_feature_id = 'HIPS_AGENT'
          LEFT JOIN tb_policy tp ON tnp.policy_id = tp.policy_id AND tnp.product_feature_id = tp.product_feature_id
          LEFT JOIN tb_policy_status tps ON tps.node_id = tpi.node_id AND tps.product_feature_id = 'HIPS_AGENT' 
      ) AS hips_agent_policy
      ON node.node_id = hips_agent_policy.node_id
      LEFT JOIN (
          SELECT
            tpi.node_id AS node_id
            , tp.name AS policy_name
            , COALESCE(tps.policy_status, 'APPLYING') AS policy_status
          FROM tb_product_info tpi
          INNER JOIN tb_product p ON p.product_id = tpi.product_id AND p.product_group = 'HIPS'
          INNER JOIN tb_product_feature_map tpfm ON tpfm.product_id = p.product_id AND tpfm.product_feature_id = 'HIPS_MGMT'
          INNER JOIN tb_node tn ON tpi.node_id = tn.node_id AND tn.is_removed IS FALSE
          LEFT JOIN tb_node_policy tnp ON tnp.node_id = tpi.node_id AND tnp.product_feature_id = 'HIPS_MGMT'
          LEFT JOIN tb_policy tp ON tnp.policy_id = tp.policy_id AND tnp.product_feature_id = tp.product_feature_id
          LEFT JOIN tb_policy_status tps ON tps.node_id = tpi.node_id AND tps.product_feature_id = 'HIPS_MGMT'
      ) AS hips_mgmt_policy
      ON node.node_id = hips_mgmt_policy.node_id
      LEFT JOIN (
          SELECT
            tpi.node_id AS node_id
            , tp.name AS policy_name
            , COALESCE(tps.policy_status, 'APPLYING') AS policy_status
          FROM tb_product_info tpi
          INNER JOIN tb_product p ON p.product_id = tpi.product_id AND p.product_group = 'HIPS'
          INNER JOIN tb_product_feature_map tpfm ON tpfm.product_id = p.product_id AND tpfm.product_feature_id = 'HIPS_FW'
          INNER JOIN tb_node tn ON tpi.node_id = tn.node_id AND tn.is_removed IS FALSE
          LEFT JOIN tb_node_policy tnp ON tnp.node_id = tpi.node_id AND tnp.product_feature_id = 'HIPS_FW'
          LEFT JOIN tb_policy tp ON tnp.policy_id = tp.policy_id AND tnp.product_feature_id = tp.product_feature_id
          LEFT JOIN tb_policy_status tps ON tps.node_id = tpi.node_id AND tps.product_feature_id = 'HIPS_FW'
      ) AS hips_fw_policy
      ON node.node_id = hips_fw_policy.node_id
    WHERE
      node.node_id = ANY(v_node_id_arr)
      AND node.is_removed IS FALSE
    ORDER BY
      node.node_id desc
    ;
END;
$$;


ALTER FUNCTION public.sp_get_agent_hips_status_link_list(i_node_id_arr bigint[], i_filter_json text, i_product_auth text, i_dashboard_layout text, i_admin_group text) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_agent_hips_status_link_list(i_node_id_arr bigint[], i_filter_json text, i_product_auth text, i_dashboard_layout text, i_admin_group text); Type: COMMENT; Schema: public; Owner: cppoltp
