--
-- Name: sp_get_agent_install_page(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_install_page(i_connect_server_ip text) RETURNS TABLE(agent_install_page_link text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY

        WITH V_IS_NAT_HOST AS (
              SELECT nat.is_nat_host
              FROM (
                  SELECT FALSE AS is_nat_host
                  FROM tb_server ts
                  WHERE ts.ip = i_connect_server_ip
                  UNION
                  SELECT TRUE AS is_nat_host
                  FROM tb_server ts
                  WHERE ts.public_ip = i_connect_server_ip
              ) nat
          LIMIT 1
        )
        SELECT
          CONCAT('https://',
                          CASE WHEN (SELECT is_nat_host FROM V_IS_NAT_HOST) = TRUE
                                                                              THEN s.public_ip
                                                                              ELSE s.ip
                                                                              END
                  , ':', sp.port) :: text as agent_install_page_link
        FROM tb_server AS s
        JOIN tb_service AS v ON s.server_id = v.server_id
        JOIN tb_service_port AS sp ON v.service_type = sp.service_type
        WHERE v.enabled IS true and sp.service_type = 'LBDIST-HTTPS';
END;
$$;


ALTER FUNCTION public.sp_get_agent_install_page(i_connect_server_ip text) OWNER TO cppoltp;

