--
-- Name: sp_get_agent_installer(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_installer(i_server_id bigint) RETURNS TABLE(product_pkg_id bigint, platform public.en_platform_type, name text, description text, modified_time text, path text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
	RETURN QUERY
    SELECT
      pkg.product_pkg_id
      , CASE  WHEN pkg.pkg_type = 'WIN_AGENT_INSTALL' THEN 'WINDOWS'::en_platform_type 
        WHEN pkg.pkg_type = 'LINUX_AGENT_INSTALL' THEN 'LINUX_UNIX'::en_platform_type
        END platform
      , pkg.name
      , pkg.description
      , TO_CHAR(ps.modified_time,'YYYY.MM.DD HH24:MI:SS') AS modified_time
      , CASE WHEN taio.product_pkg_id IS NULL THEN pkg.name::text
             WHEN taio.product_pkg_id IS NOT NULL THEN taio.product_pkg_id::text
             ELSE pkg.name::text END AS path
    FROM 
      tb_product_pkg pkg
    LEFT JOIN
      tb_agent_installer_option taio
    ON
      taio.product_pkg_id = pkg.product_pkg_id
    AND
      taio.key = 'filename'
    INNER JOIN 
      tb_pkg_server ps 
    ON 
      pkg.product_pkg_id = ps.product_pkg_id
    WHERE pkg.is_removed IS FALSE
      AND pkg_type IN ('WIN_AGENT_INSTALL','LINUX_AGENT_INSTALL')
      AND ps.server_id = i_server_id
    ORDER BY
 		  pkg.product_pkg_id DESC
    ;
END;
$$;


ALTER FUNCTION public.sp_get_agent_installer(i_server_id bigint) OWNER TO cppoltp;

