--
-- Name: sp_get_agent_list(public.en_product_id_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_list(i_product_id public.en_product_id_type) RETURNS TABLE(product_pkg_id bigint, name text, pkg_type public.en_pkg_type, version text, path text, pkg_status public.en_pkg_status, product_id public.en_product_id_type, language public.en_language, description text, mpsetup_hash text, modified_time timestamp without time zone, delta_update boolean, apply_engine boolean, apply_patch boolean, server_id bigint, platform_id public.en_platform_id_type)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT
    prpk.product_pkg_id   /* 제품 패키지 타입 */
    ,prpk.name        /* 패키지 명 */
    ,prpk.pkg_type      /* 패키지 타입 */
    ,prpk.version     /* 패키지 버전 */
    ,prpk.path        /* 패키지 경로 */
    ,prpk.pkg_status    /* 패키지 상태 */
    ,prpk.product_id    /* 제품 ID */
    ,prpk.language      /* 패키지 언어 */
    ,prpk.description   /* 설명 */
    ,prpk.mpsetup_hash    /* mpsetup 해시 */
    ,prpk.modified_time   /* 변경 시각 */
    ,prpk.delta_update    /* 델타업데이트 사용 여부 */
    ,prpk.apply_engine    /* 엔진셋 적용 여부 */
    ,prpk.apply_patch   /* 패치셋 적용 여부 */
    ,prpk.server_id     /*  */
    ,pf.platform_id
    FROM
      tb_product_pkg AS prpk,
      tb_pkg_platform AS pkpf,
      tb_platform AS pf
    WHERE prpk.product_pkg_id = pkpf.product_pkg_id
      AND pf.is_supported IS TRUE
      AND pkpf.platform_id  = pf.platform_id
      AND prpk.product_id  = i_product_id
      AND prpk.is_removed is false
    ;


END;
$$;


ALTER FUNCTION public.sp_get_agent_list(i_product_id public.en_product_id_type) OWNER TO cppoltp;

--
-- Name: sp_get_agent_master(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_master() RETURNS TABLE(product_pkg_id text, name text, version text, path text, description text, install_ip text, platform_type public.en_platform_type)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
  RETURN QUERY

    SELECT
      pp.product_pkg_id::text,
      pp.name,
      pp.version,
      pp.path,
      pp.description,
      pp.install_ip::TEXT,
      pp.platform_type
    FROM tb_product_pkg pp
    WHERE pp.pkg_type IN ('WIN_AGENT_MASTER', 'LINUX_AGENT_MASTER')
    AND pp.product_id = 'AGENT'
    AND pp.pkg_status = 'SUCCESS'
    AND pp.is_removed is false
    ORDER BY pp.modified_time DESC;

END;
$$;


