CREATE FUNCTION public.sp_get_agent_master_serverlist(i_pkg_type public.en_pkg_type) RETURNS TABLE(server_id text, ip text, port text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT
      s.server_id::text
      , s.ip
      , (SELECT tsp.port::TEXT FROM tb_service_port tsp WHERE service_type = 'TOMCAT-CONSOLE')
    FROM tb_server AS s
    JOIN tb_service AS v ON s.server_id = v.server_id
    WHERE v.enabled IS TRUE
      AND v.service_type = 'FILESERVER-UPLOAD'
      AND s.server_id IN (SELECT tps.server_id
              FROM tb_product_pkg tpp
              JOIN tb_pkg_server tps ON tps.product_pkg_id = tpp.product_pkg_id
              WHERE tpp.pkg_type = i_pkg_type
                AND tpp.is_removed = FALSE);

END;
$$;


