--
-- Name: sp_get_agent_policy_applied_count(bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_policy_applied_count(i_node_id bigint[]) RETURNS TABLE(product_group public.en_product_group_type, product_feature_id public.en_product_feature_id_type, policy_status text, count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
  WITH policy_status AS (
   SELECT p.product_group, p.product_id, pfm.product_feature_id, ps.policy_status, ps.node_id
   FROM tb_policy_status ps
      LEFT JOIN tb_product_feature_map pfm ON ps.product_feature_id = pfm.product_feature_id
      JOIN tb_product p ON pfm.product_id = p.product_id
   WHERE
   	EXISTS (SELECT 1 FROM tb_node n WHERE n.node_id = ps.node_id AND n.is_removed is false)
   	AND ps.node_id = ANY(i_node_id)
  ),
  common_policy_status AS (
   SELECT ps.product_group, ps.product_feature_id, ps.policy_status, count(DISTINCT ps.node_id) AS count
   FROM policy_status ps
   WHERE ps.product_group IN ('EMS', 'AC', 'HIPS', 'SCM')
   GROUP BY ps.product_group, ps.product_feature_id, ps.policy_status
  ),
  v3_policy_status AS (
   SELECT ps.product_group, ps.product_feature_id, ps.policy_status, count(DISTINCT ps.node_id) AS count
   FROM policy_status ps
   WHERE ps.product_group = 'V3'
     AND ps.product_feature_id <> 'V3NET_LU_UPDATE'
   GROUP BY ps.product_group, ps.product_feature_id, ps.policy_status
  )
  SELECT common.product_group, common.product_feature_id, common.policy_status::text, common.count FROM common_policy_status common
  UNION ALL
  SELECT v3.product_group, v3.product_feature_id, v3.policy_status::text, v3.count FROM v3_policy_status v3
  ;

END;
$$;


ALTER FUNCTION public.sp_get_agent_policy_applied_count(i_node_id bigint[]) OWNER TO cppoltp;

--
-- Name: sp_get_agent_policy_applied_summary_info(bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_policy_applied_summary_info(i_group_id bigint[]) RETURNS TABLE(group_id bigint, each_policy_count bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

  RETURN QUERY
  SELECT g.group_id
        ,count(np.node_id)::bigint AS each_policy_count
  FROM tb_group g
  JOIN tb_node n
  ON g.group_id = n.group_id
  JOIN tb_node_policy np
  ON n.node_id = np.node_id
    AND np.keep_agent_policy = true
  WHERE g.group_id = ANY(i_group_id)
  AND n.is_removed IS FALSE
  GROUP BY g.group_id;


END;
$$;


ALTER FUNCTION public.sp_get_agent_policy_applied_summary_info(i_group_id bigint[]) OWNER TO cppoltp;

--
-- Name: sp_get_agent_policy_detail(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_policy_detail(i_policy_id bigint) RETURNS TABLE(product_feature_id public.en_product_feature_id_type, product_feature_name text, policy_id bigint, policy_name text, description text, policy_type public.en_policy_type, online_policy_body text, offline_policy_body text, use_offline_policy text, hash text, modified_time timestamp without time zone, group_id_array bigint[])
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_product_feature_id en_product_feature_id_type;

BEGIN

SELECT p.product_feature_id
INTO v_product_feature_id
FROM tb_policy p
WHERE p.policy_id = i_policy_id;

IF v_product_feature_id IS NULL THEN

  RAISE EXCEPTION 'policy_id (%) does not exist.', i_policy_id USING HINT = 'DB-00031';

ELSIF v_product_feature_id <> 'AGENT_MGMT' THEN

  RAISE EXCEPTION 'policy_id (%) is not AGENT_MGMT policy.', i_policy_id USING HINT = 'DB-00030';

END IF;

RETURN QUERY

--정책 상세
SELECT p.product_feature_id AS product_feature_id
      ,p.product_feature_name AS product_feature_name
      ,p.policy_id AS policy_id
      ,p.policy_name AS policy_name
      ,p.description AS description
      ,p.policy_type AS policy_type
      ,p.online_policy_body AS online_policy_body
      ,p.offline_policy_body AS offline_policy_body
      ,p.use_offline_policy AS use_offline_policy
      ,p.hash AS hash
      ,p.modified_time AS modified_time
      ,p.group_id_array AS group_id_array
FROM sp_get_policy_detail(i_policy_id) p
;

END;
$$;


ALTER FUNCTION public.sp_get_agent_policy_detail(i_policy_id bigint) OWNER TO cppoltp;

