--
-- Name: sp_get_agent_policy_factory(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_policy_factory(i_admin_id text) RETURNS TABLE(policy_name text, product_feature_id public.en_product_feature_id_type, description text, online_policy_body text, offline_policy_body text, use_offline_policy text, hash text)
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_privilege_profile_auth boolean;
BEGIN

SELECT
    EXISTS (
        SELECT
            1
        FROM
            tb_admin ta
        INNER JOIN
            tb_privilege_profile tpp
        ON
            ta.privilege_profile_id = tpp.privilege_profile_id 
        WHERE
            tpp.profile_body LIKE '%"/policy/policy_SA_W"%'
        AND
            ta.admin_id = i_admin_id
    ) INTO v_privilege_profile_auth;
	
IF v_privilege_profile_auth = FALSE THEN
  RAISE EXCEPTION 'You do not have permission to write policy' USING HINT = 'DB-00084';
END IF;

  --정책 공장초기화값 조회
  RETURN QUERY
  SELECT pf.policy_name AS policy_name
        ,pf.product_feature_id AS product_feature_id
        ,pf.description AS description
        ,pf.online_policy_body AS online_policy_body
        ,pf.offline_policy_body AS offline_policy_body
        ,pf.use_offline_policy AS use_offline_policy
        ,pf.hash AS hash
  FROM sp_get_policy_factory('AGENT_MGMT') pf;

END;
$$;


ALTER FUNCTION public.sp_get_agent_policy_factory(i_admin_id text) OWNER TO cppoltp;

