--
-- Name: sp_get_agent_scm_status_link_list(bigint[], text, text, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_scm_status_link_list(i_node_id_arr bigint[], i_filter_json text, i_product_auth text, i_dashboard_layout text, i_admin_group text) RETURNS TABLE(node_id bigint, connection_status public.en_connection_status, service_status text, hardening_status public.en_product_service_status, total_scan_count integer, total_compliance_scan_pass_count integer, total_secret_scan_pass_count integer, total_compliance_scan_fail_count integer, total_secret_scan_fail_count integer, total_compliance_scan_error_count integer, total_secret_scan_error_count integer, scan_time text, product_version text, rule_version text, user_rule_version text)
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_node_id_arr bigint[];

BEGIN
	v_node_id_arr := sp_get_agent_status_filter(i_node_id_arr, i_filter_json, i_product_auth, i_dashboard_layout, i_admin_group);

	RETURN QUERY
    SELECT	 TN.NODE_ID
    		,COALESCE(TNS.CONNECTION_STATUS, 'UNINSTALLED') AS CONNECTION_STATUS /* SCM 연결 상태 */
    		,CASE WHEN TPI.PRODUCT_ID IS NULL THEN 'NOT_INSTALLED'
			ELSE COALESCE(TSS.SERVICE_STATUS::TEXT, 'NOT_INSTALLED') END AS SERVICE_STATUS /* SCM 서비스 상태 */
	        ,TSS.HARDENING_STATUS /* SCM 하드닝 엔진 상태 */
	        ,COALESCE(
	        	  TSS.COMPLIANCE_SCAN_PASS_COUNT + TSS.COMPLIANCE_SCAN_FAIL_COUNT + TSS.COMPLIANCE_SCAN_ERROR_COUNT
	        	  + TSS.COMPLIANCE_SCAN_USER_PASS_COUNT + TSS.COMPLIANCE_SCAN_USER_FAIL_COUNT + TSS.COMPLIANCE_SCAN_USER_ERROR_COUNT
	        	  + TSS.SECRET_SCAN_PASS_COUNT + TSS.SECRET_SCAN_FAIL_COUNT + TSS.SECRET_SCAN_ERROR_COUNT
	        	  + TSS.SECRET_SCAN_USER_PASS_COUNT + TSS.SECRET_SCAN_USER_FAIL_COUNT + TSS.SECRET_SCAN_USER_ERROR_COUNT
	        	, 0
	        ) AS TOTAL_SCAN_COUNT /* 전체 점검 수(기본/사용자정의 보안정보 + 민감정보) */
	        ,COALESCE(
	        	  TSS.COMPLIANCE_SCAN_PASS_COUNT + TSS.COMPLIANCE_SCAN_USER_PASS_COUNT
	        	, 0
	        ) AS TOTAL_COMPLIANCE_SCAN_PASS_COUNT /* 전체 점검 수 중 안전 수(기본/사용자정의 보안정보) */
	        ,COALESCE(
	        	  TSS.SECRET_SCAN_PASS_COUNT + TSS.SECRET_SCAN_USER_PASS_COUNT
	        	, 0
	        ) AS TOTAL_SECRET_SCAN_PASS_COUNT /* 전체 점검 수 중 안전 수(기본/사용자정의 민감정보) */
	        ,COALESCE(
	        	  TSS.COMPLIANCE_SCAN_FAIL_COUNT + TSS.COMPLIANCE_SCAN_USER_FAIL_COUNT
	        	, 0
	        ) AS TOTAL_COMPLIANCE_SCAN_FAIL_COUNT /* 전체 점검 수 중 취약 수(기본/사용자정의 보안정보) */
	        ,COALESCE(
	        	  TSS.SECRET_SCAN_FAIL_COUNT + TSS.SECRET_SCAN_USER_FAIL_COUNT
	        	, 0
	        ) AS TOTAL_SECRET_SCAN_FAIL_COUNT /* 전체 점검 수 중 취약 수(기본/사용자정의 민감정보) */
	        ,COALESCE(
	        	  TSS.COMPLIANCE_SCAN_ERROR_COUNT + TSS.COMPLIANCE_SCAN_USER_ERROR_COUNT
	        	, 0
	        ) AS TOTAL_COMPLIANCE_SCAN_ERROR_COUNT /* 전체 점검 수 중 Unkown 수(기본/사용자정의 보안정보) */
	        ,COALESCE(
	        	  TSS.SECRET_SCAN_ERROR_COUNT + TSS.SECRET_SCAN_USER_ERROR_COUNT
	        	, 0
	        ) AS TOTAL_SECRET_SCAN_ERROR_COUNT /* 전체 점검 수 중 Unkown 수(기본/사용자정의 민감정보) */
	        ,CASE
			  	WHEN TSS.SCAN_TIME IS NULL THEN TSS.SCAN_TIME::TEXT
				ELSE TO_CHAR(TSS.SCAN_TIME::TIMESTAMP + (INTERVAL '1 HOURS' * TSS.TZ_OFFSET), 'YYYY-MM-DD HH24:MI:SS')
			END AS SCAN_TIME /* 마지막 수동 검사 시간 */
	        ,TSS.PRODUCT_VERSION /* SCM 제품 버전 */        
	        ,TSS.RULE_VERSION /* SCM 룰셋 버전 */
	        ,TSS.USER_RULE_VERSION /* SCM 사용자 룰셋 버전 */
    FROM	TB_NODE TN
    LEFT
    	JOIN	TB_NODE_STATUS TNS
    	ON		TN.NODE_ID = TNS.NODE_ID
    LEFT 
    	JOIN	TB_PRODUCT_INFO TPI 
    	ON		TN.NODE_ID = TPI.NODE_ID 
    	AND		TPI.PRODUCT_ID = 'SCM_CLIENT'
    LEFT 
    	JOIN	TB_SCM_STATUS TSS
    	ON		TN.NODE_ID = TSS.NODE_ID
    WHERE	TN.NODE_ID = ANY(v_node_id_arr)
    AND		TN.IS_REMOVED IS FALSE
    ORDER BY
      		TN.NODE_ID DESC
    ;
END;
$$;


ALTER FUNCTION public.sp_get_agent_scm_status_link_list(i_node_id_arr bigint[], i_filter_json text, i_product_auth text, i_dashboard_layout text, i_admin_group text) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_agent_scm_status_link_list(i_node_id_arr bigint[], i_filter_json text, i_product_auth text, i_dashboard_layout text, i_admin_group text); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_agent_scm_status_link_list(i_node_id_arr bigint[], i_filter_json text, i_product_auth text, i_dashboard_layout text, i_admin_group text) IS '
@brief  프로시저 설명 : 대시보드>SCM>설치율/상태 링크
@in
@return';


--
-- Name: sp_get_agent_status_agent_info_olap(bigint[], text, text, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_status_agent_info_olap(i_node_id_arr bigint[], i_filter_json text, i_product_auth text, i_dashboard_layout text, i_admin_group text) RETURNS TABLE(node_id bigint, connection_status public.en_connection_status, server_time timestamp without time zone, client_time timestamp without time zone, integrity_status public.en_integrity_status, policy_status public.en_policy_status, license_code text, policy_name text)
    LANGUAGE plpgsql
    AS $$

DECLARE
  v_node_id_arr bigint[];
BEGIN

  v_node_id_arr := sp_get_agent_status_filter(i_node_id_arr, i_filter_json, i_product_auth, i_dashboard_layout, i_admin_group);

  RETURN QUERY
    SELECT
      node.node_id AS node_id -- 노드 ID
        , COALESCE(node_status.connection_status, 'UNINSTALLED'::en_connection_status) AS connection_status -- 노드 연결 상태
        , node_status.server_time::TIMESTAMP AS server_time -- 연결 시각
        , node_status.client_time::TIMESTAMP AS client_time -- 소프트웨어 정보 확인 시간
        , COALESCE(node_status.integrity_status, 'NOT_SCANNED'::en_integrity_status) AS integrity_status -- 무결성 검사 결과
        , COALESCE(policy_status.policy_status, 'APPLYING'::en_policy_status) AS policy_status -- 정책 적용 결과
        , CASE
            WHEN node_status.activation_code IS NOT NULL AND node_status.activation_code != '' THEN node_status.activation_code
            WHEN node_status.license_no IS NOT NULL AND node_status.license_no != '' THEN node_status.license_no
            ELSE NULL
            END AS license_code -- 라이선스 번호 (1.0 or 2.0)
        , p.name AS policy_name
    FROM
        tb_node node
        LEFT JOIN tb_node_status node_status ON node_status.node_id = node.node_id
        LEFT JOIN tb_policy_status policy_status ON policy_status.node_id = node.node_id AND policy_status.product_feature_id = 'AGENT_MGMT'
        LEFT JOIN tb_node_policy tnp ON node.node_id = tnp.node_id AND tnp.product_feature_id = 'AGENT_MGMT'
        LEFT JOIN tb_policy p ON tnp.policy_id = p.policy_id AND tnp.product_feature_id = p.product_feature_id 
        LEFT JOIN tb_product_feature_map tpfm ON tpfm.product_feature_id = p.product_feature_id  
        LEFT JOIN tb_product tp ON tp.product_id = tpfm.product_id
      WHERE
          node.node_id = ANY(v_node_id_arr)
          AND node.is_removed IS FALSE
      ORDER BY 1;
  END;
$$;


ALTER FUNCTION public.sp_get_agent_status_agent_info_olap(i_node_id_arr bigint[], i_filter_json text, i_product_auth text, i_dashboard_layout text, i_admin_group text) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_agent_status_agent_info_olap(i_node_id_arr bigint[], i_filter_json text, i_product_auth text, i_dashboard_layout text, i_admin_group text); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_agent_status_agent_info_olap(i_node_id_arr bigint[], i_filter_json text, i_product_auth text, i_dashboard_layout text, i_admin_group text) IS '
@brief 에이전트 보기 > 상태 정보
@in -
@out -
@return - QUERY';


--
-- Name: sp_get_agent_status_agent_info_oltp(bigint, bigint[], boolean, bigint, bigint, boolean[], text[], text[], boolean, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_status_agent_info_oltp(i_group_id bigint, i_node_id bigint[], i_is_include_all_sub_groups boolean, i_offset bigint, i_limit bigint, i_ip_search_range boolean[], i_ip_range_from text[], i_ip_range_to text[], i_is_search boolean, i_admin_id text) RETURNS TABLE(node_id bigint, group_id bigint, ip inet, ip_connected inet, mac text, nt_domain text, agent_version text, install_time timestamp without time zone, computer_name text, os_language text, login_id text, machine_uuid text, platform_id text, machine_type text, phone text, empno text, user_name text, department text, email text, description text, modified_by_admin boolean, platform_name text, platform_version text, group_name_path text, update_server_list text, is_agent_policy integer, is_v3_policy integer, is_ac_agent_policy integer, is_ac_mgmt_policy integer, is_hips_agent_policy integer, is_hips_mgmt_policy integer, is_hips_fw_policy integer, is_im_mgmt_policy integer, group_type public.en_group_type, applied_signature_count bigint, recommended_apply_count bigint, recommended_not_apply_count bigint, recommendation_analyze_time text, recommendation_complete_time text, recommendation_date text, hdd1_free_info integer, region text, public_ip inet, private_ip inet, instance_type text, agent_install_path text, agent_hdd_usage text, antimalware_install_path text, antimalware_hdd_usage text, ac_client_install_path text, ac_client_hdd_usage text, hips_client_install_path text, hips_client_hdd_usage text, container_service_type text, account_id text, region_name text, region_description text, instance_id text, instance_name text, ami_id text, vpc_id text, vpc_name_tag text, subnet_id text, subnet_name_tag text, k8s_host_os text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_node_id bigint[];
  v_available_group_id bigint[];
  v_sub_group_id bigint[];

BEGIN
    
    SELECT string_to_array(ta.admin_group,',')::bigint[] AS group_id
    INTO v_available_group_id
    FROM tb_admin ta
    WHERE ta.admin_id = i_admin_id;
    
    WITH RECURSIVE sub_group_id (group_id, pgroup_id) AS 
    (
      SELECT tg.group_id
              ,tg.pgroup_id
      FROM (
          SELECT tg.group_id
              ,tg.pgroup_id
          FROM tb_group tg
          WHERE tg.is_removed = FALSE
            AND tg.group_id = ANY(v_available_group_id)
              ) tg
      UNION DISTINCT
      SELECT tg.group_id
              ,tg.pgroup_id
      FROM tb_group tg 
          INNER JOIN sub_group_id vgi
              ON vgi.group_id = tg.pgroup_id
      WHERE tg.is_removed = FALSE
    )
    SELECT ARRAY_AGG(vgi.group_id) AS group_id
    INTO v_sub_group_id
    FROM (
        SELECT s.group_id
        FROM sub_group_id s
        
        UNION
        
        SELECT g.group_id
        FROM tb_group g
        WHERE g.group_type IN ('TOP', 'PHYSICAL', 'CLOUD')
    ) vgi;

    IF i_node_id IS NOT NULL THEN
        IF i_is_search AND TRUE = ANY(i_ip_search_range) AND 0 < array_length (i_ip_range_from, 1) THEN
            FOR i IN 1..array_length (i_ip_range_from, 1)
            LOOP
                IF v_node_id IS NULL THEN
                    SELECT ARRAY_AGG (DISTINCT n.node_id) INTO v_node_id FROM tb_node n
                    WHERE n.node_id = ANY(i_node_id)
                        AND ((i_ip_search_range[1] AND n.ip BETWEEN i_ip_range_from[i]::inet  AND i_ip_range_to[i]::inet)
                        OR (i_ip_search_range[2] AND n.ip_connected BETWEEN i_ip_range_from[i]::inet  AND i_ip_range_to[i]::inet))
                    AND n.is_removed IS FALSE;
                ELSE
                    SELECT ARRAY (SELECT DISTINCT unnest (ARRAY_AGG (n.node_id) || v_node_id)
                                    FROM tb_node n
                                    WHERE n.node_id = ANY(i_node_id)
                                    AND ((i_ip_search_range[1] AND n.ip BETWEEN i_ip_range_from[i]::inet  AND i_ip_range_to[i]::inet)
                                        OR (i_ip_search_range[2] AND n.ip_connected BETWEEN i_ip_range_from[i]::inet  AND i_ip_range_to[i]::inet))
                                    AND n.is_removed IS FALSE
                                    ) INTO v_node_id;
                END IF;
            END LOOP;
        ELSE
            v_node_id := i_node_id;
        END IF;

    RETURN QUERY
        WITH node_each_signature AS (
            SELECT
                ns.sid
                ,ns.node_id
            FROM tb_node_hips_signature ns
        )
        , node_policy_signature AS (
            WITH kept_node_policy AS (
              SELECT np.node_id, np.policy_id
              FROM tb_node_policy AS np
              WHERE np.keep_agent_policy = TRUE
                AND np.product_feature_id = 'HIPS_MGMT'
            )
            , node_policy AS (
              SELECT np.node_id, np.policy_id FROM kept_node_policy AS np
              UNION ALL
              SELECT n.node_id, gp.policy_id
              FROM tb_group_policy AS gp
                JOIN tb_node AS n ON  n.group_id = gp.group_id
              WHERE gp.product_feature_id = 'HIPS_MGMT'
                AND NOT EXISTS (SELECT 1 FROM kept_node_policy AS k WHERE k.node_id = n.node_id)
            )
            SELECT
                s.sid
                , p.node_id
                , p.policy_id
            FROM tb_policy_hips_signature s
                JOIN node_policy p ON s.policy_id = p.policy_id::BIGINT
        )
        , installed_hips_target AS (
            SELECT 
              tpi.node_id 
            FROM 
              tb_product_info tpi 
            INNER JOIN 
              tb_hips_status ths 
            ON 
              tpi.node_id = ths.node_id 
            WHERE 
              tpi.product_id = 'HIPS_CLIENT'
        )
        , applied_signature AS (
            SELECT nes.sid, nes.node_id FROM node_each_signature nes
            UNION ALL
            SELECT nps.sid, nps.node_id FROM node_policy_signature nps
            WHERE
              NOT EXISTS (SELECT 1 FROM node_each_signature nes WHERE nes.sid = nps.sid AND nes.node_id = nps.node_id)
        )
        , applied_signature_count AS (
            SELECT
                a.node_id, count(a.sid) applied_signature_count
            FROM applied_signature a
            WHERE
              EXISTS (SELECT 1 FROM installed_hips_target iht WHERE iht.node_id = a.node_id)
            GROUP BY a.node_id
        )
        , recommended_signature_count AS (
            SELECT
                sr.node_id
                ,sum(CASE WHEN sr.recommendation_type = 'APPLY' THEN 1 ELSE 0 END) recommended_apply_count
                , sum(CASE WHEN sr.recommendation_type = 'NOT_APPLY' THEN 1 ELSE 0 END) recommended_not_apply_count
            FROM tb_node_signature_recommendation  sr
            GROUP BY sr.node_id
        )
       SELECT n.node_id /* 노드 ID */
        , n.group_id /* 그룹 ID */
        , n.ip /* IP 주소 */
        , n.ip_connected
        , n.mac /* MAC 주소 */
        , n.nt_domain /* NT 도메인 */
        , n.agent_version /* 에이전트 버전정보 */
        , n.agent_install_time::TIMESTAMP
        , n.computer_name /* 컴퓨터 이름 */
        , n.os_language::text
        , n.login_id /* 로그인 ID */
        , n.machine_uuid /* 에이전트 하드웨어 시리얼 */
        , n.platform_id::text /* 플랫폼 타입 */
        , n.machine_type::text  /* 에이전트 타입 */
        , u.phone
        , u.empno
        , u.name AS user_name
        , u.department
        , u.email
        , u.description
        , u.modified_by_admin
        , p.name AS platform_name
        , CASE
            WHEN p.platform_type = 'WINDOWS' THEN nh.os_version
            ELSE nh.os_kernel_version 
          END AS platform_version
        , gnp.group_path AS group_name_path /* 그룹명경로 */
        , sl.update_server_list::TEXT
        , np.is_agent_policy
        , np.is_v3_policy
        , np.is_ac_agent_policy
        , np.is_ac_mgmt_policy
        , np.is_hips_agent_policy
        , np.is_hips_mgmt_policy
        , np.is_hips_fw_policy
        , np.is_im_mgmt_policy
        , CASE
            WHEN gro.group_type = 'TOP' THEN gro.group_type
            WHEN gro.group_type = 'CLOUD_AWS' THEN gro.group_type
            WHEN POSITION('CLOUD_AZURE' IN gro.group_type::TEXT) > 0 THEN gro.group_type
            WHEN gro.group_type = 'CLOUD_ALIBABA' THEN gro.group_type
            ELSE 'PHYSICAL'
          END AS group_type
        , COALESCE(ths.signature_count, 0)::bigint AS applied_signature_count
        , COALESCE(rsc.recommended_apply_count, 0) AS recommended_apply_count
        , COALESCE(rsc.recommended_not_apply_count, 0) AS recommended_not_apply_count
        , tnsr.recommendation_analyze_time
        , tnsr.recommendation_complete_time
        , CASE
            WHEN ths.recommendation_date IS NULL THEN ths.recommendation_date::TEXT
            ELSE TO_CHAR(ths.recommendation_date::timestamp + (INTERVAL '1 HOURS' * ths.tz_offset), 'YYYY-MM-DD HH24:MI:SS')
          END AS recommendation_date
        , CASE 
            WHEN nh.hdd1_size = '' OR nh.hdd1_size = '0' OR nh.hdd1_free = '' THEN NULL 
            ELSE (ROUND(((nh.hdd1_size::float - nh.hdd1_free::float)/nh.hdd1_size::float)::numeric, 2)*100)::integer 
          END AS hdd1_free_info
        , CASE
            WHEN n.machine_type = 'CLOUD_AWS' THEN aws.region_name
            WHEN n.machine_type = 'CLOUD_AZURE' THEN azure.region
            WHEN n.machine_type = 'CLOUD_ALIBABA' THEN alibaba.region_id
            ELSE ''
          END AS region
        , CASE
            WHEN n.machine_type = 'CLOUD_AWS' THEN aws.public_ip
            WHEN n.machine_type = 'CLOUD_AZURE' THEN azure.public_ip
            WHEN n.machine_type = 'CLOUD_ALIBABA' THEN alibaba.public_ip::inet
            ELSE NULL
          END AS public_ip
        , CASE
            WHEN n.machine_type = 'CLOUD_AWS' THEN aws.private_ip
            WHEN n.machine_type = 'CLOUD_AZURE' THEN azure.private_ip
            WHEN n.machine_type = 'CLOUD_ALIBABA' THEN alibaba.private_ip::inet
            ELSE NULL
          END AS private_ip
        , CASE
            WHEN n.machine_type = 'CLOUD_AWS' THEN aws.type
            WHEN n.machine_type = 'CLOUD_AZURE' THEN azure.vm_size_type
            WHEN n.machine_type = 'CLOUD_ALIBABA' THEN alibaba.instance_type
            ELSE ''
          END AS instance_type
            , nh.agent_install_path
        , nh.agent_hdd_usage
        , nh.antimalware_install_path
        , nh.antimalware_hdd_usage
        , nh.ac_client_install_path
        , nh.ac_client_hdd_usage
        , nh.hips_client_install_path
        , nh.hips_client_hdd_usage
        , n.container_service_type
        ,CASE
          WHEN n.machine_type = 'CLOUD_AWS' THEN cast(aws.account_id as text)
          WHEN n.machine_type = 'CLOUD_AZURE' THEN cast(azure.subscription_id as text)
          WHEN n.machine_type = 'CLOUD_ALIBABA' THEN cast(alibaba.account_id as text)
          ELSE NULL
        END AS account_id
        ,CASE
          WHEN n.machine_type = 'CLOUD_AWS' THEN cast(aws.region_name as text)
          WHEN n.machine_type = 'CLOUD_AZURE' THEN cast(azure.region as text)
          WHEN n.machine_type = 'CLOUD_ALIBABA' THEN cast(alibaba.region_id as text)
          ELSE NULL
        END AS region_name
        ,CASE
          WHEN n.machine_type = 'CLOUD_AWS' THEN cast(aws.region_description as text)
          WHEN n.machine_type = 'CLOUD_AZURE' THEN cast('' as text)
          WHEN n.machine_type = 'CLOUD_ALIBABA' THEN cast(alibaba.region_description as text)
          ELSE NULL
        END AS region_description
        ,CASE
          WHEN n.machine_type = 'CLOUD_AWS' THEN cast(aws.instance_id as text)
          WHEN n.machine_type = 'CLOUD_AZURE' THEN cast(azure.vm_id as text)
          WHEN n.machine_type = 'CLOUD_ALIBABA' THEN cast(alibaba.instance_id as text)
          ELSE NULL
        END AS instance_id
        ,CASE
          WHEN n.machine_type = 'CLOUD_AWS' THEN cast(aws.name as text)
          WHEN n.machine_type = 'CLOUD_AZURE' THEN cast(azure.vm_name as text)
          WHEN n.machine_type = 'CLOUD_ALIBABA' THEN cast(alibaba.instance_name as text)
          ELSE NULL
        END AS instance_name
        ,CASE
          WHEN n.machine_type = 'CLOUD_AWS' THEN cast(aws.ami_id as text)
          WHEN n.machine_type = 'CLOUD_AZURE' THEN cast('' as text)
          WHEN n.machine_type = 'CLOUD_ALIBABA' THEN cast(alibaba.image_id as text)
          ELSE NULL
        END AS ami_id
        ,CASE
          WHEN n.machine_type = 'CLOUD_AWS' THEN cast(aws.vpc_id as text)
          WHEN n.machine_type = 'CLOUD_AZURE' THEN cast('' as text)
          WHEN n.machine_type = 'CLOUD_ALIBABA' THEN cast(alibaba.vpc_id as text)
          ELSE NULL
        END AS vpc_id
        ,CASE
          WHEN n.machine_type = 'CLOUD_AWS' THEN cast(aws.vpc_name_tag as text)
          WHEN n.machine_type = 'CLOUD_AZURE' THEN cast('' as text)
          WHEN n.machine_type = 'CLOUD_ALIBABA' THEN cast('' as text)
          ELSE NULL
        END AS vpc_name_tag
        ,CASE
          WHEN n.machine_type = 'CLOUD_AWS' THEN cast(aws.subnet_id as text)
          WHEN n.machine_type = 'CLOUD_AZURE' THEN cast('' as text)
          WHEN n.machine_type = 'CLOUD_ALIBABA' THEN cast(alibaba.v_switch_id as text)
          ELSE NULL
        END AS subnet_id
        ,CASE
          WHEN n.machine_type = 'CLOUD_AWS' THEN cast(aws.subnet_name_tag as text)
          WHEN n.machine_type = 'CLOUD_AZURE' THEN cast(azure.subnet_name as text)
          WHEN n.machine_type = 'CLOUD_ALIBABA' THEN cast('' as text)
          ELSE NULL
        END AS subnet_name_tag
        , n.k8s_host_os
      FROM tb_node AS n
      JOIN sp_get_group_name_path_all () gnp ON n.group_id = gnp.group_id
      JOIN tb_platform p ON n.platform_id = p.platform_id
      LEFT JOIN tb_node_status tns ON n.node_id = tns.node_id
      LEFT JOIN sp_get_keep_agent_policy () np ON n.node_id = np.node_id
      LEFT JOIN tb_node_hw nh ON nh.node_id = n.node_id
      LEFT JOIN applied_signature_count sc ON n.node_id = sc.node_id
      LEFT JOIN recommended_signature_count rsc ON n.node_id = rsc.node_id
      LEFT JOIN tb_user u ON n.node_id = u.node_id
      LEFT JOIN tb_group gro ON gro.group_id = n.group_id
      LEFT JOIN tb_group pgrp ON gro.pgroup_id = pgrp.group_id
      LEFT JOIN (
              SELECT t.node_id, ARRAY_TO_STRING (ARRAY_AGG (t.update_server_list), ',') AS update_server_list
              FROM (
                  SELECT n.node_id, s.name || '(' || s.ip || ')' AS update_server_list
                  FROM tb_node n
                  JOIN tb_file_update_server us ON us.target_id = n.node_id AND target_type = 'NODE'
                  JOIN tb_server s ON us.server_id = s.server_id
                  WHERE n.is_removed IS FALSE
                  AND n.platform_id IS NOT NULL
                  ORDER BY s.name
              ) t
              GROUP BY t.node_id
      ) sl 
      ON sl.node_id = n.node_id
      LEFT JOIN tb_hips_status ths ON n.node_id = ths.node_id
      LEFT JOIN (
            SELECT
              tnsrei.node_id
              , TO_CHAR(tnsrei.last_analyze_time, 'YYYY-MM-DD HH24:MI:SS') AS recommendation_analyze_time
              , TO_CHAR(tnsrei.last_apply_time, 'YYYY-MM-DD HH24:MI:SS') AS recommendation_complete_time
            FROM tb_node_signature_recommendation_execution_info tnsrei
      ) tnsr
      ON  n.node_id = tnsr.node_id
      LEFT JOIN tb_cloud_aws_instance aws ON n.machine_uuid = aws.instance_id AND n.machine_type = 'CLOUD_AWS'
      LEFT JOIN tb_cloud_azure_vm azure ON n.machine_uuid = azure.vm_id AND n.machine_type = 'CLOUD_AZURE'
      LEFT JOIN tb_cloud_alibaba_instance alibaba ON n.machine_uuid = alibaba.instance_id AND n.machine_type = 'CLOUD_ALIBABA'
      WHERE n.node_id = ANY (v_node_id)
      AND n.is_removed = FALSE
      AND n.group_id = ANY(SELECT UNNEST(v_sub_group_id))
      AND CASE WHEN i_group_id IS NULL THEN TRUE
                     ELSE i_group_id = ANY(SELECT UNNEST(v_sub_group_id))
                     END
      AND (p.is_supported IS TRUE OR n.machine_type IN('CLOUD_AWS','CLOUD_AZURE','CLOUD_ALIBABA'))
      ORDER BY node_id;

    ELSE
        IF i_is_search AND TRUE = ANY(i_ip_search_range) AND 0 < array_length (i_ip_range_from, 1) THEN
            FOR i IN 1..array_length (i_ip_range_from, 1)
            LOOP
                IF v_node_id IS NULL THEN
                    SELECT ARRAY_AGG (DISTINCT n.node_id) INTO v_node_id FROM tb_node n
                    WHERE ((i_ip_search_range[1] AND n.ip BETWEEN i_ip_range_from[i]::inet  AND i_ip_range_to[i]::inet)
                        OR (i_ip_search_range[2] AND n.ip_connected BETWEEN i_ip_range_from[i]::inet  AND i_ip_range_to[i]::inet))
                    AND n.is_removed IS FALSE;
                ELSE
                    SELECT ARRAY (SELECT DISTINCT unnest (ARRAY_AGG (n.node_id) || v_node_id)
                                    FROM tb_node n
                                    WHERE ((i_ip_search_range[1] AND n.ip BETWEEN i_ip_range_from[i]::inet  AND i_ip_range_to[i]::inet)
                                        OR (i_ip_search_range[2] AND n.ip_connected BETWEEN i_ip_range_from[i]::inet  AND i_ip_range_to[i]::inet))
                                    AND n.is_removed IS FALSE
                                    ) INTO v_node_id;
                END IF;
            END LOOP;
        END IF;

        IF i_is_include_all_sub_groups THEN
            RETURN QUERY
            WITH node_each_signature AS (
                SELECT
                    ns.sid
                    , ns.node_id
                FROM tb_node_hips_signature ns
            )
            , node_policy_signature AS (
                WITH kept_node_policy AS (
                  SELECT np.node_id, np.policy_id
                  FROM tb_node_policy AS np
                  WHERE np.keep_agent_policy = TRUE
                    AND np.product_feature_id = 'HIPS_MGMT'
                )
                , node_policy AS (
                  SELECT np.node_id, np.policy_id FROM kept_node_policy AS np
                  UNION ALL
                  SELECT n.node_id, gp.policy_id
                  FROM tb_group_policy AS gp
                    JOIN tb_node AS n ON  n.group_id = gp.group_id
                  WHERE gp.product_feature_id = 'HIPS_MGMT'
                    AND NOT EXISTS (SELECT 1 FROM kept_node_policy AS k WHERE k.node_id = n.node_id)
                )
                SELECT
                    s.sid
                    , p.node_id
                    , p.policy_id
                FROM tb_policy_hips_signature s
                    JOIN node_policy p ON s.policy_id = p.policy_id::BIGINT
            )
            , installed_hips_target AS (
                SELECT 
                  tpi.node_id 
                FROM 
                  tb_product_info tpi 
                INNER JOIN 
                  tb_hips_status ths 
                ON 
                  tpi.node_id = ths.node_id 
                WHERE 
                  tpi.product_id = 'HIPS_CLIENT'
            )
            , applied_signature AS (
                SELECT nes.sid, nes.node_id FROM node_each_signature nes
                UNION ALL
                SELECT nps.sid, nps.node_id FROM node_policy_signature nps
                WHERE
                  NOT EXISTS (SELECT 1 FROM node_each_signature nes WHERE nes.sid = nps.sid AND nes.node_id = nps.node_id)
            )
            , applied_signature_count AS (
                SELECT
                    a.node_id, count(a.sid) applied_signature_count
                FROM applied_signature a
                WHERE
                  EXISTS (SELECT 1 FROM installed_hips_target iht WHERE iht.node_id = a.node_id)
                GROUP BY a.node_id
            )
            , recommended_signature_count AS (
                SELECT
                    sr.node_id
                    ,sum(CASE WHEN sr.recommendation_type = 'APPLY' THEN 1 ELSE 0 END) recommended_apply_count
                    , sum(CASE WHEN sr.recommendation_type = 'NOT_APPLY' THEN 1 ELSE 0 END) recommended_not_apply_count
                FROM tb_node_signature_recommendation  sr
                GROUP BY sr.node_id
            )
            SELECT NOD.node_id /* 노드 ID */
                , NOD.group_id /* 그룹 ID */
                , NOD.ip /* IP 주소 */
                , NOD.ip_connected
                , NOD.mac /* MAC 주소 */
                , NOD.nt_domain /* NT 도메인 */
                , NOD.agent_version /* 에이전트 버전정보 */
                , NOD.agent_install_time::TIMESTAMP
                , NOD.computer_name /* 컴퓨터 이름 */
                , NOD.os_language::text
                , NOD.login_id /* 로그인 ID */
                , NOD.machine_uuid /* 에이전트 하드웨어 시리얼 */
                , NOD.platform_id::text /* 플랫폼 타입 */
                , NOD.machine_type::text  /* 에이전트 타입 */
                , u.phone
                , u.empno
                , u.name AS user_name
                , u.department
                , u.email
                , u.description
                , u.modified_by_admin
                , p.name AS platform_name
                , CASE 
                    WHEN p.platform_type = 'WINDOWS' THEN nh.os_version
                    ELSE nh.os_kernel_version 
                  END AS platform_version
                , gnp.group_path AS group_name_path /* 그룹명경로 */
                , sl.update_server_list
                , np.is_agent_policy
                , np.is_v3_policy
                , np.is_ac_agent_policy
                , np.is_ac_mgmt_policy
                , np.is_hips_agent_policy
                , np.is_hips_mgmt_policy
                , np.is_hips_fw_policy
                , np.is_im_mgmt_policy
                , CASE
                    WHEN gro.group_type = 'TOP' THEN gro.group_type
                    WHEN gro.group_type = 'CLOUD_AWS' THEN gro.group_type
                    WHEN POSITION('CLOUD_AZURE' IN gro.group_type::TEXT) > 0 THEN gro.group_type
                    WHEN gro.group_type = 'CLOUD_ALIBABA' THEN gro.group_type
                    ELSE 'PHYSICAL'
                  END AS group_type
                , COALESCE(ths.signature_count, 0)::bigint AS applied_signature_count
                , COALESCE(rsc.recommended_apply_count, 0) AS recommended_apply_count
                , COALESCE(rsc.recommended_not_apply_count, 0) AS recommended_not_apply_count
                , tnsr.recommendation_analyze_time
                , tnsr.recommendation_complete_time
                , CASE
                    WHEN ths.recommendation_date IS NULL THEN ths.recommendation_date::TEXT
                    ELSE TO_CHAR(ths.recommendation_date::timestamp + (INTERVAL '1 HOURS' * ths.tz_offset), 'YYYY-MM-DD HH24:MI:SS')
                  END AS recommendation_date
                , CASE 
                    WHEN nh.hdd1_size = '' OR nh.hdd1_size = '0' OR nh.hdd1_free = '' THEN NULL 
                    ELSE (ROUND(((nh.hdd1_size::float - nh.hdd1_free::float)/nh.hdd1_size::float)::numeric, 2)*100)::integer 
                  END AS hdd1_free_info
                , CASE
                    WHEN NOD.machine_type = 'CLOUD_AWS' THEN aws.region_name
                    WHEN NOD.machine_type = 'CLOUD_AZURE' THEN azure.region
                    WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN alibaba.region_id
                    ELSE ''
                  END AS region
                , CASE
                    WHEN NOD.machine_type = 'CLOUD_AWS' THEN aws.public_ip
                    WHEN NOD.machine_type = 'CLOUD_AZURE' THEN azure.public_ip
                    WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN alibaba.public_ip::inet
                    ELSE NULL
                  END AS public_ip
                , CASE
                    WHEN NOD.machine_type = 'CLOUD_AWS' THEN aws.private_ip
                    WHEN NOD.machine_type = 'CLOUD_AZURE' THEN azure.private_ip
                    WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN alibaba.private_ip::inet
                    ELSE NULL
                  END AS private_ip
                , CASE
                    WHEN NOD.machine_type = 'CLOUD_AWS' THEN aws.type
                    WHEN NOD.machine_type = 'CLOUD_AZURE' THEN azure.vm_size_type
                    WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN alibaba.instance_type
                    ELSE ''
                  END AS instance_type
                , nh.agent_install_path
                , nh.agent_hdd_usage
                , nh.antimalware_install_path
                , nh.antimalware_hdd_usage
                , nh.ac_client_install_path
                , nh.ac_client_hdd_usage
                , nh.hips_client_install_path
                , nh.hips_client_hdd_usage
                , NOD.container_service_type
                ,CASE
                  WHEN NOD.machine_type = 'CLOUD_AWS' THEN cast(aws.account_id as text)
                  WHEN NOD.machine_type = 'CLOUD_AZURE' THEN cast(azure.subscription_id as text)
                  WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN cast(alibaba.account_id as text)
                  ELSE NULL
                END AS account_id
                ,CASE
                  WHEN NOD.machine_type = 'CLOUD_AWS' THEN cast(aws.region_name as text)
                  WHEN NOD.machine_type = 'CLOUD_AZURE' THEN cast(azure.region as text)
                  WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN cast(alibaba.region_id as text)
                  ELSE NULL
                END AS region_name
                ,CASE
                  WHEN NOD.machine_type = 'CLOUD_AWS' THEN cast(aws.region_description as text)
                  WHEN NOD.machine_type = 'CLOUD_AZURE' THEN cast('' as text)
                  WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN cast(alibaba.region_description as text)
                  ELSE NULL
                END AS region_description
                ,CASE
                  WHEN NOD.machine_type = 'CLOUD_AWS' THEN cast(aws.instance_id as text)
                  WHEN NOD.machine_type = 'CLOUD_AZURE' THEN cast(azure.vm_id as text)
                  WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN cast(alibaba.instance_id as text)
                  ELSE NULL
                END AS instance_id
                ,CASE
                  WHEN NOD.machine_type = 'CLOUD_AWS' THEN cast(aws.name as text)
                  WHEN NOD.machine_type = 'CLOUD_AZURE' THEN cast(azure.vm_name as text)
                  WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN cast(alibaba.instance_name as text)
                  ELSE NULL
                END AS instance_name
                ,CASE
                  WHEN NOD.machine_type = 'CLOUD_AWS' THEN cast(aws.ami_id as text)
                  WHEN NOD.machine_type = 'CLOUD_AZURE' THEN cast('' as text)
                  WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN cast(alibaba.image_id as text)
                  ELSE NULL
                END AS ami_id
                ,CASE
                  WHEN NOD.machine_type = 'CLOUD_AWS' THEN cast(aws.vpc_id as text)
                  WHEN NOD.machine_type = 'CLOUD_AZURE' THEN cast('' as text)
                  WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN cast(alibaba.vpc_id as text)
                  ELSE NULL
                END AS vpc_id
                ,CASE
                  WHEN NOD.machine_type = 'CLOUD_AWS' THEN cast(aws.vpc_name_tag as text)
                  WHEN NOD.machine_type = 'CLOUD_AZURE' THEN cast('' as text)
                  WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN cast('' as text)
                  ELSE NULL
                END AS vpc_name_tag
                ,CASE
                  WHEN NOD.machine_type = 'CLOUD_AWS' THEN cast(aws.subnet_id as text)
                  WHEN NOD.machine_type = 'CLOUD_AZURE' THEN cast('' as text)
                  WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN cast(alibaba.v_switch_id as text)
                  ELSE NULL
                END AS subnet_id
                ,CASE
                  WHEN NOD.machine_type = 'CLOUD_AWS' THEN cast(aws.subnet_name_tag as text)
                  WHEN NOD.machine_type = 'CLOUD_AZURE' THEN cast(azure.subnet_name as text)
                  WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN cast('' as text)
                  ELSE NULL
                END AS subnet_name_tag
                , NOD.k8s_host_os
            FROM tb_group AS GRO
            JOIN tb_node AS NOD ON GRO.group_id = NOD.group_id AND NOD.is_removed = FALSE
            JOIN tb_platform p ON NOD.platform_id = p.platform_id
            JOIN sp_get_group_name_path_all () gnp ON GRO.group_id = gnp.group_id
            LEFT JOIN tb_node_status tns ON NOD.node_id = tns.node_id 
            LEFT JOIN sp_get_keep_agent_policy() np ON NOD.node_id = np.node_id
            LEFT JOIN tb_node_hw nh ON nh.node_id = NOD.node_id
            LEFT JOIN applied_signature_count sc ON NOD.node_id = sc.node_id
            LEFT JOIN recommended_signature_count rsc ON NOD.node_id = rsc.node_id
            LEFT JOIN tb_user u ON NOD.node_id = u.node_id
            LEFT JOIN tb_group pgrp ON GRO.pgroup_id = pgrp.group_id
            LEFT JOIN (
                  SELECT t.node_id, ARRAY_TO_STRING (ARRAY_AGG (t.update_server_list), ',') AS update_server_list
                  FROM (
                      SELECT n.node_id, s.name || '(' || s.ip || ')' AS update_server_list
                      FROM tb_node n
                      JOIN tb_file_update_server us ON us.target_id = n.node_id AND target_type = 'NODE'
                      JOIN tb_server s ON us.server_id = s.server_id
                      WHERE n.is_removed = FALSE
                      AND n.platform_id IS NOT NULL
                      ORDER BY n.node_id, s.name DESC
                  ) t
                  GROUP BY t.node_id) sl 
            ON sl.node_id = NOD.node_id
            LEFT JOIN tb_hips_status ths ON NOD.node_id = ths.node_id
            LEFT JOIN (
                  SELECT
                    tnsrei.node_id
                    , TO_CHAR(tnsrei.last_analyze_time, 'YYYY-MM-DD HH24:MI:SS') AS recommendation_analyze_time
                    , TO_CHAR(tnsrei.last_apply_time, 'YYYY-MM-DD HH24:MI:SS') AS recommendation_complete_time
                  FROM tb_node_signature_recommendation_execution_info tnsrei
            ) tnsr
            ON  NOD.node_id = tnsr.node_id
            LEFT JOIN tb_cloud_aws_instance aws ON NOD.machine_uuid = aws.instance_id AND NOD.machine_type = 'CLOUD_AWS'
            LEFT JOIN tb_cloud_azure_vm azure ON NOD.machine_uuid = azure.vm_id AND NOD.machine_type = 'CLOUD_AZURE'
            LEFT JOIN tb_cloud_alibaba_instance alibaba ON NOD.machine_uuid = alibaba.instance_id AND NOD.machine_type = 'CLOUD_ALIBABA'
            WHERE (p.is_supported IS TRUE OR NOD.machine_type IN('CLOUD_AWS','CLOUD_AZURE','CLOUD_ALIBABA'))
            AND GRO.group_id IN (SELECT unnest(sp_get_all_sub_group_list(i_group_id, TRUE, i_admin_id)))
            AND NOD.is_removed = FALSE
            AND GRO.group_id = ANY(SELECT UNNEST(v_sub_group_id))
            AND CASE WHEN i_group_id IS NULL THEN TRUE
                     ELSE i_group_id = ANY(SELECT UNNEST(v_sub_group_id))
                     END
            AND CASE WHEN i_is_search THEN NOD.node_id IN (SELECT unnest (v_node_id)) ELSE 1 = 1 END
            ORDER BY node_id
            OFFSET i_offset LIMIT i_limit;

        ELSE

            RETURN QUERY
            WITH node_each_signature AS (
                SELECT
                    ns.sid
                    ,ns.node_id
                FROM tb_node_hips_signature ns
            )
            , node_policy_signature AS (
                WITH kept_node_policy AS (
                  SELECT np.node_id, np.policy_id
                  FROM tb_node_policy AS np
                  WHERE np.keep_agent_policy = TRUE
                    AND np.product_feature_id = 'HIPS_MGMT'
                )
                , node_policy AS (
                  SELECT np.node_id, np.policy_id FROM kept_node_policy AS np
                  UNION ALL
                  SELECT n.node_id, gp.policy_id
                  FROM tb_group_policy AS gp
                    JOIN tb_node AS n ON  n.group_id = gp.group_id
                  WHERE gp.product_feature_id = 'HIPS_MGMT'
                    AND NOT EXISTS (SELECT 1 FROM kept_node_policy AS k WHERE k.node_id = n.node_id)
                )
                SELECT
                    s.sid
                    , p.node_id
                    , p.policy_id
                FROM tb_policy_hips_signature s
                    JOIN node_policy p ON s.policy_id = p.policy_id::BIGINT
            )
            , installed_hips_target AS (
                SELECT 
                  tpi.node_id 
                FROM 
                  tb_product_info tpi 
                INNER JOIN 
                  tb_hips_status ths 
                ON 
                  tpi.node_id = ths.node_id 
                WHERE 
                  tpi.product_id = 'HIPS_CLIENT'
            )
            , applied_signature AS (
                SELECT nes.sid, nes.node_id FROM node_each_signature nes
                UNION ALL
                SELECT nps.sid, nps.node_id FROM node_policy_signature nps
                WHERE
                  NOT EXISTS (SELECT 1 FROM node_each_signature nes WHERE nes.sid = nps.sid AND nes.node_id = nps.node_id)
            )
            , applied_signature_count AS (
                SELECT
                    a.node_id, count(a.sid) applied_signature_count
                FROM applied_signature a
                WHERE
                  EXISTS (SELECT 1 FROM installed_hips_target iht WHERE iht.node_id = a.node_id)
                GROUP BY a.node_id
            )
            , recommended_signature_count AS (
                SELECT
                    sr.node_id
                    , sum(CASE WHEN sr.recommendation_type = 'APPLY' THEN 1 ELSE 0 END) recommended_apply_count
                    , sum(CASE WHEN sr.recommendation_type = 'NOT_APPLY' THEN 1 ELSE 0 END) recommended_not_apply_count
                FROM tb_node_signature_recommendation  sr
                GROUP BY sr.node_id
            )
            SELECT NOD.node_id /* 노드 ID */
                , NOD.group_id /* 그룹 ID */
                , NOD.ip /* IP 주소 */
                , NOD.ip_connected
                , NOD.mac /* MAC 주소 */
                , NOD.nt_domain /* NT 도메인 */
                , NOD.agent_version /* 에이전트 버전정보 */
                , NOD.agent_install_time::TIMESTAMP
                , NOD.computer_name /* 컴퓨터 이름 */
                , NOD.os_language::text
                , NOD.login_id /* 로그인 ID */
                , NOD.machine_uuid /* 에이전트 하드웨어 시리얼 */
                , NOD.platform_id::text /* 플랫폼 타입 */
                , NOD.machine_type::text  /* 에이전트 타입 */
                , u.phone
                , u.empno
                , u.name AS user_name
                , u.department
                , u.email
                , u.description
                , u.modified_by_admin
                , p.name AS platform_name
                , CASE 
                    WHEN p.platform_type = 'WINDOWS' THEN nh.os_version
                    ELSE nh.os_kernel_version 
                  END AS platform_version
                , gnp.group_path AS group_name_path /* 그룹명경로 */
                , sl.update_server_list
                , np.is_agent_policy
                , np.is_v3_policy
                , np.is_ac_agent_policy
                , np.is_ac_mgmt_policy
                , np.is_hips_agent_policy
                , np.is_hips_mgmt_policy
                , np.is_hips_fw_policy
                , np.is_im_mgmt_policy
                , CASE
                    WHEN gro.group_type = 'TOP' THEN gro.group_type
                    WHEN gro.group_type = 'CLOUD_AWS' THEN gro.group_type
                    WHEN POSITION('CLOUD_AZURE' IN gro.group_type::TEXT) > 0 THEN gro.group_type
                    WHEN gro.group_type = 'CLOUD_ALIBABA' THEN gro.group_type
                    ELSE 'PHYSICAL'
                  END AS group_type
                , COALESCE(ths.signature_count, 0)::bigint AS applied_signature_count
                , COALESCE(rsc.recommended_apply_count, 0) AS recommended_apply_count
                , COALESCE(rsc.recommended_not_apply_count, 0) AS recommended_not_apply_count
                , tnsr.recommendation_analyze_time
                , tnsr.recommendation_complete_time
                , CASE
                    WHEN ths.recommendation_date IS NULL THEN ths.recommendation_date::TEXT
                    ELSE TO_CHAR(ths.recommendation_date::timestamp + (INTERVAL '1 HOURS' * ths.tz_offset), 'YYYY-MM-DD HH24:MI:SS')
                  END AS recommendation_date
                , CASE 
                    WHEN nh.hdd1_size = '' OR nh.hdd1_size = '0' OR nh.hdd1_free = '' THEN NULL 
                    ELSE (ROUND(((nh.hdd1_size::float - nh.hdd1_free::float)/nh.hdd1_size::float)::numeric, 2)*100)::integer 
                  END AS hdd1_free_info
                , CASE
                    WHEN NOD.machine_type = 'CLOUD_AWS' THEN aws.region_name
                    WHEN NOD.machine_type = 'CLOUD_AZURE' THEN azure.region
                    WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN alibaba.region_id
                    ELSE ''
                  END AS region
                , CASE
                    WHEN NOD.machine_type = 'CLOUD_AWS' THEN aws.public_ip
                    WHEN NOD.machine_type = 'CLOUD_AZURE' THEN azure.public_ip
                    WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN alibaba.public_ip::inet
                    ELSE NULL
                  END AS public_ip
                , CASE
                    WHEN NOD.machine_type = 'CLOUD_AWS' THEN aws.private_ip
                    WHEN NOD.machine_type = 'CLOUD_AZURE' THEN azure.private_ip
                    WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN alibaba.private_ip::inet
                    ELSE NULL
                  END AS private_ip
                , CASE
                    WHEN NOD.machine_type = 'CLOUD_AWS' THEN aws.type
                    WHEN NOD.machine_type = 'CLOUD_AZURE' THEN azure.vm_size_type
                    WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN alibaba.instance_type
                    ELSE ''
                  END AS instance_type
                , nh.agent_install_path
                , nh.agent_hdd_usage
                , nh.antimalware_install_path
                , nh.antimalware_hdd_usage
                , nh.ac_client_install_path
                , nh.ac_client_hdd_usage
                , nh.hips_client_install_path
                , nh.hips_client_hdd_usage
                , NOD.container_service_type
                ,CASE
                  WHEN NOD.machine_type = 'CLOUD_AWS' THEN cast(aws.account_id as text)
                  WHEN NOD.machine_type = 'CLOUD_AZURE' THEN cast(azure.subscription_id as text)
                  WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN cast(alibaba.account_id as text)
                  ELSE NULL
                END AS account_id
                ,CASE
                  WHEN NOD.machine_type = 'CLOUD_AWS' THEN cast(aws.region_name as text)
                  WHEN NOD.machine_type = 'CLOUD_AZURE' THEN cast(azure.region as text)
                  WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN cast(alibaba.region_id as text)
                  ELSE NULL
                END AS region_name
                ,CASE
                  WHEN NOD.machine_type = 'CLOUD_AWS' THEN cast(aws.region_description as text)
                  WHEN NOD.machine_type = 'CLOUD_AZURE' THEN cast('' as text)
                  WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN cast(alibaba.region_description as text)
                  ELSE NULL
                END AS region_description
                ,CASE
                  WHEN NOD.machine_type = 'CLOUD_AWS' THEN cast(aws.instance_id as text)
                  WHEN NOD.machine_type = 'CLOUD_AZURE' THEN cast(azure.vm_id as text)
                  WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN cast(alibaba.instance_id as text)
                  ELSE NULL
                END AS instance_id
                ,CASE
                  WHEN NOD.machine_type = 'CLOUD_AWS' THEN cast(aws.name as text)
                  WHEN NOD.machine_type = 'CLOUD_AZURE' THEN cast(azure.vm_name as text)
                  WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN cast(alibaba.instance_name as text)
                  ELSE NULL
                END AS instance_name
                ,CASE
                  WHEN NOD.machine_type = 'CLOUD_AWS' THEN cast(aws.ami_id as text)
                  WHEN NOD.machine_type = 'CLOUD_AZURE' THEN cast('' as text)
                  WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN cast(alibaba.image_id as text)
                  ELSE NULL
                END AS ami_id
                ,CASE
                  WHEN NOD.machine_type = 'CLOUD_AWS' THEN cast(aws.vpc_id as text)
                  WHEN NOD.machine_type = 'CLOUD_AZURE' THEN cast('' as text)
                  WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN cast(alibaba.vpc_id as text)
                  ELSE NULL
                END AS vpc_id
                ,CASE
                  WHEN NOD.machine_type = 'CLOUD_AWS' THEN cast(aws.vpc_name_tag as text)
                  WHEN NOD.machine_type = 'CLOUD_AZURE' THEN cast('' as text)
                  WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN cast('' as text)
                  ELSE NULL
                END AS vpc_name_tag
                ,CASE
                  WHEN NOD.machine_type = 'CLOUD_AWS' THEN cast(aws.subnet_id as text)
                  WHEN NOD.machine_type = 'CLOUD_AZURE' THEN cast('' as text)
                  WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN cast(alibaba.v_switch_id as text)
                  ELSE NULL
                END AS subnet_id
                ,CASE
                  WHEN NOD.machine_type = 'CLOUD_AWS' THEN cast(aws.subnet_name_tag as text)
                  WHEN NOD.machine_type = 'CLOUD_AZURE' THEN cast(azure.subnet_name as text)
                  WHEN NOD.machine_type = 'CLOUD_ALIBABA' THEN cast('' as text)
                  ELSE NULL
                END AS subnet_name_tag
                , NOD.k8s_host_os
            FROM tb_group AS GRO
            JOIN tb_node AS NOD ON GRO.group_id = NOD.group_id AND NOD.is_removed = FALSE
            JOIN tb_platform p ON NOD.platform_id = p.platform_id
            JOIN sp_get_group_name_path_all () gnp ON GRO.group_id = gnp.group_id
            LEFT JOIN tb_node_status tns ON NOD.node_id = tns.node_id 
            LEFT JOIN sp_get_keep_agent_policy() np ON NOD.node_id = np.node_id
            LEFT JOIN tb_node_hw nh ON nh.node_id = NOD.node_id
            LEFT JOIN applied_signature_count sc ON NOD.node_id = sc.node_id
            LEFT JOIN recommended_signature_count rsc ON NOD.node_id = rsc.node_id
            LEFT JOIN tb_user u ON NOD.node_id = u.node_id
            LEFT JOIN tb_group pgrp ON GRO.pgroup_id = pgrp.group_id
            LEFT JOIN (
                  SELECT t.node_id, ARRAY_TO_STRING (ARRAY_AGG (t.update_server_list), ',') AS update_server_list
                  FROM (
                        SELECT n.node_id, s.name || '(' || s.ip || ')' AS update_server_list
                        FROM tb_node n
                        JOIN tb_file_update_server us ON us.target_id = n.node_id AND target_type = 'NODE'
                        JOIN tb_server s ON us.server_id = s.server_id
                        WHERE n.is_removed IS FALSE
                        AND n.platform_id IS NOT NULL
                        ORDER BY n.node_id, s.name DESC
                  ) t
                  GROUP BY t.node_id
            ) sl 
            ON sl.node_id = NOD.node_id
            LEFT JOIN tb_hips_status ths ON NOD.node_id = ths.node_id
            LEFT JOIN (
                  SELECT
                    tnsrei.node_id
                    , TO_CHAR(tnsrei.last_analyze_time, 'YYYY-MM-DD HH24:MI:SS') AS recommendation_analyze_time
                    , TO_CHAR(tnsrei.last_apply_time, 'YYYY-MM-DD HH24:MI:SS') AS recommendation_complete_time
                  FROM tb_node_signature_recommendation_execution_info tnsrei
            ) tnsr
            ON  NOD.node_id = tnsr.node_id
            LEFT JOIN tb_cloud_aws_instance aws ON NOD.machine_uuid = aws.instance_id AND NOD.machine_type = 'CLOUD_AWS'
            LEFT JOIN tb_cloud_azure_vm azure ON NOD.machine_uuid = azure.vm_id AND NOD.machine_type = 'CLOUD_AZURE'
            LEFT JOIN tb_cloud_alibaba_instance alibaba ON NOD.machine_uuid = alibaba.instance_id AND NOD.machine_type = 'CLOUD_ALIBABA'
            WHERE GRO.group_id = i_group_id
            AND (p.is_supported IS TRUE OR NOD.machine_type IN('CLOUD_AWS','CLOUD_AZURE','CLOUD_ALIBABA'))
            AND NOD.is_removed = FALSE
            AND GRO.group_id = ANY(SELECT UNNEST(v_sub_group_id))
            AND CASE WHEN i_group_id IS NULL THEN TRUE
                     ELSE i_group_id = ANY(SELECT UNNEST(v_sub_group_id))
                     END
            AND CASE WHEN i_is_search THEN NOD.node_id IN (SELECT unnest (v_node_id)) ELSE 1 = 1 END
            ORDER BY node_id
            OFFSET i_offset LIMIT i_limit;
        END IF;
    END IF;
END;
$$;


ALTER FUNCTION public.sp_get_agent_status_agent_info_oltp(i_group_id bigint, i_node_id bigint[], i_is_include_all_sub_groups boolean, i_offset bigint, i_limit bigint, i_ip_search_range boolean[], i_ip_range_from text[], i_ip_range_to text[], i_is_search boolean, i_admin_id text) OWNER TO cppoltp;

--
-- Name: sp_get_agent_status_filter(bigint[], text, text, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_status_filter(i_node_id_arr bigint[], i_filter_json text, i_product_auth text, i_dashboard_layout text, i_admin_group text) RETURNS TABLE(node_id_arr bigint[])
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_node_id_arr       bigint[];
  v_target            TEXT;
  v_type              en_agent_status_link_type;
  v_values            TEXT[];
  v_link_node         bigint[];
  v_correlation_node  bigint[];
BEGIN

    IF i_node_id_arr is null then

      FOR v_target IN
      -- logical_target 조회
      SELECT json_array_elements(i_filter_json::json) AS logical_target

      LOOP
        -- type 추출
        SELECT trim(type::text, '"')
        INTO v_type
        FROM (SELECT v_target::json -> 'type' AS type) AS type;

        -- values 추출
        SELECT array_agg(trim(VALUES::TEXT, '"')) into v_values
          FROM json_array_elements((SELECT v_target::json -> 'values' AS VALUES)::json) AS values;

        IF v_type = 'DASHBOARD' THEN

          SELECT node_id INTO v_link_node FROM sp_get_dashboard_link_node_list( v_values[1], i_product_auth, i_dashboard_layout);

        ELSIF v_type = 'CUSTOM_DASHBOARD' THEN

        /*
          type : CUSTOM_DASHBOARD
          , values : [group_id, widget_item_sub_type, language]
          , 연계규칙은 아래에서 연동 (기존 링크 방식 따르기 위함)
         */
          SELECT
            ARRAY_AGG(node_id) INTO v_link_node
          FROM
            sp_get_custom_dashboard_widget_link_node_list(
              (CASE WHEN v_values[1] = 'null' THEN NULL ELSE v_values[1]::bigint END) /* group_id */
              , 0   /* correlation_id */
              , v_values[2]::text[] /* widget_item_sub_type */
              , v_values[3]::en_language
              , i_product_auth)
          ;

        ELSIF v_type = 'V3' THEN
          SELECT node_id INTO v_link_node FROM sp_get_v3_link_node_list(v_values[1]::en_v3_link_param, v_values[2]::en_product_id_type, CASE WHEN array_length(v_values,1) > 2 THEN v_values[3]::en_platform_type[] ELSE NULL END);
        ELSIF v_type = 'SW' THEN
          SELECT node_id INTO v_link_node FROM sp_get_sw_link_node_list(v_values[1]::text, v_values[2]::text, v_values[3]::text);
        ELSIF v_type = 'CORRELATION' THEN
          SELECT array_agg(target_id) INTO v_correlation_node FROM sp_get_correlation_rule_group(v_values[1]::BIGINT);
        ELSIF v_type = 'LICENSE' THEN
          IF 'EMS' = (SELECT tml.product_id FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT) THEN
            IF '1.0' = (SELECT tml.version FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT) THEN
                SELECT array_agg(ts.node_id) INTO v_link_node FROM tb_node_status ts INNER JOIN tb_node tn ON ts.node_id = tn.node_id AND tn.is_removed IS FALSE WHERE ts.license_no = (SELECT tml.license_no FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT);
            ELSIF '2.0' = (SELECT tml.version FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT) THEN
                SELECT array_agg(ts.node_id) INTO v_link_node FROM tb_node_status ts INNER JOIN tb_node tn ON ts.node_id = tn.node_id AND tn.is_removed IS FALSE WHERE ts.activation_code = (SELECT tml.license_no FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT);
            END IF;
        
          ELSIF 'V3NET_9.0' = (SELECT tml.product_id FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT) THEN
            IF '1.0' = (SELECT tml.version FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT) THEN
                SELECT array_agg(ts.node_id) INTO v_link_node FROM tb_v3_status ts INNER JOIN tb_node tn ON ts.node_id = tn.node_id AND tn.is_removed IS FALSE INNER JOIN tb_product_info tpn ON ts.node_id = tpn.node_id AND tpn.product_id = 'V3NET_9.0'::en_product_id_type WHERE ts.license_no = (SELECT tml.license_no FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT) AND ts.product_id = 'V3NET_9.0';
            ELSIF '2.0' = (SELECT tml.version FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT) THEN
                SELECT array_agg(ts.node_id) INTO v_link_node FROM tb_v3_status ts INNER JOIN tb_node tn ON ts.node_id = tn.node_id AND tn.is_removed IS FALSE INNER JOIN tb_product_info tpn ON ts.node_id = tpn.node_id AND tpn.product_id = 'V3NET_9.0'::en_product_id_type WHERE ts.activation_code = (SELECT tml.license_no FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT) AND ts.product_id = 'V3NET_9.0';
            END IF;
          
          ELSIF 'V3NET_LU' = (SELECT tml.product_id FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT) THEN
            IF '1.0' = (SELECT tml.version FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT) THEN
                SELECT array_agg(ts.node_id) INTO v_link_node FROM tb_v3_status ts INNER JOIN tb_node tn ON ts.node_id = tn.node_id AND tn.is_removed IS FALSE INNER JOIN tb_product_info tpn ON ts.node_id = tpn.node_id AND tpn.product_id = 'V3NET_LU'::en_product_id_type WHERE ts.license_no = (SELECT tml.license_no FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT) AND ts.product_id = 'V3NET_LU';
            ELSIF '2.0' = (SELECT tml.version FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT) THEN
                SELECT array_agg(ts.node_id) INTO v_link_node FROM tb_v3_status ts INNER JOIN tb_node tn ON ts.node_id = tn.node_id AND tn.is_removed IS FALSE INNER JOIN tb_product_info tpn ON ts.node_id = tpn.node_id AND tpn.product_id = 'V3NET_LU'::en_product_id_type WHERE ts.activation_code = (SELECT tml.license_no FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT) AND ts.product_id = 'V3NET_LU';
            END IF;

          ELSIF 'AMC_CLIENT' = (SELECT tml.product_id FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT) THEN
            IF '1.0' = (SELECT tml.version FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT) THEN
                SELECT array_agg(ts.node_id) INTO v_link_node FROM tb_v3_status ts INNER JOIN tb_node tn ON ts.node_id = tn.node_id AND tn.is_removed IS FALSE INNER JOIN tb_product_info tpn ON ts.node_id = tpn.node_id AND tpn.product_id = 'AMC_CLIENT'::en_product_id_type WHERE ts.license_no = (SELECT tml.license_no FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT) AND ts.product_id = 'AMC_CLIENT';
            ELSIF '2.0' = (SELECT tml.version FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT) THEN
                SELECT array_agg(ts.node_id) INTO v_link_node FROM tb_v3_status ts INNER JOIN tb_node tn ON ts.node_id = tn.node_id AND tn.is_removed IS FALSE INNER JOIN tb_product_info tpn ON ts.node_id = tpn.node_id AND tpn.product_id = 'AMC_CLIENT'::en_product_id_type WHERE ts.activation_code = (SELECT tml.license_no FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT) AND ts.product_id = 'AMC_CLIENT';
            END IF;
        
          ELSIF 'AC_CLIENT' = (SELECT tml.product_id FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT) THEN
            IF '1.0' = (SELECT tml.version FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT) THEN
                SELECT array_agg(ts.node_id) INTO v_link_node FROM tb_ac_status ts INNER JOIN tb_node tn ON ts.node_id = tn.node_id AND tn.is_removed IS FALSE INNER JOIN tb_product_info tpn ON ts.node_id = tpn.node_id AND tpn.product_id = 'AC_CLIENT'::en_product_id_type WHERE ts.license_no = (SELECT tml.license_no FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT);
            ELSIF '2.0' = (SELECT tml.version FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT) THEN
                SELECT array_agg(ts.node_id) INTO v_link_node FROM tb_ac_status ts INNER JOIN tb_node tn ON ts.node_id = tn.node_id AND tn.is_removed IS FALSE INNER JOIN tb_product_info tpn ON ts.node_id = tpn.node_id AND tpn.product_id = 'AC_CLIENT'::en_product_id_type WHERE ts.activation_code = (SELECT tml.license_no FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT);
            END IF;
        
          ELSIF 'HIPS_CLIENT' = (SELECT tml.product_id FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT) THEN
            IF '1.0' = (SELECT tml.version FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT) THEN
                SELECT array_agg(ts.node_id) INTO v_link_node FROM tb_hips_status ts INNER JOIN tb_node tn ON ts.node_id = tn.node_id AND tn.is_removed IS FALSE INNER JOIN tb_product_info tpn ON ts.node_id = tpn.node_id AND tpn.product_id = 'HIPS_CLIENT'::en_product_id_type WHERE ts.license_no = (SELECT tml.license_no FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT);
            ELSIF '2.0' = (SELECT tml.version FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT) THEN
                SELECT array_agg(ts.node_id) INTO v_link_node FROM tb_hips_status ts INNER JOIN tb_node tn ON ts.node_id = tn.node_id AND tn.is_removed IS FALSE INNER JOIN tb_product_info tpn ON ts.node_id = tpn.node_id AND tpn.product_id = 'HIPS_CLIENT'::en_product_id_type WHERE ts.activation_code = (SELECT tml.license_no FROM tb_multi_license tml WHERE tml.license_id = v_values[1]::BIGINT);
            END IF;
          END IF;
        
        END IF;

        IF v_node_id_arr IS NULL THEN
          v_node_id_arr := v_link_node;
        ELSE
          SELECT array_agg(node_id::bigint order by node_id) INTO v_node_id_arr
            FROM (SELECT DISTINCT unnest(array_intersect(v_node_id_arr, v_correlation_node)) AS node_id) AS t(node_id);
        END IF;

      END LOOP;

    ELSE
      IF i_filter_json IS NULL THEN
        v_node_id_arr := i_node_id_arr;
      ELSE

        -- 커스텀 대시보드일때는 node_id 파라미터가 있을 경우 node_id를 셋팅하고, json filter를 무시한다.
        IF (SELECT (array_agg(t.type))[1] = 'CUSTOM_DASHBOARD' FROM(
              SELECT json_array_elements(i_filter_json::json)->>'type' AS type
            ) t) THEN

            v_node_id_arr := i_node_id_arr;

        ELSE

          SELECT array_agg(trim(VALUES::TEXT, '"')) into v_values
            FROM json_array_elements((SELECT json_array_elements(i_filter_json::json)::json -> 'values' AS VALUES)::json) AS values;

          SELECT array_agg(target_id) INTO v_correlation_node FROM sp_get_correlation_rule_group(v_values[1]::bigint);
          v_node_id_arr := array_intersect(i_node_id_arr, v_correlation_node);

        END IF;

      END IF;
    END IF;

    RETURN QUERY
      SELECT v_node_id_arr;

END;
$$;


