--
-- Name: sp_get_agent_status_group_issue_agent(bigint[], text[], text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_status_group_issue_agent(i_group_id_arr bigint[], i_node_id text[], i_product_auth text, i_dashboard_layout text) RETURNS TABLE(group_id bigint, license_expired bigint, abnormal_integrity bigint, policy_not_applied bigint, product_not_install bigint, v3_not_new_engine bigint, not_manual_scan bigint, malware_scan_30_days bigint, realtime_scan_off bigint, im_manual_rulecheck_not_execute bigint, scm_manual_scan_not_execute bigint, v3_service_status_off bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
  v_limit                     integer := 10;
  v_dashboard_layout          TEXT[];
BEGIN

-- dashboard layout
  IF i_dashboard_layout IS NULL THEN
    SELECT string_to_array('v3_not_install,v3_not_new_engine,not_manual_scan,realtime_scan_off,v3_policy_not_applied,malware_scan_30_days,v3_license_expired,v3_abnormal_integrity,ac_not_install,ac_license_expired,ac_abnormal_integrity,ac_policy_not_applied,im_policy_not_applied,im_manual_rulecheck_not_execute,hips_not_install,hips_license_expired,hips_abnormal_integrity,hips_policy_not_applied,scm_not_install,scm_license_expired,scm_abnormal_integrity,scm_policy_not_applied,scm_manual_scan_not_execute,v3_service_status_off', ',') INTO v_dashboard_layout;
  ELSE
    SELECT string_to_array(i_dashboard_layout, ',') INTO v_dashboard_layout;
  END IF;

  RETURN QUERY

    WITH group_table AS (
      SELECT unnest(i_group_id_arr) AS group_id, unnest(string_to_array(unnest(i_node_id),'||'))::bigint AS node_id
    )
    SELECT  g.group_id
            ,COUNT(CASE WHEN(
                             iand.v3_license_expired IS TRUE AND 'v3_license_expired' = ANY(v_dashboard_layout)
                          OR iand.ac_license_expired IS TRUE AND 'ac_license_expired' = ANY(v_dashboard_layout)
                          OR iand.hips_license_expired IS TRUE AND 'hips_license_expired' = ANY(v_dashboard_layout)
                          OR iand.scm_license_expired IS TRUE AND 'scm_license_expired' = ANY(v_dashboard_layout)
                            )
                       THEN 1 END) AS license_expired
            ,COUNT(CASE WHEN (
                             iand.v3_abnormal_integrity IS TRUE AND 'v3_abnormal_integrity' = ANY(v_dashboard_layout)
                          OR iand.ac_abnormal_integrity IS TRUE AND 'ac_abnormal_integrity' = ANY(v_dashboard_layout)
                          OR iand.hips_abnormal_integrity IS TRUE AND 'hips_abnormal_integrity' = ANY(v_dashboard_layout)
                          OR iand.scm_abnormal_integrity IS TRUE AND 'scm_abnormal_integrity' = ANY(v_dashboard_layout)
                             )
                        THEN 1 END) AS abnormal_integrity
            ,COUNT(CASE WHEN (
                             iand.v3_policy_not_applied IS TRUE AND 'v3_policy_not_applied' = ANY(v_dashboard_layout)
                          OR iand.ac_policy_not_applied IS TRUE AND 'ac_policy_not_applied' = ANY(v_dashboard_layout)
                          OR iand.im_policy_not_applied IS TRUE AND 'im_policy_not_applied' = ANY(v_dashboard_layout)
                          OR iand.hips_policy_not_applied IS TRUE AND 'hips_policy_not_applied' = ANY(v_dashboard_layout)
                          OR iand.scm_policy_not_applied IS TRUE AND 'scm_policy_not_applied' = ANY(v_dashboard_layout)
                             )
                        THEN 1 END) AS policy_not_applied
            ,COUNT(CASE WHEN (
                             iand.v3_not_install_server IS TRUE AND 'v3_not_install' = ANY(v_dashboard_layout)
                          OR iand.v3_not_install_desktop IS TRUE AND 'v3_not_install' = ANY(v_dashboard_layout)
                          OR iand.ac_not_install IS TRUE AND 'ac_not_install' = ANY(v_dashboard_layout)
                          OR iand.hips_not_install IS TRUE AND 'hips_not_install' = ANY(v_dashboard_layout)
                          OR iand.scm_not_install IS TRUE AND 'scm_not_install' = ANY(v_dashboard_layout)
                             )
                        THEN 1 END ) AS product_not_install
            ,COUNT(CASE WHEN iand.v3_not_new_engine AND 'v3_not_new_engine' = ANY(v_dashboard_layout) THEN 1 END)
            ,COUNT(CASE WHEN iand.not_manual_scan AND 'not_manual_scan' = ANY(v_dashboard_layout) THEN 1 END)
            ,COUNT(CASE WHEN iand.malware_scan_30_days AND 'malware_scan_30_days' = ANY(v_dashboard_layout) THEN 1 END)
            ,COUNT(CASE WHEN iand.realtime_scan_off AND 'realtime_scan_off' = ANY(v_dashboard_layout) THEN 1 END)
            ,COUNT(CASE WHEN iand.im_manual_rulecheck_not_execute AND 'im_manual_rulecheck_not_execute' = ANY(v_dashboard_layout) THEN 1 END)
            ,COUNT(CASE WHEN iand.scm_manual_scan_not_execute AND 'scm_manual_scan_not_execute' = ANY(v_dashboard_layout) THEN 1 END)
            ,COUNT(CASE WHEN iand.v3_service_status = 'OFF' AND 'v3_service_status_off' = ANY(v_dashboard_layout) THEN 1 END)
       FROM sp_get_issue_agent_node_data (i_product_auth) AS iand
       JOIN tb_node n ON n.node_id = iand.node_id
       JOIN group_table g ON n.node_id = g.node_id
       WHERE n.is_removed IS FALSE
       GROUP BY g.group_id
    ;

END;
$$;


ALTER FUNCTION public.sp_get_agent_status_group_issue_agent(i_group_id_arr bigint[], i_node_id text[], i_product_auth text, i_dashboard_layout text) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_agent_status_group_issue_agent(i_group_id_arr bigint[], i_node_id text[], i_product_auth text, i_dashboard_layout text); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_agent_status_group_issue_agent(i_group_id_arr bigint[], i_node_id text[], i_product_auth text, i_dashboard_layout text) IS '
@brief [SWD-SCI1052] 에이전트 현황 에이전트 이슈 정보(그룹 보기)
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_agent_status_issue_agent(bigint[], text, text, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_status_issue_agent(i_node_id_arr bigint[], i_filter_json text, i_product_auth text, i_dashboard_layout text, i_admin_group text) RETURNS TABLE(node_id bigint, connection_status public.en_connection_status, product_not_install bigint, v3_not_new_engine boolean, engine_version text, service_status public.en_product_service_status, not_manual_scan boolean, last_scan_time timestamp without time zone, realtime_scan_off boolean, policy_not_applied bigint, malware_scan_30_days integer, license_expired bigint, abnormal_integrity bigint, im_manual_rulecheck_not_execute boolean, im_manual_time timestamp without time zone, scm_manual_scan_not_execute boolean, scm_scan_time timestamp without time zone)
    LANGUAGE plpgsql
    AS $$

DECLARE
  v_engine_update_threshold   INTEGER := 0;
  v_oes_engine_date           TIMESTAMP := '9999.12.31'::TIMESTAMP;
  v_ses_engine_date           TIMESTAMP := '9999.12.31'::TIMESTAMP;
  v_manual_scan_threshold     INTEGER := 0;
  v_im_manual_rulecheck_day_interval INTEGER := 0;
  v_scm_manual_scan_day_interval INTEGER := 0;
  v_node_id_arr               BIGINT[];

  v_product_auth              en_product_group_type[];
  v_auth_v3                   BOOLEAN := FALSE;
  v_auth_ac                   BOOLEAN := FALSE;
  v_auth_hips                 BOOLEAN := FALSE;
  v_auth_scm                 BOOLEAN := FALSE;  

  v_available_group_id bigint[];
  v_sub_group_id bigint[];

BEGIN
    
  SELECT string_to_array(i_admin_group,',')::bigint[] AS group_id
  INTO v_available_group_id;
  
  WITH RECURSIVE sub_group_id (group_id, pgroup_id) AS 
  (
    SELECT tg.group_id
            ,tg.pgroup_id
    FROM (
        SELECT tg.group_id
            ,tg.pgroup_id
        FROM tb_group tg
        WHERE tg.is_removed = FALSE
          AND tg.group_id = ANY(v_available_group_id)
            ) tg
    UNION DISTINCT
    SELECT tg.group_id
            ,tg.pgroup_id
    FROM tb_group tg 
        INNER JOIN sub_group_id vgi
            ON vgi.group_id = tg.pgroup_id
    WHERE tg.is_removed = FALSE
  )
  SELECT ARRAY_AGG(vgi.group_id) AS group_id
  INTO v_sub_group_id
  FROM sub_group_id vgi;

  -- 엔진 업데이트 임계치
  SELECT GREATEST(COALESCE(MAX(c.value), '0')::integer -1, 0) INTO v_engine_update_threshold
    FROM tb_config AS c
   WHERE c.config_group = 'AGENT_THRESHOLD' AND c.key = 'engine_update_threshold'
   ;

  -- 수동 검사 임계치
  SELECT GREATEST(COALESCE(MAX(c.value), '0')::integer, 0) INTO v_manual_scan_threshold
  FROM tb_config AS c
  WHERE c.config_group = 'AGENT_THRESHOLD' AND c.key = 'manual_scan_threshold'
  ;

  -- 최신 엔진 버전(일자)
  SELECT TO_CHAR(SUBSTRING(MAX(case when key = 'oes_engine_date' THEN c.value END), 1, 10)::timestamp - (v_engine_update_threshold || ' day')::interval, 'YYYY.MM.DD')::timestamp AS oes_engine_date,
         TO_CHAR(SUBSTRING(MAX(case when key = 'ses_engine_date' THEN c.value END), 1, 10)::timestamp - (v_engine_update_threshold || ' day')::interval, 'YYYY.MM.DD')::timestamp AS ses_engine_date
    INTO v_oes_engine_date, v_ses_engine_date
    FROM tb_config AS c
   WHERE c.config_group = 'UPDATE_SERVICE'
   ;
   
  -- IM 무결성모니터링 수동검사 보안점검 설정 값
  SELECT    GREATEST(COALESCE(MAX(c.value), '0')::integer, 0)
  INTO      v_im_manual_rulecheck_day_interval
  FROM      tb_config AS c
  WHERE     c.config_group = 'AGENT_THRESHOLD' AND c.key = 'im_manual_rulecheck_day_interval'
  ;
  
  -- SCM 수동검사 보안점검 설정 값
  SELECT    GREATEST(COALESCE(MAX(c.value), '0')::integer, 0)
  INTO      v_scm_manual_scan_day_interval
  FROM      tb_config AS c
  WHERE     c.config_group = 'AGENT_THRESHOLD' AND c.key = 'manual_scan_day_interval'
  ;

  IF i_product_auth IS NOT NULL AND LENGTH(TRIM(i_product_auth)) > 0 THEN
    v_product_auth := STRING_TO_ARRAY(REPLACE(i_product_auth, ' ', ''), ',')::en_product_group_type[];
  ELSE
    SELECT ENUM_RANGE(null::en_product_group_type) INTO v_product_auth;
  END IF;

  -- 권한 처리
  v_auth_v3   := (sp_exist_license('V3') AND ('V3' = ANY(v_product_auth)));
  v_auth_ac   := (sp_exist_license('AC') AND ('AC' = ANY(v_product_auth)));
  v_auth_hips := (sp_exist_license('HIPS') AND ('HIPS' = ANY(v_product_auth)));
  v_auth_scm := (sp_exist_license('SCM') AND ('SCM' = ANY(v_product_auth)));  

  v_node_id_arr := sp_get_agent_status_filter(i_node_id_arr, i_filter_json, i_product_auth, i_dashboard_layout, i_admin_group);

  RETURN QUERY

     WITH tb_node_platform AS (
       SELECT  n.node_id
              ,p.is_server
              ,p.platform_type
              , CASE WHEN n.machine_type != 'CONTAINER' THEN TRUE
                     WHEN n.machine_type = 'CONTAINER' AND tcp.is_amc_supported IS TRUE THEN TRUE
                     ELSE FALSE
                END AS is_am_supported
              , CASE WHEN n.machine_type != 'CONTAINER' THEN TRUE
                     WHEN n.machine_type = 'CONTAINER' AND tcp.is_hips_supported IS TRUE THEN TRUE
                     ELSE FALSE
                END AS is_hips_supported
              , CASE WHEN n.machine_type != 'CONTAINER' THEN TRUE
                     WHEN n.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS TRUE THEN TRUE
                     ELSE FALSE
                END AS is_ac_supported
         FROM tb_node n
         JOIN tb_platform p ON n.platform_id = p.platform_id
         LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = n.container_service_type
        WHERE n.is_removed IS FALSE
          AND p.is_supported IS TRUE
          AND n.node_id = ANY(SELECT UNNEST(v_node_id_arr))
          AND n.group_id = ANY(SELECT UNNEST(v_sub_group_id))
     )
     SELECT n.node_id
           ,COALESCE(NOS.connection_status, 'UNINSTALLED'::en_connection_status) AS connection_status
           ,COALESCE(product_not_install.cnt, 0)
           ,CASE WHEN v3_not_new_engine.node_id IS NULL THEN NULL ELSE v3_not_new_engine.is_new_engine END
           ,v3_engine_version.engine_version
           ,v3_engine_version.service_status
           ,CASE WHEN not_manual_scan.node_id IS NULL THEN NULL ELSE not_manual_scan.is_manual_scan END
           ,last_scan_time.last_scan_time
           ,CASE WHEN realtime_scan_off.node_id IS NULL THEN NULL ELSE realtime_scan_off.is_realtime_scan_off END
           ,COALESCE(policy_not_applied.cnt, 0)
           ,CASE WHEN malware_scan_30_days.node_id IS NULL THEN NULL ELSE malware_scan_30_days.cnt END
           ,COALESCE(license_expired.cnt, 0)
           ,COALESCE(abnormal_integrity.cnt, 0)
           ,CASE WHEN im_manual_rulecheck_not_execute.node_id IS NULL THEN NULL ELSE im_manual_rulecheck_not_execute.is_manual_scan END
           ,im_manual_rulecheck_time.im_manual_time
           ,CASE WHEN scm_manual_scan_not_execute.node_id IS NULL THEN NULL ELSE scm_manual_scan_not_execute.is_manual_scan END
           ,scm_manual_scan_time.scan_time
       FROM tb_node_platform n
       --보안 제품 미설치
       LEFT JOIN (
        SELECT  t.node_id
               ,COUNT(1) as cnt
          FROM (
            -- V3 미설치
            SELECT n.node_id
            FROM tb_node_platform n
            WHERE v_auth_v3
              AND n.is_am_supported IS TRUE
              AND NOT EXISTS (
                SELECT pi.node_id
                FROM tb_product_info AS pi
                  INNER JOIN tb_product AS p ON p.product_id = pi.product_id
                WHERE p.product_group = 'V3'
                  AND pi.node_id = n.node_id
                  AND n.is_am_supported IS TRUE
               )
            UNION ALL
            -- AC 미설치
            SELECT n.node_id
            FROM tb_node_platform n
            WHERE v_auth_ac
              AND n.is_ac_supported IS TRUE
              AND NOT EXISTS (
                SELECT pi.node_id
                FROM tb_product_info AS pi
                  INNER JOIN tb_product AS p ON p.product_id = pi.product_id
                WHERE p.product_group = 'AC'
                  AND pi.node_id = n.node_id
                  AND n.is_ac_supported IS TRUE
               )
            UNION ALL
            -- HIPS 미설치
            SELECT n.node_id
            FROM tb_node_platform n
            WHERE v_auth_hips
              AND n.is_hips_supported IS TRUE
              AND NOT EXISTS (
                SELECT pi.node_id
                FROM tb_product_info AS pi
                  INNER JOIN tb_product AS p ON p.product_id = pi.product_id
                WHERE p.product_group = 'HIPS'
                  AND pi.node_id = n.node_id
                  AND n.is_hips_supported IS TRUE
               )
            UNION ALL
            -- SCM 미설치
            SELECT n.node_id
            FROM tb_node_platform n
            WHERE v_auth_scm
              AND NOT EXISTS (
                SELECT pi.node_id
                FROM tb_product_info AS pi
                  INNER JOIN tb_product AS p ON p.product_id = pi.product_id
                WHERE p.product_group = 'SCM'
                  AND pi.node_id = n.node_id
               )   
        ) AS t
        GROUP BY t.node_id
      ) AS product_not_install ON n.node_id = product_not_install.node_id
      --최신 엔진 미설치
      LEFT JOIN
        (
          SELECT pi.node_id, COALESCE(pi.node_id <> vs.node_id, TRUE) AS is_new_engine
            FROM tb_product_info AS pi
            JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'V3'
            LEFT JOIN (
                SELECT
                    vs.node_id, vs.product_id
                    , CASE vs.engine_type WHEN 'SES' THEN vs.engine_update_time >= v_ses_engine_date
                    ELSE engine_update_time >= v_oes_engine_date END is_updated_engine
                FROM
                    tb_v3_status vs
            ) vs ON pi.node_id = vs.node_id AND pi.product_id = vs.product_id AND vs.is_updated_engine IS TRUE
           WHERE v_auth_v3
      ) AS v3_not_new_engine on n.node_id = v3_not_new_engine.node_id
      --설치 엔진 버전
      LEFT JOIN (
        SELECT vs.node_id
              ,vs.engine_version
              ,vs.service_status
          FROM tb_product_info AS pi
          JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'V3'
          JOIN tb_v3_status vs ON vs.node_id = pi.node_id AND vs.product_id = pi.product_id
         WHERE v_auth_v3
      ) AS v3_engine_version on n.node_id = v3_engine_version.node_id
      --최근 수동 검사 미실행
      LEFT JOIN (
         SELECT pi.node_id, COALESCE(pi.node_id <> vs.node_id, TRUE) AS is_manual_scan
           FROM tb_product_info AS pi
           JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'V3'
           LEFT JOIN (
             SELECT v.node_id, v.product_id
               FROM tb_v3_status AS v
               JOIN tb_product_info AS pi ON v.node_id = pi.node_id AND v.product_id = pi.product_id
               JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'V3'
              WHERE v_auth_v3
                AND v.last_scan_time >= date_trunc('day', now()) - (v_manual_scan_threshold -1 || 'day')::INTERVAL
           ) vs ON pi.node_id = vs.node_id AND pi.product_id = vs.product_id
      ) AS not_manual_scan on n.node_id = not_manual_scan.node_id
      --최근 수동 검사일
      LEFT JOIN (
        SELECT  v.node_id
               ,v.last_scan_time::TIMESTAMP
          FROM tb_v3_status AS v
          JOIN tb_product_info AS pi ON pi.node_id = v.node_id AND pi.product_id = v.product_id
          JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'V3'
          WHERE v_auth_v3
      ) AS last_scan_time ON n.node_id = last_scan_time.node_id
      --실시간 검사 off
      LEFT JOIN (
        SELECT pi.node_id, COALESCE(pi.node_id <> vs.node_id, TRUE) AS is_realtime_scan_off
           FROM tb_product_info AS pi
           JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'V3'
           LEFT JOIN (
             SELECT v.node_id, v.product_id
               FROM tb_v3_status AS v
              WHERE v_auth_v3
                AND v.realtime_status IS TRUE
           ) vs ON pi.node_id = vs.node_id AND pi.product_id = vs.product_id
      ) AS realtime_scan_off on n.node_id = realtime_scan_off.node_id
      --정책 미적용
      LEFT JOIN (
        SELECT  t.node_id
               ,COUNT(1) AS cnt
          FROM (
            SELECT ps.node_id
              FROM tb_node_platform n
              JOIN vw_policy_status AS ps ON n.node_id = ps.node_id
              JOIN tb_product_feature_map AS pf ON pf.product_feature_id = ps.product_feature_id AND pf.product_feature_id <> 'V3NET_LU_UPDATE'
              JOIN tb_product AS p ON p.product_id = pf.product_id AND p.product_group = 'V3'
             WHERE v_auth_v3
               AND ps.policy_status = 'NOT_APPLIED'
               AND n.is_am_supported IS TRUE
            UNION ALL
            SELECT ps.node_id
              FROM tb_node_platform n
              JOIN vw_policy_status AS ps ON n.node_id = ps.node_id
              JOIN tb_product_feature_map AS pf ON pf.product_feature_id = ps.product_feature_id
              JOIN tb_product AS p ON p.product_id = pf.product_id AND p.product_group = 'AC'
             WHERE v_auth_ac
               AND ps.policy_status = 'NOT_APPLIED'
               AND ps.product_feature_id IN ('AC_AGENT', 'AC_MGMT')
               AND n.is_ac_supported IS TRUE
            UNION ALL
            SELECT ps.node_id
              FROM tb_node_platform n
              JOIN vw_policy_status AS ps ON n.node_id = ps.node_id
              JOIN tb_product_feature_map AS pf ON pf.product_feature_id = ps.product_feature_id
              JOIN tb_product AS p ON p.product_id = pf.product_id AND p.product_group = 'AC'
             WHERE v_auth_ac
               AND ps.policy_status = 'NOT_APPLIED'
               AND ps.product_feature_id IN ('IM_MGMT')
               AND n.is_ac_supported IS TRUE
            UNION ALL
            SELECT ps.node_id
              FROM tb_node_platform n
              JOIN vw_policy_status AS ps ON n.node_id = ps.node_id
              JOIN tb_product_feature_map AS pf ON pf.product_feature_id = ps.product_feature_id
              JOIN tb_product AS p ON p.product_id = pf.product_id AND p.product_group = 'HIPS'
             WHERE v_auth_hips
               AND ps.policy_status = 'NOT_APPLIED'
               AND n.is_hips_supported IS TRUE
            UNION ALL
            SELECT ps.node_id
              FROM tb_node_platform n
              JOIN vw_policy_status AS ps ON n.node_id = ps.node_id
              JOIN tb_product_feature_map AS pf ON pf.product_feature_id = ps.product_feature_id
              JOIN tb_product AS p ON p.product_id = pf.product_id AND p.product_group = 'SCM'
             WHERE v_auth_scm
               AND ps.policy_status = 'NOT_APPLIED'
               AND n.is_hips_supported IS TRUE
          ) as t
          GROUP BY t.node_id
      ) AS policy_not_applied on n.node_id = policy_not_applied.node_id
      --악성코드 탐지 (최근 30일)
      LEFT JOIN (
         SELECT pi.node_id, COALESCE(cnt, 0)::INTEGER AS cnt
           FROM tb_product_info AS pi
           JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'V3'
           LEFT JOIN (
             SELECT v.node_id, sum(COALESCE(v.malware_clean_count,0) +  COALESCE(v.malware_clean_fail_count,0)) AS cnt
               FROM tb_timeline_v3 AS v
              WHERE v_auth_v3
                AND v.reg_date BETWEEN TO_CHAR(now() - '29 DAY'::interval, 'YYYYMMDD') AND TO_CHAR(now(), 'YYYYMMDD')
                AND (COALESCE(v.malware_clean_count,0) > 0 OR  COALESCE(v.malware_clean_fail_count,0) > 0)
              GROUP BY v.node_id
           ) vs ON pi.node_id = vs.node_id
      ) AS malware_scan_30_days on n.node_id = malware_scan_30_days.node_id
      --라이선스 만료
      LEFT JOIN (
        SELECT vw.node_id
              ,count(1) AS cnt
          FROM (
            SELECT v.node_id
              FROM (
                SELECT
                    vs.node_id
                    , vs.product_id
                    , CASE
                        WHEN vs.activation_code IS NOT NULL AND vs.activation_code != '' THEN vs.activation_code 
                        WHEN vs.license_no IS NOT NULL AND vs.license_no != '' THEN vs.license_no
                        ELSE NULL
                        END AS license_no
                FROM tb_v3_status vs
              ) AS v
              JOIN tb_product_info AS pi ON v.node_id = pi.node_id AND v.product_id = pi.product_id
              JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'V3'
              LEFT JOIN tb_multi_license AS pl ON pl.product_id = pi.product_id AND v.license_no = pl.license_no
             WHERE v_auth_v3
               AND (pl.expire_date < CURRENT_DATE OR pl.expire_date IS NULL)
            UNION ALL
            SELECT v.node_id
              FROM (
                SELECT
                    ac.node_id
                    , ac.product_id
                    , CASE
                        WHEN ac.activation_code IS NOT NULL AND ac.activation_code != '' THEN ac.activation_code 
                        WHEN ac.license_no IS NOT NULL AND ac.license_no != '' THEN ac.license_no
                        ELSE NULL
                        END AS license_no
                FROM tb_ac_status ac
              ) AS v
              JOIN tb_product_info AS pi ON v.node_id = pi.node_id AND v.product_id = pi.product_id
              JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'AC'
              LEFT JOIN tb_multi_license AS pl ON pl.product_id = pi.product_id AND v.license_no = pl.license_no
             WHERE v_auth_ac
               AND (pl.expire_date < CURRENT_DATE OR pl.expire_date IS NULL)
            UNION ALL
            SELECT v.node_id
              FROM (
                SELECT
                    hs.node_id
                    , hs.product_id
                    , CASE
                        WHEN hs.activation_code IS NOT NULL AND hs.activation_code != '' THEN hs.activation_code 
                        WHEN hs.license_no IS NOT NULL AND hs.license_no != '' THEN hs.license_no
                        ELSE NULL
                        END AS license_no
                FROM tb_hips_status hs
              ) AS v
              JOIN tb_product_info AS pi ON v.node_id = pi.node_id AND v.product_id = pi.product_id
              JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'HIPS'
              LEFT JOIN tb_multi_license AS pl ON pl.product_id = pi.product_id AND v.license_no = pl.license_no
             WHERE v_auth_hips
               AND (pl.expire_date < CURRENT_DATE OR pl.expire_date IS NULL)
            UNION ALL
            SELECT v.node_id
              FROM tb_scm_status AS v
              JOIN tb_product_info AS pi ON v.node_id = pi.node_id AND v.product_id = pi.product_id
              JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'SCM'
              LEFT JOIN tb_multi_license AS pl ON pl.product_id = pi.product_id
             WHERE v_auth_scm
               AND (pl.expire_date < CURRENT_DATE OR pl.expire_date IS NULL)
          ) AS vw
         GROUP BY vw.node_id
      ) AS license_expired on n.node_id = license_expired.node_id
      --무결성 손상
      LEFT JOIN (
         SELECT vw.node_id
               ,count(1) AS cnt
           FROM (
              SELECT v.node_id
                FROM tb_node_platform AS n
                JOIN tb_v3_status AS v ON n.node_id = v.node_id
                JOIN tb_product_info AS pi ON v.node_id = pi.node_id AND v.product_id = pi.product_id
                JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'V3'
               WHERE v_auth_v3
                 AND v.integrity_status = 'ABNORMAL'
              UNION ALL
              SELECT v.node_id
                FROM tb_node_platform AS n
                JOIN tb_ac_status AS v ON n.node_id = v.node_id
                JOIN tb_product_info AS pi ON v.node_id = pi.node_id AND v.product_id = pi.product_id
                JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'AC'
               WHERE v_auth_ac
                 AND v.integrity_status = 'ABNORMAL'
              UNION ALL
              SELECT v.node_id
                FROM tb_node_platform AS n
                JOIN tb_hips_status AS v ON n.node_id = v.node_id
                JOIN tb_product_info AS pi ON v.node_id = pi.node_id AND v.product_id = pi.product_id
                JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'HIPS'
               WHERE v_auth_hips
                 AND v.integrity_status = 'ABNORMAL'
              UNION ALL
              SELECT v.node_id
                FROM tb_node_platform AS n
                JOIN tb_scm_status AS v ON n.node_id = v.node_id
                JOIN tb_product_info AS pi ON v.node_id = pi.node_id AND v.product_id = pi.product_id
                JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'SCM'
               WHERE v_auth_scm
                 AND v.integrity_status = 'ABNORMAL'
             ) AS vw
           GROUP BY vw.node_id
      ) AS abnormal_integrity on n.node_id = abnormal_integrity.node_id
      --IM 무결성모니터링 수동검사 미실행
      LEFT JOIN (
        SELECT pi.node_id, COALESCE(pi.node_id <> ac.node_id, TRUE) AS is_manual_scan
           FROM tb_product_info AS pi
           JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'AC'
           LEFT JOIN (
             SELECT ac.node_id, ac.product_id
               FROM tb_ac_status AS ac
               JOIN tb_product_info AS pi ON ac.node_id = pi.node_id AND ac.product_id = pi.product_id
               JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'AC'
          WHERE v_auth_ac
            AND ac.im_manual_time >= date_trunc('day', now()) - (v_im_manual_rulecheck_day_interval -1 || 'day')::INTERVAL
           ) ac ON pi.node_id = ac.node_id AND pi.product_id = ac.product_id
      ) AS im_manual_rulecheck_not_execute on n.node_id = im_manual_rulecheck_not_execute.node_id
      LEFT JOIN (
        SELECT n.node_id, ac.im_manual_time::TIMESTAMP
          FROM tb_node_platform n
          JOIN tb_product_info pi ON n.node_id = pi.node_id
          JOIN tb_product AS p ON pi.product_id = p.product_id AND p.product_group = 'AC'
          LEFT JOIN tb_ac_status ac ON n.node_id = ac.node_id AND pi.product_id = ac.product_id
         WHERE v_auth_ac
      ) AS im_manual_rulecheck_time on n.node_id = im_manual_rulecheck_time.node_id
      --SCM 수동검사 미수행
      LEFT JOIN (
        SELECT pi.node_id, COALESCE(pi.node_id <> scm.node_id, TRUE) AS is_manual_scan
           FROM tb_product_info AS pi
           JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'SCM'
           LEFT JOIN (
             SELECT scm.node_id, scm.product_id
               FROM tb_scm_status AS scm
               JOIN tb_product_info AS pi ON scm.node_id = pi.node_id AND scm.product_id = pi.product_id
               JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'SCM'
          WHERE v_auth_scm
            AND scm.scan_time >= date_trunc('day', now()) - (v_scm_manual_scan_day_interval -1 || 'day')::INTERVAL
           ) scm ON pi.node_id = scm.node_id AND pi.product_id = scm.product_id
      ) AS scm_manual_scan_not_execute on n.node_id = scm_manual_scan_not_execute.node_id
      LEFT JOIN (
        SELECT n.node_id, scm.scan_time::TIMESTAMP
          FROM tb_node_platform n
          JOIN tb_product_info pi ON n.node_id = pi.node_id
          JOIN tb_product AS p ON pi.product_id = p.product_id AND p.product_group = 'SCM'
          LEFT JOIN tb_scm_status scm ON n.node_id = scm.node_id AND pi.product_id = scm.product_id
         WHERE v_auth_scm
      ) AS scm_manual_scan_time on n.node_id = scm_manual_scan_time.node_id
      LEFT JOIN tb_node_status AS NOS ON n.node_id = NOS.node_id
      ;
END;
$$;


ALTER FUNCTION public.sp_get_agent_status_issue_agent(i_node_id_arr bigint[], i_filter_json text, i_product_auth text, i_dashboard_layout text, i_admin_group text) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_agent_status_issue_agent(i_node_id_arr bigint[], i_filter_json text, i_product_auth text, i_dashboard_layout text, i_admin_group text); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_agent_status_issue_agent(i_node_id_arr bigint[], i_filter_json text, i_product_auth text, i_dashboard_layout text, i_admin_group text) IS '
@brief [SWD-SCI1048] 에이전트 현황 에이전트 이슈 정보(에이전트 보기)
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_agent_status_policy_applied_info(bigint[], text, text, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_status_policy_applied_info(i_node_id_arr bigint[], i_filter_json text, i_product_auth text, i_dashboard_layout text, i_admin_group text) RETURNS TABLE(node_id bigint, connection_status public.en_connection_status, agent_policy_status public.en_policy_status, agent_policy_name text, agent_keep_agent_policy boolean, v3_product_name text, v3_policy_status public.en_policy_status, v3_policy_name text, v3_keep_agent_policy boolean, ac_agent_policy_status public.en_policy_status, ac_agent_policy_name text, ac_agent_keep_agent_policy boolean, ac_mgmt_policy_status public.en_policy_status, ac_mgmt_policy_name text, ac_mgmt_keep_agent_policy boolean, im_mgmt_policy_status public.en_policy_status, im_mgmt_policy_name text, im_mgmt_keep_agent_policy boolean, hips_agent_policy_status public.en_policy_status, hips_agent_policy_name text, hips_agent_keep_agent_policy boolean, hips_mgmt_policy_status public.en_policy_status, hips_mgmt_policy_name text, hips_mgmt_keep_agent_policy boolean, hips_fw_policy_status public.en_policy_status, hips_fw_policy_name text, hips_fw_keep_agent_policy boolean, scm_agent_policy_status public.en_policy_status, scm_agent_policy_name text, scm_agent_keep_agent_policy boolean, scm_mgmt_policy_status public.en_policy_status, scm_mgmt_policy_name text, scm_mgmt_keep_agent_policy boolean, server_time timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_node_id_arr bigint[];
BEGIN

  v_node_id_arr := sp_get_agent_status_filter(i_node_id_arr, i_filter_json, i_product_auth, i_dashboard_layout, i_admin_group);

  RETURN QUERY

  SELECT  n.node_id
         ,COALESCE(ns.connection_status, 'UNINSTALLED'::en_connection_status) AS connection_status  /* 노드 연결 상태 */
         ,agent_mgmt.policy_status AS agent_policy_status
         ,agent_mgmt.policy_name AS agent_policy_name
         ,agent_mgmt.keep_agent_policy AS agent_keep_agent_policy
         ,v3.name
         , CASE WHEN n.machine_type = 'CONTAINER' AND tcp.is_amc_supported IS FALSE THEN 'UNSUPPORTED'
                ELSE v3.policy_status
                END AS v3_policy_status
         ,v3.policy_name AS v3_policy_name
         ,v3.keep_agent_policy AS v3_keep_agent_policy
         , CASE WHEN n.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS FALSE THEN 'UNSUPPORTED'
                ELSE ac_agent.policy_status
                END AS ac_agent_policy_status
         ,ac_agent.policy_name AS ac_agent_policy_name
         ,ac_agent.keep_agent_policy AS ac_agent_keep_agent_policy
         , CASE WHEN n.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS FALSE THEN 'UNSUPPORTED'
                ELSE ac_mgmt.policy_status
                END AS ac_mgmt_policy_status
         ,ac_mgmt.policy_name AS ac_mgmt_policy_name
         ,ac_mgmt.keep_agent_policy AS ac_mgmt_keep_agent_policy
         , CASE WHEN n.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS FALSE THEN 'UNSUPPORTED'
                ELSE im_mgmt.policy_status
                END AS im_mgmt_policy_status
         ,im_mgmt.policy_name AS im_mgmt_policy_name
         ,im_mgmt.keep_agent_policy AS im_mgmt_keep_agent_policy
         , CASE WHEN n.machine_type = 'CONTAINER' AND tcp.is_hips_supported IS FALSE THEN 'UNSUPPORTED'
                ELSE hips_agent.policy_status
                END AS hips_agent_policy_status
         ,hips_agent.policy_name AS hips_agent_policy_name
         ,hips_agent.keep_agent_policy AS hips_agent_keep_agent_policy
         , CASE WHEN n.machine_type = 'CONTAINER' AND tcp.is_hips_supported IS FALSE THEN 'UNSUPPORTED'
                ELSE hips_mgmt.policy_status
                END AS hips_mgmt_policy_status
         ,hips_mgmt.policy_name AS hips_mgmt_policy_name
         ,hips_mgmt.keep_agent_policy AS hips_mgmt_keep_agent_policy
         , CASE WHEN n.machine_type = 'CONTAINER' AND tcp.is_hips_supported IS FALSE THEN 'UNSUPPORTED'
                ELSE hips_fw.policy_status
                END AS hips_fw_policy_status
         ,hips_fw.policy_name AS hips_fw_policy_name
         ,hips_fw.keep_agent_policy AS hips_fw_keep_agent_policy
         ,scm_agent.policy_status AS scm_agent_policy_status
         ,scm_agent.policy_name AS scm_agent_policy_name
         ,scm_agent.keep_agent_policy AS scm_agent_keep_agent_policy
         ,scm_mgmt.policy_status AS scm_mgmt_policy_status
         ,scm_mgmt.policy_name AS scm_mgmt_policy_name
         ,scm_mgmt.keep_agent_policy AS scm_mgmt_keep_agent_policy
         ,ns.server_time::TIMESTAMP
    FROM tb_node n
    LEFT JOIN (
      SELECT tnp.node_id, COALESCE(ps.policy_status, 'APPLYING') AS policy_status, tp.name AS policy_name, tnp.keep_agent_policy
        FROM tb_node_policy tnp
        JOIN tb_product_feature_map pfm ON tnp.product_feature_id = pfm.product_feature_id
        JOIN tb_policy tp ON tnp.policy_id = tp.policy_id
        LEFT JOIN vw_policy_status ps ON tnp.node_id = ps.node_id AND tnp.product_feature_id = ps.product_feature_id         
       WHERE pfm.product_feature_id = 'AGENT_MGMT'
    ) agent_mgmt ON n.node_id = agent_mgmt.node_id
    LEFT JOIN (
      SELECT pi.node_id, COALESCE(ps.policy_status, 'APPLYING') AS policy_status, p.name, tp.name AS policy_name, tnp.keep_agent_policy
        FROM tb_product_info pi
        JOIN tb_product AS p ON pi.product_id = p.product_id
        JOIN tb_product_feature_map pfm ON pi.product_id = pfm.product_id
        JOIN tb_node_policy tnp ON pi.node_id = tnp.node_id AND pfm.product_feature_id = tnp.product_feature_id
        JOIN tb_policy tp ON tnp.policy_id = tp.policy_id
        LEFT JOIN vw_policy_status ps ON pi.node_id = ps.node_id AND pfm.product_feature_id = ps.product_feature_id         
       WHERE p.product_group = 'V3'
         AND pfm.product_feature_id <> 'V3NET_LU_UPDATE'
         AND sp_exist_license(p.product_group)
    ) v3 ON n.node_id = v3.node_id
    LEFT JOIN (
      SELECT pi.node_id, COALESCE(ps.policy_status, 'APPLYING') AS policy_status, tp.name AS policy_name, tnp.keep_agent_policy
        FROM tb_product_info pi
        JOIN tb_product p ON pi.product_id = p.product_id
        JOIN tb_product_feature_map pfm ON pi.product_id = pfm.product_id
        JOIN tb_node_policy tnp ON pi.node_id = tnp.node_id AND pfm.product_feature_id = tnp.product_feature_id
        JOIN tb_policy tp ON tnp.policy_id = tp.policy_id
        LEFT JOIN vw_policy_status ps ON pi.node_id = ps.node_id AND pfm.product_feature_id = ps.product_feature_id
       WHERE p.product_group = 'AC'
         AND pfm.product_feature_id = 'AC_AGENT'
         AND sp_exist_license(p.product_group)
    ) ac_agent ON n.node_id = ac_agent.node_id
    LEFT JOIN (
      SELECT pi.node_id, COALESCE(ps.policy_status, 'APPLYING') AS policy_status, tp.name AS policy_name, tnp.keep_agent_policy
        FROM tb_product_info pi
        JOIN tb_product p ON pi.product_id = p.product_id
        JOIN tb_product_feature_map pfm ON pi.product_id = pfm.product_id
        JOIN tb_node_policy tnp ON pi.node_id = tnp.node_id AND pfm.product_feature_id = tnp.product_feature_id
        JOIN tb_policy tp ON tnp.policy_id = tp.policy_id
        LEFT JOIN vw_policy_status ps ON pi.node_id = ps.node_id AND pfm.product_feature_id = ps.product_feature_id
       WHERE p.product_group = 'AC'
         AND pfm.product_feature_id = 'AC_MGMT'
         AND sp_exist_license(p.product_group)
    ) ac_mgmt ON n.node_id = ac_mgmt.node_id
    LEFT JOIN (
      SELECT pi.node_id, COALESCE(ps.policy_status, 'APPLYING') AS policy_status, tp.name AS policy_name, tnp.keep_agent_policy
        FROM tb_product_info pi
        JOIN tb_product p ON pi.product_id = p.product_id
        JOIN tb_product_feature_map pfm ON pi.product_id = pfm.product_id
        JOIN tb_node_policy tnp ON pi.node_id = tnp.node_id AND pfm.product_feature_id = tnp.product_feature_id
        JOIN tb_policy tp ON tnp.policy_id = tp.policy_id
        LEFT JOIN vw_policy_status ps ON pi.node_id = ps.node_id AND pfm.product_feature_id = ps.product_feature_id
       WHERE p.product_group = 'AC'
         AND pfm.product_feature_id = 'IM_MGMT'
         AND sp_exist_license(p.product_group)
    ) im_mgmt ON n.node_id = im_mgmt.node_id
    LEFT JOIN (
      SELECT pi.node_id, COALESCE(ps.policy_status, 'APPLYING') AS policy_status, tp.name AS policy_name, tnp.keep_agent_policy
        FROM tb_product_info pi
        JOIN tb_product p ON pi.product_id = p.product_id
        JOIN tb_product_feature_map pfm ON pi.product_id = pfm.product_id
        JOIN tb_node_policy tnp ON pi.node_id = tnp.node_id AND pfm.product_feature_id = tnp.product_feature_id
        JOIN tb_policy tp ON tnp.policy_id = tp.policy_id
        LEFT JOIN vw_policy_status ps ON pi.node_id = ps.node_id AND pfm.product_feature_id = ps.product_feature_id
       WHERE p.product_group = 'HIPS'
         AND pfm.product_feature_id = 'HIPS_AGENT'
         AND sp_exist_license(p.product_group)
    ) hips_agent ON n.node_id = hips_agent.node_id
    LEFT JOIN (
      SELECT pi.node_id, COALESCE(ps.policy_status, 'APPLYING') AS policy_status, tp.name AS policy_name, tnp.keep_agent_policy
        FROM tb_product_info pi
        JOIN tb_product p ON pi.product_id = p.product_id
        JOIN tb_product_feature_map pfm ON pi.product_id = pfm.product_id
        JOIN tb_node_policy tnp ON pi.node_id = tnp.node_id AND pfm.product_feature_id = tnp.product_feature_id
        JOIN tb_policy tp ON tnp.policy_id = tp.policy_id
        LEFT JOIN vw_policy_status ps ON pi.node_id = ps.node_id AND pfm.product_feature_id = ps.product_feature_id
       WHERE p.product_group = 'HIPS'
         AND pfm.product_feature_id = 'HIPS_MGMT'
         AND sp_exist_license(p.product_group)
    ) hips_mgmt ON n.node_id = hips_mgmt.node_id
    LEFT JOIN (
      SELECT pi.node_id, COALESCE(ps.policy_status, 'APPLYING') AS policy_status, tp.name AS policy_name, tnp.keep_agent_policy
        FROM tb_product_info pi
        JOIN tb_product p ON pi.product_id = p.product_id
        JOIN tb_product_feature_map pfm ON pi.product_id = pfm.product_id
        JOIN tb_node_policy tnp ON pi.node_id = tnp.node_id AND pfm.product_feature_id = tnp.product_feature_id
        JOIN tb_policy tp ON tnp.policy_id = tp.policy_id
        LEFT JOIN vw_policy_status ps ON pi.node_id = ps.node_id AND pfm.product_feature_id = ps.product_feature_id
       WHERE p.product_group = 'HIPS'
         AND pfm.product_feature_id = 'HIPS_FW'
         AND sp_exist_license(p.product_group)
    ) hips_fw ON n.node_id = hips_fw.node_id
    LEFT JOIN (
      SELECT pi.node_id, COALESCE(ps.policy_status, 'APPLYING') AS policy_status, tp.name AS policy_name, tnp.keep_agent_policy
        FROM tb_product_info pi
        JOIN tb_product p ON pi.product_id = p.product_id
        JOIN tb_product_feature_map pfm ON pi.product_id = pfm.product_id
        JOIN tb_node_policy tnp ON pi.node_id = tnp.node_id AND pfm.product_feature_id = tnp.product_feature_id
        JOIN tb_policy tp ON tnp.policy_id = tp.policy_id
        LEFT JOIN vw_policy_status ps ON pi.node_id = ps.node_id AND pfm.product_feature_id = ps.product_feature_id
       WHERE p.product_group = 'SCM'
         AND pfm.product_feature_id = 'SCM_AGENT'
         AND sp_exist_license(p.product_group)
    ) scm_agent ON n.node_id = scm_agent.node_id
    LEFT JOIN (
      SELECT pi.node_id, COALESCE(ps.policy_status, 'APPLYING') AS policy_status, tp.name AS policy_name, tnp.keep_agent_policy
        FROM tb_product_info pi
        JOIN tb_product p ON pi.product_id = p.product_id
        JOIN tb_product_feature_map pfm ON pi.product_id = pfm.product_id
        JOIN tb_node_policy tnp ON pi.node_id = tnp.node_id AND pfm.product_feature_id = tnp.product_feature_id
        JOIN tb_policy tp ON tnp.policy_id = tp.policy_id
        LEFT JOIN vw_policy_status ps ON pi.node_id = ps.node_id AND pfm.product_feature_id = ps.product_feature_id
       WHERE p.product_group = 'SCM'
         AND pfm.product_feature_id = 'SCM_MGMT'
         AND sp_exist_license(p.product_group)
    ) scm_mgmt ON n.node_id = scm_mgmt.node_id
    LEFT JOIN tb_node_status AS ns ON n.node_id = ns.node_id
    LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = n.container_service_type
    WHERE n.node_id = ANY(v_node_id_arr)
      AND n.is_removed IS FALSE;

END;
$$;


ALTER FUNCTION public.sp_get_agent_status_policy_applied_info(i_node_id_arr bigint[], i_filter_json text, i_product_auth text, i_dashboard_layout text, i_admin_group text) OWNER TO cppoltp;

--
-- Name: sp_get_agent_status_v3_info(bigint[], text, text, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_status_v3_info(i_node_id_arr bigint[], i_filter_json text, i_product_auth text, i_dashboard_layout text, i_admin_group text) RETURNS TABLE(node_id bigint, is_managed text, manager_ip text, product_id text, product_version text, service_status public.en_product_service_status, product_name text, connection_status public.en_connection_status, integrity_status public.en_integrity_status, server_time timestamp without time zone, hdd1_free_info integer, policy_status public.en_policy_status, realtime_status boolean, realtime_status_mode text, engine_version text, engine_update_time timestamp without time zone, last_scan_time timestamp without time zone, v3_install_time timestamp without time zone, v3_integrity_status public.en_integrity_status, client_time text, is_license_expired text, is_new_engine text, last_quarantine_collect_time timestamp without time zone, ip inet, scan_status public.en_v3_scan_status, ckl_version text, license_code text, comp_type text, policy_name text, monitor text)
    LANGUAGE plpgsql
    AS $$

DECLARE
  v_node_id_arr bigint[];
  v_engine_update_threshold bigint;
  v_oes_engine_date           timestamp := '9999.12.31'::timestamp;
  v_ses_engine_date           timestamp := '9999.12.31'::timestamp;

  v_not_support_platform  en_platform_type[];
BEGIN

  v_node_id_arr := sp_get_agent_status_filter(i_node_id_arr, i_filter_json, i_product_auth, i_dashboard_layout, i_admin_group);

  -- 엔진 업데이트 임계치
  SELECT GREATEST(COALESCE(MAX(c.value), '0')::integer -1, 0) INTO v_engine_update_threshold
    FROM tb_config AS c
   WHERE c.config_group = 'AGENT_THRESHOLD' AND c.key = 'engine_update_threshold'
   ;

  -- 최신 엔진 버전(일자)
  SELECT TO_CHAR(SUBSTRING(MAX(case when key = 'oes_engine_date' THEN value END), 1, 10)::timestamp - (v_engine_update_threshold || ' day')::interval, 'YYYY.MM.DD')::timestamp AS oes_engine_date,
         TO_CHAR(SUBSTRING(MAX(case when key = 'ses_engine_date' THEN value END), 1, 10)::timestamp - (v_engine_update_threshold || ' day')::interval, 'YYYY.MM.DD')::timestamp AS ses_engine_date
    INTO v_oes_engine_date, v_ses_engine_date
    FROM tb_config AS c
   WHERE c.config_group = 'UPDATE_SERVICE'
   ;

  -- 제품 관리 여부
  SELECT COALESCE(config.not_support_platform,'{}') INTO v_not_support_platform
  FROM sp_get_not_manage_product('V3'::en_product_group_type) AS config;

  RETURN QUERY
    SELECT
      n.node_id
      -- 1.0.5.1 추가(CWPP-2208)
      , CASE WHEN (SELECT platform_type FROM tb_platform WHERE platform_id = n.platform_id) = ANY(v_not_support_platform)
          THEN FALSE::TEXT
          ELSE COALESCE(p.is_managed,TRUE)::TEXT END AS is_managed
      , p.manager_ip AS manager_ip
      , CASE WHEN n.machine_type = 'CONTAINER' AND tcp.is_amc_supported IS FALSE THEN 'UNSUPPORTED'
             ELSE p.product_id::TEXT
             END AS product_id
      , p.product_version
      , p.service_status
      , p.name
      , COALESCE(NOS.connection_status, 'UNINSTALLED'::en_connection_status) AS connection_status  /* 노드 연결 상태 */
      , COALESCE(NOS.integrity_status, 'NOT_SCANNED'::en_integrity_status) AS integrity_status  /* 무결성 검사 결과 */
      , NOS.server_time::TIMESTAMP                         /* 연결 시각 */
      , CASE WHEN hws.hdd1_size = '' OR hws.hdd1_size = '0' OR hws.hdd1_free = '' THEN NULL ELSE (ROUND(((hdd1_size::float - hdd1_free::float)/hdd1_size::float)::numeric, 2)*100)::integer END AS hdd1_free_info           /* hdd1 free */
      , CASE WHEN n.machine_type = 'CONTAINER' AND tcp.is_amc_supported IS FALSE THEN 'UNSUPPORTED'
             ELSE p.policy_status
             END AS policy_status
      , p.realtime_status
      , p.realtime_status_mode
      , p.engine_version                      /* 엔진 버전 */
      , p.engine_update_time::TIMESTAMP
      , p.last_scan_time::TIMESTAMP
      , p.install_time::TIMESTAMP
      , p.integrity_status AS v3_integrity_status
      , NOS.client_time::TIMESTAMP::text
      , CASE WHEN tpl.expire_date >= now() THEN 'N'
            WHEN tpl.expire_date  < now() THEN 'Y'
            ELSE ''
        END AS is_license_expired /* 라이센스 만료 여부(Y:만료, N:유효, 데이터 없을 시:'') */
      , CASE WHEN p.engine_update_time >= CASE WHEN p.engine_type = 'OES' THEN v_oes_engine_date WHEN p.engine_type = 'SES' THEN v_ses_engine_date END THEN 'Y'
            WHEN p.engine_update_time <  CASE WHEN p.engine_type = 'OES' THEN v_oes_engine_date WHEN p.engine_type = 'SES' THEN v_ses_engine_date END THEN 'N'
            ELSE ''
        END AS is_new_engine /* 최신 엔진 여부(Y:최신엔진, N:이전버전엔진, 데이터 없을 시:'') */
      , p.last_quarantine_collect_time::TIMESTAMP
      , n.ip
      , p.scan_status
      , COALESCE(p.ckl_version, '') AS ckl_version
      , CASE
          WHEN tpl.product_id IS NULL THEN ''
          WHEN p.activation_code IS NOT NULL AND p.activation_code != '' THEN p.activation_code 
          WHEN p.license_no IS NOT NULL AND p.license_no != '' THEN p.license_no
          ELSE NULL
          END AS license_code
      , p.comp_type
      , p.policy_name AS policy_name
      , p.monitor AS monitor
    FROM tb_node AS n
    INNER JOIN tb_platform platform ON platform.platform_id = n.platform_id
    LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = n.container_service_type
    LEFT JOIN tb_node_status AS nos ON n.node_id = nos.node_id
    LEFT JOIN tb_node_hw AS hws ON n.node_id = hws.node_id
    LEFT JOIN (
              SELECT
                -- null인 경우 true로 처리한 이유는 하위 버전 호환을 위함(기존 제품 등록시에는 is_managed 값을 저장하지 않음)
                -- register_product revision 2 부터는 is_managed 값을 저장함(CWPP-2205)
                COALESCE(pi.is_managed, TRUE) AS is_managed
                , pi.node_id, p.name, pi.product_id, pi.manager_ip
                , vs.product_version, vs.service_status, vs.realtime_status, vs.realtime_status_mode, vs.engine_version, vs.engine_update_time
                , vs.last_scan_time, vs.install_time, vs.integrity_status, vs.engine_type, vs.last_quarantine_collect_time
                , vs.license_no, vs.activation_code  ,COALESCE(ps.policy_status, 'APPLYING') AS policy_status
                , vs.scan_status, vs.ckl_version, vs.comp_type, tp.name AS policy_name, COALESCE(vs.monitor, 'false') AS monitor
              FROM tb_product_info AS pi
                JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'V3'
                JOIN tb_product_feature_map pfm ON pi.product_id = pfm.product_id AND pfm.product_feature_id <> 'V3NET_LU_UPDATE'
                LEFT JOIN tb_v3_status vs ON vs.node_id = pi.node_id AND vs.product_id = pi.product_id
                LEFT JOIN tb_policy_status ps ON pi.node_id = ps.node_id AND pfm.product_feature_id = ps.product_feature_id
                LEFT JOIN tb_policy tp ON tp.policy_id = ps.policy_id AND tp.product_feature_id = tp.product_feature_id
              WHERE sp_exist_license(p.product_group)
              ) p ON n.node_id = p.node_id
    LEFT JOIN tb_product_license AS tpl ON tpl.product_id = p.product_id
    WHERE n.node_id = ANY(v_node_id_arr)
      AND n.is_removed IS FALSE;

END;
$$;


ALTER FUNCTION public.sp_get_agent_status_v3_info(i_node_id_arr bigint[], i_filter_json text, i_product_auth text, i_dashboard_layout text, i_admin_group text) OWNER TO cppoltp;

--
-- Name: sp_get_agent_summary_olap_info(bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_summary_olap_info(i_node_id_arr bigint[]) RETURNS TABLE(con_count numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
  RETURN QUERY
  SELECT COUNT(*)
  FROM tb_node_status
  WHERE node_id IN ( SELECT unnest(i_node_id_arr) )
    AND connection_status = 'CONNECTED'
  ;
END;
$$;


ALTER FUNCTION public.sp_get_agent_summary_olap_info(i_node_id_arr bigint[]) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_agent_summary_olap_info(i_node_id_arr bigint[]); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_agent_summary_olap_info(i_node_id_arr bigint[]) IS '
@brief  프로시저 설명 : 에이전트 정보 그룹 목록 요약 정보
@in
      i_node_id_arr bigint[]
@return
';


--
-- Name: sp_get_agent_sync_file_list(bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_sync_file_list(i_product_pkg_id bigint[]) RETURNS TABLE(server_id text, file_id text, file_path text, file_name text, file_type text, org_file_name text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

    RETURN QUERY
    SELECT
        pkg_svr.server_id       :: text AS server_id
        , prd_pkg.product_pkg_id  :: text AS file_id
        , '/opt/ahnlab/cpp/pkgroot/' || prd_pkg.path            AS file_path
        , CASE WHEN taio.product_pkg_id IS NULL THEN prd_pkg.name::text
               WHEN taio.product_pkg_id IS NOT NULL THEN taio.product_pkg_id::text
               ELSE prd_pkg.name::text END AS file_name
        , prd_pkg.pkg_type      :: text AS file_type
        , prd_pkg.name::text AS org_file_name
    FROM 
      tb_product_pkg prd_pkg 
    LEFT JOIN
      tb_agent_installer_option taio
    ON
      taio.product_pkg_id = prd_pkg.product_pkg_id
    AND
      taio.key = 'filename'
    INNER JOIN 
      tb_pkg_server pkg_svr
    ON 
      prd_pkg.product_pkg_id = pkg_svr.product_pkg_id
    AND
      prd_pkg.is_removed is FALSE
    AND 
      prd_pkg.product_pkg_id IN (SELECT UNNEST(i_product_pkg_id))
    ;

END;
$$;


ALTER FUNCTION public.sp_get_agent_sync_file_list(i_product_pkg_id bigint[]) OWNER TO cppoltp;

--
-- Name: sp_get_agent_timeline(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_agent_timeline(i_node_id bigint) RETURNS TABLE(reg_date text, engine_version text, engine_update_past_days integer, manual_scan_past_days integer, manual_scan_time timestamp without time zone, malware_clean_count bigint, malware_clean_fail_count bigint, detect_count integer, block_count integer, compliance_scan_pass_count integer, compliance_scan_fail_count integer, compliance_scan_error_count integer, compliance_scan_user_pass_count integer, compliance_scan_user_fail_count integer, compliance_scan_user_error_count integer, secret_scan_pass_count integer, secret_scan_fail_count integer, secret_scan_error_count integer, secret_scan_user_pass_count integer, secret_scan_user_fail_count integer, secret_scan_user_error_count integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_engine_update_threshold   integer;
  v_manual_scan_threshold   integer;
BEGIN

  -- 엔진 업데이트 임계치
  SELECT GREATEST(COALESCE(MAX(c.value), '0')::integer - 1, 0) INTO v_engine_update_threshold
  FROM tb_config AS c
  WHERE c.config_group = 'AGENT_THRESHOLD' AND c.key = 'engine_update_threshold';

  -- 수동 검사 임계치
  SELECT GREATEST(COALESCE(MAX(c.value), '0')::integer - 1, 0) INTO v_manual_scan_threshold
  FROM tb_config AS c
  WHERE c.config_group = 'AGENT_THRESHOLD' AND c.key = 'manual_scan_threshold';

  RETURN QUERY
    SELECT
      i.reg_date
      , oltp.engine_version AS engine_version
      , (CASE WHEN oltp.engine_update_past_days < 1
               THEN 0
               WHEN oltp.engine_update_past_days >= v_engine_update_threshold
               THEN 1
               ELSE 2
               END)::integer AS engine_update_past_days
      , (CASE WHEN oltp.reg_date::date - to_char(oltp.last_scan_time, 'YYYYMMDD')::date < 1
               THEN 0
               WHEN oltp.reg_date::date - to_char(oltp.last_scan_time, 'YYYYMMDD')::date >= v_manual_scan_threshold
               THEN 1
               ELSE 2
               END)::integer AS manual_scan_past_days
      , oltp.last_scan_time AS manual_scan_time
      , v3.malware_clean_count
      , v3.malware_clean_fail_count
      , hips.detect_count
      , hips.block_count
	  , COALESCE(scm.compliance_scan_pass_count , 0) AS compliance_scan_pass_count /* 기본 보안정보 안전 건수*/
	  , COALESCE(scm.compliance_scan_fail_count , 0) AS compliance_scan_fail_count /* 기본 보안정보 취약 건수*/
	  , COALESCE(scm.compliance_scan_error_count , 0) AS compliance_scan_error_count /* 기본 보안정보 Unkown 건수*/
	  , COALESCE(scm.compliance_scan_user_pass_count , 0) AS compliance_scan_user_pass_count /* 사용자정의 보안정보 안전 건수*/
	  , COALESCE(scm.compliance_scan_user_fail_count , 0) AS compliance_scan_user_fail_count /* 사용자정의 보안정보 취약 건수*/
	  , COALESCE(scm.compliance_scan_user_error_count , 0) AS compliance_scan_user_error_count /* 사용자정의 보안정보 Unkown 건수*/
	  , COALESCE(scm.secret_scan_pass_count , 0) AS secret_scan_pass_count /* 기본 민감정보 안전 건수*/
	  , COALESCE(scm.secret_scan_fail_count , 0) AS secret_scan_fail_count /* 기본 민감정보 취약 건수*/
	  , COALESCE(scm.secret_scan_error_count , 0) AS secret_scan_error_count /* 기본 민감정보 Unkown 건수*/
	  , COALESCE(scm.secret_scan_user_pass_count , 0) AS secret_scan_user_pass_count /* 사용자정의 민감정보 안전 건수*/
	  , COALESCE(scm.secret_scan_user_fail_count , 0) AS secret_scan_user_fail_count /* 사용자정의 민감정보 취약 건수*/
	  , COALESCE(scm.secret_scan_user_error_count , 0) AS secret_scan_user_error_count /* 사용자정의 민감정보 Unkown 건수*/
    FROM (
      SELECT TO_CHAR(NOW()::timestamp without time zone - (29 - interval || ' DAYS')::INTERVAL, 'YYYYMMDD') AS reg_date
      FROM GENERATE_SERIES(0,29) interval
    ) AS i(reg_date)
    LEFT JOIN tb_timeline_oltp AS oltp ON oltp.node_id = i_node_id AND oltp.reg_date = i.reg_date
    LEFT JOIN tb_timeline_v3 AS v3 ON v3.node_id = i_node_id AND v3.reg_date = i.reg_date
    LEFT JOIN tb_hips_detect_daily_timeline AS hips ON hips.node_id = i_node_id AND hips.reg_date::text = i.reg_date
    LEFT JOIN tb_scm_status_daily_timeline AS scm on scm.node_id = i_node_id and scm.reg_date = i.reg_date
    ORDER BY i.reg_date;

END;
$$;


ALTER FUNCTION public.sp_get_agent_timeline(i_node_id bigint) OWNER TO cppoltp;

