CREATE FUNCTION public.sp_get_agent_v3_info(i_node_id bigint) RETURNS TABLE(product_id public.en_product_id_type, product_name text, engine_version text, last_scan_time timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT  v.product_id
          , p.name
          , v.engine_version
          , v.last_scan_time::TIMESTAMP
    FROM tb_node AS n
    JOIN tb_product_info AS pi ON n.node_id = pi.node_id AND n.is_removed IS FALSE
    JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'V3'
    JOIN tb_v3_status AS v ON v.node_id = n.node_id
   WHERE n.node_id = i_node_id;

END;
$$;


