--
-- Name: sp_get_alert_correlation_rule(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_alert_correlation_rule() RETURNS TABLE(correlation_rule_id bigint, correlation_type public.en_correlation_type, name text, is_enabled text, schedule text, alarm_threshold integer, condition_text text, exclude_text text, send_notice text, base_report_id public.en_base_report_id_type, alert_template_id bigint, send_mail text, send_mail_to_target text, custom_email text, admin_id text, "values" text, comparison_operator public.en_comparison_operator, send_log text)
    LANGUAGE plpgsql
    AS $$

BEGIN

RETURN QUERY

SELECT cr.correlation_rule_id         AS correlation_rule_id
      ,cr.correlation_type            AS correlation_type
      ,cr.name                        AS name
      ,cr.is_enabled ::text           AS is_enabled
      ,cr.schedule                    AS schedule
      ,cr.alarm_threshold             AS alarm_threshold
      ,cr.condition_text              AS condition_text
      ,cr.exclude_text                AS exclude_text
      ,cr.send_notice ::text          AS send_notice
      ,cr.base_report_id              AS base_report_id
      ,cr.alert_template_id           AS alert_template_id
      ,cr.send_mail ::text            AS send_mail
      ,cr.send_mail_to_target ::text  AS send_mail_to_target
      ,cr.custom_email                AS custom_email
      ,cr.admin_id                    AS admin_id
      ,cri.values                     AS "values"
      ,cri.comparison_operator        AS comparison_operator
      ,cr.send_log::text   			  AS send_log
FROM tb_correlation_rule AS cr
JOIN tb_correlation_rule_item AS cri
ON cr.correlation_rule_id = cri.correlation_rule_id
WHERE cr.correlation_type = 'SYSTEM_ALERT'
  AND cri.intersect_set = 1
UNION ALL
SELECT cr.correlation_rule_id           AS correlation_rule_id
      ,cr.correlation_type              AS correlation_type
      ,cr.name                          AS name
      ,cr.is_enabled ::text             AS is_enabled
      ,cr.schedule                      AS schedule
      ,cr.alarm_threshold               AS alarm_threshold
      ,cr.condition_text                AS condition_text
      ,cr.exclude_text                  AS exclude_text
      ,cr.send_notice ::text            AS send_notice
      ,cr.base_report_id                AS base_report_id
      ,cr.alert_template_id             AS alert_template_id
      ,cr.send_mail ::text              AS send_mail
      ,cr.send_mail_to_target ::text    AS send_mail_to_target
      ,cr.custom_email                  AS custom_email
      ,cr.admin_id                      AS admin_id
      ,null AS "values"
      ,null AS comparison_operator
      ,null AS send_log
FROM tb_correlation_rule AS cr
WHERE cr.correlation_type = 'GENERAL'
;


END;
$$;


