--
-- Name: sp_get_all_sub_group_list(bigint, boolean); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_all_sub_group_list(i_group_id bigint, i_is_include_slef boolean) RETURNS TABLE(all_sub_group_id bigint[])
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
  IF i_is_include_slef THEN
    RETURN QUERY
    WITH RECURSIVE tree AS (
      SELECT
       tb_group.group_id
      FROM tb_group
      WHERE pgroup_id  = i_group_id
      AND is_removed = false
      UNION ALL
      SELECT
       tb_group.group_id
      FROM tb_group
      INNER JOIN tree
      ON tb_group.pgroup_id  = tree.group_id
      AND tb_group.is_removed = false
       )
    SELECT
      ARRAY[i_group_id::bigint] || array_agg(tree.group_id)
    FROM tree;
  ELSE

    RETURN QUERY
    WITH RECURSIVE tree AS (
      SELECT
       tb_group.group_id
      FROM tb_group
      WHERE pgroup_id  = i_group_id
      AND is_removed = false
      UNION ALL
      SELECT
       tb_group.group_id
      FROM tb_group
      INNER JOIN tree
      ON tb_group.pgroup_id  = tree.group_id
      AND tb_group.is_removed = false
       )
    SELECT
      array_agg(tree.group_id)
    FROM tree;
  END IF;
  END;
$$;


ALTER FUNCTION public.sp_get_all_sub_group_list(i_group_id bigint, i_is_include_slef boolean) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_all_sub_group_list(i_group_id bigint, i_is_include_slef boolean); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_all_sub_group_list(i_group_id bigint, i_is_include_slef boolean) IS '
@brief  하위그룹전체 가져오기
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_all_sub_group_list(bigint, boolean, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_all_sub_group_list(i_group_id bigint, i_is_include_slef boolean, i_admin_id text) RETURNS TABLE(all_sub_group_id bigint[])
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_admin_group text;
    v_top_group text;
    v_admin_groups bigint[];
    v_etc_admin_group bigint[];
	v_physical_group_id bigint;
BEGIN
    SELECT admin_group
      INTO v_admin_group
      FROM tb_admin
     WHERE admin_id = i_admin_id;

    SELECT g.group_id::text
      INTO v_top_group
      FROM tb_group g
     WHERE g.group_type = 'TOP';

    SELECT g.group_id
      INTO v_physical_group_id
      FROM tb_group g
      WHERE g.group_type = 'PHYSICAL';

    SELECT array_agg(g.group_id)::bigint[]
	  INTO v_etc_admin_group
      FROM tb_group g
	 WHERE g.group_type IN ('TOP','PHYSICAL');

    IF i_group_id = any(v_etc_admin_group) AND v_admin_group <> v_top_group THEN

        v_admin_groups := string_to_array(v_admin_group,',')::bigint[];

        IF i_group_id = any(array[v_physical_group_id]) THEN
	        SELECT array_agg(tb_group.group_id)
	          INTO v_admin_groups
	          FROM tb_group
	         WHERE is_removed = false
	           AND CASE  WHEN i_group_id = v_physical_group_id THEN group_id IN (SELECT * FROM unnest(v_admin_groups)) AND group_type IN ('PHYSICAL','DEFAULT','GENERAL') end;
        END IF;
    ELSE
        v_admin_groups := array[i_group_id];
    END IF;


    IF i_is_include_slef then


        RETURN QUERY

        WITH RECURSIVE tree AS
        (
            SELECT tb_group.group_id
              FROM tb_group
             WHERE pgroup_id  = any(v_admin_groups)
               AND is_removed = false
             UNION ALL
            SELECT tb_group.group_id
              FROM tb_group
             INNER JOIN tree
                ON tb_group.pgroup_id  = tree.group_id
               AND tb_group.is_removed = false
        )
            SELECT  v_admin_groups || array_agg(tree.group_id)
              FROM tree;


    ELSE

        RETURN QUERY

        WITH RECURSIVE tree AS
        (
            SELECT tb_group.group_id
              FROM tb_group
             WHERE pgroup_id  = any(v_admin_groups)
               AND is_removed = false

             UNION ALL
            SELECT tb_group.group_id
              FROM tb_group
             INNER JOIN tree
                ON tb_group.pgroup_id  = tree.group_id
               AND tb_group.is_removed = false
        )
            SELECT  array_agg(tree.group_id)
              FROM tree;

    END IF;
  END;
$$;


ALTER FUNCTION public.sp_get_all_sub_group_list(i_group_id bigint, i_is_include_slef boolean, i_admin_id text) OWNER TO cppoltp;

