--
-- Name: sp_get_amc_mgmt_policy_detail(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_amc_mgmt_policy_detail(i_policy_id bigint) RETURNS TABLE(product_feature_id public.en_product_feature_id_type, product_feature_name text, policy_id bigint, policy_name text, description text, policy_type public.en_policy_type, online_policy_body text, offline_policy_body text, use_offline_policy text, hash text, modified_time timestamp without time zone, group_id_array bigint[])
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_product_feature_id en_product_feature_id_type;

BEGIN

SELECT p.product_feature_id
INTO v_product_feature_id
FROM tb_policy p
WHERE p.policy_id = i_policy_id;

IF v_product_feature_id IS NULL THEN

  RAISE EXCEPTION 'policy_id (%) does not exist.', i_policy_id USING HINT = 'DB-00031';

ELSIF v_product_feature_id <> 'AMC_MGMT' THEN

  RAISE EXCEPTION 'policy_id (%) is not AMC_MGMT policy.', i_policy_id USING HINT = 'DB-00030';

END IF;

RETURN QUERY

--정책 상세
SELECT p.product_feature_id AS product_feature_id
      ,p.product_feature_name AS product_feature_name
      ,p.policy_id AS policy_id
      ,p.policy_name AS policy_name
      ,p.description AS description
      ,p.policy_type AS policy_type
      ,p.online_policy_body AS online_policy_body
      ,p.offline_policy_body AS offline_policy_body
      ,p.use_offline_policy AS use_offline_policy
      ,p.hash AS hash
      ,p.modified_time AS modified_time
      ,p.group_id_array AS group_id_array
FROM sp_get_policy_detail(i_policy_id) p
;

END;
$$;


ALTER FUNCTION public.sp_get_amc_mgmt_policy_detail(i_policy_id bigint) OWNER TO cppoltp;

--
-- Name: sp_get_amc_mgmt_policy_factory(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_amc_mgmt_policy_factory(i_admin_id text) RETURNS TABLE(policy_name text, product_feature_id public.en_product_feature_id_type, description text, online_policy_body text, offline_policy_body text, use_offline_policy text, hash text)
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_privilege_profile_auth boolean;
BEGIN

SELECT
    EXISTS (
        SELECT
            1
        FROM
            tb_admin ta
        INNER JOIN
            tb_privilege_profile tpp
        ON
            ta.privilege_profile_id = tpp.privilege_profile_id 
        WHERE
            tpp.profile_body LIKE '%"/policy/policy_AMC_W"%'
        AND
            ta.admin_id = i_admin_id
    ) INTO v_privilege_profile_auth;
	
IF v_privilege_profile_auth = FALSE THEN
  RAISE EXCEPTION 'You do not have permission to write policy' USING HINT = 'DB-00084';
END IF;

  --정책 공장초기화값 조회
  RETURN QUERY
    SELECT pf.policy_name AS policy_name
            ,pf.product_feature_id AS product_feature_id
            ,pf.description AS description
            ,pf.online_policy_body AS online_policy_body
            ,pf.offline_policy_body AS offline_policy_body
            ,pf.use_offline_policy AS use_offline_policy
            ,pf.hash AS hash
    FROM sp_get_policy_factory('AMC_MGMT') pf;

END;
$$;


ALTER FUNCTION public.sp_get_amc_mgmt_policy_factory(i_admin_id text) OWNER TO cppoltp;

--
-- Name: sp_get_anti_virus_product_list(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_anti_virus_product_list(i_product_auth text) RETURNS TABLE(product_group public.en_product_group_type, product_id public.en_product_id_type, platform_type public.en_platform_type, name text, product_pkg_id bigint, pkg text, license text, version text, use_update text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_product_auth              en_product_group_type[];
BEGIN

  -- 권한 처리
  IF i_product_auth IS NOT NULL AND LENGTH(TRIM(i_product_auth)) > 0 THEN
    v_product_auth := STRING_TO_ARRAY(REPLACE(i_product_auth, ' ', ''), ',')::en_product_group_type[];
  ELSE
    SELECT ENUM_RANGE(null::en_product_group_type) INTO v_product_auth;
  END IF;

  RETURN QUERY
    SELECT
      pl.product_group
      , pl.product_id
      , pl.platform_type
      , pl.name
      , pl.product_pkg_id
      , pl.pkg
      , pl.license
      , pl.version
      , (CASE WHEN pl.product_pkg_id IS NULL THEN 'false'
              WHEN pl.license = '0' THEN 'false'
              WHEN pl.product_id ='V3NET_LU' THEN 'false'
              ELSE (SELECT tc.value FROM tb_config tc WHERE tc.config_group = 'V3_PKG_UPDATE' AND tc."key" = 'v3_pkg_update_use')
        END) AS use_update
    FROM (
      SELECT
        p.product_group
        , p.platform_type
        , p.product_id
        , p.name
        , pp.product_pkg_id
        , pp.version
        , (CASE WHEN pp.path IS NULL THEN 0 ELSE 1 END)::text AS pkg
        , (CASE WHEN COALESCE(pl.license_no, 0) = 0 THEN 0 ELSE 1 END)::text AS license
      FROM (SELECT t.product_group, t.product_id, t.name, unnest(t.platform_support) platform_type FROM tb_product t) AS p
      LEFT JOIN (
          SELECT pp.product_pkg_id, pp.product_id, pp.platform_type
                , FIRST_VALUE(pp.path) OVER(PARTITION BY pp.product_pkg_id, pp.product_id ORDER BY modified_time DESC) AS path
                , FIRST_VALUE(pp.version) OVER(PARTITION BY pp.product_pkg_id, pp.product_id ORDER BY modified_time DESC) AS version
          FROM tb_product_pkg pp
          WHERE pp.is_removed = FALSE
          GROUP BY pp.product_pkg_id, pp.product_id, pp.platform_type
      ) AS pp ON p.product_id = pp.product_id AND p.platform_type = pp.platform_type
      LEFT JOIN (
          SELECT pl.product_id, COUNT(pl.license_no) AS license_no
          FROM tb_product_license AS pl
          GROUP BY pl.product_id
      ) AS pl ON p.product_id = pl.product_id
      WHERE p.product_group = ANY(v_product_auth)
        AND p.product_group <> 'EMS'
        AND sp_exist_product_license(p.product_id) = TRUE
    ) AS pl
    ORDER BY pl.license DESC, pl.product_group, product_id, pl.platform_type ASC;

END;
$$;


ALTER FUNCTION public.sp_get_anti_virus_product_list(i_product_auth text) OWNER TO cppoltp;

