--
-- Name: sp_get_application_auth_list(text, public.en_app_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_application_auth_list(i_app_id text, i_app_type public.en_app_type) RETURNS TABLE(app_id text, app_key text, app_type public.en_app_type, connect_ipaddr text, from_date date, to_date date, expire_time bigint, service_type text, db_type public.en_db_type, query text, command_list text, use boolean, modified_by text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
	RETURN QUERY
    SELECT
      aa.app_id, aa.app_key, aa.app_type, ARRAY_TO_STRING(aa.connect_ipaddr,',') AS connect_ipaddr
      , aa.from_date, aa.to_date, aa.expire_time, ARRAY_TO_STRING(aa.service_type,',') AS service_type
      , aa.db_type, aa.query, ARRAY_TO_STRING(aa.command_list,',') AS command_list, aa.use, aa.modified_by
    FROM
      tb_application_auth  aa
    WHERE
      CASE WHEN i_app_id != '0' AND i_app_id IS NOT NULL THEN
        aa.app_id  = i_app_id
      ELSE
        1=1
      END
      AND
        CASE WHEN i_app_type IS NOT NULL THEN
          aa.app_type = i_app_type
        ELSE
          1=1
        END
    ;
END;
$$;


