    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT
      u.server_id
      , u.file_id
      , u.file_path
      , u.file_name
      , u.file_type
    FROM tb_upload_file u
