--
-- Name: sp_get_artifacts_list(bigint[], bigint[], bigint[], text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_artifacts_list(i_task_id bigint[], i_instance_id bigint[], i_target_id bigint[], i_connect_server_ip text) RETURNS TABLE(admin_id text, task_type public.en_task_type, task_id bigint, instance_id bigint, target_id bigint, modified_time timestamp without time zone, file_id bigint, file_name text, file_uri text, file_size bigint, ahnreport_file_url text, is_timeout text, ip inet, file_uri_path text, ahnreport_file_url_path text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_is_nat_host                    boolean;
BEGIN
    
    SELECT nat.is_nat_host
    INTO v_is_nat_host
    FROM (
        SELECT FALSE AS is_nat_host
        FROM tb_server ts
        WHERE ts.ip = i_connect_server_ip
        UNION
        SELECT TRUE AS is_nat_host
        FROM tb_server ts
        WHERE ts.public_ip = i_connect_server_ip
    ) nat
    LIMIT 1;
  
  RETURN QUERY
    SELECT
      j.admin_id,
      t.task_type,
      tts.task_id,
      tts.instance_id,
      tts.target_id,
      COALESCE(ti.modified_time, t.modified_time) AS modified_time,
      uf.file_id,
      uf.file_name,
      (SELECT sp_get_file_download_uri(uf.server_id , v_is_nat_host) || uf.file_uri) AS file_uri,
      uf.file_size,
      (SELECT sp_get_file_download_uri(uf.server_id , v_is_nat_host) || '/web/ahnrptViewer/?ahnrptpath=' || uf.ahnreport_file_url || '&type=' || uf.file_type) AS ahnreport_file_url,
      CASE WHEN t.task_type = 'COLLECT_ARTIFACTS' THEN 'false'
            ELSE (
               CASE WHEN LENGTH(t.logical_payload::json ->> 'timeout'::text) > 0 THEN
                  CASE WHEN now() > COALESCE(ti.modified_time, t.modified_time) + (t.logical_payload::json ->> 'timeout' || ' minute')::interval THEN 'true' else 'false' END
                  ELSE 'false' END
            ) END AS is_timeout,
      n.ip,
      (SELECT sp_get_file_download_uri(uf.server_id , false) || uf.file_uri) AS file_uri_path,
      (SELECT sp_get_file_download_uri(uf.server_id , false) || uf.ahnreport_file_url) AS ahnreport_file_url_path
    FROM tb_job j
      JOIN tb_task t ON j.job_id = t.job_id
      JOIN (
        SELECT t.task_id, t.instance_id, t.target_id
        FROM UNNEST(i_task_id, i_instance_id, i_target_id) AS t(task_id, instance_id, target_id)
        EXCEPT
        SELECT u.task_id, u.instance_id, u.node_id
        FROM tb_upload_file AS u
        JOIN (
          SELECT t.task_id, t.instance_id, t.target_id
          FROM UNNEST(i_task_id, i_instance_id, i_target_id) AS t(task_id, instance_id, target_id)
        ) AS t ON t.task_id = u.task_id AND t.instance_id = u.instance_id AND t.target_id = u.node_id AND u.is_removed = true
      ) AS tts ON t.task_id = tts.task_id
      JOIN tb_node n ON tts.target_id = n.node_id AND n.is_removed = false
      LEFT JOIN tb_task_instance AS ti ON tts.task_id = ti.task_id AND tts.instance_id = ti.instance_id
      LEFT JOIN tb_upload_file uf ON tts.task_id = uf.task_id AND tts.instance_id = uf.instance_id AND tts.target_id = uf.node_id
    ORDER BY COALESCE(ti.modified_time, t.modified_time) DESC, tts.target_id;

END;
$$;


ALTER FUNCTION public.sp_get_artifacts_list(i_task_id bigint[], i_instance_id bigint[], i_target_id bigint[], i_connect_server_ip text) OWNER TO cppoltp;

--
-- Name: sp_get_artifacts_list_by_tasks(bigint[], bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_artifacts_list_by_tasks(i_task_id bigint[], i_instance_id bigint[]) RETURNS TABLE(task_id bigint, instance_id bigint, is_removed boolean, target_id bigint, task_status public.en_task_status, server_time timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
	BEGIN
		RETURN QUERY
			SELECT
				t.task_id
				, t.instance_id
				, CASE WHEN tts.target_id IS NULL THEN TRUE
					ELSE COALESCE(upload_file.is_removed, FALSE) END AS is_removed
				, tts.target_id
				, tts.task_status
				, tts.server_time::timestamp
			FROM (
				SELECT t.task_id, t.instance_id
				FROM UNNEST(i_task_id, i_instance_id) AS t(task_id, instance_id)
			) AS t
			LEFT JOIN tb_task_target_status tts ON tts.task_id = t.task_id AND tts.instance_id = t.instance_id AND tts.task_status != 'DUPLICATED_TASK'::en_task_status
			LEFT JOIN tb_upload_file upload_file ON upload_file.task_id = tts.task_id AND tts.target_id = upload_file.node_id
		;
		
	END;
$$;


ALTER FUNCTION public.sp_get_artifacts_list_by_tasks(i_task_id bigint[], i_instance_id bigint[]) OWNER TO cppoltp;

--
-- Name: sp_get_artifacts_task_list(text, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_artifacts_task_list(i_login_admin_id text, i_start_time timestamp without time zone, i_end_time timestamp without time zone) RETURNS TABLE(task_id bigint, instance_id bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_profile_type              en_privilege_profile_type;
  v_task_type                 en_task_type[] := ARRAY['COLLECT_AHNREPORT_FILE']::en_task_type[];
BEGIN

  -- login_admin_id 의 권한 가져오기
  v_profile_type := sp_get_admin_privilege_type( i_login_admin_id );


  IF v_profile_type = 'ROOT_ADMIN' THEN

    RETURN QUERY
      SELECT ti.task_id, ti.instance_id
      FROM tb_job j
        JOIN tb_task t ON j.job_id = t.job_id AND j.visible = TRUE AND j.is_schedule = TRUE
        JOIN tb_task_instance AS ti ON ti.task_id = t.task_id
      WHERE t.task_type = ANY(v_task_type)
        AND ti.modified_time BETWEEN i_start_time AND i_end_time
      UNION ALL
      SELECT t.task_id, 0 AS instance_id
      FROM tb_job AS j
      JOIN tb_task AS t ON j.job_id = t.job_id AND j.visible = TRUE AND j.is_schedule = FALSE
      WHERE t.task_type = ANY(v_task_type)
        AND t.modified_time BETWEEN i_start_time AND i_end_time;

  ELSE

    RETURN QUERY
      SELECT ti.task_id, ti.instance_id
      FROM tb_job j
        JOIN tb_task t ON j.job_id = t.job_id AND j.visible = TRUE AND j.is_schedule = TRUE AND j.admin_id = i_login_admin_id
        JOIN tb_task_instance AS ti ON ti.task_id = t.task_id
      WHERE t.task_type = ANY(v_task_type)
        AND ti.modified_time BETWEEN i_start_time AND i_end_time
      UNION ALL
      SELECT t.task_id, 0 AS instance_id
      FROM tb_job AS j
      JOIN tb_task AS t ON j.job_id = t.job_id AND j.visible = TRUE AND j.is_schedule = FALSE AND j.admin_id = i_login_admin_id
      WHERE t.task_type = ANY(v_task_type)
        AND t.modified_time BETWEEN i_start_time AND i_end_time;

  END IF;

END;
$$;


ALTER FUNCTION public.sp_get_artifacts_task_list(i_login_admin_id text, i_start_time timestamp without time zone, i_end_time timestamp without time zone) OWNER TO cppoltp;

