--
-- Name: sp_get_base_report_data(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_base_report_data() RETURNS TABLE(base_report_id text, product_group text, base_report_group text, load_nosql_procedure text, load_nosql_to_rdb_table text, load_rdb_procedure text, summary_procedure text, report_procedure text, save_rdb_table text, fill_empty text, nosql_collection text, load_nosql_to_rdb_column text, db_type text, step text, version text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

RETURN QUERY
  SELECT br.base_report_id::text, br.product_group::text, br.base_report_group::text, br.load_nosql_procedure, br.load_nosql_to_rdb_table,
    br.load_rdb_procedure, br.summary_procedure, br.report_procedure, br.save_rdb_table, br.fill_empty::text,
    br.nosql_collection, br.load_nosql_to_rdb_column, br.db_type::text, br.step::text, COALESCE(brc.version, 1)::TEXT
  FROM tb_base_report br
  LEFT JOIN (
    SELECT b.base_report_id, b.version, ROW_NUMBER() OVER(PARTITION BY b.base_report_id ORDER BY b.version DESC) AS row_num
    FROM tb_base_report_column b
  ) AS brc ON br.base_report_id = brc.base_report_id AND brc.row_num = 1
  JOIN (
    SELECT p.product_group
    FROM tb_product p
    JOIN tb_product_license pl
    ON p.product_id = pl.product_id
      AND pl.expire_date > now()
    GROUP BY p.product_group
  ) AS tpl ON br.product_group = tpl.product_group
  WHERE enabled = TRUE
  ORDER BY br.step;

END;
$$;


ALTER FUNCTION public.sp_get_base_report_data() OWNER TO cppoltp;

