--
-- Name: sp_get_blocked_node_status(text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_blocked_node_status(i_start_time text, i_end_time text) RETURNS TABLE(node_id bigint, connection_status public.en_connection_status, integrity_status public.en_integrity_status, client_time timestamp with time zone, tz_offset integer, server_time timestamp with time zone, ip inet, computer_name text, name text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY

    SELECT DISTINCT
    ns.node_id,
    ns.connection_status,
    ns.integrity_status,
    ns.client_time,
    ns.tz_offset,
    ns.server_time,
    n.ip,
    n.computer_name,
    u.name
    FROM tb_node_status ns
    JOIN tb_node n using(node_id)
    LEFT JOIN tb_user u using(node_id)
    WHERE ns.client_time BETWEEN i_start_time::timestamp AND i_end_time::timestamp
      AND n.is_removed is FALSE
  ;

END;
$$;


