--
-- Name: sp_get_check_group_list(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_check_group_list() RETURNS TABLE(err_code text, err_msg text)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_max_depth bigint;
  v_depth bigint;
  v_space_count bigint;

BEGIN

SELECT max(lvl) + 1::bigint
      ,max(array_length(string_to_array(name, ' '), 1))
INTO v_depth
    ,v_space_count
FROM sp_get_group_list(1, true, 'ASC', null);

SELECT value
INTO v_max_depth
FROM tb_config
WHERE config_group = 'GENERAL'
  AND key = 'group_depth';

IF v_max_depth < v_depth THEN

  RAISE EXCEPTION 'max depth is (%).', v_max_depth USING HINT = 'DB-00002';

END IF;

  RETURN QUERY SELECT 'DB-00000'::text, 'success'::text;

END;
$$;


