--

CREATE FUNCTION public.sp_get_config_group_key_value(i_config_group public.en_config_group, i_key text, i_default_value text DEFAULT ''::text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_value                     text;
BEGIN

  SELECT c.value INTO v_value FROM tb_config AS c WHERE c.config_group = i_config_group AND c.key = i_key;

  IF v_value IS NULL OR TRIM(v_value) = '' THEN
    RETURN i_default_value;
  ELSE
    RETURN v_value;
  END IF;

END;
$$;


