--
-- Name: sp_get_console_upload_file_path(text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_console_upload_file_path(i_file_id text, i_file_name text) RETURNS TABLE(ip text, port text, file_path text)
    LANGUAGE plpgsql
    AS $$
BEGIN

  RETURN QUERY
  SELECT sv.ip AS ip
        ,sp.port::text AS port
        ,cuf.file_path || '/' || i_file_name AS file_path
  FROM tb_console_upload_file cuf
  JOIN tb_server sv
  ON cuf.server_id = sv.server_id
  JOIN tb_service svc
  ON sv.server_id = svc.server_id
    AND svc.service_type = 'TOMCAT-CONSOLE'
  JOIN tb_service_port sp
  ON svc.service_type = sp.service_type
  WHERE cuf.file_id = i_file_id;

END;
$$;


