--
-- Name: sp_get_correlation_ac_exec_block_count(text, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_ac_exec_block_count(i_comparison text, i_values bigint[]) RETURNS TABLE(node_id bigint, rt_val text)
    LANGUAGE plpgsql
    AS $$
DECLARE

BEGIN

  IF (i_comparison = '>') THEN
    RETURN QUERY
      SELECT
		aect.node_id as node_id
	   ,COALESCE(SUM(aect.log_count),0)::text as rt_val
	  FROM tb_ac_execution_control_timeline aect
	  WHERE aect."action" = 'BLOCK'
		AND aect.last_modified_time >= now() - CONCAT(i_values[2], 'minute')::interval
	  GROUP BY aect.node_id, aect."action"
	  HAVING SUM(aect.log_count) > i_values[1]
	  ORDER BY aect.node_id ASC;

  ELSEIF (i_comparison = '>=') THEN
    RETURN QUERY
      SELECT
		aect.node_id as node_id
	   ,COALESCE(SUM(aect.log_count),0)::text as rt_val
	  FROM tb_ac_execution_control_timeline aect
	  WHERE aect."action" = 'BLOCK'
		AND aect.last_modified_time >= now() - CONCAT(i_values[2], 'minute')::interval
	  GROUP BY aect.node_id, aect."action"
	  HAVING SUM(aect.log_count) >= i_values[1]
	  ORDER BY aect.node_id ASC;

  ELSEIF (i_comparison = '=') THEN
    RETURN QUERY
      SELECT
	    aect.node_id as node_id
	   ,COALESCE(SUM(aect.log_count),0)::text as rt_val
	  FROM tb_ac_execution_control_timeline aect
	  WHERE aect."action" = 'BLOCK'
		AND aect.last_modified_time >= now() - CONCAT(i_values[2], 'minute')::interval
	  GROUP BY aect.node_id, aect."action"
	  HAVING SUM(aect.log_count) = i_values[1]
	  ORDER BY aect.node_id ASC;

   ELSEIF (i_comparison = '<=') THEN
    RETURN QUERY
      SELECT
		aect.node_id as node_id
	   ,COALESCE(SUM(aect.log_count),0)::text as rt_val
	  FROM tb_ac_execution_control_timeline aect
	  WHERE aect."action" = 'BLOCK'
		AND aect.last_modified_time >= now() - CONCAT(i_values[2], 'minute')::interval
	  GROUP BY aect.node_id, aect."action"
	  HAVING SUM(aect.log_count) <= i_values[1]
	  ORDER BY aect.node_id ASC;

   ELSEIF (i_comparison = '<') THEN
    RETURN QUERY
      SELECT
		aect.node_id as node_id
	   ,COALESCE(SUM(aect.log_count),0)::text as rt_val
	  FROM tb_ac_execution_control_timeline aect
	  WHERE aect."action" = 'BLOCK'
		AND aect.last_modified_time >= now() - CONCAT(i_values[2], 'minute')::interval
	  GROUP BY aect.node_id, aect."action"
	  HAVING SUM(aect.log_count) < i_values[1]
	  ORDER BY aect.node_id ASC;

  END IF;


END;
$$;


