--
-- Name: sp_get_correlation_ac_im_manual_time(text, text[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_ac_im_manual_time(i_comparison text, i_values text[]) RETURNS TABLE(node_id bigint, im_manual_time text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_date_format TEXT := 'yyyy-mm-dd hh24:mi:ss';
BEGIN

  IF i_comparison = '>' THEN
    RETURN QUERY
    SELECT
      tas.node_id
      , TO_CHAR(tas.im_manual_time::TIMESTAMP, v_date_format)::TEXT
    FROM
      tb_ac_status tas
    INNER JOIN tb_product_info pi ON tas.node_id = pi.node_id AND tas.product_id = pi.product_id
    INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'AC'
    INNER JOIN tb_node AS n ON tas.node_id = n.node_id AND n.is_removed IS FALSE
    WHERE
      NOW() - tas.im_manual_time > concat(i_values[1], 'day')::INTERVAL;
  ELSEIF i_comparison = '>=' THEN
    RETURN QUERY
    SELECT
      tas.node_id
      , TO_CHAR(tas.im_manual_time::TIMESTAMP, v_date_format)::TEXT
    FROM
      tb_ac_status tas
    INNER JOIN tb_product_info pi ON tas.node_id = pi.node_id AND tas.product_id = pi.product_id
    INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'AC'
    INNER JOIN tb_node AS n ON tas.node_id = n.node_id AND n.is_removed IS FALSE
    WHERE
      NOW() - tas.im_manual_time >= concat(i_values[1], 'day')::INTERVAL;
  ELSEIF i_comparison = '=' THEN
    RETURN QUERY
    SELECT
      tas.node_id
      , TO_CHAR(tas.im_manual_time::TIMESTAMP, v_date_format)::TEXT
    FROM
      tb_ac_status tas
    INNER JOIN tb_product_info pi ON tas.node_id = pi.node_id AND tas.product_id = pi.product_id
    INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'AC'
    INNER JOIN tb_node AS n ON tas.node_id = n.node_id AND n.is_removed IS FALSE
    WHERE
      NOW() - tas.im_manual_time = concat(i_values[1], 'day')::INTERVAL;
  ELSEIF i_comparison = '<=' THEN
    RETURN QUERY
    SELECT
      tas.node_id
      , TO_CHAR(tas.im_manual_time::TIMESTAMP, v_date_format)::TEXT
    FROM
      tb_ac_status tas
    INNER JOIN tb_product_info pi ON tas.node_id = pi.node_id AND tas.product_id = pi.product_id
    INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'AC'
    INNER JOIN tb_node AS n ON tas.node_id = n.node_id AND n.is_removed IS FALSE
    WHERE
      NOW() - tas.im_manual_time <= concat(i_values[1], 'day')::INTERVAL;
  ELSEIF i_comparison = '<' THEN
    RETURN QUERY
    SELECT
      tas.node_id
      , TO_CHAR(tas.im_manual_time::TIMESTAMP, v_date_format)::TEXT
    FROM
      tb_ac_status tas
    INNER JOIN tb_product_info pi ON tas.node_id = pi.node_id AND tas.product_id = pi.product_id
    INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'AC'
    INNER JOIN tb_node AS n ON tas.node_id = n.node_id AND n.is_removed IS FALSE
    WHERE
      NOW() - tas.im_manual_time < concat(i_values[1], 'day')::INTERVAL;

  END IF;

END;
$$;


