CREATE FUNCTION public.sp_get_correlation_ac_im_watchlist_detect_count(i_comparison text, i_values text[]) RETURNS TABLE(node_id bigint, rt_val text)
    LANGUAGE plpgsql
    AS $$
DECLARE

BEGIN

  IF (i_comparison = '>') THEN
    RETURN QUERY
      SELECT
		tidwt.node_id as node_id
	   ,COALESCE(SUM(tidwt.detect_count),0)::text as rt_val
	  FROM tb_im_detect_watchlist_timeline tidwt
	  WHERE tidwt.last_modified_time >= now() - CONCAT(i_values[3]::bigint, 'minute')::interval
		AND CASE WHEN i_values[1] IS NOT NULL THEN tidwt.watchlist_name= i_values[1] ELSE 1=1 END	  
	  GROUP BY tidwt.node_id
	  HAVING SUM(tidwt.detect_count) > i_values[2]::bigint
	  ORDER BY tidwt.node_id ASC;

  ELSEIF (i_comparison = '>=') THEN
    RETURN QUERY
      SELECT
		tidwt.node_id as node_id
	   ,COALESCE(SUM(tidwt.detect_count),0)::text as rt_val
