--
-- Name: sp_get_correlation_agent_version(text, text[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_agent_version(i_comparison text, i_values text[]) RETURNS TABLE(node_id bigint, agent_version text)
    LANGUAGE plpgsql
    AS $$
BEGIN

IF i_comparison = '=' THEN
  RETURN QUERY
  SELECT n.node_id, n.agent_version FROM tb_node n WHERE n.is_removed IS FALSE AND n.agent_version = i_values[1];
ELSEIF i_comparison = 'LIKE' THEN
  RETURN QUERY
  SELECT n.node_id, n.agent_version FROM tb_node n WHERE n.is_removed IS FALSE AND n.agent_version ilike '%' || i_values[1] || '%';
END IF;

END;
$$;


ALTER FUNCTION public.sp_get_correlation_agent_version(i_comparison text, i_values text[]) OWNER TO cppoltp;

--
-- Name: sp_get_correlation_certificate_expire(text, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_certificate_expire(i_comparison text, i_values bigint[]) RETURNS TABLE(dummy bigint, expire_date text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT
     1::bigint AS id
     , concat(
       key, '||'
       , VALUE, '||'
       , (SELECT value FROM tb_config WHERE config_group = 'SYS_NET_CERT' AND key = 'correlation_alret_sent' )
     ) AS value
    FROM
     tb_config
    WHERE
     config_group = 'SYS_NET_CERT'
     AND KEY = (SELECT (CASE WHEN (SELECT tc.value FROM tb_config tc
                               WHERE tc.config_group = 'SYS_NET_CERT'
                               AND tc.key = 'cert_current_type') = 'epp'
                               THEN 'cert_epp_expire_date'
                               ELSE 'cert_site_expire_date' END)
                               )
    AND EXTRACT(DAY FROM value::timestamp - now()) <= i_values[1]
  ;
END;
$$;


