CREATE FUNCTION public.sp_get_correlation_condition_data() RETURNS TABLE(correlation_condition_id text, correlation_type text, db_type text, collection text, comparison_candidate text, macro_candidate text, procedure text, product_group text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

-- get predefined correlation conditions
RETURN QUERY
SELECT cc.correlation_condition_id::text, cc.correlation_type::text, cc.db_type::text, cc.collection::text, cc.comparison_candidate::text, cc.macro_candidate::text, cc.procedure::text, cc.product_group::text
FROM tb_correlation_condition cc;

END;
$$;


