--
-- Name: sp_get_correlation_condition_list(public.en_correlation_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_condition_list(i_correlation_type public.en_correlation_type) RETURNS TABLE(correlation_condition_id public.en_correlation_condition_id_type, correlation_type public.en_correlation_type, collection text, comparison_candidate text, macro_candidate text, procedure text, product_group public.en_product_group_type, db_type public.en_db_type)
    LANGUAGE plpgsql
    AS $$

BEGIN

RETURN QUERY

SELECT cc.correlation_condition_id  AS correlation_condition_id
      ,cc.correlation_type  AS correlation_type
      ,cc.collection  AS collection
      ,cc.comparison_candidate   AS comparison_candidate
      ,cc.macro_candidate   AS macro_candidate
      ,cc.procedure    AS procedure
      ,cc.product_group    AS product_group
      ,cc.db_type  AS db_type
FROM tb_correlation_condition AS cc /*연계 규칙 매핑  */
WHERE cc.correlation_type = coalesce(i_correlation_type, cc.correlation_type) --1.'GENERAL',2.모두
AND cc.correlation_condition_id::text in (SELECT UNNEST(ENUM_RANGE(NULL::en_mail_template_macro_type))::text)
;


END;
$$;


