--
-- Name: sp_get_correlation_cpu(text, numeric[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_cpu(i_comparison text, i_values numeric[]) RETURNS TABLE(server_id bigint, avg_used_cpu text)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
    SELECT
      t.server_id, TO_CHAR(t.avg_used_cpu, 'FM990.00')
    FROM (
      SELECT sr.server_id, ROUND(AVG(sr.used_cpu), 2) avg_used_cpu
      FROM tb_server_resource sr
      WHERE log_time > (NOW() - INTERVAL '5' MINUTE)
      GROUP BY sr.server_id
    ) t
    WHERE
      CASE
        WHEN i_comparison = '>' THEN t.avg_used_cpu > i_values[1]
        WHEN i_comparison = '>=' THEN t.avg_used_cpu >= i_values[1]
        WHEN i_comparison = '<' THEN t.avg_used_cpu < i_values[1]
        WHEN i_comparison = '<=' THEN t.avg_used_cpu <= i_values[1]
        WHEN i_comparison = '=' THEN t.avg_used_cpu = i_values[1]
        ELSE FALSE
      END
    ;
END;
$$;


ALTER FUNCTION public.sp_get_correlation_cpu(i_comparison text, i_values numeric[]) OWNER TO cppoltp;

--
-- Name: sp_get_correlation_db_file_size(text, numeric[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_db_file_size(i_comparison text, i_values numeric[]) RETURNS TABLE(server_id bigint, max_db_size text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
  RETURN QUERY
    SELECT t.server_id, ROUND(t.max_db_size,2)::TEXT
      FROM (
        SELECT sr.server_id, MAX(sr.oltp_db_size+sr.log_db_size) / 1024.0 AS max_db_size
        FROM tb_server_resource sr
        WHERE log_time > (NOW() - INTERVAL '5' MINUTE)
        GROUP BY sr.server_id
      ) t
      WHERE
        CASE
          WHEN i_comparison = '>' THEN t.max_db_size > i_values[1]
          WHEN i_comparison = '>=' THEN t.max_db_size >= i_values[1]
          WHEN i_comparison = '<' THEN t.max_db_size < i_values[1]
          WHEN i_comparison = '<=' THEN t.max_db_size <= i_values[1]
          WHEN i_comparison = '=' THEN t.max_db_size = i_values[1]
          ELSE FALSE
        END
      ;
END;
$$;


ALTER FUNCTION public.sp_get_correlation_db_file_size(i_comparison text, i_values numeric[]) OWNER TO cppoltp;

--
-- Name: sp_get_correlation_disk_usage(text, numeric[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_disk_usage(i_comparison text, i_values numeric[]) RETURNS TABLE(server_id bigint, avg_used_hdd text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
  RETURN QUERY
    SELECT t.server_id, TO_CHAR(t.avg_used_hdd, 'FM990.00')
    FROM (
      SELECT sr.server_id, MAX(100*sr.used_hdd/(used_hdd+avail_hdd))::NUMERIC AS avg_used_hdd
      FROM tb_server_resource sr
      WHERE log_time > (NOW() - INTERVAL '5' MINUTE)
      GROUP BY sr.server_id
    ) t
    WHERE
      CASE
        WHEN i_comparison = '>' THEN t.avg_used_hdd > i_values[1]
        WHEN i_comparison = '>=' THEN t.avg_used_hdd >= i_values[1]
        WHEN i_comparison = '<' THEN t.avg_used_hdd < i_values[1]
        WHEN i_comparison = '<=' THEN t.avg_used_hdd <= i_values[1]
        WHEN i_comparison = '=' THEN t.avg_used_hdd = i_values[1]
        ELSE FALSE
      END
    ;
END;
$$;


