--
-- Name: sp_get_correlation_exclude_data(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_exclude_data() RETURNS TABLE(correlation_rule_id text, target_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

-- get correlation exception nodes
RETURN QUERY
SELECT ce.correlation_rule_id::text, ce.target_id::text FROM tb_correlation_exclude ce WHERE exclude_type = 'NODE'
UNION
SELECT t.correlation_rule_id::text, n.node_id::text FROM tb_group g
JOIN (SELECT ce.correlation_rule_id, ce.target_id FROM tb_correlation_exclude ce
WHERE exclude_type = 'GROUP') t ON g.group_id = t.target_id
JOIN tb_node n ON n.group_id = g.group_id
ORDER BY 1;

END;
$$;


ALTER FUNCTION public.sp_get_correlation_exclude_data() OWNER TO cppoltp;

--
-- Name: sp_get_correlation_file_server_disk_size(text, numeric[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_file_server_disk_size(i_comparison text, i_values numeric[]) RETURNS TABLE(server_id bigint, max_disk_size text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
  RETURN QUERY
    SELECT t.server_id, t.max_disk_size::text
    FROM (
      SELECT sr.server_id, (MAX(sr.used_hdd) / 1024.0)::NUMERIC AS max_disk_size
      FROM tb_server_resource sr
        JOIN tb_service s ON sr.server_id = s.server_id
          AND s.enabled IS TRUE
          AND s.service_type IN ('FILESERVER-UPLOAD','FILESERVER-HTTP')
      WHERE log_time > (NOW() - INTERVAL '5' MINUTE)
      GROUP BY sr.server_id
    ) t
    WHERE
      CASE
        WHEN i_comparison = '>' THEN t.max_disk_size > i_values[1]
        WHEN i_comparison = '>=' THEN t.max_disk_size >= i_values[1]
        WHEN i_comparison = '<' THEN t.max_disk_size < i_values[1]
        WHEN i_comparison = '<=' THEN t.max_disk_size <= i_values[1]
        WHEN i_comparison = '=' THEN t.max_disk_size = i_values[1]
        ELSE FALSE
      END
    ;
END;
$$;


