--
-- Name: sp_get_correlation_hips_applying_count(text, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_hips_applying_count(i_comparison text, i_values bigint[]) RETURNS TABLE(node_id bigint, applying_signature_count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
    IF i_comparison = '>' THEN
        RETURN QUERY
            SELECT
                hips.node_id,
                SUM(COALESCE(hips.signature_count,0)) AS applying_signature_count
            FROM
                tb_hips_status hips
                INNER JOIN tb_node node ON node.node_id = hips.node_id AND node.is_removed IS FALSE
                INNER JOIN tb_product_info node_product_info ON node_product_info.node_id = node.node_id
                INNER JOIN tb_product product ON product.product_id = node_product_info.product_id
                    AND product.product_group IN ('HIPS')
            WHERE
                hips.ips_status = 'ON'
            GROUP BY
                hips.node_id
            HAVING
                SUM(COALESCE(hips.signature_count,0)) > i_values[1];

    ELSEIF i_comparison = '>=' THEN
        RETURN QUERY
            SELECT
                hips.node_id,
                SUM(COALESCE(hips.signature_count,0)) AS applying_signature_count
            FROM
                tb_hips_status hips
                INNER JOIN tb_node node ON node.node_id = hips.node_id AND node.is_removed IS FALSE
                INNER JOIN tb_product_info node_product_info ON node_product_info.node_id = node.node_id
                INNER JOIN tb_product product ON product.product_id = node_product_info.product_id
                    AND product.product_group IN ('HIPS')
            WHERE
                hips.ips_status = 'ON'
            GROUP BY
                hips.node_id
            HAVING
                SUM(COALESCE(hips.signature_count,0)) >= i_values[1];
    ELSEIF i_comparison = '=' THEN
        RETURN QUERY
            SELECT
                hips.node_id,
                SUM(COALESCE(hips.signature_count,0)) AS applying_signature_count
            FROM
                tb_hips_status hips
                INNER JOIN tb_node node ON node.node_id = hips.node_id AND node.is_removed IS FALSE
                INNER JOIN tb_product_info node_product_info ON node_product_info.node_id = node.node_id
                INNER JOIN tb_product product ON product.product_id = node_product_info.product_id
                    AND product.product_group IN ('HIPS')
            WHERE
                hips.ips_status = 'ON'
            GROUP BY
                hips.node_id
            HAVING
                SUM(COALESCE(hips.signature_count,0)) = i_values[1];
    ELSEIF i_comparison = '<=' THEN
        RETURN QUERY
            SELECT
                hips.node_id,
                SUM(COALESCE(hips.signature_count,0)) AS applying_signature_count
            FROM
                tb_hips_status hips
                INNER JOIN tb_node node ON node.node_id = hips.node_id AND node.is_removed IS FALSE
                INNER JOIN tb_product_info node_product_info ON node_product_info.node_id = node.node_id
                INNER JOIN tb_product product ON product.product_id = node_product_info.product_id
                    AND product.product_group IN ('HIPS')
            WHERE
                hips.ips_status = 'ON'
            GROUP BY
                hips.node_id
            HAVING
                SUM(COALESCE(hips.signature_count,0)) <= i_values[1];
    ELSEIF i_comparison = '<' THEN
        RETURN QUERY
            SELECT
                hips.node_id,
                SUM(COALESCE(hips.signature_count,0)) AS applying_signature_count
            FROM
                tb_hips_status hips
                INNER JOIN tb_node node ON node.node_id = hips.node_id AND node.is_removed IS FALSE
                INNER JOIN tb_product_info node_product_info ON node_product_info.node_id = node.node_id
                INNER JOIN tb_product product ON product.product_id = node_product_info.product_id
                    AND product.product_group IN ('HIPS')
            WHERE
                hips.ips_status = 'ON'
            GROUP BY
                hips.node_id
            HAVING
                SUM(COALESCE(hips.signature_count,0)) < i_values[1];
END IF;

END;
$$;


