                AND hips.modified_time > (NOW() - CONCAT(i_values[3]::bigint,' minute')::INTERVAL)
            GROUP BY
                hips.node_id
            HAVING
                COUNT(hips.name) < i_values[2]::bigint;
END IF;

END;
$$;


