--
-- Name: sp_get_correlation_last_connect_time(text, text[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_last_connect_time(i_comparison text, i_values text[]) RETURNS TABLE(node_id bigint, connect_time text)
    LANGUAGE plpgsql
    AS $$
declare
  v_date_format text := 'yyyy-mm-dd hh24:mi:ss';
BEGIN
    
IF array_length(i_values, 1) = 1 then
    IF i_comparison = '>' then
      RETURN QUERY SELECT ns.node_id, TO_CHAR(ns.server_time::TIMESTAMP, v_date_format) FROM tb_node_status ns
      JOIN tb_node AS n ON ns.node_id = n.node_id AND n.is_removed IS FALSE
      WHERE now() - ns.server_time > concat(i_values[1]::bigint, 'day')::INTERVAL;
    ELSEIF i_comparison = '>=' THEN
      RETURN QUERY SELECT ns.node_id, TO_CHAR(ns.server_time::TIMESTAMP, v_date_format)::text FROM tb_node_status ns
      JOIN tb_node AS n ON ns.node_id = n.node_id AND n.is_removed IS FALSE
      WHERE now() - ns.server_time >= concat(i_values[1]::bigint, 'day')::INTERVAL;
    ELSEIF i_comparison = '<' THEN
      RETURN QUERY SELECT ns.node_id, TO_CHAR(ns.server_time::TIMESTAMP, v_date_format)::text FROM tb_node_status ns
      JOIN tb_node AS n ON ns.node_id = n.node_id AND n.is_removed IS FALSE
      WHERE now() - ns.server_time < concat(i_values[1]::bigint, 'day')::INTERVAL;
    ELSEIF i_comparison = '<=' THEN
      RETURN QUERY SELECT ns.node_id, TO_CHAR(ns.server_time::TIMESTAMP, v_date_format)::text FROM tb_node_status ns
      JOIN tb_node AS n ON ns.node_id = n.node_id AND n.is_removed IS FALSE
      WHERE now() - ns.server_time <= concat(i_values[1]::bigint, 'day')::INTERVAL;
    ELSEIF i_comparison = '=' THEN
      RETURN QUERY SELECT ns.node_id, TO_CHAR(ns.server_time::TIMESTAMP, v_date_format)::text FROM tb_node_status ns
      JOIN tb_node AS n ON ns.node_id = n.node_id AND n.is_removed IS FALSE
      WHERE now() - ns.server_time = concat(i_values[1]::bigint, 'day')::INTERVAL;
    END IF;
ELSEIF array_length(i_values, 1) = 2 then
    IF i_values[1] = 'DAY' THEN
        IF i_comparison = '>' then
          RETURN QUERY SELECT ns.node_id, TO_CHAR(ns.server_time::TIMESTAMP, v_date_format) FROM tb_node_status ns
          JOIN tb_node AS n ON ns.node_id = n.node_id AND n.is_removed IS FALSE
          WHERE now() - ns.server_time > concat(i_values[2]::bigint, 'day')::INTERVAL;
        ELSEIF i_comparison = '>=' THEN
          RETURN QUERY SELECT ns.node_id, TO_CHAR(ns.server_time::TIMESTAMP, v_date_format)::text FROM tb_node_status ns
          JOIN tb_node AS n ON ns.node_id = n.node_id AND n.is_removed IS FALSE
          WHERE now() - ns.server_time >= concat(i_values[2]::bigint, 'day')::INTERVAL;
        ELSEIF i_comparison = '<' THEN
          RETURN QUERY SELECT ns.node_id, TO_CHAR(ns.server_time::TIMESTAMP, v_date_format)::text FROM tb_node_status ns
          JOIN tb_node AS n ON ns.node_id = n.node_id AND n.is_removed IS FALSE
          WHERE now() - ns.server_time < concat(i_values[2]::bigint, 'day')::INTERVAL;
        ELSEIF i_comparison = '<=' THEN
          RETURN QUERY SELECT ns.node_id, TO_CHAR(ns.server_time::TIMESTAMP, v_date_format)::text FROM tb_node_status ns
          JOIN tb_node AS n ON ns.node_id = n.node_id AND n.is_removed IS FALSE
          WHERE now() - ns.server_time <= concat(i_values[2]::bigint, 'day')::INTERVAL;
        ELSEIF i_comparison = '=' THEN
          RETURN QUERY SELECT ns.node_id, TO_CHAR(ns.server_time::TIMESTAMP, v_date_format)::text FROM tb_node_status ns
          JOIN tb_node AS n ON ns.node_id = n.node_id AND n.is_removed IS FALSE
          WHERE now() - ns.server_time = concat(i_values[2]::bigint, 'day')::INTERVAL;
        END IF;
    ELSEIF i_values[1] = 'MINUTE' THEN
        IF i_comparison = '>' then
          RETURN QUERY SELECT ns.node_id, TO_CHAR(ns.server_time::TIMESTAMP, v_date_format) FROM tb_node_status ns
          JOIN tb_node AS n ON ns.node_id = n.node_id AND n.is_removed IS FALSE
          WHERE now() - ns.server_time > concat(i_values[2]::bigint, 'minute')::INTERVAL;
        ELSEIF i_comparison = '>=' THEN
          RETURN QUERY SELECT ns.node_id, TO_CHAR(ns.server_time::TIMESTAMP, v_date_format)::text FROM tb_node_status ns
          JOIN tb_node AS n ON ns.node_id = n.node_id AND n.is_removed IS FALSE
          WHERE now() - ns.server_time >= concat(i_values[2]::bigint, 'minute')::INTERVAL;
        ELSEIF i_comparison = '<' THEN
          RETURN QUERY SELECT ns.node_id, TO_CHAR(ns.server_time::TIMESTAMP, v_date_format)::text FROM tb_node_status ns
          JOIN tb_node AS n ON ns.node_id = n.node_id AND n.is_removed IS FALSE
          WHERE now() - ns.server_time < concat(i_values[2]::bigint, 'minute')::INTERVAL;
        ELSEIF i_comparison = '<=' THEN
          RETURN QUERY SELECT ns.node_id, TO_CHAR(ns.server_time::TIMESTAMP, v_date_format)::text FROM tb_node_status ns
          JOIN tb_node AS n ON ns.node_id = n.node_id AND n.is_removed IS FALSE
          WHERE now() - ns.server_time <= concat(i_values[2]::bigint, 'minute')::INTERVAL;
        ELSEIF i_comparison = '=' THEN
          RETURN QUERY SELECT ns.node_id, TO_CHAR(ns.server_time::TIMESTAMP, v_date_format)::text FROM tb_node_status ns
          JOIN tb_node AS n ON ns.node_id = n.node_id AND n.is_removed IS FALSE
          WHERE now() - ns.server_time = concat(i_values[2]::bigint, 'minute')::INTERVAL;
        END IF;
    END IF;
END IF;

END;
$$;


ALTER FUNCTION public.sp_get_correlation_last_connect_time(i_comparison text, i_values text[]) OWNER TO cppoltp;

--
-- Name: sp_get_correlation_last_scan_time(text, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_last_scan_time(i_comparison text, i_values bigint[]) RETURNS TABLE(node_id bigint, last_scan_time text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

IF i_comparison = '>' THEN
  RETURN QUERY
  SELECT
    ns.node_id
    , ns.last_scan_time::text
  FROM
    tb_v3_status ns
    JOIN tb_product_info pi ON ns.node_id = pi.node_id AND ns.product_id = pi.product_id
    JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'V3'
    JOIN tb_node AS n ON ns.node_id = n.node_id AND n.is_removed IS FALSE
  WHERE
    now() - ns.last_scan_time > concat(i_values[1], 'day')::INTERVAL
  ;

ELSEIF i_comparison = '>=' THEN
  RETURN QUERY
  SELECT
    ns.node_id
    , ns.last_scan_time::text
  FROM
    tb_v3_status ns
    JOIN tb_product_info pi ON ns.node_id = pi.node_id AND ns.product_id = pi.product_id
    JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'V3'
    JOIN tb_node AS n ON ns.node_id = n.node_id AND n.is_removed IS FALSE
  WHERE
    now() - ns.last_scan_time >= concat(i_values[1], 'day')::INTERVAL
  ;

ELSEIF i_comparison = '=' THEN
  RETURN QUERY
  SELECT
    ns.node_id
    , ns.last_scan_time::text
  FROM
    tb_v3_status ns
    JOIN tb_product_info pi ON ns.node_id = pi.node_id AND ns.product_id = pi.product_id
    JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'V3'
    JOIN tb_node AS n ON ns.node_id = n.node_id AND n.is_removed IS FALSE
  WHERE
    now() - ns.last_scan_time = concat(i_values[1], 'day')::INTERVAL
  ;

ELSEIF i_comparison = '<=' THEN
  RETURN QUERY
  SELECT
    ns.node_id
    , ns.last_scan_time::text
  FROM
    tb_v3_status ns
    JOIN tb_product_info pi ON ns.node_id = pi.node_id AND ns.product_id = pi.product_id
    JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'V3'
    JOIN tb_node AS n ON ns.node_id = n.node_id AND n.is_removed IS FALSE
  WHERE
    now() - ns.last_scan_time <= concat(i_values[1], 'day')::INTERVAL
  ;

ELSEIF i_comparison = '<' THEN
  RETURN QUERY
  SELECT
    ns.node_id
    , ns.last_scan_time::text
  FROM
    tb_v3_status ns
    JOIN tb_product_info pi ON ns.node_id = pi.node_id AND ns.product_id = pi.product_id
    JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'V3'
    JOIN tb_node AS n ON ns.node_id = n.node_id AND n.is_removed IS FALSE
  WHERE
    now() - ns.last_scan_time < concat(i_values[1], 'day')::INTERVAL
  ;

END IF;

END;
$$;


ALTER FUNCTION public.sp_get_correlation_last_scan_time(i_comparison text, i_values bigint[]) OWNER TO cppoltp;

--
-- Name: sp_get_correlation_license_expire(text, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_license_expire(i_comparison text, i_values bigint[]) RETURNS TABLE(dummy bigint, expire_date text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  -- 만료 몇일 이내 (기준 : expire_date - now())
  IF (i_comparison = '<=') THEN
    RETURN QUERY
    SELECT
      1::bigint as id
      , concat(
         p.name , '||'
         , to_char(pl.service_date, 'yyyy-mm-dd hh24:mi:ss') , '||'
         , to_char(
             (CASE 
               WHEN pl.next_license_start_date IS NOT NULL 
                 AND ABS((pl.next_license_start_date::date - pl.expire_date::date)) <= 1
               THEN pl.next_license_expire_date
               ELSE pl.expire_date
             END)::timestamp, 'yyyy-mm-dd hh24:mi:ss'
           ) , '||'
         , pl.correlation_alret_sent , '||'
         , pl.product_id
      ) as value
      FROM
        tb_product_license pl
        JOIN tb_product p ON pl.product_id = p.product_id
      WHERE
        EXTRACT(DAY FROM 
          (CASE 
            WHEN pl.next_license_start_date IS NOT NULL 
              AND ABS((pl.next_license_start_date::date - pl.expire_date::date)) <= 1
            THEN pl.next_license_expire_date
            ELSE pl.expire_date
          END)::timestamp - now()) <= i_values[1]
      ORDER BY
        service_date ASC
    ;

  -- 만료 몇일 이후  (기준 :  now() - expire_date)
  ELSEIF (i_comparison = '>=') THEN
    RETURN QUERY
      SELECT
        1::bigint as id
        , concat(
            p.name , '||'
            , to_char(pl.service_date, 'yyyy-mm-dd hh24:mi:ss') , '||'
            , to_char(
                (CASE 
                  WHEN pl.next_license_start_date IS NOT NULL 
                    AND ABS((pl.next_license_start_date::date - pl.expire_date::date)) <= 1
                  THEN pl.next_license_expire_date
                  ELSE pl.expire_date
                END)::timestamp, 'yyyy-mm-dd hh24:mi:ss'
              ) , '||'
            , pl.correlation_alret_sent , '||'
            , pl.product_id
        ) as value
      FROM
        tb_product_license pl
        JOIN tb_product p ON pl.product_id = p.product_id
      WHERE
        EXTRACT(DAY FROM now() - 
          (CASE 
            WHEN pl.next_license_start_date IS NOT NULL 
              AND ABS((pl.next_license_start_date::date - pl.expire_date::date)) <= 1
            THEN pl.next_license_expire_date
            ELSE pl.expire_date
          END)::timestamp) >= i_values[1]
      ORDER BY
        service_date ASC
      ;
  END IF;


END;
$$;


ALTER FUNCTION public.sp_get_correlation_license_expire(i_comparison text, i_values bigint[]) OWNER TO cppoltp;

--
-- Name: sp_get_correlation_memory(text, numeric[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_memory(i_comparison text, i_values numeric[]) RETURNS TABLE(server_id bigint, avg_used_mem text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
  RETURN QUERY
    SELECT
      t.server_id, TO_CHAR(t.avg_used_mem, 'FM990.00')
    FROM (
      SELECT sr.server_id, ROUND(AVG(100*sr.used_mem/(used_mem+avail_mem)), 2) avg_used_mem
      FROM tb_server_resource sr
      WHERE log_time > (NOW() - INTERVAL '5' MINUTE)
      GROUP BY sr.server_id
    ) t
    WHERE
      CASE
        WHEN i_comparison = '>' THEN t.avg_used_mem > i_values[1]
        WHEN i_comparison = '>=' THEN t.avg_used_mem >= i_values[1]
        WHEN i_comparison = '<' THEN t.avg_used_mem < i_values[1]
        WHEN i_comparison = '<=' THEN t.avg_used_mem <= i_values[1]
        WHEN i_comparison = '=' THEN t.avg_used_mem = i_values[1]
        ELSE FALSE
      END
    ;
END;
$$;


ALTER FUNCTION public.sp_get_correlation_memory(i_comparison text, i_values numeric[]) OWNER TO cppoltp;

--
-- Name: sp_get_correlation_need_refresh(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_need_refresh(i_server_id bigint) RETURNS TABLE(need_correlation_refresh text)
    LANGUAGE plpgsql
    AS $$

DECLARE
  v_need_correlation_refresh text;
BEGIN

  SELECT
    sv.need_correlation_refresh::text
  INTO
    v_need_correlation_refresh
  FROM
    tb_server sv
  WHERE sv.server_id = i_server_id
  ;

  IF v_need_correlation_refresh THEN
    UPDATE tb_server SET need_correlation_refresh = false WHERE server_id = i_server_id;
  END IF;

  RETURN QUERY
    SELECT v_need_correlation_refresh;

END;
$$;


