--
-- Name: sp_get_correlation_no_license_user(text, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_no_license_user(i_comparison text, i_values bigint[]) RETURNS TABLE(node_id bigint, dummy text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

RETURN QUERY
SELECT ps.node_id, STRING_AGG(ps.prod_type, ',') FROM  (

  SELECT
    n.node_id
    , 'V3' AS prod_type
  FROM
    tb_node n
    JOIN tb_product_info pi ON n.node_id = pi.node_id
    JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'V3'
    LEFT JOIN tb_product_license pl ON pi.product_id = pl.product_id
  WHERE
    n.is_removed IS FALSE
    AND (pl.license_no = '' OR pl.license_no IS NULL)
  UNION ALL
  SELECT
    n.node_id
    , 'AC' AS prod_type
  FROM
    tb_node n
    JOIN tb_product_info pi ON n.node_id = pi.node_id
    JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'AC'
    LEFT JOIN tb_product_license pl ON pi.product_id = pl.product_id
  WHERE
    n.is_removed IS FALSE
    AND (pl.license_no = '' OR pl.license_no IS NULL)

  UNION ALL
  SELECT
    n.node_id
    , 'HIPS' AS prod_type
  FROM
    tb_node n
    JOIN tb_product_info pi ON n.node_id = pi.node_id
    JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'
    LEFT JOIN tb_product_license pl ON pi.product_id = pl.product_id
  WHERE
    n.is_removed IS FALSE
    AND (pl.license_no = '' OR pl.license_no IS NULL)
) ps
GROUP BY
  ps.node_id
;

END;
$$;


ALTER FUNCTION public.sp_get_correlation_no_license_user(i_comparison text, i_values bigint[]) OWNER TO cppoltp;

--
-- Name: sp_get_correlation_node_failure(text, text[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_node_failure(i_comparison text, i_values text[]) RETURNS TABLE(node_id bigint, occurred_at timestamp without time zone, department text, product_id text, log_type text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
  SELECT
      tnfh.node_id AS node_id
      , tnfh.occurred_at AS occurred_at
      , tnfh.department AS department
      , tnfh.product_id::text AS product_id
      , tnfh.log_type AS log_type
  FROM
      tb_node_failure_history tnfh 
  INNER JOIN
      tb_node tn 
  ON
      tn.node_id = tnfh.node_id 
  AND
      tn.is_removed IS FALSE
  WHERE
      tnfh.occurred_at >= i_values[1]::timestamp WITH time ZONE
  AND
      tnfh.occurred_at < i_values[2]::timestamp WITH time ZONE
  AND
      tnfh.log_type = ANY(SELECT val
                          FROM unnest(i_values[3:array_length(i_values, 1)]) AS val)
  ORDER BY tnfh.history_id ASC;

END;
$$;


ALTER FUNCTION public.sp_get_correlation_node_failure(i_comparison text, i_values text[]) OWNER TO cppoltp;

--
-- Name: sp_get_correlation_product_install(text, public.en_product_id_type[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_product_install(i_comparison text, i_values public.en_product_id_type[]) RETURNS TABLE(node_id bigint, dummy text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

IF i_values[1] = 'AGENT' then
  RETURN QUERY
  SELECT n.node_id, i_values[1]::text FROM tb_node AS n WHERE n.is_removed IS FALSE;
ELSE
  RETURN QUERY
  SELECT pi.node_id, p.product_id::text FROM tb_product_info pi
  JOIN tb_node AS n ON pi.node_id = n.node_id AND n.is_removed IS FALSE
  JOIN tb_product p ON p.product_id = pi.product_id AND p.product_id = i_values[1]::en_product_id_type;
END IF;

END;
$$;


