--
-- Name: sp_get_correlation_rule(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_rule(i_correlation_rule_id bigint) RETURNS TABLE(correlation_rule_id bigint, correlation_type public.en_correlation_type, name text, is_enabled text, schedule text, alarm_threshold integer, condition_text text, exclude_text text, send_notice text, base_report_id public.en_base_report_id_type, alert_template_id bigint, send_mail text, send_mail_to_target text, send_mail_to_target_agent text, custom_email text, admin_id text)
    LANGUAGE plpgsql
    AS $$

BEGIN

RETURN QUERY

SELECT cr.correlation_rule_id        AS correlation_rule_id     /* 연계 규칙 ID           */
      ,cr.correlation_type           AS correlation_type        /* 연계 규칙 타입              */
      ,cr.name                       AS name                    /* 연계 규칙 명                            */
      ,cr.is_enabled::text           AS is_enabled              /* 사용 여부                                */
      ,cr.schedule                   AS schedule                /* 실행 주기                                */
      ,cr.alarm_threshold            AS alarm_threshold         /* 재알림 제한 (분)         */
      ,cr.condition_text             AS condition_text          /* 조건 표시용 텍스트                      */
      ,cr.exclude_text               AS exclude_text            /* 예외 표시용 텍스트                      */
      ,cr.send_notice::text          AS send_notice             /* 공지사항 전송 여부                      */
      ,cr.base_report_id             AS base_report_id          /* 보고서 타입                             */
      ,cr.alert_template_id          AS alert_template_id       /* 알림 템플릿 ID                  */
      ,cr.send_mail::text            AS send_mail               /* 메일 전송 여부                          */
      ,cr.send_mail_to_target::text  AS send_mail_to_target     /* 담당 관리자에 전송 여부  */
      ,cr.send_mail_to_target_agent::text  AS send_mail_to_target_agent     /* 발생 에이전트에 전송 여부  */
      ,cr.custom_email               AS custom_email            /* 직접 입력 메일 수신인들                 */
      ,cr.admin_id                   AS admin_id
FROM tb_correlation_rule AS cr
WHERE cr.correlation_rule_id = i_correlation_rule_id
;



END;
$$;


