--
-- Name: sp_get_correlation_rule_list(boolean, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_rule_list(i_enabled boolean, i_def_keyword text) RETURNS TABLE(correlation_rule_id bigint, correlation_type public.en_correlation_type, name text, is_enabled text, schedule text, alarm_threshold integer, condition_text text, exclude_text text, send_notice text, base_report_id public.en_base_report_id_type, alert_template_id bigint, send_mail text, send_mail_to_target text, custom_email text, admin_id text, modified_time timestamp without time zone, task_type public.en_task_type[], last_execute_time timestamp without time zone, node_count bigint, node_id_list bigint[])
    LANGUAGE plpgsql
    AS $$

DECLARE

  /*
    i_def_keyword : 정의된 검색 키워드
      1. TODAY_EXCUTE
  */

BEGIN

RETURN QUERY

    SELECT
        cr.correlation_rule_id               AS correlation_rule_id     /* 연계 규칙 ID           */
        , cr.correlation_type                  AS correlation_type        /* 연계 규칙 타입              */
        , cr.name                              AS name                    /* 연계 규칙 명                            */
        , cr.is_enabled ::text                 AS is_enabled              /* 사용 여부                                */
        , cr.schedule                          AS schedule                /* 실행 주기                                */
        , cr.alarm_threshold                   AS alarm_threshold         /* 재알림 제한 (분)         */
        , cr.condition_text                    AS condition_text          /* 조건 표시용 텍스트                      */
        , cr.exclude_text                      AS exclude_text            /* 예외 표시용 텍스트                      */
        , cr.send_notice ::text                AS send_notice             /* 공지사항 전송 여부                      */
        , cr.base_report_id                    AS base_report_id          /* 보고서 타입                             */
        , cr.alert_template_id                 AS alert_template_id       /* 알림 템플릿 ID                  */
        , cr.send_mail ::text                  AS send_mail               /* 메일 전송 여부                          */
        , cr.send_mail_to_target ::text        AS send_mail_to_target     /* 담당 관리자/ 발생 에이전트에 전송 여부  */
        , cr.custom_email                      AS custom_email            /* 직접 입력 메일 수신인들                 */
        , cr.admin_id                          AS admin_id
        , cr.modified_time                     AS modified_time           /* 변경 시각 */
        , ct.task_type
        , cr.last_execute_time
        , rk.node_count
        , rk.node_id_list
    FROM
        tb_correlation_rule cr
    LEFT JOIN
        (
        SELECT
            ct.correlation_rule_id
            , ARRAY_AGG(ct.task_type) AS task_type
        FROM
            tb_correlation_task ct
        GROUP BY
            ct.correlation_rule_id
        ) AS ct
    ON
        cr.correlation_rule_id = ct.correlation_rule_id
    LEFT JOIN
        (
        SELECT
            t.correlation_rule_id
            , count(t.*) AS node_count
            , ARRAY_AGG(t.target_id) AS node_id_list
        FROM
            (
            SELECT
                rk.correlation_rule_id
                , target_id
            FROM
                (
                SELECT
                    tcr.correlation_rule_id
                    , tcr.target_id
                    , RANK() OVER(PARTITION BY tcr.correlation_rule_id ORDER BY tcr.phase DESC) AS phase_order
                FROM
                    tb_correlation_rule cr
                INNER JOIN
                    tb_correlation_result tcr
                ON
                    tcr.correlation_rule_id = cr.correlation_rule_id
                INNER JOIN 
                    tb_node tn
                ON
                    tn.node_id = tcr.target_id
                AND 
                    tn.is_removed IS FALSE
                WHERE
                    cr.correlation_type = 'GENERAL'
                ) rk
            WHERE
                rk.phase_order = 1
            GROUP BY
                rk.correlation_rule_id
                , rk.target_id
            ) t
        GROUP BY
            t.correlation_rule_id
        ) rk
    ON
        rk.correlation_rule_id = cr.correlation_rule_id 
    WHERE
        cr.correlation_type = 'GENERAL'
    
      /* 검색 조건 필터 : 검색 필터가 없으면 전체 대상 조회한다.  */
    AND (
            (
              CASE
                WHEN i_enabled IS NULL THEN TRUE
                WHEN i_enabled IS NOT NULL THEN cr.is_enabled = i_enabled
              ELSE
                FALSE
              END
            )
            AND
            (
              CASE
                WHEN i_def_keyword IS NULL THEN TRUE
                WHEN i_def_keyword = 'TODAY_EXECUTE' THEN cr.last_execute_time BETWEEN TO_TIMESTAMP(CONCAT(TO_CHAR(NOW(), 'YYYYMMDD'), ' 000000'), 'YYYYMMDD HH24MISS')::TIMESTAMP AND TO_TIMESTAMP(CONCAT(TO_CHAR(NOW(), 'YYYYMMDD'), ' 235959'), 'YYYYMMDD HH24MISS')::TIMESTAMP
              ELSE
                FALSE
              END
            )
    )
    ;


END;
$$;


