--
-- Name: sp_get_correlation_schedule(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_schedule(i_correlation_rule_id bigint) RETURNS TABLE(correlation_rule_id bigint, schedule text, tenant_server bigint, now_time text)
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_tenant_server			BIGINT;
	v_now_time				TEXT;
BEGIN

	IF (i_correlation_rule_id = 0) then
		RETURN QUERY
			SELECT
				cr.correlation_rule_id
				, cr.schedule
				, v_tenant_server
				, v_now_time
			FROM tb_correlation_rule cr
			WHERE is_enabled = true ORDER BY cr.correlation_rule_id;
	ELSE
		SELECT
			tenant.tenant_server
			, to_char(now(), 'YYYYMMDDHH24MI') AS now_time
			INTO v_tenant_server, v_now_time
		FROM (
			SELECT
				tst.tenant_server, count(*) AS cnt
			FROM tb_schedule_trigger tst GROUP BY tst.tenant_server
		)tenant ORDER BY tenant.cnt LIMIT 1
		;

		RETURN QUERY
			SELECT
				cr.correlation_rule_id
				, cr.schedule
				, v_tenant_server
				, v_now_time
			FROM tb_correlation_rule cr
			WHERE cr.correlation_rule_id = i_correlation_rule_id AND is_enabled = true;
	END IF;

END;
$$;


