--
-- Name: sp_get_correlation_scm_compliance_scan_result_failed_detect_cou(text, text[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_scm_compliance_scan_result_failed_detect_cou(i_comparison text, i_values text[]) RETURNS TABLE(node_id bigint, rt_val text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
    IF i_comparison = '>' THEN
        RETURN QUERY
            SELECT
                scm.node_id,
                SUM(COALESCE(scm.detect_count,0))::text AS detect_count
            FROM
                tb_scm_compliance_scan_result_failed_timeline scm
                INNER JOIN tb_node node ON node.node_id = scm.node_id AND node.is_removed IS FALSE
                INNER JOIN tb_product_info node_product_info ON node_product_info.node_id = node.node_id
                INNER JOIN tb_product product ON product.product_id = node_product_info.product_id
                    AND product.product_group IN ('SCM')
            GROUP BY
                scm.node_id
            HAVING
                SUM(COALESCE(scm.detect_count,0)) > i_values[1]::bigint;

    ELSEIF i_comparison = '>=' THEN
        RETURN QUERY
            SELECT
                scm.node_id,
                SUM(COALESCE(scm.detect_count,0))::text AS detect_count
            FROM
                tb_scm_compliance_scan_result_failed_timeline scm
                INNER JOIN tb_node node ON node.node_id = scm.node_id AND node.is_removed IS FALSE
                INNER JOIN tb_product_info node_product_info ON node_product_info.node_id = node.node_id
                INNER JOIN tb_product product ON product.product_id = node_product_info.product_id
                    AND product.product_group IN ('SCM')
            GROUP BY
                scm.node_id
            HAVING
                SUM(COALESCE(scm.detect_count,0)) >= i_values[1]::bigint;
    ELSEIF i_comparison = '=' THEN
        RETURN QUERY
            SELECT
                scm.node_id,
                SUM(COALESCE(scm.detect_count,0))::text AS detect_count
            FROM
                tb_scm_compliance_scan_result_failed_timeline scm
                INNER JOIN tb_node node ON node.node_id = scm.node_id AND node.is_removed IS FALSE
                INNER JOIN tb_product_info node_product_info ON node_product_info.node_id = node.node_id
                INNER JOIN tb_product product ON product.product_id = node_product_info.product_id
                    AND product.product_group IN ('SCM')
            GROUP BY
                scm.node_id
            HAVING
                SUM(COALESCE(scm.detect_count,0)) = i_values[1]::bigint;
    ELSEIF i_comparison = '<=' THEN
        RETURN QUERY
            SELECT
                scm.node_id,
                SUM(COALESCE(scm.detect_count,0))::text AS detect_count
            FROM
                tb_scm_compliance_scan_result_failed_timeline scm
                INNER JOIN tb_node node ON node.node_id = scm.node_id AND node.is_removed IS FALSE
                INNER JOIN tb_product_info node_product_info ON node_product_info.node_id = node.node_id
                INNER JOIN tb_product product ON product.product_id = node_product_info.product_id
                    AND product.product_group IN ('SCM')
            GROUP BY
                scm.node_id
            HAVING
                SUM(COALESCE(scm.detect_count,0)) <= i_values[1]::bigint;
    ELSEIF i_comparison = '<' THEN
        RETURN QUERY
            SELECT
                scm.node_id,
                SUM(COALESCE(scm.detect_count,0))::text AS detect_count
            FROM
                tb_scm_compliance_scan_result_failed_timeline scm
                INNER JOIN tb_node node ON node.node_id = scm.node_id AND node.is_removed IS FALSE
                INNER JOIN tb_product_info node_product_info ON node_product_info.node_id = node.node_id
                INNER JOIN tb_product product ON product.product_id = node_product_info.product_id
                    AND product.product_group IN ('SCM')
            GROUP BY
                scm.node_id
            HAVING
                SUM(COALESCE(scm.detect_count,0)) < i_values[1]::bigint;
END IF;

END;
$$;


