--
-- Name: sp_get_correlation_scm_compliance_scan_result_failed_item_detec(text, text[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_scm_compliance_scan_result_failed_item_detec(i_comparison text, i_values text[]) RETURNS TABLE(node_id bigint, rt_val text)
    LANGUAGE plpgsql
    AS $$
DECLARE

BEGIN

  IF (i_comparison = '>') THEN
    RETURN QUERY
     SELECT
        scm.node_id as node_id
       ,SUM(COALESCE(scm.detect_count,0))::text AS detect_count
     FROM tb_scm_compliance_scan_result_failed_timeline scm
     WHERE scm.last_modified_time >= now() - CONCAT(i_values[3]::bigint, 'day')::interval
        AND CASE WHEN i_values[1] IS NOT NULL THEN scm.compliance_policy_id = i_values[1] ELSE 1=1 END
     GROUP BY scm.node_id
     HAVING SUM(COALESCE(scm.detect_count,0)) > i_values[2]::bigint
     ORDER BY scm.node_id ASC;

  ELSEIF (i_comparison = '>=') THEN
    RETURN QUERY
      SELECT
        scm.node_id as node_id
       ,SUM(COALESCE(scm.detect_count,0))::text AS detect_count
     FROM tb_scm_compliance_scan_result_failed_timeline scm
     WHERE scm.last_modified_time >= now() - CONCAT(i_values[3]::bigint, 'day')::interval
        AND CASE WHEN i_values[1] IS NOT NULL THEN scm.compliance_policy_id = i_values[1] ELSE 1=1 END
     GROUP BY scm.node_id
     HAVING SUM(COALESCE(scm.detect_count,0)) >= i_values[2]::bigint
     ORDER BY scm.node_id ASC;

  ELSEIF (i_comparison = '=') THEN
    RETURN QUERY
      SELECT
        scm.node_id as node_id
       ,SUM(COALESCE(scm.detect_count,0))::text AS detect_count
     FROM tb_scm_compliance_scan_result_failed_timeline scm
     WHERE scm.last_modified_time >= now() - CONCAT(i_values[3]::bigint, 'day')::interval
        AND CASE WHEN i_values[1] IS NOT NULL THEN scm.compliance_policy_id = i_values[1] ELSE 1=1 END
     GROUP BY scm.node_id
     HAVING SUM(COALESCE(scm.detect_count,0)) = i_values[2]::bigint
     ORDER BY scm.node_id ASC;

   ELSEIF (i_comparison = '<=') THEN
    RETURN QUERY
      SELECT
        scm.node_id as node_id
       ,SUM(COALESCE(scm.detect_count,0))::text AS detect_count
     FROM tb_scm_compliance_scan_result_failed_timeline scm
     WHERE scm.last_modified_time >= now() - CONCAT(i_values[3]::bigint, 'day')::interval
        AND CASE WHEN i_values[1] IS NOT NULL THEN scm.compliance_policy_id = i_values[1] ELSE 1=1 END
     GROUP BY scm.node_id
     HAVING SUM(COALESCE(scm.detect_count,0)) <= i_values[2]::bigint
     ORDER BY scm.node_id ASC;

   ELSEIF (i_comparison = '<') THEN
    RETURN QUERY
     SELECT
        scm.node_id as node_id
       ,SUM(COALESCE(scm.detect_count,0))::text AS detect_count
     FROM tb_scm_compliance_scan_result_failed_timeline scm
     WHERE scm.last_modified_time >= now() - CONCAT(i_values[3]::bigint, 'day')::interval
        AND CASE WHEN i_values[1] IS NOT NULL THEN scm.compliance_policy_id = i_values[1] ELSE 1=1 END
     GROUP BY scm.node_id
     HAVING SUM(COALESCE(scm.detect_count,0)) < i_values[2]::bigint
     ORDER BY scm.node_id ASC;

  END IF;


END;
$$;


