--
-- Name: sp_get_correlation_scm_last_scan_time(text, text[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_scm_last_scan_time(i_comparison text, i_values text[]) RETURNS TABLE(node_id bigint, rt_val text)
    LANGUAGE plpgsql
    AS $$
declare
  v_date_format text := 'yyyy-mm-dd hh24:mi:ss';
BEGIN

    IF i_comparison = '>' then
      RETURN QUERY SELECT scm.node_id, TO_CHAR(scm.scan_time::TIMESTAMP, v_date_format) 
      FROM tb_scm_status scm
        JOIN tb_node AS n ON scm.node_id = n.node_id AND n.is_removed IS FALSE
      WHERE now() - scm.scan_time > concat(i_values[1], 'day')::INTERVAL;
    ELSEIF i_comparison = '>=' THEN
      RETURN QUERY SELECT scm.node_id, TO_CHAR(scm.scan_time::TIMESTAMP, v_date_format)::text 
      FROM tb_scm_status scm
        JOIN tb_node AS n ON scm.node_id = n.node_id AND n.is_removed IS FALSE
      WHERE now() - scm.scan_time >= concat(i_values[1], 'day')::INTERVAL;
    ELSEIF i_comparison = '<' THEN
      RETURN QUERY SELECT scm.node_id, TO_CHAR(scm.scan_time::TIMESTAMP, v_date_format)::text 
      FROM tb_scm_status scm
        JOIN tb_node AS n ON scm.node_id = n.node_id AND n.is_removed IS FALSE
      WHERE now() - scm.scan_time < concat(i_values[1], 'day')::INTERVAL;
    ELSEIF i_comparison = '<=' THEN
      RETURN QUERY SELECT scm.node_id, TO_CHAR(scm.scan_time::TIMESTAMP, v_date_format)::text 
      FROM tb_scm_status scm
        JOIN tb_node AS n ON scm.node_id = n.node_id AND n.is_removed IS FALSE
      WHERE now() - scm.scan_time <= concat(i_values[1], 'day')::INTERVAL;
    ELSEIF i_comparison = '=' THEN
      RETURN QUERY SELECT scm.node_id, TO_CHAR(scm.scan_time::TIMESTAMP, v_date_format)::text 
      FROM tb_scm_status scm
        JOIN tb_node AS n ON scm.node_id = n.node_id AND n.is_removed IS FALSE
      WHERE now() - scm.scan_time = concat(i_values[1], 'day')::INTERVAL;
    END IF;

END;
$$;


