--
-- Name: sp_get_correlation_should_alert(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_should_alert(i_correlation_rule_id bigint) RETURNS TABLE(alert integer)
    LANGUAGE plpgsql
    AS $$
BEGIN

RETURN QUERY
WITH t AS (
UPDATE tb_correlation_rule t SET last_alert_time = now()
WHERE correlation_rule_id = i_correlation_rule_id AND (now() - coalesce(last_alert_time, '2000-01-01'::TIMESTAMP)) > coalesce(alarm_threshold*60, 0)::text::INTERVAL
RETURNING 1
)
SELECT count(*)::INT FROM t;

END;
$$;


