--
-- Name: sp_get_correlation_task_payload(text, public.en_task_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_task_payload(i_payload text, i_task_type public.en_task_type) RETURNS TABLE(payload text)
    LANGUAGE plpgsql
    AS $$

DECLARE
  v_payload text;
BEGIN

  v_payload := i_payload;

  -- send_time 가공
  IF COALESCE(v_payload::json ->> 'send_time', '') <> '' THEN
   v_payload := jsonb_set(v_payload::jsonb,'{send_time}', to_jsonb(to_char(now(), 'YYYY-MM-DD HH24:MI:SS OF00')))::text;
  END IF;

  RETURN QUERY
  SELECT v_payload AS payload;


END;
$$;


