--
-- Name: sp_get_correlation_v3_last_engine_update(text, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_v3_last_engine_update(i_comparison text, i_values bigint[]) RETURNS TABLE(node_id bigint, engine_update_time text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

IF i_comparison = '>' THEN
  RETURN QUERY
  SELECT
   v3.node_id
   , v3.engine_update_time::text
  FROM
    tb_v3_status v3
    JOIN tb_product_info pi ON v3.node_id = pi.node_id AND v3.product_id = pi.product_id
    JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'V3'
    JOIN tb_node AS n ON v3.node_id = n.node_id AND n.is_removed IS FALSE
  WHERE
    now() - v3.engine_update_time > concat(i_values[1], 'day')::INTERVAL;

ELSEIF i_comparison = '>=' THEN
  RETURN QUERY
  SELECT
   v3.node_id
   , v3.engine_update_time::text
  FROM
    tb_v3_status v3
    JOIN tb_product_info pi ON v3.node_id = pi.node_id AND v3.product_id = pi.product_id
    JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'V3'
    JOIN tb_node AS n ON v3.node_id = n.node_id AND n.is_removed IS FALSE
  WHERE
    now() - v3.engine_update_time >= concat(i_values[1], 'day')::INTERVAL;

ELSEIF i_comparison = '=' THEN
  RETURN QUERY
  SELECT
   v3.node_id
   , v3.engine_update_time::text
  FROM
    tb_v3_status v3
    JOIN tb_product_info pi ON v3.node_id = pi.node_id AND v3.product_id = pi.product_id
    JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'V3'
    JOIN tb_node AS n ON v3.node_id = n.node_id AND n.is_removed IS FALSE
  WHERE
    now() - v3.engine_update_time = concat(i_values[1], 'day')::INTERVAL;

ELSEIF i_comparison = '<=' THEN
  RETURN QUERY
  SELECT
   v3.node_id
   , v3.engine_update_time::text
  FROM
    tb_v3_status v3
    JOIN tb_product_info pi ON v3.node_id = pi.node_id AND v3.product_id = pi.product_id
    JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'V3'
    JOIN tb_node AS n ON v3.node_id = n.node_id AND n.is_removed IS FALSE
  WHERE
    now() - v3.engine_update_time <= concat(i_values[1], 'day')::INTERVAL;

ELSEIF i_comparison = '<' THEN
  RETURN QUERY
  SELECT
   v3.node_id
   , v3.engine_update_time::text
  FROM
    tb_v3_status v3
    JOIN tb_product_info pi ON v3.node_id = pi.node_id AND v3.product_id = pi.product_id
    JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'V3'
    JOIN tb_node AS n ON v3.node_id = n.node_id AND n.is_removed IS FALSE
  WHERE
    now() - v3.engine_update_time < concat(i_values[1], 'day')::INTERVAL;

END IF;

END;
$$;


ALTER FUNCTION public.sp_get_correlation_v3_last_engine_update(i_comparison text, i_values bigint[]) OWNER TO cppoltp;

--
-- Name: sp_get_correlation_v3_real_time_scan_off(text, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_v3_real_time_scan_off(i_comparison text, i_values bigint[]) RETURNS TABLE(node_id bigint, dummy text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

RETURN QUERY
SELECT DISTINCT
  v3.node_id
  , 'N/A'
FROM
  tb_v3_status v3
  JOIN tb_product_info pi ON v3.node_id = pi.node_id AND v3.product_id = pi.product_id
  JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'V3'
  JOIN tb_node AS n ON v3.node_id = n.node_id AND n.is_removed IS FALSE
WHERE
  v3.realtime_status = FALSE;

END;
$$;


ALTER FUNCTION public.sp_get_correlation_v3_real_time_scan_off(i_comparison text, i_values bigint[]) OWNER TO cppoltp;

--
-- Name: sp_get_correlation_v3_uninstall(text, text[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_correlation_v3_uninstall(i_comparison text, i_values text[]) RETURNS TABLE(node_id bigint, dummy text)
    LANGUAGE plpgsql
    AS $$
BEGIN

RETURN QUERY
  SELECT
      n.node_id, 'N/A'::TEXT
  FROM
      tb_node n
  LEFT JOIN
      tb_container_platform tcp 
  ON
      tcp.container_service_type = n.container_service_type 
  WHERE
      n.is_removed IS FALSE
  AND
      n.node_id NOT IN (
          SELECT
              pi.node_id
          FROM
              tb_product_info pi
          INNER JOIN
              tb_product p
          ON
              pi.product_id = p.product_id
          AND p.product_group = 'V3'
      )
  AND
      CASE WHEN n.machine_type != 'CONTAINER' THEN TRUE
          WHEN n.machine_type = 'CONTAINER' AND tcp.is_amc_supported IS TRUE THEN TRUE
          ELSE FALSE
          END;

END;
$$;


ALTER FUNCTION public.sp_get_correlation_v3_uninstall(i_comparison text, i_values text[]) OWNER TO cppoltp;

