--
-- Name: sp_get_custom_dashboard_ac(public.en_widget_item_type[], text[], bigint, bigint, public.en_language, text, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_custom_dashboard_ac(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text, i_node_id_arr bigint[]) RETURNS TABLE(link_type text, widget_item_type public.en_widget_item_type, widget_item_sub_type text, response_values text, ord_num bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE

    v_link_type text := 'CUSTOM_DASHBOARD';

BEGIN

  RETURN QUERY

  SELECT
   v_link_type AS link_type
   , wit.widget_item_type
   , wit.widget_item_sub_type

   , (CASE
        WHEN (org.std_group_title IS NULL OR org.std_group_title = '') AND wit.is_show_default_col IS TRUE THEN
          JSON_BUILD_OBJECT(
            'value', COALESCE(org.value, 0)
          )::text
        ELSE
            org.std_group_title
    END) AS response_values

    , ROW_NUMBER() OVER (ORDER BY org.widget_item_type, org.widget_item_sub_type, org.std_group_key, org.value DESC) AS ord_num

  FROM
    (
      SELECT
        wit.widget_item_type
        , wit.widget_item_sub_type
        , wit.product_group
        , (CASE WHEN wit.widget_item_type IN('AC_AGENT_TOP', 'AC_BLOCK_FILE_TOP', 'AC_BLOCK_HISTORY', 'AC_EXEC_LIST') THEN FALSE ELSE TRUE END) is_show_default_col
      FROM
        tb_widget_item_type wit
      WHERE
        wit.product_group = 'AC'
    ) wit
    LEFT JOIN
    (


    /* AC 설치 현황 */
    SELECT
      org_rate.widget_item_type
      , org_rate.widget_item_sub_type
      , org_rate.value
      , org_rate.std_group_key
      , org_rate.std_group_title
    FROM(
      WITH org_data AS(
      SELECT
        data.widget_item_type
        , data.widget_item_sub_type
        , SUM(data.value)::bigint AS value
        , data.std_group_key
        , data.std_group_key AS std_group_title
      FROM
        sp_get_custom_dashboard_ac_link_node_list('{AC_INSTALL}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
      WHERE
        ('AC_INSTALL' = ANY(i_widget_item_type))
        AND data.node_id= ANY(i_node_id_arr)

      GROUP BY
        data.widget_item_type
        , data.widget_item_sub_type
        , data.std_group_key
      )
      SELECT
        data.widget_item_type
        , data.widget_item_sub_type
        , data.value
        , data.std_group_key
        , data.std_group_title
      FROM
        org_data data
    ) org_rate



    /* AC 정책 */
    UNION ALL
    SELECT
          data.widget_item_type
        , data.widget_item_sub_type
        , SUM(data.value) AS value
        , data.std_group_key
        , data.std_group_key AS std_group_title
      FROM
        sp_get_custom_dashboard_ac_link_node_list('{AC_POLICY_STATUS}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
      WHERE
        ('AC_POLICY_STATUS' = ANY(i_widget_item_type))
        AND data.node_id= ANY(i_node_id_arr)
      GROUP BY
        data.widget_item_type, data.widget_item_sub_type, data.std_group_key


    /* AC 상태 */
    UNION ALL
    SELECT
          data.widget_item_type
        , data.widget_item_sub_type
        , SUM(data.value) AS value
        , data.std_group_key
        , data.std_group_key AS std_group_title
      FROM
        sp_get_custom_dashboard_ac_link_node_list('{AC_STATUS}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
      WHERE
        ('AC_STATUS' = ANY(i_widget_item_type))
        AND data.node_id= ANY(i_node_id_arr)
      GROUP BY
        data.widget_item_type, data.widget_item_sub_type, data.std_group_key

  /* AC 실행제어 차단 에이전트 순위 */
    UNION ALL
    SELECT
      data.widget_item_type
      , data.widget_item_sub_type
      , data.value
      , data.std_group_key
      , data.std_group_title
    FROM
      sp_get_custom_dashboard_ac_link_node_list('{AC_AGENT_TOP}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('AC_AGENT_TOP' = ANY(i_widget_item_type))
      AND data.node_id= ANY(i_node_id_arr)


  /* AC 실행 제어 차단 파일 순위 */
    UNION ALL
    SELECT
      data.widget_item_type
      , data.widget_item_sub_type
      , data.value
      , data.std_group_key
      , data.std_group_title
    FROM
      sp_get_custom_dashboard_ac_link_node_list('{AC_BLOCK_FILE_TOP}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('AC_BLOCK_FILE_TOP' = ANY(i_widget_item_type))


  /* AC 실행 제어 차단 추이 */
    UNION ALL
    SELECT
      data.widget_item_type
      , data.widget_item_sub_type
      , data.value
      , data.std_group_key
      , data.std_group_title
    FROM
      sp_get_custom_dashboard_ac_link_node_list('{AC_BLOCK_HISTORY}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('AC_BLOCK_HISTORY' = ANY(i_widget_item_type))


  /* AC 최근 실행 제어 이벤트 */
    UNION ALL
    SELECT
      data.widget_item_type
      , data.widget_item_sub_type
      , data.value
      , data.std_group_key
      , data.std_group_title
    FROM
      sp_get_custom_dashboard_ac_link_node_list('{AC_EXEC_LIST}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('AC_EXEC_LIST' = ANY(i_widget_item_type))

  /* AC IM 탐지 Watchlist 순위 */
    UNION ALL
    SELECT
      data.widget_item_type
      , data.widget_item_sub_type
      , data.value
      , data.std_group_key
      , data.std_group_title
    FROM
      sp_get_custom_dashboard_ac_link_node_list('{AC_IM_DETECT_WATCHLIST_TOP}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('AC_IM_DETECT_WATCHLIST_TOP' = ANY(i_widget_item_type))

  /* AC IM 탐지 규칙 순위 */
    UNION ALL
    SELECT
      data.widget_item_type
      , data.widget_item_sub_type
      , data.value
      , data.std_group_key
      , data.std_group_title
    FROM
      sp_get_custom_dashboard_ac_link_node_list('{AC_IM_DETECT_RULE_TOP}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('AC_IM_DETECT_RULE_TOP' = ANY(i_widget_item_type))

  /* AC IM 탐지 에이전트 순위 */
    UNION ALL
    SELECT
      data.widget_item_type
      , data.widget_item_sub_type
      , data.value
      , data.std_group_key
      , data.std_group_title
    FROM
      sp_get_custom_dashboard_ac_link_node_list('{AC_IM_DETECT_AGENT_TOP}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('AC_IM_DETECT_AGENT_TOP' = ANY(i_widget_item_type))
      AND data.node_id= ANY(i_node_id_arr)

  /* AC IM 탐지 파일/디렉토리 순위 */
    UNION ALL
    SELECT
      data.widget_item_type
      , data.widget_item_sub_type
      , data.value
      , data.std_group_key
      , data.std_group_title
    FROM
      sp_get_custom_dashboard_ac_link_node_list('{AC_IM_DETECT_TARGET_TYPE_TOP}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('AC_IM_DETECT_TARGET_TYPE_TOP' = ANY(i_widget_item_type))

  /* AC IM 탐지 추이 */
    UNION ALL
    SELECT
      data.widget_item_type
      , data.widget_item_sub_type
      , data.value
      , data.std_group_key
      , data.std_group_title
    FROM
      sp_get_custom_dashboard_ac_link_node_list('{AC_IM_DETECT_HISTORY}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('AC_IM_DETECT_HISTORY' = ANY(i_widget_item_type))

  ) org
  ON wit.widget_item_sub_type = org.widget_item_sub_type
  WHERE
    wit.product_group = 'AC'
    AND wit.widget_item_sub_type = ANY(i_widget_item_sub_type)
  ;


END;
$$;


ALTER FUNCTION public.sp_get_custom_dashboard_ac(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text, i_node_id_arr bigint[]) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_custom_dashboard_ac(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text, i_node_id_arr bigint[]); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_custom_dashboard_ac(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text, i_node_id_arr bigint[]) IS '
@brief [] - 제품별 및 커스텀 대시보드 > AC 요약
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_custom_dashboard_ac_link_node_list(public.en_widget_item_type[], text[], bigint, bigint, public.en_language, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_custom_dashboard_ac_link_node_list(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text) RETURNS TABLE(widget_item_type public.en_widget_item_type, widget_item_sub_type text, node_id bigint, value bigint, std_group_key text, std_group_title text)
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_product_auth_check boolean;
  v_all_target boolean;
  v_node_id_array bigint[];

  v_top_limit integer := 10;

BEGIN

  v_product_auth_check := sp_get_product_auth_check(i_product_auth, 'AC');

  IF (i_group_id IS NULL OR i_group_id < 1) AND (i_correlation_rule_id IS NULL OR i_correlation_rule_id < 1) THEN
    v_all_target := true;
  ELSE
    v_all_target := false;
    v_node_id_array := sp_get_node_list( i_group_id, i_correlation_rule_id, null );
  END IF;


  RETURN QUERY

    /* AC 설치율 */
    SELECT
      org.widget_item_type
      , org.widget_item_sub_type
      , org.node_id
      , org.value
      , '' AS std_group_key
      , '' AS std_group_title
    FROM(
      WITH possible_install_node_list AS(
        SELECT
          pf.is_server
          , n.node_id
        FROM
          tb_node n
          JOIN tb_platform pf ON n.platform_id = pf.platform_id
          LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = n.container_service_type
        WHERE
          n.is_removed IS false
          AND pf.is_supported IS TRUE
          AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
          AND ('AC_INSTALL' = ANY(i_widget_item_type))
          AND v_product_auth_check
          AND (n.machine_type != 'CONTAINER' OR n.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS TRUE)
      ), installed_server_on AS (
        SELECT
          'AC_INSTALL'::en_widget_item_type AS widget_item_type
          , 'AC_INSTALLED_SERVER_ON'::text AS widget_item_sub_type
          , n.node_id
          , 1 AS value
        FROM
          tb_node n
          JOIN tb_product_info pi ON n.node_id = pi.node_id AND n.is_removed IS FALSE
          JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'AC'
          JOIN tb_platform pf ON n.platform_id = pf.platform_id
          JOIN tb_ac_status ac ON n.node_id = ac.node_id AND ac.service_status = 'ON'
          LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = n.container_service_type
        WHERE pf.is_supported IS TRUE
          AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
          AND ('AC_INSTALL' = ANY(i_widget_item_type))
          AND ('AC_INSTALLED_SERVER_ON' = ANY(i_widget_item_sub_type))
          AND v_product_auth_check
          AND (n.machine_type != 'CONTAINER' OR n.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS TRUE)
      ), installed_server_off AS (
        SELECT
          'AC_INSTALL'::en_widget_item_type AS widget_item_type
          , 'AC_INSTALLED_SERVER_OFF'::text AS widget_item_sub_type
          , n.node_id
          , 1 AS value
        FROM
          tb_node n
          JOIN tb_product_info pi ON n.node_id = pi.node_id AND n.is_removed IS FALSE
          JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'AC'
          JOIN tb_platform pf ON n.platform_id = pf.platform_id
          JOIN tb_ac_status ac ON n.node_id = ac.node_id AND ac.service_status = 'OFF'
          LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = n.container_service_type
        WHERE pf.is_supported IS TRUE
          AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
          AND ('AC_INSTALL' = ANY(i_widget_item_type))
          AND ('AC_INSTALLED_SERVER_OFF' = ANY(i_widget_item_sub_type))
          AND v_product_auth_check
          AND (n.machine_type != 'CONTAINER' OR n.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS TRUE)
      ), not_installed_server AS (
         SELECT
          'AC_INSTALL'::en_widget_item_type AS widget_item_type
          , 'AC_NOT_INSTALL_SERVER'::text AS widget_item_sub_type
          , n.node_id
          , 1::bigint AS value
         FROM
          tb_node n
          LEFT JOIN tb_product_info pi ON n.node_id = pi.node_id AND pi.product_id = 'AC_CLIENT'
          LEFT JOIN tb_platform pf ON n.platform_id = pf.platform_id
          LEFT JOIN tb_ac_status ac_status ON ac_status.node_id = n.node_id
          LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = n.container_service_type
          WHERE
           n.is_removed IS FALSE
          AND (pi.product_id IS NULL OR ac_status.service_status IS NULL)
          AND pf.is_supported IS TRUE
          AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
          AND ('AC_INSTALL' = ANY(i_widget_item_type))
          AND ('AC_NOT_INSTALL_SERVER' = ANY(i_widget_item_sub_type))
          AND v_product_auth_check
          AND (n.machine_type != 'CONTAINER' OR n.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS TRUE)
      ), not_supported_server AS (
         SELECT
          'AC_INSTALL'::en_widget_item_type AS widget_item_type
          , 'AC_NOT_SUPPORTED_SERVER'::text AS widget_item_sub_type
          , n.node_id
          , 1::bigint AS value
         FROM
          tb_node n
          LEFT JOIN tb_product_info pi ON n.node_id = pi.node_id AND pi.product_id = 'AC_CLIENT'
          LEFT JOIN tb_platform pf ON n.platform_id = pf.platform_id
          LEFT JOIN tb_ac_status ac_status ON ac_status.node_id = n.node_id
          LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = n.container_service_type
          WHERE
           n.is_removed IS FALSE
          AND (pi.product_id IS NULL OR ac_status.service_status IS NULL)
          AND pf.is_supported IS TRUE
          AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
          AND ('AC_INSTALL' = ANY(i_widget_item_type))
          AND ('AC_NOT_SUPPORTED_SERVER' = ANY(i_widget_item_sub_type))
          AND v_product_auth_check
          AND (n.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS FALSE)
      )

      SELECT
        installed_on.widget_item_type
        , installed_on.widget_item_sub_type
        , installed_on.node_id
        , 1 AS value
      FROM
        installed_server_on installed_on

      UNION ALL
      SELECT
        installed_off.widget_item_type
        , installed_off.widget_item_sub_type
        , installed_off.node_id
        , 1 AS value
      FROM
        installed_server_off installed_off

      UNION ALL
      SELECT
          not_installed_server.widget_item_type
        , not_installed_server.widget_item_sub_type
        , not_installed_server.node_id
        , 1 AS value
      FROM
        not_installed_server
        
      UNION ALL
      SELECT
          not_supported_server.widget_item_type
        , not_supported_server.widget_item_sub_type
        , not_supported_server.node_id
        , 1 AS value
      FROM
        not_supported_server
     ) org

     /* AC 정책 */
     UNION ALL
     SELECT org.widget_item_type
          ,org.widget_item_sub_type
          ,org.node_id
          ,org.value
          ,org.std_group_key
          ,org.std_group_title
     FROM (
        SELECT 'AC_POLICY_STATUS'::en_widget_item_type AS widget_item_type
                , CASE
                    WHEN ps.policy_status IS NULL THEN CONCAT(pfm.product_feature_id, '_APPLYING')
                    ELSE CONCAT(pfm.product_feature_id, '_',  ps.policy_status)
                   END AS widget_item_sub_type
                , n.node_id
                , 1 AS value
                , '' AS std_group_key
                , '' AS std_group_title
          FROM tb_node n
          JOIN tb_product_info pi on n.node_id = pi.node_id AND n.is_removed IS FALSE
          JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'AC'
          JOIN tb_product_feature_map pfm on pfm.product_id = pi.product_id
          JOIN tb_platform platform ON n.platform_id = platform.platform_id
          JOIN tb_ac_status status ON status.node_id = n.node_id
          LEFT JOIN tb_policy_status ps  on n.node_id = ps.node_id and ps.product_feature_id = pfm.product_feature_id
          LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = n.container_service_type
          WHERE platform.is_supported IS TRUE
          AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
          AND ('AC_POLICY_STATUS'::en_widget_item_type = ANY(i_widget_item_type))
          AND v_product_auth_check
          AND (n.machine_type != 'CONTAINER' OR n.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS TRUE)
     ) org
     WHERE org.widget_item_sub_type = ANY(i_widget_item_sub_type)

    /* AC 상태 */
     UNION ALL
     SELECT org.widget_item_type
           ,org.widget_item_sub_type
          ,org.node_id
          ,org.value
          ,org.std_group_key
          ,org.std_group_title
     FROM (
        SELECT 'AC_STATUS'::en_widget_item_type AS widget_item_type
                ,CONCAT('AC_STATUS_', acst.ac_status)::text AS widget_item_sub_type
                , n.node_id as node_id
                , 1 AS value
                , '' AS std_group_key
                , '' AS std_group_title
        FROM tb_node n
        JOIN tb_product_info pi ON n.node_id = pi.node_id
        JOIN tb_product p ON pi.product_id = p.product_id
        JOIN tb_platform platform ON n.platform_id = platform.platform_id
        JOIN tb_ac_status acst on n.node_id = acst.node_id
        LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = n.container_service_type
        WHERE n.is_removed IS FALSE
        AND p.product_group = 'AC'
        AND platform.is_supported IS TRUE
        AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
        AND ('AC_STATUS'::en_widget_item_type = ANY(i_widget_item_type))
        AND v_product_auth_check
        AND (n.machine_type != 'CONTAINER' OR n.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS TRUE)
      ) org
     WHERE org.widget_item_sub_type = ANY(i_widget_item_sub_type)

    /* AC 실행 제어 차단 에이전트 순위 */
    UNION ALL
    SELECT
      'AC_AGENT_TOP'::en_widget_item_type AS widget_item_type
      , 'AC_AGENT_TOP_LAST_30_DAYS'::text AS widget_item_sub_type
      , node.node_id AS node_id
      , node.log_count AS value
      , CONCAT(node.node_id, '|', COALESCE(node.ip,node.ip_connected), '|', node.computer_name) AS std_group_key
      , JSON_BUILD_OBJECT(
        'ip', COALESCE(HOST(node.ip),HOST(node.ip_connected))
      , 'name', COALESCE(node.computer_name,'')
      , 'value',node.log_count)::TEXT AS std_group_title
    FROM (
        SELECT node.node_id, node.ip, node.computer_name, node.ip_connected, node.log_count
        FROM (
            SELECT node.node_id, node.ip, node.computer_name, node.ip_connected, COALESCE(SUM(timeline.log_count), 0) AS log_count
            FROM
              tb_node node
              INNER JOIN tb_ac_execution_control_timeline timeline ON node.node_id = timeline.node_id
                AND timeline.action = 'BLOCK'
                AND CONCAT(timeline.yyyy,timeline.mm,timeline.dd) > TO_CHAR(date_trunc('DAYS', NOW() - '29 DAYS'::interval),'YYYYMMDD')
              LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = node.container_service_type
            WHERE
              node.is_removed IS FALSE
              AND ((v_all_target) OR (v_all_target = false AND node.node_id = ANY(v_node_id_array)))
              AND ('AC_AGENT_TOP'::en_widget_item_type = ANY(i_widget_item_type))
              AND ('AC_AGENT_TOP_LAST_30_DAYS'::text = ANY(i_widget_item_sub_type))
              AND v_product_auth_check
              AND (node.machine_type != 'CONTAINER' OR node.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS TRUE)
            GROUP BY
              node.node_id, node.ip, node.computer_name
        ) node
        ORDER BY node.log_count DESC
        LIMIT v_top_limit
    ) node
    UNION ALL
    SELECT
      'AC_AGENT_TOP'::en_widget_item_type AS widget_item_type
      , 'AC_AGENT_TOP_LAST_7_DAYS'::text AS widget_item_sub_type
      , node.node_id AS node_id
      , node.log_count AS value
      , CONCAT(node.node_id, '|', COALESCE(node.ip,node.ip_connected), '|', node.computer_name) AS std_group_key
      , JSON_BUILD_OBJECT(
        'ip', COALESCE(HOST(node.ip),HOST(node.ip_connected))
        , 'name', COALESCE(node.computer_name,'')
        , 'value',node.log_count)::TEXT AS std_group_title
    FROM (
        SELECT node.node_id, node.ip, node.computer_name, node.ip_connected, node.log_count
        FROM (
            SELECT node.node_id, node.ip, node.computer_name, node.ip_connected, COALESCE(SUM(timeline.log_count), 0) AS log_count
            FROM
              tb_node node
              INNER JOIN tb_ac_execution_control_timeline timeline ON node.node_id = timeline.node_id
                AND timeline.action = 'BLOCK'
                AND CONCAT(timeline.yyyy,timeline.mm,timeline.dd) > TO_CHAR(date_trunc('DAYS', NOW() - '6 DAYS'::interval),'YYYYMMDD')
              LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = node.container_service_type
            WHERE
              node.is_removed IS FALSE
              AND ((v_all_target) OR (v_all_target = false AND node.node_id = ANY(v_node_id_array)))
              AND ('AC_AGENT_TOP'::en_widget_item_type = ANY(i_widget_item_type))
              AND ('AC_AGENT_TOP_LAST_7_DAYS'::text = ANY(i_widget_item_sub_type))
              AND v_product_auth_check
              AND (node.machine_type != 'CONTAINER' OR node.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS TRUE)
            GROUP BY
              node.node_id, node.ip, node.computer_name
        ) node
        ORDER BY node.log_count DESC
        LIMIT v_top_limit
    ) node
    UNION ALL
    SELECT
      'AC_AGENT_TOP'::en_widget_item_type AS widget_item_type
      , 'AC_AGENT_TOP_LAST_24_HR'::text AS widget_item_sub_type
      , node.node_id AS node_id
      , node.log_count AS value
      , CONCAT(node.node_id, '|', COALESCE(node.ip,node.ip_connected), '|', node.computer_name) AS std_group_key
      , JSON_BUILD_OBJECT(
        'ip', COALESCE(HOST(node.ip),HOST(node.ip_connected))
        , 'name', COALESCE(node.computer_name,'')
        , 'value',node.log_count)::TEXT AS std_group_title
    FROM (
        SELECT node.node_id, node.ip, node.computer_name, node.ip_connected, node.log_count
        FROM (
            SELECT node.node_id, node.ip, node.computer_name, node.ip_connected, COALESCE(SUM(timeline.log_count), 0) AS log_count
            FROM
              tb_node node
              INNER JOIN tb_ac_execution_control_timeline timeline ON node.node_id = timeline.node_id
                AND timeline.action = 'BLOCK'
                AND CONCAT(timeline.yyyy,timeline.mm,timeline.dd,timeline.hh) > TO_CHAR(date_trunc('HOURS', NOW() - '23 HOURS'::interval),'YYYYMMDDHH24')
              LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = node.container_service_type
            WHERE
              node.is_removed IS FALSE
              AND ((v_all_target) OR (v_all_target = false AND node.node_id = ANY(v_node_id_array)))
              AND ('AC_AGENT_TOP'::en_widget_item_type = ANY(i_widget_item_type))
              AND ('AC_AGENT_TOP_LAST_24_HR'::text = ANY(i_widget_item_sub_type))
              AND v_product_auth_check
              AND (node.machine_type != 'CONTAINER' OR node.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS TRUE)
            GROUP BY
              node.node_id, node.ip, node.computer_name
        ) node
        ORDER BY node.log_count DESC
        LIMIT v_top_limit
    ) node
  /* AC 실행 제어 차단 파일 순위 */
    UNION ALL
    SELECT
      'AC_BLOCK_FILE_TOP'::en_widget_item_type AS widget_item_type
      , 'AC_BLOCK_FILE_TOP_LAST_30_DAYS'::text AS widget_item_sub_type
      , 0 AS node_id
      , timeline.log_count AS value
      , CONCAT(timeline.file_name, '|', timeline.file_hash) AS std_group_key
      , JSON_BUILD_OBJECT(
        'name', COALESCE(timeline.file_name,'')
        , 'hash', COALESCE(timeline.file_hash,'')
        , 'value', timeline.log_count)::text AS std_group_title
    FROM (
        SELECT timeline.file_name, timeline.file_hash, timeline.log_count
        FROM (
            SELECT timeline.file_name, timeline.file_hash, COALESCE(SUM(timeline.log_count), 0) AS log_count
            FROM
              tb_node node
              INNER JOIN tb_ac_execution_control_timeline timeline ON node.node_id = timeline.node_id
                AND timeline.action = 'BLOCK'
                AND CONCAT(timeline.yyyy,timeline.mm,timeline.dd) > TO_CHAR(date_trunc('DAYS', NOW() - '29 DAYS'::interval),'YYYYMMDD')
              LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = node.container_service_type
            WHERE
              node.is_removed IS FALSE
              AND ((v_all_target) OR (v_all_target = false AND node.node_id = ANY(v_node_id_array)))
              AND ('AC_BLOCK_FILE_TOP'::en_widget_item_type = ANY(i_widget_item_type))
              AND ('AC_BLOCK_FILE_TOP_LAST_30_DAYS'::text = ANY(i_widget_item_sub_type))
              AND v_product_auth_check
              AND (node.machine_type != 'CONTAINER' OR node.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS TRUE)
            GROUP BY
              timeline.file_name, timeline.file_hash
            ) timeline
        ORDER BY timeline.log_count DESC
        LIMIT v_top_limit
    ) timeline
    UNION ALL
    SELECT
      'AC_BLOCK_FILE_TOP'::en_widget_item_type AS widget_item_type
      , 'AC_BLOCK_FILE_TOP_LAST_7_DAYS'::text AS widget_item_sub_type
      , 0 AS node_id
      , timeline.log_count AS value
      , CONCAT(timeline.file_name, '|', timeline.file_hash) AS std_group_key
      , JSON_BUILD_OBJECT(
        'name', COALESCE(timeline.file_name,'')
      , 'hash', COALESCE(timeline.file_hash,'')
      , 'value', timeline.log_count)::text AS std_group_title
    FROM (
        SELECT timeline.file_name, timeline.file_hash, timeline.log_count
        FROM (
            SELECT timeline.file_name, timeline.file_hash, COALESCE(SUM(timeline.log_count), 0) AS log_count
            FROM
              tb_node node
              INNER JOIN tb_ac_execution_control_timeline timeline ON node.node_id = timeline.node_id
                AND timeline.action = 'BLOCK'
                AND CONCAT(timeline.yyyy,timeline.mm,timeline.dd) > TO_CHAR(date_trunc('DAYS', NOW() - '6 DAYS'::interval),'YYYYMMDD')
              LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = node.container_service_type
            WHERE
              node.is_removed IS FALSE
              AND ((v_all_target) OR (v_all_target = false AND node.node_id = ANY(v_node_id_array)))
              AND ('AC_BLOCK_FILE_TOP'::en_widget_item_type = ANY(i_widget_item_type))
              AND ('AC_BLOCK_FILE_TOP_LAST_7_DAYS'::text = ANY(i_widget_item_sub_type))
              AND v_product_auth_check
              AND (node.machine_type != 'CONTAINER' OR node.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS TRUE)
            GROUP BY
              timeline.file_name, timeline.file_hash
            ) timeline
        ORDER BY timeline.log_count DESC
        LIMIT v_top_limit
    ) timeline
    UNION ALL
    SELECT
      'AC_BLOCK_FILE_TOP'::en_widget_item_type AS widget_item_type
      , 'AC_BLOCK_FILE_TOP_LAST_24_HR'::text AS widget_item_sub_type
      , 0 AS node_id
      , timeline.log_count AS value
      , CONCAT(timeline.file_name, '|', timeline.file_hash) AS std_group_key
      , JSON_BUILD_OBJECT(
        'name', COALESCE(timeline.file_name,'')
      , 'hash', COALESCE(timeline.file_hash,'')
      , 'value', timeline.log_count)::text AS std_group_title
    FROM (
        SELECT timeline.file_name, timeline.file_hash, timeline.log_count
        FROM (
            SELECT timeline.file_name, timeline.file_hash, COALESCE(SUM(timeline.log_count), 0) AS log_count
            FROM
              tb_node node
              INNER JOIN tb_ac_execution_control_timeline timeline ON node.node_id = timeline.node_id
                AND timeline.action = 'BLOCK'
                AND CONCAT(timeline.yyyy,timeline.mm,timeline.dd,timeline.hh) > TO_CHAR(date_trunc('HOURS', NOW() - '23 HOURS'::interval),'YYYYMMDDHH24')
              LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = node.container_service_type
            WHERE
              node.is_removed IS FALSE
              AND ((v_all_target) OR (v_all_target = false AND node.node_id = ANY(v_node_id_array)))
              AND ('AC_BLOCK_FILE_TOP'::en_widget_item_type = ANY(i_widget_item_type))
              AND ('AC_BLOCK_FILE_TOP_LAST_24_HR'::text = ANY(i_widget_item_sub_type))
              AND v_product_auth_check
              AND (node.machine_type != 'CONTAINER' OR node.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS TRUE)
            GROUP BY
              timeline.file_name, timeline.file_hash
            ) timeline
        ORDER BY timeline.log_count DESC
        LIMIT v_top_limit
    ) timeline

  /* AC 실행 제어 차단 추이 */
    UNION ALL
    SELECT
      'AC_BLOCK_HISTORY'::en_widget_item_type AS widget_item_type
      , 'AC_BLOCK_HISTORY_LAST_30_DAYS'::text AS widget_item_sub_type
      , 0::bigint AS node_id
      , COALESCE(timeline.value, 0)::bigint AS value
      , std_data.reg_date AS std_group_key
      , JSON_BUILD_OBJECT(
        'reg_date', std_data.reg_date
        , 'value', COALESCE(timeline.value,0)
      )::text AS std_group_title
    FROM (
      SELECT
        TO_CHAR(NOW()::timestamp without time zone - (29 - interval_hour || ' DAYS')::INTERVAL, 'YYYYMMDD') AS reg_date
      FROM
        GENERATE_SERIES(0,29) interval_hour
      ) std_data
      LEFT JOIN
      (
        SELECT
          CONCAT(timeline.yyyy, timeline.mm, timeline.dd) AS reg_date
          , SUM(timeline.log_count) AS value
        FROM
          tb_node node
          INNER JOIN tb_ac_execution_control_timeline timeline ON node.node_id = timeline.node_id
            AND timeline.action = 'BLOCK'
            AND CONCAT(timeline.yyyy, timeline.mm, timeline.dd) > TO_CHAR((NOW() - '30 DAY'::INTERVAL),'YYYYMMDD')
          LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = node.container_service_type
        WHERE
          node.is_removed IS FALSE
          AND ((v_all_target) OR (v_all_target = false AND node.node_id = ANY(v_node_id_array)))
          AND (node.machine_type != 'CONTAINER' OR node.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS TRUE)
        GROUP BY
          timeline.yyyy, timeline.mm, timeline.dd
      ) timeline ON std_data.reg_date = timeline.reg_date
    WHERE
      ('AC_BLOCK_HISTORY'::en_widget_item_type = ANY(i_widget_item_type))
      AND ('AC_BLOCK_HISTORY_LAST_30_DAYS'::text = ANY(i_widget_item_sub_type))
      AND v_product_auth_check
    UNION ALL
    SELECT
      'AC_BLOCK_HISTORY'::en_widget_item_type AS widget_item_type
      , 'AC_BLOCK_HISTORY_LAST_7_DAYS'::text AS widget_item_sub_type
      , 0::bigint AS node_id
