      , std_data.reg_date AS std_group_key
      , JSON_BUILD_OBJECT(
        'reg_date', std_data.reg_date
        , 'value', COALESCE(timeline.value,0)
      )::text AS std_group_title
    FROM (
      SELECT
        TO_CHAR(NOW()::timestamp without time zone - (6 - interval_hour || ' DAYS')::INTERVAL, 'YYYYMMDD') AS reg_date
      FROM
        GENERATE_SERIES(0,6) interval_hour
      ) std_data
      LEFT JOIN
      (
        SELECT
          CONCAT(timeline.yyyy, timeline.mm, timeline.dd) AS reg_date
          , SUM(timeline.log_count) AS value
        FROM
          tb_node node
          INNER JOIN tb_ac_execution_control_timeline timeline ON node.node_id = timeline.node_id
            AND timeline.action = 'BLOCK'
            AND CONCAT(timeline.yyyy, timeline.mm, timeline.dd) > TO_CHAR((NOW() - '7 DAY'::INTERVAL),'YYYYMMDD')
          LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = node.container_service_type
        WHERE
          node.is_removed IS FALSE
