      SELECT
        'AC_IM_DETECT_TARGET_TYPE_TOP'::en_widget_item_type AS widget_item_type
        , 'AC_IM_DETECT_TARGET_TYPE_TOP_LAST_30_DAYS'::text AS widget_item_sub_type
        , 0 AS node_id
        , timeline.detect_count AS value
        , timeline.detect_path AS std_group_key
        , JSON_BUILD_OBJECT(
          'path', COALESCE(timeline.detect_path,'')
          , 'value', timeline.detect_count)::text AS std_group_title
      FROM (
        SELECT timeline.detect_path, timeline.detect_count
        FROM (
          SELECT 
            timeline.detect_path, COALESCE(SUM(timeline.detect_count), 0) AS detect_count
          FROM 
            tb_im_detect_target_type_timeline timeline
          INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
          INNER JOIN tb_product_info pi ON n.node_id = pi.node_id AND pi.product_id = 'AC_CLIENT'
          LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = n.container_service_type
          WHERE 
            timeline.reg_date >= to_char(date_trunc('DAYS', now() - '29 DAYS'::interval), 'YYYYMMDD')
          AND timeline.reg_date <= to_char(date_trunc('DAYS', now()), 'YYYYMMDD')
          AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
          AND ('AC_IM_DETECT_TARGET_TYPE_TOP'::en_widget_item_type = ANY(i_widget_item_type))
          AND v_product_auth_check
          AND (n.machine_type != 'CONTAINER' OR n.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS TRUE)
          GROUP BY 
            timeline.detect_path
        ) timeline
        ORDER BY timeline.detect_count DESC
        LIMIT v_top_limit
      ) timeline
      UNION ALL
      SELECT
        'AC_IM_DETECT_TARGET_TYPE_TOP'::en_widget_item_type AS widget_item_type
        , 'AC_IM_DETECT_TARGET_TYPE_TOP_LAST_7_DAYS'::text AS widget_item_sub_type
        , 0 AS node_id
        , timeline.detect_count AS value
        , timeline.detect_path AS std_group_key
        , JSON_BUILD_OBJECT(
          'path', COALESCE(timeline.detect_path,'')
          , 'value', timeline.detect_count)::text AS std_group_title
      FROM (
        SELECT timeline.detect_path, timeline.detect_count
        FROM (
          SELECT 
            timeline.detect_path, COALESCE(SUM(timeline.detect_count), 0) AS detect_count
          FROM 
            tb_im_detect_target_type_timeline timeline
          INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
          INNER JOIN tb_product_info pi ON n.node_id = pi.node_id AND pi.product_id = 'AC_CLIENT'
          LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = n.container_service_type
          WHERE 
            timeline.reg_date >= to_char(date_trunc('DAYS', now() - '6 DAYS'::interval), 'YYYYMMDD')
          AND timeline.reg_date <= to_char(date_trunc('DAYS', now()), 'YYYYMMDD')
          AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
          AND ('AC_IM_DETECT_TARGET_TYPE_TOP'::en_widget_item_type = ANY(i_widget_item_type))
          AND v_product_auth_check
          AND (n.machine_type != 'CONTAINER' OR n.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS TRUE)
          GROUP BY 
            timeline.detect_path
        ) timeline
        ORDER BY timeline.detect_count DESC
        LIMIT v_top_limit
      ) timeline
      UNION ALL
      SELECT
        'AC_IM_DETECT_TARGET_TYPE_TOP'::en_widget_item_type AS widget_item_type
        , 'AC_IM_DETECT_TARGET_TYPE_TOP_LAST_24_HR'::text AS widget_item_sub_type
        , 0 AS node_id
        , timeline.detect_count AS value
        , timeline.detect_path AS std_group_key
        , JSON_BUILD_OBJECT(
          'path', COALESCE(timeline.detect_path,'')
          , 'value', timeline.detect_count)::text AS std_group_title
      FROM (
        SELECT timeline.detect_path, timeline.detect_count
        FROM (
          SELECT 
            timeline.detect_path, COALESCE(SUM(timeline.detect_count), 0) AS detect_count
          FROM 
            tb_im_detect_target_type_timeline timeline
          INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
          INNER JOIN tb_product_info pi ON n.node_id = pi.node_id AND pi.product_id = 'AC_CLIENT'
          LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = n.container_service_type
          WHERE 
            timeline.reg_date >= to_char(date_trunc('DAYS', now() - '23 HOURS'::interval), 'YYYYMMDD')
          AND CONCAT(timeline.reg_date, LPAD(timeline.hour, 2, '0')) >= to_char(date_trunc('HOURS', now() - '23 HOURS'::interval), 'YYYYMMDDHH24')
          AND CONCAT(timeline.reg_date, LPAD(timeline.hour, 2, '0')) <= to_char(date_trunc('HOURS', now()), 'YYYYMMDDHH24')
          AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
          AND ('AC_IM_DETECT_TARGET_TYPE_TOP'::en_widget_item_type = ANY(i_widget_item_type))
          AND v_product_auth_check
          AND (n.machine_type != 'CONTAINER' OR n.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS TRUE)
          GROUP BY 
            timeline.detect_path
        ) timeline
        ORDER BY timeline.detect_count DESC
        LIMIT v_top_limit
      ) timeline

      /* AC IM 탐지 추이 */
      UNION ALL
      SELECT
        'AC_IM_DETECT_HISTORY'::en_widget_item_type AS widget_item_type
        , 'AC_IM_DETECT_HISTORY_LAST_30_DAYS'::text AS widget_item_sub_type
        , 0::bigint AS node_id
        , COALESCE(timeline.value, 0)::bigint AS value
        , std_data.reg_date AS std_group_key
        , JSON_BUILD_OBJECT(
          'reg_date', std_data.reg_date
          , 'value', COALESCE(timeline.value,0)
        )::text AS std_group_title
      FROM (
        SELECT
          TO_CHAR(NOW()::timestamp without time zone - (29 - interval_hour || ' DAYS')::INTERVAL, 'YYYYMMDD') AS reg_date
        FROM
          GENERATE_SERIES(0,29) interval_hour
        ) std_data
        LEFT JOIN
        (
          SELECT
            timeline.reg_date AS reg_date
            , SUM(timeline.detect_count) AS value
          FROM
            tb_node node
            INNER JOIN tb_im_detect_timeline timeline ON node.node_id = timeline.node_id
              AND timeline.reg_date > TO_CHAR((NOW() - '30 DAY'::INTERVAL),'YYYYMMDD')
            LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = node.container_service_type
          WHERE
            node.is_removed IS FALSE
            AND ((v_all_target) OR (v_all_target = false AND node.node_id = ANY(v_node_id_array)))
            AND (node.machine_type != 'CONTAINER' OR node.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS TRUE)
          GROUP BY
            timeline.reg_date
        ) timeline ON std_data.reg_date = timeline.reg_date
      WHERE
        ('AC_IM_DETECT_HISTORY'::en_widget_item_type = ANY(i_widget_item_type))
        AND ('AC_IM_DETECT_HISTORY_LAST_30_DAYS'::text = ANY(i_widget_item_sub_type))
        AND v_product_auth_check
      UNION ALL
      SELECT
        'AC_IM_DETECT_HISTORY'::en_widget_item_type AS widget_item_type
        , 'AC_IM_DETECT_HISTORY_LAST_7_DAYS'::text AS widget_item_sub_type
        , 0::bigint AS node_id
        , COALESCE(timeline.value, 0)::bigint AS value
        , std_data.reg_date AS std_group_key
        , JSON_BUILD_OBJECT(
          'reg_date', std_data.reg_date
          , 'value', COALESCE(timeline.value,0)
        )::text AS std_group_title
      FROM (
        SELECT
          TO_CHAR(NOW()::timestamp without time zone - (6 - interval_hour || ' DAYS')::INTERVAL, 'YYYYMMDD') AS reg_date
        FROM
          GENERATE_SERIES(0,6) interval_hour
        ) std_data
        LEFT JOIN
        (
          SELECT
            timeline.reg_date AS reg_date
            , SUM(timeline.detect_count) AS value
          FROM
            tb_node node
            INNER JOIN tb_im_detect_timeline timeline ON node.node_id = timeline.node_id
              AND timeline.reg_date > TO_CHAR((NOW() - '7 DAY'::INTERVAL),'YYYYMMDD')
            LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = node.container_service_type
          WHERE
            node.is_removed IS FALSE
            AND ((v_all_target) OR (v_all_target = false AND node.node_id = ANY(v_node_id_array)))
            AND (node.machine_type != 'CONTAINER' OR node.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS TRUE)
          GROUP BY
            timeline.reg_date
        ) timeline ON std_data.reg_date = timeline.reg_date
      WHERE
        ('AC_IM_DETECT_HISTORY'::en_widget_item_type = ANY(i_widget_item_type))
        AND ('AC_IM_DETECT_HISTORY_LAST_7_DAYS'::text = ANY(i_widget_item_sub_type))
        AND v_product_auth_check
      UNION ALL
      SELECT
        'AC_IM_DETECT_HISTORY'::en_widget_item_type AS widget_item_type
        , 'AC_IM_DETECT_HISTORY_LAST_24_HR'::text AS widget_item_sub_type
        , 0::bigint AS node_id
        , COALESCE(timeline.value, 0)::bigint AS value
        , std_data.reg_date AS std_group_key
        , JSON_BUILD_OBJECT(
          'reg_date', std_data.reg_date
          , 'value', COALESCE(timeline.value,0)
        )::text AS std_group_title
      FROM (
        SELECT
          TO_CHAR(NOW()::timestamp without time zone - (23 - interval_hour || ' HOUR')::INTERVAL, 'YYYYMMDDHH24') AS reg_date
        FROM
          GENERATE_SERIES(0,23) interval_hour
        ) std_data
        LEFT JOIN
        (
          SELECT
            CONCAT(timeline.reg_date, timeline.hour) AS reg_date
            , SUM(timeline.detect_count) AS value
          FROM
            tb_node node
            INNER JOIN tb_im_detect_timeline timeline ON node.node_id = timeline.node_id
              AND CONCAT(timeline.reg_date, timeline.hour) > TO_CHAR((NOW() - '24 HOUR'::INTERVAL),'YYYYMMDDHH24')
            LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = node.container_service_type
          WHERE
            node.is_removed IS FALSE
            AND ((v_all_target) OR (v_all_target = false AND node.node_id = ANY(v_node_id_array)))
            AND (node.machine_type != 'CONTAINER' OR node.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS TRUE)
          GROUP BY
            timeline.reg_date, timeline.hour
        ) timeline ON std_data.reg_date = timeline.reg_date
      WHERE
        ('AC_IM_DETECT_HISTORY'::en_widget_item_type = ANY(i_widget_item_type))
        AND ('AC_IM_DETECT_HISTORY_LAST_24_HR'::text = ANY(i_widget_item_sub_type))
        AND v_product_auth_check
    ) org
;

END;
$$;


ALTER FUNCTION public.sp_get_custom_dashboard_ac_link_node_list(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_custom_dashboard_ac_link_node_list(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_custom_dashboard_ac_link_node_list(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text) IS '
@brief [] - 제품별 및 커스텀 대시보드 > AC 노드 리스트
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_custom_dashboard_epp(public.en_widget_item_type[], text[], bigint, bigint, public.en_language, text, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_custom_dashboard_epp(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text, i_node_id_arr bigint[]) RETURNS TABLE(link_type text, widget_item_type public.en_widget_item_type, widget_item_sub_type text, response_values text, ord_num bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_link_type text := 'CUSTOM_DASHBOARD';

BEGIN





  RETURN QUERY

  SELECT
   v_link_type
   , wit.widget_item_type
   , wit.widget_item_sub_type

   , (CASE
        WHEN (org.std_group_title IS NULL OR org.std_group_title = '') AND wit.is_show_default_col IS TRUE THEN
          JSON_BUILD_OBJECT(
            'value', COALESCE(org.value, 0)
          )::text
        ELSE
            org.std_group_title
    END) AS response_values

    , ROW_NUMBER() OVER (ORDER BY org.widget_item_type, org.widget_item_sub_type, org.std_group_key, org.value DESC) AS ord_num

  FROM
    (
      SELECT
        wit.widget_item_type
        , wit.widget_item_sub_type
        , wit.product_group
        , (CASE WHEN wit.widget_item_type IN('SERVER_STATUS') THEN FALSE ELSE TRUE END) is_show_default_col
      FROM
        tb_widget_item_type wit
      WHERE
        wit.product_group = 'EMS'
    ) wit
   LEFT JOIN
   (

    /* EPP 설치 현황 */
    SELECT
      org_rate.widget_item_type
      , org_rate.widget_item_sub_type
      , org_rate.value
      , org_rate.std_group_key
      , org_rate.std_group_title
    FROM(
      WITH org_data AS(
      SELECT
        data.widget_item_type
        , data.widget_item_sub_type
        , SUM(data.value)::bigint AS value
        , data.std_group_key
        , data.std_group_key AS std_group_title
      FROM
        sp_get_custom_dashboard_epp_link_node_list('{AGENT_INSTALL}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
      WHERE
        ('AGENT_INSTALL'::en_widget_item_type = ANY(i_widget_item_type))
        AND data.node_id= ANY(i_node_id_arr)

      GROUP BY
        data.widget_item_type
        , data.widget_item_sub_type
        , data.std_group_key
      )
      SELECT
        data.widget_item_type
        , data.widget_item_sub_type
        , data.value
        , data.std_group_key
        , data.std_group_title
      FROM
        org_data data
    ) org_rate


    /* 정책 적용 현황 */
    UNION ALL
    SELECT
        data.widget_item_type
        , data.widget_item_sub_type
        , SUM(data.value)::bigint AS value
        , data.std_group_key
        , data.std_group_key AS std_group_title
      FROM
        sp_get_custom_dashboard_epp_link_node_list('{POLICY_APPLY}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
      WHERE
        ('POLICY_APPLY'::en_widget_item_type = ANY(i_widget_item_type))
        AND data.node_id= ANY(i_node_id_arr)

      GROUP BY
        data.widget_item_type
        , data.widget_item_sub_type
        , data.std_group_key

    /* 서버 현황 */
    UNION ALL
    SELECT
        data.widget_item_type
        , data.widget_item_sub_type
        , data.value AS value
        , data.std_group_key
        , data.std_group_title
      FROM
        sp_get_custom_dashboard_epp_link_node_list('{SERVER_STATUS}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) DATA
      WHERE
        ('SERVER_STATUS'::en_widget_item_type = ANY(i_widget_item_type))


    /* 에이전트 현황 */
    UNION ALL
    SELECT
      data.widget_item_type
      , data.widget_item_sub_type
      , sum(data.value)::bigint AS value
      , data.std_group_key
      , data.std_group_title
    FROM
      sp_get_custom_dashboard_epp_link_node_list('{AGENT_STATUS}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('AGENT_STATUS'::en_widget_item_type = ANY(i_widget_item_type))
      AND data.node_id= ANY(i_node_id_arr)
    GROUP BY
      data.widget_item_type
      , data.widget_item_sub_type
      , data.std_group_key
      , data.std_group_title


  ) org
  ON wit.widget_item_sub_type = org.widget_item_sub_type
  WHERE
    wit.product_group = 'EMS'
    AND wit.widget_item_sub_type = ANY(i_widget_item_sub_type)
  ;


END;
$$;


ALTER FUNCTION public.sp_get_custom_dashboard_epp(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text, i_node_id_arr bigint[]) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_custom_dashboard_epp(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text, i_node_id_arr bigint[]); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_custom_dashboard_epp(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text, i_node_id_arr bigint[]) IS '
@brief [] - 제품별 및 커스텀 대시보드 > EPP 요약
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_custom_dashboard_epp_link_node_list(public.en_widget_item_type[], text[], bigint, bigint, public.en_language, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_custom_dashboard_epp_link_node_list(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text) RETURNS TABLE(widget_item_type public.en_widget_item_type, widget_item_sub_type text, node_id bigint, value bigint, std_group_key text, std_group_title text)
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_product_auth_check boolean;
  v_all_target boolean;
  v_node_id_array bigint[];

BEGIN

  v_product_auth_check := sp_get_product_auth_check(i_product_auth, 'EMS');

  IF (i_group_id IS NULL OR i_group_id < 1) AND (i_correlation_rule_id IS NULL OR i_correlation_rule_id < 1) THEN
    v_all_target := true;
  ELSE
    v_all_target := false;
    v_node_id_array := sp_get_node_list( i_group_id, i_correlation_rule_id, null );
  END IF;


  RETURN QUERY

    /* EPP 설치율 */
    SELECT
      org.widget_item_type
      , org.widget_item_sub_type
      , org.node_id
      , org.value
      , '' AS std_group_key
      , '' AS std_group_title
    FROM(

     WITH possible_install_node_list AS(
        SELECT
          pf.is_server
          , n.node_id
        FROM
          tb_node n
          JOIN tb_platform pf ON n.platform_id = pf.platform_id
        WHERE
          n.is_removed IS false
          AND pf.is_supported IS TRUE
          AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
          AND ('AGENT_INSTALL'::en_widget_item_type = ANY(i_widget_item_type))
          AND v_product_auth_check

      -- epp 설치는 tb_product_info에 적재하지 않기 때문에 node 개수가 곧 epp 설치 개수이다.
      ), installed_server AS (
        SELECT 
          'AGENT_INSTALL'::en_widget_item_type AS widget_item_type
          , 'AGENT_INSTALLED_SERVER'::text AS widget_item_sub_type
          , n.node_id
		  , pf.platform_type
          , 1::bigint AS value
		  , (CASE WHEN pf.platform_type = 'WINDOWS' THEN 'AGENT_INSTALLED_SERVER_WINDOWS'
        		ELSE 'AGENT_INSTALLED_SERVER_LINUX' END)::text AS platform_type_convert 
        FROM
          tb_node n
          JOIN tb_platform pf ON n.platform_id = pf.platform_id
        WHERE n.is_removed IS FALSE
          AND pf.is_server IS TRUE
          AND pf.is_supported IS TRUE
          AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
          AND ('AGENT_INSTALL'::en_widget_item_type = ANY(i_widget_item_type))
          AND v_product_auth_check
      )

      SELECT
        server.widget_item_type
        , server.widget_item_sub_type
        , server.node_id
        , 1::bigint AS value
      FROM
        installed_server server
      WHERE ('AGENT_INSTALLED_SERVER' = ANY(i_widget_item_sub_type))

      UNION ALL
      SELECT
        'AGENT_INSTALL'
        , 'AGENT_NOT_INSTALL_SERVER'
        , t.node_id
        , 1::bigint AS value
      FROM
        possible_install_node_list t
      WHERE
        t.is_server IS TRUE
        AND NOT EXISTS(
          SELECT installed.node_id FROM installed_server installed WHERE t.node_id = installed.node_id
        )
        AND ('AGENT_INSTALL'::en_widget_item_type = ANY(i_widget_item_type))
        AND ('AGENT_NOT_INSTALL_SERVER' = ANY(i_widget_item_sub_type))
        AND v_product_auth_check

      UNION ALL
      SELECT
          server.widget_item_type
        , server.platform_type_convert AS widget_item_sub_type
        , server.node_id
        , 1::bigint AS value
      FROM
        installed_server server
      where server.platform_type_convert = ANY(i_widget_item_sub_type)

    ) org


    /* EPP 정책 적용 현황 */
    UNION ALL
    SELECT
      'POLICY_APPLY'::en_widget_item_type AS widget_item_type
      , org.widget_item_sub_type
      , org.node_id
      , 1 AS value
      , '' AS std_group_key
      , '' AS std_group_title
    FROM(
    WITH policy_base_data AS (
      SELECT
        pfm.product_feature_id
        , ps.policy_status
      from
        tb_product_feature_map pfm
        JOIN tb_product p ON pfm.product_id = p.product_id
        CROSS JOIN UNNEST(enum_range(null::en_policy_status)) AS ps(policy_status)
      WHERE
        p.product_group = 'EMS'

    ), vw_policy_status_data AS(
    SELECT
      ps.node_id
      , pbd.product_feature_id
      , pbd.policy_status
      , 1 AS value
    FROM
      vw_policy_status ps
      JOIN tb_node n ON ps.node_id = n.node_id AND n.is_removed IS FALSE
      JOIN policy_base_data pbd ON ps.product_feature_id = pbd.product_feature_id AND ps.policy_status = pbd.policy_status
    WHERE
      ((v_all_target) OR (v_all_target = false AND ps.node_id = ANY(v_node_id_array)))
      AND v_product_auth_check
    )
    SELECT
      (pbd.product_feature_id || '_' || pbd.policy_status )::text AS widget_item_sub_type
      , n.node_id
    FROM
      tb_node n
      CROSS JOIN policy_base_data pbd
      WHERE n.is_removed IS FALSE
      AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
      AND v_product_auth_check
      AND pbd.policy_status = 'APPLYING'
      AND NOT EXISTS(
        SELECT * FROM vw_policy_status_data psd WHERE n.node_id = psd.node_id AND pbd.product_feature_id = psd.product_feature_id
      )
    UNION ALL
    SELECT
      (psd.product_feature_id || '_' || psd.policy_status )::text AS widget_item_sub_type
      , psd.node_id
    FROM
      vw_policy_status_data psd
    ) org
    WHERE
        ('POLICY_APPLY'::en_widget_item_type = ANY(i_widget_item_type))
        AND (org.widget_item_sub_type = ANY(i_widget_item_sub_type))
        AND v_product_auth_check


    /* 서버 현황 */
    UNION ALL
    SELECT
        'SERVER_STATUS'::en_widget_item_type AS widget_item_type
        , 'SERVER_STATUS_RESOURCE'::text AS widget_item_sub_type
        , s.server_id AS node_id
        , 1 AS value
        , s.server_id::text AS std_group_key
        , (JSON_BUILD_OBJECT(
          'server_id' , s.server_id
          , 'server_ip' , s.ip
          , 'server_name' , s.name
          , 'server_status' , s.server_status
          , 'used_cpu' , sr.used_cpu
          , 'avail_cpu' , sr.avail_cpu
          , 'used_mem' , sr.used_mem
          , 'avail_mem' , sr.avail_mem
          , 'used_hdd' , sr.used_hdd
          , 'avail_hdd' , sr.avail_hdd
          , 'db_size' , (sr.oltp_db_size + sr.log_db_size)
          , 'used_traffic' , sr.used_traffic
       )::text) AS std_group_title

    FROM
      tb_server_resource AS sr
      JOIN tb_server s ON sr.server_id = s.server_id
    WHERE
      ('SERVER_STATUS'::en_widget_item_type = ANY(i_widget_item_type))
      AND ('SERVER_STATUS_RESOURCE' = ANY(i_widget_item_sub_type))
      AND (sr.log_time, sr.server_id) IN(SELECT max(msr.log_time), msr.server_id FROM tb_server_resource AS msr group by msr.server_id)
      AND v_product_auth_check


    /* 에이전트 현황 */
    /* 연결됨 */
    UNION ALL
    SELECT
        'AGENT_STATUS'::en_widget_item_type AS widget_item_type
        , 'AGENT_STATUS_CONNECTED'::text AS widget_item_sub_type
        , n.node_id
        , 1 AS value
        , '' AS std_group_key
        , '' AS std_group_title
    FROM
      tb_node_status ns
      JOIN tb_node n ON ns.node_id = n.node_id
    WHERE
      n.is_removed IS FALSE
      AND ((v_all_target) OR (v_all_target = false AND ns.node_id = ANY(v_node_id_array)))
      AND ('AGENT_STATUS'::en_widget_item_type = ANY(i_widget_item_type))
      AND ('AGENT_STATUS_CONNECTED' = ANY(i_widget_item_sub_type))
      AND ns.connection_status = 'CONNECTED'
      AND v_product_auth_check

    /* 연결 안 됨 */
    UNION ALL
    SELECT
        'AGENT_STATUS'::en_widget_item_type AS widget_item_type
        , 'AGENT_STATUS_DISCONNECTED'::text AS widget_item_sub_type
        , n.node_id
        , 1 AS value
        , '' AS std_group_key
        , '' AS std_group_title
    FROM
      tb_node_status ns
      JOIN tb_node n ON ns.node_id = n.node_id
    WHERE
      n.is_removed IS FALSE
      AND ((v_all_target) OR (v_all_target = false AND ns.node_id = ANY(v_node_id_array)))
      AND ('AGENT_STATUS'::en_widget_item_type = ANY(i_widget_item_type))
      AND ('AGENT_STATUS_DISCONNECTED'= ANY(i_widget_item_sub_type))
      AND ns.connection_status = 'DISCONNECTED'
      AND v_product_auth_check
      
    /* 미설치 */
    UNION ALL
    SELECT
        'AGENT_STATUS'::en_widget_item_type AS widget_item_type
        , 'AGENT_STATUS_NOT_INSTALL'::text AS widget_item_sub_type
        , n.node_id
        , 1 AS value
        , '' AS std_group_key
        , '' AS std_group_title
    FROM
      tb_node_status ns
      JOIN tb_node n ON ns.node_id = n.node_id
    WHERE
      n.is_removed IS FALSE
      AND ((v_all_target) OR (v_all_target = false AND ns.node_id = ANY(v_node_id_array)))
      AND ('AGENT_STATUS'::en_widget_item_type = ANY(i_widget_item_type))
      AND ('AGENT_STATUS_NOT_INSTALL'= ANY(i_widget_item_sub_type))
      AND ns.connection_status = 'UNINSTALLED'
      AND v_product_auth_check
  ;

END;
$$;


ALTER FUNCTION public.sp_get_custom_dashboard_epp_link_node_list(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_custom_dashboard_epp_link_node_list(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_custom_dashboard_epp_link_node_list(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text) IS '
@brief [] - 제품별 및 커스텀 대시보드 > APM 노드 리스트
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_custom_dashboard_hips(public.en_widget_item_type[], text[], bigint, bigint, public.en_language, text, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_custom_dashboard_hips(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text, i_node_id_arr bigint[]) RETURNS TABLE(link_type text, widget_item_type public.en_widget_item_type, widget_item_sub_type text, response_values text, ord_num bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE

    v_link_type text := 'CUSTOM_DASHBOARD';

BEGIN

  RETURN QUERY

  SELECT
   v_link_type AS link_type
   , wit.widget_item_type
   , wit.widget_item_sub_type

   , (CASE
        WHEN (org.std_group_title IS NULL OR org.std_group_title = '') AND wit.is_show_default_col IS TRUE THEN
          JSON_BUILD_OBJECT(
            'value', COALESCE(org.value, 0)
          )::text
        ELSE
            org.std_group_title
    END) AS response_values

    , ROW_NUMBER() OVER (ORDER BY org.widget_item_type, org.widget_item_sub_type, org.std_group_key, org.value DESC) AS ord_num

  FROM
    (
      SELECT
        wit.widget_item_type
        , wit.widget_item_sub_type
        , wit.product_group
        , (CASE WHEN wit.widget_item_type
        IN('HIPS_SIP_TOP', 'HIPS_DETECT_AGENT_TOP', 'HIPS_ATTACK_TOP', 'HIPS_APPLICATION_TOP', 'HIPS_COUNTRY_TOP', 'HIPS_DETECT_LIST', 'HIPS_DETECT_HISTORY', 'HIPS_SEVERITY_STATUS', 'HIPS_FW_SIP_TOP', 'HIPS_FW_AGENT_TOP', 'HIPS_FW_HISTORY', 'HIPS_FW_PORT_TOP', 'HIPS_FW_RULE_TOP') THEN FALSE ELSE TRUE END) is_show_default_col
      FROM
        tb_widget_item_type wit
      WHERE
        wit.product_group = 'HIPS'
    ) wit
    LEFT JOIN
    (


    /* HIPS 설치 현황 */
    SELECT
      org_rate.widget_item_type
      , org_rate.widget_item_sub_type
      , org_rate.value
      , org_rate.std_group_key
      , org_rate.std_group_title
    FROM(
      WITH org_data AS(
      SELECT
        data.widget_item_type
        , data.widget_item_sub_type
        , SUM(data.value)::bigint AS value
        , data.std_group_key
        , data.std_group_key AS std_group_title
      FROM
        sp_get_custom_dashboard_hips_link_node_list('{HIPS_INSTALL}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
      WHERE
        ('HIPS_INSTALL' = ANY(i_widget_item_type))
        AND data.node_id= ANY(i_node_id_arr)

      GROUP BY
        data.widget_item_type
        , data.widget_item_sub_type
        , data.std_group_key
      )
      SELECT
        data.widget_item_type
        , data.widget_item_sub_type
        , data.value
        , data.std_group_key
        , data.std_group_title
      FROM
        org_data data
    ) org_rate

    /* HIPS 정책 */
    UNION ALL
    SELECT
          data.widget_item_type
        , data.widget_item_sub_type
        , SUM(data.value) AS value
        , data.std_group_key
        , data.std_group_key AS std_group_title
      FROM
        sp_get_custom_dashboard_hips_link_node_list('{HIPS_POLICY_STATUS}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
      WHERE
        ('HIPS_POLICY_STATUS' = ANY(i_widget_item_type))
        AND data.node_id= ANY(i_node_id_arr)
      GROUP BY
        data.widget_item_type, data.widget_item_sub_type, data.std_group_key


    /* HIPS IPS 상태 */
    UNION ALL
    SELECT
          data.widget_item_type
        , data.widget_item_sub_type
        , SUM(data.value) AS value
        , data.std_group_key
        , data.std_group_key AS std_group_title
      FROM
        sp_get_custom_dashboard_hips_link_node_list('{HIPS_IPS_STATUS}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
      WHERE
        ('HIPS_IPS_STATUS' = ANY(i_widget_item_type))
        AND data.node_id= ANY(i_node_id_arr)
      GROUP BY
        data.widget_item_type, data.widget_item_sub_type, data.std_group_key

    /* HIPS 공격자 탐지 Top */
    UNION ALL
    SELECT
       data.widget_item_type
     , data.widget_item_sub_type
     , data.value
     , data.std_group_key
     , data.std_group_title
    FROM
      sp_get_custom_dashboard_hips_link_node_list('{HIPS_SIP_TOP}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('HIPS_SIP_TOP' = ANY(i_widget_item_type))

    /* HIPS 탐지 에이전트 Top */
    UNION ALL
    SELECT
       data.widget_item_type
     , data.widget_item_sub_type
     , data.value
     , data.std_group_key
     , data.std_group_title
    FROM
      sp_get_custom_dashboard_hips_link_node_list('{HIPS_DETECT_AGENT_TOP}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('HIPS_DETECT_AGENT_TOP' = ANY(i_widget_item_type))


    /* HIPS 시그니처 공격명 Top */
    UNION ALL
    SELECT
       data.widget_item_type
     , data.widget_item_sub_type
     , data.value
     , data.std_group_key
     , data.std_group_title
    FROM
      sp_get_custom_dashboard_hips_link_node_list('{HIPS_ATTACK_TOP}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('HIPS_ATTACK_TOP' = ANY(i_widget_item_type))

    /* HIPS 시그니처 탐지 추이 */
    UNION ALL
    SELECT
       data.widget_item_type
     , data.widget_item_sub_type
     , data.value
     , data.std_group_key
     , data.std_group_title
    FROM
      sp_get_custom_dashboard_hips_link_node_list('{HIPS_DETECT_HISTORY}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('HIPS_DETECT_HISTORY' = ANY(i_widget_item_type))

    /* HIPS Application Type 탐지 Top */
    UNION ALL
    SELECT
       data.widget_item_type
     , data.widget_item_sub_type
     , data.value
     , data.std_group_key
     , data.std_group_title
    FROM
      sp_get_custom_dashboard_hips_link_node_list('{HIPS_APPLICATION_TOP}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('HIPS_APPLICATION_TOP' = ANY(i_widget_item_type))

    /* HIPS 공격 국가 Top */
    UNION ALL
    SELECT
       data.widget_item_type
     , data.widget_item_sub_type
     , data.value
     , data.std_group_key
     , data.std_group_title
    FROM
      sp_get_custom_dashboard_hips_link_node_list('{HIPS_COUNTRY_TOP}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('HIPS_COUNTRY_TOP' = ANY(i_widget_item_type))

    /* HIPS 위험도별 현황 */
    UNION ALL
    SELECT
       data.widget_item_type
     , data.widget_item_sub_type
     , data.value
     , data.std_group_key
     , data.std_group_title
    FROM
      sp_get_custom_dashboard_hips_link_node_list('{HIPS_SEVERITY_STATUS}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('HIPS_SEVERITY_STATUS' = ANY(i_widget_item_type))

    /* 최근 HIPS 차단/탐지 현황 */
    UNION ALL
    SELECT
       data.widget_item_type
     , data.widget_item_sub_type
     , data.value
     , data.std_group_key
     , data.std_group_title
    FROM
      sp_get_custom_dashboard_hips_link_node_list('{HIPS_DETECT_LIST}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('HIPS_DETECT_LIST' = ANY(i_widget_item_type))

    /* HIPS FW 상태 */
    UNION ALL
    SELECT
          data.widget_item_type
        , data.widget_item_sub_type
        , SUM(data.value) AS value
        , data.std_group_key
        , data.std_group_key AS std_group_title
      FROM
        sp_get_custom_dashboard_hips_link_node_list('{HIPS_FW_STATUS}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
      WHERE
        ('HIPS_FW_STATUS' = ANY(i_widget_item_type))
        AND data.node_id= ANY(i_node_id_arr)
      GROUP BY
        data.widget_item_type, data.widget_item_sub_type, data.std_group_key

    /* HIPS FW(방화벽) 차단 IP 순위 */
    UNION ALL
    SELECT
       data.widget_item_type
     , data.widget_item_sub_type
     , data.value
     , data.std_group_key
     , data.std_group_title
    FROM
      sp_get_custom_dashboard_hips_link_node_list('{HIPS_FW_SIP_TOP}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('HIPS_FW_SIP_TOP' = ANY(i_widget_item_type))

    /* HIPS FW(방화벽) 차단 에이전트 Top */
    UNION ALL
    SELECT
       data.widget_item_type
     , data.widget_item_sub_type
     , data.value
     , data.std_group_key
     , data.std_group_title
    FROM
      sp_get_custom_dashboard_hips_link_node_list('{HIPS_FW_AGENT_TOP}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('HIPS_FW_AGENT_TOP' = ANY(i_widget_item_type))

    /* HIPS FW(방화벽) 차단 추이 */
    UNION ALL
    SELECT
       data.widget_item_type
     , data.widget_item_sub_type
     , data.value
     , data.std_group_key
     , data.std_group_title
    FROM
      sp_get_custom_dashboard_hips_link_node_list('{HIPS_FW_HISTORY}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('HIPS_FW_HISTORY' = ANY(i_widget_item_type))

      /* HIPS FW(방화벽) 차단 포트 순위 */
      UNION ALL
    SELECT
       data.widget_item_type
     , data.widget_item_sub_type
     , data.value
     , data.std_group_key
     , data.std_group_title
    FROM
      sp_get_custom_dashboard_hips_link_node_list('{HIPS_FW_PORT_TOP}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('HIPS_FW_PORT_TOP' = ANY(i_widget_item_type))

    /* HIPS FW(방화벽) 차단 규칙 순위 */
    UNION ALL
    SELECT
       data.widget_item_type
     , data.widget_item_sub_type
     , data.value
     , data.std_group_key
     , data.std_group_title
    FROM
      sp_get_custom_dashboard_hips_link_node_list('{HIPS_FW_RULE_TOP}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('HIPS_FW_RULE_TOP' = ANY(i_widget_item_type))

  ) org
  ON wit.widget_item_sub_type = org.widget_item_sub_type
  WHERE
    wit.product_group = 'HIPS'
    AND wit.widget_item_sub_type = ANY(i_widget_item_sub_type)
  ;


END;
$$;


ALTER FUNCTION public.sp_get_custom_dashboard_hips(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text, i_node_id_arr bigint[]) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_custom_dashboard_hips(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text, i_node_id_arr bigint[]); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_custom_dashboard_hips(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text, i_node_id_arr bigint[]) IS '
@brief [] - 제품별 및 커스텀 대시보드 > HIPS 요약
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_custom_dashboard_hips_link_node_list(public.en_widget_item_type[], text[], bigint, bigint, public.en_language, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_custom_dashboard_hips_link_node_list(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text) RETURNS TABLE(widget_item_type public.en_widget_item_type, widget_item_sub_type text, node_id bigint, value bigint, std_group_key text, std_group_title text)
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_product_auth_check boolean;
  v_all_target boolean;
  v_node_id_array bigint[];

  v_top_limit integer := 10;
  v_now timestamp := NOW();

BEGIN

  v_product_auth_check := sp_get_product_auth_check(i_product_auth, 'HIPS');

  IF (i_group_id IS NULL OR i_group_id < 1) AND (i_correlation_rule_id IS NULL OR i_correlation_rule_id < 1) THEN
    v_all_target := true;
  ELSE
    v_all_target := false;
    v_node_id_array := sp_get_node_list( i_group_id, i_correlation_rule_id, null );
  END IF;


  RETURN QUERY

    /* HIPS 설치율 */
    SELECT
      org.widget_item_type
      , org.widget_item_sub_type
      , org.node_id
      , org.value
      , '' AS std_group_key
      , '' AS std_group_title
    FROM(
      WITH possible_install_node_list AS(
        SELECT
          pf.is_server
          , n.node_id
        FROM
          tb_node n
          JOIN tb_platform pf ON n.platform_id = pf.platform_id
        WHERE n.is_removed IS false
          AND pf.is_supported IS TRUE
          AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
          AND ('HIPS_INSTALL' = ANY(i_widget_item_type))
          AND v_product_auth_check
      ), installed_server_on AS (
        SELECT
          'HIPS_INSTALL'::en_widget_item_type AS widget_item_type
          , 'HIPS_INSTALLED_SERVER_ON'::text AS widget_item_sub_type
          , n.node_id
          , 1 AS value
        FROM
          tb_node n
          JOIN tb_product_info pi ON n.node_id = pi.node_id
          JOIN tb_product p ON pi.product_id = p.product_id
          JOIN tb_platform pf ON n.platform_id = pf.platform_id
          JOIN tb_hips_status hips ON n.node_id = hips.node_id AND hips.service_status = 'ON'
        WHERE n.is_removed IS FALSE
          AND p.product_group = 'HIPS'
          AND pf.is_supported IS TRUE
          AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
          AND ('HIPS_INSTALL' = ANY(i_widget_item_type))
          AND ('HIPS_INSTALLED_SERVER_ON' = ANY(i_widget_item_sub_type))
          AND v_product_auth_check
      ), installed_server_off AS (
        SELECT
          'HIPS_INSTALL'::en_widget_item_type AS widget_item_type
          , 'HIPS_INSTALLED_SERVER_OFF'::text AS widget_item_sub_type
          , n.node_id
          , 1 AS value
        FROM
          tb_node n
          JOIN tb_product_info pi ON n.node_id = pi.node_id
          JOIN tb_product p ON pi.product_id = p.product_id
          JOIN tb_platform pf ON n.platform_id = pf.platform_id
          JOIN tb_hips_status hips ON n.node_id = hips.node_id AND hips.service_status = 'OFF'
        WHERE n.is_removed IS FALSE
          AND p.product_group = 'HIPS'
          AND pf.is_supported IS TRUE
          AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
          AND ('HIPS_INSTALL' = ANY(i_widget_item_type))
          AND ('HIPS_INSTALLED_SERVER_OFF' = ANY(i_widget_item_sub_type))
          AND v_product_auth_check
      )

      SELECT
        installed_on.widget_item_type
        , installed_on.widget_item_sub_type
        , installed_on.node_id
        , 1 AS value
      FROM
        installed_server_on installed_on

      UNION ALL
      SELECT
        installed_off.widget_item_type
        , installed_off.widget_item_sub_type
        , installed_off.node_id
        , 1 AS value
      FROM
        installed_server_off installed_off

      UNION ALL
         SELECT
          'HIPS_INSTALL'::en_widget_item_type AS widget_item_type
          , 'HIPS_NOT_INSTALL_SERVER'::text AS widget_item_sub_type
          , n.node_id
          , 1::bigint AS value
         FROM
          tb_node n
          LEFT JOIN tb_product_info pi ON n.node_id = pi.node_id AND pi.product_id = 'HIPS_CLIENT'
          LEFT JOIN tb_platform pf ON n.platform_id = pf.platform_id
          LEFT JOIN tb_hips_status hips_status ON hips_status.node_id = n.node_id
          WHERE
           n.is_removed IS FALSE
          AND (pi.product_id IS NULL OR hips_status.service_status IS NULL)
          AND pf.is_supported IS TRUE
          AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
          AND ('HIPS_INSTALL' = ANY(i_widget_item_type))
          AND ('HIPS_NOT_INSTALL_SERVER' = ANY(i_widget_item_sub_type))
          AND v_product_auth_check
     ) org



    /* HIPS 정책 */
    UNION ALL
      SELECT org.widget_item_type
            ,org.widget_item_sub_type
            ,org.node_id
            ,org.value
            ,org.std_group_key
            ,org.std_group_title
      FROM (
          SELECT
                'HIPS_POLICY_STATUS'::en_widget_item_type AS widget_item_type
                , CASE
                    WHEN ps.policy_status IS NULL THEN CONCAT(pfm.product_feature_id, '_APPLYING')
                    ELSE CONCAT(pfm.product_feature_id, '_',  ps.policy_status)
                   END AS widget_item_sub_type
                , n.node_id
                , 1 AS value
                , '' AS std_group_key
                , '' AS std_group_title
          FROM tb_node n
          JOIN tb_product_info pi on n.node_id = pi.node_id
          JOIN tb_product p ON pi.product_id = p.product_id
          JOIN tb_product_feature_map pfm on pfm.product_id = pi.product_id
          JOIN tb_platform platform ON n.platform_id = platform.platform_id
        JOIN tb_hips_status hs ON hs.node_id = n.node_id
          LEFT JOIN tb_policy_status ps  on n.node_id = ps.node_id and ps.product_feature_id = pfm.product_feature_id
          WHERE n.is_removed IS FALSE
          AND p.product_group = 'HIPS'
          AND platform.is_supported IS TRUE
              AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
            AND ('HIPS_POLICY_STATUS'::en_widget_item_type = ANY(i_widget_item_type))
              AND v_product_auth_check
      ) org
      WHERE org.widget_item_sub_type = ANY(i_widget_item_sub_type)


   /* HIPS IPS 상태 */
    UNION ALL
    SELECT org.widget_item_type
          ,org.widget_item_sub_type
          ,org.node_id
          ,org.value
          ,org.std_group_key
          ,org.std_group_title
    FROM (
        SELECT 'HIPS_IPS_STATUS'::en_widget_item_type AS widget_item_type
                    , CONCAT('HIPS_IPS_STATUS_', CASE WHEN hs.engine_state = 'OFF' THEN 'ENGINE_OFF' ELSE hs.ips_status::TEXT END)::TEXT AS widget_item_sub_type -- engine_state가 OFF인 경우에는 ENGINE_OFF로 처리(CWPP-4001)
                    , n.node_id as node_id
                    ,1 AS value
                    , '' AS std_group_key
                    , '' AS std_group_title
        FROM tb_node n
        JOIN tb_product_info pi ON n.node_id = pi.node_id
        JOIN tb_product p ON pi.product_id = p.product_id
        JOIN tb_platform platform ON n.platform_id = platform.platform_id
        JOIN tb_hips_status hs on n.node_id = hs.node_id
        WHERE n.is_removed IS FALSE
          AND p.product_group = 'HIPS'
          AND platform.is_supported IS TRUE
            AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
            AND ('HIPS_IPS_STATUS'::en_widget_item_type = ANY(i_widget_item_type))
            AND v_product_auth_check
    ) org
    WHERE org.widget_item_sub_type = ANY(i_widget_item_sub_type)


   /* HIPS 최근 30일, 최근 7일, 최근 24시간 */
    UNION ALL
    SELECT   org.widget_item_type
            ,org.widget_item_sub_type
            ,org.node_id
            ,org.value
