    FROM    (
        WITH vw_common_30days AS (
             SELECT to_char(interval_val, 'YYYYMMDD')::int4 AS interval_val
             FROM generate_series(date_trunc('DAYS', v_now - '29 DAYS'::interval), date_trunc('DAYS', v_now),'1 DAYS'::interval) interval_val
        ), vw_common_07days AS (
             SELECT to_char(interval_val, 'YYYYMMDD')::int4 AS interval_val
