        ), vw_common_24hours AS (
             SELECT to_char(interval_val, 'YYYYMMDDHH24')::int4 AS interval_val
             FROM  generate_series(date_trunc('HOURS', v_now - '23 HOURS'::interval), date_trunc('HOURS', v_now),'1 HOURS'::interval) interval_val
        )
        /* HIPS 공격자 탐지 Top-최근30일  */
        SELECT   'HIPS_SIP_TOP'::en_widget_item_type AS widget_item_type
