                ,timeline.saddr::text AS std_group_key
                ,JSON_BUILD_OBJECT(
                     'saddr', timeline.saddr
                    ,'saddr_count', timeline.saddr_count
                )::text AS std_group_title
        FROM (
            SELECT timeline.saddr, timeline.saddr_count
            FROM (
                SELECT timeline.saddr, SUM(saddr_count) AS saddr_count
                FROM vw_common_30days
                INNER JOIN tb_hips_detect_attacker_daily_timeline timeline ON vw_common_30days.interval_val = timeline.reg_date
                INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
                INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
                INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'
                WHERE ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
                AND ('HIPS_SIP_TOP'::en_widget_item_type = ANY(i_widget_item_type))
                AND v_product_auth_check
                GROUP BY timeline.saddr
            ) timeline
            ORDER BY timeline.saddr_count DESC
            LIMIT v_top_limit
        ) timeline
        UNION ALL
        /* HIPS 공격자 탐지 Top-최근7일  */
