        UNION ALL
        /* HIPS 공격 국가 Top-최근7일 */
        SELECT   'HIPS_COUNTRY_TOP'::en_widget_item_type AS widget_item_type
                ,'HIPS_COUNTRY_TOP_LAST_7_DAYS' AS widget_item_sub_type
                ,0 AS node_id
                ,0 AS value
                ,timeline.scountry::text AS std_group_key
                ,JSON_BUILD_OBJECT(
                     'scountry', timeline.scountry
                    ,'scountry_count', timeline.scountry_count
                )::text AS std_group_title
        FROM (
            SELECT timeline.scountry, timeline.scountry_count
            FROM (
                SELECT timeline.scountry, SUM(timeline.scountry_count) AS scountry_count
                FROM vw_common_07days
                INNER JOIN tb_hips_detect_attack_nation_daily_timeline timeline ON vw_common_07days.interval_val = timeline.reg_date
                INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
                INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
                INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'
                WHERE ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
                AND ('HIPS_COUNTRY_TOP'::en_widget_item_type = ANY(i_widget_item_type))
                AND v_product_auth_check
                GROUP BY timeline.scountry
            ) timeline
            ORDER BY timeline.scountry_count DESC
            LIMIT v_top_limit
        ) timeline
        UNION ALL
        /* HIPS 공격 국가 Top-최근24시간 */
        SELECT   'HIPS_COUNTRY_TOP'::en_widget_item_type AS widget_item_type
                ,'HIPS_COUNTRY_TOP_LAST_24_HR' AS widget_item_sub_type
                ,0 AS node_id
                ,0 AS value
                ,timeline.scountry::text AS std_group_key
                ,JSON_BUILD_OBJECT(
                     'scountry', timeline.scountry
                    ,'scountry_count', timeline.scountry_count
                )::text AS std_group_title
        FROM (
            SELECT timeline.scountry, timeline.scountry_count
            FROM (
                SELECT timeline.scountry, SUM(timeline.scountry_count) AS scountry_count
                FROM vw_common_24hours
                INNER JOIN tb_hips_detect_attack_nation_hourly_timeline timeline ON vw_common_24hours.interval_val = timeline.reg_date
                INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
                INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
                INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'
                WHERE ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
                AND ('HIPS_COUNTRY_TOP'::en_widget_item_type = ANY(i_widget_item_type))
                AND v_product_auth_check
                GROUP BY timeline.scountry
            ) timeline
            ORDER BY timeline.scountry_count DESC
            LIMIT v_top_limit
        ) timeline

        /* HIPS 시그니처 탐지 추이-최근30일 */
        UNION ALL
        SELECT
            'HIPS_DETECT_HISTORY'::en_widget_item_type AS widget_item_type
            ,'HIPS_DETECT_HISTORY_LAST_30_DAYS' AS widget_item_sub_type
            ,0 AS node_id
            ,0 AS value
            , main.reg_date::text AS std_group_key

            ,JSON_BUILD_OBJECT(
                 'reg_date', main.reg_date,
                 'count', main.sum_count

            )::text AS std_group_title

        FROM (
            SELECT criteria.reg_date::text AS reg_date, coalesce(target.sum_count, 0) as sum_count

            FROM (
                SELECT interval_val as reg_date
                FROM vw_common_30days

            ) as criteria

            LEFT JOIN (
                SELECT timeline.reg_date, sum(timeline.detect_count + timeline.block_count) as sum_count
                FROM tb_hips_detect_daily_timeline timeline

                INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
                INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
                INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'

                WHERE ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
                AND timeline.reg_date IN (SELECT interval_val FROM vw_common_30days)

                GROUP BY reg_date

            ) as target

            ON (criteria.reg_date = target.reg_date)

        ) as main

        WHERE ('HIPS_DETECT_HISTORY'::en_widget_item_type = ANY(i_widget_item_type))
            AND v_product_auth_check

        /* HIPS 시그니처 탐지 추이-최근7일 */
        UNION ALL
        SELECT
            'HIPS_DETECT_HISTORY'::en_widget_item_type AS widget_item_type
            ,'HIPS_DETECT_HISTORY_LAST_7_DAYS' AS widget_item_sub_type
            ,0 AS node_id
            ,0 AS value
            , main.reg_date::text AS std_group_key

            ,JSON_BUILD_OBJECT(
                 'reg_date', main.reg_date,
                 'count', main.sum_count

            )::text AS std_group_title

        FROM (
            SELECT criteria.reg_date::text AS reg_date, coalesce(target.sum_count, 0) as sum_count

            FROM (
                SELECT interval_val as reg_date
                FROM vw_common_07days

            ) as criteria

            LEFT JOIN (
                SELECT timeline.reg_date, sum(timeline.detect_count + timeline.block_count) as sum_count
                FROM tb_hips_detect_daily_timeline timeline

                INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
                INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
                INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'

                WHERE ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
                AND timeline.reg_date IN (SELECT interval_val FROM vw_common_07days)

                GROUP BY reg_date

            ) as target

            ON (criteria.reg_date = target.reg_date)

        ) as main

        WHERE ('HIPS_DETECT_HISTORY'::en_widget_item_type = ANY(i_widget_item_type))
            AND v_product_auth_check

        /* HIPS 시그니처 탐지 추이-최근24시간 */
        UNION ALL
        SELECT
            'HIPS_DETECT_HISTORY'::en_widget_item_type AS widget_item_type
            ,'HIPS_DETECT_HISTORY_LAST_24_HR' AS widget_item_sub_type
            ,0 AS node_id
            ,0 AS value
            , main.reg_date::text AS std_group_key

            ,JSON_BUILD_OBJECT(
                 'reg_date', main.reg_date,
                 'count', main.sum_count

            )::text AS std_group_title

        FROM (
            SELECT criteria.reg_date::text AS reg_date, coalesce(target.sum_count, 0) as sum_count

            FROM (
                SELECT interval_val as reg_date
                FROM vw_common_24hours

            ) as criteria

            LEFT JOIN (
                SELECT timeline.reg_date, sum(timeline.detect_count + timeline.block_count) as sum_count
                FROM tb_hips_detect_hourly_timeline timeline

                INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
                INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
                INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'

                WHERE ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
                AND timeline.reg_date IN (SELECT interval_val FROM vw_common_24hours)

                GROUP BY reg_date

            ) as target

            ON (criteria.reg_date = target.reg_date)

        ) as main

        WHERE ('HIPS_DETECT_HISTORY'::en_widget_item_type = ANY(i_widget_item_type))
            AND v_product_auth_check

        /* HIPS 위험도별 현황-최근30일 */
        UNION ALL
        SELECT
            'HIPS_SEVERITY_STATUS'::en_widget_item_type AS widget_item_type
            ,'HIPS_SEVERITY_STATUS_LAST_30_DAYS' AS widget_item_sub_type
            ,0 AS node_id
            ,0 AS value
            , '' AS std_group_key

            ,JSON_BUILD_OBJECT(
                 'critical', main.critical,
                 'high', main.high,
                 'medium', main.medium,
                 'low', main.low,
                 'info', main.info

            )::text AS std_group_title

        FROM (
            SELECT COALESCE(SUM(timeline.critical_count), 0) as critical,
                   COALESCE(SUM(timeline.high_count), 0) as high,
                   COALESCE(SUM(timeline.medium_count), 0) as medium,
                   COALESCE(SUM(timeline.low_count), 0) as low,
                   COALESCE(SUM(timeline.information_count), 0) as info

            FROM tb_hips_detect_daily_timeline timeline

            INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
            INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
            INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'

            WHERE ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
            AND timeline.reg_date IN (SELECT interval_val FROM vw_common_30days)

        ) as main

        WHERE ('HIPS_SEVERITY_STATUS'::en_widget_item_type = ANY(i_widget_item_type))
            AND v_product_auth_check

        /* HIPS 위험도별 현황-최근7일 */
        UNION ALL
        SELECT
            'HIPS_SEVERITY_STATUS'::en_widget_item_type AS widget_item_type
            ,'HIPS_SEVERITY_STATUS_LAST_7_DAYS' AS widget_item_sub_type
            ,0 AS node_id
            ,0 AS value
            , '' AS std_group_key

            ,JSON_BUILD_OBJECT(
                 'critical', main.critical,
                 'high', main.high,
                 'medium', main.medium,
                 'low', main.low,
                 'info', main.info

            )::text AS std_group_title

        FROM (
            SELECT COALESCE(SUM(timeline.critical_count), 0) as critical,
                   COALESCE(SUM(timeline.high_count), 0) as high,
                   COALESCE(SUM(timeline.medium_count), 0) as medium,
                   COALESCE(SUM(timeline.low_count), 0) as low,
                   COALESCE(SUM(timeline.information_count), 0) as info

            FROM tb_hips_detect_daily_timeline timeline

            INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
            INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
            INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'

            WHERE ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
            AND timeline.reg_date IN (SELECT interval_val FROM vw_common_07days)

        ) as main

        WHERE ('HIPS_SEVERITY_STATUS'::en_widget_item_type = ANY(i_widget_item_type))
            AND v_product_auth_check

        /* HIPS 위험도별 현황-최근24시간 */
        UNION ALL
        SELECT
            'HIPS_SEVERITY_STATUS'::en_widget_item_type AS widget_item_type
            ,'HIPS_SEVERITY_STATUS_LAST_24_HR' AS widget_item_sub_type
            ,0 AS node_id
            ,0 AS value
            , '' AS std_group_key

            ,JSON_BUILD_OBJECT(
                 'critical', main.critical,
                 'high', main.high,
                 'medium', main.medium,
                 'low', main.low,
                 'info', main.info

            )::text AS std_group_title

        FROM (
            SELECT COALESCE(SUM(timeline.critical_count), 0) as critical,
                   COALESCE(SUM(timeline.high_count), 0) as high,
                   COALESCE(SUM(timeline.medium_count), 0) as medium,
                   COALESCE(SUM(timeline.low_count), 0) as low,
                   COALESCE(SUM(timeline.information_count), 0) as info

            FROM tb_hips_detect_hourly_timeline timeline

            INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
            INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
            INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'

            WHERE ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
            AND timeline.reg_date IN (SELECT interval_val FROM vw_common_24hours)

        ) as main

        WHERE ('HIPS_SEVERITY_STATUS'::en_widget_item_type = ANY(i_widget_item_type))
            AND v_product_auth_check

    ) org

    /* 최근 HIPS 차단/탐지 현황 */
    UNION ALL
    SELECT  'HIPS_DETECT_LIST'::en_widget_item_type AS widget_item_type
           ,'HIPS_DETECT_LIST' AS widget_item_sub_type
           ,0 AS node_id
           ,0 AS value
           ,timeline.reg_date_time AS std_group_key
           ,JSON_BUILD_OBJECT(
                 'reg_date_time', timeline.reg_date_time
                ,'severity', timeline.severity
                ,'name', timeline.name
                ,'saddr', timeline.saddr
                ,'daddr', timeline.daddr
                ,'packet', timeline.detect_bytes
            )::text AS std_group_title
    FROM (
        SELECT  timeline.node_id, to_char(to_timestamp(reg_date || min_sec, 'YYYYMMDDHH24MISS'), 'YYYY-MM-DD HH24:MI:SS') AS reg_date_time, severity, "name", saddr, daddr, detect_bytes
        FROM    tb_hips_detect_event_log_hourly timeline
        ORDER BY obj_id DESC
        LIMIT 5
    ) timeline
    INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
    INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
    INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'
    WHERE ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
    AND ('HIPS_DETECT_LIST'::en_widget_item_type = ANY(i_widget_item_type))
    AND v_product_auth_check

   /* HIPS FW 상태 */
    UNION ALL
    SELECT org.widget_item_type
          ,org.widget_item_sub_type
          ,org.node_id
          ,org.value
          ,org.std_group_key
          ,org.std_group_title
    FROM (
        SELECT 'HIPS_FW_STATUS'::en_widget_item_type AS widget_item_type
                ,CONCAT('HIPS_FW_STATUS_', CASE WHEN hs.engine_state = 'OFF' THEN 'ENGINE_OFF' ELSE hs.fw_status::TEXT END)::TEXT AS widget_item_sub_type -- engine_state가 OFF인 경우에는 ENGINE_OFF로 처리(CWPP-4001)
                ,n.node_id as node_id
                , 1 AS value
                , '' AS std_group_key
                , '' AS std_group_title
        FROM tb_node n
        JOIN tb_product_info pi ON n.node_id = pi.node_id
        JOIN tb_product p ON pi.product_id = p.product_id
        JOIN tb_platform platform ON n.platform_id = platform.platform_id
        JOIN tb_hips_status hs on n.node_id = hs.node_id
        WHERE n.is_removed IS FALSE
          AND p.product_group = 'HIPS'
          AND platform.is_supported IS TRUE
            AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
            AND ('HIPS_FW_STATUS'::en_widget_item_type = ANY(i_widget_item_type))
            AND v_product_auth_check
      ) org
    WHERE org.widget_item_sub_type = ANY(i_widget_item_sub_type)


    /* HIPS FW(방화벽) 최근 30일, 최근 7일, 최근 24시간 */
    UNION ALL
    SELECT
      org.widget_item_type
      , org.widget_item_sub_type
      , org.node_id
      , org.value
      , org.std_group_key
      , org.std_group_title
    FROM (
      WITH vw_common_30days AS (
        SELECT
          to_char(interval_val, 'YYYYMMDD')::int4 AS interval_val
        FROM
          generate_series(date_trunc('DAYS', v_now - '29 DAYS'::interval), date_trunc('DAYS', v_now),'1 DAYS'::interval) interval_val
      ), vw_common_07days AS (
        SELECT
          to_char(interval_val, 'YYYYMMDD')::int4 AS interval_val
        FROM
          generate_series(date_trunc('DAYS', v_now - '6 DAYS'::interval), date_trunc('DAYS', v_now),'1 DAYS'::interval) interval_val
      ), vw_common_24hours AS (
        SELECT
          to_char(interval_val, 'YYYYMMDDHH24')::int4 AS interval_val
        FROM
          generate_series(date_trunc('HOURS', v_now - '23 HOURS'::interval), date_trunc('HOURS', v_now),'1 HOURS'::interval) interval_val
      )
      /* HIPS FW(방화벽) 차단 IP 순위 - 최근 30일 */
      SELECT
        'HIPS_FW_SIP_TOP'::en_widget_item_type AS widget_item_type
        , 'HIPS_FW_SIP_TOP_LAST_30_DAYS' AS widget_item_sub_type
        , 0 AS node_id
        , 0 AS value
        , timeline.src_ip::text AS std_group_key
        , JSON_BUILD_OBJECT(
            'src_ip', timeline.src_ip
            , 'src_ip_count', timeline.src_ip_count
        )::text AS std_group_title
      FROM (
        SELECT timeline.src_ip, timeline.src_ip_count
        FROM (
            SELECT timeline.src_ip, SUM(src_ip_count) AS src_ip_count
            FROM vw_common_30days
            INNER JOIN tb_hips_fw_block_ip_daily_timeline timeline ON vw_common_30days.interval_val = timeline.reg_date
            INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
            INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
            INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'
            WHERE ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
                AND ('HIPS_FW_SIP_TOP'::en_widget_item_type = ANY(i_widget_item_type))
                AND v_product_auth_check
            GROUP BY
              timeline.src_ip
        ) timeline
        ORDER BY timeline.src_ip_count DESC
        LIMIT v_top_limit
      ) timeline
      /* HIPS FW(방화벽) 차단 IP 순위 - 최근 7일 */
      UNION ALL
      SELECT
        'HIPS_FW_SIP_TOP'::en_widget_item_type AS widget_item_type
        , 'HIPS_FW_SIP_TOP_LAST_7_DAYS' AS widget_item_sub_type
        , 0 AS node_id
        , 0 AS value
        , timeline.src_ip::text AS std_group_key
        , JSON_BUILD_OBJECT(
            'src_ip', timeline.src_ip
            , 'src_ip_count', timeline.src_ip_count
        )::text AS std_group_title
      FROM (
        SELECT timeline.src_ip, timeline.src_ip_count
        FROM (
            SELECT timeline.src_ip, SUM(src_ip_count) AS src_ip_count
            FROM vw_common_07days
            INNER JOIN tb_hips_fw_block_ip_daily_timeline timeline ON vw_common_07days.interval_val = timeline.reg_date
            INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
            INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
            INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'
            WHERE ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
                AND ('HIPS_FW_SIP_TOP'::en_widget_item_type = ANY(i_widget_item_type))
                AND v_product_auth_check
            GROUP BY
              timeline.src_ip
        ) timeline
        ORDER BY timeline.src_ip_count DESC
        LIMIT v_top_limit
      ) timeline
      /* HIPS FW(방화벽) 차단 IP 순위 - 최근 24시간 */
      UNION ALL
      SELECT
        'HIPS_FW_SIP_TOP'::en_widget_item_type AS widget_item_type
        , 'HIPS_FW_SIP_TOP_LAST_24_HR' AS widget_item_sub_type
        , 0 AS node_id
        , 0 AS value
        , timeline.src_ip::text AS std_group_key
        , JSON_BUILD_OBJECT(
            'src_ip', timeline.src_ip
            , 'src_ip_count', timeline.src_ip_count
        )::text AS std_group_title
      FROM (
        SELECT timeline.src_ip, timeline.src_ip_count
        FROM (
            SELECT timeline.src_ip, SUM(src_ip_count) AS src_ip_count
            FROM vw_common_24hours
            INNER JOIN tb_hips_fw_block_ip_hourly_timeline timeline ON vw_common_24hours.interval_val = timeline.reg_date
            INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
            INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
            INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'
            WHERE ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
                AND ('HIPS_FW_SIP_TOP'::en_widget_item_type = ANY(i_widget_item_type))
                AND v_product_auth_check
            GROUP BY
              timeline.src_ip
        ) timeline
        ORDER BY timeline.src_ip_count DESC
        LIMIT v_top_limit
      ) timeline

      /* HIPS FW(방화벽) 차단 에이전트 Top - 최근 30일 */
      UNION ALL
      SELECT
        'HIPS_FW_AGENT_TOP'::en_widget_item_type AS widget_item_type
        , 'HIPS_FW_AGENT_TOP_LAST_30_DAYS' AS widget_item_sub_type
        , 0 AS node_id
        , 0 AS value
        , timeline.ip::text AS std_group_key
        , JSON_BUILD_OBJECT(
            'ip', timeline.ip
            , 'computer_name', timeline.computer_name
            , 'ip_count', timeline.ip_count
        )::text AS std_group_title
      FROM (
        SELECT timeline.ip, timeline.computer_name, timeline.ip_count
        FROM (
            SELECT timeline.ip, timeline.computer_name, SUM(timeline.ip_count) AS ip_count
            FROM vw_common_30days
            INNER JOIN tb_hips_fw_block_agent_daily_timeline timeline ON vw_common_30days.interval_val = timeline.reg_date
            INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
              INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
              INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'
              WHERE ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
                AND ('HIPS_FW_AGENT_TOP'::en_widget_item_type = ANY(i_widget_item_type))
                AND v_product_auth_check
            GROUP BY
              timeline.ip, timeline.computer_name
        ) timeline
        ORDER BY timeline.ip_count DESC
        LIMIT v_top_limit
      ) timeline
      /* HIPS FW(방화벽) 차단 에이전트 Top - 최근 7일 */
      UNION ALL
      SELECT
        'HIPS_FW_AGENT_TOP'::en_widget_item_type AS widget_item_type
        , 'HIPS_FW_AGENT_TOP_LAST_7_DAYS' AS widget_item_sub_type
        , 0 AS node_id
        , 0 AS value
        , timeline.ip::text AS std_group_key
        , JSON_BUILD_OBJECT(
            'ip', timeline.ip
            , 'computer_name', timeline.computer_name
            , 'ip_count', timeline.ip_count
        )::text AS std_group_title
      FROM (
        SELECT timeline.ip, timeline.computer_name, timeline.ip_count
        FROM (
            SELECT timeline.ip, timeline.computer_name, SUM(timeline.ip_count) AS ip_count
            FROM vw_common_07days
                  INNER JOIN tb_hips_fw_block_agent_daily_timeline timeline ON vw_common_07days.interval_val = timeline.reg_date
                  INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
              INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
              INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'
              WHERE ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
                AND ('HIPS_FW_AGENT_TOP'::en_widget_item_type = ANY(i_widget_item_type))
                AND v_product_auth_check
            GROUP BY
              timeline.ip, timeline.computer_name
        ) timeline
        ORDER BY timeline.ip_count DESC
        LIMIT v_top_limit
      ) timeline
      /* HIPS FW(방화벽) 차단 에이전트 Top - 최근 24시간 */
      UNION ALL
      SELECT
        'HIPS_FW_AGENT_TOP'::en_widget_item_type AS widget_item_type
        , 'HIPS_FW_AGENT_TOP_LAST_24_HR' AS widget_item_sub_type
        , 0 AS node_id
        , 0 AS value
        , timeline.ip::text AS std_group_key
        , JSON_BUILD_OBJECT(
            'ip', timeline.ip
            , 'computer_name', timeline.computer_name
            , 'ip_count', timeline.ip_count
        )::text AS std_group_title
      FROM (
        SELECT timeline.ip, timeline.computer_name, timeline.ip_count
        FROM (
          SELECT timeline.ip, timeline.computer_name, SUM(timeline.ip_count) AS ip_count
          FROM vw_common_24hours
          INNER JOIN tb_hips_fw_block_agent_hourly_timeline timeline ON vw_common_24hours.interval_val = timeline.reg_date
          INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
          INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
          INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'
          WHERE ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
          AND ('HIPS_FW_AGENT_TOP'::en_widget_item_type = ANY(i_widget_item_type))
          AND v_product_auth_check
          GROUP BY
            timeline.ip, timeline.computer_name
        ) timeline
        ORDER BY timeline.ip_count DESC
        LIMIT v_top_limit
      ) timeline

      /* HIPS FW(방화벽) 차단 추이 - 최근 30일 */
      UNION ALL
      SELECT
        'HIPS_FW_HISTORY'::en_widget_item_type AS widget_item_type
        , 'HIPS_FW_HISTORY_LAST_30_DAYS' AS widget_item_sub_type
        , 0 AS node_id
        , 0 AS value
        , main.reg_date::text AS std_group_key
        , JSON_BUILD_OBJECT(
            'reg_date', main.reg_date
            , 'block_count', main.block_count
        )::text AS std_group_title
      FROM (
        SELECT criteria.reg_date::text AS reg_date, COALESCE(target.block_count, 0) AS block_count
        FROM (
          SELECT interval_val AS reg_date
          FROM vw_common_30days

        ) AS criteria
        LEFT JOIN (
          SELECT timeline.reg_date, SUM(timeline.block_count) AS block_count
          FROM tb_hips_fw_daily_timeline timeline
          INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
          INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
          INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'
          WHERE ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
          AND timeline.reg_date IN (SELECT interval_val FROM vw_common_30days)
          GROUP BY reg_date
        ) AS target
        ON (criteria.reg_date = target.reg_date)
      ) AS main
      WHERE ('HIPS_FW_HISTORY'::en_widget_item_type = ANY(i_widget_item_type))
      AND v_product_auth_check
      /* HIPS FW(방화벽) 차단 추이 - 최근 7일 */
      UNION ALL
      SELECT
        'HIPS_FW_HISTORY'::en_widget_item_type AS widget_item_type
        , 'HIPS_FW_HISTORY_LAST_7_DAYS' AS widget_item_sub_type
        , 0 AS node_id
        , 0 AS value
        , main.reg_date::text AS std_group_key
        , JSON_BUILD_OBJECT(
            'reg_date', main.reg_date
            , 'block_count', main.block_count
        )::text AS std_group_title
      FROM (
        SELECT criteria.reg_date::text AS reg_date, COALESCE(target.block_count, 0) AS block_count
        FROM (
          SELECT interval_val AS reg_date
          FROM vw_common_07days
        ) AS criteria
        LEFT JOIN (
          SELECT timeline.reg_date, SUM(timeline.block_count) AS block_count
          FROM tb_hips_fw_daily_timeline timeline
          INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
          INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
          INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'
          WHERE ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
          AND timeline.reg_date IN (SELECT interval_val FROM vw_common_07days)
          GROUP BY reg_date
        ) AS target
        ON (criteria.reg_date = target.reg_date)
      ) AS main
      WHERE ('HIPS_FW_HISTORY'::en_widget_item_type = ANY(i_widget_item_type))
      AND v_product_auth_check
      /* HIPS FW(방화벽) 차단 추이 - 최근 24시간 */
      UNION ALL
      SELECT
        'HIPS_FW_HISTORY'::en_widget_item_type AS widget_item_type
        , 'HIPS_FW_HISTORY_LAST_24_HR' AS widget_item_sub_type
        , 0 AS node_id
        , 0 AS value
        , main.reg_date::text AS std_group_key
        , JSON_BUILD_OBJECT(
            'reg_date', main.reg_date
            , 'block_count', main.block_count
        )::text AS std_group_title
      FROM (
        SELECT criteria.reg_date::text AS reg_date, COALESCE(target.block_count, 0) AS block_count
        FROM (
          SELECT interval_val AS reg_date
          FROM vw_common_24hours
        ) as criteria
        LEFT JOIN (
          SELECT timeline.reg_date, SUM(timeline.block_count) AS block_count
          FROM tb_hips_fw_hourly_timeline timeline
          INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
          INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
          INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'
          WHERE ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
          AND timeline.reg_date IN (SELECT interval_val FROM vw_common_24hours)
          GROUP BY reg_date
        ) AS target
        ON (criteria.reg_date = target.reg_date)
      ) AS main
      WHERE ('HIPS_FW_HISTORY'::en_widget_item_type = ANY(i_widget_item_type))
      AND v_product_auth_check

      /* HIPS FW(방화벽) 차단 포트 순위 - 최근 30일 */
      UNION ALL
      SELECT
        'HIPS_FW_PORT_TOP'::en_widget_item_type AS widget_item_type
        , 'HIPS_FW_PORT_TOP_LAST_30_DAYS' AS widget_item_sub_type
        , 0 AS node_id
        , 0 AS value
        , timeline.dst_port::text AS std_group_key
        , JSON_BUILD_OBJECT(
            'dst_port', timeline.dst_port
            , 'dst_port_count', timeline.dst_port_count
        )::text AS std_group_title
      FROM (
        SELECT timeline.dst_port, timeline.dst_port_count
        FROM (
            SELECT timeline.dst_port, SUM(timeline.dst_port_count) AS dst_port_count
            FROM vw_common_30days
                  INNER JOIN tb_hips_fw_block_port_daily_timeline timeline ON vw_common_30days.interval_val = timeline.reg_date
                  INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
            INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
            INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'
            WHERE ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
                AND ('HIPS_FW_PORT_TOP'::en_widget_item_type = ANY(i_widget_item_type))
                AND v_product_auth_check
            GROUP BY
              timeline.dst_port
        ) timeline
        ORDER BY timeline.dst_port_count DESC
        LIMIT v_top_limit
      ) timeline
      /* HIPS FW(방화벽) 차단 포트 순위 - 최근 7일 */
      UNION ALL
      SELECT
        'HIPS_FW_PORT_TOP'::en_widget_item_type AS widget_item_type
        , 'HIPS_FW_PORT_TOP_LAST_7_DAYS' AS widget_item_sub_type
        , 0 AS node_id
        , 0 AS value
        , timeline.dst_port::text AS std_group_key
        , JSON_BUILD_OBJECT(
            'dst_port', timeline.dst_port
            ,'dst_port_count', timeline.dst_port_count
        )::text AS std_group_title
      FROM (
        SELECT timeline.dst_port, timeline.dst_port_count
        FROM (
            SELECT timeline.dst_port, SUM(timeline.dst_port_count) AS dst_port_count
            FROM vw_common_07days
                  INNER JOIN tb_hips_fw_block_port_daily_timeline timeline ON vw_common_07days.interval_val = timeline.reg_date
                  INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
            INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
            INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'
            WHERE ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
                AND ('HIPS_FW_PORT_TOP'::en_widget_item_type = ANY(i_widget_item_type))
                AND v_product_auth_check
            GROUP BY
              timeline.dst_port
        ) timeline
        ORDER BY timeline.dst_port_count DESC
        LIMIT v_top_limit
      ) timeline
      /* HIPS FW(방화벽) 차단 포트 순위 - 최근 24시간 */
      UNION ALL
      SELECT
        'HIPS_FW_PORT_TOP'::en_widget_item_type AS widget_item_type
        , 'HIPS_FW_PORT_TOP_LAST_24_HR' AS widget_item_sub_type
        , 0 AS node_id
        , 0 AS value
        , timeline.dst_port::text AS std_group_key
        , JSON_BUILD_OBJECT(
            'dst_port', timeline.dst_port
            , 'dst_port_count', timeline.dst_port_count
        )::text AS std_group_title
      FROM (
        SELECT timeline.dst_port, timeline.dst_port_count
        FROM (
            SELECT timeline.dst_port, SUM(timeline.dst_port_count) AS dst_port_count
            FROM vw_common_24hours
                  INNER JOIN tb_hips_fw_block_port_hourly_timeline timeline ON vw_common_24hours.interval_val = timeline.reg_date
                  INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
            INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
            INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'
            WHERE ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
                AND ('HIPS_FW_PORT_TOP'::en_widget_item_type = ANY(i_widget_item_type))
                AND v_product_auth_check
            GROUP BY
              timeline.dst_port
        ) timeline
        ORDER BY timeline.dst_port_count DESC
        LIMIT v_top_limit
      ) timeline

      /* HIPS FW(방화벽) 차단 규칙 순위 - 최근 30일 */
      UNION ALL
      SELECT
        'HIPS_FW_RULE_TOP'::en_widget_item_type AS widget_item_type
        , 'HIPS_FW_RULE_TOP_LAST_30_DAYS' AS widget_item_sub_type
        , 0 AS node_id
        , 0 AS value
        , timeline.rule_name::text AS std_group_key
        , JSON_BUILD_OBJECT(
            'rule_name', timeline.rule_name
            , 'rule_name_count', timeline.rule_name_count
        )::text AS std_group_title
      FROM (
        SELECT timeline.rule_name, timeline.rule_name_count
        FROM (
            SELECT timeline.rule_name, SUM(timeline.rule_name_count) AS rule_name_count
            FROM vw_common_30days
                INNER JOIN tb_hips_fw_block_rule_daily_timeline timeline ON vw_common_30days.interval_val = timeline.reg_date
                INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
            INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
            INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'
            WHERE ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
                AND ('HIPS_FW_RULE_TOP'::en_widget_item_type = ANY(i_widget_item_type))
                AND v_product_auth_check
            GROUP BY
              timeline.rule_name
        ) timeline
        ORDER BY timeline.rule_name_count DESC
        LIMIT v_top_limit
      ) timeline
      /* HIPS FW(방화벽) 차단 규칙 순위 - 최근 7일 */
      UNION ALL
      SELECT
        'HIPS_FW_RULE_TOP'::en_widget_item_type AS widget_item_type
        , 'HIPS_FW_RULE_TOP_LAST_7_DAYS' AS widget_item_sub_type
        , 0 AS node_id
        , 0 AS value
        , timeline.rule_name::text AS std_group_key
        , JSON_BUILD_OBJECT(
            'rule_name', timeline.rule_name
            ,'rule_name_count', timeline.rule_name_count
        )::text AS std_group_title
      FROM (
        SELECT timeline.rule_name, timeline.rule_name_count
        FROM (
            SELECT timeline.rule_name, SUM(timeline.rule_name_count) AS rule_name_count
            FROM vw_common_07days
                INNER JOIN tb_hips_fw_block_rule_daily_timeline timeline ON vw_common_07days.interval_val = timeline.reg_date
                INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
            INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
            INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'
            WHERE ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
                AND ('HIPS_FW_RULE_TOP'::en_widget_item_type = ANY(i_widget_item_type))
                AND v_product_auth_check
            GROUP BY
              timeline.rule_name
        ) timeline
        ORDER BY timeline.rule_name_count DESC
        LIMIT v_top_limit
      ) timeline
      /* HIPS FW(방화벽) 차단 규칙 순위 - 최근 24시간 */
      UNION ALL
      SELECT
        'HIPS_FW_RULE_TOP'::en_widget_item_type AS widget_item_type
        , 'HIPS_FW_RULE_TOP_LAST_24_HR' AS widget_item_sub_type
        , 0 AS node_id
        , 0 AS value
        , timeline.rule_name::text AS std_group_key
        , JSON_BUILD_OBJECT(
            'rule_name', timeline.rule_name
            ,'rule_name_count', timeline.rule_name_count
        )::text AS std_group_title
      FROM (
        SELECT timeline.rule_name, timeline.rule_name_count
        FROM (
            SELECT timeline.rule_name, SUM(timeline.rule_name_count) AS rule_name_count
            FROM vw_common_24hours
                INNER JOIN tb_hips_fw_block_rule_hourly_timeline timeline ON vw_common_24hours.interval_val = timeline.reg_date
                INNER JOIN tb_node n ON timeline.node_id = n.node_id AND n.is_removed IS FALSE
            INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
            INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'HIPS'
            WHERE ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
                AND ('HIPS_FW_RULE_TOP'::en_widget_item_type = ANY(i_widget_item_type))
                AND v_product_auth_check
            GROUP BY
              timeline.rule_name
        ) timeline
        ORDER BY timeline.rule_name_count DESC
        LIMIT v_top_limit
      ) timeline
    ) org
    ;

END;
$$;


ALTER FUNCTION public.sp_get_custom_dashboard_hips_link_node_list(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_custom_dashboard_hips_link_node_list(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_custom_dashboard_hips_link_node_list(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text) IS '
@brief [] - 제품별 및 커스텀 대시보드 > HIPS 노드 리스트
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_custom_dashboard_scm(public.en_widget_item_type[], text[], bigint, bigint, public.en_language, text, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_custom_dashboard_scm(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text, i_node_id_arr bigint[]) RETURNS TABLE(link_type text, widget_item_type public.en_widget_item_type, widget_item_sub_type text, response_values text, ord_num bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE

    v_link_type text := 'CUSTOM_DASHBOARD';

BEGIN

  RETURN QUERY

  SELECT
    v_link_type AS link_type
    , wit.widget_item_type
    , wit.widget_item_sub_type
    , (CASE
          WHEN (org.std_group_title IS NULL OR org.std_group_title = '') AND wit.is_show_default_col IS TRUE THEN
            JSON_BUILD_OBJECT(
              'value', COALESCE(org.value, 0)
            )::text
          ELSE
              org.std_group_title
      END) AS response_values
    , ROW_NUMBER() OVER (ORDER BY org.widget_item_type, org.widget_item_sub_type, org.std_group_key, org.value DESC) AS ord_num
  FROM ( 
    SELECT
      wit.widget_item_type
      , wit.widget_item_sub_type
      , wit.product_group
      , (CASE WHEN wit.widget_item_type IN('SCM_COMPLIANCE_AGENT_TOP', 'SCM_SECRET_AGENT_TOP') THEN FALSE ELSE TRUE END) is_show_default_col
    FROM
      tb_widget_item_type wit
    WHERE
      wit.product_group = 'SCM'
  ) wit
  LEFT JOIN (
    /* SCM 설치 현황 */
    SELECT
      org_rate.widget_item_type
      , org_rate.widget_item_sub_type
      , org_rate.value
      , org_rate.std_group_key
      , org_rate.std_group_title
    FROM(
      WITH org_data AS (
        SELECT
          data.widget_item_type
          , data.widget_item_sub_type
          , SUM(data.value)::bigint AS value
          , data.std_group_key
          , data.std_group_key AS std_group_title
        FROM
          sp_get_custom_dashboard_scm_link_node_list('{SCM_INSTALL}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
        WHERE
          ('SCM_INSTALL' = ANY(i_widget_item_type))
          AND data.node_id= ANY(i_node_id_arr)
        GROUP BY
          data.widget_item_type, data.widget_item_sub_type, data.std_group_key
      )
      SELECT
        data.widget_item_type
        , data.widget_item_sub_type
        , data.value
        , data.std_group_key
        , data.std_group_title
      FROM
        org_data data
    ) org_rate

      /* SCM 정책 */
    UNION ALL
    SELECT
      data.widget_item_type
      , data.widget_item_sub_type
      , SUM(data.value) AS value
      , data.std_group_key
      , data.std_group_key AS std_group_title
    FROM
      sp_get_custom_dashboard_scm_link_node_list('{SCM_POLICY_STATUS}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('SCM_POLICY_STATUS' = ANY(i_widget_item_type))
      AND data.node_id= ANY(i_node_id_arr)
    GROUP BY
      data.widget_item_type, data.widget_item_sub_type, data.std_group_key

      /* SCM 상태 */
    UNION ALL
    SELECT
      data.widget_item_type
      , data.widget_item_sub_type
      , SUM(data.value) AS value
      , data.std_group_key
      , data.std_group_key AS std_group_title
    FROM
      sp_get_custom_dashboard_scm_link_node_list('{SCM_STATUS}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('SCM_STATUS' = ANY(i_widget_item_type))
      AND data.node_id= ANY(i_node_id_arr)
      GROUP BY
      data.widget_item_type, data.widget_item_sub_type, data.std_group_key

    /* SCM 보안 수준 취약 에이전트 순위 */
    UNION ALL
    SELECT
      data.widget_item_type
      , data.widget_item_sub_type
      , data.value
      , data.std_group_key
      , data.std_group_title
    FROM
      sp_get_custom_dashboard_scm_link_node_list('{SCM_COMPLIANCE_AGENT_TOP}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('SCM_COMPLIANCE_AGENT_TOP' = ANY(i_widget_item_type))
      AND data.node_id= ANY(i_node_id_arr)

    /* SCM 실행 민감 정도 취약 순위 */
    UNION ALL
    SELECT
      data.widget_item_type
      , data.widget_item_sub_type
      , data.value
      , data.std_group_key
      , data.std_group_title
    FROM
      sp_get_custom_dashboard_scm_link_node_list('{SCM_SECRET_AGENT_TOP}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('SCM_SECRET_AGENT_TOP' = ANY(i_widget_item_type))
      AND data.node_id= ANY(i_node_id_arr)

    /* 최근 30일 SCM 수동 검사율 */
    UNION ALL
    SELECT
      data.widget_item_type
      , data.widget_item_sub_type
      , SUM(data.value) AS value
      , data.std_group_key
      , data.std_group_key AS std_group_title
    FROM
      sp_get_custom_dashboard_scm_link_node_list('{SCM_MANUAL_SCAN_RATIO}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('SCM_MANUAL_SCAN_RATIO' = ANY(i_widget_item_type))
      AND data.node_id= ANY(i_node_id_arr)
    GROUP BY
      data.widget_item_type, data.widget_item_sub_type, data.std_group_key
  ) org
  ON wit.widget_item_sub_type = org.widget_item_sub_type
  WHERE
    wit.product_group = 'SCM'
  AND wit.widget_item_sub_type = ANY(i_widget_item_sub_type)
  ;


END;
$$;


ALTER FUNCTION public.sp_get_custom_dashboard_scm(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text, i_node_id_arr bigint[]) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_custom_dashboard_scm(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text, i_node_id_arr bigint[]); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_custom_dashboard_scm(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text, i_node_id_arr bigint[]) IS '
@brief [] - 제품별 및 커스텀 대시보드 > SCM 요약
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_custom_dashboard_scm_link_node_list(public.en_widget_item_type[], text[], bigint, bigint, public.en_language, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_custom_dashboard_scm_link_node_list(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text) RETURNS TABLE(widget_item_type public.en_widget_item_type, widget_item_sub_type text, node_id bigint, value bigint, std_group_key text, std_group_title text)
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_product_auth_check boolean;
  v_all_target boolean;
  v_node_id_array bigint[];

  v_top_limit integer := 10;
  v_not_support_platform  en_platform_type[];

BEGIN

  v_product_auth_check := sp_get_product_auth_check(i_product_auth, 'SCM');

  SELECT COALESCE(config.not_support_platform,'{}') INTO v_not_support_platform
  FROM sp_get_not_manage_product('SCM'::en_product_group_type) AS config;

  IF (i_group_id IS NULL OR i_group_id < 1) AND (i_correlation_rule_id IS NULL OR i_correlation_rule_id < 1) THEN
    v_all_target := true;
  ELSE
    v_all_target := false;
    v_node_id_array := sp_get_node_list( i_group_id, i_correlation_rule_id, null );
  END IF;


  RETURN QUERY

    /* SCM 설치율 */
    SELECT
      org.widget_item_type
      , org.widget_item_sub_type
      , org.node_id
      , org.value
      , '' AS std_group_key
      , '' AS std_group_title
    FROM (
      WITH possible_install_node_list AS (
        SELECT
          pf.is_server
          , n.node_id
        FROM
          tb_node n
        INNER JOIN tb_platform pf ON n.platform_id = pf.platform_id
        WHERE
          n.is_removed IS false
        AND pf.is_supported IS TRUE
        AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
        AND ('SCM_INSTALL' = ANY(i_widget_item_type))
        AND v_product_auth_check
      ), installed_server_on AS (
        SELECT
          'SCM_INSTALL'::en_widget_item_type AS widget_item_type
          , 'SCM_INSTALLED_SERVER_ON'::text AS widget_item_sub_type
          , n.node_id
          , 1 AS value
        FROM
          tb_node n
        INNER JOIN tb_product_info pi ON n.node_id = pi.node_id AND n.is_removed IS FALSE
        INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'SCM'
        INNER JOIN tb_platform pf ON n.platform_id = pf.platform_id
        INNER JOIN tb_scm_status scm ON n.node_id = scm.node_id AND scm.service_status = 'ON'
        WHERE pf.is_supported IS TRUE
        AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
        AND ('SCM_INSTALL' = ANY(i_widget_item_type))
        AND ('SCM_INSTALLED_SERVER_ON' = ANY(i_widget_item_sub_type))
        AND v_product_auth_check
      ), installed_server_off AS (
        SELECT
          'SCM_INSTALL'::en_widget_item_type AS widget_item_type
          , 'SCM_INSTALLED_SERVER_OFF'::text AS widget_item_sub_type
          , n.node_id
          , 1 AS value
        FROM
          tb_node n
        INNER JOIN tb_product_info pi ON n.node_id = pi.node_id AND n.is_removed IS FALSE
        INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'SCM'
        INNER JOIN tb_platform pf ON n.platform_id = pf.platform_id
        INNER JOIN tb_scm_status scm ON n.node_id = scm.node_id AND scm.service_status = 'OFF'
        WHERE pf.is_supported IS TRUE
        AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
        AND ('SCM_INSTALL' = ANY(i_widget_item_type))
        AND ('SCM_INSTALLED_SERVER_OFF' = ANY(i_widget_item_sub_type))
        AND v_product_auth_check
      ), not_installed_server AS (
         SELECT
          'SCM_INSTALL'::en_widget_item_type AS widget_item_type
          , 'SCM_NOT_INSTALL_SERVER'::text AS widget_item_sub_type
          , n.node_id
          , 1 AS value
         FROM
          tb_node n
          LEFT JOIN tb_product_info pi ON n.node_id = pi.node_id AND pi.product_id = 'SCM_CLIENT'
          LEFT JOIN tb_platform pf ON n.platform_id = pf.platform_id
          LEFT JOIN tb_scm_status scm ON scm.node_id = n.node_id
          WHERE
            n.is_removed IS FALSE
          AND (pi.product_id IS NULL OR scm.service_status IS NULL)
          AND pf.is_supported IS TRUE
          AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
          AND ('SCM_INSTALL' = ANY(i_widget_item_type))
          AND ('SCM_NOT_INSTALL_SERVER' = ANY(i_widget_item_sub_type))
          AND v_product_auth_check
      )
      SELECT
        installed_on.widget_item_type
        , installed_on.widget_item_sub_type
        , installed_on.node_id
        , 1 AS value
      FROM
        installed_server_on installed_on
      UNION ALL
      SELECT
        installed_off.widget_item_type
        , installed_off.widget_item_sub_type
        , installed_off.node_id
        , 1 AS value
      FROM
        installed_server_off installed_off
      UNION ALL
      SELECT
        not_installed_server.widget_item_type
        , not_installed_server.widget_item_sub_type
        , not_installed_server.node_id
        , 1 AS value
      FROM
        not_installed_server
    ) org

    /* SCM 정책 */
    UNION ALL
    SELECT
      org.widget_item_type
      , org.widget_item_sub_type
      , org.node_id
      , org.value
      , org.std_group_key
      , org.std_group_title
    FROM (
      SELECT
        'SCM_POLICY_STATUS'::en_widget_item_type AS widget_item_type
        , CASE
          WHEN ps.policy_status IS NULL THEN CONCAT(pfm.product_feature_id, '_APPLYING')
          ELSE CONCAT(pfm.product_feature_id, '_',  ps.policy_status)
            END AS widget_item_sub_type
        , n.node_id
        , 1 AS value
        , '' AS std_group_key
        , '' AS std_group_title
      FROM tb_node n
      INNER JOIN tb_product_info pi on n.node_id = pi.node_id AND n.is_removed IS FALSE
      INNER JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'SCM'
      INNER JOIN tb_product_feature_map pfm on pfm.product_id = pi.product_id
      INNER JOIN tb_platform platform ON n.platform_id = platform.platform_id
      INNER JOIN tb_scm_status status ON status.node_id = n.node_id
      LEFT JOIN tb_policy_status ps  on n.node_id = ps.node_id and ps.product_feature_id = pfm.product_feature_id
      WHERE platform.is_supported IS TRUE
      AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
      AND ('SCM_POLICY_STATUS'::en_widget_item_type = ANY(i_widget_item_type))
      AND v_product_auth_check
    ) org
    WHERE org.widget_item_sub_type = ANY(i_widget_item_sub_type)

    /* SCM 상태 */
    UNION ALL
    SELECT
      org.widget_item_type
      , org.widget_item_sub_type
      , org.node_id
      , org.value
      , org.std_group_key
      , org.std_group_title
    FROM (
      SELECT
        'SCM_STATUS'::en_widget_item_type AS widget_item_type
        , CONCAT('SCM_STATUS_', scm.hardening_status)::text AS widget_item_sub_type
        , n.node_id as node_id
        , 1 AS value
        , '' AS std_group_key
        , '' AS std_group_title
      FROM tb_node n
      INNER JOIN tb_product_info pi ON n.node_id = pi.node_id
      INNER JOIN tb_product p ON pi.product_id = p.product_id
      INNER JOIN tb_platform platform ON n.platform_id = platform.platform_id
      INNER JOIN tb_scm_status scm on n.node_id = scm.node_id
      WHERE n.is_removed IS FALSE
      AND p.product_group = 'SCM'
      AND platform.is_supported IS TRUE
      AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
      AND ('SCM_STATUS'::en_widget_item_type = ANY(i_widget_item_type))
      AND v_product_auth_check
    ) org
    WHERE org.widget_item_sub_type = ANY(i_widget_item_sub_type)

	  /* SCM 보안 수준 취약 에이전트 순위 */
    UNION ALL
    SELECT
      'SCM_COMPLIANCE_AGENT_TOP'::en_widget_item_type AS widget_item_type
      , 'SCM_COMPLIANCE_AGENT_TOP'::text AS widget_item_sub_type
      , node.node_id AS node_id
      , node.fail_count::bigint AS value
      , CONCAT(node.node_id, '|', COALESCE(node.ip,node.ip_connected), '|', node.computer_name) AS std_group_key
      , JSON_BUILD_OBJECT(
        'ip', COALESCE(HOST(node.ip),HOST(node.ip_connected))
        , 'name', COALESCE(node.computer_name,'')
        , 'value',node.fail_count
      )::TEXT AS std_group_title
    FROM (
      SELECT node.node_id, node.ip, node.computer_name, node.ip_connected, node.fail_count
    	FROM (
        SELECT n.node_id, n.ip, n.computer_name, n.ip_connected, COALESCE(timeline.compliance_scan_fail_count, 0) + COALESCE(timeline.compliance_scan_user_fail_count, 0) AS fail_count
		    FROM
		      tb_node n
		    INNER JOIN tb_scm_status timeline ON n.node_id = timeline.node_id
		    WHERE
		      n.is_removed IS FALSE
		    AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
		    AND ('SCM_COMPLIANCE_AGENT_TOP'::en_widget_item_type = ANY(i_widget_item_type))
		    AND ('SCM_COMPLIANCE_AGENT_TOP'::text = ANY(i_widget_item_sub_type))
		    AND v_product_auth_check
		    GROUP BY
		      n.node_id, n.ip, n.computer_name, timeline.compliance_scan_fail_count, timeline.compliance_scan_user_fail_count
		  ) node
	    ORDER BY node.fail_count DESC
	    LIMIT v_top_limit
	  ) node

    /* SCM 민감 정보 취약 에이전트 순위 */
    UNION ALL
    SELECT
      'SCM_SECRET_AGENT_TOP'::en_widget_item_type AS widget_item_type
      , 'SCM_SECRET_AGENT_TOP'::text AS widget_item_sub_type
      , node.node_id AS node_id
      , node.fail_count::bigint AS value
      , CONCAT(node.node_id, '|', COALESCE(node.ip,node.ip_connected), '|', node.computer_name) AS std_group_key
      , JSON_BUILD_OBJECT(
        'ip', COALESCE(HOST(node.ip),HOST(node.ip_connected))
        , 'name', COALESCE(node.computer_name,'')
        , 'value',node.fail_count
      )::TEXT AS std_group_title
    FROM (
      SELECT node.node_id, node.ip, node.computer_name, node.ip_connected, node.fail_count
    	FROM (
        SELECT n.node_id, n.ip, n.computer_name, n.ip_connected, COALESCE(timeline.secret_scan_fail_count, 0) + COALESCE(timeline.secret_scan_user_fail_count, 0) AS fail_count
		    FROM
		      tb_node n
		    INNER JOIN tb_scm_status timeline ON n.node_id = timeline.node_id
		    WHERE
		      n.is_removed IS FALSE
		    AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
		    AND ('SCM_SECRET_AGENT_TOP'::en_widget_item_type = ANY(i_widget_item_type))
		    AND ('SCM_SECRET_AGENT_TOP'::text = ANY(i_widget_item_sub_type))
		    AND v_product_auth_check
		    GROUP BY
		      n.node_id, n.ip, n.computer_name, timeline.secret_scan_fail_count, timeline.secret_scan_user_fail_count
		  ) node
	    ORDER BY node.fail_count DESC
	    LIMIT v_top_limit
	  ) node

    /* SCM 보안 점검 설정 일자 만큼의 SCM 수동 검사율 */
    UNION ALL
    SELECT
      'SCM_MANUAL_SCAN_RATIO'::en_widget_item_type AS widget_item_type
      , org.widget_item_sub_type
      , org.node_id
      , org.value
      , '' AS std_group_key
      , '' AS std_group_title
    FROM (
      WITH target_node_list AS (
        SELECT
          n.node_id
          , pi.product_id
        FROM
          tb_node n
        INNER JOIN tb_platform pf ON n.platform_id = pf.platform_id
        AND NOT (pf.platform_type = ANY(v_not_support_platform))
        AND pf.is_supported IS TRUE
        INNER JOIN tb_product_info pi ON pi.node_id = n.node_id
        INNER JOIN tb_product p ON p.product_id = pi.product_id AND p.product_group = 'SCM'
        WHERE
          n.is_removed IS FALSE
        AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
        AND ('SCM_MANUAL_SCAN_RATIO'::en_widget_item_type = ANY(i_widget_item_type))
      ), scm_manual_scan_day_interval_config AS (
        SELECT
            tc.value as value
        FROM
            tb_config tc
        WHERE
            tc.config_group = 'AGENT_THRESHOLD'::en_config_group
            AND tc.key = 'manual_scan_day_interval'
      ), scanned_node_list AS (
          SELECT
            scm.node_id
            , 1 AS value
          FROM
            tb_scm_status scm
          INNER JOIN target_node_list tnl ON tnl.node_id = scm.node_id AND tnl.product_id = scm.product_id
          WHERE 
            scm.scan_time >= date_trunc('day', now()) - ((SELECT smsdic.value FROM scm_manual_scan_day_interval_config smsdic)||' day')::INTERVAL
          AND ('SCM_MANUAL_SCAN_RATIO'::en_widget_item_type = ANY(i_widget_item_type))
      )
      SELECT
        'SCM_MANUAL_SCANNED_SERVER'::text AS widget_item_sub_type
        , snl.node_id
        , 1 AS value
      FROM
        scanned_node_list snl
      WHERE
        ('SCM_MANUAL_SCAN_RATIO'::en_widget_item_type = ANY(i_widget_item_type))
        AND ('SCM_MANUAL_SCANNED_SERVER'::text = ANY(i_widget_item_sub_type))
      UNION ALL
      SELECT
        'SCM_MANUAL_NOT_SCAN_SERVER'::text AS widget_item_sub_type
        , tnl.node_id
        , 1 AS value
      FROM
        target_node_list tnl
      WHERE
        NOT EXISTS(
            SELECT 1 FROM scanned_node_list snl WHERE tnl.node_id = snl.node_id
        )
      AND ('SCM_MANUAL_SCAN_RATIO'::en_widget_item_type = ANY(i_widget_item_type))
      AND ('SCM_MANUAL_NOT_SCAN_SERVER' = ANY(i_widget_item_sub_type))
    ) org
    
;

END;
$$;


ALTER FUNCTION public.sp_get_custom_dashboard_scm_link_node_list(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_custom_dashboard_scm_link_node_list(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_custom_dashboard_scm_link_node_list(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text) IS '
@brief [] - 제품별 및 커스텀 대시보드 > SCM 노드 리스트
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_custom_dashboard_v3(public.en_widget_item_type[], text[], bigint, bigint, public.en_language, text, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_custom_dashboard_v3(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text, i_node_id_arr bigint[]) RETURNS TABLE(link_type text, widget_item_type public.en_widget_item_type, widget_item_sub_type text, response_values text, ord_num bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_link_type text := 'CUSTOM_DASHBOARD';

BEGIN

  RETURN QUERY

  SELECT
   v_link_type
   , wit.widget_item_type
   , wit.widget_item_sub_type

   , (CASE
        WHEN (org.std_group_title IS NULL OR org.std_group_title = '') AND wit.is_show_default_col IS TRUE THEN
          JSON_BUILD_OBJECT(
            'value', COALESCE(org.value, 0)
          )::text
        ELSE
            org.std_group_title
    END) AS response_values

    , ROW_NUMBER() OVER (ORDER BY org.widget_item_type, org.widget_item_sub_type, org.std_group_key, org.value DESC) AS ord_num

  FROM
    (
      SELECT
        wit.widget_item_type
        , wit.widget_item_sub_type
        , wit.product_group
        , (CASE WHEN wit.widget_item_type IN('AGENT_MALWARE', 'MALWARE_INFECTION') THEN FALSE ELSE TRUE END) is_show_default_col
      FROM
        tb_widget_item_type wit
      WHERE
        wit.product_group = 'V3'
    ) wit
    LEFT JOIN(

    /* V3 설치 현황 */
    SELECT
      org_rate.widget_item_type
      , org_rate.widget_item_sub_type
      , org_rate.value
      , org_rate.std_group_key
      , org_rate.std_group_title
    FROM(
      WITH org_data AS(
      SELECT
        data.widget_item_type
        , data.widget_item_sub_type
        , SUM(data.value)::bigint AS value
        , data.std_group_key
        , data.std_group_key AS std_group_title
      FROM
        sp_get_custom_dashboard_v3_link_node_list('{V3_INSTALL}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
      WHERE
        ('V3_INSTALL' = ANY(i_widget_item_type))
        AND data.node_id = ANY(i_node_id_arr)

      GROUP BY
        data.widget_item_type
        , data.widget_item_sub_type
        , data.std_group_key
      )
      SELECT
        data.widget_item_type
        , data.widget_item_sub_type
        , data.value
        , data.std_group_key
        , data.std_group_title
      FROM
        org_data data
    ) org_rate


    /* 정책 적용 현황 */
    UNION ALL
    SELECT
        data.widget_item_type
        , data.widget_item_sub_type
        , SUM(data.value)::bigint AS value
        , data.std_group_key
        , data.std_group_key AS std_group_title
      FROM
        sp_get_custom_dashboard_v3_link_node_list('{V3_POLICY_STATUS}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
      WHERE
        ('V3_POLICY_STATUS'::en_widget_item_type = ANY(i_widget_item_type))
        AND data.node_id = ANY(i_node_id_arr)

      GROUP BY
        data.widget_item_type
        , data.widget_item_sub_type
        , data.std_group_key



    /* 최근 7일내 수동 검사율 */
    UNION ALL
    SELECT
        data.widget_item_type
        , data.widget_item_sub_type
        , SUM(data.value)::bigint AS value
        , data.std_group_key
        , data.std_group_key AS std_group_title
      FROM
        sp_get_custom_dashboard_v3_link_node_list('{MANUAL_SCAN_RATIO}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
      WHERE
        ('MANUAL_SCAN_RATIO'::en_widget_item_type = ANY(i_widget_item_type))
        AND data.node_id = ANY(i_node_id_arr)

      GROUP BY
        data.widget_item_type
        , data.widget_item_sub_type
        , data.std_group_key



    /* 최신 엔진 업데이트율 */
    UNION ALL
    SELECT
        data.widget_item_type
        , data.widget_item_sub_type
        , SUM(data.value)::bigint AS value
        , data.std_group_key
        , (CASE
            WHEN data.widget_item_sub_type IN ('ENGINE_UPDATE_VERSION_OES', 'ENGINE_UPDATE_VERSION_SES') THEN
              JSON_BUILD_OBJECT('value', data.std_group_title)::text
            ELSE
              data.std_group_title
            END
        ) AS std_group_title
      FROM
        sp_get_custom_dashboard_v3_link_node_list('{ENGINE_UPDATE_RATIO}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
      WHERE
        ('ENGINE_UPDATE_RATIO'::en_widget_item_type = ANY(i_widget_item_type))
        AND 
	        CASE
	          WHEN data.widget_item_sub_type IN ('ENGINE_UPDATE_VERSION_OES', 'ENGINE_UPDATE_VERSION_SES') THEN true 
	          ELSE
	            data.node_id = ANY(i_node_id_arr)
	        END

      GROUP BY
        data.widget_item_type
        , data.widget_item_sub_type
        , data.std_group_key
        , data.std_group_title

    /* 악성코드 감염 에이전트  순위 */
    UNION ALL
    SELECT
      org.widget_item_type
      , org.widget_item_sub_type
      , org.value
      , '' AS std_group_key
      , org.std_group_title
    FROM(
        SELECT
          data.widget_item_type
          , data.widget_item_sub_type
          , SUM(data.value)::bigint AS value
          , data.std_group_key
          , JSON_BUILD_OBJECT(
             'ip', data.std_group_title::json->>'ip'
             , 'name', data.std_group_title::json->>'name'
             , 'value', SUM(data.value)::bigint
          )::text AS std_group_title
        FROM
          sp_get_custom_dashboard_v3_link_node_list('{AGENT_MALWARE}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
        WHERE
          ('AGENT_MALWARE'::en_widget_item_type = ANY(i_widget_item_type))
          AND data.node_id = ANY(i_node_id_arr)
        GROUP BY
          data.widget_item_type
          , data.widget_item_sub_type
          , data.std_group_key
          , data.std_group_title
    ) org




    /* 악성코드  순위 */
    UNION ALL
    SELECT
      org.widget_item_type
      , org.widget_item_sub_type
      , org.value
      , org.std_group_key
      , org.std_group_title
    FROM(
      SELECT
          data.widget_item_type
          , data.widget_item_sub_type
          , SUM(data.value)::bigint AS value
          , data.std_group_key
          , JSON_BUILD_OBJECT(
            'file_name' , data.std_group_key
            , 'value', SUM(data.value)::bigint
          )::text AS std_group_title
        FROM
          sp_get_custom_dashboard_v3_link_node_list('{MALWARE_INFECTION}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
        WHERE
          ('MALWARE_INFECTION'::en_widget_item_type = ANY(i_widget_item_type))
          AND data.node_id = ANY(i_node_id_arr)

        GROUP BY
          data.widget_item_type
          , data.widget_item_sub_type
          , data.std_group_key
          , data.std_group_title
        ORDER BY
          data.widget_item_type
          , data.widget_item_sub_type
          , SUM(data.value) DESC
          , data.std_group_key
    ) org



    /* 배포 엔진 적용 현황 */
    UNION ALL
    SELECT
      data.widget_item_type
      , data.widget_item_sub_type
      , 0 AS value
      , data.std_group_key
      , data.std_group_title AS std_group_title
    FROM
      sp_get_custom_dashboard_v3_link_node_list('{V3_ENGINE_STATUS}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('V3_ENGINE_STATUS' = ANY(i_widget_item_type))



    /* 악성코드 및 평판 기반 탐지 추이 */
    UNION ALL
    SELECT
      data.widget_item_type
      , data.widget_item_sub_type
      , 0 AS value
      , data.std_group_key
      , (JSON_BUILD_OBJECT(
          'reg_date', data.std_group_key
          , 'value', SUM((data.std_group_title::json->>'detect_count')::bigint)
        )::text
      )AS std_group_title
    FROM
      sp_get_custom_dashboard_v3_link_node_list('{V3_MALWARE_HISTORY}'::en_widget_item_type[], i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      ('V3_MALWARE_HISTORY' = ANY(i_widget_item_type))
    GROUP BY
      data.widget_item_type
      , data.widget_item_sub_type
      , data.std_group_key





  ) org
  ON wit.widget_item_sub_type = org.widget_item_sub_type
  WHERE
    wit.product_group = 'V3'
    AND wit.widget_item_sub_type = ANY(i_widget_item_sub_type)
  ;

END;
$$;


ALTER FUNCTION public.sp_get_custom_dashboard_v3(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text, i_node_id_arr bigint[]) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_custom_dashboard_v3(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text, i_node_id_arr bigint[]); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_custom_dashboard_v3(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text, i_node_id_arr bigint[]) IS '
@brief [] - 제품별 및 커스텀 대시보드 > V3 요약
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_custom_dashboard_v3_link_node_list(public.en_widget_item_type[], text[], bigint, bigint, public.en_language, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_custom_dashboard_v3_link_node_list(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text) RETURNS TABLE(widget_item_type public.en_widget_item_type, widget_item_sub_type text, node_id bigint, value bigint, std_group_key text, std_group_title text)
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_product_auth_check boolean;
  v_all_target boolean;
  v_node_id_array bigint[];

  v_manual_scan_threshold integer := 0;
  v_engine_update_threshold integer := 0;

  v_not_support_platform  en_platform_type[];

BEGIN
  v_product_auth_check := sp_get_product_auth_check(i_product_auth, 'V3');

  IF v_product_auth_check IS TRUE THEN
    -- V3 제품 관리 여부 가져오기
    -- 관리하지 않는 os 정보 가져오기
    SELECT
      COALESCE(config.not_support_platform,'{}') INTO v_not_support_platform
    FROM
      sp_get_not_manage_product('V3') AS config;

    IF (i_group_id IS NULL OR i_group_id < 1) AND (i_correlation_rule_id IS NULL OR i_correlation_rule_id < 1) THEN
      v_all_target := true;
    ELSE
      v_all_target := false;
      v_node_id_array := sp_get_node_list( i_group_id, i_correlation_rule_id, null );
    END IF;

    IF 'MANUAL_SCAN_RATIO'::en_widget_item_type = ANY(i_widget_item_type) THEN
      SELECT
        COALESCE(c.value, '0')::integer INTO v_manual_scan_threshold
      FROM
        tb_config AS c
      WHERE
        c.config_group = 'AGENT_THRESHOLD'
        AND c.key = 'manual_scan_threshold';
    END IF;

    IF 'V3_ENGINE_STATUS'::en_widget_item_type = ANY(i_widget_item_type) THEN
      SELECT
        COALESCE(c.value, '0')::integer INTO v_engine_update_threshold
      FROM
        tb_config AS c
      WHERE
        c.config_group = 'AGENT_THRESHOLD'
        AND c.key = 'engine_update_threshold';
    END IF;

    RETURN QUERY

      /* V3 설치율 */
      SELECT
        org.widget_item_type
        , org.widget_item_sub_type
        , org.node_id
        , org.value
        , '' AS std_group_key
        , '' AS std_group_title
      FROM(
        WITH node_list AS(  -- 에이전트 전체 리스트
          SELECT
            n.node_id
            , pi.product_id
            , CASE WHEN (SELECT platform_type FROM tb_platform WHERE platform_id = n.platform_id) = ANY(v_not_support_platform)
                    THEN FALSE
                   ELSE COALESCE(pi.is_managed,TRUE)
              END AS is_managed
            , CASE WHEN n.machine_type != 'CONTAINER' THEN TRUE
                   WHEN n.machine_type = 'CONTAINER' AND tcp.is_amc_supported IS TRUE THEN TRUE
                   ELSE FALSE
              END AS is_am_supported
          FROM
            tb_node n
            INNER JOIN tb_platform pf ON n.platform_id = pf.platform_id AND pf.is_supported IS TRUE AND pf.is_server IS TRUE
            LEFT JOIN tb_product_info pi ON pi.node_id = n.node_id
            LEFT JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'V3'
            LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = n.container_service_type
          WHERE
            n.is_removed IS FALSE
            AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
            AND ('V3_INSTALL'::en_widget_item_type = ANY(i_widget_item_type))
        )
        , install_list AS ( -- 설치 리스트
          SELECT
            'V3_INSTALL'::en_widget_item_type AS widget_item_type
            , 'V3_INSTALLED_SERVER'::text AS widget_item_sub_type
            , n.node_id
            , 1 AS value
          FROM
            node_list n
          WHERE
            n.is_managed IS TRUE
            AND n.is_am_supported IS TRUE
            AND EXISTS (SELECT 1 FROM tb_product WHERE product_id = n.product_id AND product_group = 'V3')
            AND ('V3_INSTALL'::en_widget_item_type = ANY(i_widget_item_type))
            AND ('V3_INSTALLED_SERVER' = ANY(i_widget_item_sub_type))
            GROUP BY n.node_id
        )
        , not_install_list AS ( -- 미설치 리스트
          SELECT
            'V3_INSTALL'::en_widget_item_type AS widget_item_type
            , 'V3_INSTALL_NOT_INSTALLED_SERVER'::text AS widget_item_sub_type
            , n.node_id
            , 1 AS value
          FROM
            node_list n
          WHERE
            n.is_managed IS TRUE
            AND n.is_am_supported IS TRUE
            AND NOT EXISTS(
              SELECT 1 FROM install_list install WHERE n.node_id = install.node_id
            )
            AND ('V3_INSTALL'::en_widget_item_type = ANY(i_widget_item_type))
            AND ('V3_INSTALL_NOT_INSTALLED_SERVER' = ANY(i_widget_item_sub_type))
            GROUP BY n.node_id
        )
        , not_supported_list AS ( -- 미지원 리스트
          SELECT
            'V3_INSTALL'::en_widget_item_type AS widget_item_type
            , 'V3_INSTALL_NOT_SUPPORTED_SERVER'::text AS widget_item_sub_type
            , n.node_id
            , 1 AS value
          FROM
            node_list n
          WHERE
            n.is_managed IS TRUE
            AND n.is_am_supported IS FALSE
            AND NOT EXISTS(
              SELECT 1 FROM install_list install WHERE n.node_id = install.node_id
            )
            AND ('V3_INSTALL'::en_widget_item_type = ANY(i_widget_item_type))
            AND ('V3_INSTALL_NOT_SUPPORTED_SERVER' = ANY(i_widget_item_sub_type))
            GROUP BY n.node_id
        )
        , not_manage_list AS (  -- 미관리 리스트
          SELECT
            'V3_INSTALL'::en_widget_item_type AS widget_item_type
            , 'V3_NOT_MANAGE'::text AS widget_item_sub_type
            , n.node_id
            , 1 AS value
          FROM
            node_list n
          WHERE
            n.is_managed IS FALSE
            AND ('V3_INSTALL'::en_widget_item_type = ANY(i_widget_item_type))
            AND ('V3_NOT_MANAGE' = ANY(i_widget_item_sub_type))
            GROUP BY n.node_id
        )
        SELECT  -- 설치
          install.widget_item_type
          , install.widget_item_sub_type
          , install.node_id
          , install.value
        FROM
          install_list install
        UNION ALL
        SELECT  -- 미설치
          not_install.widget_item_type
          , not_install.widget_item_sub_type
          , not_install.node_id
          , not_install.value
        FROM
          not_install_list not_install
        UNION ALL
        SELECT  -- 미지원
          not_supported.widget_item_type
          , not_supported.widget_item_sub_type
          , not_supported.node_id
          , not_supported.value
        FROM
          not_supported_list not_supported
        UNION ALL
        SELECT  -- 미관리(1.0.5.1 추가, CWPP-2207)
          not_manage.widget_item_type
          , not_manage.widget_item_sub_type
          , not_manage.node_id
          , not_manage.value
        FROM
          not_manage_list not_manage
      ) org


      /* V3 정책 적용 현황 */
      UNION ALL
      SELECT
        org.widget_item_type AS widget_item_type
        , org.widget_item_sub_type AS widget_item_sub_type
        , org.node_id AS node_id
        , org.value AS value
        , org.std_group_key AS std_group_key
        , org.std_group_title AS std_group_title
      FROM (
        WITH manage_node_list AS (
          SELECT
            node.node_id AS node_id
          FROM
            tb_node node
            INNER JOIN tb_platform platform ON platform.platform_id = node.platform_id
              AND NOT (platform.platform_type = ANY(v_not_support_platform))
            LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = node.container_service_type
          WHERE
            node.is_removed IS FALSE
            AND ((v_all_target) OR (v_all_target = false AND node.node_id = ANY(v_node_id_array)))
            AND (node.machine_type != 'CONTAINER' OR node.machine_type = 'CONTAINER' AND tcp.is_amc_supported IS TRUE)
        )
        SELECT
          'V3_POLICY_STATUS'::en_widget_item_type AS widget_item_type
          , CONCAT('V3_POLICY_STATUS_',node_policy_status.policy_status) AS widget_item_sub_type
          , node.node_id AS node_id
          , 1 AS value
          , '' AS std_group_key
          , '' AS std_group_title
        FROM
          manage_node_list node
          INNER JOIN tb_product_info product_info ON product_info.node_id = node.node_id
            AND COALESCE(product_info.is_managed,TRUE) IS TRUE
          INNER JOIN tb_policy_status node_policy_status ON node_policy_status.node_id = node.node_id
          INNER JOIN (
            SELECT
              product.product_id
              , feature_map.product_feature_id
            FROM
              tb_product product
              INNER JOIN tb_product_feature_map feature_map ON feature_map.product_id = product.product_id
                AND feature_map.product_feature_id <> 'V3NET_LU_UPDATE'
            WHERE
              product.product_group = 'V3'
          ) product_feature ON product_feature.product_id = product_info.product_id
            AND product_feature.product_feature_id = node_policy_status.product_feature_id
      ) org
      WHERE
        ('V3_POLICY_STATUS'::en_widget_item_type = ANY(i_widget_item_type))
        AND (org.widget_item_sub_type = ANY(i_widget_item_sub_type))
        

      /* 최근 7일내 수동 검사율 */
      UNION ALL
      SELECT
        'MANUAL_SCAN_RATIO'::en_widget_item_type AS widget_item_type
        , org.widget_item_sub_type
        , org.node_id
        , org.value
        , '' AS std_group_key
        , '' AS std_group_title
      FROM(
        WITH target_node_list AS(
          SELECT
            n.node_id
            , pi.product_id
          FROM
            tb_node AS n
            JOIN tb_platform AS p ON n.platform_id = p.platform_id
              AND NOT (p.platform_type = ANY(v_not_support_platform))
              AND p.is_supported IS TRUE
              AND is_server IS TRUE
            JOIN tb_product_info AS pi ON pi.node_id = n.node_id AND COALESCE(pi.is_managed,TRUE) IS TRUE
            JOIN tb_product AS pd ON pd.product_id = pi.product_id AND pd.product_group = 'V3'
            LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = n.container_service_type
          WHERE
            n.is_removed IS FALSE
            AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
            AND ('MANUAL_SCAN_RATIO'::en_widget_item_type = ANY(i_widget_item_type))
            AND (n.machine_type != 'CONTAINER' OR n.machine_type = 'CONTAINER' AND tcp.is_amc_supported IS TRUE)
        ), scanned_node_list AS(
            SELECT
              v3s.node_id
              , 1 AS value
            FROM
              tb_v3_status v3s
              INNER JOIN target_node_list target ON target.node_id = v3s.node_id AND target.product_id = v3s.product_id
            WHERE 
              v3s.last_scan_time >= date_trunc('day', now()) - (v_manual_scan_threshold -1 || 'day')::INTERVAL
              AND ('MANUAL_SCAN_RATIO'::en_widget_item_type = ANY(i_widget_item_type))
        )
        SELECT
          'MANUAL_SCANNED_SERVER'::text AS widget_item_sub_type
          , data.node_id
          , 1 AS value
        FROM
          scanned_node_list AS data
        WHERE
          ('MANUAL_SCAN_RATIO'::en_widget_item_type = ANY(i_widget_item_type))
          AND ('MANUAL_SCANNED_SERVER'::text = ANY(i_widget_item_sub_type))
        UNION ALL
        SELECT
          'MANUAL_NOT_SCAN_SERVER'::text AS widget_item_sub_type
          , st.node_id
          , 1 AS value
        FROM
          target_node_list st
        WHERE
          NOT EXISTS(
              SELECT 1 FROM scanned_node_list snl WHERE st.node_id = snl.node_id
          )
          AND ('MANUAL_SCAN_RATIO'::en_widget_item_type = ANY(i_widget_item_type))
          AND ('MANUAL_NOT_SCAN_SERVER' = ANY(i_widget_item_sub_type))
      ) org



      /* 최신 엔진 업데이트율 */
      UNION ALL
      SELECT
        'ENGINE_UPDATE_RATIO'::en_widget_item_type
        , org.widget_item_sub_type
        , org.node_id
        , org.value
        , org.std_group_key
        , org.std_group_title
      FROM(
        WITH update_date_version_info AS(
          SELECT
            (CASE WHEN st.key = 'oes_engine_date' THEN 'OES'::en_engine_type ELSE 'SES'::en_engine_type END) AS key
            , COALESCE(config.value, st.value) AS value
          FROM
            UNNEST(
              ARRAY['oes_engine_date'::text, 'ses_engine_date'::text]
              , ARRAY['9999.12.31.00'::text, '9999.12.31.00'::text]
            )
          st(key, value)
          LEFT JOIN(
            SELECT
              c.key
              , c.value
            FROM
              tb_config AS c
            WHERE
              c.config_group = 'UPDATE_SERVICE' AND c.key IN('oes_engine_date', 'ses_engine_date')
          ) config ON st.key = config.key

        ), engine_update_threshold AS(
          SELECT st.config_group, COALESCE(config.value, st.value) AS value
          FROM
          (SELECT 'AGENT_THRESHOLD'::en_config_group AS config_group, 0 AS value) AS st
          LEFT JOIN(
            SELECT c.config_group, GREATEST(COALESCE(c.value, '0')::integer - 1, 0) AS value FROM tb_config AS c WHERE c.config_group = 'AGENT_THRESHOLD' AND c.key = 'engine_update_threshold'
          ) config ON st.config_group = config.config_group

        ), update_date_info AS(
          SELECT
            vi.key
            , TO_CHAR(SUBSTRING(vi.value, 1, 10)::timestamptz - (config.value || ' day')::interval, 'YYYY.MM.DD')::timestamptz AS update_date_time
          FROM
            update_date_version_info vi
            CROSS JOIN engine_update_threshold config

        )
        , node_list AS (  -- 대상 에이전트 리스트 가져오기
          SELECT
              node.node_id AS node_id
          FROM
              tb_node node
              INNER JOIN tb_platform platform ON platform.platform_id = node.platform_id
                AND platform.is_supported IS TRUE
                AND platform.is_server IS TRUE
                AND NOT (platform.platform_type = ANY(v_not_support_platform))
              INNER JOIN tb_product_info product_info ON product_info.node_id = node.node_id
                AND COALESCE(product_info.is_managed,TRUE) IS TRUE
              INNER JOIN tb_product product ON product.product_id = product_info.product_id
                  AND product.product_group = 'V3'
              LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = node.container_service_type
          WHERE
              node.is_removed IS FALSE
          AND (node.machine_type != 'CONTAINER' OR node.machine_type = 'CONTAINER' AND tcp.is_amc_supported IS TRUE)
        )
        , update_data AS (
            SELECT
            v3s.node_id
            , CASE v3s.engine_type
              WHEN 'SES' THEN v3s.engine_update_time >= (SELECT update_date_time FROM update_date_info WHERE "key" = 'SES')
              ELSE v3s.engine_update_time >= (SELECT update_date_time FROM update_date_info WHERE "key" = 'OES')
            END AS is_updated_engine
          FROM
            tb_v3_status v3s
            INNER JOIN node_list n ON n.node_id = v3s.node_id
          WHERE 
              v3s.engine_type IN('OES', 'SES')
              AND ((v_all_target) OR (v_all_target = false AND n.node_id = ANY(v_node_id_array)))
              AND ('ENGINE_UPDATE_RATIO'::en_widget_item_type = ANY(i_widget_item_type))
        )
        SELECT
          'ENGINE_UPDATED_SERVER'::text AS widget_item_sub_type
          , data.node_id
          , 1 AS value
          , ''::text AS std_group_key
          , ''::text AS std_group_title
        FROM
          update_data data
        WHERE
            data.is_updated_engine IS TRUE
            AND ('ENGINE_UPDATE_RATIO'::en_widget_item_type = ANY(i_widget_item_type))
          AND ('ENGINE_UPDATED_SERVER'::text = ANY(i_widget_item_sub_type))

        UNION ALL

        SELECT
          'ENGINE_NOT_UPDATE_SERVER'::text AS widget_item_sub_type
          , data.node_id
          , 1 AS value
          , ''::text AS std_group_key
          , ''::text AS std_group_title
        FROM
          update_data data
        WHERE
          data.is_updated_engine IS NOT TRUE
          AND ('ENGINE_UPDATE_RATIO'::en_widget_item_type = ANY(i_widget_item_type))
          AND ('ENGINE_NOT_UPDATE_SERVER'::text = ANY(i_widget_item_sub_type))

        UNION ALL

        SELECT
          'ENGINE_UPDATE_VERSION_OES'::text AS widget_item_sub_type
          , 0
          , 0
          , 'OES'::text AS std_group_key
          , uvi.value AS std_group_title
        FROM
          update_date_version_info uvi
        WHERE
          uvi.key = 'OES'
          AND ('ENGINE_UPDATE_RATIO'::en_widget_item_type = ANY(i_widget_item_type))
          AND ('ENGINE_UPDATE_VERSION_OES'::text = ANY(i_widget_item_sub_type))

        UNION ALL

        SELECT
          'ENGINE_UPDATE_VERSION_SES'::text AS widget_item_sub_type
          , 0
          , 0
          , 'SES'::text AS std_group_key
          , uvi.value AS std_group_title
        FROM
          update_date_version_info uvi
        WHERE
          uvi.key = 'SES'
          AND ('ENGINE_UPDATE_RATIO'::en_widget_item_type = ANY(i_widget_item_type))
          AND ('ENGINE_UPDATE_VERSION_SES'::text = ANY(i_widget_item_sub_type))
      ) org
      WHERE
        ('ENGINE_UPDATE_RATIO'::en_widget_item_type = ANY(i_widget_item_type))
        AND (org.widget_item_sub_type = ANY(i_widget_item_sub_type))



      /* 악성코드 감염 에이전트 순위  */
      UNION ALL
      SELECT
          data.widget_item_type
          , data.widget_item_sub_type
          , data.node_id
          , data.value
          , data.std_group_key
          , data.std_group_title
      FROM
          (
              WITH node_list AS (
                  SELECT
                      node.node_id
                      , node.computer_name AS name
                  FROM
                      tb_node node
                      INNER JOIN tb_platform platform ON platform.platform_id = node.platform_id
                          AND platform.is_supported IS TRUE
                          AND platform.is_server IS TRUE
                          AND NOT (platform.platform_type = ANY(v_not_support_platform))
                      INNER JOIN tb_product_info product_info ON product_info.node_id = node.node_id
                        AND COALESCE(product_info.is_managed,TRUE) IS TRUE
                      INNER JOIN tb_product product ON product.product_id = product_info.product_id
                        AND product.product_group = 'V3'
                      LEFT JOIN tb_user "user" ON "user".node_id = node.node_id
                      LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = node.container_service_type
                  WHERE
                      node.is_removed IS FALSE
                      AND ((v_all_target) OR (v_all_target = false AND node.node_id = ANY(v_node_id_array)))
                      AND (node.machine_type != 'CONTAINER' OR node.machine_type = 'CONTAINER' AND tcp.is_amc_supported IS TRUE)
              )
              SELECT
                  'AGENT_MALWARE'::en_widget_item_type AS widget_item_type
                  , 'AGENT_MALWARE_LAST_30_DAYS'::text AS widget_item_sub_type
                  , m.node_id
                  , m.count AS value
                  , m.ip AS std_group_key
                  , (JSON_BUILD_OBJECT(
                      'ip' , m.ip
                      , 'name' , COALESCE(node.name, '')
                      )::text) AS std_group_title
              FROM
                  (
                    SELECT
                        tvat.node_id AS node_id
                        , tvat.ip AS ip
                        , sum(tvat.count)::bigint AS count
                    FROM
                        tb_v3_alert_timeline tvat 
                    WHERE
                        tvat.reg_date BETWEEN (date_trunc('DAYS', NOW() - '29 DAYS'::interval)) AND NOW()
                    GROUP BY
                        tvat.node_id
                        , tvat.ip
                  ) AS m
                  INNER JOIN node_list node ON node.node_id = m.node_id
              WHERE
                  ('AGENT_MALWARE'::en_widget_item_type = ANY(i_widget_item_type))
                  AND ('AGENT_MALWARE_LAST_30_DAYS'::text = ANY(i_widget_item_sub_type))
              UNION ALL
              SELECT
                  'AGENT_MALWARE'::en_widget_item_type
                  , 'AGENT_MALWARE_LAST_7_DAYS'::text AS widget_item_sub_type
                  , m.node_id
                  , m.count AS value
                  , m.ip AS std_group_key
                  , (JSON_BUILD_OBJECT(
                      'ip' , m.ip
                      , 'name' , COALESCE(node.name, '')
                      )::text) AS std_group_title
              FROM
                  (
                    SELECT
                        tvat.node_id AS node_id
                        , tvat.ip AS ip
                        , sum(tvat.count)::bigint AS count
                    FROM
                        tb_v3_alert_timeline tvat 
                    WHERE
                        tvat.reg_date BETWEEN (date_trunc('DAYS', NOW() - '6 DAYS'::interval)) AND NOW()
                    GROUP BY
                        tvat.node_id
                        , tvat.ip
                  ) AS m
                  INNER JOIN node_list AS node ON node.node_id = m.node_id
              WHERE
                  ('AGENT_MALWARE'::en_widget_item_type = ANY(i_widget_item_type))
                  AND ('AGENT_MALWARE_LAST_7_DAYS'::text = ANY(i_widget_item_sub_type))
              UNION ALL
              SELECT
                  'AGENT_MALWARE'::en_widget_item_type
                  , 'AGENT_MALWARE_LAST_24HR'
                  , m.node_id
                  , m.count AS value
                  , m.ip AS std_group_key
                  , (JSON_BUILD_OBJECT(
                      'ip' , m.ip
                      , 'name' , COALESCE(node.name, '')
                      )::text) AS std_group_title
              FROM
                  (
                    SELECT
                        tvat.node_id AS node_id
                        , tvat.ip AS ip
                        , sum(tvat.count)::bigint AS count
                    FROM
                        tb_v3_alert_timeline tvat 
                    WHERE
                        tvat.reg_date BETWEEN (date_trunc('HOURS', NOW() - '23 HOURS'::interval)) AND NOW()
                    GROUP BY
                        tvat.node_id
                        , tvat.ip
                  ) AS m
                  INNER JOIN node_list node ON node.node_id = m.node_id
              WHERE
                  ('AGENT_MALWARE'::en_widget_item_type = ANY(i_widget_item_type))
                  AND ('AGENT_MALWARE_LAST_24HR'::text = ANY(i_widget_item_sub_type))
          ) AS data



      /* 악성코드 순위 */
      UNION ALL
      SELECT
        data.widget_item_type
        , data.widget_item_sub_type
        , data.node_id
        , data.value
        , data.std_group_key
        , data.std_group_title
      FROM (
        WITH node_list AS (
            SELECT
                node.node_id
                , "user".name
            FROM
                tb_node node
                INNER JOIN tb_platform platform ON platform.platform_id = node.platform_id
                    AND platform.is_supported IS TRUE
                    AND platform.is_server IS TRUE
                    AND NOT (platform.platform_type = ANY(v_not_support_platform))
                INNER JOIN tb_product_info product_info ON product_info.node_id = node.node_id
                  AND COALESCE(product_info.is_managed,TRUE) IS TRUE
                INNER JOIN tb_product product ON product.product_id = product_info.product_id
                  AND product.product_group = 'V3'
                LEFT JOIN tb_user "user" ON "user".node_id = node.node_id
                LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = node.container_service_type
            WHERE
                node.is_removed IS FALSE
                AND ((v_all_target) OR (v_all_target = false AND node.node_id = ANY(v_node_id_array)))
                AND (node.machine_type != 'CONTAINER' OR node.machine_type = 'CONTAINER' AND tcp.is_amc_supported IS TRUE)
        )
        SELECT
          'MALWARE_INFECTION'::en_widget_item_type AS widget_item_type
          , 'MALWARE_INFECTION_LAST_30_DAYS'::text AS widget_item_sub_type
          , m.node_id
          , m.count AS value
          , m.malware_name AS std_group_key
          , '' AS std_group_title
        FROM
            (
              SELECT
                  tvat.node_id AS node_id
                  , tvat.malware_name AS malware_name
                  , sum(tvat.count)::bigint AS count
              FROM
                  tb_v3_alert_timeline tvat 
              WHERE
                  tvat.reg_date BETWEEN (date_trunc('DAYS', NOW() - '29 DAYS'::interval)) AND NOW()
              GROUP BY
                  tvat.node_id
                  , tvat.malware_name
            ) AS m
          INNER JOIN node_list AS n ON m.node_id = n.node_id
        WHERE
          ('MALWARE_INFECTION'::en_widget_item_type = ANY(i_widget_item_type))
          AND ('MALWARE_INFECTION_LAST_30_DAYS'::text = ANY(i_widget_item_sub_type))
        UNION ALL
        SELECT
          'MALWARE_INFECTION'::en_widget_item_type AS widget_item_type
          , 'MALWARE_INFECTION_LAST_7_DAYS'::text AS widget_item_sub_type
          , m.node_id
          , m.count AS value
          , m.malware_name AS std_group_key
          , '' AS std_group_title
        FROM
            (
              SELECT
                  tvat.node_id AS node_id
                  , tvat.malware_name AS malware_name
                  , sum(tvat.count)::bigint AS count
              FROM
                  tb_v3_alert_timeline tvat 
              WHERE
                  tvat.reg_date BETWEEN (date_trunc('DAYS', NOW() - '6 DAYS'::interval)) AND NOW()
              GROUP BY
                  tvat.node_id
                  , tvat.malware_name
            ) AS m
          INNER JOIN node_list AS n ON m.node_id = n.node_id
        WHERE
          ('MALWARE_INFECTION'::en_widget_item_type = ANY(i_widget_item_type))
          AND ('MALWARE_INFECTION_LAST_7_DAYS'::text = ANY(i_widget_item_sub_type))
        UNION ALL
        SELECT
          'MALWARE_INFECTION'::en_widget_item_type AS widget_item_type
          , 'MALWARE_INFECTION_LAST_24HR'::text AS widget_item_sub_type
          , m.node_id
          , m.count AS value
          , m.malware_name AS std_group_key
          , '' AS std_group_title
        FROM
            (
              SELECT
                  tvat.node_id AS node_id
                  , tvat.malware_name AS malware_name
                  , sum(tvat.count)::bigint AS count
              FROM
                  tb_v3_alert_timeline tvat 
              WHERE
                  tvat.reg_date BETWEEN (date_trunc('HOURS', NOW() - '23 HOURS'::interval)) AND NOW()
              GROUP BY
                  tvat.node_id
                  , tvat.malware_name
            ) AS m
          JOIN node_list AS n ON m.node_id = n.node_id
        WHERE
          ('MALWARE_INFECTION'::en_widget_item_type = ANY(i_widget_item_type))
          AND ('MALWARE_INFECTION_LAST_24HR'::text = ANY(i_widget_item_sub_type))
      ) AS data
      

      /* 배포 엔진 적용 현황 */
      UNION ALL
      SELECT
        'V3_ENGINE_STATUS'::en_widget_item_type AS widget_item_type
        , org.widget_item_sub_type
        , 0 AS node_id
        , 0 AS value
        , org.reg_date AS std_group_key
        , org.std_group_title
      FROM
      (
        WITH engine_update_last30days AS(
          SELECT
            TO_CHAR(eu.modified_time, 'YYYYMMDD') AS reg_date
            , eu.engine_type
            , eu.engine_date AS engine_version
          FROM
            tb_engine_update eu
          WHERE
            eu.modified_time BETWEEN CURRENT_TIMESTAMP - '30 DAY'::interval AND CURRENT_TIMESTAMP
            AND ('V3_ENGINE_STATUS'::en_widget_item_type = ANY(i_widget_item_type))
            AND ('V3_ENGINE_STATUS_LAST_30_DAYS'::text = ANY(i_widget_item_sub_type))
        )
        , engine_update_last7days AS(
          SELECT
            TO_CHAR(eu.modified_time, 'YYYYMMDD') AS reg_date
            , eu.engine_type
            , eu.engine_date AS engine_version
          FROM
            tb_engine_update eu
          WHERE
            eu.modified_time BETWEEN CURRENT_TIMESTAMP - '7 DAY'::interval AND CURRENT_TIMESTAMP
            AND ('V3_ENGINE_STATUS'::en_widget_item_type = ANY(i_widget_item_type))
            AND ('V3_ENGINE_STATUS_LAST_7_DAYS'::text = ANY(i_widget_item_sub_type))
        )
        , engine_update_last24hr AS(
          SELECT
            TO_CHAR(eu.modified_time, 'YYYYMMDDHH24') AS reg_date
            , eu.engine_type
            , eu.engine_date AS engine_version
          FROM
            tb_engine_update eu
          WHERE
            eu.modified_time BETWEEN CURRENT_TIMESTAMP - '24 HOUR'::interval AND CURRENT_TIMESTAMP
            AND ('V3_ENGINE_STATUS'::en_widget_item_type = ANY(i_widget_item_type))
            AND ('V3_ENGINE_STATUS_LAST_24_HR'::text = ANY(i_widget_item_sub_type))
        )
        , node_list AS (  -- 에이전트 리스트
          SELECT
              node.node_id AS node_id
          FROM
              tb_node node
              INNER JOIN tb_platform platform ON platform.platform_id = node.platform_id
                  AND platform.is_supported IS TRUE
                  AND platform.is_server IS TRUE
                  AND NOT (platform.platform_type = ANY(v_not_support_platform))
              INNER JOIN tb_product_info product_info ON product_info.node_id = node.node_id
                AND COALESCE(product_info.is_managed,TRUE) IS TRUE
              INNER JOIN tb_product product ON product.product_id = product_info.product_id
                AND product.product_group = 'V3'
              LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = node.container_service_type
          WHERE
              node.is_removed IS FALSE
              AND ((v_all_target) OR (v_all_target = false AND node.node_id = ANY(v_node_id_array)))
              AND (node.machine_type != 'CONTAINER' OR node.machine_type = 'CONTAINER' AND tcp.is_amc_supported IS TRUE)
        )

        SELECT
          'V3_ENGINE_STATUS_LAST_30_DAYS' AS widget_item_sub_type
          , std_data.reg_date
          , JSON_BUILD_OBJECT(
            'reg_date', std_data.reg_date
            , 'value', COALESCE(node.value, 0)
            , 'engine_update_cnt', COALESCE(euc.value::integer, 0)
            , 'engine_update_type', COALESCE(STRING_AGG(euv.engine_type::text, '|'), '')
            , 'engine_update_date', COALESCE(STRING_AGG(euv.value::text, '|'), '')
          )::text AS std_group_title
        FROM(
        SELECT
          TO_CHAR(NOW()::timestamp without time zone - (29 - interval_val || ' DAYS')::INTERVAL, 'YYYYMMDD') AS reg_date
        FROM
          GENERATE_SERIES(0,29) interval_val
        ) std_data
        LEFT JOIN(
          SELECT
            timeline.reg_date
            , COUNT(1) AS value
          FROM
            tb_timeline_oltp timeline
            INNER JOIN node_list AS n ON timeline.node_id = n.node_id
          WHERE
            timeline.reg_date BETWEEN TO_CHAR(CURRENT_TIMESTAMP - '30 DAY'::interval, 'YYYYMMDD') AND TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDD')
            AND timeline.engine_update_past_days < v_engine_update_threshold
          GROUP BY
            timeline.reg_date
        ) node ON std_data.reg_date = node.reg_date
        LEFT JOIN(SELECT reg_date, COUNT(*)::text AS value FROM engine_update_last30days GROUP BY reg_date) euc ON std_data.reg_date = euc.reg_date
        LEFT JOIN(SELECT reg_date, engine_type, MAX(engine_version) AS value FROM engine_update_last30days GROUP BY reg_date, engine_type) euv ON std_data.reg_date = euv.reg_date
        WHERE
          ('V3_ENGINE_STATUS'::en_widget_item_type = ANY(i_widget_item_type))
          AND ('V3_ENGINE_STATUS_LAST_30_DAYS'::text = ANY(i_widget_item_sub_type))
        GROUP BY
          std_data.reg_date
          , node.value
          , euc.value

        UNION ALL
        SELECT
          'V3_ENGINE_STATUS_LAST_7_DAYS' AS widget_item_sub_type
          , std_data.reg_date
          , JSON_BUILD_OBJECT(
            'reg_date', std_data.reg_date
            , 'value', COALESCE(node.value, 0)
            , 'engine_update_cnt', COALESCE(euc.value::integer, 0)
            , 'engine_update_type', COALESCE(STRING_AGG(euv.engine_type::text, '|'), '')
            , 'engine_update_date', COALESCE(STRING_AGG(euv.value::text, '|'), '')
          )::text AS std_group_title
        FROM(
        SELECT
          TO_CHAR(NOW()::timestamp without time zone - (6 - interval_val || ' DAYS')::INTERVAL, 'YYYYMMDD') AS reg_date
        FROM
          GENERATE_SERIES(0,6) interval_val
        ) std_data
        LEFT JOIN(
          SELECT
            timeline.reg_date
            , COUNT(1) AS value
          FROM
            tb_timeline_oltp timeline
            INNER JOIN node_list AS n ON timeline.node_id = n.node_id
          WHERE
            timeline.reg_date BETWEEN TO_CHAR(CURRENT_TIMESTAMP - '7 DAY'::interval, 'YYYYMMDD') AND TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDD')
            AND timeline.engine_update_past_days < v_engine_update_threshold
          GROUP BY
            timeline.reg_date
        ) node ON std_data.reg_date = node.reg_date
        LEFT JOIN(SELECT reg_date, COUNT(*)::text AS value FROM engine_update_last7days GROUP BY reg_date) euc ON std_data.reg_date = euc.reg_date
        LEFT JOIN(SELECT reg_date, engine_type, MAX(engine_version) AS value FROM engine_update_last7days GROUP BY reg_date, engine_type) euv ON std_data.reg_date = euv.reg_date
        WHERE
          ('V3_ENGINE_STATUS'::en_widget_item_type = ANY(i_widget_item_type))
          AND ('V3_ENGINE_STATUS_LAST_7_DAYS'::text = ANY(i_widget_item_sub_type))
        GROUP BY
          std_data.reg_date
          , node.value
          , euc.value

        UNION ALL
        SELECT
          'V3_ENGINE_STATUS_LAST_24_HR' AS widget_item_sub_type
          , std_data.reg_date
          , JSON_BUILD_OBJECT(
            'reg_date', std_data.reg_date
            , 'value', COALESCE(node.value, 0)
            , 'engine_update_cnt', COALESCE(euc.value::integer, 0)
            , 'engine_update_type', COALESCE(STRING_AGG(euv.engine_type::text, '|'), '')
            , 'engine_update_date', COALESCE(STRING_AGG(euv.value::text, '|'), '')
          )::text AS std_group_title
        FROM(
        SELECT
          TO_CHAR(NOW()::timestamp without time zone - (23 - interval_val || ' HOUR')::INTERVAL, 'YYYYMMDDHH24') AS reg_date
        FROM
          GENERATE_SERIES(0,23) interval_val
        ) std_data
        LEFT JOIN(
          SELECT
            timeline.reg_date
            , COUNT(1) AS value
          FROM
            tb_v3_update_hourly_timeline timeline
            INNER JOIN node_list AS n ON timeline.node_id = n.node_id
          WHERE
            timeline.reg_date BETWEEN TO_CHAR(CURRENT_TIMESTAMP - '24 HOUR'::interval, 'YYYYMMDDHH24') AND TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24')
            AND timeline.engine_update_past_days < v_engine_update_threshold
          GROUP BY
            timeline.reg_date
        ) node ON std_data.reg_date = node.reg_date
        LEFT JOIN(SELECT reg_date, COUNT(*)::text AS value FROM engine_update_last24hr GROUP BY reg_date) euc ON std_data.reg_date = euc.reg_date
        LEFT JOIN(SELECT reg_date, engine_type, MAX(engine_version) AS value FROM engine_update_last24hr GROUP BY reg_date, engine_type) euv ON std_data.reg_date = euv.reg_date
        WHERE
          ('V3_ENGINE_STATUS'::en_widget_item_type = ANY(i_widget_item_type))
          AND ('V3_ENGINE_STATUS_LAST_24_HR'::text = ANY(i_widget_item_sub_type))
        GROUP BY
          std_data.reg_date
          , node.value
          , euc.value

      ) org


      /* 악성코드 및 평판 기반 탐지 추이 */
      UNION ALL
      SELECT
        data.widget_item_type
        , data.widget_item_sub_type
        , data.node_id
        , data.value
        , data.std_group_key
        , data.std_group_title
      FROM (
        WITH node_list AS (
          SELECT
            node.node_id
          FROM
            tb_node node
            INNER JOIN tb_platform platform ON platform.platform_id = node.platform_id
                AND platform.is_supported IS TRUE
                AND platform.is_server IS TRUE
                AND NOT (platform.platform_type = ANY(v_not_support_platform))
            INNER JOIN tb_product_info product_info ON product_info.node_id = node.node_id
                AND COALESCE(product_info.is_managed,TRUE) IS TRUE
            INNER JOIN tb_product product ON product.product_id = product_info.product_id
                AND product.product_group = 'V3'
            LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = node.container_service_type
          WHERE
            node.is_removed IS FALSE
            AND ((v_all_target) OR (v_all_target = false AND node.node_id = ANY(v_node_id_array)))
            AND (node.machine_type != 'CONTAINER' OR node.machine_type = 'CONTAINER' AND tcp.is_amc_supported IS TRUE)
        )
        SELECT
          'V3_MALWARE_HISTORY'::en_widget_item_type AS widget_item_type
          , 'V3_MALWARE_HISTORY_LAST_30_DAYS' AS widget_item_sub_type
          , COALESCE(timeline.node_id, 0) AS node_id
          , 0 AS value
          , std_data.reg_date AS std_group_key
          , JSON_BUILD_OBJECT(
              'detect_count', COALESCE(timeline.detect_count, 0)
          )::text AS std_group_title
        FROM
          (SELECT
            TO_CHAR(NOW()::timestamp without time zone - (29 - interval_hour || ' DAYS')::INTERVAL, 'YYYYMMDD') AS reg_date
          FROM
            GENERATE_SERIES(0,29) interval_hour
          ) std_data
          LEFT JOIN(
            SELECT
              timeline.reg_date
              , timeline.node_id
              , COALESCE(timeline.malware_clean_count, 0) + COALESCE(timeline.malware_clean_fail_count, 0) AS detect_count
            FROM
              tb_timeline_v3 timeline
              INNER JOIN node_list n ON timeline.node_id = n.node_id
            WHERE
              COALESCE(timeline.malware_clean_count, 0) + COALESCE(timeline.malware_clean_fail_count, 0) > 0
          ) timeline ON std_data.reg_date = timeline.reg_date
        WHERE
          ('V3_MALWARE_HISTORY'::en_widget_item_type = ANY(i_widget_item_type))
          AND ('V3_MALWARE_HISTORY_LAST_30_DAYS' = ANY(i_widget_item_sub_type))

        UNION ALL
        SELECT
          'V3_MALWARE_HISTORY'::en_widget_item_type AS widget_item_type
          , 'V3_MALWARE_HISTORY_LAST_7_DAYS' AS widget_item_sub_type
          , COALESCE(timeline.node_id, 0) AS node_id
          , 0 AS value
          , std_data.reg_date AS std_group_key
          , JSON_BUILD_OBJECT(
              'detect_count', COALESCE(timeline.detect_count, 0)
          )::text AS std_group_title
        FROM
          (SELECT
            TO_CHAR(NOW()::timestamp without time zone - (6 - interval_hour || ' DAYS')::INTERVAL, 'YYYYMMDD') AS reg_date
          FROM
            GENERATE_SERIES(0,6) interval_hour
          ) std_data
          LEFT JOIN(
            SELECT
              timeline.reg_date
              , timeline.node_id
              , COALESCE(timeline.malware_clean_count, 0) + COALESCE(timeline.malware_clean_fail_count, 0) AS detect_count
            FROM
              tb_timeline_v3 timeline
              INNER JOIN node_list n ON timeline.node_id = n.node_id
            WHERE
              COALESCE(timeline.malware_clean_count, 0) + COALESCE(timeline.malware_clean_fail_count, 0) > 0
              AND timeline.reg_date > TO_CHAR((CURRENT_TIMESTAMP - '7 DAY'::interval), 'YYYYMMDD')
          ) timeline ON std_data.reg_date = timeline.reg_date
        WHERE
          ('V3_MALWARE_HISTORY'::en_widget_item_type = ANY(i_widget_item_type))
          AND ('V3_MALWARE_HISTORY_LAST_7_DAYS' = ANY(i_widget_item_sub_type))

        UNION ALL
        SELECT
          'V3_MALWARE_HISTORY'::en_widget_item_type AS widget_item_type
          , 'V3_MALWARE_HISTORY_LAST_24_HR' AS widget_item_sub_type
          , COALESCE(timeline.node_id, 0) AS node_id
          , 0 AS value
          , std_data.reg_date AS std_group_key
          , JSON_BUILD_OBJECT(
              'detect_count', COALESCE(timeline.detect_count, 0)
          )::text AS std_group_title
        FROM
          (SELECT
            TO_CHAR(NOW()::timestamp without time zone - (23 - interval_hour || ' HOUR')::INTERVAL, 'YYYYMMDDHH24') AS reg_date
          FROM
            GENERATE_SERIES(0,23) interval_hour
          ) std_data
          LEFT JOIN(
            SELECT
              timeline.reg_date
              , timeline.node_id
              , COALESCE(timeline.malware_clean_count, 0) + COALESCE(timeline.malware_clean_fail_count, 0) AS detect_count
            FROM
              tb_hourly_timeline timeline
              INNER JOIN node_list n ON timeline.node_id = n.node_id
            WHERE
              COALESCE(timeline.malware_clean_count, 0) + COALESCE(timeline.malware_clean_fail_count, 0) > 0
          ) timeline ON std_data.reg_date = timeline.reg_date
        WHERE
          ('V3_MALWARE_HISTORY'::en_widget_item_type = ANY(i_widget_item_type))
          AND ('V3_MALWARE_HISTORY_LAST_24_HR' = ANY(i_widget_item_sub_type))
      ) AS data
      ;
  ELSE
    RETURN QUERY
      SELECT NULL::en_widget_item_type, NULL::text, NULL::bigint, NULL::bigint, NULL::text, NULL::text;
  END IF;

END;
$$;


ALTER FUNCTION public.sp_get_custom_dashboard_v3_link_node_list(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_custom_dashboard_v3_link_node_list(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_custom_dashboard_v3_link_node_list(i_widget_item_type public.en_widget_item_type[], i_widget_item_sub_type text[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text) IS '
@brief [] - 제품별 및 커스텀 대시보드 > V3 노드 리스트
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_custom_dashboard_widget(public.en_widget_item_type[], bigint, bigint, public.en_language, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_custom_dashboard_widget(i_widget_item_type public.en_widget_item_type[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text, i_admin_id text) RETURNS TABLE(link_type text, widget_item_type public.en_widget_item_type, widget_item_sub_type text, response_values text)
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_product_group_type en_product_group_type[];
  v_widget_item_sub_type text[];
  v_node_id_arr bigint[];

BEGIN

	WITH RECURSIVE v_group_id (group_id, pgroup_id) AS 
	(
		SELECT tg.group_id
			    ,tg.pgroup_id
		FROM (
          SELECT tg.group_id
              ,tg.pgroup_id
          FROM tb_group tg
          WHERE tg.is_removed = FALSE
            AND tg.group_id IN ( 
                                    SELECT unnest(string_to_array(ta.admin_group,',')::bigint[]) AS group_id
                                    FROM tb_admin ta
                                    WHERE ta.admin_id = i_admin_id
                                )
			    ) tg
		UNION DISTINCT
		SELECT tg.group_id
			    ,tg.pgroup_id
		FROM tb_group tg 
			INNER JOIN v_group_id vgi
				ON vgi.group_id = tg.pgroup_id
		WHERE tg.is_removed = FALSE
	)
	SELECT ARRAY_AGG(n.node_id) AS node_id
  INTO
    v_node_id_arr
	FROM tb_node n
	WHERE n.is_removed = FALSE
		AND n.group_id = ANY(SELECT vgi.group_id FROM v_group_id vgi);

  SELECT
    ARRAY_AGG(DISTINCT wit.product_group)
    , ARRAY_AGG(wit.widget_item_sub_type)
  INTO
    v_product_group_type
    , v_widget_item_sub_type
  FROM
    tb_widget_item_type wit
  WHERE
    wit.widget_item_type = ANY(i_widget_item_type)
  ;


  RETURN QUERY
  SELECT org.link_type, org.widget_item_type, org.widget_item_sub_type, org.response_values FROM(
  SELECT
    data.link_type, data.widget_item_type, data.widget_item_sub_type, sp_base64_encode(data.response_values) AS response_values, data.ord_num
  FROM
    sp_get_custom_dashboard_epp(i_widget_item_type, v_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth, v_node_id_arr) data
  WHERE
    'EMS'::en_product_group_type = ANY(v_product_group_type)
    AND data.response_values IS NOT NULL


  UNION ALL
  SELECT
    data.link_type, data.widget_item_type, data.widget_item_sub_type, sp_base64_encode(data.response_values) AS response_values, data.ord_num
  FROM
    sp_get_custom_dashboard_ac(i_widget_item_type, v_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth, v_node_id_arr) data
  WHERE
    'AC'::en_product_group_type = ANY(v_product_group_type)
    AND data.response_values IS NOT null


  UNION ALL
  SELECT
    data.link_type, data.widget_item_type, data.widget_item_sub_type, sp_base64_encode(data.response_values) AS response_values, data.ord_num
  FROM
    sp_get_custom_dashboard_hips(i_widget_item_type, v_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth, v_node_id_arr) data
  WHERE
    'HIPS'::en_product_group_type = ANY(v_product_group_type)
    AND data.response_values IS NOT null


  UNION ALL
  SELECT
    data.link_type, data.widget_item_type, data.widget_item_sub_type, sp_base64_encode(data.response_values) AS response_values, data.ord_num
  FROM
    sp_get_custom_dashboard_v3(i_widget_item_type, v_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth, v_node_id_arr) data
  WHERE
    'V3'::en_product_group_type = ANY(v_product_group_type)
    AND data.response_values IS NOT NULL

  UNION ALL
  SELECT
    data.link_type, data.widget_item_type, data.widget_item_sub_type, sp_base64_encode(data.response_values) AS response_values, data.ord_num
  FROM
    sp_get_custom_dashboard_scm(i_widget_item_type, v_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth, v_node_id_arr) data
  WHERE
    'SCM'::en_product_group_type = ANY(v_product_group_type)
    AND data.response_values IS NOT null
  ) org
  ORDER BY org.widget_item_type, org.widget_item_sub_type, org.ord_num
  ;


END;
$$;


ALTER FUNCTION public.sp_get_custom_dashboard_widget(i_widget_item_type public.en_widget_item_type[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text, i_admin_id text) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_custom_dashboard_widget(i_widget_item_type public.en_widget_item_type[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text, i_admin_id text); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_custom_dashboard_widget(i_widget_item_type public.en_widget_item_type[], i_group_id bigint, i_correlation_rule_id bigint, i_language public.en_language, i_product_auth text, i_admin_id text) IS '
@brief [SWD-SCI1051] - 제품별 및 커스텀 대시보드 > 제품별 및 사용자 정의 대시보드 조회
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_custom_dashboard_widget_link_node_list(bigint, bigint, text[], public.en_language, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_custom_dashboard_widget_link_node_list(i_group_id bigint, i_correlation_rule_id bigint, i_widget_item_sub_type text[], i_language public.en_language, i_product_auth text) RETURNS TABLE(node_id bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_product_group_type en_product_group_type[];
  v_widget_item_type en_widget_item_type[];

BEGIN

  SELECT
    ARRAY_AGG(DISTINCT wit.product_group)
    , ARRAY_AGG(wit.widget_item_type)
  INTO
    v_product_group_type
    , v_widget_item_type
  FROM
    tb_widget_item_type wit
  WHERE
    wit.widget_item_sub_type = ANY(i_widget_item_sub_type)
  ;


  RETURN QUERY
  SELECT DISTINCT org.node_id FROM(

    SELECT
      data.node_id
    FROM
      sp_get_custom_dashboard_epp_link_node_list(v_widget_item_type, i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      'EMS'::en_product_group_type = ANY(v_product_group_type)


    UNION ALL
    SELECT
      data.node_id
    FROM
      sp_get_custom_dashboard_v3_link_node_list(v_widget_item_type, i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      'V3'::en_product_group_type = ANY(v_product_group_type)

	UNION ALL
    SELECT
      data.node_id
    FROM
      sp_get_custom_dashboard_ac_link_node_list(v_widget_item_type, i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      'AC'::en_product_group_type = ANY(v_product_group_type)

	UNION ALL
    SELECT
      data.node_id
    FROM
      sp_get_custom_dashboard_hips_link_node_list(v_widget_item_type, i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      'HIPS'::en_product_group_type = ANY(v_product_group_type)
      
	UNION ALL
    SELECT
      data.node_id
    FROM
      sp_get_custom_dashboard_scm_link_node_list(v_widget_item_type, i_widget_item_sub_type, i_group_id, i_correlation_rule_id, i_language, i_product_auth) data
    WHERE
      'SCM'::en_product_group_type = ANY(v_product_group_type)
  ) org
  WHERE org.node_id > 0
  ;


END;
$$;


ALTER FUNCTION public.sp_get_custom_dashboard_widget_link_node_list(i_group_id bigint, i_correlation_rule_id bigint, i_widget_item_sub_type text[], i_language public.en_language, i_product_auth text) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_custom_dashboard_widget_link_node_list(i_group_id bigint, i_correlation_rule_id bigint, i_widget_item_sub_type text[], i_language public.en_language, i_product_auth text); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_custom_dashboard_widget_link_node_list(i_group_id bigint, i_correlation_rule_id bigint, i_widget_item_sub_type text[], i_language public.en_language, i_product_auth text) IS '
@brief [] - 제품별 및 커스텀 대시보드 > 상세 node list
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_dashboard_layout(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_dashboard_layout(i_admin_id text) RETURNS TABLE(layout text)
    LANGUAGE plpgsql
    AS $$
BEGIN

  RETURN QUERY
  SELECT a.dashboard_layout
  FROM tb_admin a
  WHERE a.admin_id = i_admin_id
      ;
END;
$$;


ALTER FUNCTION public.sp_get_dashboard_layout(i_admin_id text) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_dashboard_layout(i_admin_id text); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_dashboard_layout(i_admin_id text) IS '
@brief 대시보드 layout 조회
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_dashboard_link_node_list(text, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_dashboard_link_node_list(i_link_type text, i_product_auth text, i_dashboard_layout text) RETURNS TABLE(node_id bigint[])
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_node_id                   bigint[];
  v_connection_status         en_connection_status;
  v_dashboard_layout          TEXT[];
BEGIN

  -- dashboard layout
  IF i_dashboard_layout = 'null' OR i_dashboard_layout IS NULL THEN
    SELECT string_to_array('v3_not_install,v3_not_new_engine,not_manual_scan,realtime_scan_off,v3_policy_not_applied,malware_scan_30_days,v3_license_expired,v3_abnormal_integrity,ac_not_install,ac_license_expired,ac_abnormal_integrity,ac_policy_not_applied,im_policy_not_applied,im_manual_rulecheck_not_execute,hips_not_install,hips_license_expired,hips_abnormal_integrity,hips_policy_not_applied,scm_not_install,scm_license_expired,scm_abnormal_integrity,scm_policy_not_applied,scm_manual_scan_not_execute', ',') INTO v_dashboard_layout;
  ELSE
    SELECT string_to_array(i_dashboard_layout, ',') INTO v_dashboard_layout;
  END IF;

  -- 에이전트 연결 상태
  IF i_link_type IN ('AGENT_CONNECTED', 'AGENT_DISCONNECTED','AGENT_STATUS_NOT_INSTALL') THEN

    IF i_link_type = 'AGENT_CONNECTED' THEN
      v_connection_status = 'CONNECTED';
    ELSIF i_link_type = 'AGENT_DISCONNECTED' THEN
      v_connection_status = 'DISCONNECTED';
    ELSIF i_link_type = 'AGENT_STATUS_NOT_INSTALL' THEN
      v_connection_status = 'UNINSTALLED';
    END IF;

    SELECT ARRAY_AGG(n.node_id) INTO v_node_id
    FROM tb_node AS n
    LEFT JOIN tb_node_status AS ns ON n.node_id = ns.node_id
    WHERE n.is_removed = false
    AND COALESCE(ns.connection_status, 'UNINSTALLED') = v_connection_status;

  ELSIF i_link_type = 'V3_NOT_INSTALL_SERVER' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE iand.v3_not_install_server IS TRUE;

  ELSIF i_link_type = 'V3_NOT_INSTALL_DESKTOP' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE iand.v3_not_install_desktop IS TRUE;

  ELSIF i_link_type = 'V3_NOT_INSTALL_ALL' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE iand.v3_not_install_server IS TRUE OR iand.v3_not_install_desktop IS TRUE;

  -- 에이전트 데스크탑 / 서버
  ELSIF i_link_type = 'V3_NOT_NEW_ENGINE' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE iand.v3_not_new_engine IS TRUE;

  -- 최근 수동 검사 미실행
  ELSIF i_link_type = 'NOT_MANUAL_SCAN' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE iand.not_manual_scan IS TRUE;

  -- 실시간 검사 off
  ELSIF i_link_type = 'REALTIME_SCAN_OFF' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE iand.realtime_scan_off IS TRUE;

  -- V3 정책 미적용
  ELSIF i_link_type = 'V3_POLICY_NOT_APPLIED' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE iand.v3_policy_not_applied IS TRUE;

  -- 악성코드 탐지 (최근 30일)
  ELSIF i_link_type = 'MALWARE_SCAN_30_DAYS' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE iand.malware_scan_30_days IS TRUE;

  -- V3 라이선스 만료
  ELSIF i_link_type = 'V3_LICENSE_EXPIRED' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE iand.v3_license_expired IS TRUE;

  -- V3 무결성 손상
  ELSIF i_link_type = 'V3_ABNORMAL_INTEGRITY' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE iand.v3_abnormal_integrity IS TRUE;

  -- AC 미설치
  ELSIF i_link_type = 'AC_NOT_INSTALL' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE iand.ac_not_install IS TRUE;

  -- AC 라이선스 만료
  ELSIF i_link_type = 'AC_LICENSE_EXPIRED' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE iand.ac_license_expired IS TRUE;

  -- AC 무결성 손상
  ELSIF i_link_type = 'AC_ABNORMAL_INTEGRITY' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE iand.ac_abnormal_integrity IS TRUE;

  -- AC 정책 미적용
  ELSIF i_link_type = 'AC_POLICY_NOT_APPLIED' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE iand.ac_policy_not_applied IS TRUE;

  -- IM 정책 미적용
  ELSIF i_link_type = 'IM_POLICY_NOT_APPLIED' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE iand.im_policy_not_applied IS TRUE;
    
  -- IM 무결성모니터링 수동검사 미실행
  ELSIF i_link_type = 'IM_MANUAL_RULECHECK_NOT_EXECUTE' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE iand.im_manual_rulecheck_not_execute IS TRUE;

  -- HIPS 미설치
  ELSIF i_link_type = 'HIPS_NOT_INSTALL' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE iand.hips_not_install IS TRUE;

  -- HIPS 라이선스 만료
  ELSIF i_link_type = 'HIPS_LICENSE_EXPIRED' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE iand.hips_license_expired IS TRUE;

  -- HIPS 무결성 손상
  ELSIF i_link_type = 'HIPS_ABNORMAL_INTEGRITY' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE iand.hips_abnormal_integrity IS TRUE;

  -- HIPS 정책 미적용
  ELSIF i_link_type = 'HIPS_POLICY_NOT_APPLIED' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE iand.hips_policy_not_applied IS TRUE;

  -- SCM 미설치
  ELSIF i_link_type = 'SCM_NOT_INSTALL' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE iand.scm_not_install IS TRUE;

  -- SCM 라이선스 만료
  ELSIF i_link_type = 'SCM_LICENSE_EXPIRED' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE iand.scm_license_expired IS TRUE;

  -- SCM 무결성 손상
  ELSIF i_link_type = 'SCM_ABNORMAL_INTEGRITY' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE iand.scm_abnormal_integrity IS TRUE;

  -- SCM 정책 미적용
  ELSIF i_link_type = 'SCM_POLICY_NOT_APPLIED' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE iand.scm_policy_not_applied IS TRUE;
    
  -- SCM 수동검사 미수행
  ELSIF i_link_type = 'SCM_MANUAL_SCAN_NOT_EXECUTE' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE iand.scm_manual_scan_not_execute IS TRUE;

  -- 이슈 발생
  ELSIF i_link_type IN ('ISSUE_AGENT_ALL', 'NORMAL_AGENT') THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE (
            (iand.v3_not_install_server IS TRUE AND 'v3_not_install' = ANY(v_dashboard_layout))
         OR (iand.v3_not_install_desktop IS TRUE AND 'v3_not_install' = ANY(v_dashboard_layout))
         OR (iand.v3_not_new_engine IS TRUE AND 'v3_not_new_engine' = ANY(v_dashboard_layout))
         OR (iand.not_manual_scan IS TRUE AND 'not_manual_scan' = ANY(v_dashboard_layout))
         OR (iand.realtime_scan_off IS TRUE AND 'realtime_scan_off' = ANY(v_dashboard_layout))
         OR (iand.v3_policy_not_applied IS TRUE AND 'v3_policy_not_applied' = ANY(v_dashboard_layout))
         OR (iand.malware_scan_30_days IS TRUE AND 'malware_scan_30_days' = ANY(v_dashboard_layout))
         OR (iand.v3_license_expired IS TRUE AND 'v3_license_expired' = ANY(v_dashboard_layout))
         OR (iand.v3_abnormal_integrity IS TRUE AND 'v3_abnormal_integrity' = ANY(v_dashboard_layout))
         OR (iand.ac_not_install IS TRUE AND 'ac_not_install' = ANY(v_dashboard_layout))
         OR (iand.ac_license_expired IS TRUE AND 'ac_license_expired' = ANY(v_dashboard_layout))
         OR (iand.ac_abnormal_integrity IS TRUE AND 'ac_abnormal_integrity' = ANY(v_dashboard_layout))
         OR (iand.ac_policy_not_applied IS TRUE AND 'ac_policy_not_applied' = ANY(v_dashboard_layout))
         OR (iand.im_policy_not_applied IS TRUE AND 'im_policy_not_applied' = ANY(v_dashboard_layout))
         OR (iand.im_manual_rulecheck_not_execute IS TRUE AND 'im_manual_rulecheck_not_execute' = ANY(v_dashboard_layout))
         OR (iand.hips_not_install IS TRUE AND 'hips_not_install' = ANY(v_dashboard_layout))
         OR (iand.hips_license_expired IS TRUE AND 'hips_license_expired' = ANY(v_dashboard_layout))
         OR (iand.hips_abnormal_integrity IS TRUE AND 'hips_abnormal_integrity' = ANY(v_dashboard_layout))
         OR (iand.hips_policy_not_applied IS TRUE AND 'hips_policy_not_applied' = ANY(v_dashboard_layout))
         OR (iand.scm_not_install IS TRUE AND 'scm_not_install' = ANY(v_dashboard_layout))
         OR (iand.scm_license_expired IS TRUE AND 'scm_license_expired' = ANY(v_dashboard_layout))
         OR (iand.scm_abnormal_integrity IS TRUE AND 'scm_abnormal_integrity' = ANY(v_dashboard_layout))
         OR (iand.scm_policy_not_applied IS TRUE AND 'scm_policy_not_applied' = ANY(v_dashboard_layout))
         OR (iand.scm_manual_scan_not_execute IS TRUE AND 'scm_manual_scan_not_execute' = ANY(v_dashboard_layout))
           );
  -- 정상 에이전트
    IF i_link_type = 'NORMAL_AGENT' THEN
      SELECT ARRAY_AGG(n.node_id) INTO v_node_id
        FROM tb_node AS n
         WHERE NOT EXISTS(
           SELECT 1 FROM (SELECT unnest(v_node_id) AS node_id) t  WHERE t.node_id = n.node_id
         )
           AND n.is_removed IS FALSE;
    END IF;

  -- 라이선스 만료
  ELSIF i_link_type = 'LICENSE_EXPIRED' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE ((iand.v3_license_expired IS TRUE AND 'v3_license_expired' = ANY(v_dashboard_layout))
        OR (iand.ac_license_expired IS TRUE AND 'ac_license_expired' = ANY(v_dashboard_layout))
        OR (iand.hips_license_expired IS TRUE AND 'hips_license_expired' = ANY(v_dashboard_layout))
        OR (iand.scm_license_expired IS TRUE AND 'scm_license_expired' = ANY(v_dashboard_layout))
        );

  -- 무결성 손상
  ELSIF i_link_type = 'ABNORMAL_INTEGRITY' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE (  (iand.v3_abnormal_integrity IS TRUE AND 'v3_abnormal_integrity' = ANY(v_dashboard_layout))
          OR (iand.ac_abnormal_integrity IS TRUE AND 'ac_abnormal_integrity' = ANY(v_dashboard_layout))
          OR (iand.hips_abnormal_integrity IS TRUE AND 'hips_abnormal_integrity' = ANY(v_dashboard_layout))
          OR (iand.scm_abnormal_integrity IS TRUE AND 'scm_abnormal_integrity' = ANY(v_dashboard_layout))
          );

  -- 정책 미적용
  ELSIF i_link_type = 'POLICY_NOT_APPLIED' THEN

    SELECT ARRAY_AGG(iand.node_id) INTO v_node_id
    FROM sp_get_issue_agent_node_data(i_product_auth) AS iand
    WHERE ((iand.v3_policy_not_applied IS TRUE AND 'v3_policy_not_applied' = ANY(v_dashboard_layout))
        OR (iand.ac_policy_not_applied IS TRUE AND 'ac_policy_not_applied' = ANY(v_dashboard_layout))
        OR (iand.im_policy_not_applied IS TRUE AND 'im_policy_not_applied' = ANY(v_dashboard_layout))
        OR (iand.hips_policy_not_applied IS TRUE AND 'hips_policy_not_applied' = ANY(v_dashboard_layout))
        OR (iand.scm_policy_not_applied IS TRUE AND 'scm_policy_not_applied' = ANY(v_dashboard_layout))
        );

  END IF;


  RETURN QUERY
    SELECT v_node_id;

END;
$$;


