--
-- Name: sp_get_db_mgmt(public.en_db_mgmt_type, public.en_db_type, character varying); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_db_mgmt(i_db_mgmt_type public.en_db_mgmt_type, i_db_type public.en_db_type, i_server_ip character varying) RETURNS TABLE(mgmt_time timestamp without time zone, file_path text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_server_id bigint;
BEGIN
  select server_id into v_server_id from tb_server where tb_server.ip = i_server_ip;

  IF( v_server_id IS NOT NULL ) THEN
    IF( i_db_mgmt_type = 'BACKUP' ) THEN
      RETURN QUERY
      SELECT tb_db_mgmt.mgmt_time, tb_db_mgmt.file_path FROM tb_db_mgmt where db_mgmt_type = 'BACKUP' and db_type = i_db_type and server_id = v_server_id;
    END IF;
  END IF;

END;
$$;


ALTER FUNCTION public.sp_get_db_mgmt(i_db_mgmt_type public.en_db_mgmt_type, i_db_type public.en_db_type, i_server_ip character varying) OWNER TO cppoltp;

--
-- Name: sp_get_db_mgmt_list(public.en_db_mgmt_type, inet, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_db_mgmt_list(i_db_mgmt_type public.en_db_mgmt_type, i_ip_connected inet, i_host_url text) RETURNS TABLE(db_type public.en_db_type, mgmt_time text, server_id text, ip text, port text, file_path text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
      SELECT
        d.db_type
        , d.mgmt_time::text
        , d.server_id::text
        , i_host_url AS ip
        , sp.port::text
        , d.file_path
      FROM tb_db_mgmt AS d
      LEFT JOIN tb_server AS s ON d.server_id = s.server_id
      CROSS JOIN tb_service_port AS sp
      WHERE EXISTS (
          SELECT 1
          FROM (
            SELECT dm.db_mgmt_type, dm.db_type, dm.mgmt_time, ROW_NUMBER() OVER(PARTITION BY dm.db_mgmt_type, dm.db_type ORDER BY dm.mgmt_time DESC) AS row_num
            FROM tb_db_mgmt AS dm
            WHERE dm.db_mgmt_type = i_db_mgmt_type
          ) AS dm
          WHERE dm.db_mgmt_type = d.db_mgmt_type AND dm.db_type = d.db_type AND dm.mgmt_time = d.mgmt_time AND dm.row_num = 1
        )
        AND sp.service_type = 'FILESERVER-HTTPS';

END;
$$;


ALTER FUNCTION public.sp_get_db_mgmt_list(i_db_mgmt_type public.en_db_mgmt_type, i_ip_connected inet, i_host_url text) OWNER TO cppoltp;

