--
-- Name: sp_get_delete_old_product_pkg(text, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_delete_old_product_pkg(i_pkgtype text, i_serverid bigint[]) RETURNS TABLE(path text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
    RETURN QUERY
        WITH removed_pkg AS (
            SELECT
                pkg.product_pkg_id, pkg.path
            FROM
                tb_product_pkg pkg
            WHERE
                pkg.pkg_type = i_pkgType::en_pkg_type
                AND pkg.is_removed IS TRUE
                AND pkg.pkg_type NOT IN ('WIN_AGENT_MASTER','LINUX_AGENT_MASTER','WIN_AGENT_INSTALL','LINUX_AGENT_INSTALL')
        )
        , remain_pkg AS (
            SELECT
                pkg.product_pkg_id, pkg.path
            FROM
                tb_product_pkg pkg
            WHERE
                pkg.pkg_type = i_pkgType::en_pkg_type
                AND pkg.is_removed IS FALSE
                AND pkg.pkg_type NOT IN ('WIN_AGENT_MASTER','LINUX_AGENT_MASTER','WIN_AGENT_INSTALL','LINUX_AGENT_INSTALL')
        )
        , delete_pkg_server AS (
            DELETE FROM tb_pkg_server
            WHERE product_pkg_id IN (SELECT product_pkg_id FROM removed_pkg)
                    AND server_id IN (SELECT * FROM unnest(i_serverId))
        )
        SELECT pkg.path AS path 
        FROM removed_pkg pkg
        WHERE pkg.path NOT IN (SELECT rp.path FROM remain_pkg rp)
    ;

END;
$$;


ALTER FUNCTION public.sp_get_delete_old_product_pkg(i_pkgtype text, i_serverid bigint[]) OWNER TO cppoltp;

