CREATE FUNCTION public.sp_get_department_list() RETURNS TABLE(department text)
    LANGUAGE plpgsql
    AS $$
BEGIN

  RETURN QUERY
  SELECT DISTINCT u.department AS department
  FROM tb_user u
  WHERE  EXISTS (SELECT 1 FROM tb_node n WHERE n.node_id = u.node_id AND is_removed is false)
  ORDER BY department;

END;
$$;


