--
-- Name: sp_get_deploy_detail(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_deploy_detail(i_product_pkg_id bigint) RETURNS TABLE(product_pkg_id bigint, name text, pkg_type public.en_pkg_type, version text, path text, pkg_status public.en_pkg_status, product_id public.en_product_id_type, language public.en_language, description text, mpsetup_hash text, modified_time timestamp without time zone, delta_update boolean, apply_engine boolean, apply_patch boolean, server_id bigint, platform_id public.en_platform_id_type)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT
    prpk.product_pkg_id   /* 제품 패키지 타입 */
    ,prpk.name        /* 패키지 명 */
    ,prpk.pkg_type      /* 패키지 타입 */
    ,prpk.version     /* 패키지 버전 */
    ,prpk.path        /* 패키지 경로 */
    ,prpk.pkg_status    /* 패키지 상태 */
    ,prpk.product_id    /* 제품 ID */
    ,prpk.language      /* 패키지 언어 */
    ,prpk.description   /* 설명 */
    ,prpk.mpsetup_hash    /* mpsetup 해시 */
    ,prpk.modified_time   /* 변경 시각 */
    ,prpk.delta_update    /* 델타업데이트 사용 여부 */
    ,prpk.apply_engine    /* 엔진셋 적용 여부 */
    ,prpk.apply_patch   /* 패치셋 적용 여부 */
    ,prpk.server_id     /*  */
    ,pf.platform_id
    FROM
      tb_product_pkg AS prpk,
    tb_pkg_platform AS pkpf,
    tb_platform AS pf
    WHERE pf.is_supported IS TRUE
      AND prpk.product_pkg_id = i_product_pkg_id
      AND prpk.product_pkg_id = pkpf.product_pkg_id
      AND pkpf.platform_id  = pf.platform_id
      AND prpk.is_removed is false;

END;
$$;


