--
-- Name: sp_get_deploy_sync_upload_server_list(bigint, public.en_service_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_deploy_sync_upload_server_list(i_server_id bigint, i_server_type public.en_service_type) RETURNS TABLE(server_id bigint, server_ip text, server_port integer, service_type public.en_service_type)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT
      tss.server_id,
      tss.ip AS server_ip,
      (SELECT port FROM tb_service_port tspp WHERE tspp.service_type = 'TOMCAT-CONSOLE' LIMIT 1) AS server_port,
      ts.service_type
    FROM tb_server tss
    JOIN tb_service ts ON ts.server_id = tss.server_id
    WHERE tss.server_id != i_server_id AND ts.service_type = i_server_type AND ts.enabled = TRUE;
END;
$$;


