--
-- Name: sp_get_diag_info(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_diag_info() RETURNS TABLE(name text, info text)
    LANGUAGE plpgsql
    AS $$
BEGIN

RETURN QUERY
SELECT 'pg_stat_activity', array_to_json(array_agg(t))::text FROM (SELECT * FROM pg_stat_activity) t union all
SELECT 'pg_locks', array_to_json(array_agg(t))::text FROM (SELECT * FROM pg_locks) t union all
SELECT 'pg_stat_user_tables', array_to_json(array_agg(t))::text FROM (SELECT * FROM pg_stat_user_tables) t union ALL
SELECT 'tb_node_status', array_to_json(array_agg(t))::text FROM (SELECT * FROM tb_node_status) t union ALL
SELECT 'tb_v3_status', array_to_json(array_agg(t))::text FROM (SELECT * FROM tb_v3_status) t union ALL
SELECT 'tb_product_info', array_to_json(array_agg(t))::text FROM (SELECT * FROM tb_product_info) t union ALL
SELECT 'tb_policy_status', array_to_json(array_agg(t))::text FROM (SELECT * FROM tb_policy_status) t union ALL
SELECT 'tb_task_target_status', array_to_json(array_agg(t))::text FROM (SELECT * FROM tb_task_target_status WHERE task_type <> 'APPLY_MERGEABLE_POLICY' ORDER BY server_time DESC LIMIT 1000) t union ALL
SELECT 'tb_server_resource', array_to_json(array_agg(t))::text FROM (SELECT * FROM tb_server_resource ORDER BY log_time DESC LIMIT 500) t;

END;
$$;


ALTER FUNCTION public.sp_get_diag_info() OWNER TO cppoltp;

--
-- Name: sp_get_disconnected_node(bigint, bigint, public.en_task_status, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_disconnected_node(i_task_id bigint, i_instance_id bigint, i_task_status public.en_task_status, i_task_error text) RETURNS TABLE(node_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_node_id BIGINT[];

BEGIN

  SELECT array_agg(n.node_id)
  INTO v_node_id
  FROM tb_node_status AS n
  WHERE n.connection_status <> 'CONNECTED'
    AND EXISTS (SELECT 1
                FROM tb_task_target_status tts
                WHERE tts.task_id = i_task_id
                  AND tts.target_id = n.node_id);

  UPDATE tb_task_target_status
  SET task_status = i_task_status
     ,task_error = i_task_error
     ,server_time = now()
  WHERE task_id = i_task_id
    AND instance_id = i_instance_id
    AND target_id = ANY(v_node_id);

  RETURN QUERY
  SELECT v_node_id::TEXT;

END;
$$;


ALTER FUNCTION public.sp_get_disconnected_node(i_task_id bigint, i_instance_id bigint, i_task_status public.en_task_status, i_task_error text) OWNER TO cppoltp;

