--

CREATE FUNCTION public.sp_get_domain_information() RETURNS TABLE(oes_engine_version text, ses_engine_version text, oes_modified_time timestamp without time zone, ses_modified_time timestamp without time zone)
    LANGUAGE plpgsql
    AS $$

BEGIN

RETURN QUERY
-- 도메인 정보
SELECT co.engine_version AS oes_engine_version
      ,cs.engine_version AS ses_engine_version
      ,co.modified_time AS oes_modified_time
      ,cs.modified_time AS ses_modified_time
FROM (SELECT c.value AS engine_version
            ,c.modified_time AS modified_time
      FROM tb_config c
      WHERE c.config_group = 'UPDATE_SERVICE'
        AND c.key = 'oes_engine_date') co
CROSS JOIN
     (SELECT c.value AS engine_version
            ,c.modified_time AS modified_time
      FROM tb_config c
      WHERE c.config_group = 'UPDATE_SERVICE'
        AND c.key = 'ses_engine_date') cs;

END;
$$;


