CREATE FUNCTION public.sp_get_domain_policy_status() RETURNS TABLE(product_feature_id public.en_product_feature_id_type, policy_status public.en_policy_status, count bigint)
    LANGUAGE plpgsql
    AS $$

BEGIN

RETURN QUERY
--도메인 정책 적용 현황
SELECT ps.product_feature_id AS product_feature_id
      ,ps.policy_status AS policy_status
      ,count(*) AS count
FROM vw_policy_status ps
