CREATE FUNCTION public.sp_get_dtb_detail(i_pkg_id bigint) RETURNS TABLE(detail text)
    LANGUAGE plpgsql
    AS $$
#variable_conflict use_column
DECLARE
BEGIN
  IF NOT EXISTS (SELECT product_pkg_id FROM tb_product_pkg WHERE pkg_type = 'CUSTOM' AND product_pkg_id = i_pkg_id AND is_removed IS FALSE) THEN
    RAISE EXCEPTION 'not existed package : %', i_pkg_id USING HINT = 'DB-00053';
  END IF;

  RETURN QUERY SELECT detail FROM tb_product_pkg WHERE pkg_type = 'CUSTOM' AND product_pkg_id = i_pkg_id AND is_removed IS FALSE;
END;
