--
-- Name: sp_get_duplicate_group_name(bigint, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_duplicate_group_name(i_pgroup_id bigint, i_name text) RETURNS TABLE(group_id bigint, group_type public.en_group_type)
    LANGUAGE plpgsql
    AS $$

BEGIN

RETURN QUERY

WITH RECURSIVE group_list (group_id, name, pgroup_id, group_type, is_removed, level, grp_path, cycle)
AS (
SELECT g.group_id
      ,g.name
      ,g.pgroup_id
      ,g.group_type
      ,g.is_removed
      ,0
      ,ARRAY[g.group_id]
      ,false
FROM tb_group g
WHERE g.group_type = 'TOP'
UNION ALL
SELECT g.group_id
      ,g.name
      ,g.pgroup_id
      ,g.group_type
      ,g.is_removed
      ,gl.level + 1
      ,gl.grp_path || g.group_id
      ,g.group_id = ANY(gl.grp_path)
FROM tb_group g
JOIN group_list gl
  ON g.pgroup_id = gl.group_id
  AND NOT cycle
WHERE g.group_type NOT IN ('TOP')
  AND g.is_removed IS NOT true
)

SELECT gl.group_id AS group_id
      ,gl.group_type AS group_type
FROM group_list gl
WHERE gl.is_removed IS NOT true
  AND gl.name = i_name
  AND gl.group_type = 'TOP'
UNION ALL
SELECT gl.group_id AS group_id
      ,gl.group_type AS group_type
FROM group_list gl
WHERE gl.is_removed IS NOT true
  AND gl.name = i_name
  AND gl.pgroup_id = i_pgroup_id
;

END;
$$;


ALTER FUNCTION public.sp_get_duplicate_group_name(i_pgroup_id bigint, i_name text) OWNER TO cppoltp;

