--

CREATE FUNCTION public.sp_get_emsinfo_engine() RETURNS TABLE(product_name public.en_product_group_type, current_version text, install_count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
    RETURN QUERY
    select tb_product.product_group, tb_v3_status.engine_version, count(*) as install_count
    from tb_product, tb_v3_status
    where tb_product.product_id = tb_v3_status.product_id
    and tb_v3_status.engine_version is not NULL
    group by tb_product.product_group, tb_v3_status.engine_version;

END;
$$;


ALTER FUNCTION public.sp_get_emsinfo_engine() OWNER TO cppoltp;

--
-- Name: sp_get_emsinfo_product(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_emsinfo_product() RETURNS TABLE(product_id text, current_version text, os_version text, kernel_version text, os_type text, system_type text, count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
	RETURN QUERY
    SELECT
      (
        SELECT
          CASE
            WHEN tp.product_id = 'EMS' THEN 'CPP'
            ELSE tp.product_id::text
          END AS product_id
        FROM
          tb_product tp
        WHERE
          tp.product_id = 'EMS'
      )
      , COALESCE(ts.current_version, '') AS current_version
      , '' AS os_version
      , '' AS kernel_version
      , '' AS os_type
      , '' AS system_type
      , COUNT(*)
    FROM
      tb_server ts
    GROUP BY
      ts.current_version
    UNION
    SELECT
    	tp.product_id::text
    	, COALESCE(tn.agent_version, '') AS current_version
    	, tn.platform_id::text AS os_version
    	, COALESCE(tnh.os_kernel_version, '') AS kernel_version
    	, CASE
          WHEN tn.platform_id::text = 'UNKNOWN' THEN 'etc'
          WHEN tn.platform_id::text LIKE '%WINDOWS%' THEN 'WINDOWS'
          ELSE 'LINUX_UNIX'
        END AS os_type
    	, tn.machine_type::text AS system_type
    	, COUNT(DISTINCT tn.node_id)
    FROM
    	tb_node tn
    INNER JOIN
    	tb_node_status tns 
    ON
    	tn.node_id = tns.node_id
    AND
    	tns.connection_status NOT IN ('UNINSTALLED')
    INNER JOIN
    	tb_product tp
    ON
    	tp.product_id = 'AGENT'
    INNER JOIN
    	TB_NODE_HW TNH
    ON
    	TN.NODE_ID = TNH.NODE_ID
    WHERE
    	tn.is_removed IS FALSE
    GROUP BY 
      tp.product_id, tn.agent_version, tn.machine_type, tn.platform_id, tnh.os_kernel_version
    UNION
    SELECT
    	tvs.product_id::text
    	, COALESCE(tvs.product_version,'') AS current_version
    	, tn.platform_id::text AS os_version
    	, COALESCE(tnh.os_kernel_version, '') AS kernel_version
    	, CASE
          WHEN tn.platform_id::text = 'UNKNOWN' THEN 'etc'
          WHEN tn.platform_id::text LIKE '%WINDOWS%' THEN 'WINDOWS'
          ELSE 'LINUX_UNIX'
        END AS os_type
    	, tn.machine_type::text AS system_type
    	, COUNT(DISTINCT tvs.node_id)
    FROM
    	tb_v3_status tvs
    INNER JOIN
    	tb_node tn
    ON
    	tvs.node_id = tn.node_id
    AND
    	tn.is_removed IS FALSE
    INNER JOIN
    	tb_node_status tns 
    ON
    	tn.node_id = tns.node_id
    AND
    	tns.connection_status NOT IN ('UNINSTALLED')
    INNER JOIN
    	tb_product tp
    ON
    	tvs.product_id = tp.product_id
    INNER JOIN
    	TB_NODE_HW TNH
    ON
    	TN.NODE_ID = TNH.NODE_ID
    WHERE
    	tvs.node_id IN (SELECT tpi.node_id FROM tb_product_info tpi WHERE tpi.product_id = tvs.product_id)
    GROUP BY
    	tvs.product_id, tvs.product_version, tn.machine_type, tn.platform_id, tnh.os_kernel_version
    UNION
    SELECT
    	tas.product_id::text
    	, COALESCE(tas.product_version,'') AS current_version
    	, tn.platform_id::text AS os_version
    	, COALESCE(tnh.os_kernel_version, '') AS kernel_version
    	, CASE
          WHEN tn.platform_id::text = 'UNKNOWN' THEN 'etc'
          WHEN tn.platform_id::text LIKE '%WINDOWS%' THEN 'WINDOWS'
          ELSE 'LINUX_UNIX'
        END AS os_type
    	, tn.machine_type::text AS system_type
    	, COUNT(DISTINCT tas.node_id)
    FROM
    	tb_ac_status tas
    INNER JOIN
    	tb_node tn
    ON
    	tas.node_id = tn.node_id
    AND
    	tn.is_removed IS FALSE
    INNER JOIN
    	tb_node_status tns 
    ON
    	tn.node_id = tns.node_id
    AND
    	tns.connection_status NOT IN ('UNINSTALLED')
    INNER JOIN
    	tb_product tp
    ON
    	tas.product_id = tp.product_id
    INNER JOIN
    	TB_NODE_HW TNH
    ON
    	TN.NODE_ID = TNH.NODE_ID
    WHERE
    	tas.node_id IN (SELECT tpi.node_id FROM tb_product_info tpi WHERE tpi.product_id = tas.product_id)
    GROUP BY
    	tas.product_id, tas.product_version, tn.machine_type, tn.platform_id, tnh.os_kernel_version
    UNION
    SELECT
    	ths.product_id::text
    	, COALESCE(ths.product_version,'') AS current_version
    	, tn.platform_id::text AS os_version
    	, COALESCE(tnh.os_kernel_version, '') AS kernel_version
    	, CASE
          WHEN tn.platform_id::text = 'UNKNOWN' THEN 'etc'
          WHEN tn.platform_id::text LIKE '%WINDOWS%' THEN 'WINDOWS'
          ELSE 'LINUX_UNIX'
        END AS os_type
    	, tn.machine_type::text AS system_type
    	, COUNT(DISTINCT ths.node_id) 
    FROM
    	tb_hips_status ths
    INNER JOIN
    	tb_node tn
    ON
    	ths.node_id = tn.node_id
    AND
    	tn.is_removed IS FALSE
    INNER JOIN
    	tb_node_status tns 
    ON
    	tn.node_id = tns.node_id
    AND
    	tns.connection_status NOT IN ('UNINSTALLED')
    INNER JOIN
    	tb_product tp
    ON
    	ths.product_id = tp.product_id
    INNER JOIN
    	TB_NODE_HW TNH
    ON
    	TN.NODE_ID = TNH.NODE_ID
    WHERE
    	ths.node_id IN (SELECT tpi.node_id FROM tb_product_info tpi WHERE tpi.product_id = ths.product_id)
    GROUP BY
   		ths.product_id, ths.product_version, tn.machine_type, tn.platform_id, tnh.os_kernel_version
   	ORDER BY
   		product_id, current_version;

END;
$$;


ALTER FUNCTION public.sp_get_emsinfo_product() OWNER TO cppoltp;

--
-- Name: sp_get_emsinfo_product_license(public.en_product_id_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_emsinfo_product_license(i_product_id public.en_product_id_type) RETURNS TABLE(product_id text, product_license text, version text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
  IF( i_product_id IS NULL ) THEN
    RETURN QUERY
    SELECT
      CASE WHEN tp.product_id = 'EMS' THEN 'CPP' ELSE tp.product_id::text END AS product_id
      , tpl.license_no
      , tpl.version
    FROM tb_product tp
      INNER JOIN tb_product_license tpl ON tp.product_id = tpl.product_id
    WHERE
      tp.managed IS true;
  ELSEIF( i_product_id = 'HIPS_CLIENT' ) THEN
    RETURN query
    SELECT
      CASE WHEN tp.product_id = 'EMS' THEN 'CPP' ELSE tp.product_id::text END AS product_id
      , tpl.license_no
      , tpl.version
    FROM tb_product tp
      INNER JOIN tb_product_license tpl ON tp.product_id = tpl.product_id
    WHERE
      tp.managed IS TRUE
      AND tp.product_id IN ('EMS', 'HIPS_CLIENT');
  ELSE
    RETURN QUERY
    SELECT
      CASE WHEN tp.product_id = 'EMS' THEN 'CPP' ELSE tp.product_id::text END AS product_id
      , tpl.license_no
      , tpl.version
    FROM tb_product tp
      INNER JOIN tb_product_license tpl ON tp.product_id = tpl.product_id
    WHERE
      tp.managed IS TRUE
      AND tpl.product_id = i_product_id;
  END IF;

END;
$$;


ALTER FUNCTION public.sp_get_emsinfo_product_license(i_product_id public.en_product_id_type) OWNER TO cppoltp;

