--
-- Name: sp_get_engine_update(bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_engine_update(i_node_id bigint[]) RETURNS TABLE(engine_version text, count bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

RETURN QUERY

WITH base_data AS
(SELECT vs.engine_version AS engine_version
      , count(*) AS count
      , row_number() over() as rn
   FROM tb_v3_status vs
   JOIN tb_product_info pi ON vs.node_id = pi.node_id AND vs.product_id = pi.product_id
  WHERE vs.node_id = ANY(i_node_id)
    AND EXISTS (SELECT 1  FROM tb_node n  WHERE n.node_id = vs.node_id  AND n.is_removed is false)
  GROUP BY vs.engine_version
 HAVING vs.engine_version != ''
  ORDER BY vs.engine_version DESC )
 SELECT bd.engine_version
      , CASE WHEN rn < 3 THEN bd.count
             ELSE (SELECT sum(bd.count)::BIGINT FROM base_data AS bd WHERE rn > 2 )
  		END as count
   FROM base_data bd
  WHERE rn <= 3
;

END;
$$;


ALTER FUNCTION public.sp_get_engine_update(i_node_id bigint[]) OWNER TO cppoltp;

