--
-- Name: sp_get_etl_map(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_etl_map() RETURNS TABLE(step integer, etl_from public.en_etl_from, etl_to public.en_etl_to, etl_method public.en_etl_method, from_collection text, etl_query text, to_table text, to_column text, pre_from_proc text, pre_to_proc text, post_from_proc text, post_to_proc text, max_step integer, is_shard boolean)
    LANGUAGE plpgsql
    AS $$
BEGIN
RETURN QUERY
WITH t AS (select max(m.step) max_step from tb_etl_map m)
select m.step, m.etl_from, m.etl_to, m.etl_method, m.from_collection, m.etl_query, m.to_table, m.to_column,
m.pre_from_proc, m.pre_to_proc, m.post_from_proc, m.post_to_proc, t.max_step, m.is_shard
from tb_etl_map m, t
WHERE m.enabled = true
order by m.step asc;
END;
$$;


