--
-- Name: sp_get_event_log_common_obj_id(text, text, integer); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_event_log_common_obj_id(i_event_type text, i_from_obj_id text, i_limit integer) RETURNS TABLE(start_obj_id text, start_obj_index_num integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
  /*
  CWPP-4837 처리
  i_event_type
    SERVICE(로그 > 서버 > 서비스이벤트)
    AUDIT(로그 > 서버 > 관리자이벤트)
    ENGINE_UPDATE(로그 > 서버 > 업데이트)
    BACKUP(로그 > 서버 > 백업)
    PKG_DIST(로그 > 서버 > 배포)
    PKG_SYNC(로그 > 서버 > 파일동기화)
    AGENT_INSTALL_PKG(로그 > 서버 > 에이전트 설치 파일)
    SERVER_ALERT(로그 > 서버 > 서버 경보)

    AGENT_EVENT(로그 > 제품 > CPP 에이전트 이벤트)
    TASK_STATUS(로그 > 제품 > 작업 이력)
    NODE_SW(로그 > 제품 > 소프트웨어 자산 변경 이력)
    NODE_HW(로그 > 제품 > 하드웨어 자산 변경 이력)
    V3_ALERT(로그 > 제품 > 악성코드 감염 정보)
    V3_SS(로그 > 제품 > 검사/실시간 검사)
    V3_IS(로그 > 제품 > 인터넷 보안)
    V3_SUP(로그 > 제품 > V3업데이트)
    V3_QUAR(로그 > 제품 > V3 검역소 파일 복원)
    V3_DEVICE(로그 > 제품 > 장치 제어)
    HIPS_AGENT_EVENT(로그 > 제품 > HIPS 에이전트 이벤트)
    HIPS_DETECT_EVENT(로그 > 제품 > HIPS 탐지 이벤트)
    HIPS_FW_EVENT(로그 > 제품 > HIPS 탐지 이벤트)
    AC_AGENT_EVENT(로그 > 제품 > AC 에이전트 이벤트)
    AC_EXEC_EVENT(로그 > 제품 > AC 실행제어 이벤트)
    AC_ACCESS_EVENT(로그 > 제품 > AC 실행제어 이벤트)
    AC_IM_DETECT_EVENT(로그 > 제품 > AC > IM 탐지 이벤트)
    CNAPP_EVENT(로그 > 제품 > Container Security > Container Security 이벤트)
    CNAPP_MALWARE_SCAN(로그 > 제품 > Container Security > Image Scan(Malware) 이벤트)
    CNAPP_VULNERABILITY_SCAN(로그 > 제품 > Container Security > Image Scan(Vulnerabilities) 이벤트)
    SCM_AGENT_EVENT(로그 > 제품 > SCM > SCM 에이전트 이벤트)
    SCM_SCAN_EVENT(로그 > 제품 > SCM > SCM 점검 이벤트)
  */
  RETURN QUERY
      SELECT i_from_obj_id, 0;
END;
$$;


ALTER FUNCTION public.sp_get_event_log_common_obj_id(i_event_type text, i_from_obj_id text, i_limit integer) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_event_log_common_obj_id(i_event_type text, i_from_obj_id text, i_limit integer); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_event_log_common_obj_id(i_event_type text, i_from_obj_id text, i_limit integer) IS '
@brief 로그 > 리스트 시작 object id 구하기
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_event_log_common_obj_id_list(text, text, text, integer); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_event_log_common_obj_id_list(i_event_type text, i_from_obj_id text, i_to_obj_id text, i_limit integer) RETURNS TABLE(paging integer, start_obj_id text, paging_count integer, start_obj_index_num integer, end_obj_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_min_row_number            bigint := 0;
  v_max_row_number            bigint := 0;
  v_row_number                bigint[];
  v_paging_count              integer[];
  v_join_row_number           bigint[];
  v_temp_count                integer;

  v_zero_num_obj_id           text := '000000000000000000000000';
BEGIN

  set LOCAL work_mem = '32MB';
  -- 로그 > 서버 > 서비스이벤트
  IF ( i_event_type = 'SERVICE') THEN
    SELECT row_number INTO v_min_row_number FROM tb_service_log_obj_id WHERE obj_id <= i_to_obj_id AND obj_id >= i_from_obj_id ORDER BY obj_id ASC LIMIT 1;
    SELECT row_number INTO v_max_row_number FROM tb_service_log_obj_id WHERE obj_id <= i_to_obj_id AND obj_id >= i_from_obj_id ORDER BY obj_id DESC LIMIT 1;

    SELECT f.row_number, f.paging_count, (SELECT ARRAY_AGG(paging_sum.row_number) FROM (SELECT (UNNEST(f.row_number) + UNNEST(f.paging_count))) AS paging_sum(row_number)) INTO v_row_number, v_paging_count, v_join_row_number FROM sp_get_event_log_custom_paging_composition(v_min_row_number, v_max_row_number, i_limit, false) f;

    RETURN QUERY
      SELECT
        (ROW_NUMBER() OVER(ORDER BY org.end_obj_id DESC))::integer
        , COALESCE(org.obj_id, v_zero_num_obj_id) AS obj_id
        , org.paging_count
        , 0
        , org.end_obj_id
      FROM (
        SELECT 
          (CASE WHEN t.row_number = 0 THEN v_zero_num_obj_id ELSE s.obj_id END) AS obj_id
          , (CASE WHEN t.paging_count = 0 THEN i_limit ELSE t.paging_count END) AS paging_count
          , (CASE WHEN e.obj_id IS NULL THEN (CASE WHEN t.row_number = 0 THEN v_zero_num_obj_id ELSE s.obj_id END) ELSE e.obj_id END) As end_obj_id
        FROM UNNEST(v_row_number, v_paging_count) AS t(row_number, paging_count)
        LEFT JOIN tb_service_log_obj_id s ON t.row_number = s.row_number
        LEFT JOIN (
          SELECT s.obj_id AS obj_id, e.row_number
          FROM UNNEST(v_row_number, v_paging_count, v_join_row_number) AS e(row_number, paging_count, join_row_number)
          LEFT JOIN tb_service_log_obj_id s ON e.join_row_number = s.row_number
        ) e
        ON t.row_number = e.row_number
      ) org
      ORDER BY 1;

  -- 로그 > 서버 > 관리자이벤트
  ELSEIF ( i_event_type = 'AUDIT') THEN
    SELECT row_number INTO v_min_row_number FROM tb_audit_log_obj_id WHERE obj_id <= i_to_obj_id AND obj_id >= i_from_obj_id ORDER BY obj_id ASC LIMIT 1;
    SELECT row_number INTO v_max_row_number FROM tb_audit_log_obj_id WHERE obj_id <= i_to_obj_id AND obj_id >= i_from_obj_id ORDER BY obj_id DESC LIMIT 1;

    SELECT f.row_number, f.paging_count, (SELECT ARRAY_AGG(paging_sum.row_number) FROM (SELECT (UNNEST(f.row_number) + UNNEST(f.paging_count))) AS paging_sum(row_number)) INTO v_row_number, v_paging_count, v_join_row_number FROM sp_get_event_log_custom_paging_composition(v_min_row_number, v_max_row_number, i_limit, false) f;

    RETURN QUERY
      SELECT
        (ROW_NUMBER() OVER(ORDER BY org.end_obj_id DESC))::integer
        , COALESCE(org.obj_id, v_zero_num_obj_id) AS obj_id
        , org.paging_count
        , 0
        , org.end_obj_id
      FROM (
        SELECT 
          (CASE WHEN t.row_number = 0 THEN v_zero_num_obj_id ELSE s.obj_id END) AS obj_id
          , (CASE WHEN t.paging_count = 0 THEN i_limit ELSE t.paging_count END) AS paging_count
          , (CASE WHEN e.obj_id IS NULL THEN (CASE WHEN t.row_number = 0 THEN v_zero_num_obj_id ELSE s.obj_id END) ELSE e.obj_id END) As end_obj_id
        FROM UNNEST(v_row_number, v_paging_count) AS t(row_number, paging_count)
        LEFT JOIN tb_audit_log_obj_id s ON t.row_number = s.row_number
        LEFT JOIN (
          SELECT s.obj_id AS obj_id, e.row_number
          FROM UNNEST(v_row_number, v_paging_count, v_join_row_number) AS e(row_number, paging_count, join_row_number)
          LEFT JOIN tb_audit_log_obj_id s ON e.join_row_number = s.row_number
        ) e
        ON t.row_number = e.row_number
      ) org
      ORDER BY 1;

  -- 로그 > 서버 > 업데이트
  ELSEIF ( i_event_type = 'ENGINE_UPDATE') THEN
    SELECT row_number INTO v_min_row_number FROM tb_engine_update_log_obj_id WHERE obj_id <= i_to_obj_id AND obj_id >= i_from_obj_id ORDER BY obj_id ASC LIMIT 1;
    SELECT row_number INTO v_max_row_number FROM tb_engine_update_log_obj_id WHERE obj_id <= i_to_obj_id AND obj_id >= i_from_obj_id ORDER BY obj_id DESC LIMIT 1;

    SELECT f.row_number, f.paging_count, (SELECT ARRAY_AGG(paging_sum.row_number) FROM (SELECT (UNNEST(f.row_number) + UNNEST(f.paging_count))) AS paging_sum(row_number)) INTO v_row_number, v_paging_count, v_join_row_number FROM sp_get_event_log_custom_paging_composition(v_min_row_number, v_max_row_number, i_limit, false) f;

    RETURN QUERY
      SELECT
        (ROW_NUMBER() OVER(ORDER BY org.end_obj_id DESC))::integer
        , COALESCE(org.obj_id, v_zero_num_obj_id) AS obj_id
        , org.paging_count
        , 0
        , org.end_obj_id
      FROM (
        SELECT 
          (CASE WHEN t.row_number = 0 THEN v_zero_num_obj_id ELSE s.obj_id END) AS obj_id
          , (CASE WHEN t.paging_count = 0 THEN i_limit ELSE t.paging_count END) AS paging_count
          , (CASE WHEN e.obj_id IS NULL THEN (CASE WHEN t.row_number = 0 THEN v_zero_num_obj_id ELSE s.obj_id END) ELSE e.obj_id END) As end_obj_id
        FROM UNNEST(v_row_number, v_paging_count) AS t(row_number, paging_count)
        LEFT JOIN tb_engine_update_log_obj_id s ON t.row_number = s.row_number
        LEFT JOIN (
          SELECT s.obj_id AS obj_id, e.row_number
          FROM UNNEST(v_row_number, v_paging_count, v_join_row_number) AS e(row_number, paging_count, join_row_number)
          LEFT JOIN tb_engine_update_log_obj_id s ON e.join_row_number = s.row_number
        ) e
        ON t.row_number = e.row_number
      ) org
      ORDER BY 1;

  -- 로그 > 서버 > 백업
  ELSEIF ( i_event_type = 'BACKUP') THEN
    SELECT row_number INTO v_min_row_number FROM tb_backup_log_obj_id WHERE obj_id <= i_to_obj_id AND obj_id >= i_from_obj_id ORDER BY obj_id ASC LIMIT 1;
    SELECT row_number INTO v_max_row_number FROM tb_backup_log_obj_id WHERE obj_id <= i_to_obj_id AND obj_id >= i_from_obj_id ORDER BY obj_id DESC LIMIT 1;

    SELECT f.row_number, f.paging_count, (SELECT ARRAY_AGG(paging_sum.row_number) FROM (SELECT (UNNEST(f.row_number) + UNNEST(f.paging_count))) AS paging_sum(row_number)) INTO v_row_number, v_paging_count, v_join_row_number FROM sp_get_event_log_custom_paging_composition(v_min_row_number, v_max_row_number, i_limit, false) f;

    RETURN QUERY
      SELECT
