    SELECT row_number INTO v_max_row_number FROM tb_cnapp_event_log_obj_id WHERE obj_id <= i_to_obj_id AND obj_id >= i_from_obj_id ORDER BY obj_id DESC LIMIT 1;

    SELECT f.row_number, f.paging_count, (SELECT ARRAY_AGG(paging_sum.row_number) FROM (SELECT (UNNEST(f.row_number) + UNNEST(f.paging_count))) AS paging_sum(row_number)) INTO v_row_number, v_paging_count, v_join_row_number FROM sp_get_event_log_custom_paging_composition(v_min_row_number, v_max_row_number, i_limit, false) f;

    RETURN QUERY
      SELECT
        (ROW_NUMBER() OVER(ORDER BY org.end_obj_id DESC))::integer
        , COALESCE(org.obj_id, v_zero_num_obj_id) AS obj_id
        , org.paging_count
        , 0
        , org.end_obj_id
      FROM (
        SELECT
          (CASE WHEN t.row_number = 0 THEN v_zero_num_obj_id ELSE s.obj_id END) AS obj_id
          , (CASE WHEN t.paging_count = 0 THEN i_limit ELSE t.paging_count END) AS paging_count
          , (CASE WHEN e.obj_id IS NULL THEN (CASE WHEN t.row_number = 0 THEN v_zero_num_obj_id ELSE s.obj_id END) ELSE e.obj_id END) As end_obj_id
        FROM UNNEST(v_row_number, v_paging_count) AS t(row_number, paging_count)
        LEFT JOIN tb_cnapp_event_log_obj_id s ON t.row_number = s.row_number
        LEFT JOIN (
          SELECT s.obj_id AS obj_id, e.row_number
          FROM UNNEST(v_row_number, v_paging_count, v_join_row_number) AS e(row_number, paging_count, join_row_number)
          LEFT JOIN tb_cnapp_event_log_obj_id s ON e.join_row_number = s.row_number
        ) e
        ON t.row_number = e.row_number
      ) org
      ORDER BY 1;
  
  -- 로그 > 제품 > Container Security > Image Scan(Malware) 이벤트
  ELSEIF (i_event_type = 'CNAPP_MALWARE_SCAN') THEN
    SELECT row_number INTO v_min_row_number FROM tb_cnapp_malware_scan_event_log_obj_id WHERE obj_id <= i_to_obj_id AND obj_id >= i_from_obj_id ORDER BY obj_id ASC LIMIT 1;
    SELECT row_number INTO v_max_row_number FROM tb_cnapp_malware_scan_event_log_obj_id WHERE obj_id <= i_to_obj_id AND obj_id >= i_from_obj_id ORDER BY obj_id DESC LIMIT 1;

    SELECT f.row_number, f.paging_count, (SELECT ARRAY_AGG(paging_sum.row_number) FROM (SELECT (UNNEST(f.row_number) + UNNEST(f.paging_count))) AS paging_sum(row_number)) INTO v_row_number, v_paging_count, v_join_row_number FROM sp_get_event_log_custom_paging_composition(v_min_row_number, v_max_row_number, i_limit, false) f;

    RETURN QUERY
      SELECT
        (ROW_NUMBER() OVER(ORDER BY org.end_obj_id DESC))::integer
        , COALESCE(org.obj_id, v_zero_num_obj_id) AS obj_id
        , org.paging_count
        , 0
        , org.end_obj_id
      FROM (
        SELECT
          (CASE WHEN t.row_number = 0 THEN v_zero_num_obj_id ELSE s.obj_id END) AS obj_id
          , (CASE WHEN t.paging_count = 0 THEN i_limit ELSE t.paging_count END) AS paging_count
          , (CASE WHEN e.obj_id IS NULL THEN (CASE WHEN t.row_number = 0 THEN v_zero_num_obj_id ELSE s.obj_id END) ELSE e.obj_id END) As end_obj_id
        FROM UNNEST(v_row_number, v_paging_count) AS t(row_number, paging_count)
        LEFT JOIN tb_cnapp_malware_scan_event_log_obj_id s ON t.row_number = s.row_number
        LEFT JOIN (
          SELECT s.obj_id AS obj_id, e.row_number
          FROM UNNEST(v_row_number, v_paging_count, v_join_row_number) AS e(row_number, paging_count, join_row_number)
          LEFT JOIN tb_cnapp_malware_scan_event_log_obj_id s ON e.join_row_number = s.row_number
        ) e
        ON t.row_number = e.row_number
      ) org
      ORDER BY 1;

  -- 로그 > 제품 > Container Security > Image Scan(Vulnerability) 이벤트
  ELSEIF (i_event_type = 'CNAPP_VULNERABILITY_SCAN') THEN
    SELECT row_number INTO v_min_row_number FROM tb_cnapp_vulnerability_scan_event_log_obj_id WHERE obj_id <= i_to_obj_id AND obj_id >= i_from_obj_id ORDER BY obj_id ASC LIMIT 1;
    SELECT row_number INTO v_max_row_number FROM tb_cnapp_vulnerability_scan_event_log_obj_id WHERE obj_id <= i_to_obj_id AND obj_id >= i_from_obj_id ORDER BY obj_id DESC LIMIT 1;

    SELECT f.row_number, f.paging_count, (SELECT ARRAY_AGG(paging_sum.row_number) FROM (SELECT (UNNEST(f.row_number) + UNNEST(f.paging_count))) AS paging_sum(row_number)) INTO v_row_number, v_paging_count, v_join_row_number FROM sp_get_event_log_custom_paging_composition(v_min_row_number, v_max_row_number, i_limit, false) f;

    RETURN QUERY
      SELECT
        (ROW_NUMBER() OVER(ORDER BY org.end_obj_id DESC))::integer
        , COALESCE(org.obj_id, v_zero_num_obj_id) AS obj_id
        , org.paging_count
        , 0
        , org.end_obj_id
      FROM (
        SELECT
          (CASE WHEN t.row_number = 0 THEN v_zero_num_obj_id ELSE s.obj_id END) AS obj_id
          , (CASE WHEN t.paging_count = 0 THEN i_limit ELSE t.paging_count END) AS paging_count
          , (CASE WHEN e.obj_id IS NULL THEN (CASE WHEN t.row_number = 0 THEN v_zero_num_obj_id ELSE s.obj_id END) ELSE e.obj_id END) As end_obj_id
        FROM UNNEST(v_row_number, v_paging_count) AS t(row_number, paging_count)
        LEFT JOIN tb_cnapp_vulnerability_scan_event_log_obj_id s ON t.row_number = s.row_number
        LEFT JOIN (
          SELECT s.obj_id AS obj_id, e.row_number
          FROM UNNEST(v_row_number, v_paging_count, v_join_row_number) AS e(row_number, paging_count, join_row_number)
          LEFT JOIN tb_cnapp_vulnerability_scan_event_log_obj_id s ON e.join_row_number = s.row_number
        ) e
        ON t.row_number = e.row_number
      ) org
      ORDER BY 1;

  -- 로그 > 제품 > SCM > SCM 에이전트 이벤트
  ELSEIF (i_event_type = 'SCM_AGENT_EVENT') THEN
    SELECT row_number INTO v_min_row_number FROM tb_scm_agent_log_obj_id WHERE obj_id <= i_to_obj_id AND obj_id >= i_from_obj_id ORDER BY obj_id ASC LIMIT 1;
    SELECT row_number INTO v_max_row_number FROM tb_scm_agent_log_obj_id WHERE obj_id <= i_to_obj_id AND obj_id >= i_from_obj_id ORDER BY obj_id DESC LIMIT 1;

    SELECT f.row_number, f.paging_count, (SELECT ARRAY_AGG(paging_sum.row_number) FROM (SELECT (UNNEST(f.row_number) + UNNEST(f.paging_count))) AS paging_sum(row_number)) INTO v_row_number, v_paging_count, v_join_row_number FROM sp_get_event_log_custom_paging_composition(v_min_row_number, v_max_row_number, i_limit, false) f;

    RETURN QUERY
      SELECT
        (ROW_NUMBER() OVER(ORDER BY org.end_obj_id DESC))::integer
        , COALESCE(org.obj_id, v_zero_num_obj_id) AS obj_id
        , org.paging_count
        , 0
        , org.end_obj_id
      FROM (
        SELECT 
          (CASE WHEN t.row_number = 0 THEN v_zero_num_obj_id ELSE s.obj_id END) AS obj_id
          , (CASE WHEN t.paging_count = 0 THEN i_limit ELSE t.paging_count END) AS paging_count
          , (CASE WHEN e.obj_id IS NULL THEN (CASE WHEN t.row_number = 0 THEN v_zero_num_obj_id ELSE s.obj_id END) ELSE e.obj_id END) As end_obj_id
        FROM UNNEST(v_row_number, v_paging_count) AS t(row_number, paging_count)
        LEFT JOIN tb_scm_agent_log_obj_id s ON t.row_number = s.row_number
        LEFT JOIN (
          SELECT s.obj_id AS obj_id, e.row_number
          FROM UNNEST(v_row_number, v_paging_count, v_join_row_number) AS e(row_number, paging_count, join_row_number)
          LEFT JOIN tb_scm_agent_log_obj_id s ON e.join_row_number = s.row_number
        ) e
        ON t.row_number = e.row_number
      ) org
      ORDER BY 1;

  -- 로그 > 제품 > SCM > SCM 점검 이벤트
  ELSEIF (i_event_type = 'SCM_SCAN_EVENT') THEN
    SELECT row_number INTO v_min_row_number FROM tb_scm_scan_log_obj_id WHERE obj_id <= i_to_obj_id AND obj_id >= i_from_obj_id ORDER BY obj_id ASC LIMIT 1;
    SELECT row_number INTO v_max_row_number FROM tb_scm_scan_log_obj_id WHERE obj_id <= i_to_obj_id AND obj_id >= i_from_obj_id ORDER BY obj_id DESC LIMIT 1;

    SELECT f.row_number, f.paging_count, (SELECT ARRAY_AGG(paging_sum.row_number) FROM (SELECT (UNNEST(f.row_number) + UNNEST(f.paging_count))) AS paging_sum(row_number)) INTO v_row_number, v_paging_count, v_join_row_number FROM sp_get_event_log_custom_paging_composition(v_min_row_number, v_max_row_number, i_limit, false) f;

    RETURN QUERY
      SELECT
        (ROW_NUMBER() OVER(ORDER BY org.end_obj_id DESC))::integer
        , COALESCE(org.obj_id, v_zero_num_obj_id) AS obj_id
        , org.paging_count
        , 0
        , org.end_obj_id
      FROM (
        SELECT 
          (CASE WHEN t.row_number = 0 THEN v_zero_num_obj_id ELSE s.obj_id END) AS obj_id
          , (CASE WHEN t.paging_count = 0 THEN i_limit ELSE t.paging_count END) AS paging_count
          , (CASE WHEN e.obj_id IS NULL THEN (CASE WHEN t.row_number = 0 THEN v_zero_num_obj_id ELSE s.obj_id END) ELSE e.obj_id END) As end_obj_id
        FROM UNNEST(v_row_number, v_paging_count) AS t(row_number, paging_count)
        LEFT JOIN tb_scm_scan_log_obj_id s ON t.row_number = s.row_number
        LEFT JOIN (
          SELECT s.obj_id AS obj_id, e.row_number
          FROM UNNEST(v_row_number, v_paging_count, v_join_row_number) AS e(row_number, paging_count, join_row_number)
          LEFT JOIN tb_scm_scan_log_obj_id s ON e.join_row_number = s.row_number
        ) e
        ON t.row_number = e.row_number
      ) org
      ORDER BY 1;


  END IF;

END;
$$;


ALTER FUNCTION public.sp_get_event_log_common_obj_id_list(i_event_type text, i_from_obj_id text, i_to_obj_id text, i_limit integer) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_event_log_common_obj_id_list(i_event_type text, i_from_obj_id text, i_to_obj_id text, i_limit integer); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_event_log_common_obj_id_list(i_event_type text, i_from_obj_id text, i_to_obj_id text, i_limit integer) IS '
@brief 로그 사용자 정의 정보 조회
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_event_log_custom_paging_composition(bigint, bigint, integer, boolean); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_event_log_custom_paging_composition(i_min_row_number bigint, i_max_row_number bigint, i_limit integer, is_exists_obj_number boolean) RETURNS TABLE(row_number bigint[], paging_count integer[])
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_row_number bigint[];
	v_paging_count integer[];
	
	v_max_row_number bigint;
	v_min_row_number bigint;
	
	v_adj_count integer;
	v_adj_count2 integer;

BEGIN
	v_max_row_number := COALESCE(i_max_row_number, 0);
	v_min_row_number := COALESCE(i_min_row_number, 0);
	
	IF is_exists_obj_number IS FALSE THEN
		v_adj_count := 0;
		v_adj_count2 := 1;
	ELSE
		v_adj_count := 1;
		v_adj_count2 := 0;
	END IF;
	
	IF (v_min_row_number = 0 AND v_max_row_number = 0) THEN
		RETURN QUERY
			SELECT ARRAY[0]::bigint[], ARRAY[0]::integer[];
	ELSE
		FOR idx IN 1 .. ((v_max_row_number - v_min_row_number + 1) / i_limit) LOOP
			v_row_number := ARRAY_APPEND(v_row_number, (v_max_row_number - (i_limit * idx)) + v_adj_count);
			v_paging_count := ARRAY_APPEND(v_paging_count, i_limit);
		END LOOP;
		
		IF (v_max_row_number - v_min_row_number + 1) % i_limit > 0 THEN
			v_row_number := ARRAY_APPEND(v_row_number, v_min_row_number - v_adj_count2);
			v_paging_count := ARRAY_APPEND(v_paging_count, ((v_max_row_number - v_min_row_number + 1) % i_limit)::integer);
		END IF;
		
		RETURN QUERY
			SELECT v_row_number, v_paging_count;
	END IF;

END;
$$;


ALTER FUNCTION public.sp_get_event_log_custom_paging_composition(i_min_row_number bigint, i_max_row_number bigint, i_limit integer, is_exists_obj_number boolean) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_event_log_custom_paging_composition(i_min_row_number bigint, i_max_row_number bigint, i_limit integer, is_exists_obj_number boolean); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_event_log_custom_paging_composition(i_min_row_number bigint, i_max_row_number bigint, i_limit integer, is_exists_obj_number boolean) IS '
@brief [EMS5-3826] - 로그 페이징 공통 로직
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_file_download_uri(bigint, boolean); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_file_download_uri(i_server_id bigint, i_is_nat boolean) RETURNS TABLE(uri text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
  SELECT
    (CASE WHEN i_is_nat
    THEN 'https://'||ts.public_ip||':'||tsp.port
    ELSE 'https://'||ts.ip||':'||tsp.port
    END) AS uri
  FROM tb_server ts
  JOIN tb_service tss ON tss.server_id = ts.server_id
  JOIN tb_service_port tsp ON tsp.service_type = tss.service_type
  WHERE ts.server_id = i_server_id
    AND tss.service_type = 'FILESERVER-HTTPS'
  ;
END;
$$;


ALTER FUNCTION public.sp_get_file_download_uri(i_server_id bigint, i_is_nat boolean) OWNER TO cppoltp;

--
-- Name: sp_get_file_server_path(bigint, inet, public.en_pkg_type, bigint, public.en_product_id_type, public.en_platform_type, integer, integer, integer, boolean, boolean, integer); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_file_server_path(i_node_id bigint, i_ip_connected inet, i_pkg_type public.en_pkg_type, i_product_pkg_id bigint, i_product_id public.en_product_id_type, i_platform_type public.en_platform_type, i_major integer, i_minor integer, i_bit integer, i_is_server boolean, i_extra boolean, i_release_id integer) RETURNS TABLE(url text)
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_afs_server_id			BIGINT[];
	v_epp_server_id			BIGINT[];

	v_is_nat				TEXT;
	v_lb_http_port			INT;
	v_lb_https_port	   		INT;
	v_file_http_port	 	INT;
	v_file_https_port	   	INT;

	v_virtual_ip			TEXT;

	v_pkg_path				TEXT[];
	v_product_pkg_id 		BIGINT[];
	v_file_url_path			TEXT[];
	v_product_group 		en_product_group_type;
BEGIN

	-- LICENSE

	SELECT p.product_group INTO v_product_group
 	FROM tb_product p JOIN tb_product_license pl
 	ON p.product_id = pl.product_id
	WHERE pl.product_id = i_product_id;

	-- LINUX Agent
	IF EXISTS (SELECT TRUE FROM tb_node WHERE node_id = i_node_id AND platform_id = 'LINUX/UNIX') THEN
		SELECT sp_get_config_group_key_value
			INTO v_virtual_ip
		FROM sp_get_config_group_key_value('NETWORK', 'main_vip', null);
	END IF;

	-->> Aid File Server

	SELECT
		array_agg(svr.server_id)
		INTO v_afs_server_id
	FROM tb_file_update_server file_svr
	INNER JOIN tb_server svr ON svr.server_id = file_svr.server_id
	WHERE file_svr.target_id = i_node_id
	AND file_svr.target_type = 'NODE';


	-->> EPP File Server
	SELECT
		array_agg(svr.server_id)
		INTO v_epp_server_id
	FROM tb_server svr
	INNER JOIN tb_service svc  ON svc.server_id = svr.server_id
	AND svc.service_type='FILESERVER-UPLOAD' AND svc.enabled = TRUE;

	-- Service Port
	SELECT
		is_nat
		, (SELECT tsp.port FROM tb_service_port tsp WHERE tsp.service_type = 'LBDIST-HTTP')
		, (SELECT tsp.port FROM tb_service_port tsp WHERE tsp.service_type = 'LBDIST-HTTPS')
		, (SELECT tsp.port FROM tb_service_port tsp WHERE tsp.service_type = 'FILESERVER-HTTP')
		, (SELECT tsp.port FROM tb_service_port tsp WHERE tsp.service_type = 'FILESERVER-HTTPS')
		INTO v_is_nat, v_lb_http_port, v_lb_https_port, v_file_http_port, v_file_https_port
	FROM
	sp_get_is_nat(i_ip_connected);

	IF i_pkg_type = 'UPDATE_SES' or i_pkg_type = 'UPDATE_OES' THEN
		v_file_http_port := v_lb_http_port;
		v_file_https_port := v_lb_https_port;
	END IF;

	IF(
		i_pkg_type IS NULL AND i_product_pkg_id IS null AND i_product_id IS null
			AND i_platform_type IS null AND i_major IS null AND i_minor IS null AND i_bit IS null
				AND i_is_server IS NULL AND i_extra IS null AND i_release_id IS null
	) THEN
	------------------------------------------------------------------------------------------------------------------
	------------------------------------------------------------------------------------------------------------------

	ELSE
	------------------------------------------------------------------------------------------------------------------
	------------------------------------------------------------------------------------------------------------------
	-- [Platform & Product File]
		/****/
		SELECT
			array_agg(file.product_pkg_id)
			, array_agg(file.path)
			INTO v_product_pkg_id, v_pkg_path
		FROM (
			-----------------------------------------------------------------------------------
			SELECT
				product_pkg.product_id
				, product_pkg.product_pkg_id
				, product_pkg.pkg_type
				, pkg.platform_type
				, pkg.major
				, pkg.major
				, pkg.bit
				, pkg.is_server
				, pkg.release_id
				, product_pkg.path
				, product_pkg.modified_time
				, license.expire_date
			FROM tb_product_pkg product_pkg
			LEFT OUTER JOIN (
				SELECT * FROM tb_pkg_platform pkg_platform INNER JOIN tb_platform platform ON pkg_platform.platform_id = platform.platform_id
			) pkg ON pkg.product_pkg_id = product_pkg.product_pkg_id
			LEFT OUTER JOIN tb_product_license license ON license.product_id = product_pkg.product_id
			WHERE product_pkg.is_removed = FALSE
			-----------------------------------------------------------------------------------
			AND CASE WHEN i_product_id IS NOT NULL THEN
					(product_pkg.product_id = i_product_id AND license.expire_date > now() - interval '90 day')
				ELSE
					1=1
				END
			AND CASE WHEN i_product_pkg_id IS NOT NULL THEN
					product_pkg.product_pkg_id = i_product_pkg_id
				ELSE
					1=1
				END
			AND CASE WHEN i_pkg_type IS NOT NULL THEN
					product_pkg.pkg_type = i_pkg_type
				ELSE
					1=1
				END
			-----------------------------------------------------------------------------------
			AND CASE WHEN i_platform_type IS NOT NULL THEN
					pkg.platform_type = i_platform_type
				ELSE
					1=1
				END
			AND CASE WHEN i_major IS NOT NULL THEN
					pkg.major = i_major
				ELSE
					1=1
				END
			AND CASE WHEN i_minor IS NOT NULL THEN
					pkg.minor = i_minor
				ELSE
					1=1
				END
			AND CASE WHEN i_bit IS NOT NULL THEN
					pkg.bit = i_bit
				ELSE
					1=1
				END
			AND CASE WHEN i_is_server IS NOT NULL THEN
					pkg.is_server = i_is_server
				ELSE
					1=1
				END
			AND CASE WHEN i_is_server AND i_release_id IS NOT NULL THEN
					pkg.release_id = i_release_id
				ELSE
					1=1
				END
			-----------------------------------------------------------------------------------
			ORDER BY product_pkg.modified_time DESC
			LIMIT CASE WHEN (i_pkg_type = 'UPDATE_SES' or i_pkg_type = 'UPDATE_OES') THEN
				     1
				END
			-----------------------------------------------------------------------------------
		) file;


	   	--  Aid File Server or EPP File Server
   		SELECT
			array_agg(DISTINCT final.url)
			INTO v_file_url_path
		FROM(
			SELECT
				CASE WHEN v_is_nat = 'true' THEN
					'http://' || sp_if_condition(v_afs_server_id, svr.public_ip, v_virtual_ip) || ':' || v_file_http_port || '/' || file_pkg.pkg_path
					|| ',https://' || sp_if_condition(v_afs_server_id, svr.public_ip, v_virtual_ip) || ':' || v_file_https_port || '/' || file_pkg.pkg_path
					|| ',http://' || sp_if_condition(v_afs_server_id, svr.ip, v_virtual_ip) || ':' || v_file_http_port || '/' || file_pkg.pkg_path
					|| ',https://' || sp_if_condition(v_afs_server_id, svr.ip, v_virtual_ip) || ':' || v_file_https_port || '/' || file_pkg.pkg_path
				ELSE
					'http://' || sp_if_condition(v_afs_server_id, svr.ip, v_virtual_ip) || ':' || v_file_http_port || '/' || file_pkg.pkg_path
					|| ',https://' || sp_if_condition(v_afs_server_id, svr.ip, v_virtual_ip) || ':' || v_file_https_port || '/' || file_pkg.pkg_path
				END	  AS url
			FROM (
				SELECT
					pkg.pkg_prd_pkg_id
					, pkg.pkg_path
				FROM unnest(v_product_pkg_id, v_pkg_path) AS pkg(pkg_prd_pkg_id, pkg_path)
			)file_pkg, tb_server svr, tb_pkg_server pkg_svr
			WHERE svr.server_id = pkg_svr.server_id
			AND pkg_svr.product_pkg_id = file_pkg.pkg_prd_pkg_id
			AND CASE WHEN i_extra THEN
					svr.server_id = ANY(v_afs_server_id)
				ELSE
					svr.server_id = ANY(v_epp_server_id)
				END
			AND CASE WHEN v_is_nat = 'true' THEN
					svr.public_ip IS NOT NULL
				ELSE
					1 = 1
				END
		)final;
	------------------------------------------------------------------------------------------------------------------
	------------------------------------------------------------------------------------------------------------------
	END IF;

	RETURN QUERY
		SELECT
			string_agg(final.url, ',') AS url
		FROM(
			SELECT
				file.url
				, random() AS rnd_id
			FROM unnest(v_file_url_path) AS file(url)
			ORDER BY rnd_id
		)final
	;
END;
$$;


ALTER FUNCTION public.sp_get_file_server_path(i_node_id bigint, i_ip_connected inet, i_pkg_type public.en_pkg_type, i_product_pkg_id bigint, i_product_id public.en_product_id_type, i_platform_type public.en_platform_type, i_major integer, i_minor integer, i_bit integer, i_is_server boolean, i_extra boolean, i_release_id integer) OWNER TO cppoltp;

--
-- Name: sp_get_file_service_server(public.en_service_type[], bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_file_service_server(i_service_type public.en_service_type[], i_server_id bigint) RETURNS TABLE(service_type public.en_service_type, server_id text, ip text, port text, static text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT
      v.service_type
      , s.server_id::text
      , (CASE
        WHEN (SELECT tc.value FROM tb_config tc
            WHERE tc.config_group = 'NETWORK'
            AND tc.key = 'use_nat') = 'true'
        THEN s.public_ip
        ELSE s.ip
        END) AS ip
      , sp.port::text
    , v.static::text
    FROM tb_server AS s
    INNER JOIN tb_service AS v ON s.server_id = v.server_id
    INNER JOIN tb_service_port AS sp ON v.service_type = sp.service_type
    WHERE s.server_id = i_server_id
      AND v.enabled IS TRUE
      AND v.service_type IN (SELECT UNNEST(i_service_type));

END;
$$;


ALTER FUNCTION public.sp_get_file_service_server(i_service_type public.en_service_type[], i_server_id bigint) OWNER TO cppoltp;

--
-- Name: sp_get_file_service_server_list(public.en_service_type[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_file_service_server_list(i_service_type public.en_service_type[]) RETURNS TABLE(service_type public.en_service_type, server_id text, ip text, port text, static text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT
      v.service_type
      , s.server_id::text
      , (CASE
        WHEN (SELECT tc.value FROM tb_config tc
            WHERE tc.config_group = 'NETWORK'
            AND tc.key = 'use_nat') = 'true'
        THEN s.public_ip
        ELSE s.ip
        END) AS ip
      , sp.port::text
    , v.static::text
    FROM tb_server AS s
    INNER JOIN tb_service AS v ON s.server_id = v.server_id
    INNER JOIN tb_service_port AS sp ON v.service_type = sp.service_type
    WHERE v.enabled IS TRUE
      AND v.service_type IN (SELECT UNNEST(i_service_type));

END;
$$;


ALTER FUNCTION public.sp_get_file_service_server_list(i_service_type public.en_service_type[]) OWNER TO cppoltp;

--
-- Name: sp_get_file_update_server_list(bigint, public.en_file_update_target_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_file_update_server_list(i_target_id bigint, i_target_type public.en_file_update_target_type) RETURNS TABLE(server_id bigint, name text, ip text, is_specified text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT
      info.server_id
      , info.name
      , info.ip
      , info.is_specified::text
    FROM (
      SELECT
        svr.server_id
        , svr.name
        , svr.ip
        , CASE WHEN fus.server_id IS NULL THEN false ELSE true END AS is_specified
      FROM tb_server svr
      LEFT JOIN (
        SELECT insvr.server_id
        FROM tb_file_update_server insvr
        WHERE insvr.target_id = i_target_id
          AND insvr.target_type = i_target_type
      ) fus ON svr.server_id = fus.server_id
    ) info
    JOIN tb_service svc ON info.server_id = svc.server_id
      AND svc.service_type = 'FILESERVER-UPLOAD'
      AND svc.enabled = TRUE
    ORDER BY 1;

END;
$$;


ALTER FUNCTION public.sp_get_file_update_server_list(i_target_id bigint, i_target_type public.en_file_update_target_type) OWNER TO cppoltp;

--
-- Name: sp_get_file_uri(bigint, public.en_pkg_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_file_uri(i_node_id bigint, i_pkg_type public.en_pkg_type) RETURNS TABLE(uri text, file_hash text, file_hash_algorithm text, http_port integer, https_port integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
  SELECT pp.path
    , pp.mpsetup_hash
    , pp.hash_algorithm::TEXT
    , (SELECT tsp.port FROM tb_service_port tsp WHERE tsp.service_type = 'LBDIST-HTTP') AS http_port
    , (SELECT tsp.port FROM tb_service_port tsp WHERE tsp.service_type = 'LBDIST-HTTPS') AS https_port
  FROM tb_product_pkg pp
  WHERE pp.pkg_type = i_pkg_type
    AND pp.is_removed is false
  ORDER BY pp.modified_time DESC LIMIT 1;

END;
$$;


ALTER FUNCTION public.sp_get_file_uri(i_node_id bigint, i_pkg_type public.en_pkg_type) OWNER TO cppoltp;

--
-- Name: sp_get_file_uri2(bigint, public.en_pkg_type, inet); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_file_uri2(i_node_id bigint, i_pkg_type public.en_pkg_type, i_ip_connected inet) RETURNS TABLE(uri text, file_hash text, file_hash_algorithm text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
  RETURN QUERY
  SELECT
    file_info.url
    , hash.file_hash
    , hash.file_hash_algorithm
  FROM (
    SELECT
      product_pkg.mpsetup_hash AS file_hash
      , product_pkg.hash_algorithm::TEXT AS file_hash_algorithm
    FROM tb_product_pkg product_pkg
    WHERE product_pkg.pkg_type = i_pkg_type
      AND product_pkg.is_removed is false
    ORDER BY product_pkg.modified_time DESC LIMIT 1
  ) hash,(
    SELECT
    url
    FROM sp_get_file_server_path(i_node_id, i_ip_connected, i_pkg_type, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL)
  ) file_info
  ;
END;
$$;


ALTER FUNCTION public.sp_get_file_uri2(i_node_id bigint, i_pkg_type public.en_pkg_type, i_ip_connected inet) OWNER TO cppoltp;

