CREATE FUNCTION public.sp_get_get_task_favorite_list() RETURNS TABLE(task_type public.en_task_type, count bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN

  RETURN QUERY
    SELECT t.task_type
         , count(1) count
      FROM tb_task t
  GROUP BY t.task_type
  ORDER BY count DESC, t.task_type
  ;
END;
$$;


