--
-- Name: sp_get_group_agent_summary(bigint[], text[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_group_agent_summary(i_group_id bigint[], i_node_id text[]) RETURNS TABLE(group_id bigint, all_count bigint, connected_count bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_node_id bigint[];
  v_all_count bigint[];
  v_connected_count bigint[];

BEGIN

  FOR i IN array_lower(i_group_id, 1) .. array_upper(i_group_id, 1)
  LOOP

    SELECT string_to_array(i_node_id[i], '||')::bigint[]
    INTO v_node_id;

    SELECT array_append(v_all_count, ras.all_count)
          ,array_append(v_connected_count, ras.connected_count)
    INTO v_all_count
        ,v_connected_count
    FROM sp_get_register_agent_summary(v_node_id) ras;

  END LOOP;

  RETURN QUERY
  SELECT unnest(i_group_id) AS group_id
        ,unnest(v_all_count) AS all_count
        ,unnest(v_connected_count) AS connected_count;

END;
$$;


ALTER FUNCTION public.sp_get_group_agent_summary(i_group_id bigint[], i_node_id text[]) OWNER TO cppoltp;

--
-- Name: sp_get_group_check_list(bigint, boolean, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_group_check_list(i_group_id bigint, i_include_recursive boolean, i_order_type text) RETURNS TABLE(group_id bigint, group_type public.en_group_type, name text, parent bigint, lvl integer, subgroups text[], agent_cnt bigint, group_order bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_update_flag text;

BEGIN

  SELECT value
  INTO v_update_flag
  FROM tb_config
  WHERE config_group = 'GROUP_ORDER'
    AND key = 'update_flag';

  IF v_update_flag = 'ON' THEN

    PERFORM sp_set_group_order();

  END IF;

  IF i_include_recursive THEN

  RETURN QUERY

  WITH RECURSIVE group_list (group_id, name, pgroup_id, group_type, is_removed, level, grp_path, cycle, asc_order, desc_order, user_order, group_order, agent_cnt)
  AS (
  SELECT g.group_id
        ,g.name
        ,g.pgroup_id
        ,g.group_type
        ,g.is_removed
        ,0
        ,ARRAY[g.group_id]
        ,false
        ,ARRAY[RANK() OVER(PARTITION BY g.pgroup_id ORDER BY g.name ASC)] AS asc_order
        ,ARRAY[RANK() OVER(PARTITION BY g.pgroup_id ORDER BY g.name DESC)] AS desc_order
        ,ARRAY[RANK() OVER(PARTITION BY g.pgroup_id ORDER BY g.group_order ASC)] AS user_order
        ,g.group_order
        ,(SELECT count(*) FROM tb_node n WHERE n.group_id = (SELECT sg.group_id FROM tb_group sg WHERE sg.group_type = 'DEFAULT') AND n.is_removed IS NOT true)
  FROM tb_group g
  WHERE g.group_type = 'TOP'
  UNION ALL
  SELECT g.group_id
        ,g.name
        ,g.pgroup_id
        ,g.group_type
        ,g.is_removed
        ,gl.level + 1
        ,gl.grp_path || g.group_id
        ,g.group_id = ANY(gl.grp_path)
        ,gl.asc_order || RANK() OVER(PARTITION BY g.pgroup_id ORDER BY g.name ASC) AS asc_order
        ,gl.desc_order || RANK() OVER(PARTITION BY g.pgroup_id ORDER BY g.name DESC) AS desc_order
        ,gl.user_order || RANK() OVER(PARTITION BY g.pgroup_id ORDER BY g.group_order ASC) AS user_order
        ,g.group_order
        ,COALESCE(n.agent_cnt, 0)
  FROM tb_group g
  JOIN group_list gl
    ON g.pgroup_id = gl.group_id
    AND NOT cycle
  LEFT JOIN (SELECT count(*) AS agent_cnt
                   ,n.group_id
             FROM tb_node n
             WHERE n.is_removed IS NOT true
             GROUP BY n.group_id) n
  ON g.group_id = n.group_id
  WHERE g.group_type = 'GENERAL')
  SELECT gl.group_id AS group_id
        ,gl.group_type AS group_type
        ,gl.name AS name
        ,gl.pgroup_id AS parent
        ,gl.level AS lvl
        ,(SELECT ARRAY_AGG(ARRAY[CAST(g.group_id AS text), g.name]) AS subgroups FROM tb_group g WHERE g.pgroup_id = gl.group_id AND g.is_removed IS NOT true) AS subgroups
        ,gls.agent_cnt::bigint AS agent_cnt
        ,gl.group_order
  FROM group_list gl
  JOIN (SELECT unnest(gls.grp_path) AS grp_path
              ,sum(gls.agent_cnt) AS agent_cnt
        FROM group_list gls
        GROUP BY unnest(gls.grp_path)) gls
  ON gl.group_id = gls.grp_path
  WHERE gl.is_removed IS NOT true
  ORDER BY
    CASE i_order_type
      WHEN 'ASC'
        THEN gl.asc_order
      WHEN 'DESC'
        THEN gl.desc_order
      WHEN 'USER'
        THEN gl.user_order
    END
  ;

  ELSE

  RETURN QUERY

  WITH RECURSIVE group_list (group_id, name, pgroup_id, group_type, is_removed, level, grp_path, cycle, asc_order, desc_order, user_order, group_order, agent_cnt)
  AS (
  SELECT g.group_id
        ,g.name
        ,g.pgroup_id
        ,g.group_type
        ,g.is_removed
        ,0
        ,ARRAY[g.group_id]
        ,false
        ,ARRAY[RANK() OVER(PARTITION BY g.pgroup_id ORDER BY g.name ASC)] AS asc_order
        ,ARRAY[RANK() OVER(PARTITION BY g.pgroup_id ORDER BY g.name DESC)] AS desc_order
        ,ARRAY[RANK() OVER(PARTITION BY g.pgroup_id ORDER BY g.group_order ASC)] AS user_order
        ,g.group_order
        ,(SELECT count(*) FROM tb_node n WHERE n.group_id = (SELECT sg.group_id FROM tb_group sg WHERE sg.group_type = 'DEFAULT') AND n.is_removed IS NOT true)
  FROM tb_group g
  WHERE g.group_id = i_group_id
  UNION ALL
  SELECT g.group_id
        ,g.name
        ,g.pgroup_id
        ,g.group_type
        ,g.is_removed
        ,gl.level + 1
        ,gl.grp_path || g.group_id
        ,g.group_id = ANY(gl.grp_path)
        ,gl.asc_order || RANK() OVER(PARTITION BY g.pgroup_id ORDER BY g.name ASC) AS asc_order
        ,gl.desc_order || RANK() OVER(PARTITION BY g.pgroup_id ORDER BY g.name DESC) AS desc_order
        ,gl.user_order || RANK() OVER(PARTITION BY g.pgroup_id ORDER BY g.group_order ASC) AS user_order
        ,g.group_order
        ,COALESCE(n.agent_cnt, 0)
  FROM tb_group g
  JOIN group_list gl
    ON g.pgroup_id = gl.group_id
    AND NOT cycle
  LEFT JOIN (SELECT count(*) AS agent_cnt
                   ,n.group_id
             FROM tb_node n
             WHERE n.is_removed IS NOT true
             GROUP BY n.group_id) n
  ON g.group_id = n.group_id
  WHERE g.group_type = 'GENERAL')
  SELECT gl.group_id AS group_id
        ,gl.group_type AS group_type
        ,gl.name AS name
        ,gl.pgroup_id AS parent
        ,gl.level AS lvl
        ,(SELECT ARRAY_AGG(ARRAY[CAST(g.group_id AS text), g.name]) AS subgroups FROM tb_group g WHERE g.pgroup_id = gl.group_id AND g.is_removed IS NOT true) AS subgroups
        ,gls.agent_cnt::bigint AS agent_cnt
        ,gl.group_order
  FROM group_list gl
  JOIN (SELECT unnest(gls.grp_path) AS grp_path
              ,sum(gls.agent_cnt) AS agent_cnt
        FROM group_list gls
        GROUP BY unnest(gls.grp_path)) gls
  ON gl.group_id = gls.grp_path
  WHERE gl.is_removed IS NOT true
  ORDER BY
    CASE i_order_type
      WHEN 'ASC'
        THEN gl.asc_order
      WHEN 'DESC'
        THEN gl.desc_order
      WHEN 'USER'
        THEN gl.user_order
    END
  ;

  END IF;

END;
$$;


ALTER FUNCTION public.sp_get_group_check_list(i_group_id bigint, i_include_recursive boolean, i_order_type text) OWNER TO cppoltp;

--
-- Name: sp_get_group_list(bigint, boolean, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_group_list(i_group_id bigint, i_include_recursive boolean, i_order_type text, i_admin_id text) RETURNS TABLE(group_id bigint, group_type public.en_group_type, name text, parent bigint, lvl integer, subgroups text[], agent_cnt bigint, group_order bigint, is_enable integer)
    LANGUAGE plpgsql
    AS $$
 
DECLARE
 
  v_update_flag text;
  v_admin_group text;
  v_top_group text;
  v_group_id bigint[];
  v_sub_group_id bigint[];
  v_physical_group_id bigint;
  v_cloud_group_id bigint;
 
BEGIN

 
  SELECT value
  INTO v_update_flag
  FROM tb_config
  WHERE config_group = 'GROUP_ORDER'
    AND key = 'update_flag';
 
  IF v_update_flag = 'ON' THEN
 
    PERFORM sp_set_group_order();
 
  END IF;
 
  SELECT admin_group
  INTO v_admin_group
  FROM tb_admin
  WHERE admin_id = i_admin_id;
 
  SELECT g.group_id::text
  INTO v_top_group
  FROM tb_group g
  WHERE g.group_type = 'TOP';
  
  IF i_admin_id IS NULL OR v_admin_group = v_top_group THEN
 
    RETURN QUERY
 
    WITH RECURSIVE group_list (group_id, name, pgroup_id, group_type, is_removed, level, grp_path, cycle, asc_order, desc_order, user_order, group_order, agent_cnt)
    AS (
      SELECT g.group_id
            ,g.name
            ,g.pgroup_id
            ,g.group_type
            ,g.is_removed
            ,0
            ,ARRAY[g.group_id]
            ,false
            ,ARRAY[RANK() OVER(PARTITION BY g.pgroup_id ORDER BY g.name ASC)] AS asc_order
            ,ARRAY[RANK() OVER(PARTITION BY g.pgroup_id ORDER BY g.name DESC)] AS desc_order
            ,ARRAY[RANK() OVER(PARTITION BY g.pgroup_id ORDER BY g.group_order ASC)] AS user_order
            ,g.group_order
            ,0::BIGINT
      FROM tb_group g
      WHERE CASE WHEN i_include_recursive
                 THEN g.group_type = 'TOP'
                 ELSE g.group_id = i_group_id
            END
      UNION ALL
      SELECT g.group_id
            ,g.name
            ,g.pgroup_id
            ,g.group_type
            ,g.is_removed
            ,gl.level + 1
            ,gl.grp_path || g.group_id
            ,g.group_id = ANY(gl.grp_path)
            ,gl.asc_order || RANK() OVER(PARTITION BY g.pgroup_id ORDER BY (CASE WHEN g.group_type IN ('PHYSICAL','DEFAULT') THEN 0 ELSE 1 END), (CASE WHEN g.group_type = 'GENERAL' THEN 0 ELSE g.group_order END), g.name ASC) AS asc_order
            ,gl.desc_order || RANK() OVER(PARTITION BY g.pgroup_id ORDER BY (CASE WHEN g.group_type IN ('PHYSICAL','DEFAULT') THEN 0 ELSE 1 END), (CASE WHEN g.group_type = 'GENERAL' THEN 0 ELSE g.group_order END), g.name DESC) AS desc_order
            ,gl.user_order || RANK() OVER(PARTITION BY g.pgroup_id ORDER BY (CASE WHEN g.group_type IN ('PHYSICAL','DEFAULT') THEN 0 ELSE 1 END), g.group_order ASC) AS user_order
            ,g.group_order
            ,COALESCE(n.agent_cnt, 0)
      FROM tb_group g
      JOIN group_list gl
        ON g.pgroup_id = gl.group_id
        AND NOT cycle
      LEFT JOIN (SELECT
                    "group".group_id AS group_id
                    , COUNT(n.node_id) AS agent_cnt
                 FROM
                    tb_group "group"
                    INNER JOIN tb_node n ON n.group_id = "group".group_id AND n.is_removed IS FALSE AND n.platform_id IS NOT NULL
                    -- Works Number : CWPP-2629
                    -- agent 목록은 미지원 플랫폼 제외하고 출력. 카운트 일치를 위해 그룹별 에이전트 수 출력시에도 동일 처리
                    INNER JOIN tb_platform p on n.platform_id = p.platform_id and p.is_supported = true
                 GROUP BY
                    "group".group_id) n
      ON g.group_id = n.group_id
      WHERE g.group_type NOT IN ('TOP')
        AND g.is_removed = false
    )
      SELECT gl.group_id AS group_id
            ,gl.group_type AS group_type
            ,gl.name AS name
            ,gl.pgroup_id AS parent
            ,gl.level AS lvl
            ,sgl.subgroups
            ,gls.agent_cnt::bigint AS agent_cnt
            ,gl.group_order
            ,1
      FROM group_list gl
      JOIN (SELECT unnest(gls.grp_path) AS grp_path
                  ,sum(gls.agent_cnt) AS agent_cnt
             FROM group_list gls
            GROUP BY unnest(gls.grp_path)) gls
      ON gl.group_id = gls.grp_path
      LEFT JOIN  (SELECT ARRAY_AGG(ARRAY[CAST(sgl.group_id AS text), sgl.name]) AS subgroups, sgl.pgroup_id
                FROM group_list sgl group by sgl.pgroup_id) sgl
      ON gl.group_id = sgl.pgroup_id
     WHERE gl.is_removed = false
      ORDER BY
        CASE i_order_type
          WHEN 'ASC'
            THEN gl.asc_order
          WHEN 'DESC'
            THEN gl.desc_order
          WHEN 'USER'
            THEN gl.user_order
        END
      ;
 
  ELSE
 
    WITH RECURSIVE sub_group_id (group_id, pgroup_id) AS 
    (
      SELECT tg.group_id
              ,tg.pgroup_id
      FROM (
          SELECT tg.group_id
              ,tg.pgroup_id
          FROM tb_group tg
          WHERE tg.is_removed = FALSE
            AND tg.group_id = ANY(string_to_array(v_admin_group,',')::bigint[])
              ) tg
      UNION DISTINCT
      SELECT tg.group_id
              ,tg.pgroup_id
      FROM tb_group tg 
          INNER JOIN sub_group_id vgi
              ON vgi.group_id = tg.pgroup_id
      WHERE tg.is_removed = FALSE
    )
    SELECT ARRAY_AGG(vgi.group_id) AS group_id
    INTO v_sub_group_id
    FROM sub_group_id vgi;
    
    SELECT tg.group_id
    INTO v_physical_group_id
    FROM tb_group tg
    WHERE tg.group_type = 'PHYSICAL'
    ORDER BY tg.group_id DESC
    LIMIT 1;
    
    SELECT tg.group_id
    INTO v_cloud_group_id
    FROM tb_group tg
    WHERE tg.group_type = 'CLOUD'
    ORDER BY tg.group_id DESC
    LIMIT 1;
  
    SELECT string_to_array(v_admin_group, ',')::bigint[]
    INTO v_group_id;
 
    RETURN QUERY
    WITH v_group_list AS (
        /* TOP, 물리, 클라우드 그룹 조회 */
         WITH v_top_group AS (
            WITH RECURSIVE T(group_id, lvl, group_path, group_order, asc_order, desc_order, user_order, cycle) AS (
                SELECT   tg.group_id
                        ,0 AS lvl
                        ,ARRAY[tg.group_id] AS group_path
                        ,tg.group_order
                        ,ARRAY[RANK() OVER(PARTITION BY tg.pgroup_id ORDER BY tg.name ASC)] AS asc_order
                        ,ARRAY[RANK() OVER(PARTITION BY tg.pgroup_id ORDER BY tg.name DESC)] AS desc_order
                        ,ARRAY[RANK() OVER(PARTITION BY tg.pgroup_id ORDER BY tg.group_order ASC)] AS user_order
                        ,FALSE
                FROM    tb_group tg
                WHERE   tg.group_type = 'TOP'
                AND     tg.is_removed = FALSE
                UNION ALL
                SELECT   tg.group_id
                        ,t.lvl + 1 AS lvl
                        ,t.group_path || tg.group_id AS group_path
                        ,tg.group_order
                        ,t.asc_order || RANK() OVER(PARTITION BY tg.pgroup_id ORDER BY ( CASE WHEN tg.group_type IN ('PHYSICAL','DEFAULT', 'CLOUD') THEN  tg.group_order END ) ASC  , tg.name ASC) AS asc_order
                        ,t.desc_order || RANK() OVER(PARTITION BY tg.pgroup_id ORDER BY ( CASE WHEN tg.group_type IN ('PHYSICAL','DEFAULT', 'CLOUD') THEN  tg.group_order END ) DESC , tg.name DESC) AS desc_order
                        ,t.user_order || RANK() OVER(PARTITION BY tg.pgroup_id ORDER BY tg.group_order ASC) AS user_order
                        ,tg.group_id = ANY(t.group_path) AS CYCLE
                FROM    tb_group tg
                INNER
                    JOIN    T t
                    ON      tg.pgroup_id = t.group_id
                    AND     tg.is_removed = FALSE
                    AND     tg.group_type NOT IN ('GENERAL', 'CLOUD_AWS', 'CLOUD_AZURE', 'CLOUD_AZURE_SUBSCRIPTION', 'CLOUD_AZURE_RESOURCE_GROUP', 'DEFAULT', 'CLOUD_ALIBABA')
                    AND
                        CASE WHEN 2 = ANY(v_group_id) THEN tg.group_type != 'PHYSICAL'
                             ELSE TRUE
                             END
                    AND
                        CASE WHEN 4 = ANY(v_group_id) THEN tg.group_type != 'CLOUD'
                             ELSE TRUE
                             END
                    AND     NOT CYCLE
            )
            SELECT *
            FROM T
         ),
         /* 본인 그룹 조회 */
         v_own_group AS (
            WITH RECURSIVE T(group_id, lvl, group_path, group_order, asc_order, desc_order, user_order, cycle) AS (
                SELECT   tg.group_id
                        , CASE WHEN tg.group_type IN ('PHYSICAL', 'CLOUD') THEN 1
                               ELSE 2
                               END AS lvl
                        ,ARRAY[tg.group_id] AS group_path
                        ,tg.group_order
                        ,ARRAY[RANK() OVER(PARTITION BY tg.pgroup_id ORDER BY tg.name ASC)] AS asc_order
                        ,ARRAY[RANK() OVER(PARTITION BY tg.pgroup_id ORDER BY tg.name DESC)] AS desc_order
                        ,ARRAY[RANK() OVER(PARTITION BY tg.pgroup_id ORDER BY tg.group_order ASC)] AS user_order
                        ,FALSE
                FROM    tb_group tg
                WHERE   tg.group_id = ANY(v_group_id)
                AND     tg.is_removed = FALSE
                UNION ALL
                SELECT   tg.group_id
                        ,t.lvl + 1 AS lvl
                        ,t.group_path || tg.group_id AS group_path
                        ,tg.group_order
                        ,t.asc_order || RANK() OVER(PARTITION BY tg.pgroup_id ORDER BY ( CASE WHEN tg.group_type IN ('PHYSICAL','DEFAULT', 'CLOUD') THEN  tg.group_order END ) ASC  , tg.name ASC) AS asc_order
                        ,t.desc_order || RANK() OVER(PARTITION BY tg.pgroup_id ORDER BY ( CASE WHEN tg.group_type IN ('PHYSICAL','DEFAULT', 'CLOUD') THEN  tg.group_order END ) DESC , tg.name DESC) AS desc_order
                        ,t.user_order || RANK() OVER(PARTITION BY tg.pgroup_id ORDER BY tg.group_order ASC) AS user_order
                        ,tg.group_id = ANY(t.group_path) AS CYCLE
                FROM    tb_group tg
                INNER
                    JOIN    T t
                    ON      tg.pgroup_id = t.group_id
                    AND     tg.is_removed = FALSE
                    AND     NOT CYCLE
            )
            SELECT *
            FROM T
         ),
         /* 그룹별 에이전트 카운트 조회 */
         -- Works Number : CWPP-2629
         -- agent 목록은 미지원 플랫폼 제외하고 출력. 카운트 일치를 위해 그룹별 에이전트 수 출력시에도 동일 처리
         v_group_agent_count AS (
            SELECT   tg.group_id
                    ,tg.pgroup_id
                    ,count(tnp.node_id) AS group_agent_count
                    ,count(CASE WHEN tnp.is_server = TRUE THEN 1 END) AS group_server_agent_count
            FROM    tb_group tg
            LEFT JOIN   
                (   select tn.group_id, tn.node_id, tp.is_server
                    from tb_node tn, tb_platform tp
                    where tn.platform_id = tp.platform_id
                    AND     tp.is_supported IS true
                    AND     tn.is_removed = FALSE
                ) tnp
                ON      tg.group_id = tnp.group_id
            where tg.is_removed = FALSE
            GROUP BY    tg.group_id, tg.pgroup_id
        ),
        /* 특정 그룹 대상 상위/하위 그룹 목록 조회 */
        v_group_list AS (
            /* 특정 그룹의 하위 그룹 목록 조회 */
            WITH
            RECURSIVE v_sub_group_list (group_id, name, pgroup_id, group_type, group_path, is_enable, cycle) AS (
                SELECT   tg.group_id
                        ,tg.name
                        ,tg.pgroup_id
                        ,tg.group_type
                        ,ARRAY[tg.group_id] AS group_path
                        ,1 AS is_enable
                        ,FALSE AS CYCLE
                FROM    tb_group tg
                WHERE   tg.pgroup_id IN (SELECT * FROM unnest(v_group_id))
                AND     tg.is_removed = FALSE
                UNION ALL
                SELECT   tg.group_id
                        ,tg.name
                        ,tg.pgroup_id
                        ,tg.group_type
                        ,vsgl.group_path || tg.group_id AS group_path
                        ,1 AS is_enable
                        ,tg.group_id = ANY(vsgl.group_path) AS cycle
                FROM    tb_group tg
                INNER
                    JOIN    v_sub_group_list vsgl
                    ON      tg.pgroup_id = vsgl.group_id
                    AND     tg.is_removed = FALSE
                    AND     NOT CYCLE
            ),
            /* 특정 그룹을 포함한 상위 그룹 목록 조회 */
            v_parent_group_list AS (
                WITH RECURSIVE v_parent_group_list (group_id, name, pgroup_id, group_type, group_path, is_enable, cycle) AS (
                    SELECT   tg.group_id
                            ,tg.name
                            ,tg.pgroup_id
                            ,tg.group_type
                            ,ARRAY[tg.group_id] AS group_path
                            ,1 AS is_enable
                            ,FALSE AS cycle
                    FROM    tb_group tg
                    WHERE   tg.group_id IN (SELECT * FROM unnest(v_group_id))
                    AND     tg.is_removed = FALSE
                    UNION ALL
                    SELECT   tg.group_id
                            ,tg.name
                            ,tg.pgroup_id
                            ,tg.group_type
                            ,tg.group_id || vpgl.group_path AS group_path
                            ,0 AS is_enable
                            ,tg.group_id = ANY(vpgl.group_path) AS cycle
                    FROM    tb_group tg
                    INNER
                        JOIN    v_parent_group_list vpgl
                        ON      tg.group_id = vpgl.pgroup_id
                        AND     tg.is_removed = FALSE
                        AND     NOT CYCLE
                )
                SELECT  *
                FROM    v_parent_group_list
            )
            SELECT  vpgl.group_id, vpgl.name, vpgl.pgroup_id, vpgl.group_type, vpgl.is_enable
            FROM    v_parent_group_list vpgl
            UNION
            SELECT  vsgl.group_id, vsgl.name, vsgl.pgroup_id, vsgl.group_type, vsgl.is_enable
            FROM    v_sub_group_list vsgl
        ),
        /* 하위 그룹 그룹아이디, 그룹명 pair 조회 */
        v_group_subgroups AS (
            SELECT   vgl.pgroup_id
                    , CASE
                           /* 시스템 그룹이며, 소유권한의 그룹에 기본그룹이 포함되어있는경우 */
                           WHEN vgl.pgroup_id = v_physical_group_id
                            AND (SELECT EXISTS (SELECT 1 FROM v_own_group own WHERE own.group_id IN (SELECT tg.group_id FROM tb_group tg WHERE tg.group_type = 'DEFAULT')))
                            THEN (SELECT ARRAY_AGG(ARRAY[CAST(own.group_id AS text) , tg.name]) FROM v_own_group own INNER JOIN tb_group tg ON own.group_id = tg.group_id WHERE own.lvl = 2 AND tg.group_type IN ('DEFAULT', 'GENERAL'))
                            
                           /* 시스템 그룹이며, 소유권한의 그룹에 기본그룹이 포함되어있지 않은경우 */
                           WHEN vgl.pgroup_id = v_physical_group_id
                            AND (SELECT EXISTS (SELECT 1 FROM v_own_group own WHERE own.group_id IN (SELECT tg.group_id FROM tb_group tg WHERE tg.group_type = 'DEFAULT'))) = FALSE
                            THEN (SELECT ARRAY_AGG(ARRAY[CAST(own.group_id AS text) , tg.name]) FROM v_own_group own INNER JOIN tb_group tg ON own.group_id = tg.group_id WHERE own.lvl = 2 AND tg.group_type IN ('GENERAL'))
                            
                            
                           /* 계정연동 그룹인경우 */
                           WHEN vgl.pgroup_id = v_cloud_group_id
                            THEN (SELECT ARRAY_AGG(ARRAY[CAST(own.group_id AS text) , tg.name]) FROM v_own_group own INNER JOIN tb_group tg ON own.group_id = tg.group_id WHERE own.lvl = 2 AND tg.group_type IN ('CLOUD_AWS', 'CLOUD_AZURE', 'CLOUD_AZURE_SUBSCRIPTION', 'CLOUD_AZURE_RESOURCE_GROUP', 'CLOUD_ALIBABA'))
                            
                           /* 최상위 그룹이며, 둘 다 소유권한이 있는 경우 */
                           WHEN vgl.pgroup_id = v_top_group::bigint
                            AND (SELECT EXISTS (SELECT 1 FROM v_own_group own WHERE own.group_id IN (SELECT tg.group_id FROM tb_group tg WHERE tg.group_type = 'PHYSICAL'))) = TRUE 
                            AND (SELECT EXISTS (SELECT 1 FROM v_own_group own WHERE own.group_id IN (SELECT tg.group_id FROM tb_group tg WHERE tg.group_type = 'CLOUD'))) = TRUE
                            THEN (SELECT ARRAY_AGG(ARRAY[CAST(tg.group_id AS text) , tg.name]) FROM tb_group tg WHERE tg.group_type IN ('PHYSICAL', 'CLOUD'))
                            
                           /* 최상위 그룹이며, 소유권한에 시스템그룹이 없지만 하위그룹은 존재하고, 계정연동그룹 권한은 없지만 하위그룹은 존재하는 경우*/
                           WHEN vgl.pgroup_id = v_top_group::bigint
                            AND (SELECT EXISTS (SELECT 1 FROM v_own_group own WHERE own.group_id IN (SELECT tg.group_id FROM tb_group tg WHERE tg.group_type = 'PHYSICAL'))) = FALSE 
                            AND (SELECT EXISTS (SELECT 1 FROM v_own_group own WHERE own.group_id = ANY(SELECT gg.group_id FROM tb_group gg WHERE gg.group_type IN ('DEFAULT','GENERAL')))) = TRUE
                            AND (SELECT EXISTS (SELECT 1 FROM v_own_group own WHERE own.group_id IN (SELECT tg.group_id FROM tb_group tg WHERE tg.group_type = 'CLOUD'))) = FALSE
                            AND (SELECT EXISTS (SELECT 1 FROM v_own_group own WHERE own.group_id = ANY(SELECT gg.group_id FROM tb_group gg WHERE gg.group_type IN ('CLOUD_AWS', 'CLOUD_AZURE', 'CLOUD_AZURE_SUBSCRIPTION', 'CLOUD_AZURE_RESOURCE_GROUP', 'CLOUD_ALIBABA')))) = TRUE
                            THEN (SELECT ARRAY_AGG(ARRAY[CAST(tg.group_id AS text) , tg.name]) FROM tb_group tg WHERE tg.group_type IN ('PHYSICAL', 'CLOUD'))
                            
                           /* 최상위 그룹이며, 소유권한에 시스템그룹 권한이 없지만 하위그룹은 존재하고, 계정연동그룹 권한은 있는 경우 */
                           WHEN vgl.pgroup_id = v_top_group::bigint
                            AND (SELECT EXISTS (SELECT 1 FROM v_own_group own WHERE own.group_id IN (SELECT tg.group_id FROM tb_group tg WHERE tg.group_type = 'PHYSICAL'))) = FALSE 
                            AND (SELECT EXISTS (SELECT 1 FROM v_own_group own WHERE own.group_id = ANY(SELECT gg.group_id FROM tb_group gg WHERE gg.group_type IN ('DEFAULT','GENERAL')))) = TRUE
                            AND (SELECT EXISTS (SELECT 1 FROM v_own_group own WHERE own.group_id IN (SELECT tg.group_id FROM tb_group tg WHERE tg.group_type = 'CLOUD'))) = TRUE
                            THEN (SELECT ARRAY_AGG(ARRAY[CAST(tg.group_id AS text) , tg.name]) FROM tb_group tg WHERE tg.group_type IN ('PHYSICAL', 'CLOUD'))
                            
                           /* 최상위 그룹이며, 소유권한에 시스템그룹 권한은 있고 계정연동 권한이 없는 경우*/
                           WHEN vgl.pgroup_id = v_top_group::bigint
                            AND (SELECT EXISTS (SELECT 1 FROM v_own_group own WHERE own.group_id IN (SELECT tg.group_id FROM tb_group tg WHERE tg.group_type = 'CLOUD'))) = FALSE 
                            AND (SELECT EXISTS (SELECT 1 FROM v_own_group own WHERE own.group_id = ANY(SELECT gg.group_id FROM tb_group gg WHERE gg.group_type IN ('CLOUD_AWS', 'CLOUD_AZURE', 'CLOUD_AZURE_SUBSCRIPTION', 'CLOUD_AZURE_RESOURCE_GROUP', 'CLOUD_ALIBABA')))) = TRUE
                            AND (SELECT EXISTS (SELECT 1 FROM v_own_group own WHERE own.group_id IN (SELECT tg.group_id FROM tb_group tg WHERE tg.group_type = 'PHYSICAL'))) = TRUE
                            THEN (SELECT ARRAY_AGG(ARRAY[CAST(tg.group_id AS text) , tg.name]) FROM tb_group tg WHERE tg.group_type IN ('PHYSICAL', 'CLOUD'))
                            
                           /* 최상위 그룹이며, 소유권한에 시스템그룹만 필요한 경우 */
                           WHEN vgl.pgroup_id = v_top_group::bigint
                            AND (SELECT EXISTS (SELECT 1 FROM v_own_group own WHERE own.group_id IN (SELECT tg.group_id FROM tb_group tg WHERE tg.group_type = 'PHYSICAL'))) = FALSE 
                            AND (SELECT EXISTS (SELECT 1 FROM v_own_group own WHERE own.group_id = ANY(SELECT gg.group_id FROM tb_group gg WHERE gg.group_type IN ('DEFAULT','GENERAL')))) = TRUE
                            AND (SELECT EXISTS (SELECT 1 FROM v_own_group own WHERE own.group_id IN (SELECT tg.group_id FROM tb_group tg WHERE tg.group_type = 'CLOUD'))) = FALSE 
                            AND (SELECT EXISTS (SELECT 1 FROM v_own_group own WHERE own.group_id = ANY(SELECT gg.group_id FROM tb_group gg WHERE gg.group_type IN ('CLOUD_AWS', 'CLOUD_AZURE', 'CLOUD_AZURE_SUBSCRIPTION', 'CLOUD_AZURE_RESOURCE_GROUP', 'CLOUD_ALIBABA')))) = FALSE
                            THEN (SELECT ARRAY_AGG(ARRAY[CAST(tg.group_id AS text) , tg.name]) FROM tb_group tg WHERE tg.group_type IN ('PHYSICAL'))
                            
                           /* 최상위 그룹이며, 소유권한에 계정연동만 만 필요한 경우 */
                           WHEN vgl.pgroup_id = v_top_group::bigint
                            AND (SELECT EXISTS (SELECT 1 FROM v_own_group own WHERE own.group_id IN (SELECT tg.group_id FROM tb_group tg WHERE tg.group_type = 'PHYSICAL'))) = FALSE 
                            AND (SELECT EXISTS (SELECT 1 FROM v_own_group own WHERE own.group_id = ANY(SELECT gg.group_id FROM tb_group gg WHERE gg.group_type IN ('DEFAULT','GENERAL')))) = FALSE
                            AND (SELECT EXISTS (SELECT 1 FROM v_own_group own WHERE own.group_id IN (SELECT tg.group_id FROM tb_group tg WHERE tg.group_type = 'CLOUD'))) = FALSE
                            AND (SELECT EXISTS (SELECT 1 FROM v_own_group own WHERE own.group_id = ANY(SELECT gg.group_id FROM tb_group gg WHERE gg.group_type IN ('CLOUD_AWS', 'CLOUD_AZURE', 'CLOUD_AZURE_SUBSCRIPTION', 'CLOUD_AZURE_RESOURCE_GROUP', 'CLOUD_ALIBABA')))) = TRUE
                            THEN (SELECT ARRAY_AGG(ARRAY[CAST(tg.group_id AS text) , tg.name]) FROM tb_group tg WHERE tg.group_type IN ('CLOUD'))

                           /* 그 외*/
                           ELSE ARRAY_AGG(ARRAY[CAST(vgl.group_id AS text), vgl.name]) 
                           END AS subgroups
            FROM    v_group_list vgl
            GROUP BY
                    vgl.pgroup_id
        )
        /* 특정 그룹 포함 상/하위 그룹 조회 : 그룹레벨, 그룹패스, 하위그룹pair, 정렬순서 포함 */
        SELECT   vgl.group_id
                ,vgl.name
                ,vgl.pgroup_id AS parent
                ,vgl.group_type
                ,vgl.is_enable
                ,vtg.lvl
                ,COALESCE(CASE WHEN vgl.group_type::TEXT NOT LIKE 'CLOUD%' THEN vgac.group_server_agent_count ELSE group_agent_count END) AS group_agent_count
                ,vtg.group_path
                ,vgs.subgroups
                ,vtg.group_order
                ,vtg.asc_order
                ,vtg.desc_order
                ,vtg.user_order
        FROM    v_group_list vgl
        INNER
            JOIN    v_top_group vtg
            ON      vgl.group_id = vtg.group_id
        LEFT
            JOIN    v_group_subgroups vgs
            ON      vgl.group_id = vgs.pgroup_id
        LEFT
            JOIN    v_group_agent_count vgac
            ON      vgl.group_id = vgac.group_id
            
        UNION
        
        SELECT   vgl.group_id
                ,vgl.name
                ,CASE WHEN vog.lvl = 2 AND vgl.group_type = 'GENERAL' THEN v_physical_group_id
                      WHEN vog.lvl = 2 AND vgl.group_type IN ('CLOUD_AWS', 'CLOUD_AZURE', 'CLOUD_AZURE_SUBSCRIPTION', 'CLOUD_AZURE_RESOURCE_GROUP', 'CLOUD_ALIBABA') THEN v_cloud_group_id
                      ELSE vgl.pgroup_id END AS parent
                ,vgl.group_type
                ,vgl.is_enable
                ,vog.lvl
                ,COALESCE(CASE WHEN vgl.group_type::TEXT NOT LIKE 'CLOUD%' THEN vgac.group_server_agent_count ELSE group_agent_count END) AS group_agent_count
                ,vog.group_path
                ,vgs.subgroups
                ,vog.group_order
                ,vog.asc_order
                ,vog.desc_order
                ,vog.user_order
        FROM    v_group_list vgl
        INNER
            JOIN    v_own_group vog
            ON      vgl.group_id = vog.group_id
        LEFT
            JOIN    v_group_subgroups vgs
            ON      vgl.group_id = vgs.pgroup_id
        LEFT
            JOIN    v_group_agent_count vgac
            ON      vgl.group_id = vgac.group_id
    )
    /* 특정 그룹 포함 상/하위 그룹 조회 : 각 그룹 별 에이전트 카운트 집계 포함 및 order type에 대한 정렬 */
    SELECT   vgl.group_id
            ,vgl.group_type
            ,vgl.name
            ,vgl.parent
            ,vgl.lvl
            ,vgl.subgroups
            , v_group_count.group_agent_count::bigint AS agent_cnt
            ,vgl.group_order
            ,vgl.is_enable
    FROM    v_group_list vgl
    LEFT
        JOIN (
            SELECT  g.group_id AS group_id
                    , CASE WHEN g.group_type = 'TOP' THEN (SELECT count(*) FROM tb_node n WHERE n.is_removed IS FALSE AND n.group_id = ANY(SELECT UNNEST(v_sub_group_id)))
                           WHEN g.group_type = 'CLOUD' THEN (SELECT count(*) FROM tb_node n INNER JOIN tb_group tg ON n.group_id = tg.group_id WHERE n.is_removed IS FALSE AND n.group_id = ANY(SELECT UNNEST(v_sub_group_id)) AND tg.group_type IN ('CLOUD_AWS', 'CLOUD_AZURE', 'CLOUD_AZURE_SUBSCRIPTION', 'CLOUD_AZURE_RESOURCE_GROUP', 'CLOUD_ALIBABA'))
                           WHEN g.group_type = 'PHYSICAL' THEN (SELECT count(*) FROM tb_node n INNER JOIN tb_group tg ON n.group_id = tg.group_id  WHERE n.is_removed IS FALSE AND n.group_id = ANY(SELECT UNNEST(v_sub_group_id)) AND tg.group_type IN ('GENERAL', 'DEFAULT'))
                           ELSE 0 END AS group_agent_count
            FROM    tb_group g
            WHERE   g.group_type IN ('TOP', 'CLOUD', 'PHYSICAL')
        
            UNION        
            
            SELECT  unnest(vgl.group_path) AS group_id
                    , sum(vgl.group_agent_count) AS group_agent_count
            FROM    v_group_list vgl
            WHERE   vgl.group_type NOT IN ('TOP', 'CLOUD', 'PHYSICAL')
            GROUP BY
                    UNNEST(vgl.group_path)
        ) v_group_count
        ON vgl.group_id = v_group_count.group_id
    WHERE   CASE WHEN i_include_recursive THEN TRUE ELSE (vgl.parent = i_group_id OR vgl.group_id = i_group_id) END /* 반복 제외 시 입력 group_id 기준으로 조회 */
    ORDER BY
            vgl.lvl ASC,            
            CASE i_order_type
                WHEN 'ASC'  THEN vgl.asc_order
                WHEN 'DESC' THEN vgl.desc_order
                WHEN 'USER' THEN vgl.user_order
            END
    ;
 
  END IF;
 
END;
$$;


ALTER FUNCTION public.sp_get_group_list(i_group_id bigint, i_include_recursive boolean, i_order_type text, i_admin_id text) OWNER TO cppoltp;

--
-- Name: sp_get_group_name_path(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_group_name_path(i_group_id bigint) RETURNS TABLE(group_path text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
  WITH RECURSIVE tree AS (
    SELECT
     g.group_id
     , '/' || name AS group_path
    FROM tb_group AS g
    WHERE group_type  = 'TOP'
    AND is_removed = false
    UNION ALL
    SELECT
     g.group_id
    , tree.group_path || '/' || g.name
    FROM tb_group AS g
    INNER JOIN tree
    ON g.pgroup_id  = tree.group_id
    AND g.is_removed = false
  )
  SELECT
    tree.group_path
  FROM tree
  where group_id = i_group_id;

END;
$$;


ALTER FUNCTION public.sp_get_group_name_path(i_group_id bigint) OWNER TO cppoltp;

--
-- Name: sp_get_group_name_path(bigint, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_group_name_path(i_group_id bigint, i_text text) RETURNS TABLE(group_path text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
  WITH RECURSIVE tree AS (
    SELECT
     tb_group.group_id
     , i_text || REPLACE(name, '/', '\/') AS group_path
    FROM tb_group
    WHERE group_type  = 'TOP'
    AND is_removed = false
    UNION ALL
    SELECT
     tb_group.group_id
    , tree.group_path || i_text || REPLACE(tb_group.name, '/', '\/')
    FROM tb_group
    INNER JOIN tree
    ON tb_group.pgroup_id  = tree.group_id
    AND tb_group.is_removed = false
  )
  SELECT
    tree.group_path
  FROM tree
  where group_id = i_group_id;

END;
$$;


ALTER FUNCTION public.sp_get_group_name_path(i_group_id bigint, i_text text) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_group_name_path(i_group_id bigint, i_text text); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_group_name_path(i_group_id bigint, i_text text) IS '
@brief 그룹명경로 가져오기
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_group_name_path_all(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_group_name_path_all() RETURNS TABLE(group_id bigint, group_path text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
  WITH RECURSIVE tree AS (
  SELECT g.group_id
        ,'/' || g.name AS group_path
  FROM tb_group g
  WHERE g.group_type  = 'TOP'
    AND g.is_removed = false
  UNION ALL
  SELECT g.group_id
        ,t.group_path || '/' || g.name
  FROM tb_group g
  INNER JOIN tree t
  ON g.pgroup_id  = t.group_id
    AND g.is_removed = false
  )
  SELECT t.group_id,
   t.group_path
  FROM tree t;

END;
$$;


ALTER FUNCTION public.sp_get_group_name_path_all() OWNER TO cppoltp;

--
-- Name: sp_get_group_node_array(bigint[], public.en_platform_type[], text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_group_node_array(i_group_id bigint[], i_platform_type public.en_platform_type[], i_admin_id text) RETURNS TABLE(group_id text, node_id text)
    LANGUAGE plpgsql
    AS $$
#variable_conflict use_column
DECLARE
BEGIN
  RETURN QUERY
  WITH group_node AS (
    SELECT g.group_id, unnest(sp_get_group_node_list(g.group_id, TRUE, i_admin_id)::BIGINT[]) AS node_id
    FROM tb_group g
    WHERE is_removed IS FALSE AND group_id = ANY(i_group_id)
  ),
  filtered AS (
    SELECT gn.group_id, gn.node_id
    FROM group_node gn
      JOIN tb_node n ON n.node_id = gn.node_id
      JOIN tb_platform p ON n.platform_id = p.platform_id
    WHERE n.is_removed IS FALSE
      AND p.is_supported IS TRUE
      AND p.platform_type = ANY(CASE WHEN i_platform_type IS NULL THEN enum_range(NULL::en_platform_type) ELSE i_platform_type END)
  )
  SELECT s.group_id, s.node_id
  FROM (
    SELECT array_agg(t.group_id)::TEXT AS group_id, array_agg(t.node_id) ::TEXT AS node_id
    FROM (
      SELECT f.group_id, array_to_string(array_agg(f.node_id),'||') AS node_id
      FROM filtered f
      GROUP BY f.group_id
    ) t
  ) s
  WHERE group_id IS NOT NULL AND node_id IS NOT NULL;
END;
$$;


ALTER FUNCTION public.sp_get_group_node_array(i_group_id bigint[], i_platform_type public.en_platform_type[], i_admin_id text) OWNER TO cppoltp;

--
-- Name: sp_get_group_node_list(bigint, boolean, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_group_node_list(i_group_id bigint, i_include_subgroup boolean, i_admin_id text) RETURNS TABLE(node_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_admin_group text;
  v_top_group_id text;
  v_node_id text;
  v_node_count integer;
  v_physical_group_id BIGINT;
  v_group_id bigint[];

BEGIN

  -- i_include_subgroup이 TRUE일 경우 group_id의 모든 서브그룹을 다 가져온다
  IF i_include_subgroup THEN

    SELECT admin_group
    INTO v_admin_group
    FROM tb_admin
    WHERE admin_id = i_admin_id;

    SELECT g.group_id::text
    INTO v_top_group_id
    FROM tb_group g
    WHERE g.group_type = 'TOP';

    IF i_admin_id IS NULL OR i_admin_id = 'TOMCAT_CONSOLE' OR v_admin_group = v_top_group_id THEN

      WITH RECURSIVE group_list (group_id, name, pgroup_id, group_type, is_removed, level, grp_path, cycle)
      AS (
        SELECT g.group_id
              ,g.name
              ,g.pgroup_id
              ,g.group_type
              ,g.is_removed
              ,0
              ,ARRAY[g.group_id]
              ,false
        FROM tb_group g
        WHERE g.group_id = i_group_id
        UNION ALL
        SELECT g.group_id
              ,g.name
              ,g.pgroup_id
              ,g.group_type
              ,g.is_removed
              ,gl.level + 1
              ,gl.grp_path || g.group_id
              ,g.group_id = ANY(gl.grp_path)
        FROM tb_group g
        JOIN group_list gl
          ON g.pgroup_id = gl.group_id
          AND NOT cycle
        WHERE g.group_type NOT IN ('TOP')
          AND g.is_removed IS NOT true
      )
        SELECT array_agg(n.node_id)
              ,count(n.node_id)
        INTO v_node_id
            ,v_node_count
        FROM tb_node n
          INNER JOIN tb_platform platform ON platform.platform_id = n.platform_id AND platform.is_supported IS TRUE
        WHERE EXISTS (SELECT 1 FROM group_list gl WHERE gl.group_id = n.group_id)
          AND n.is_removed = false
        ;

    ELSE

      SELECT string_to_array(v_admin_group, ',')::bigint[]
      INTO v_group_id;

      SELECT g.group_id
      INTO v_physical_group_id
      FROM tb_group g
      WHERE g.group_type = 'PHYSICAL';

      WITH RECURSIVE group_list (group_id, name, pgroup_id, group_type, is_removed, level, grp_path, cycle)
      AS (
        SELECT g.group_id
              ,g.name
              ,CASE WHEN g.group_type IN ('PHYSICAL') THEN g.pgroup_id
                    ELSE v_physical_group_id
               END AS pgroup_id
              ,g.group_type
              ,g.is_removed
              ,1
              ,ARRAY[g.group_id]
              ,false
        FROM tb_group g
        WHERE g.is_removed IS NOT TRUE
          AND CASE i_group_id WHEN v_top_group_id::BIGINT THEN g.group_id IN (SELECT * FROM unnest(v_group_id))
                              WHEN v_physical_group_id THEN g.group_id IN (SELECT * FROM unnest(v_group_id)) AND g.group_type IN ('PHYSICAL','DEFAULT','GENERAL')
                              ELSE g.group_id = i_group_id
              END
        UNION ALL
        SELECT g.group_id
              ,g.name
              ,g.pgroup_id
              ,g.group_type
              ,g.is_removed
              ,gl.level + 1
              ,gl.grp_path || g.group_id
              ,g.group_id = ANY(gl.grp_path)
        FROM tb_group g
        JOIN group_list gl
          ON g.pgroup_id = gl.group_id
          AND NOT cycle
        WHERE g.group_type NOT IN ('TOP')
          AND g.is_removed IS NOT TRUE
      )
      SELECT array_agg(n.node_id)
            ,count(n.node_id)
      INTO v_node_id
          ,v_node_count
      FROM tb_node n
        INNER JOIN tb_platform platform ON platform.platform_id = n.platform_id AND platform.is_supported IS TRUE
      WHERE EXISTS (SELECT 1 FROM group_list gl WHERE gl.group_id = n.group_id)
        AND n.is_removed = false
        ;

    END IF;

  -- i_include_subgroup이 FALSE일 경우 group_id에 대한 정보만 가져온다
  ELSE

    SELECT array_agg(n.node_id)
          ,count(n.node_id)
    INTO v_node_id
        ,v_node_count
    FROM tb_node n
    WHERE n.group_id = i_group_id
      AND n.is_removed = false
    ;

  END IF;

  IF v_node_count < 1 THEN

    SELECT '{}'
    INTO v_node_id;

  END IF;

  RETURN QUERY
  SELECT v_node_id;

END;
$$;


ALTER FUNCTION public.sp_get_group_node_list(i_group_id bigint, i_include_subgroup boolean, i_admin_id text) OWNER TO cppoltp;

--
-- Name: sp_get_group_order_setting(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_group_order_setting() RETURNS TABLE(new_group_position text, select_order text)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_new_group_position text;
  v_select_order text;

BEGIN

  SELECT value
  INTO v_new_group_position
  FROM tb_config
  WHERE config_group = 'GROUP_ORDER'
    AND key = 'new_group_position';

  SELECT value
  INTO v_select_order
  FROM tb_config
  WHERE config_group = 'GROUP_ORDER'
    AND key = 'select_order';

  RETURN QUERY SELECT v_new_group_position, v_select_order;

END;
$$;


