--
-- Name: sp_get_group_policy_summary(bigint[], text[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_group_policy_summary(i_group_id bigint[], i_node_id text[]) RETURNS TABLE(group_id bigint, product_group public.en_product_group_type, product_feature_id public.en_product_feature_id_type, policy_status text, count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_node_id bigint[];
  v_group_id bigint[];
  v_product_group en_product_group_type[];
  v_product_feature_id en_product_feature_id_type[];
  v_policy_status text[];
  v_count bigint[];

BEGIN

  FOR i IN array_lower(i_group_id, 1) .. array_upper(i_group_id, 1)
  LOOP

    SELECT string_to_array(i_node_id[i], '||')::bigint[]
    INTO v_node_id;

    SELECT array_cat(v_group_id, array_agg(i_group_id[i]))
          ,array_cat(v_product_group, array_agg(pac.product_group))
          ,array_cat(v_product_feature_id, array_agg(pac.product_feature_id))
          ,array_cat(v_policy_status, array_agg(pac.policy_status))
          ,array_cat(v_count, array_agg(pac.count))
    INTO v_group_id
        ,v_product_group
        ,v_product_feature_id
        ,v_policy_status
        ,v_count
    FROM sp_get_agent_policy_applied_count(v_node_id) pac
    WHERE pac.product_group IN ('EMS','V3')
      OR (pac.product_group IN ('AC') AND sp_exist_license('AC'))
      OR (pac.product_group IN ('HIPS') AND sp_exist_license('HIPS'))
      OR (pac.product_group IN ('SCM') AND sp_exist_license('SCM'));
  END LOOP;

  RETURN QUERY
  SELECT unnest(v_group_id) AS group_id
        ,unnest(v_product_group) AS product_group
        ,unnest(v_product_feature_id) AS product_feature_id
        ,unnest(v_policy_status) AS policy_status
        ,unnest(v_count) AS count;

END;
$$;


ALTER FUNCTION public.sp_get_group_policy_summary(i_group_id bigint[], i_node_id text[]) OWNER TO cppoltp;

--
-- Name: sp_get_group_summary_ac_status(bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_group_summary_ac_status(i_node_id bigint[]) RETURNS TABLE(view_type text, title text, value text)
    LANGUAGE plpgsql
    AS $$

DECLARE
  v_step      integer[];
  v_view_type   text[];
  v_title      text[];
  v_value         text[];

BEGIN

   -- 1. AC 설치 현황
   SELECT   ARRAY_CAT(v_step, ARRAY_AGG(1))
            , ARRAY_CAT(v_view_type, ARRAY_AGG('AC_INSTALLED_COUNT'::text))
            , ARRAY_CAT(v_title, ARRAY_AGG(t2.view_type::text))
            , ARRAY_CAT(v_value, ARRAY_AGG(COALESCE(t2.value, '0'))) INTO v_step, v_view_type, v_title, v_value
   FROM(
        SELECT
             t1.v_view_type::text AS view_type
            ,SUM(t1.v_value)::text AS value
         FROM (
                SELECT
                    0 AS node_id
                  , UNNEST(ARRAY['AC_NOT_INSTALLED_COUNT','AC_NOT_SUPPORTED_COUNT','AC_INSTALLED_COUNT']) AS v_view_type
                  , 0 AS v_value
                UNION ALL
                SELECT
                    n.node_id
                  , CASE WHEN ARRAY_AGG(pi.product_id) @> ('{AC_CLIENT}'::en_product_id_type[]) THEN 'AC_INSTALLED_COUNT'
                         WHEN (n.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS FALSE) THEN 'AC_NOT_SUPPORTED_COUNT'
                         ELSE 'AC_NOT_INSTALLED_COUNT'
                    END AS v_view_type
                  , 1 AS v_value
                 FROM tb_node n
                 LEFT JOIN tb_product_info pi ON n.node_id = pi.node_id
                 LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = n.container_service_type
                 WHERE
                  n.node_id = ANY(i_node_id)
                  AND n.is_removed IS FALSE
                 GROUP BY n.node_id, tcp.is_ac_supported
              ) AS t1
              GROUP BY t1.v_view_type
         )AS t2;


   -- 2. AC 상태
   SELECT  ARRAY_CAT(v_step, ARRAY_AGG(2))
        , ARRAY_CAT(v_view_type, ARRAY_AGG('AC_STATUS'::text))
        , ARRAY_CAT(v_title, ARRAY_AGG(t1.policy_status::text))
        , ARRAY_CAT(v_value, ARRAY_AGG(t1.cnt::text)) INTO v_step, v_view_type, v_title, v_value
   FROM (
        SELECT
              ac.ac_status AS policy_status
            , COUNT(1) AS cnt
        FROM tb_node n
        JOIN tb_ac_status ac on n.node_id = ac.node_id
        WHERE
            ac.node_id = ANY(i_node_id)
            AND n.is_removed IS FALSE
        GROUP BY ac.ac_status
    ) AS t1;

  -- 3. 정책 적용 현황 (AC 에이전트 정책, AC 정책)
  SELECT  ARRAY_CAT(v_step, ARRAY_AGG(3))
        , ARRAY_CAT(v_view_type, ARRAY_AGG(CONCAT(tot.product_feature_id::text, '_POLICY_STATUS')))
        , ARRAY_CAT(v_title, ARRAY_AGG(tot.policy_status::text))
        , ARRAY_CAT(v_value, ARRAY_AGG(tot.cnt::text)) INTO v_step, v_view_type, v_title, v_value
  FROM (
    SELECT t2.product_feature_id, t.policy_status, COALESCE(t2.cnt, 0) AS cnt
    FROM UNNEST(enum_range(null::en_policy_status)) AS t(policy_status)
    JOIN (
      SELECT t1.product_feature_id, t1.policy_status, t1.cnt
      FROM (
        SELECT ps.product_feature_id
          , ps.policy_status AS policy_status
          , count(1) AS cnt
        FROM vw_policy_status ps
        JOIN tb_node n ON n.node_id = ps.node_id AND n.is_removed is FALSE
        JOIN tb_product_feature_map pfm ON ps.product_feature_id = pfm.product_feature_id AND pfm.product_id = 'AC_CLIENT'
        WHERE ps.node_id = ANY(i_node_id)
        GROUP BY ps.policy_status, ps.product_feature_id
      ) AS t1
    ) AS t2 ON t.policy_status = t2.policy_status
  ) AS tot;

  RETURN QUERY
    SELECT t.view_type, t.title, t.value
    FROM UNNEST(v_step, v_view_type, v_title, v_value) AS t(step, view_type, title, value)
    ORDER BY 1;

END;
$$;


ALTER FUNCTION public.sp_get_group_summary_ac_status(i_node_id bigint[]) OWNER TO cppoltp;

