COMMENT ON FUNCTION public.sp_get_group_summary_ac_status(i_node_id bigint[]) IS '
@brief [SWM-SCI1163] 그룹> AC 현황
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_group_summary_hips_status(bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_group_summary_hips_status(i_node_id bigint[]) RETURNS TABLE(view_type text, title text, value text)
    LANGUAGE plpgsql
    AS $$

DECLARE
  v_step      integer[];
  v_view_type   text[];
  v_title      text[];
  v_value         text[];

BEGIN
  -- 1. HIPS 설치 현황
  SELECT   
    ARRAY_CAT(v_step, ARRAY_AGG(1))
    , ARRAY_CAT(v_view_type, ARRAY_AGG('HIPS_INSTALLED_COUNT'::text))
    , ARRAY_CAT(v_title, ARRAY_AGG(t2.view_type::text))
    , ARRAY_CAT(v_value, ARRAY_AGG(COALESCE(t2.value, '0'))) INTO v_step, v_view_type, v_title, v_value
  FROM (
    SELECT
      t1.v_view_type::text AS view_type
      , SUM(t1.v_value)::text AS value
    FROM (
      SELECT
        0 AS node_id
        , UNNEST(ARRAY['HIPS_NOT_INSTALLED_COUNT','HIPS_INSTALLED_COUNT']) AS v_view_type
        , 0 AS v_value
      UNION ALL
      SELECT
        n.node_id
        , CASE WHEN ARRAY_AGG(pi.product_id) @> ('{HIPS_CLIENT}'::en_product_id_type[]) THEN 'HIPS_INSTALLED_COUNT'
          ELSE 'HIPS_NOT_INSTALLED_COUNT'
        END AS v_view_type
        , 1 AS v_value
      FROM tb_node n
      LEFT JOIN tb_product_info pi ON n.node_id = pi.node_id
      WHERE
        n.node_id = ANY(i_node_id)
        AND n.is_removed IS FALSE
      GROUP BY n.node_id
    ) AS t1
    GROUP BY t1.v_view_type
  )AS t2;

  -- 2. HIP IPS 상태
  SELECT 
    ARRAY_CAT(v_step, ARRAY_AGG(2))
    , ARRAY_CAT(v_view_type, ARRAY_AGG('HIPS_IPS_STATUS'::text))
    , ARRAY_CAT(v_title, ARRAY_AGG(t.ips_status::text))
    , ARRAY_CAT(v_value, ARRAY_AGG(t.cnt::text)) INTO v_step, v_view_type, v_title, v_value
  FROM (
    SELECT
      t1.ips_status
      , COUNT(t1.*) AS cnt
    FROM (
      SELECT 
        CASE 
          WHEN engine_state = 'OFF' THEN CONCAT('ENGINE_',engine_state)::text
          ELSE ips_status::text
        END AS ips_status
      FROM tb_hips_status ths
      INNER JOIN tb_product_info tpi
      ON ths.node_id = tpi.node_id AND tpi.product_id = 'HIPS_CLIENT'
      WHERE ths.node_id = ANY(i_node_id)
		) t1 
    GROUP BY t1.ips_status
	) AS t;

  -- 3. HIP FW 상태
  SELECT 
    ARRAY_CAT(v_step, ARRAY_AGG(3))
    , ARRAY_CAT(v_view_type, ARRAY_AGG('HIPS_FW_STATUS'::text))
    , ARRAY_CAT(v_title, ARRAY_AGG(t.fw_status::text))
    , ARRAY_CAT(v_value, ARRAY_AGG(t.cnt::text)) INTO v_step, v_view_type, v_title, v_value
  FROM (
    SELECT
      t1.fw_status
      , COUNT(t1.*) AS cnt 
    FROM (
      SELECT 
        CASE 
          WHEN engine_state = 'OFF' THEN CONCAT('ENGINE_',engine_state)::text
          ELSE fw_status::text
        END AS fw_status
      FROM tb_hips_status ths
      INNER JOIN tb_product_info tpi
      ON ths.node_id = tpi.node_id AND tpi.product_id = 'HIPS_CLIENT'
      WHERE ths.node_id = ANY(i_node_id)
    ) t1 
    GROUP BY t1.fw_status
	) AS t;

  -- 4. 정책 적용 현황 (HIPS 에이전트 정책, HIPS 정책)
  SELECT 
    ARRAY_CAT(v_step, ARRAY_AGG(4))
    , ARRAY_CAT(v_view_type, ARRAY_AGG(CONCAT(tot.product_feature_id::text, '_POLICY_STATUS')))
    , ARRAY_CAT(v_title, ARRAY_AGG(tot.policy_status::text))
    , ARRAY_CAT(v_value, ARRAY_AGG(tot.cnt::text)) INTO v_step, v_view_type, v_title, v_value
  FROM (
    SELECT 
      t2.product_feature_id
      , t.policy_status
      , COALESCE(t2.cnt, 0) AS cnt
    FROM UNNEST(enum_range(null::en_policy_status)) AS t(policy_status)
    JOIN (
      SELECT t1.product_feature_id, t1.policy_status, t1.cnt
      FROM (
        SELECT 
          ps.product_feature_id
          , ps.policy_status AS policy_status
          , count(1) AS cnt
        FROM vw_policy_status ps
        JOIN tb_node n ON n.node_id = ps.node_id AND n.is_removed is FALSE
        JOIN tb_product_feature_map pfm ON ps.product_feature_id = pfm.product_feature_id AND pfm.product_id = 'HIPS_CLIENT'
        WHERE ps.node_id = ANY(i_node_id)
        GROUP BY ps.policy_status, ps.product_feature_id
      ) AS t1
    ) AS t2 
    ON t.policy_status = t2.policy_status
  ) AS tot;

  RETURN QUERY
    SELECT t.view_type, t.title, t.value
    FROM UNNEST(v_step, v_view_type, v_title, v_value) AS t(step, view_type, title, value)
    ORDER BY 1;

END;
$$;


ALTER FUNCTION public.sp_get_group_summary_hips_status(i_node_id bigint[]) OWNER TO cppoltp;

