--
-- Name: sp_get_group_table_shard_data(bigint, bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_group_table_shard_data(i_start_id bigint, i_end_id bigint) RETURNS TABLE(group_id text, name text, path text, name_path text, pgroup_id text, group_type text, is_removed text, group_order text, hash text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
RETURN QUERY

  WITH RECURSIVE tree AS (
  SELECT
   g.group_id
   , '/' || g.name AS group_path
  FROM tb_group g
  WHERE g.group_type  = 'TOP'
  UNION ALL
  SELECT
   g.group_id
  , t.group_path || '/' || g.name
  FROM tb_group g
  INNER JOIN tree t
  ON g.pgroup_id  = t.group_id
  )
  SELECT g.group_id::text,  g.name::text,  g.path::text,  t.group_path::text AS name_path,  g.pgroup_id::text,  g.group_type::text,  g.is_removed::TEXT, g.group_order::TEXT,
  md5(concat(g.name, g.pgroup_id, g.group_type, g.is_removed, g.group_order))
  FROM tb_group g
  LEFT JOIN tree t
  ON g.group_id = t.group_id;

END;
$$;


ALTER FUNCTION public.sp_get_group_table_shard_data(i_start_id bigint, i_end_id bigint) OWNER TO cppoltp;

--
-- Name: sp_get_group_timeline(bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_group_timeline(i_node_id bigint[]) RETURNS TABLE(reg_date text, agent_count bigint, v3_install_count bigint, engine_update_count bigint, manual_scan_count bigint, installed_ac_agent_count bigint, installed_hips_agent_count bigint, installed_scm_agent_count bigint, hips_detect_detect_count bigint, hips_detect_block_count bigint, hips_fw_block_count bigint)
    LANGUAGE plpgsql
    AS $$

  DECLARE
  v_engine_update_threshold   integer;
  v_manual_scan_threshold     integer;
BEGIN
  -- 엔진 업데이트 임계치
  SELECT GREATEST(COALESCE(MAX(c.value), '0')::integer, 0) INTO v_engine_update_threshold
  FROM tb_config AS c
  WHERE c.config_group = 'AGENT_THRESHOLD' AND c.key = 'engine_update_threshold';

  -- 수동 검사 임계치
  SELECT GREATEST(COALESCE(MAX(c.value), '0')::integer, 0) INTO v_manual_scan_threshold
  FROM tb_config AS c
  WHERE c.config_group = 'AGENT_THRESHOLD' AND c.key = 'manual_scan_threshold';


  RETURN QUERY
  SELECT i.reg_date
        ,COALESCE(oltp.agent_count, 0)
        ,COALESCE(v3.v3_install_count, 0)
        ,COALESCE(v3.engine_update_count, 0)
        ,COALESCE(v3.manual_scan_count, 0)
        ,COALESCE(ac.installed_ac_agent_count, 0)
        ,COALESCE(hips.installed_hips_agent_count, 0)
        ,COALESCE(scm.installed_scm_agent_count, 0)
        ,COALESCE(hips_log.hips_detect_detect_count, 0)
        ,COALESCE(hips_log.hips_detect_block_count, 0)
        ,COALESCE(hips_log.hips_fw_block_count, 0)
  FROM (
    SELECT TO_CHAR(date_trunc('DAY', CURRENT_TIMESTAMP) - (t.i || 'DAY')::interval, 'YYYYMMDD') AS time_interval
      FROM generate_series(0, 29) AS t(i)
  ) i(reg_date)
  LEFT JOIN (
    SELECT  oltp.reg_date
           ,count(oltp.node_id)::BIGINT AS agent_count
      FROM tb_timeline_oltp oltp
      JOIN tb_node n ON n.node_id = oltp.node_id AND n.is_removed IS FALSE
     WHERE n.node_id = ANY(i_node_id)
     GROUP BY oltp.reg_date
  ) oltp on oltp.reg_date = i.reg_date
  LEFT JOIN (
    SELECT  oltp.reg_date
           ,COUNT(oltp.product_id)::BIGINT AS v3_install_count
           ,SUM(CASE WHEN oltp.engine_update_past_days < v_engine_update_threshold THEN 1 ELSE 0 END)::BIGINT AS engine_update_count
           ,SUM(CASE WHEN oltp.last_scan_time IS NOT NULL AND GREATEST(oltp.reg_date::date - to_char(oltp.last_scan_time, 'YYYYMMDD')::date, 0) < v_manual_scan_threshold THEN 1 ELSE 0 END)::BIGINT AS manual_scan_count
      FROM tb_timeline_oltp oltp
      JOIN tb_node n ON n.node_id = oltp.node_id AND n.is_removed IS FALSE
     WHERE n.node_id = ANY(i_node_id)
     GROUP BY oltp.reg_date
  ) v3 ON v3.reg_date = i.reg_date
  LEFT JOIN (
     SELECT  ac.reg_date
            ,COUNT(ac.node_id)::bigint AS installed_ac_agent_count
       FROM tb_ac_daily_timeline ac
       JOIN tb_node n ON n.node_id = ac.node_id AND n.is_removed IS FALSE
       WHERE n.node_id = ANY(i_node_id) AND COALESCE(ac.is_removed, FALSE) = FALSE
       GROUP BY ac.reg_date
  ) ac ON ac.reg_date = i.reg_date
  LEFT JOIN (
     SELECT  hips.reg_date
            ,COUNT(hips.node_id)::bigint AS installed_hips_agent_count
       FROM tb_hips_daily_timeline hips
       JOIN tb_node n ON n.node_id = hips.node_id AND n.is_removed IS FALSE
       WHERE n.node_id = ANY(i_node_id) AND COALESCE(hips.is_removed, FALSE) = FALSE
       GROUP BY hips.reg_date
  ) hips ON hips.reg_date = i.reg_date
  LEFT JOIN (
     SELECT  scm.reg_date
            ,COUNT(scm.node_id)::bigint AS installed_scm_agent_count
       FROM tb_scm_status_daily_timeline scm
       JOIN tb_node n ON n.node_id = scm.node_id AND n.is_removed IS FALSE
       WHERE n.node_id = ANY(i_node_id)
       GROUP BY scm.reg_date
  ) scm ON scm.reg_date = i.reg_date  
  LEFT JOIN (
    SELECT   hips_log.reg_date
            ,SUM(hips_detect.detect_count) AS hips_detect_detect_count
            ,SUM(hips_detect.block_count) AS hips_detect_block_count
            ,SUM(hips_fw.block_count) AS hips_fw_block_count
    FROM (
        SELECT   hips_detect.reg_date AS reg_date
                ,hips_detect.node_id AS node_id
        FROM    tb_hips_detect_daily_timeline hips_detect
        JOIN    tb_node n ON n.node_id = hips_detect.node_id AND n.is_removed IS FALSE
        WHERE   n.node_id = ANY(i_node_id)
        UNION
        SELECT   hips_fw.reg_date AS reg_date
                ,hips_fw.node_id AS node_id
        FROM    tb_hips_fw_daily_timeline hips_fw
        JOIN    tb_node n ON n.node_id = hips_fw.node_id AND n.is_removed IS FALSE
        WHERE   n.node_id = ANY(i_node_id)
    ) hips_log
    LEFT JOIN tb_hips_detect_daily_timeline hips_detect ON hips_log.reg_date = hips_detect.reg_date AND hips_log.node_id = hips_detect.node_id
    LEFT JOIN tb_hips_fw_daily_timeline hips_fw ON hips_log.reg_date = hips_fw.reg_date AND hips_log.node_id = hips_fw.node_id
    GROUP BY hips_log.reg_date
  ) hips_log ON hips_log.reg_date::text = i.reg_date
  ;

END;
$$;


ALTER FUNCTION public.sp_get_group_timeline(i_node_id bigint[]) OWNER TO cppoltp;

--
-- Name: sp_get_group_top(public.en_group_type, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_group_top(i_group_type public.en_group_type, i_admin_id text) RETURNS TABLE(group_id bigint, group_type public.en_group_type, name text, parent bigint, subgroups bigint[], agent_cnt bigint, is_enable integer, is_all integer)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_top_group text;
  v_admin_group text;
  v_is_enable integer := 1;
  v_is_all integer := 1;
  v_group_id bigint[];
  v_default_group_id bigint[];

BEGIN

  SELECT admin_group
  INTO v_admin_group
  FROM tb_admin
  WHERE admin_id = i_admin_id;

  SELECT g.group_id::text
  INTO v_top_group
  FROM tb_group g
  WHERE g.group_type = 'TOP';

  IF v_admin_group <> v_top_group THEN

    SELECT string_to_array(v_admin_group, ',')::bigint[]
    INTO v_group_id;

    SELECT array_agg(g.group_id)
    INTO v_default_group_id
    FROM tb_group g
    WHERE g.group_type = 'DEFAULT';

    SELECT (v_group_id @> v_default_group_id)::integer
    INTO v_is_enable;

    v_is_all := 0;

  END IF;

  RETURN QUERY
  -- 그룹 가져오기 (최상위 : top / 기본 : default)
  SELECT g.group_id AS group_id
        ,g.group_type AS group_type
        ,g.name AS name
        ,g.pgroup_id AS parent
        ,(SELECT ARRAY_AGG(gs.group_id) AS subgroups FROM tb_group gs WHERE gs.pgroup_id = g.group_id AND gs.is_removed = false) AS subgroups
        ,(SELECT count(*)::bigint FROM tb_node n WHERE n.group_id = g.group_id AND n.is_removed = false AND n.platform_id IS NOT NULL) AS agent_cnt
        ,v_is_enable AS is_enable
        ,v_is_all AS is_all
  FROM tb_group g
  WHERE g.group_type = i_group_type
    AND g.is_removed IS NOT true;

END;
$$;


ALTER FUNCTION public.sp_get_group_top(i_group_type public.en_group_type, i_admin_id text) OWNER TO cppoltp;

--
-- Name: sp_get_group_update_server_list(bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_group_update_server_list(i_group_id bigint[]) RETURNS TABLE(group_id bigint, update_server_list text)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_update_server_list text[];

BEGIN

  FOR i IN array_lower(i_group_id, 1) .. array_upper(i_group_id, 1)
  LOOP

    SELECT array_append(v_update_server_list, ARRAY_TO_STRING(ARRAY_AGG(t.update_server_list),','))
    INTO v_update_server_list
    FROM (
      SELECT s.name || '(' || s.ip || ')' as update_server_list
      FROM tb_file_update_server us
      JOIN tb_server s ON s.server_id = us.server_id AND us.target_id = i_group_id[i]
      WHERE us.target_type = 'GROUP'
      ORDER BY us.target_id, s.name DESC
    ) t;

  END LOOP;

  RETURN QUERY
  SELECT unnest(i_group_id) AS group_id
         , unnest(v_update_server_list) AS update_server_list;

END;
$$;


ALTER FUNCTION public.sp_get_group_update_server_list(i_group_id bigint[]) OWNER TO cppoltp;

--
-- Name: sp_get_group_v3_summary(bigint[], text[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_group_v3_summary(i_group_id bigint[], i_node_id text[]) RETURNS TABLE(group_id bigint, product_type text, product_id text, count bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_node_id bigint[];
  v_group_id bigint[];
  v_product_type text[];
  v_product_id text[];
  v_count bigint[];

BEGIN

  FOR i IN array_lower(i_group_id, 1) .. array_upper(i_group_id, 1)
  LOOP

    SELECT string_to_array(i_node_id[i], '||')::bigint[]
    INTO v_node_id;

    SELECT array_cat(v_group_id, array_agg(t.group_id))
          ,array_cat(v_product_type, array_agg(t.product_type))
          ,array_cat(v_product_id, array_agg(t.product_id))
          ,array_cat(v_count, array_agg(t.count))
    INTO v_group_id
        ,v_product_type
        ,v_product_id
        ,v_count
    FROM (SELECT i_group_id[i] AS group_id
                ,'NOT_INSTALL'::text AS product_type
                ,''::text AS product_id
                ,count(t.node_id) AS count
          FROM unnest(v_node_id::bigint[]) AS t(node_id)
          JOIN tb_node n ON t.node_id = n.node_id AND n.is_removed IS FALSE AND n.platform_id IS NOT NULL
          LEFT JOIN (SELECT vs.node_id
                     FROM tb_v3_status vs
                     JOIN tb_product_info pi ON vs.node_id = pi.node_id AND vs.product_id = pi.product_id
                     JOIN tb_product p ON vs.product_id = p.product_id AND p.product_group = 'V3'
                     JOIN tb_node n ON vs.node_id = n.node_id
                      AND n.is_removed IS FALSE
                      AND n.platform_id IS NOT NULL) vs
          ON t.node_id = vs.node_id
          LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = n.container_service_type
          WHERE vs.node_id IS NULL AND (n.machine_type != 'CONTAINER' OR n.machine_type = 'CONTAINER' AND tcp.is_amc_supported IS TRUE)
          ) t;

    SELECT array_cat(v_group_id, array_agg(i_group_id[i]))
          ,array_cat(v_product_type, array_agg(vmc.product_type))
          ,array_cat(v_product_id, array_agg(vmc.product_id::text))
          ,array_cat(v_count, array_agg(vmc.count))
    INTO v_group_id
        ,v_product_type
        ,v_product_id
        ,v_count
    FROM sp_get_v3_malware_count(v_node_id) vmc;

  END LOOP;

  RETURN QUERY
  SELECT unnest(v_group_id) AS group_id
        ,unnest(v_product_type) AS product_type
        ,unnest(v_product_id) AS product_id
        ,unnest(v_count) AS count;

END;
$$;


ALTER FUNCTION public.sp_get_group_v3_summary(i_group_id bigint[], i_node_id text[]) OWNER TO cppoltp;

--
-- Name: sp_get_hardware_info(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_hardware_info() RETURNS TABLE(license text, version text, "group" text, model text, cpu text, mem bigint, hdd bigint, instance_type text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_server_count		BIGINT;
  v_license			TEXT;
  v_version			TEXT;
BEGIN
  SELECT count(*) INTO v_server_count FROM tb_server;
	SELECT
    tb_product_license.license_no, tb_product_license.version INTO v_license, v_version
  FROM
    tb_product_license
  WHERE
    product_id = 'EMS';
	RETURN QUERY
	SELECT
      v_license
      , v_version
      , s."name"
      , s.model_no
      , s.cpu_desc,(sr.used_mem+sr.avail_mem)/1024 AS mem
      , (sr.used_hdd+sr.avail_hdd)/1024 AS hdd
      , COALESCE(s.instance_type, '') AS instance_type
	FROM
      tb_server_resource AS sr
	JOIN
      tb_server AS s
	ON
      sr.server_id = s.server_id
	ORDER BY
      log_time DESC
	LIMIT
      v_server_count;

END
$$;


ALTER FUNCTION public.sp_get_hardware_info() OWNER TO cppoltp;

--
-- Name: sp_get_hips_agent_policy_detail(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_hips_agent_policy_detail(i_policy_id bigint) RETURNS TABLE(product_feature_id public.en_product_feature_id_type, product_feature_name text, policy_id bigint, policy_name text, description text, policy_type public.en_policy_type, online_policy_body text, offline_policy_body text, use_offline_policy text, hash text, modified_time timestamp without time zone, group_id_array bigint[])
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_product_feature_id en_product_feature_id_type;

BEGIN

SELECT p.product_feature_id
INTO v_product_feature_id
FROM tb_policy p
WHERE p.policy_id = i_policy_id;

IF v_product_feature_id IS NULL THEN

  RAISE EXCEPTION 'policy_id (%) does not exist.', i_policy_id USING HINT = 'DB-00031';

ELSIF v_product_feature_id <> 'HIPS_AGENT' THEN

  RAISE EXCEPTION 'policy_id (%) is not HIPS_AGENT policy.', i_policy_id USING HINT = 'DB-00030';

END IF;

RETURN QUERY

--정책 상세
SELECT p.product_feature_id AS product_feature_id
      ,p.product_feature_name AS product_feature_name
      ,p.policy_id AS policy_id
      ,p.policy_name AS policy_name
      ,p.description AS description
      ,p.policy_type AS policy_type
      ,p.online_policy_body AS online_policy_body
      ,p.offline_policy_body AS offline_policy_body
      ,p.use_offline_policy AS use_offline_policy
      ,p.hash AS hash
      ,p.modified_time AS modified_time
      ,p.group_id_array AS group_id_array
FROM sp_get_policy_detail(i_policy_id) p
;

END;
$$;


