--
-- Name: sp_get_hips_signature_info(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_hips_signature_info() RETURNS TABLE(sid bigint, os_type text, use_count bigint, detect_count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
  RETURN QUERY

  SELECT
    tnhs.sid
    , CASE
      WHEN tn.platform_id::text = 'UNKNOWN' THEN 'ETC'
      WHEN tn.platform_id::text LIKE '%WINDOWS%' THEN 'WINDOWS'
      ELSE 'LINUX_UNIX'
    END AS os_type
    , COALESCE(COUNT(tnhs.sid), 0) AS use_count
    , COALESCE(COUNT(thdeld.sid), 0) as detect_count
  FROM
    tb_node_hips_signature tnhs
  INNER JOIN
    tb_node tn
  ON
    tnhs.node_id = tn.node_id
  LEFT JOIN
    tb_hips_detect_event_log_hourly thdeld
  ON
    thdeld.node_id = tnhs.node_id
  AND
    thdeld.sid = tnhs.sid
  AND (
  	thdeld.reg_date
  		BETWEEN to_char(now() - interval '1 day', 'yyyyMMdd00')::int4
  		AND 	to_char(now() - interval '1 day', 'yyyyMMdd23')::int4
  )
  WHERE
    tnhs.sid < 20000000
  GROUP BY
    tnhs.sid, os_type
  UNION ALL
  SELECT
    tphs.sid
    , CASE
      WHEN tn.platform_id::text = 'UNKNOWN' THEN 'ETC'
      WHEN tn.platform_id::text LIKE '%WINDOWS%' THEN 'WINDOWS'
      ELSE 'LINUX_UNIX'
    END AS os_type
    , COALESCE(COUNT(tphs.sid), 0) AS use_count
    , COALESCE(COUNT(thdeld.sid), 0) as detect_count
  FROM
    tb_policy_hips_signature tphs
  INNER JOIN
    tb_node_policy tnp
  ON
    tphs.policy_id = tnp.policy_id
  INNER JOIN
    tb_node tn
  ON
    tnp.node_id = tn.node_id
  LEFT JOIN
    tb_hips_detect_event_log_hourly thdeld
  ON
    thdeld.node_id = tnp.node_id
  AND
    thdeld.sid = tphs.sid
  AND (
  	thdeld.reg_date
  		BETWEEN to_char(now() - interval '1 day', 'yyyyMMdd00')::int4
  		AND 	to_char(now() - interval '1 day', 'yyyyMMdd23')::int4
  )
  WHERE
    tphs.sid < 20000000
  GROUP BY
    tphs.sid, os_type
  ORDER BY
    sid;

END;
$$;


ALTER FUNCTION public.sp_get_hips_signature_info() OWNER TO cppoltp;

--
-- Name: sp_get_hips_status(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_hips_status() RETURNS TABLE(product_id public.en_product_id_type, os_type text, type text, status text, count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
  RETURN QUERY
	SELECT
		ths.product_id
		, CASE
      WHEN tn.platform_id::text = 'UNKNOWN' THEN 'etc'
      WHEN tn.platform_id::text LIKE '%WINDOWS%' THEN 'WINDOWS'
      ELSE 'LINUX_UNIX'
		END AS os_type
		, 'ips'::text AS type
		, ths.ips_status::text AS status
		, COUNT(*)
	FROM
		tb_hips_status ths
	INNER JOIN
		tb_node tn
	ON
		ths.node_id = tn.node_id
	AND
		tn.is_removed IS FALSE
	GROUP BY
		ths.product_id, ths.ips_status, os_type
	UNION
	SELECT
		ths.product_id
		, CASE
      WHEN tn.platform_id::text = 'UNKNOWN' THEN 'etc'
      WHEN tn.platform_id::text LIKE '%WINDOWS%' THEN 'WINDOWS'
      ELSE 'LINUX_UNIX'
		END AS os_type
		, 'fw'::text AS type
		, ths.fw_status::text AS status
		, count(*)
	FROM
		tb_hips_status ths
	INNER JOIN
		tb_node tn
	ON
		ths.node_id = tn.node_id
	AND
		tn.is_removed IS FALSE
	GROUP BY
		ths.product_id, ths.fw_status, os_type
	ORDER BY
		type desc;

END;
$$;


ALTER FUNCTION public.sp_get_hips_status() OWNER TO cppoltp;

