--
-- Name: sp_get_is_nat(inet); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_is_nat(i_ip inet) RETURNS TABLE(is_nat text)
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_is_nat TEXT;
BEGIN
	SELECT value FROM tb_config WHERE config_group = 'NETWORK' AND "key" = 'use_nat' INTO v_is_nat;

  -- [CWPP-5146] Private IP 목록을 tb_private_ip_range에서 관리.
  IF v_is_nat = 'false' OR HOST(i_ip) = '127.0.0.1' THEN
    RETURN QUERY SELECT 'false'::TEXT AS is_nat;
  ELSE
      RETURN QUERY 
          SELECT 
            (CASE WHEN COUNT(*) > 0 THEN 'false' ELSE 'true' END)::TEXT AS is_nat
          FROM
            tb_private_ip_range range
          WHERE
            range.range_from <= i_ip
            AND range.range_to >= i_ip;
  END IF;
END;
$$;


ALTER FUNCTION public.sp_get_is_nat(i_ip inet) OWNER TO cppoltp;

--
-- Name: sp_get_is_nat(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_is_nat(i_node_id bigint) RETURNS TABLE(is_nat text)
    LANGUAGE plpgsql
    AS $$
DECLARE
v_node_connected_ip INET;
BEGIN

  SELECT ip_connected::INET FROM tb_node WHERE node_id = i_node_id INTO v_node_connected_ip;

  IF v_node_connected_ip IS NULL THEN
   RETURN QUERY SELECT 'false'::TEXT AS is_nat;
  ELSE
    RETURN QUERY
   SELECT check_nat.is_nat FROM sp_get_is_nat(v_node_connected_ip) check_nat;
  END IF;

END;
$$;


ALTER FUNCTION public.sp_get_is_nat(i_node_id bigint) OWNER TO cppoltp;

