-- Name: sp_get_issue_agent_node_data(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_issue_agent_node_data(i_product_auth text) RETURNS TABLE(node_id bigint, v3_not_install_server boolean, v3_server_product_name text, v3_server_product_version text, v3_not_install_desktop boolean, v3_desktop_product_name text, v3_desktop_product_version text, v3_not_new_engine boolean, v3_engine_version text, not_manual_scan boolean, last_scan_time text, realtime_scan_off boolean, v3_policy_not_applied boolean, v3_node_policy_data json, malware_scan_30_days boolean, malware_scan_30_cnt text, v3_license_expired boolean, expire_date text, v3_abnormal_integrity boolean, ac_not_install boolean, ac_product_name text, ac_product_version text, ac_license_expired boolean, ac_expire_date text, ac_abnormal_integrity boolean, ac_policy_not_applied boolean, ac_policy_data json, im_policy_not_applied boolean, im_policy_data json, im_manual_rulecheck_not_execute boolean, im_manual_time text, hips_not_install boolean, hips_product_name text, hips_product_version text, hips_license_expired boolean, hips_expire_date text, hips_abnormal_integrity boolean, hips_policy_not_applied boolean, hips_policy_data json, scm_not_install boolean, scm_license_expired boolean, scm_abnormal_integrity boolean, scm_policy_not_applied boolean, scm_manual_scan_not_execute boolean, v3_service_status public.en_product_service_status, engine_update_threshold text, manual_scan_threshold text, im_manual_rulecheck_day_interval text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY SELECT * FROM sp_get_issue_agent_node_detail_data(0, i_product_auth);
END;
$$;


