--
-- Name: sp_get_issue_agent_node_detail_data(bigint, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_issue_agent_node_detail_data(i_node_id bigint, i_product_auth text) RETURNS TABLE(node_id bigint, v3_not_install_server boolean, v3_server_product_name text, v3_server_product_version text, v3_not_install_desktop boolean, v3_desktop_product_name text, v3_desktop_product_version text, v3_not_new_engine boolean, v3_engine_version text, not_manual_scan boolean, last_scan_time text, realtime_scan_off boolean, v3_policy_not_applied boolean, v3_node_policy_data json, malware_scan_30_days boolean, malware_scan_30_cnt text, v3_license_expired boolean, expire_date text, v3_abnormal_integrity boolean, ac_not_install boolean, ac_product_name text, ac_product_version text, ac_license_expired boolean, ac_expire_date text, ac_abnormal_integrity boolean, ac_policy_not_applied boolean, ac_policy_data json, im_policy_not_applied boolean, im_policy_data json, im_manual_rulecheck_not_execute boolean, im_manual_time text, hips_not_install boolean, hips_product_name text, hips_product_version text, hips_license_expired boolean, hips_expire_date text, hips_abnormal_integrity boolean, hips_policy_not_applied boolean, hips_policy_data json, scm_not_install boolean, scm_license_expired boolean, scm_abnormal_integrity boolean, scm_policy_not_applied boolean, scm_manual_scan_not_execute boolean, v3_service_status public.en_product_service_status, engine_update_threshold text, manual_scan_threshold text, im_manual_rulecheck_day_interval text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_engine_update_threshold   BIGINT;
  v_oes_engine_date           timestamp := '9999.12.31'::timestamp;
  v_ses_engine_date           timestamp := '9999.12.31'::timestamp;
  v_manual_scan_threshold     integer := 0;
  v_im_manual_rulecheck_day_interval integer := 0;
  v_scm_manual_scan_day_interval integer := 0;
  v_product_auth              en_product_group_type[];
  v_auth_v3                   boolean := false;
  v_auth_ac                   boolean := false;
  v_auth_hips                 boolean := false;
  v_auth_scm                  boolean := false;
 v_product_name text;
    v_product_version text;
BEGIN

  IF i_product_auth IS NOT NULL AND LENGTH(TRIM(i_product_auth)) > 0 THEN
    v_product_auth := STRING_TO_ARRAY(REPLACE(i_product_auth, ' ', ''), ',')::en_product_group_type[];
  ELSE
    SELECT ENUM_RANGE(null::en_product_group_type) INTO v_product_auth;
  END IF;

  -- 권한 처리
  v_auth_v3   := (sp_exist_license('V3') AND ('V3' = ANY(v_product_auth)));
  v_auth_ac   := (sp_exist_license('AC') AND ('AC' = ANY(v_product_auth)));
  v_auth_hips := (sp_exist_license('HIPS') AND ('HIPS' = ANY(v_product_auth)));
  v_auth_scm := (sp_exist_license('SCM') AND ('SCM' = ANY(v_product_auth)));

  -- 엔진 업데이트 임계치
  SELECT GREATEST(COALESCE(MAX(c.value), '0')::integer -1, 0) INTO v_engine_update_threshold
    FROM tb_config AS c
   WHERE c.config_group = 'AGENT_THRESHOLD' AND c.key = 'engine_update_threshold'
   ;

  -- 수동 검사 임계치
  SELECT GREATEST(COALESCE(MAX(c.value), '0')::integer, 0) INTO v_manual_scan_threshold
  FROM tb_config AS c
  WHERE c.config_group = 'AGENT_THRESHOLD' AND c.key = 'manual_scan_threshold';

  -- 최신 엔진 버전(일자)
  SELECT TO_CHAR(SUBSTRING(MAX(case when key = 'oes_engine_date' THEN c.value END), 1, 10)::timestamp - (v_engine_update_threshold || ' day')::interval, 'YYYY.MM.DD')::timestamp AS oes_engine_date,
         TO_CHAR(SUBSTRING(MAX(case when key = 'ses_engine_date' THEN c.value END), 1, 10)::timestamp - (v_engine_update_threshold || ' day')::interval, 'YYYY.MM.DD')::timestamp AS ses_engine_date
    INTO v_oes_engine_date, v_ses_engine_date
    FROM tb_config AS c
   WHERE c.config_group = 'UPDATE_SERVICE'
   ;
   
  -- IM 무결성모니터링 수동검사 보안점검 설정 값
  SELECT    GREATEST(COALESCE(MAX(c.value), '0')::integer, 0)
  INTO      v_im_manual_rulecheck_day_interval
  FROM      tb_config AS c
  WHERE     c.config_group = 'AGENT_THRESHOLD' AND c.key = 'im_manual_rulecheck_day_interval'
  ;
  
  -- SCM 수동검사 보안점검 설정 값
  SELECT    GREATEST(COALESCE(MAX(c.value), '0')::integer, 0)
  INTO      v_scm_manual_scan_day_interval
  FROM      tb_config AS c
  WHERE     c.config_group = 'AGENT_THRESHOLD' AND c.key = 'manual_scan_day_interval'
  ;

RETURN QUERY
     WITH tb_node_platform AS (
        SELECT
            n.node_id
            , p.is_server
            , p.platform_type
            , COALESCE(tcp.is_amc_supported, TRUE) AS is_am_supported
            , COALESCE(tcp.is_hips_supported, TRUE) AS is_hips_supported
            , COALESCE(tcp.is_ac_supported, TRUE) AS is_ac_supported
            , n.machine_type AS machine_type
        FROM
           tb_node n
        INNER JOIN
           tb_platform p
        ON
           n.platform_id = p.platform_id
        LEFT JOIN
            tb_container_platform tcp
        ON
            tcp.container_service_type = n.container_service_type
        WHERE
            n.is_removed IS FALSE
        AND
            p.is_supported IS TRUE
     ),
     product_info AS (
	    SELECT
	        tb_product.platform_type,
	        tb_product.product_id,
	        tb_product.name,
	        tb_product_pkg.version
	    FROM
	        (
	            SELECT 
	                unnest(platform_support) AS platform_type,
	                product_id,
	                name 
	            FROM tb_product
	        ) AS tb_product
	        LEFT JOIN tb_product_pkg ON tb_product_pkg.product_id = tb_product.product_id
	            AND tb_product_pkg.platform_type::en_platform_type = tb_product.platform_type
	            AND tb_product_pkg.pkg_type = 'PRODUCT_INSTALL'
	            AND tb_product_pkg.is_removed IS FALSE
	),
     antimalware_platform AS (
     	SELECT 
     		a.node_id, 
     		a.engine_version, 
     		a.last_scan_time,
        a.service_status
    	FROM tb_v3_status a,  tb_product b 
    	WHERE v_auth_v3 
    		AND a.product_id = b.product_id 
     ),
     ac_platform AS (
      SELECT
     		a.node_id, 
     		a.engine_version
    	FROM tb_ac_status a,  tb_product b 
    	WHERE v_auth_ac 
        	AND a.product_id = b.product_id 
     ),
     hips_platform AS (
     	SELECT
     		a.node_id, 
     		a.engine_version
    	FROM tb_hips_status a,  tb_product b 
    	WHERE v_auth_hips
    		AND a.product_id = b.product_id 
     ),
     antimalware_product_info AS (
     	SELECT
		    tb_node_platform.node_id,
		    name,
		    version
		FROM 
		    tb_node_platform
		    LEFT JOIN product_info ON product_info.platform_type = tb_node_platform.platform_type
		        AND CASE 
		                WHEN tb_node_platform.machine_type = 'CONTAINER' THEN
		                    product_info.product_id = 'AMC_CLIENT'
		                ELSE
		                    CASE 
		                        WHEN tb_node_platform.platform_type = 'LINUX_UNIX' THEN
		                            product_info.product_id = 'V3NET_LU'
		                        ELSE
		                            product_info.product_id = 'V3NET_9.0'
		                    END
		            END
     ),
     ac_product_info AS (
     	SELECT
		    tb_node_platform.node_id,
		    name,
		    version
		FROM 
		    tb_node_platform
		    LEFT JOIN product_info ON product_info.platform_type = tb_node_platform.platform_type
		    	AND product_info.product_id = 'AC_CLIENT'
     ),
     hips_product_info AS (
     	SELECT
		    tb_node_platform.node_id,
		    name,
		    version
		FROM 
		    tb_node_platform
		    LEFT JOIN product_info ON product_info.platform_type = tb_node_platform.platform_type
		    	AND product_info.product_id = 'HIPS_CLIENT'
     )
     SELECT  
     		n.node_id
            ,COALESCE(n.node_id = v3_not_install_server.node_id, FALSE) --V3 미설치 서버
            ,(SELECT name FROM antimalware_product_info WHERE antimalware_product_info.node_id=n.node_id)::text AS product_name -- 제품명
            ,(SELECT version FROM antimalware_product_info WHERE antimalware_product_info.node_id=n.node_id)::text AS product_version -- 제품버전

            ,COALESCE(n.node_id = v3_not_install_desktop.node_id, FALSE) -- V3 미설치 데스크탑
            ,(SELECT name FROM antimalware_product_info WHERE antimalware_product_info.node_id=n.node_id)::text AS product_name -- 제품명
            ,(SELECT version FROM antimalware_product_info WHERE antimalware_product_info.node_id=n.node_id)::text AS product_version -- 제품버전


            ,COALESCE(n.node_id = v3_not_new_engine.node_id, FALSE) --최신 엔진 미설치
            ,(SELECT ap.engine_version FROM antimalware_platform ap WHERE ap.node_id = n.node_id)::text AS engine_version -- 엔진 버전

            ,COALESCE(n.node_id = not_manual_scan.node_id, FALSE) --V3 최근 수동 검사 미실행
            ,(SELECT ap.last_scan_time FROM antimalware_platform ap WHERE ap.node_id = n.node_id)::text AS last_scan_time --수동검사일
    
            
            ,COALESCE(n.node_id = realtime_scan_off.node_id, false) --실시간 검사 off
            
            ,COALESCE(n.node_id = v3_policy_not_applied.node_id, false) --V3 정책 미적용
            ,(
	            SELECT
				  json_agg(json_build_object('product_feature_id', ps.product_feature_id, 'name', tp.name, 'policy_status', ps.policy_status)) AS node_policy_data
				FROM vw_policy_status AS ps
					JOIN tb_product_feature_map AS pf ON pf.product_feature_id = ps.product_feature_id AND pf.product_feature_id <> 'V3NET_LU_UPDATE'
					JOIN tb_product AS p ON p.product_id = pf.product_id AND p.product_group = 'V3'
					JOIN tb_policy AS tp ON tp.policy_id = ps.policy_id
				WHERE v_auth_v3 
					AND ps.node_id = n.node_id   
					GROUP BY ps.node_id
            )::json AS node_policy_data  -- V3 정책명
            
            ,COALESCE(n.node_id = malware_scan_30_days.node_id, FALSE) --악성코드 탐지 (최근 30일)
            ,(
            	SELECT count(*)
                FROM tb_v3_alert_timeline a
              WHERE v_auth_v3 
                AND a.reg_date > NOW() - INTERVAL '30 days'
                AND a.node_id = n.node_id
            )::text AS malware_scan_30_cnt -- 악성코드 개수
            
            ,COALESCE(n.node_id = v3_license_expired.node_id, FALSE) --V3 라이선스 만료 
            ,(
            	SELECT
					DISTINCT tml.expire_date
				FROM tb_v3_status a
					LEFT JOIN tb_multi_license tml ON a.product_id = tml.product_id
				WHERE v_auth_v3 
					AND a.node_id = n.node_id
					AND tml.expire_date IS NOT null
		            ORDER BY tml.expire_date DESC LIMIT 1
            )::text AS expire_date -- V3 라이선스 만료일
            
            ,COALESCE(n.node_id = v3_abnormal_integrity.node_id, FALSE) --V3 무결성 손상
            
            ,COALESCE(n.node_id = ac_not_install.node_id, FALSE) --AC 미설치
            ,(SELECT name FROM ac_product_info WHERE ac_product_info.node_id = n.node_id)::text AS product_name -- 제품명
            ,(SELECT version FROM ac_product_info  WHERE ac_product_info.node_id = n.node_id)::text AS product_version -- 제품버전

            
            ,COALESCE(n.node_id = ac_license_expired.node_id, FALSE) --AC 라이선스 만료
            ,(
            	SELECT
				    DISTINCT tml.expire_date
				FROM tb_ac_status a
					LEFT JOIN tb_multi_license tml ON a.product_id = tml.product_id
				WHERE v_auth_ac 
					AND a.node_id = n.node_id
				    AND tml.expire_date IS NOT null
		            ORDER BY tml.expire_date DESC LIMIT 1
             )::text AS expire_date --AC 라이선스 만료일
            
            ,COALESCE(n.node_id = ac_abnormal_integrity.node_id, FALSE) --AC 무결성 손상
            
            ,COALESCE(n.node_id = ac_policy_not_applied.node_id, FALSE) --AC 정책 미적용
            ,(
            	SELECT 
					json_agg(json_build_object('product_feature_id', ps.product_feature_id, 'name', p.name, 'policy_status',ps.policy_status)) as policy_data 
				FROM vw_policy_status AS ps
					JOIN tb_product_feature_map AS pf ON pf.product_feature_id = ps.product_feature_id
					JOIN tb_product AS p ON p.product_id = pf.product_id AND p.product_group = 'AC'
				WHERE v_auth_ac 
					AND ps.product_feature_id IN ('AC_AGENT', 'AC_MGMT')
					AND ps.node_id = n.node_id
					GROUP BY ps.node_id
            )::json AS ac_policy_data -- AC 정책데이터
            
            ,COALESCE(n.node_id = im_policy_not_applied.node_id, FALSE) --IM 정책 미적용
            ,(
            	SELECT 
					json_agg(json_build_object('product_feature_id', ps.product_feature_id, 'name', p.name, 'policy_status',ps.policy_status)) as policy_data 
				FROM vw_policy_status AS ps
					JOIN tb_product_feature_map AS pf ON pf.product_feature_id = ps.product_feature_id
					JOIN tb_product AS p ON p.product_id = pf.product_id AND p.product_group = 'AC'
				WHERE v_auth_ac
				    AND ps.product_feature_id = 'IM_MGMT'
				 	AND ps.node_id = n.node_id 
					GROUP BY ps.node_id
            )::json AS im_policy_data
            
            ,COALESCE(n.node_id = im_manual_rulecheck_not_execute.node_id, FALSE) --IM 무결성모니터링 수동검사 미실행
            ,(
            	 SELECT DISTINCT a.im_manual_time
					FROM tb_ac_status a
		         WHERE v_auth_ac
		           AND a.node_id = n.node_id
		           AND a.im_manual_time IS NOT null
		           ORDER BY a.im_manual_time DESC LIMIT 1
            )::text AS im_manual_time
            
            ,COALESCE(n.node_id = hips_not_install.node_id, FALSE) --HIPS 미설치
            ,(SELECT name FROM hips_product_info WHERE hips_product_info.node_id = n.node_id)::text AS product_name -- 제품명
            ,(SELECT version FROM hips_product_info WHERE hips_product_info.node_id = n.node_id)::text AS product_version -- 제품버전

            ,COALESCE(n.node_id = hips_license_expired.node_id, FALSE) --HIPS 라이선스 만료
            ,(
            	SELECT
				    DISTINCT tml.expire_date
				FROM tb_hips_status a
					LEFT JOIN tb_multi_license tml ON a.product_id = tml.product_id
				WHERE v_auth_hips 
					AND a.node_id = n.node_id
					AND tml.expire_date IS NOT null
		        ORDER BY tml.expire_date DESC LIMIT 1
            )::text AS hips_expire_date  -- HIPS 라이선스 만료일
            
            ,COALESCE(n.node_id = hips_abnormal_integrity.node_id, FALSE) --HIPS 무결성 손상
            
            ,COALESCE(n.node_id = hips_policy_not_applied.node_id, FALSE) --HIPS 정책 미적용
            ,(
            	SELECT
				  json_agg(json_build_object('product_feature_id', ps.product_feature_id, 'name', tp."name", 'policy_status', ps.policy_status)) AS policy_map
				FROM vw_policy_status AS ps
					JOIN tb_product_feature_map AS pf ON pf.product_feature_id = ps.product_feature_id
					JOIN tb_product AS p ON p.product_id = pf.product_id AND p.product_group = 'HIPS'
					JOIN tb_policy AS tp ON tp.policy_id = ps.policy_id
				WHERE v_auth_hips
					AND ps.node_id = n.node_id
					GROUP BY ps.node_id
            )::json AS hips_policy_data -- 정책명
            
            ,COALESCE(n.node_id = scm_not_install.node_id, FALSE)
            
            ,COALESCE(n.node_id = scm_license_expired.node_id, FALSE)
            
            ,COALESCE(n.node_id = scm_abnormal_integrity.node_id, FALSE)
            
            ,COALESCE(n.node_id = scm_policy_not_applied.node_id, FALSE)
            
            ,COALESCE(n.node_id = scm_manual_scan_not_execute.node_id, FALSE)

            ,(SELECT ap.service_status FROM antimalware_platform ap WHERE ap.node_id = n.node_id)::en_product_service_status AS v3_service_status

            ,(SELECT value FROM tb_config WHERE config_group ='AGENT_THRESHOLD' AND key = 'engine_update_threshold')

            ,(SELECT value FROM tb_config WHERE config_group ='AGENT_THRESHOLD' AND key = 'manual_scan_threshold')

            ,(SELECT value FROM tb_config WHERE config_group ='AGENT_THRESHOLD' AND key = 'im_manual_rulecheck_day_interval')
      
        FROM tb_node_platform n
      --V3 미설치 서버
      LEFT JOIN (
        SELECT n.node_id
          FROM tb_node_platform n
         WHERE v_auth_v3
           AND n.is_server IS TRUE
           AND n.is_am_supported IS TRUE
           AND NOT EXISTS (
             SELECT 1
               FROM tb_product_info AS pi
               JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'V3'
              WHERE n.node_id = pi.node_id
                AND n.is_am_supported IS TRUE
           )
      ) AS v3_not_install_server on n.node_id = v3_not_install_server.node_id
      --V3 미설치 데스크탑
      LEFT JOIN (
        SELECT n.node_id
          FROM tb_node_platform n
         WHERE v_auth_v3
           AND n.is_server IS FALSE
           AND n.is_am_supported IS TRUE
           AND NOT EXISTS (
             SELECT 1
               FROM tb_product_info AS pi
               JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'V3'
              WHERE n.node_id = pi.node_id
                AND n.is_am_supported IS TRUE
           )
      ) AS v3_not_install_desktop on n.node_id = v3_not_install_desktop.node_id
      --최신 엔진 미설치
      LEFT JOIN (
        (
          SELECT pi.node_id
            FROM tb_product_info pi
            JOIN tb_product AS p ON pi.product_id = p.product_id AND p.product_group = 'V3'
            LEFT JOIN tb_v3_status vs ON pi.node_id = vs.node_id AND pi.product_id = vs.product_id
           WHERE v_auth_v3
             AND (vs.engine_type = 'OES' OR vs.engine_type IS NULL)
             AND (vs.engine_update_time < v_oes_engine_date OR vs.engine_update_time IS NULL)
        )
        UNION
        (
          SELECT pi.node_id
            FROM tb_product_info pi
            JOIN tb_product AS p ON pi.product_id = p.product_id AND p.product_group = 'V3'
            LEFT JOIN tb_v3_status vs ON pi.node_id = vs.node_id AND pi.product_id = vs.product_id
           WHERE v_auth_v3
             AND vs.engine_type = 'SES'
             AND (vs.engine_update_time < v_ses_engine_date OR vs.engine_update_time IS NULL)
        )
      ) AS v3_not_new_engine on n.node_id = v3_not_new_engine.node_id
      --최근 수동 검사 미실행
      LEFT JOIN (
        SELECT n.node_id
          FROM tb_node_platform n
          JOIN tb_product_info pi ON n.node_id = pi.node_id
          JOIN tb_product AS p ON pi.product_id = p.product_id AND p.product_group = 'V3'
          LEFT JOIN tb_v3_status vs ON n.node_id = vs.node_id AND pi.product_id = vs.product_id
         WHERE v_auth_v3
           AND (vs.last_scan_time < date_trunc('day', now()) - (v_manual_scan_threshold -1 || 'day')::INTERVAL OR vs.last_scan_time IS NULL)
      ) AS not_manual_scan on n.node_id = not_manual_scan.node_id
      --실시간 검사 off
      LEFT JOIN (
        SELECT n.node_id
          FROM tb_node_platform n
          JOIN tb_product_info pi ON n.node_id = pi.node_id
          JOIN tb_product AS p ON pi.product_id = p.product_id AND p.product_group = 'V3'
          LEFT JOIN tb_v3_status vs ON n.node_id = vs.node_id AND pi.product_id = vs.product_id
         WHERE v_auth_v3
           AND (vs.realtime_status IS FALSE OR vs.realtime_status IS NULL)
      ) AS realtime_scan_off on n.node_id = realtime_scan_off.node_id
      --V3 정책 미적용
      LEFT JOIN (
        SELECT DISTINCT n.node_id
          FROM tb_node_platform n
          JOIN (
            SELECT DISTINCT ps.node_id, ps.policy_status
              FROM vw_policy_status AS ps
              JOIN tb_product_feature_map AS pf ON pf.product_feature_id = ps.product_feature_id AND pf.product_feature_id <> 'V3NET_LU_UPDATE'
              JOIN tb_product AS p ON p.product_id = pf.product_id AND p.product_group = 'V3'
             WHERE v_auth_v3
               AND ps.policy_status = 'NOT_APPLIED'
          ) AS ps ON n.node_id = ps.node_id
          WHERE n.is_am_supported IS TRUE
      ) AS v3_policy_not_applied on n.node_id = v3_policy_not_applied.node_id
      --악성코드 탐지 (최근 30일)
      LEFT JOIN (
        SELECT DISTINCT tv.node_id
          FROM tb_timeline_v3 AS tv
          JOIN tb_product_info AS pi ON tv.node_id = pi.node_id
          JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'V3'
         WHERE v_auth_v3
           AND tv.reg_date BETWEEN TO_CHAR(now() - '29 DAY'::interval, 'YYYYMMDD') AND TO_CHAR(now(), 'YYYYMMDD')
           AND (COALESCE(tv.malware_clean_count,0) > 0 OR COALESCE(tv.malware_clean_fail_count,0) > 0)
      ) AS malware_scan_30_days on n.node_id = malware_scan_30_days.node_id
      --V3 라이선스 만료
      LEFT JOIN (
          SELECT n.node_id
            FROM tb_node_platform AS n
            JOIN tb_product_info AS pi ON n.node_id = pi.node_id
            JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'V3'
            JOIN (
                SELECT
                    vs.node_id
                    , vs.product_id
                    , CASE
                        WHEN vs.activation_code IS NOT NULL AND vs.activation_code != '' THEN vs.activation_code 
                        WHEN vs.license_no IS NOT NULL AND vs.license_no != '' THEN vs.license_no
                        ELSE NULL
                        END AS license_no
                FROM tb_v3_status vs
            ) vs ON n.node_id = vs.node_id AND pi.product_id = vs.product_id
            LEFT JOIN tb_multi_license pl ON vs.product_id = pl.product_id AND vs.license_no = pl.license_no
           WHERE v_auth_v3
             AND (pl.expire_date < CURRENT_DATE OR pl.expire_date IS NULL)
      ) AS v3_license_expired on n.node_id = v3_license_expired.node_id
      --V3 무결성 손상
      LEFT JOIN (
          SELECT v.node_id
            FROM tb_v3_status v
            JOIN tb_product_info pi ON v.node_id = pi.node_id AND v.product_id = pi.product_id
            JOIN tb_product AS p ON pi.product_id = p.product_id AND p.product_group = 'V3'
           WHERE v_auth_v3
             AND v.integrity_status = 'ABNORMAL'
      ) AS v3_abnormal_integrity on n.node_id = v3_abnormal_integrity.node_id
      --AC 미설치
      LEFT JOIN (
        SELECT n.node_id
          FROM tb_node_platform AS n
         WHERE v_auth_ac
           AND n.is_ac_supported IS TRUE
           AND NOT EXISTS (
             SELECT pi.node_id
               FROM tb_product_info AS pi
               JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'AC'
               WHERE pi.node_id = n.node_id
                 AND n.is_ac_supported IS TRUE
           )
      ) AS ac_not_install on n.node_id = ac_not_install.node_id
      --AC 라이선스 만료
      LEFT JOIN (
          SELECT n.node_id
            FROM tb_node_platform AS n
            JOIN tb_product_info AS pi ON n.node_id = pi.node_id
            JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'AC'
            JOIN (
                SELECT
                    ac.node_id
                    , ac.product_id
                    , CASE
                        WHEN ac.activation_code IS NOT NULL AND ac.activation_code != '' THEN ac.activation_code 
                        WHEN ac.license_no IS NOT NULL AND ac.license_no != '' THEN ac.license_no
                        ELSE NULL
                        END AS license_no
                FROM tb_ac_status ac
            ) vs ON n.node_id = vs.node_id AND pi.product_id = vs.product_id
            LEFT JOIN tb_multi_license pl ON vs.product_id = pl.product_id AND vs.license_no = pl.license_no
           WHERE v_auth_ac
             AND (pl.expire_date < CURRENT_DATE OR pl.expire_date IS NULL)
      ) AS ac_license_expired on n.node_id = ac_license_expired.node_id
      --AC 무결성 손상
      LEFT JOIN (
        SELECT v.node_id
          FROM tb_ac_status AS v
          JOIN tb_product_info AS pi ON v.node_id = pi.node_id AND v.product_id = pi.product_id
          JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'AC'
         WHERE v_auth_ac
           AND v.integrity_status = 'ABNORMAL'
      ) AS ac_abnormal_integrity on n.node_id = ac_abnormal_integrity.node_id
      --AC 정책 미적용
      LEFT JOIN (
        SELECT DISTINCT n.node_id
          FROM tb_node_platform AS n
          JOIN (
            SELECT ps.node_id, ps.policy_status
            FROM vw_policy_status AS ps
            JOIN tb_product_feature_map AS pf ON pf.product_feature_id = ps.product_feature_id
            JOIN tb_product AS p ON p.product_id = pf.product_id AND p.product_group = 'AC'
           WHERE v_auth_ac
             AND ps.policy_status = 'NOT_APPLIED'
             AND ps.product_feature_id IN ('AC_AGENT', 'AC_MGMT')
          ) AS ps ON n.node_id = ps.node_id
          WHERE n.is_ac_supported IS TRUE
      ) AS ac_policy_not_applied on n.node_id = ac_policy_not_applied.node_id
      --IM 정책 미적용
      LEFT JOIN (
        SELECT DISTINCT n.node_id
          FROM tb_node_platform AS n
          JOIN (
            SELECT ps.node_id, ps.policy_status
            FROM vw_policy_status AS ps
            JOIN tb_product_feature_map AS pf ON pf.product_feature_id = ps.product_feature_id
            JOIN tb_product AS p ON p.product_id = pf.product_id AND p.product_group = 'AC'
           WHERE v_auth_ac
             AND ps.policy_status = 'NOT_APPLIED'
             AND ps.product_feature_id = 'IM_MGMT'
          ) AS ps ON n.node_id = ps.node_id
          WHERE n.is_ac_supported IS TRUE
      ) AS im_policy_not_applied on n.node_id = im_policy_not_applied.node_id
      --IM 무결성모니터링 수동검사 미실행
      LEFT JOIN (
        SELECT n.node_id
          FROM tb_node_platform n
          JOIN tb_product_info pi ON n.node_id = pi.node_id
          JOIN tb_product AS p ON pi.product_id = p.product_id AND p.product_group = 'AC'
          LEFT JOIN tb_ac_status ac ON n.node_id = ac.node_id AND pi.product_id = ac.product_id
         WHERE v_auth_ac
           AND (ac.im_manual_time < date_trunc('day', now()) - (v_im_manual_rulecheck_day_interval -1 || 'day')::INTERVAL OR ac.im_manual_time IS NULL)
      ) AS im_manual_rulecheck_not_execute on n.node_id = im_manual_rulecheck_not_execute.node_id
      --HIPS 미설치
      LEFT JOIN (
        SELECT n.node_id
          FROM tb_node_platform AS n
         WHERE v_auth_hips
           AND n.is_hips_supported IS TRUE
           AND NOT EXISTS (
             SELECT pi.node_id
               FROM tb_product_info AS pi
               JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'HIPS'
               WHERE pi.node_id = n.node_id
                 AND n.is_hips_supported IS TRUE
           )
      ) AS hips_not_install on n.node_id = hips_not_install.node_id
      --HIPS 라이선스 만료
      LEFT JOIN (
          SELECT n.node_id
            FROM tb_node_platform AS n
            JOIN tb_product_info AS pi ON n.node_id = pi.node_id
            JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'HIPS'
            JOIN (
                SELECT
                    hs.node_id
                    , hs.product_id
                    , CASE
                        WHEN hs.activation_code IS NOT NULL AND hs.activation_code != '' THEN hs.activation_code 
                        WHEN hs.license_no IS NOT NULL AND hs.license_no != '' THEN hs.license_no
                        ELSE NULL
                        END AS license_no
                FROM tb_hips_status hs
            ) vs ON n.node_id = vs.node_id AND pi.product_id = vs.product_id
            LEFT JOIN tb_multi_license pl ON vs.product_id = pl.product_id AND vs.license_no = pl.license_no
           WHERE v_auth_hips
             AND (pl.expire_date < CURRENT_DATE OR pl.expire_date IS NULL)
      ) AS hips_license_expired on n.node_id = hips_license_expired.node_id
      --HIPS 무결성 손상
      LEFT JOIN (
        SELECT v.node_id
          FROM tb_hips_status AS v
          JOIN tb_product_info AS pi ON v.node_id = pi.node_id AND v.product_id = pi.product_id
          JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'HIPS'
         WHERE v_auth_hips
           AND v.integrity_status = 'ABNORMAL'
      ) AS hips_abnormal_integrity on n.node_id = hips_abnormal_integrity.node_id
      --HIPS 정책 미적용
      LEFT JOIN (
        SELECT DISTINCT n.node_id
          FROM tb_node_platform AS n
          JOIN (
            SELECT ps.node_id, ps.policy_status
            FROM vw_policy_status AS ps
            JOIN tb_product_feature_map AS pf ON pf.product_feature_id = ps.product_feature_id
            JOIN tb_product AS p ON p.product_id = pf.product_id AND p.product_group = 'HIPS'
           WHERE v_auth_hips
             AND ps.policy_status = 'NOT_APPLIED'
          ) AS ps ON n.node_id = ps.node_id
          WHERE n.is_hips_supported IS TRUE
      ) AS hips_policy_not_applied on n.node_id = hips_policy_not_applied.node_id

      --SCM 미설치
      LEFT JOIN (
        SELECT n.node_id
          FROM tb_node_platform AS n
         WHERE v_auth_scm
           AND NOT EXISTS (
             SELECT pi.node_id
               FROM tb_product_info AS pi
               JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'SCM'
               WHERE pi.node_id = n.node_id
           )
      ) AS scm_not_install on n.node_id = scm_not_install.node_id
      --SCM 라이선스 만료
      LEFT JOIN (
          SELECT n.node_id
            FROM tb_node_platform AS n
            JOIN tb_product_info AS pi ON n.node_id = pi.node_id
            JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'SCM'
            JOIN tb_hips_status vs ON n.node_id = vs.node_id AND pi.product_id = vs.product_id
            LEFT JOIN tb_product_license pl ON vs.product_id = pl.product_id
           WHERE v_auth_scm
             AND (pl.expire_date < CURRENT_DATE OR pl.expire_date IS NULL)
      ) AS scm_license_expired on n.node_id = scm_license_expired.node_id
      --SCM 무결성 손상
      LEFT JOIN (
        SELECT v.node_id
          FROM tb_hips_status AS v
          JOIN tb_product_info AS pi ON v.node_id = pi.node_id AND v.product_id = pi.product_id
          JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'SCM'
         WHERE v_auth_scm
           AND v.integrity_status = 'ABNORMAL'
      ) AS scm_abnormal_integrity on n.node_id = scm_abnormal_integrity.node_id
      --SCM 정책 미적용
      LEFT JOIN (
        SELECT DISTINCT n.node_id
          FROM tb_node_platform AS n
          JOIN (
            SELECT ps.node_id, ps.policy_status
            FROM vw_policy_status AS ps
            JOIN tb_product_feature_map AS pf ON pf.product_feature_id = ps.product_feature_id
            JOIN tb_product AS p ON p.product_id = pf.product_id AND p.product_group = 'SCM'
           WHERE v_auth_scm
             AND ps.policy_status = 'NOT_APPLIED'
          ) AS ps ON n.node_id = ps.node_id
      ) AS scm_policy_not_applied on n.node_id = scm_policy_not_applied.node_id
      --SCM 수동검사 미수행
      LEFT JOIN (
        SELECT n.node_id
          FROM tb_node_platform n
          JOIN tb_product_info pi ON n.node_id = pi.node_id
          JOIN tb_product AS p ON pi.product_id = p.product_id AND p.product_group = 'SCM'
          LEFT JOIN tb_scm_status scm ON n.node_id = scm.node_id AND pi.product_id = scm.product_id
         WHERE v_auth_scm
           AND (scm.scan_time < date_trunc('day', now()) - (v_scm_manual_scan_day_interval -1 || 'day')::INTERVAL OR scm.scan_time IS NULL)
      ) AS scm_manual_scan_not_execute on n.node_id = scm_manual_scan_not_execute.node_id
      WHERE n.node_id = CASE WHEN i_node_id = 0 THEN n.node_id ELSE i_node_id END
      ;
END;
$$;


