--
-- Name: sp_get_job_schedule(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_job_schedule(i_job_id bigint) RETURNS TABLE(job_id bigint, admin_id text, schedule_detail text, tenant_server bigint, now_time text)
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_tenant_server			BIGINT;
	v_now_time				TEXT;
BEGIN

	IF (i_job_id = 0) then
		RETURN QUERY
			SELECT
				sch.job_id
				, sch.admin_id
				, sch.schedule_detail
				, v_tenant_server
				, v_now_time
			FROM tb_job as sch
			WHERE sch.onoff = true
			AND sch.is_schedule = true
		;
	ELSE
		SELECT
			tenant.tenant_server
			, to_char(now(), 'YYYYMMDDHH24MI') AS now_time
			INTO v_tenant_server, v_now_time
		FROM (
			SELECT
				tst.tenant_server, count(*) AS cnt
			FROM tb_schedule_trigger tst GROUP BY tst.tenant_server
		)tenant ORDER BY tenant.cnt LIMIT 1
		;

		RETURN QUERY
			SELECT
				sch.job_id
				, sch.admin_id
				, sch.schedule_detail
				, v_tenant_server
				, v_now_time
			FROM tb_job as sch
			WHERE sch.onoff = true
			AND sch.is_schedule = true
			AND sch.job_id = i_job_id
		;
	END IF;
END;
$$;


