--
-- Name: sp_get_keep_agent_policy(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_keep_agent_policy() RETURNS TABLE(node_id bigint, is_agent_policy integer, is_v3_policy integer, is_ac_agent_policy integer, is_ac_mgmt_policy integer, is_hips_agent_policy integer, is_hips_mgmt_policy integer, is_hips_fw_policy integer, is_im_mgmt_policy integer)
    LANGUAGE plpgsql
    AS $_$
BEGIN

  RETURN QUERY
    SELECT
      np.node_id AS node_id
      , COALESCE(np.is_agent_policy, 0) AS is_agent_policy
      , CASE WHEN COALESCE(np.is_v3_net_policy, 0) + COALESCE(np.is_v3_lu_policy,0) + COALESCE(np.is_amc_mgmt_policy,0) > 0 THEN 1 ELSE 0 END AS is_v3_policy
      , COALESCE(np.is_ac_agent_policy, 0) AS is_ac_agent_policy
      , COALESCE(np.is_ac_mgmt_policy, 0) AS is_ac_mgmt_policy
      , COALESCE(np.is_hips_agent_policy, 0) AS is_hips_agent_policy
      , COALESCE(np.is_hips_mgmt_policy, 0) AS is_hips_mgmt_policy
      , COALESCE(np.is_hips_fw_policy, 0) AS is_hips_fw_policy
      , COALESCE(np.is_im_mgmt_policy, 0) AS is_im_mgmt_policy
    FROM crosstab(
      $func$
        SELECT
          np.node_id
          , np.product_feature_id
          , np.keep_agent_policy::integer
        FROM tb_node_policy np
          JOIN tb_node n ON np.node_id = n.node_id
            AND n.is_removed IS FALSE AND np.keep_agent_policy IS TRUE
        ORDER BY 1
      $func$,
      $func$
        VALUES ('AGENT_MGMT'), ('V3NET_9.0_AV'), ('V3NET_LU_AV'), ('AC_AGENT'), ('AC_MGMT'), ('HIPS_AGENT'), ('HIPS_MGMT'), ('HIPS_FW'), ('IM_MGMT'), ('AMC_MGMT')
        $func$
      ) AS np(node_id bigint, is_agent_policy integer, is_v3_net_policy integer, is_v3_lu_policy integer,
          is_ac_agent_policy integer, is_ac_mgmt_policy integer,
          is_hips_agent_policy integer, is_hips_mgmt_policy integer, is_hips_fw_policy integer,
          is_im_mgmt_policy integer, is_amc_mgmt_policy integer);

END;
$_$;


ALTER FUNCTION public.sp_get_keep_agent_policy() OWNER TO cppoltp;

