--

CREATE FUNCTION public.sp_get_language_code_to_text(i_language integer) RETURNS TABLE(language public.en_language)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT CASE WHEN i_language = 1 THEN 'ko'
                WHEN i_language = 2 THEN 'en'
                WHEN i_language = 3 THEN 'ko'
                WHEN i_language = 4 THEN 'ja'
                WHEN i_language = 5 THEN 'zh-Hans'
                WHEN i_language = 6 THEN 'others'
            END :: en_language;
END;
$$;


