-- Name: sp_get_last_obj_id(public.en_olap_table_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_last_obj_id(i_olap_table public.en_olap_table_type) RETURNS TABLE(last_obj_id text, current_iso_time text)
    LANGUAGE plpgsql
    AS $$
DECLARE v_last_obj_id TEXT;
DECLARE v_current_iso_time TEXT;
BEGIN

select o.last_obj_id, sp_get_current_iso_time() INTO v_last_obj_id, v_current_iso_time from tb_olap_table o where o.olap_table = i_olap_table;

IF (v_last_obj_id IS NULL) THEN
  RETURN QUERY select '0'::text, sp_get_current_iso_time();
ELSE
  RETURN QUERY select o.last_obj_id, sp_get_current_iso_time() from tb_olap_table o where o.olap_table = i_olap_table;
END IF;

END;
$$;


