CREATE FUNCTION public.sp_get_latest_engine_path(i_server_id bigint, i_pkg_type public.en_pkg_type) RETURNS TABLE(v_pkg_path text)
    LANGUAGE plpgsql
    AS $$
BEGIN

RETURN QUERY
  SELECT path AS v_pkg_path FROM tb_product_pkg
WHERE version = (
SELECT  max(version) FROM tb_product_pkg
WHERE pkg_type = i_pkg_type AND product_pkg_id IN ( SELECT product_pkg_id FROM tb_pkg_server WHERE server_id = i_server_id ))
AND pkg_type = i_pkg_type AND product_pkg_id IN ( SELECT product_pkg_id FROM tb_pkg_server WHERE server_id = i_server_id )
AND is_removed is false;
END;

$$;


