--
-- Name: sp_get_latest_engine_update_datetime(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_latest_engine_update_datetime() RETURNS timestamp with time zone[]
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_engine_update_threshold   integer := 0;
  v_oes_engine_version        text;
  v_oes_engine_date           timestamptz := '9999.12.31'::timestamptz;
  v_ses_engine_version        text;
  v_ses_engine_date           timestamptz := '9999.12.31'::timestamptz;
BEGIN

  -- 엔진 업데이트 임계치
  SELECT GREATEST(COALESCE(c.value, '0')::integer - 1, 0) INTO v_engine_update_threshold
  FROM tb_config AS c
  WHERE c.config_group = 'AGENT_THRESHOLD' AND c.key = 'engine_update_threshold';

  -- oes_engine_version
  SELECT c.value INTO v_oes_engine_version
  FROM tb_config AS c
  WHERE c.config_group = 'UPDATE_SERVICE' AND c.key = 'oes_engine_date';

  IF COALESCE(TRIM(v_oes_engine_version), '') <> '' THEN
    SELECT TO_CHAR(SUBSTRING(v_oes_engine_version, 1, 10)::timestamptz - (v_engine_update_threshold || ' day')::interval, 'YYYY.MM.DD')::timestamptz INTO v_oes_engine_date;
  END IF;

  -- ses_engine_version
  SELECT c.value INTO v_ses_engine_version
  FROM tb_config AS c
  WHERE c.config_group = 'UPDATE_SERVICE' AND c.key = 'ses_engine_date';

  IF COALESCE(TRIM(v_ses_engine_version), '') <> '' THEN
    SELECT TO_CHAR(SUBSTRING(v_ses_engine_version, 1, 10)::timestamptz - (v_engine_update_threshold || ' day')::interval, 'YYYY.MM.DD')::timestamptz INTO v_ses_engine_date;
  END IF;

  RETURN ARRAY[v_oes_engine_date, v_ses_engine_date];

END;
$$;


ALTER FUNCTION public.sp_get_latest_engine_update_datetime() OWNER TO cppoltp;

--
-- Name: sp_get_lbdist_http(boolean); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_lbdist_http(is_list boolean) RETURNS TABLE(server text)
    LANGUAGE plpgsql
    AS $$
BEGIN

  IF (is_list = FALSE) THEN
	  RETURN QUERY
	    SELECT concat('http://', (CASE WHEN (SELECT tc.value FROM tb_config tc
	             WHERE tc.config_group = 'NETWORK'
	             AND tc.key = 'use_nat') = 'true'
	             THEN s.public_ip
	             ELSE s.ip END)
	    , ':', ( SELECT sp.port FROM tb_service_port sp WHERE sp.service_type = sv.service_type ), '/') AS server
	  FROM tb_server s, tb_service sv
	  WHERE s.server_id = sv.server_id AND sv.service_type = 'LBDIST-HTTP' AND sv.enabled = TRUE AND sv.static = TRUE;
	ELSE
	  RETURN QUERY
	    SELECT string_agg( concat('http://', (CASE WHEN (SELECT tc.value FROM tb_config tc
	             WHERE tc.config_group = 'NETWORK'
	             AND tc.key = 'use_nat') = 'true'
	             THEN s.public_ip
	             ELSE s.ip END)
	    , ':', ( SELECT sp.port FROM tb_service_port sp WHERE sp.service_type = sv.service_type ), '/'), ',')AS server
	  FROM tb_server s, tb_service sv
	  WHERE s.server_id = sv.server_id AND sv.service_type = 'LBDIST-HTTP' AND sv.enabled = TRUE;
	END IF;

END;
$$;


ALTER FUNCTION public.sp_get_lbdist_http(is_list boolean) OWNER TO cppoltp;

