--
-- Name: sp_get_license_all_expire_date(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_license_all_expire_date(i_node_id text) RETURNS TABLE(product_id public.en_product_id_type, expire_date timestamp without time zone, product_group public.en_product_group_type, is_license_expired text, license_code text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT
        pl.product_id AS product_id
        , tml.expire_date AS expire_date
        , p.product_group AS product_group
        , (CASE WHEN tml.expire_date IS NULL THEN NULL
                WHEN tml.expire_date < now() THEN true ELSE false END)::text AS is_license_expired
        , pl.license_no AS license_code
    FROM (
        SELECT
            'EMS'::en_product_id_type AS product_id
            , CASE
                WHEN ts.activation_code IS NOT NULL AND ts.activation_code != '' THEN ts.activation_code
                WHEN ts.license_no IS NOT NULL AND ts.license_no != '' THEN ts.license_no 
                ELSE NULL
                END AS license_no
        FROM
            tb_node tn
        LEFT JOIN
            tb_node_status ts
        ON
            tn.node_id = ts.node_id 
        AND
            tn.is_removed IS FALSE
        WHERE
            ts.node_id = i_node_id::bigint
            
        UNION
        
        SELECT
            pi.product_id::en_product_id_type AS product_id
            , CASE
                WHEN ts.activation_code IS NOT NULL AND ts.activation_code != '' THEN ts.activation_code
                WHEN ts.license_no IS NOT NULL AND ts.license_no != '' THEN ts.license_no 
                ELSE NULL
                END AS license_no
        FROM (
                SELECT UNNEST(ARRAY['V3NET_9.0','V3NET_LU','AMC_CLIENT'])::en_product_id_type AS product_id
        ) pi
        LEFT JOIN
            tb_v3_status ts
        ON
            ts.product_id = pi.product_id
        AND
            ts.node_id = i_node_id::bigint
            
        UNION
            
        SELECT
            pi.product_id::en_product_id_type AS product_id
            , CASE
                WHEN ts.activation_code IS NOT NULL AND ts.activation_code != '' THEN ts.activation_code
                WHEN ts.license_no IS NOT NULL AND ts.license_no != '' THEN ts.license_no 
                ELSE NULL
                END AS license_no
        FROM (
                SELECT UNNEST(ARRAY['AC_CLIENT'])::en_product_id_type AS product_id
        ) pi
        LEFT JOIN
            tb_ac_status ts
        ON
            ts.product_id = pi.product_id
        AND
            ts.node_id = i_node_id::bigint
            
        UNION
        
        SELECT
            pi.product_id::en_product_id_type AS product_id
            , CASE
                WHEN ts.activation_code IS NOT NULL AND ts.activation_code != '' THEN ts.activation_code
                WHEN ts.license_no IS NOT NULL AND ts.license_no != '' THEN ts.license_no 
                ELSE NULL
                END AS license_no
        FROM (
                SELECT UNNEST(ARRAY['HIPS_CLIENT'])::en_product_id_type AS product_id
        ) pi
        LEFT JOIN
            tb_hips_status ts
        ON
            ts.product_id = pi.product_id
        AND
            ts.node_id = i_node_id::bigint
        
        UNION
        
        SELECT
            ts.product_id::en_product_id_type AS product_id
            , license_no
        FROM (
                SELECT UNNEST(ARRAY['CNAPP'])::en_product_id_type AS product_id
        ) pi
        LEFT JOIN
            tb_multi_license ts
        ON
            pi.product_id = ts.product_id
        AND
            ts.product_id = 'CNAPP'::en_product_id_type
        AND
            ts.is_main_license = TRUE
    ) pl
    INNER JOIN
        tb_product p
    ON
        pl.product_id = p.product_id
    LEFT JOIN
        tb_multi_license tml 
    ON
        tml.license_no = pl.license_no
    AND
        tml.product_id = pl.product_id
;

END;
$$;


ALTER FUNCTION public.sp_get_license_all_expire_date(i_node_id text) OWNER TO cppoltp;

--
-- Name: sp_get_license_expire(public.en_product_group_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_license_expire(i_product_group public.en_product_group_type) RETURNS TABLE(product_group public.en_product_group_type, value text, expire_date text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT
      p.product_group
      , (SUM(CASE WHEN pl.expire_date > now() THEN 1 ELSE 0 END) > 0)::text
      , MAX(pl.expire_date)::text
    FROM tb_product AS p
    JOIN tb_product_license AS pl ON p.product_id = pl.product_id
    WHERE p.product_group = i_product_group
    GROUP BY p.product_group;

END;
$$;


ALTER FUNCTION public.sp_get_license_expire(i_product_group public.en_product_group_type) OWNER TO cppoltp;

