--
-- Name: sp_get_license_expire_list(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_license_expire_list(i_login_admin_id text) RETURNS TABLE(product_group text, product_id public.en_product_id_type, value text, expire_date timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_profile_type              en_privilege_profile_type;
  v_product_auth              text;
  v_product_group             en_product_group_type[] := null;
BEGIN

  -- login_admin_id 의 권한 가져오기
  SELECT p.profile_type, a.product_auth INTO v_profile_type, v_product_auth
  FROM tb_admin AS a
  JOIN tb_privilege_profile AS p ON a.privilege_profile_id = p.privilege_profile_id
  WHERE a.admin_id = i_login_admin_id;

  IF v_profile_type IN ('PRODUCT_ADMIN') THEN
    BEGIN
      v_product_group := STRING_TO_ARRAY(v_product_auth, ',')::en_product_group_type[];
    EXCEPTION
      WHEN others THEN
        v_product_group := null;
    END;
  ELSE
    SELECT ENUM_RANGE(null::en_product_group_type) INTO v_product_group;
  END IF;

  RETURN QUERY
    SELECT t.product_group, t.product_id, t.value, t.expire_date
    FROM (
      SELECT
        p.product_group::text
        , NULL::en_product_id_type AS product_id
        , (SUM(CASE WHEN pl.expire_date > now() THEN 1 ELSE 0 END) > 0)::text AS value
        , MAX(pl.expire_date) AS expire_date
      FROM tb_product AS p
      JOIN tb_product_license AS pl ON p.product_id = pl.product_id
      WHERE p.product_group = ANY(v_product_group)
        AND pl.expire_date IS NOT NULL
      GROUP BY p.product_group
    ) AS t
    ORDER BY CASE t.product_group WHEN 'EMS' THEN 1 WHEN 'V3' THEN 2 WHEN 'AC' THEN 3 WHEN 'HIPS' THEN 4 ELSE 9 END;

END;
$$;


ALTER FUNCTION public.sp_get_license_expire_list(i_login_admin_id text) OWNER TO cppoltp;

