--
-- Name: sp_get_license_list(public.en_product_group_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_license_list(i_product_group public.en_product_group_type) RETURNS TABLE(product_group public.en_product_group_type, product_id public.en_product_id_type, name text, platform text, is_manageable_license text, license_no text, service_date timestamp without time zone, expire_date timestamp without time zone, sub_type public.en_license_sub_type, system_datetime timestamp with time zone, expire_update_status text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT
      p.product_group
      , p.product_id
      , p.name
      , array_to_string(array_agg(pp.platform_type), ',') platform
      , pl.is_manageable_license::text
      , pl.license_no
      , pl.service_date
      , pl.expire_date
      , pl.sub_type
      , now()
      , CASE 
        WHEN pl.expire_date IS NULL THEN 'READY'
        WHEN pl.product_id = 'EMS'::en_product_id_type AND pl.expire_date < NOW() +'8 day'::INTERVAL THEN 'READY'
        WHEN pl.product_id = 'EMS'::en_product_id_type and pl.expire_date IS NOT null AND pl.expire_date >= NOW() +'8 day'::INTERVAL THEN 'FINISH'
        WHEN pl.product_id != 'EMS'::en_product_id_type AND pl.expire_date IS NOT NULL THEN 'FINISH'
        ELSE pl.expire_update_status 
        END AS expire_update_status 
    FROM
      tb_product AS p
      INNER JOIN tb_product_license AS pl ON p.product_id = pl.product_id
      LEFT JOIN (
        SELECT
          pp.product_id, pp.platform_type, ROW_NUMBER() OVER(PARTITION BY pp.product_id ORDER BY pp.product_pkg_id DESC) AS row_num
        FROM
          tb_product_pkg AS pp
        WHERE
          pp.is_removed is FALSE
      ) AS pp ON p.product_id = pp.product_id
    WHERE
      p.product_group = CASE WHEN 'EMS' = 'EMS' THEN p.product_group ELSE 'EMS' END
      AND pl.is_manageable_license IS NOT FALSE
    GROUP BY
      p.product_id, pl.is_manageable_license, pl.product_id , pl.license_no
    ORDER BY
      p.product_group;

END;
$$;


