--
-- Name: sp_get_local_timestamp_from_object_id(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_local_timestamp_from_object_id(i_obj_id text) RETURNS timestamp without time zone
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_local_timestamp timestamp;
BEGIN
	SELECT to_timestamp(t.val)::timestamp
	INTO v_local_timestamp
	FROM (
		SELECT ('x' || lpad(left(t.objectid, 8), 8, '0'))::bit(32)::int AS val
		FROM (
			values(i_obj_id)
		) AS t(objectid)
	) t;
	RETURN v_local_timestamp;

END;
$$;


ALTER FUNCTION public.sp_get_local_timestamp_from_object_id(i_obj_id text) OWNER TO cppoltp;

