CREATE FUNCTION public.sp_get_log_config_list(i_product_group public.en_product_group_type) RETURNS TABLE(log_type public.en_log_type, send text, product_group_type public.en_product_group_type)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT
      l.log_type
      , l.send::text
      , l.product_group_type
    FROM tb_log_config AS l
    WHERE l.product_group_type in (
      SELECT DISTINCT tp.product_group
      FROM tb_product tp
      JOIN tb_product_license tpl ON tp.product_id = tpl.product_id AND tpl.expire_date >= now()
    );

END;
$$;


