--
-- Name: sp_get_login_fail(text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_login_fail(i_admin_id text, i_ip text) RETURNS TABLE(admin_id text, ip text, name text, computer_name text, fail_count integer, login_time timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
  SELECT
    lfs.admin_id,
    lfs.ip::text,
    lfs.name,
    lfs.computer_name,
    lfs.fail_count,
    lfs.login_time
  FROM tb_login_fail_status lfs
    WHERE
      lfs.admin_id = i_admin_id
    AND
      lfs.ip = i_ip::inet
    AND
      lfs.fail_count >= 3;

END;
$$;


ALTER FUNCTION public.sp_get_login_fail(i_admin_id text, i_ip text) OWNER TO cppoltp;

--
-- Name: sp_get_login_fail_status(bigint, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_login_fail_status(i_fail_count bigint, i_admin_id text) RETURNS TABLE(admin_id text, name text, computer_name text, fail_count integer, login_time timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
  SELECT lfs.admin_id
        ,lfs.name
        ,lfs.computer_name
        ,lfs.fail_count
        ,lfs.login_time
  FROM tb_login_fail_status lfs
  JOIN tb_admin a
  ON lfs.admin_id = a.admin_id
  WHERE lfs.admin_id = i_admin_id
    AND lfs.fail_count % i_fail_count = 0
    AND lfs.login_time > now() - (a.auth_wait_time || ' minute')::INTERVAL
    ;

END;
$$;


ALTER FUNCTION public.sp_get_login_fail_status(i_fail_count bigint, i_admin_id text) OWNER TO cppoltp;

