--
-- Name: sp_get_login_status_list(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_login_status_list(i_admin_id text) RETURNS TABLE(admin_id text, ip inet, name text, computer_name text, privilege_profile_id text, profile_name text, profile_type public.en_privilege_profile_type, login_time text, profile_body text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_profile_type    en_privilege_profile_type;
  v_privilege_profile_id    bigint;

BEGIN

  SELECT
    p.profile_type
    ,p.privilege_profile_id
  INTO
    v_profile_type
    ,v_privilege_profile_id

  FROM tb_privilege_profile AS p
  JOIN tb_admin a using (privilege_profile_id)
  WHERE a.admin_id = i_admin_id;

  RETURN QUERY
    SELECT
      ls.admin_id
      , ls.ip
      , ls.name
      , ls.computer_name
      , ls.privilege_profile_id::text
      , pp.profile_name
      , pp.profile_type
      , ls.login_time::text
      , pp.profile_body 
    FROM tb_login_status AS ls
    JOIN tb_privilege_profile AS pp USING (privilege_profile_id)
    WHERE
      CASE WHEN i_admin_id IS NULL THEN TRUE
      ELSE (pp.privilege_profile_id = v_privilege_profile_id
            OR
            pp.profile_type = CASE WHEN v_profile_type = 'ROOT_ADMIN' THEN pp.profile_type
                              WHEN v_profile_type = 'PRODUCT_ADMIN' THEN 'SECMGR_ADMIN' END)
      END;

END;
$$;


ALTER FUNCTION public.sp_get_login_status_list(i_admin_id text) OWNER TO cppoltp;

