-- Name: sp_get_login_status_privilege(bigint, inet, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_login_status_privilege(i_privilege_profile_id bigint, i_ip inet, i_cert_check text) RETURNS TABLE(admin_id text, ip inet, name text, computer_name text, privilege_profile_id bigint, login_time timestamp without time zone, token text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN


RETURN QUERY
    SELECT
    ls.admin_id,
    ls.ip,
    ls.name,
    ls.computer_name,
    ls.privilege_profile_id,
    ls.login_time,
    ls.token
    FROM
      tb_login_status ls
  JOIN tb_privilege_profile pp using(privilege_profile_id)
    WHERE 
      CASE WHEN i_cert_check::boolean IS FALSE THEN TRUE
		  ELSE ls.privilege_profile_id = i_privilege_profile_id END
  AND pp.profile_type IN ('ROOT_ADMIN', 'POLICY_ADMIN', 'CUSTOM_ADMIN')
  --AND ls.ip != i_ip
;


END;
$$;


