--
-- Name: sp_get_manual_config(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_manual_config(i_login_admin_id text) RETURNS TABLE(manual_type text, server_version text, language text, integrated_version text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_manual_type               text;
  v_server_version            text;
  v_language                  text;
  v_integrated_version        text;
BEGIN

  -- manual_type
  SELECT c.value INTO v_manual_type
  FROM tb_config AS c
  WHERE c.config_group = 'MANUAL'
    AND c.key = 'manual_type';

  -- server
  SELECT c.value INTO v_server_version
  FROM tb_config AS c
  WHERE c.config_group = 'UPDATE'
    AND c.key = 'server_version';

  -- integrated
  SELECT c.value INTO v_integrated_version
    FROM tb_config AS c
  WHERE c.config_group = 'UPDATE'
    AND c.key = 'integrated_version'; 

  -- language
  SELECT  CASE WHEN v_manual_type = 'server' AND a.language = 'ja' THEN 'en'::text
               ELSE a.language::text END INTO v_language
  FROM tb_admin AS a
  WHERE a.admin_id = i_login_admin_id;

  RETURN QUERY
    SELECT v_manual_type, v_server_version, v_language, v_integrated_version;

END;
$$;


