--
-- Name: sp_get_mergeable_common_policy(bigint, public.en_product_feature_id_type, boolean); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_mergeable_common_policy(i_node_id bigint, i_product_feature_id public.en_product_feature_id_type, is_private_ip boolean) RETURNS TABLE(merge_step text, hash text, policy_format text, online_policy_body text, offline_policy_body text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

IF (SELECT EXISTS (SELECT 1 FROM tb_common_policy AS c WHERE c.product_feature_id = i_product_feature_id)) = true THEN
  RETURN QUERY
    SELECT '1'::text merge_step, e.hash_value hash, e.policy_format::text policy_format, CASE WHEN is_private_ip THEN e.private_policy_data ELSE e.online_policy_data END online_policy_body, e.offline_policy_data offline_policy_body
    FROM tb_common_policy AS e
    WHERE e.product_feature_id = i_product_feature_id;
ELSE
  RETURN QUERY
    SELECT '1'::text merge_step, ''::TEXT hash, ''::TEXT policy_format, ''::TEXT online_policy_body, ''::TEXT offline_policy_body;
END IF;

END;
$$;


ALTER FUNCTION public.sp_get_mergeable_common_policy(i_node_id bigint, i_product_feature_id public.en_product_feature_id_type, is_private_ip boolean) OWNER TO cppoltp;

--
-- Name: sp_get_mergeable_extra_policy(bigint, public.en_product_feature_id_type, inet); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_mergeable_extra_policy(i_node_id bigint, i_product_feature_id public.en_product_feature_id_type, i_private_ip inet) RETURNS TABLE(merge_step text, product_feature_id public.en_product_feature_id_type, policy_format text, hash text, online_policy_body text, offline_policy_body text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT '2'::text merge_step
        , p.product_feature_id
        , p.policy_format
        , p.hash
        , p.online_policy_body
        , p.offline_policy_body
    FROM (
      SELECT
        p.product_feature_id
        , p.policy_format
        , p.hash
        , p.online_policy_body
        , p.offline_policy_body
        , ROW_NUMBER() OVER(PARTITION BY p.product_feature_id ORDER BY p.policy_seq ASC) AS policy_seq
      FROM (
        SELECT
          agent_extra.product_feature_id AS product_feature_id
          , agent_extra.policy_format::TEXT AS policy_format
          , agent_extra.hash AS hash
          , sp_base64_encode(agent_extra.online_policy_body) AS online_policy_body
          , sp_base64_encode(agent_extra.offline_policy_body) AS offline_policy_body
          , 1 AS policy_seq
        FROM
          sp_get_mergeable_extra_policy_agent(i_node_id, i_private_ip) AS agent_extra
        WHERE
          CASE WHEN i_product_feature_id IS NULL THEN TRUE ELSE agent_extra.product_feature_id = i_product_feature_id END
        UNION ALL
        SELECT
          v3_extra.product_feature_id AS product_feature_id
          , v3_extra.policy_format::TEXT AS policy_format
          , MD5(CONCAT(v3_extra.online_policy_body, v3_extra.offline_policy_body)) AS hash
          , sp_base64_encode(v3_extra.online_policy_body) AS online_policy_body
          , sp_base64_encode(v3_extra.offline_policy_body) AS offline_policy_body
          , 1 AS policy_seq
        FROM
          sp_get_mergeable_extra_policy_v3(i_node_id, i_private_ip) AS v3_extra
        WHERE
          CASE WHEN i_product_feature_id IS NULL THEN TRUE ELSE v3_extra.product_feature_id = i_product_feature_id END
        UNION ALL
        SELECT
			    ac_agent.product_feature_id
		  	  , ac_agent.policy_format::TEXT policy_format
		  	  , md5(concat(ac_agent.online_policy_body, ac_agent.offline_policy_body))::TEXT hash
		  	  , sp_base64_encode(ac_agent.online_policy_body) online_policy_body
		  	  , sp_base64_encode(ac_agent.online_policy_body) offline_policy_body
		  	  , 1 AS policy_seq
		    FROM sp_get_mergeable_extra_policy_ac_agent(i_node_id, i_private_ip) ac_agent
		    WHERE
          CASE WHEN i_product_feature_id IS NULL THEN TRUE ELSE ac_agent.product_feature_id = i_product_feature_id END
		    UNION ALL
		    SELECT
          hips_agent.product_feature_id
          , hips_agent.policy_format::TEXT policy_format
          , md5(concat(hips_agent.online_policy_body, hips_agent.offline_policy_body))::TEXT hash
          , sp_base64_encode(hips_agent.online_policy_body) online_policy_body
          , sp_base64_encode(hips_agent.online_policy_body) offline_policy_body
          , 1 AS policy_seq
		    FROM
          sp_get_mergeable_extra_policy_hips_agent(i_node_id, i_private_ip) hips_agent
		    WHERE
          CASE WHEN i_product_feature_id IS NULL THEN TRUE ELSE hips_agent.product_feature_id = i_product_feature_id END
		    UNION ALL
		    SELECT
          hips_mgmt.product_feature_id
          , hips_mgmt.policy_format::TEXT policy_format
          , md5(concat(hips_mgmt.online_policy_body, hips_mgmt.offline_policy_body))::TEXT hash
          , sp_base64_encode(hips_mgmt.online_policy_body) online_policy_body
          , sp_base64_encode(hips_mgmt.online_policy_body) offline_policy_body
          , 1 AS policy_seq
        FROM
          sp_get_mergeable_extra_policy_hips_mgmt(i_node_id, i_private_ip) hips_mgmt
        WHERE
          CASE WHEN i_product_feature_id IS NULL THEN TRUE ELSE hips_mgmt.product_feature_id = i_product_feature_id END
        UNION ALL
        SELECT pf.product_feature_id
            , ''::text AS hash
            , ''::text AS policy_format
            , ''::text AS online_policy_body
            , ''::text AS offline_policy_body
            , 2 AS policy_seq
        FROM
          tb_product_feature AS pf
        WHERE
          CASE WHEN i_product_feature_id IS NULL THEN TRUE ELSE pf.product_feature_id = i_product_feature_id END
      ) AS p
    ) AS p
    JOIN tb_product_feature_map AS pf ON p.product_feature_id = pf.product_feature_id
    JOIN tb_product AS pd ON pf.product_id = pd.product_id
    WHERE p.policy_seq = 1
    ORDER BY pd.product_group, pd.product_id, p.product_feature_id;

END;
$$;


ALTER FUNCTION public.sp_get_mergeable_extra_policy(i_node_id bigint, i_product_feature_id public.en_product_feature_id_type, i_private_ip inet) OWNER TO cppoltp;

--
-- Name: sp_get_mergeable_extra_policy_ac_agent(bigint, inet); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_mergeable_extra_policy_ac_agent(i_node_id bigint, i_private_ip inet) RETURNS TABLE(node_id text, policy_format public.en_policy_format, product_feature_id public.en_product_feature_id_type, online_policy_body text, offline_policy_body text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

	RETURN QUERY
  	WITH oes_engine_update AS (
		SELECT
			array_to_json(string_to_array(oes.url, ',')) oes_url_list
		FROM
			sp_get_file_server_path(i_node_id, i_private_ip, 'UPDATE_OES', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, NULL) AS oes
    )
    , policy_body AS (
    	SELECT '{ "body": { "policy_ac_agent": {"update": { "oes_url_list":' || u.oes_url_list || '} } } }' AS content
    	FROM oes_engine_update u
    	WHERE u.oes_url_list IS NOT NULL
    )
	SELECT
		i_node_id::TEXT
		, 'JSON'::en_policy_format
		, 'AC_AGENT'::en_product_feature_id_type
		, pb.content online_policy_body
		, pb.content offline_policy_body
	FROM policy_body pb;

END;
$$;


ALTER FUNCTION public.sp_get_mergeable_extra_policy_ac_agent(i_node_id bigint, i_private_ip inet) OWNER TO cppoltp;

--
-- Name: sp_get_mergeable_extra_policy_agent(bigint, inet); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_mergeable_extra_policy_agent(i_node_id bigint, i_private_ip inet) RETURNS TABLE(policy_format public.en_policy_format, product_feature_id public.en_product_feature_id_type, hash text, online_policy_body text, offline_policy_body text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
    RETURN QUERY
        SELECT
            extra_policy.policy_format
            , extra_policy.product_feature_id
            , MD5(CONCAT(ARRAY_TO_STRING(ARRAY_AGG(extra_policy.online_policy_body),','), ARRAY_TO_STRING(ARRAY_AGG(extra_policy.offline_policy_body),','))) AS hash
            , FORMAT('{%s}', ARRAY_TO_STRING(ARRAY_AGG(extra_policy.online_policy_body),',')) AS online_policy_body
            , FORMAT('{%s}', ARRAY_TO_STRING(ARRAY_AGG(extra_policy.offline_policy_body),',')) AS offline_policy_body
        FROM (
            SELECT
                update_server.policy_format
                , update_server.product_feature_id
                , update_server.online_policy_body
                , update_server.offline_policy_body
            FROM
                sp_get_mergeable_extra_policy_agent_update_server(i_node_id, i_private_ip) AS update_server  -- 개별 업데이트 서버 주소
            UNION
            SELECT
                license.policy_format
                , license.product_feature_id
                , license.online_policy_body
                , license.offline_policy_body
            FROM
                sp_get_mergeable_extra_policy_agent_license(i_node_id) AS license  -- 개별 할당 라이선스
        ) AS extra_policy
        GROUP BY
            extra_policy.policy_format, extra_policy.product_feature_id
        ;

END;
$$;


ALTER FUNCTION public.sp_get_mergeable_extra_policy_agent(i_node_id bigint, i_private_ip inet) OWNER TO cppoltp;

--
-- Name: sp_get_mergeable_extra_policy_agent_license(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_mergeable_extra_policy_agent_license(i_node_id bigint) RETURNS TABLE(policy_format public.en_policy_format, product_feature_id public.en_product_feature_id_type, online_policy_body text, offline_policy_body text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
    RETURN QUERY
        WITH license_info AS (
          SELECT
            MAX(CASE WHEN key = 'company_name' THEN value END) AS company_name
            , MAX(CASE WHEN key = 'user_name' THEN value end) AS user_name
          FROM
            tb_config
          WHERE
            config_group = 'SYS_INFO'
            AND key IN ('company_name', 'user_name')
        )
        , node_license AS (
          SELECT license_id
          FROM tb_group_license
          WHERE EXISTS (SELECT 1 FROM tb_node WHERE tb_node.group_id = tb_group_license.group_id AND tb_node.node_id = i_node_id)
        )
        , node_license_info AS (
          SELECT
            node_license.license_id
            , license_info.company_name
            , license_info.user_name
          FROM
            node_license, license_info
        )
        , node_license_v1 AS (
          WITH v1_license_info AS (
            SELECT
              ARRAY_TO_STRING(
                ARRAY_AGG(
                  CONCAT('"', CASE WHEN license.product_id = 'EMS' THEN 'AGENT' ELSE license.product_id END, '"', ':',
                    JSON_BUILD_OBJECT('license_no',license.license_no,'license_org',node.company_name,'license_user',node.user_name)
                  )
                ),
              ',') AS v1_license
            FROM
              node_license_info node
              INNER JOIN tb_multi_license license ON node.license_id = license.license_id
                AND license.version = '1.0'
          )
          SELECT
              detail_format.product_feature_id
              , detail_format.policy_format
              , detail_format.extra_policy_detail
              , FORMAT(detail_format.online_policy_format, v1_license_info.v1_license) AS online_policy_body
              , FORMAT(detail_format.offline_policy_format, v1_license_info.v1_license) AS offline_policy_body
          FROM
              tb_extra_policy_detail_format detail_format
              , v1_license_info v1_license_info
          WHERE
              detail_format.product_feature_id = 'AGENT_MGMT'
              AND detail_format.extra_policy_detail = 'LICENSE_V1'
              AND v1_license_info.v1_license IS NOT NULL
        )
        , node_license_v2 AS (
          WITH v2_license_info AS (
            SELECT
              ARRAY_TO_STRING(
                ARRAY_AGG(
                  CONCAT('"', CASE WHEN license.product_id = 'EMS' THEN 'AGENT' ELSE license.product_id END, '"', ':',
                    JSON_BUILD_OBJECT('activation_code',license.license_no,'license_org',node.company_name,'license_user',node.user_name)
                  )
                ),
              ',') AS v2_license
            FROM
              node_license_info node
              INNER JOIN tb_multi_license license ON node.license_id = license.license_id
                AND license.version = '2.0'
          )
          SELECT
              detail_format.product_feature_id
              , detail_format.policy_format
              , detail_format.extra_policy_detail
              , FORMAT(detail_format.online_policy_format, v2_license_info.v2_license) AS online_policy_body
              , FORMAT(detail_format.offline_policy_format, v2_license_info.v2_license) AS offline_policy_body
          FROM
              tb_extra_policy_detail_format detail_format
              , v2_license_info v2_license_info
          WHERE
              detail_format.product_feature_id = 'AGENT_MGMT'
              AND detail_format.extra_policy_detail = 'LICENSE_V2'
              AND v2_license_info.v2_license IS NOT NULL
        )
        SELECT
          license_result.policy_format AS policy_format
          , license_result.product_feature_id AS product_feature_id
          , FORMAT('"main_service":{%s}', ARRAY_TO_STRING(ARRAY_AGG(license_result.online_policy_body),',')) AS online_policy_body
          , FORMAT('"main_service":{%s}', ARRAY_TO_STRING(ARRAY_AGG(license_result.offline_policy_body),',')) AS offline_policy_body
        FROM (
          SELECT
            node_license_v1.product_feature_id
            , node_license_v1.policy_format
            , node_license_v1.online_policy_body
            , node_license_v1.offline_policy_body
          FROM
            node_license_v1
          UNION
          SELECT
            node_license_v2.product_feature_id
            , node_license_v2.policy_format
            , node_license_v2.online_policy_body
            , node_license_v2.offline_policy_body
          FROM
            node_license_v2
        ) AS license_result
        GROUP BY license_result.product_feature_id, license_result.policy_format
        ;

END;
$$;


ALTER FUNCTION public.sp_get_mergeable_extra_policy_agent_license(i_node_id bigint) OWNER TO cppoltp;

--
-- Name: sp_get_mergeable_extra_policy_agent_update_server(bigint, inet); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_mergeable_extra_policy_agent_update_server(i_node_id bigint, i_private_ip inet) RETURNS TABLE(policy_format public.en_policy_format, product_feature_id public.en_product_feature_id_type, online_policy_body text, offline_policy_body text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
    RETURN QUERY
      WITH update_url_list AS (
        SELECT
          (SELECT sp_get_file_server_path(i_node_id, i_private_ip, 'UPDATE_OES', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, NULL)) AS oes_url
          , (SELECT sp_get_file_server_path(i_node_id, i_private_ip, 'UPDATE_SES', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, NULL)) AS ses_url
      )
      SELECT
          detail_format.policy_format
          , detail_format.product_feature_id
          , FORMAT(detail_format.online_policy_format,
                (SELECT SPLIT_PART(oes_url,',',1) FROM update_url_list)
                , (SELECT SPLIT_PART(ses_url,',',1) FROM update_url_list)
                , (SELECT REPLACE(oes_url,',','","') FROM update_url_list)
                , (SELECT REPLACE(ses_url,',','","') FROM update_url_list)
        ) AS online_policy_body
          , FORMAT(detail_format.offline_policy_format,
                (SELECT SPLIT_PART(oes_url,',',1) FROM update_url_list)
                , (SELECT SPLIT_PART(ses_url,',',1) FROM update_url_list)
                , (SELECT REPLACE(oes_url,',','","') FROM update_url_list)
                , (SELECT REPLACE(ses_url,',','","') FROM update_url_list)
        ) AS offline_policy_body
      FROM
          tb_extra_policy_detail_format detail_format
          , update_url_list update_url_list
      WHERE
          detail_format.product_feature_id = 'AGENT_MGMT'
          AND detail_format.extra_policy_detail = 'UPDATE_SERVER'
          AND update_url_list.oes_url IS NOT NULL
      ;

END;
$$;


ALTER FUNCTION public.sp_get_mergeable_extra_policy_agent_update_server(i_node_id bigint, i_private_ip inet) OWNER TO cppoltp;

--
-- Name: sp_get_mergeable_extra_policy_hash_list(bigint, inet); Type: FUNCTION; Schema: public; Owner: cppoltp
