ALTER FUNCTION public.sp_get_mergeable_extra_policy_hash_list(i_node_id bigint, i_private_ip inet) OWNER TO cppoltp;

--
-- Name: sp_get_mergeable_extra_policy_hips_agent(bigint, inet); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_mergeable_extra_policy_hips_agent(i_node_id bigint, i_private_ip inet) RETURNS TABLE(node_id text, policy_format public.en_policy_format, product_feature_id public.en_product_feature_id_type, online_policy_body text, offline_policy_body text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

	RETURN QUERY
	WITH oes_engine_update AS (
        SELECT array_to_json(string_to_array(oes.url, ',')) oes_url_list
        FROM
            sp_get_file_server_path(i_node_id, i_private_ip, 'UPDATE_OES', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, NULL) AS oes
    )
    , geo_db_update AS (
        SELECT
            array_to_json(array_agg(t.geodb_update)) AS updates
        FROM
            (SELECT
                json_build_object(
                    'geo_db_url', sp_get_private_file_server_path(i_node_id, i_private_ip) || '/' || p.path || '/' || p.name
                    , 'geo_db_hash', p.content_hash_value
                    , 'geo_db_hash_algorithm', lower(p.content_hash_algorithm::TEXT)
                    , 'geo_db_enc_algorithm', lower(p.enc_algorithm::TEXT)
                    , 'geo_db_enc_key', p.enc_key
                ) AS geodb_update
            FROM tb_product_pkg p
            WHERE p.pkg_type = 'IPS_GEO_DB' AND p.is_removed IS FALSE
            ORDER BY p.modified_time DESC
            LIMIT 1) t
    )
	, except_ip_additional AS (
        SELECT
            a.ip_except_additional_body::JSON as additional_body
        FROM
            tb_hips_agent_policy_ip_except_additional a
        WHERE   
            a.node_id = i_node_id
    )
    , policy_body AS (
        SELECT
               ('{ "body": { "policy_hips_agent": {' || array_to_string(array_agg(item), ',') || '} } }')::json AS content
        FROM (
            SELECT  '"update": { "oes_url_list": ' || e.oes_url_list || '}' AS item  FROM oes_engine_update e WHERE e.oes_url_list IS NOT NULL
           
            UNION ALL
            SELECT '"nation":' || g.updates  AS item FROM geo_db_update g WHERE g.updates IS NOT null
           
            UNION ALL
               SELECT '"except_ip_additional":' || a.additional_body AS item FROM except_ip_additional a WHERE a.additional_body IS NOT NULL
              
            ) t
    )
	SELECT
		i_node_id::TEXT
		, 'JSON'::en_policy_format
		, 'HIPS_AGENT'::en_product_feature_id_type
		, pb.content::text
		, pb.content::text
	FROM policy_body pb
	WHERE content IS NOT NULL;
END;
$$;


ALTER FUNCTION public.sp_get_mergeable_extra_policy_hips_agent(i_node_id bigint, i_private_ip inet) OWNER TO cppoltp;

--
-- Name: sp_get_mergeable_extra_policy_hips_mgmt(bigint, inet); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_mergeable_extra_policy_hips_mgmt(i_node_id bigint, i_private_ip inet) RETURNS TABLE(node_id text, policy_format public.en_policy_format, product_feature_id public.en_product_feature_id_type, online_policy_body text, offline_policy_body text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

	RETURN QUERY
  	WITH default_signature AS (
		SELECT
			COALESCE(array_to_json( array_agg( json_build_object(
				'sid',ns.sid,
				'name',bs.name,
				'cve', bs.cve,
				'applicationType', bs.application_type,
				'protectionArea', bs.protection_area,
				'severity', ns.severity,
				'action',ns.action,
				'blockAction',ns.block_action,
				'raw',ns.raw,
				'recommendation',ns.recommendation,
				'alarm',ns.alarm,
				'direction', ns.direction,
				'vulnerabilityId', bs.vulnerability_id,
				'period', ns.period,
				'threshold', ns.threshold,
				'blockTime', ns.block_time,
				'description',ns.description,
				'lastModified', bs.last_modified
			)))::text,'[]') AS signature
		FROM tb_node_hips_signature ns
			JOIN tb_hips_signature bs ON ns.sid = bs.sid
		WHERE ns.node_id = i_node_id
	)
	, user_signature AS (
		SELECT
			COALESCE(array_to_json(array_agg(json_build_object(
				'sid',ns.sid,
				'name',cs.name,
				'applicationType', cs.application_type,
				'protectionArea', cs.protection_area,
				'severity', ns.severity,
				'action',ns.action,
				'blockAction',ns.block_action,
				'raw',ns.raw,
				'alarm',ns.alarm,
				'direction', cs.direction,
				'packetDirection', cs.packet_direction,
				'protocol', cs.protocol,
				'saddr', cs.saddr,
				'sport', cs.sport,
				'daddr', cs.daddr,
				'dport', cs.dport,
				'partternType', cs.pattern_type,
				'offset', cs."offset",
				'depth', cs.depth,
				'nocase', cs.nocase,
				'pattern', cs.pattern,
				'period', ns.period,
				'threshold', ns.threshold,
				'blockTime', ns.block_time,
				'description',ns.description,
				'lastModified', cs.last_modified
			)))::text,'[]') AS signature
		FROM tb_node_hips_signature ns
			JOIN tb_hips_signature_custom cs ON ns.sid = cs.sid
		WHERE cs.is_removed IS FALSE
			AND ns.node_id = i_node_id
	)
	, default_signature_update AS (
		SELECT
			array_to_json( 	array_agg(t.signature_update)) AS updates
		FROM
			(SELECT
				json_build_object(
					'signature_url', sp_get_private_file_server_path(i_node_id, i_private_ip) || '/' || p.path || '/' || p.name
					, 'signature_hash', p.content_hash_value
					, 'signature_hash_algorithm', lower(p.content_hash_algorithm::TEXT)
					, 'signature_enc_algorithm', lower(p.enc_algorithm::TEXT)
					, 'signature_enc_key', p.enc_key
				) AS signature_update
			FROM tb_product_pkg p
			WHERE pkg_type = 'IPS_DEFAULT_SIGNATURE' AND is_removed IS FALSE
	    	ORDER BY modified_time DESC
	    	LIMIT 1) t
	)
	, user_signature_update AS (
		SELECT
			array_to_json( 	array_agg(t.signature_update)) AS updates
		FROM
			(SELECT
				json_build_object(
					'signature_url', sp_get_private_file_server_path(i_node_id, i_private_ip)|| '/' || p.path || '/' || p.name
					, 'signature_hash', p.content_hash_value
					, 'signature_hash_algorithm', lower(p.content_hash_algorithm::TEXT)
					, 'signature_enc_algorithm', lower(p.enc_algorithm::TEXT)
					, 'signature_enc_key', p.enc_key
				) AS signature_update
			FROM tb_product_pkg p
	    	WHERE pkg_type = 'IPS_USER_SIGNATURE' AND is_removed IS FALSE
	    	ORDER BY modified_time DESC
	    	LIMIT 1) t
	)
	, policy_body AS (
		SELECT
				('{ "body": { "policy_hips_ips_mgmt": {' || array_to_string(items, ',') || '} } }') AS content
		FROM (
			SELECT
				array_agg(item) AS items
			FROM (
			    SELECT  '"signature": ' || u.updates AS item  FROM default_signature_update u WHERE u.updates IS NOT NULL
			    UNION ALL
			    SELECT '"user_signature":' || u.updates  AS item FROM user_signature_update u WHERE u.updates IS NOT NULL
			    UNION ALL
			    SELECT '"additional" : {' || array_to_string(array_agg(signature), ',') || '}'
			    FROM (
			    	SELECT '"default":' || ds.signature signature FROM default_signature ds WHERE ds.signature IS NOT NULL
			    	UNION ALL
			    	SELECT '"user":' ||  us.signature signature FROM user_signature us WHERE us.signature IS NOT NULL
					) t
			    WHERE t.signature IS NOT NULL
			) s
			WHERE s.item IS NOT NULL
		) v
		WHERE v.items IS NOT NULL
	)
	SELECT
		i_node_id::TEXT
		, 'JSON'::en_policy_format
		, 'HIPS_MGMT'::en_product_feature_id_type
		, pb.content online_policy_body
		, pb.content offline_policy_body
	FROM policy_body pb
	WHERE pb.content IS NOT NULL;
END;
$$;


ALTER FUNCTION public.sp_get_mergeable_extra_policy_hips_mgmt(i_node_id bigint, i_private_ip inet) OWNER TO cppoltp;

--
-- Name: sp_get_mergeable_extra_policy_target(public.en_file_update_target_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_mergeable_extra_policy_target(i_target_type public.en_file_update_target_type) RETURNS TABLE(product_feature_id text, target_filter text, logical_target text)
    LANGUAGE plpgsql
    AS $$

BEGIN

  RETURN QUERY
  SELECT epf.product_feature_id::TEXT
        ,CASE WHEN epf.product_feature_id = 'AGENT_MGMT' THEN '[]' ELSE json_build_array(json_build_object('type','PRODUCT_ID','filter',json_agg(pfm.product_id)))::TEXT END
        ,fus.logical_target
  FROM tb_extra_policy_format epf
  JOIN tb_product_feature_map pfm
  ON epf.product_feature_id = pfm.product_feature_id
  CROSS JOIN (SELECT json_build_array(json_build_object('type',fus.target_type,'target',json_agg(DISTINCT fus.target_id)))::TEXT AS logical_target
              FROM tb_file_update_server fus
              WHERE fus.target_type = i_target_type
              GROUP BY fus.target_type
             ) fus
  GROUP BY
        epf.product_feature_id
       ,fus.logical_target;

END;
$$;


ALTER FUNCTION public.sp_get_mergeable_extra_policy_target(i_target_type public.en_file_update_target_type) OWNER TO cppoltp;

--
-- Name: sp_get_mergeable_extra_policy_update_server_list(bigint, inet); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_mergeable_extra_policy_update_server_list(i_node_id bigint, i_private_ip inet) RETURNS TABLE(node_id text, policy_format public.en_policy_format, product_feature_id public.en_product_feature_id_type, online_policy_body text, offline_policy_body text)
    LANGUAGE plpgsql
    AS $$
DECLARE
v_oes_url_list TEXT;
BEGIN

SELECT url INTO v_oes_url_list FROM sp_get_file_server_path(i_node_id, i_private_ip, 'UPDATE_OES', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, NULL) AS oes_url;
-- v_oes_url_list 있는 경우만 판단.
IF (v_oes_url_list IS NOT NULL) THEN
  RETURN QUERY
  WITH engine_update AS (
  /* ========================================================================================================================= 엔진 업데이트 정보(사설망) */
    SELECT
      oes.url AS oes_url,
      ses.url AS ses_url
    FROM (
        SELECT url FROM sp_get_file_server_path(i_node_id, i_private_ip, 'UPDATE_OES', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, NULL) AS oes_url
    ) oes, (
        SELECT url FROM sp_get_file_server_path(i_node_id, i_private_ip, 'UPDATE_SES', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, NULL) AS ses_url
    ) ses
  ), single_update_server AS (
    -- OES만 지원 (1개의 URL 지원)
    SELECT
      tepd.product_feature_id
      , tepd.policy_format
      , format(tepd.online_policy_format, (SELECT split_part(oes.oes_url,',',1) FROM engine_update AS oes)) AS online_policy_body
      , format(tepd.offline_policy_format, (SELECT split_part(oes.oes_url,',',1) FROM engine_update AS oes)) AS offline_policy_body
    FROM tb_extra_policy_detail_format tepd
    WHERE tepd.product_feature_id IN ('V3NET_LU_UPDATE', 'V3NET_9.0_AV')
      AND tepd.extra_policy_detail = 'UPDATE_SERVER'
  ), multi_update_server_list AS (
    -- OES/SES 세팅, 콤마(,)로 여러개의 URL 지원 가능.
    SELECT
      tepd.product_feature_id
      , tepd.policy_format
      , format(tepd.online_policy_format,
            (SELECT split_part(oes.oes_url,',',1) FROM engine_update AS oes)
            , (SELECT split_part(ses.ses_url,',',1) FROM engine_update AS ses)
            , (SELECT REPLACE(oes.oes_url, ',', '","') FROM engine_update AS oes)
            , (SELECT REPLACE(ses.ses_url, ',', '","') FROM engine_update AS ses)
          ) AS online_policy_body
      , format(tepd.offline_policy_format,
            (SELECT split_part(oes.oes_url,',',1) FROM engine_update AS oes)
            , (SELECT split_part(ses.ses_url,',',1) FROM engine_update AS ses)
            , (SELECT REPLACE(oes.oes_url, ',', '","') FROM engine_update AS oes)
            , (SELECT REPLACE(ses.ses_url, ',', '","') FROM engine_update AS ses)
          ) AS offline_policy_body
    FROM tb_extra_policy_detail_format tepd
    WHERE tepd.product_feature_id IN ('AGENT_MGMT')
      AND tepd.extra_policy_detail = 'UPDATE_SERVER'
  )
  SELECT
    i_node_id::TEXT AS node_id
    , sus.policy_format
    , sus.product_feature_id
    , sus.online_policy_body::TEXT
    , sus.offline_policy_body::TEXT
  FROM single_update_server sus
  UNION ALL
  SELECT
    i_node_id::TEXT AS node_id
    , musl.policy_format
    , musl.product_feature_id
    , musl.online_policy_body::TEXT
    , musl.offline_policy_body::TEXT
  FROM multi_update_server_list musl;

END IF;

END;
$$;


ALTER FUNCTION public.sp_get_mergeable_extra_policy_update_server_list(i_node_id bigint, i_private_ip inet) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_mergeable_extra_policy_update_server_list(i_node_id bigint, i_private_ip inet); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_mergeable_extra_policy_update_server_list(i_node_id bigint, i_private_ip inet) IS '
@brief update server 조회
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_mergeable_extra_policy_v3(bigint, inet); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_mergeable_extra_policy_v3(i_node_id bigint, i_private_ip inet) RETURNS TABLE(policy_format public.en_policy_format, product_feature_id public.en_product_feature_id_type, online_policy_body text, offline_policy_body text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
    RETURN QUERY
        WITH update_server AS (
            WITH update_url_list AS (
                SELECT
                    url AS oes_url
                FROM
                    sp_get_file_server_path(i_node_id, i_private_ip, 'UPDATE_OES', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, NULL)
            )
        SELECT
            detail_format.product_feature_id
            , detail_format.policy_format
            , detail_format.extra_policy_detail
            , FORMAT(detail_format.online_policy_format, (SELECT SPLIT_PART(oes_url,',',1) FROM update_url_list)) AS online_policy_body
            , FORMAT(detail_format.offline_policy_format, (SELECT SPLIT_PART(oes_url,',',1) FROM update_url_list)) AS offline_policy_body
        FROM
            tb_extra_policy_detail_format detail_format
            , update_url_list update_url_list
        WHERE
            detail_format.product_feature_id IN ('V3NET_LU_UPDATE', 'V3NET_9.0_AV')
            AND detail_format.extra_policy_detail = 'UPDATE_SERVER'
            AND update_url_list.oes_url IS NOT NULL
        )
        SELECT
            format.policy_format
            , format.product_feature_id
            , FORMAT(format.online_policy_format, (SELECT update_server.online_policy_body FROM update_server WHERE update_server.product_feature_id = format.product_feature_id))
            , FORMAT(format.offline_policy_format, (SELECT update_server.offline_policy_body FROM update_server WHERE update_server.product_feature_id = format.product_feature_id))
        FROM
            tb_extra_policy_format format
            INNER JOIN update_server "update" ON "update".product_feature_id = format.product_feature_id
        ;
END;
$$;


ALTER FUNCTION public.sp_get_mergeable_extra_policy_v3(i_node_id bigint, i_private_ip inet) OWNER TO cppoltp;

--
-- Name: sp_get_multi_admin(public.en_privilege_profile_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_multi_admin(i_profile_type public.en_privilege_profile_type) RETURNS TABLE(admin_id text, password text, current_password text, error_message text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_privilege_profile_id      bigint;
BEGIN

  SELECT p.privilege_profile_id INTO v_privilege_profile_id
  FROM tb_privilege_profile AS p
  WHERE p.profile_type = i_profile_type LIMIT 1;


  UPDATE tb_temp_admin_temp AS t
    SET privilege_profile_id = v_privilege_profile_id
      , current_pwd = (SELECT a.password FROM tb_admin AS a WHERE a.admin_id = t.admin_id AND a.privilege_profile_id = v_privilege_profile_id);

  IF i_profile_type = 'DEPT_ADMIN' THEN

    RETURN QUERY
      SELECT t.admin_id, t.password, COALESCE(a.password, ''), t.error_message
      FROM tb_temp_admin_temp AS t
      LEFT JOIN (
        SELECT a.admin_id, a.password
        FROM tb_admin AS a
        JOIN tb_privilege_profile AS p ON a.privilege_profile_id = p.privilege_profile_id AND p.profile_type = i_profile_type
      ) AS a ON t.admin_id = a.admin_id;

  ELSE

    RETURN QUERY
      SELECT t.admin_id, t.password, ''::text, t.error_message
      FROM tb_temp_admin_temp AS t;

  END IF;

END;
$$;


ALTER FUNCTION public.sp_get_multi_admin(i_profile_type public.en_privilege_profile_type) OWNER TO cppoltp;

--
-- Name: sp_get_nat_service_server_list(public.en_service_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_nat_service_server_list(i_service_type public.en_service_type) RETURNS TABLE(service_type public.en_service_type, server_id text, ip text, port text, static text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT
      v.service_type
      , s.server_id::text
      , (CASE
        WHEN (SELECT tc.value FROM tb_config tc
            WHERE tc.config_group = 'NETWORK'
            AND tc.key = 'use_nat') = 'true'
        THEN s.public_ip
        ELSE s.ip
        END) AS ip
      , sp.port::text
    , v.static::text
    FROM tb_server AS s
    INNER JOIN tb_service AS v ON s.server_id = v.server_id
    INNER JOIN tb_service_port AS sp ON v.service_type = sp.service_type
    WHERE v.enabled IS TRUE
      AND v.service_type = i_service_type;

END;
$$;


ALTER FUNCTION public.sp_get_nat_service_server_list(i_service_type public.en_service_type) OWNER TO cppoltp;

--
-- Name: sp_get_net_cert_mgmt_list(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_net_cert_mgmt_list() RETURNS TABLE(key text, value text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT
      c.key
      , CASE 
          WHEN c.key = 'cert_apply_status' AND (SELECT tc.value FROM tb_config tc WHERE tc.config_group = 'SYS_NET_CERT' AND tc.key = 'cert_epp_expire_date')::timestamp <= (NOW()::date)::timestamp 
            THEN '4'
          WHEN 
            c.key = 'cert_schedule' AND c.value != '' 
          THEN
            TO_TIMESTAMP(
              c.value::json->'basic_moment'->>'year'
              ||LPAD(c.value::json->'basic_moment'->>'month', 2, '0')
              ||LPAD(c.value::json->'basic_moment'->>'day', 2, '0')
              ||LPAD(c.value::json->'basic_moment'->>'hour', 2, '0')
              ||LPAD(c.value::json->'basic_moment'->>'minute', 2, '0')
              , 'YYYYMMDDHH24MI'
            )::timestamp::text
          ELSE c.value 
        END AS value 
    FROM tb_config AS c
    WHERE c.config_group = 'SYS_NET_CERT';

END;
$$;


ALTER FUNCTION public.sp_get_net_cert_mgmt_list() OWNER TO cppoltp;

