--
-- Name: sp_get_next_non_shard_etl(text, integer); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_next_non_shard_etl(i_batch_uuid text, i_cnt integer) RETURNS TABLE(etl_id bigint, step integer, etl_from public.en_etl_from, etl_to public.en_etl_to, etl_method public.en_etl_method, from_collection text, etl_query text, to_table text, to_column text, pre_from_proc text, pre_to_proc text, post_from_proc text, post_to_proc text, is_shard boolean, from_column text)
    LANGUAGE plpgsql
    AS $_$
BEGIN

RETURN query EXECUTE '
  WITH t AS (
	SELECT step, enabled, is_shard, batch_status, affinity FROM (
    	SELECT m.step, m.enabled, m.is_shard, m.batch_status, coalesce(m.end_time, ''2000-01-01'') end_time, m.affinity FROM tb_etl_map m
      	WHERE m.enabled = TRUE AND m.is_shard = FALSE AND m.batch_status = ''READY''
    ) t
  ORDER BY end_time LIMIT 1
)
UPDATE tb_etl_map m
SET batch_uuid = $1, batch_status = ''RUNNING'', start_time = now()
WHERE (m.etl_id) IN
    (
    SELECT m.etl_id FROM tb_etl_map m WHERE m.affinity = (SELECT t.affinity FROM t WHERE t.affinity IS NOT NULL LIMIT 1)
    UNION ALL
    (
      SELECT m.etl_id FROM tb_etl_map m WHERE (m.step, m.enabled, m.is_shard, m.batch_status) = (SELECT t.step, t.enabled, t.is_shard, t.batch_status FROM t WHERE m.affinity IS NULL)
      ORDER BY step, coalesce(end_time, ''1900-01-01''::TIMESTAMP) LIMIT $2
    )
  )
  RETURNING m.etl_id, m.step, m.etl_from, m.etl_to, m.etl_method, m.from_collection, m.etl_query, m.to_table, m.to_column,
  m.pre_from_proc, m.pre_to_proc, m.post_from_proc, m.post_to_proc, m.is_shard, m.from_column'
USING i_batch_uuid, i_cnt;

END;
$_$;


ALTER FUNCTION public.sp_get_next_non_shard_etl(i_batch_uuid text, i_cnt integer) OWNER TO cppoltp;

