-- Name: sp_get_no_sync_file(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_no_sync_file(i_server_id bigint) RETURNS TABLE(product_pkg_id bigint, name text, pkg_type public.en_pkg_type, path text, product_id public.en_product_id_type, install_ip text, size bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
  RETURN QUERY
    SELECT *
    FROM sp_get_no_sync_file(i_server_id,
      '{WIN_AGENT_MASTER,LINUX_AGENT_MASTER,WIN_AGENT_INSTALL,LINUX_AGENT_INSTALL,PRODUCT_INSTALL,CUSTOM,IPS_DEFAULT_SIGNATURE,IPS_USER_SIGNATURE,IPS_GEO_DB,IM_PREDEFINED,IM_USERDEFINED,SCM_PREDEFINED,SCM_USERDEFINED,IPS_DEFAULT_OVAL}'::en_pkg_type[]);
END;
$$;


ALTER FUNCTION public.sp_get_no_sync_file(i_server_id bigint) OWNER TO cppoltp;

--
-- Name: sp_get_no_sync_file(bigint, public.en_pkg_type[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_no_sync_file(i_server_id bigint, i_pkg_type public.en_pkg_type[]) RETURNS TABLE(product_pkg_id bigint, name text, pkg_type public.en_pkg_type, path text, product_id public.en_product_id_type, install_ip text, size bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
  RETURN QUERY
    SELECT
      tpp.product_pkg_id
      , tpp.name
    , tpp.pkg_type
    , tpp.path
    , tpp.product_id
    , tpp.install_ip
    , tpp.size
  FROM tb_product_pkg tpp
  LEFT OUTER JOIN tb_pkg_server AS tps
    ON tps.product_pkg_id = tpp.product_pkg_id
   AND tps.server_id = i_server_id
  WHERE tpp.pkg_status = 'SUCCESS'
  AND tpp.pkg_type = ANY(i_pkg_type)
  AND tpp.is_removed is false
  AND (SELECT count(ts.server_id)
    FROM tb_server ts
    JOIN tb_service tsv
    ON ts.server_id = tsv.server_id
    WHERE ts.server_id = i_server_id
    AND ts.server_status = 'NORMAL'
    AND tsv.service_type = 'FILESERVER-UPLOAD'
    AND tsv.enabled IS TRUE) > 0
  AND tps.server_id IS NULL;
END;
$$;


ALTER FUNCTION public.sp_get_no_sync_file(i_server_id bigint, i_pkg_type public.en_pkg_type[]) OWNER TO cppoltp;

