CREATE FUNCTION public.sp_get_node(i_node_id bigint) RETURNS TABLE(node_id bigint, group_id bigint, machine_uuid text, is_removed boolean, path text, ip inet, ip_connected inet, mac text, nt_domain text, login_id text, computer_name text, agent_install_time timestamp with time zone, removed_time timestamp without time zone, machine_type public.en_machine_type, platform_id public.en_platform_id_type, agent_port integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    BEGIN

      RETURN QUERY
        SELECT
         NOD.node_id                            /* 노드 ID */
        , NOD.group_id                            /* 그룹 ID */
        , NOD.machine_uuid                        /* 에이전트 하드웨어 시리얼 */
        , NOD.is_removed                          /* 삭제 여부 */
        , NOD.path                                /* 경로 */
        , NOD.ip                                  /* IP 주소 */
        , NOD.ip_connected                    /* 연결 IP 주소 */
        , NOD.mac                                 /* MAC 주소 */
        , NOD.nt_domain                           /* NT 도메인 */
        , NOD.login_id                            /* 로그인 ID */
        , NOD.computer_name                       /* 컴퓨터 이름 */
        , NOD.agent_install_time                        /* 설치 시각 */
        , NOD.removed_time                        /* 삭제 시각 */
        , NOD.machine_type                        /* 머신 타입 */
        , NOD.platform_id                         /* 머신 타입 */
        , NOD.agent_port                      /* 플랫폼 타입 */
        FROM tb_node AS NOD
        WHERE NOD.node_id = i_node_id
        AND NOD.is_removed = false
        ;
    END;
$$;


