CREATE FUNCTION public.sp_get_node_connection_status(i_node_id bigint) RETURNS TABLE(connection_status text)
    LANGUAGE plpgsql
    AS $$
BEGIN

  RETURN QUERY
  SELECT n.connection_status::text AS connection_status
  FROM tb_node_status AS n
  JOIN tb_node AS vn ON vn.node_id = n.node_id AND vn.is_removed IS FALSE
  WHERE n.node_id = i_node_id
    AND n.connection_status = 'CONNECTED';

END;
$$;


