CREATE FUNCTION public.sp_get_node_hw(i_node_id bigint[]) RETURNS TABLE(node_id text, cpu text, cpu_version text, cpu_speed text, physical_memory text, virtual_memory text, bios_date text, bios_name text, bios_vendor text, bios_version text, vga_resolution text, vga_type text, vga_chipset text, vga_mem text, hdd1_fs text, hdd1_total text, hdd1_free text, hdd2_fs text, hdd2_total text, hdd2_free text, hdd3_fs text, hdd3_total text, hdd3_free text, host text, iexplorer text, winsock text, mac1 text, gw1 text, ip1 text, dhcp_use1 text, dhcp_server1 text, virtual_nic1 text, mac2 text, gw2 text, ip2 text, dhcp_use2 text, dhcp_server2 text, virtual_nic2 text, mac3 text, gw3 text, ip3 text, dhcp_use3 text, dhcp_server3 text, virtual_nic3 text, mac4 text, gw4 text, ip4 text, dhcp_use4 text, dhcp_server4 text, virtual_nic4 text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
  SELECT nh.node_id::text
        ,nh.cpu_name AS cpu
        ,nh.cpu_version
        ,nh.cpu_speed::text
        ,nh.memory_physical::text AS physical_memory
        ,nh.memory_virtual::text AS virtual_memory
        ,nh.bios_date::text
        ,nh.bios_name
        ,nh.bios_vendor
        ,nh.bios_version
        ,nh.vga_resolution
        ,nh.vga_type
        ,nh.vga_chipset
        ,nh.vga_mem
        ,nh.hdd1_file_system AS hdd1_fs
        ,nh.hdd1_size AS hdd1_total
        ,nh.hdd1_free
        ,nh.hdd2_file_system AS hdd1_fs
        ,nh.hdd2_size AS hdd1_total
        ,nh.hdd2_free
        ,nh.hdd3_file_system AS hdd1_fs
        ,nh.hdd3_size AS hdd1_total
        ,nh.hdd3_free
        ,nh.host
        ,nh.iexplorer
        ,nh.winsock
        ,nh.nic1_mac AS mac1
        ,nh.nic1_gw AS gw1
        ,nh.nic1_ip AS ip1
        ,nh.nic1_dhcp_use AS dhcp_use1
        ,nh.nic1_dhcp_server AS dhcp_server1
        ,nh.nic1_virtual AS virtual_nic1
        ,nh.nic2_mac AS mac2
        ,nh.nic2_gw AS gw2
        ,nh.nic2_ip AS ip2
        ,nh.nic2_dhcp_use AS dhcp_use2
        ,nh.nic2_dhcp_server AS dhcp_server2
        ,nh.nic2_virtual AS virtual_nic2
        ,nh.nic3_mac AS mac3
        ,nh.nic3_gw AS gw3
        ,nh.nic3_ip AS ip3
        ,nh.nic3_dhcp_use AS dhcp_use3
        ,nh.nic3_dhcp_server AS dhcp_server3
        ,nh.nic3_virtual AS virtual_nic3
        ,nh.nic4_mac AS mac4
        ,nh.nic4_gw AS gw4
        ,nh.nic4_ip AS ip4
        ,nh.nic4_dhcp_use AS dhcp_use4
        ,nh.nic4_dhcp_server AS dhcp_server4
        ,nh.nic4_virtual AS virtual_nic4
  FROM tb_node_hw nh
  JOIN tb_node AS n ON n.node_id = nh.node_id AND n.is_removed IS FALSE
  WHERE nh.node_id = ANY(i_node_id);

END;
$$;


