--
-- Name: sp_get_node_list(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_node_list(i_srch_word text) RETURNS TABLE(node_ids text)
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_inetArray text[];
  v_isInet boolean;
BEGIN
  v_inetArray = STRING_TO_ARRAY( i_srch_word, ',' );  /* ip범위검색 : ip=string, ex:"192.168.1.1,192.168.1.255" */

  SELECT v_inetArray[1] ~ '^[0-2]?[0-9]?[0-9]+\.[0-2]?[0-9]?[0-9]+\.[0-2]?[0-9]?[0-9]+\.[0-2]?[0-9]?[0-9]+$'
      AND v_inetArray[2] ~ '^[0-2]?[0-9]?[0-9]+\.[0-2]?[0-9]?[0-9]+\.[0-2]?[0-9]?[0-9]+\.[0-2]?[0-9]?[0-9]+$'
  INTO v_isInet;

  RETURN QUERY

  SELECT ARRAY_TO_STRING( ARRAY_AGG(node_id), ',' )
  FROM (
    /* tb_node */
    SELECT node.node_id
    FROM tb_node node
    WHERE
      node.is_removed = false
      AND node.node_id ||' '||
        coalesce(node.ip::text,'') ||' '||
        coalesce(node.mac,'') ||' '||
        coalesce(node.login_id,'') ||' '||--로그인한 사용자
        coalesce(node.computer_name,'') ||' '||
        coalesce(node.platform_id::text,'')
    LIKE '%'|| i_srch_word ||'%'


    UNION  /* tb_user */
    SELECT usr.node_id
    FROM tb_user usr LEFT JOIN tb_node node ON usr.node_id = node.node_id
    WHERE
      node.is_removed = false
      AND coalesce(usr.name,'') ||' '||
        coalesce(usr.email,'') ||' '||
        coalesce(usr.empno,'') ||' '||
        coalesce(usr.department,'')
    LIKE '%'|| i_srch_word ||'%'


    UNION  /*ip range : TO-DO exception 시 전체 실패로 인한 기능 분리 필요*/
    SELECT node.node_id
      FROM tb_node node
     WHERE node.ip IS NOT NULL
       AND node.is_removed = FALSE
       AND coalesce(v_isInet, TRUE) = TRUE
       AND node.ip::inet >= v_inetArray[1]::inet
       AND node.ip::inet <= v_inetArray[2]::inet

  ) t ;

END;
$_$;


ALTER FUNCTION public.sp_get_node_list(i_srch_word text) OWNER TO cppoltp;

--
-- Name: sp_get_node_list(bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_node_list(i_group_id bigint, i_correlation_rule_id bigint, i_admin_group text) RETURNS TABLE(node_id bigint[])
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_admin_group_id            bigint[];
  v_top_group_id              bigint;
  v_node_id                   bigint[];
  v_physical_group_id         BIGINT;
BEGIN

  SELECT g.group_id INTO v_top_group_id
    FROM tb_group g
   WHERE g.group_type = 'TOP';

  IF (i_admin_group = v_top_group_id::text AND i_group_id > 0) OR i_admin_group IS NULL THEN

    WITH RECURSIVE group_list (group_id, pgroup_id, is_removed, level, grp_path, cycle)
      AS (
        SELECT g.group_id
              ,g.pgroup_id
              ,g.is_removed
              ,0
              ,ARRAY[g.group_id]
              ,false
         FROM tb_group g
        WHERE g.group_id = i_group_id
        UNION ALL
       SELECT g.group_id
              ,g.pgroup_id
              ,g.is_removed
              ,gl.level + 1
              ,gl.grp_path || g.group_id
              ,g.group_id = ANY(gl.grp_path)
        FROM tb_group g
        JOIN group_list gl
          ON g.pgroup_id = gl.group_id
         AND NOT cycle
       WHERE g.is_removed IS FALSE
      )
      SELECT array_agg(n.node_id) INTO v_node_id
        FROM tb_node n
       WHERE EXISTS (SELECT 1 FROM group_list gl WHERE gl.group_id = n.group_id)
         AND n.is_removed is false
        ;

  ELSE

      v_admin_group_id := string_to_array(i_admin_group, ',')::bigint[];

      SELECT g.group_id
      INTO v_physical_group_id
      FROM tb_group g
      WHERE g.group_type = 'PHYSICAL';

      WITH RECURSIVE group_list (group_id, pgroup_id, group_type, is_removed, level, grp_path, cycle)
      AS (
        SELECT g.group_id
              ,CASE WHEN g.group_type IN ('PHYSICAL') THEN g.pgroup_id
                    ELSE v_physical_group_id
               END AS pgroup_id
              ,g.group_type
              ,g.is_removed
              ,1
              ,ARRAY[g.group_id]
              ,false
         FROM tb_group g
        WHERE g.is_removed IS NOT TRUE
          AND CASE WHEN i_group_id = v_top_group_id OR i_group_id IS NULL OR i_group_id < 0 THEN g.group_id = any(v_admin_group_id)
                   WHEN i_group_id = v_physical_group_id THEN g.group_id = any(v_admin_group_id) AND g.group_type IN ('PHYSICAL','DEFAULT','GENERAL')
                   ELSE g.group_id = i_group_id
              END
        UNION ALL
        SELECT g.group_id
              ,g.pgroup_id
              ,g.group_type
              ,g.is_removed
              ,gl.level + 1
              ,gl.grp_path || g.group_id
              ,g.group_id = ANY(gl.grp_path)
        FROM tb_group g
        JOIN group_list gl
          ON g.pgroup_id = gl.group_id
          AND NOT cycle
        WHERE g.is_removed IS NOT TRUE
      )
      SELECT array_agg(n.node_id) INTO v_node_id
        FROM tb_node n
       WHERE EXISTS (SELECT 1 FROM group_list gl WHERE gl.group_id = n.group_id)
         AND n.is_removed = false
      ;

  END IF;

  IF i_correlation_rule_id > 0 THEN
    -- group을 선택 안하고 admin_group 이 top이면 연계규칙 ID만 조회.
    IF i_group_id < 0 AND i_admin_group = v_top_group_id::text THEN
      SELECT ARRAY_AGG(DISTINCT c.target_id) INTO v_node_id
        FROM vw_correlation_result AS c
        JOIN tb_node AS n ON c.correlation_rule_id = i_correlation_rule_id AND c.target_id = n.node_id AND n.is_removed = FALSE;
    ELSE
      IF v_node_id IS NOT NULL THEN
        SELECT array_intersect(v_node_id, ARRAY_AGG(DISTINCT c.target_id)) INTO v_node_id
          FROM vw_correlation_result AS c
          JOIN tb_node AS n ON c.correlation_rule_id = i_correlation_rule_id AND c.target_id = n.node_id AND n.is_removed = FALSE;
      END IF;
    END IF;
  END IF;

  RETURN QUERY
    SELECT v_node_id;

END;

$$;


ALTER FUNCTION public.sp_get_node_list(i_group_id bigint, i_correlation_rule_id bigint, i_admin_group text) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_node_list(i_group_id bigint, i_correlation_rule_id bigint, i_admin_group text); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_node_list(i_group_id bigint, i_correlation_rule_id bigint, i_admin_group text) IS '
@brief 그룹정보와 연결규칙에 해당하는 노드 목록 구하기
@in -
