@return - TABLE';


--
-- Name: sp_get_node_policy(bigint, public.en_product_feature_id_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_node_policy(i_node_id bigint, i_product_feature_id public.en_product_feature_id_type) RETURNS TABLE(policy_id text, hash text, online_policy_body text, offline_policy_body text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

    RETURN QUERY
  	WITH kept_node_policy AS (
      SELECT np.product_feature_id, np.node_id, np.policy_id
      FROM tb_node_policy AS np
      WHERE np.keep_agent_policy = TRUE
      	AND np.node_id = i_node_id
      	AND np.product_feature_id = i_product_feature_id
    )
    , delegated_policy AS (
      SELECT gp.product_feature_id, n.node_id, gp.policy_id
      FROM tb_group_policy AS gp
      JOIN tb_node AS n ON  n.group_id = gp.group_id
      WHERE n.node_id = i_node_id
      	AND gp.product_feature_id = i_product_feature_id
      	AND NOT(gp.product_feature_id = ANY(SELECT k.product_feature_id FROM kept_node_policy AS k))
    )
    , node_policy AS (
      SELECT np.product_feature_id, np.node_id, np.policy_id FROM kept_node_policy AS np
      UNION
      SELECT dp.product_feature_id, dp.node_id, dp.policy_id FROM delegated_policy As dp
    )
    , get_node_policy AS (
      SELECT
        p.policy_id
        , p.hash
        , p.online_policy_body
        , p.offline_policy_body
      FROM node_policy np
        JOIN tb_policy p ON np.policy_id = p.policy_id AND np.product_feature_id = p.product_feature_id
      WHERE np.node_id = i_node_id
        AND np.product_feature_id = i_product_feature_id
      LIMIT 1
    )
    , update_node_policy AS (
      UPDATE
        tb_node_policy
      SET
        policy_id = (SELECT get_node_policy.policy_id FROM get_node_policy)
        , modified_time = NOW()
      WHERE
        node_id = i_node_id
        AND product_feature_id = i_product_feature_id
    )
    SELECT
      get_node_policy.policy_id::TEXT
      , get_node_policy.hash
      , get_node_policy.online_policy_body
      , get_node_policy.offline_policy_body
    FROM
      get_node_policy
  	;

END;
$$;


ALTER FUNCTION public.sp_get_node_policy(i_node_id bigint, i_product_feature_id public.en_product_feature_id_type) OWNER TO cppoltp;

--
-- Name: sp_get_node_policy_status(bigint[], bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_node_policy_status(i_node_id bigint[], i_policy_id bigint[]) RETURNS TABLE(policy_id bigint, policy_status public.en_policy_status, count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
  RETURN QUERY
  --도메인 정책 적용 현황
  SELECT ps.policy_id AS policy_id
        ,ps.policy_status AS policy_status
        ,count(*) AS count
  FROM vw_policy_status ps
  JOIN (SELECT DISTINCT
               pfm.product_feature_id
              ,p.product_group
        FROM tb_product_feature_map pfm
        JOIN tb_product p
        ON pfm.product_id = p.product_id) pfm
  ON ps.product_feature_id = pfm.product_feature_id
  WHERE ps.node_id = ANY(i_node_id)
    AND ps.policy_id = ANY(i_policy_id)
    AND EXISTS (SELECT 1 FROM tb_node n WHERE n.node_id = ps.node_id AND n.is_removed is false)
    AND (
      pfm.product_group IN ('EMS','V3')
      OR pfm.product_group = 'AC' AND sp_exist_license('AC')
      OR pfm.product_group = 'HIPS' AND sp_exist_license('HIPS')
      OR pfm.product_group = 'SCM' AND sp_exist_license('SCM')
    )
  GROUP BY ps.policy_id, ps.policy_status
  ORDER BY policy_id, policy_status;

END;
$$;


ALTER FUNCTION public.sp_get_node_policy_status(i_node_id bigint[], i_policy_id bigint[]) OWNER TO cppoltp;

