    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT ns.node_id, ns.sw_guid, ns.sw_name, ns.publisher, ns.version
        , CASE WHEN ns.size = '0' THEN '' ELSE ns.size END AS size
        , ns.install_time::timestamp
    FROM tb_node_sw AS ns
    JOIN tb_node AS n ON n.node_id = ns.node_id AND n.is_removed = false
    WHERE ns.node_id = ANY(i_node_id);

END;
$$;


