--
-- Name: sp_get_not_manage_product(public.en_product_group_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_not_manage_product(i_product_group public.en_product_group_type) RETURNS TABLE(not_support_platform public.en_platform_type[])
    LANGUAGE plpgsql
    AS $$

DECLARE
  
BEGIN

  RETURN QUERY
    WITH manage_product_config AS (
      SELECT
        json_data.key::en_product_id_type AS product_id
        , json_data.value::boolean AS is_managed
        , UNNEST(product.platform_support) AS platform_support
      FROM (
          SELECT value FROM tb_config WHERE config_group = 'AGENT_MANAGE_PRODUCT' AND key = 'manage_product'
          ) AS config, json_each_text(config.value::json) AS json_data
          INNER JOIN tb_product product ON product.product_id = json_data.key::en_product_id_type
            AND product.product_group = i_product_group
    )
    SELECT
    	ARRAY_AGG(config.platform_support) AS platform_support
    FROM
      manage_product_config AS config
     WHERE
     	config.is_managed IS FALSE;

END;
$$;


ALTER FUNCTION public.sp_get_not_manage_product(i_product_group public.en_product_group_type) OWNER TO cppoltp;

