--
-- Name: sp_get_or_create_group_path(text, bigint, bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_or_create_group_path(i_group_path text, i_base_group_id bigint, i_group_order bigint) RETURNS TABLE(group_id bigint)
    LANGUAGE plpgsql
    AS $$
#variable_conflict use_column
DECLARE
 v_base_group_id BIGINT;
 v_group_name TEXT;
BEGIN

  SELECT i_base_group_id INTO v_base_group_id;

  -- get group_id from base group_path (create or get)
  FOR v_group_name IN (SELECT * FROM unnest(string_to_array(btrim(i_group_path, '/'), '/')))
  LOOP
    IF NOT EXISTS (SELECT * FROM tb_group g WHERE g.name = v_group_name AND g.pgroup_id = v_base_group_id)
    THEN
      VALUES(v_group_name, v_base_group_id, 'GENERAL', FALSE, i_group_order)
      RETURNING tb_group.group_id INTO v_base_group_id;

      SELECT v_base_group_id, p.product_feature_id, p.policy_id, CURRENT_TIMESTAMP AS modified_time
      FROM tb_policy p WHERE p.policy_type = 'DEFAULT'
      ON CONFLICT(group_id, product_feature_id) DO UPDATE SET policy_id = EXCLUDED.policy_id, modified_time = EXCLUDED.modified_time;

    ELSIF EXISTS (SELECT * FROM tb_group g WHERE g.name = v_group_name AND g.pgroup_id = v_base_group_id AND g.is_removed = TRUE)
    THEN
      UPDATE tb_group g SET is_removed = FALSE
      WHERE g.name = v_group_name AND g.pgroup_id = v_base_group_id AND g.is_removed = TRUE
      RETURNING g.group_id INTO v_base_group_id;

      SELECT v_base_group_id, p.product_feature_id, p.policy_id, CURRENT_TIMESTAMP AS modified_time
      FROM tb_policy p WHERE p.policy_type = 'DEFAULT'
      ON CONFLICT(group_id, product_feature_id) DO UPDATE SET policy_id = EXCLUDED.policy_id, modified_time = EXCLUDED.modified_time;
    ELSE
      SELECT g.group_id INTO v_base_group_id FROM tb_group g WHERE name = v_group_name AND g.pgroup_id = v_base_group_id AND is_removed = FALSE;
    END IF;
  END LOOP;

  RETURN QUERY SELECT v_base_group_id;
END;
$$;


ALTER FUNCTION public.sp_get_or_create_group_path(i_group_path text, i_base_group_id bigint, i_group_order bigint) OWNER TO cppoltp;

