CREATE FUNCTION public.sp_get_pkg_url(i_node_id bigint, i_pkg_id bigint, ip inet) RETURNS TABLE(url text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
  IF NOT EXISTS (SELECT product_pkg_id FROM tb_product_pkg WHERE is_removed IS FALSE AND pkg_type = 'CUSTOM' AND product_pkg_id = i_pkg_id) THEN
    RAISE EXCEPTION 'package id (%) does not exist.', i_pkg_id USING HINT = 'DB-00053';
  END IF;

  RETURN QUERY
    SELECT regexp_split_to_table(u.url, ',')
    FROM sp_get_file_server_path(i_node_id, ip, NULL, i_pkg_id, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL) u;
END;
$$;


