--
-- Name: sp_get_platform_group(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_platform_group() RETURNS TABLE(platform_group_id public.en_platform_id_type, platform_group_name text, is_server text, platform_type text)
    LANGUAGE plpgsql
    AS $$
BEGIN

  RETURN QUERY
    SELECT
      pg.platform_group AS platform_group_id
      , p.name AS platform_group_name
      , pg.is_server::text AS is_server
      , pg.platform_type::TEXT AS platform_type
    FROM (
      SELECT
        DISTINCT pg.platform_group
          , pg.platform_type
          , pg.is_server
      FROM
        tb_platform pg
      WHERE
        pg.is_supported IS TRUE) pg
      JOIN tb_platform p ON pg.platform_group = p.platform_id
    WHERE
      p.is_supported IS TRUE
      AND pg.platform_type NOT IN ('UNKNOWN'::en_platform_type, 'UNKNOWN_EXTERNAL'::en_platform_type)
    ORDER BY
      CASE WHEN pg.platform_type = 'WINDOWS'::en_platform_type THEN 1
      WHEN pg.platform_type = 'LINUX_UNIX'::en_platform_type THEN 2
      ELSE 3 END ASC
      , CASE WHEN pg.platform_group = 'LINUX/UNIX'::en_platform_id_type THEN 2 ELSE 1 END ASC
      , p.name ASC;

END;
$$;


ALTER FUNCTION public.sp_get_platform_group() OWNER TO cppoltp;

