--
-- Name: sp_get_policy_agent_apply_list(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_policy_agent_apply_list(i_node_id bigint) RETURNS TABLE(product_feature_id public.en_product_feature_id_type, product_feature_name text, policy_id bigint, policy_name text, description text, policy_type public.en_policy_type, modified_time timestamp without time zone, keep_agent_policy boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    -- 에이전트 정책
    SELECT
      p.product_feature_id
      , p.product_feature_name
      , p.policy_id
      , p.policy_name
      , p.description
      , p.policy_type
      , p.modified_time
      , p.keep_agent_policy
    FROM (
        SELECT
            pf.product_feature_id
            , pf.name AS product_feature_name
            , p.policy_id
            , p.name AS policy_name
            , p.description
            , p.policy_type
            , p.modified_time
            , 'EMS'::en_product_group_type AS product_group
            , np.keep_agent_policy
        FROM
            tb_product_feature AS pf
        INNER JOIN
            tb_policy AS p
        ON
            pf.product_feature_id = p.product_feature_id
        INNER JOIN
            tb_node_policy AS np
        ON
            np.policy_id = p.policy_id
        INNER JOIN
            tb_node AS n
        ON
            n.node_id = np.node_id
        WHERE
            np.node_id = i_node_id
        AND
            p.product_feature_id = 'AGENT_MGMT'
        AND
            n.is_removed = FALSE
          
        UNION ALL
        
        -- 제품 정책
        SELECT
            pf.product_feature_id
            , pf.name AS product_feature_name
            , p.policy_id
            , p.name AS policy_name
            , p.description
            , p.policy_type
            , p.modified_time
            , pfm.product_group
            , np.keep_agent_policy
        FROM
            tb_product_feature AS pf
        INNER JOIN (
            SELECT
                DISTINCT pfm.product_feature_id
                , p.product_group
            FROM
                tb_node AS n
            INNER JOIN
                tb_platform AS pl
            ON
                n.platform_id = pl.platform_id
            INNER JOIN (
                SELECT
                    product_group
                    , product_id
                    , is_server_product
                    , is_client_product
                    , unnest(platform_support) platform_type
                FROM
                    tb_product
            ) AS p
                ON pl.platform_type = p.platform_type
            INNER JOIN
                tb_product_feature_map AS pfm
            ON
                p.product_id = pfm.product_id
            WHERE
                n.node_id = i_node_id
            AND
                n.is_removed = FALSE
            AND
                pl.is_supported IS TRUE
            AND
                sp_exist_product_license(p.product_id)
            AND
                pfm.product_feature_id NOT IN ('AGENT_MGMT','V3NET_LU_UPDATE')
            AND
                CASE WHEN p.product_group = 'V3' AND pl.is_server = TRUE THEN p.is_server_product
                    WHEN p.product_group = 'V3' AND pl.is_server = FALSE THEN p.is_client_product
                    WHEN pl.platform_type = 'WINDOWS' AND product_group <> 'V3' THEN TRUE
                    WHEN product_group IN ('AC', 'HIPS', 'SCM') THEN TRUE
                    ELSE FALSE
                END
            AND
                CASE WHEN n.machine_type != 'CONTAINER'
                        THEN pfm.product_feature_id IN ('V3NET_LU_AV', 'V3NET_9.0_AV', 'HIPS_AGENT', 'HIPS_MGMT', 'HIPS_FW', 'AC_AGENT', 'AC_MGMT', 'IM_MGMT')
                    WHEN n.machine_type = 'CONTAINER' AND n.container_service_type IN (SELECT tcp.container_service_type FROM tb_container_platform tcp WHERE tcp.is_amc_supported IS TRUE AND tcp.is_ac_supported IS TRUE AND tcp.is_hips_supported IS TRUE)
                        THEN pfm.product_feature_id IN ('HIPS_AGENT', 'HIPS_MGMT', 'HIPS_FW', 'AMC_MGMT', 'AC_AGENT', 'AC_MGMT', 'IM_MGMT')
                    WHEN n.machine_type = 'CONTAINER' AND n.container_service_type IN (SELECT tcp.container_service_type FROM tb_container_platform tcp WHERE tcp.is_amc_supported IS FALSE AND tcp.is_ac_supported IS TRUE AND tcp.is_hips_supported IS TRUE)
                        THEN pfm.product_feature_id IN ('HIPS_AGENT', 'HIPS_MGMT', 'HIPS_FW', 'AC_AGENT', 'AC_MGMT', 'IM_MGMT')
                    WHEN n.machine_type = 'CONTAINER' AND n.container_service_type IN (SELECT tcp.container_service_type FROM tb_container_platform tcp WHERE tcp.is_amc_supported IS FALSE AND tcp.is_ac_supported IS FALSE AND tcp.is_hips_supported IS TRUE)
                        THEN pfm.product_feature_id IN ('HIPS_AGENT', 'HIPS_MGMT', 'HIPS_FW')
                    ELSE FALSE
                END
        ) AS pfm
        ON
            pf.product_feature_id = pfm.product_feature_id
        INNER JOIN
            tb_policy AS p
        ON
            pf.product_feature_id = p.product_feature_id
        INNER JOIN
            tb_node_policy AS np
        ON
            np.policy_id = p.policy_id
        WHERE
            np.node_id = i_node_id
    ) AS p
    ORDER BY p.product_group, p.product_feature_id;
END;
$$;


ALTER FUNCTION public.sp_get_policy_agent_apply_list(i_node_id bigint) OWNER TO cppoltp;

--
-- Name: sp_get_policy_apply_count_list(bigint, bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_policy_apply_count_list(i_node_id bigint, i_policy_id bigint) RETURNS TABLE(product_feature_id public.en_product_feature_id_type, policy_id bigint, policy_status public.en_policy_status, count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE

BEGIN

	RETURN QUERY
	SELECT
		np.product_feature_id
		, np.policy_id
		, COALESCE(ps.policy_status, 'APPLYING')
		, COUNT(1) AS count
	FROM
		tb_node_policy AS np
		JOIN tb_node AS n ON np.node_id = n.node_id
		JOIN (
			SELECT DISTINCT pfm.product_feature_id, p.product_group
			FROM tb_product_feature_map AS pfm
			JOIN tb_product AS p ON pfm.product_id = p.product_id
		) AS pfm ON np.product_feature_id = pfm.product_feature_id
		LEFT JOIN vw_policy_status AS ps ON np.node_id = ps.node_id AND np.product_feature_id = ps.product_feature_id AND np.policy_id = ps.policy_id
	WHERE
		n.is_removed IS FALSE
		AND np.product_feature_id = 'AGENT_MGMT'
		AND CASE WHEN i_node_id IS NULL THEN TRUE ELSE np.node_id = i_node_id END
		AND CASE WHEN i_policy_id IS NULL THEN TRUE ELSE np.policy_id = i_policy_id END
	GROUP BY
		np.product_feature_id, np.policy_id, COALESCE(ps.policy_status, 'APPLYING')
	UNION ALL
	SELECT
		np.product_feature_id
		, np.policy_id
		, COALESCE(ps.policy_status, 'APPLYING')
		, COUNT(1) AS count
	FROM
		tb_node_policy AS np
		JOIN (
			SELECT n.node_id, p.product_group, p.product_id, pfm.product_feature_id
			FROM tb_node AS n
				JOIN tb_platform AS pf ON n.platform_id = pf.platform_id
				JOIN tb_product_info AS pi ON n.node_id = pi.node_id
				JOIN tb_product AS p ON p.product_id = pi.product_id
				JOIN tb_product_feature_map AS pfm ON p.product_id = pfm.product_id
			WHERE
				pf.is_supported IS TRUE
				AND n.is_removed IS FALSE
				AND sp_exist_license(p.product_group)
				AND NOT pfm.product_feature_id = ANY(ARRAY['AGENT_MGMT']::en_product_feature_id_type[])
		) AS pfm ON np.node_id = pfm.node_id AND np.product_feature_id = pfm.product_feature_id
		LEFT JOIN vw_policy_status AS ps ON np.node_id = ps.node_id AND np.product_feature_id = ps.product_feature_id AND np.policy_id = ps.policy_id
	WHERE
		CASE WHEN i_node_id IS NULL THEN TRUE ELSE np.node_id = i_node_id END
		AND CASE WHEN i_policy_id IS NULL THEN TRUE ELSE np.policy_id = i_policy_id END
	GROUP BY
		np.product_feature_id, np.policy_id, COALESCE(ps.policy_status, 'APPLYING')
	ORDER BY 1, 2;

END;
$$;


ALTER FUNCTION public.sp_get_policy_apply_count_list(i_node_id bigint, i_policy_id bigint) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_policy_apply_count_list(i_node_id bigint, i_policy_id bigint); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_policy_apply_count_list(i_node_id bigint, i_policy_id bigint) IS '
@brief [SWP-SCI1011] 도메인 정책별 적용 현황(olap)
@      [SWP-SCI1013] 에이전트 정책별 적용 현황(olap)
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_policy_apply_count_list(bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_policy_apply_count_list(i_node_id bigint, i_policy_id bigint, i_admin_id text) RETURNS TABLE(product_feature_id public.en_product_feature_id_type, policy_id bigint, policy_status public.en_policy_status, count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_manager_group_id bigint;
BEGIN

  SELECT manager_group_id INTO v_manager_group_id FROM tb_admin WHERE admin_id = i_admin_id;

	RETURN QUERY
	SELECT
		np.product_feature_id
		, np.policy_id
		, COALESCE(ps.policy_status, 'APPLYING')
		, COUNT(1) AS count
	FROM
		tb_node_policy AS np
		JOIN tb_node AS n ON np.node_id = n.node_id
		JOIN (
			SELECT DISTINCT pfm.product_feature_id, p.product_group
			FROM tb_product_feature_map AS pfm
			JOIN tb_product AS p ON pfm.product_id = p.product_id
      JOIN (SELECT a.product_feature_id FROM sp_get_policy_product_auth(i_admin_id) a) pa ON pa.product_feature_id = pfm.product_feature_id
		) AS pfm ON np.product_feature_id = pfm.product_feature_id
    JOIN tb_policy AS p ON np.policy_id = p.policy_id
		LEFT JOIN vw_policy_status AS ps ON np.node_id = ps.node_id AND np.product_feature_id = ps.product_feature_id AND np.policy_id = ps.policy_id
	WHERE
		n.is_removed IS FALSE
		AND np.product_feature_id = 'AGENT_MGMT'
		AND CASE WHEN i_node_id IS NULL THEN TRUE ELSE np.node_id = i_node_id END
		AND CASE WHEN i_policy_id IS NULL THEN TRUE ELSE np.policy_id = i_policy_id END
    AND v_manager_group_id = 1
    OR
		n.is_removed IS FALSE
		AND np.product_feature_id = 'AGENT_MGMT'
		AND CASE WHEN i_node_id IS NULL THEN TRUE ELSE np.node_id = i_node_id END
		AND CASE WHEN i_policy_id IS NULL THEN TRUE ELSE np.policy_id = i_policy_id END
    AND (p.manager_group_id = v_manager_group_id OR p.manager_group_id = 1)
	GROUP BY
		np.product_feature_id, np.policy_id, COALESCE(ps.policy_status, 'APPLYING')
	UNION ALL
	SELECT
		np.product_feature_id
		, np.policy_id
		, COALESCE(ps.policy_status, 'APPLYING')
		, COUNT(1) AS count
	FROM
		tb_node_policy AS np
		JOIN (
			SELECT n.node_id, p.product_group, p.product_id, pfm.product_feature_id
			FROM tb_node AS n
				JOIN tb_platform AS pf ON n.platform_id = pf.platform_id
				JOIN tb_product_info AS pi ON n.node_id = pi.node_id
				JOIN tb_product AS p ON p.product_id = pi.product_id
				JOIN tb_product_feature_map AS pfm ON p.product_id = pfm.product_id
        JOIN (SELECT a.product_feature_id FROM sp_get_policy_product_auth(i_admin_id) a) pa ON pa.product_feature_id = pfm.product_feature_id
			WHERE
				pf.is_supported IS TRUE
				AND n.is_removed IS FALSE
				AND sp_exist_license(p.product_group)
				AND NOT pfm.product_feature_id = ANY(ARRAY['AGENT_MGMT']::en_product_feature_id_type[])
		) AS pfm ON np.node_id = pfm.node_id AND np.product_feature_id = pfm.product_feature_id
    JOIN tb_policy AS p ON np.policy_id = p.policy_id
		LEFT JOIN vw_policy_status AS ps ON np.node_id = ps.node_id AND np.product_feature_id = ps.product_feature_id AND np.policy_id = ps.policy_id
	WHERE
		CASE WHEN i_node_id IS NULL THEN TRUE ELSE np.node_id = i_node_id END
		AND CASE WHEN i_policy_id IS NULL THEN TRUE ELSE np.policy_id = i_policy_id END
    AND v_manager_group_id = 1
    OR
		CASE WHEN i_node_id IS NULL THEN TRUE ELSE np.node_id = i_node_id END
		AND CASE WHEN i_policy_id IS NULL THEN TRUE ELSE np.policy_id = i_policy_id END
    AND (p.manager_group_id = v_manager_group_id OR p.manager_group_id = 1)
	GROUP BY
		np.product_feature_id, np.policy_id, COALESCE(ps.policy_status, 'APPLYING')
	ORDER BY 1, 2;

END;
$$;


