--
-- Name: sp_get_policy_apply_list(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_policy_apply_list(i_admin_id text) RETURNS TABLE(product_feature_id public.en_product_feature_id_type, product_feature_name text, policy_id bigint, policy_name text, description text, policy_type public.en_policy_type, modified_time timestamp without time zone, group_count bigint, each_count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_manager_group_id bigint;
BEGIN

  SELECT manager_group_id INTO v_manager_group_id FROM tb_admin WHERE admin_id = i_admin_id;

  RETURN QUERY
    WITH product_feature AS (
		SELECT DISTINCT pfm.product_feature_id, p.product_group, pf.name AS product_feature_name
		FROM tb_product AS p
		JOIN tb_product_feature_map AS pfm ON  pfm.product_id = p.product_id
		JOIN tb_product_feature AS pf ON pfm.product_feature_id = pf.product_feature_id
		WHERE pfm.product_feature_id <> 'V3NET_LU_UPDATE'
			AND sp_exist_product_license(p.product_id)
    )
	SELECT np.product_feature_id, pf.product_feature_name
		, np.policy_id, p.name AS policy_name, p.description, p.policy_type, p.modified_time
		, np.group_count, np.each_count
	FROM (
			SELECT p.product_feature_id, p.policy_id
			, SUM( CASE WHEN np.keep_agent_policy = false THEN 1 ELSE 0 END ) AS group_count
			, SUM( CASE WHEN np.keep_agent_policy = true THEN 1 ELSE 0 END ) AS each_count
			FROM tb_policy AS p
				LEFT JOIN tb_node_policy np ON np.policy_id = p.policy_id
			WHERE p.policy_type <> 'FACTORY'
			GROUP BY p.product_feature_id, p.policy_id
		) AS np
		JOIN tb_policy AS p ON p.policy_id = np.policy_id
		JOIN product_feature pf ON np.product_feature_id = pf.product_feature_id
    JOIN (SELECT a.product_feature_id FROM sp_get_policy_product_auth(i_admin_id) a) pa ON pa.product_feature_id = p.product_feature_id
  WHERE (p.manager_group_id = v_manager_group_id OR p.manager_group_id = 1)
      OR
        v_manager_group_id = 1
	ORDER BY pf.product_group, np.product_feature_id, np.policy_id;

END;
$$;


ALTER FUNCTION public.sp_get_policy_apply_list(i_admin_id text) OWNER TO cppoltp;

--
-- Name: sp_get_policy_array_list(public.en_product_feature_id_type[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_policy_array_list(i_product_feature_id public.en_product_feature_id_type[]) RETURNS TABLE(product_feature_id public.en_product_feature_id_type, product_feature_name text, policy_id bigint, policy_name text, description text, policy_type public.en_policy_type, modified_time timestamp without time zone)
    LANGUAGE plpgsql
    AS $$

BEGIN

RETURN QUERY

SELECT pf.product_feature_id AS product_feature_id
      ,coalesce(pf.name,'n') AS product_feature_name
      ,p.policy_id AS policy_id
      ,p.name AS policy_name
      ,p.description AS description
      ,p.policy_type AS policy_type
      ,p.modified_time AS modified_time
FROM tb_product_feature pf
JOIN tb_policy p
ON pf.product_feature_id = p.product_feature_id
WHERE pf.product_feature_id = ANY(i_product_feature_id)
  AND p.policy_type <> 'FACTORY'
;

END;
$$;


