--
-- Name: sp_get_policy_detail(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_policy_detail(i_policy_id bigint) RETURNS TABLE(product_feature_id public.en_product_feature_id_type, product_feature_name text, policy_id bigint, policy_name text, description text, policy_type public.en_policy_type, online_policy_body text, offline_policy_body text, use_offline_policy text, hash text, modified_time timestamp without time zone, group_id_array bigint[])
    LANGUAGE plpgsql
    AS $$

BEGIN

RETURN QUERY

--정책 상세
SELECT pf.product_feature_id AS product_feature_id
      ,pf.name AS product_feature_name
      ,p.policy_id AS policy_id
      ,p.name AS policy_name
      ,p.description AS description
      ,p.policy_type AS policy_type
      ,p.online_policy_body AS online_policy_body
      ,COALESCE(p.offline_policy_body, '') AS offline_policy_body
      ,COALESCE(p.use_offline_policy, false)::integer::text AS use_offline_policy
      ,COALESCE(p.hash, '') AS hash
      ,p.modified_time AS modified_time
      ,(SELECT array_agg(gp.group_id) FROM tb_group_policy gp WHERE gp.policy_id = p.policy_id) AS group_id_array
FROM tb_product_feature pf
JOIN tb_policy p
ON pf.product_feature_id = p.product_feature_id
  AND p.policy_id = i_policy_id
  AND p.policy_type <> 'FACTORY'
;

END;
$$;


