--
-- Name: sp_get_policy_factory(public.en_product_feature_id_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_policy_factory(i_product_feature_id public.en_product_feature_id_type) RETURNS TABLE(policy_id bigint, policy_name text, product_feature_id public.en_product_feature_id_type, description text, online_policy_body text, offline_policy_body text, use_offline_policy text, hash text, ppolicy_id bigint)
    LANGUAGE plpgsql
    AS $$

BEGIN

  --정책 공장초기화값 조회
  RETURN QUERY
  SELECT pf.policy_id AS policy_id
        ,pf.name AS policy_name
        ,pf.product_feature_id AS product_feature_id
        ,pf.description AS description
        ,pf.online_policy_body AS online_policy_body
        ,COALESCE(pf.offline_policy_body, '') AS offline_policy_body
        ,COALESCE(pf.use_offline_policy, false)::integer::text AS use_offline_policy
        ,COALESCE(pf.hash, '') AS hash
        ,pf.ppolicy_id AS ppolicy_id
  FROM tb_policy pf
  WHERE pf.product_feature_id = i_product_feature_id
    AND pf.policy_type = 'FACTORY';

END;
$$;


