--
-- Name: sp_get_policy_group_apply_list(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_policy_group_apply_list(i_group_id bigint) RETURNS TABLE(product_feature_id public.en_product_feature_id_type, product_feature_name text, policy_id bigint, policy_name text, description text, policy_type public.en_policy_type, modified_time timestamp without time zone, each_count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_ac en_product_group_type := NULL;
  v_hips en_product_group_type := NULL;
  v_scm en_product_group_type := NULL;
BEGIN

  IF sp_exist_license('AC') THEN
    v_ac := 'AC';
  END IF;

  IF sp_exist_license('HIPS') THEN
    v_hips := 'HIPS';
  END IF;
  
  IF sp_exist_license('SCM') THEN
    v_scm := 'SCM';
  END IF;  

  RETURN QUERY
  SELECT pf.product_feature_id AS product_feature_id
        ,pf.name AS product_feature_name
        ,p.policy_id AS policy_id
        ,p.name AS policy_name
        ,p.description AS description
        ,p.policy_type AS policy_type
        ,p.modified_time AS modified_time
        ,count(np.node_id) AS each_count
  FROM tb_product_feature AS pf
  JOIN tb_policy AS p
  ON pf.product_feature_id = p.product_feature_id
  JOIN (SELECT DISTINCT
               pfm.product_feature_id
              ,p.product_group
        FROM tb_product_feature_map pfm
        JOIN (SELECT product_id, name, product_group, is_server_product, is_client_product, unnest(platform_support) platform_type FROM tb_product) p
        ON pfm.product_id = p.product_id) pfm
    ON pf.product_feature_id = pfm.product_feature_id
    AND pfm.product_group = 'EMS'
  JOIN tb_group_policy gp
  ON p.product_feature_id = gp.product_feature_id
    AND gp.group_id = i_group_id
    AND gp.policy_id = p.policy_id
  LEFT JOIN tb_node_policy np
  ON gp.product_feature_id = np.product_feature_id
    AND np.node_id IN (SELECT n.node_id FROM tb_node n WHERE n.group_id = i_group_id)
    AND np.keep_agent_policy IS TRUE
  WHERE p.policy_type <> 'FACTORY'
  GROUP BY pf.product_feature_id
        ,pf.name
        ,p.policy_id
        ,p.name
        ,p.description
        ,p.policy_type
        ,p.modified_time
  UNION ALL
  SELECT pf.product_feature_id AS product_feature_id
        ,pf.name AS product_feature_name
        ,p.policy_id AS policy_id
        ,p.name AS policy_name
        ,p.description AS description
        ,p.policy_type AS policy_type
        ,p.modified_time AS modified_time
        ,count(np.node_id) AS each_count
  FROM tb_product_feature AS pf
  JOIN tb_policy AS p
  ON pf.product_feature_id = p.product_feature_id
  JOIN (SELECT DISTINCT
               pfm.product_feature_id
              ,pr.product_group
        FROM tb_platform pl
        JOIN (SELECT product_id, name, product_group, is_server_product, is_client_product, unnest(platform_support) platform_type FROM tb_product) pr
        ON pl.platform_type = pr.platform_type
          AND CASE
                WHEN pl.is_server THEN pr.is_server_product
                ELSE pr.is_client_product
              END IS TRUE
        JOIN tb_product_feature_map pfm
        ON pr.product_id = pfm.product_id) pfm
  ON p.product_feature_id = pfm.product_feature_id
    AND pfm.product_group IN ('V3',v_ac, v_hips, v_scm)
    AND pfm.product_feature_id <> 'V3NET_LU_UPDATE'
  JOIN tb_group_policy gp
  ON gp.product_feature_id = p.product_feature_id
    AND gp.group_id = i_group_id
    AND gp.policy_id = p.policy_id
  LEFT JOIN tb_node_policy np
  ON gp.product_feature_id = np.product_feature_id
    AND np.node_id IN (SELECT n.node_id FROM tb_node n WHERE n.group_id = i_group_id)
    AND np.keep_agent_policy IS TRUE
  WHERE p.policy_type <> 'FACTORY'
  GROUP BY pf.product_feature_id
        ,pf.name
        ,p.policy_id
        ,p.name
        ,p.description
        ,p.policy_type
        ,p.modified_time;

END;
$$;


