--
-- Name: sp_get_policy_hash_list(bigint, inet); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_policy_hash_list(i_node_id bigint, i_private_ip inet) RETURNS TABLE(product_feature_id public.en_product_feature_id_type, hash_value text, common_hash_value text, extra_hash_value text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

RETURN QUERY
    WITH wt_kept_node_policy AS (
      SELECT np.product_feature_id, np.policy_id
      FROM tb_node_policy AS np
      WHERE np.node_id = i_node_id AND np.keep_agent_policy = TRUE
    ), wt_delegated_policy AS (
      SELECT gp.product_feature_id, gp.policy_id
      FROM tb_group_policy AS gp
      JOIN tb_node AS n ON n.node_id = i_node_id AND n.group_id = gp.group_id
      WHERE NOT(gp.product_feature_id = ANY(SELECT kp.product_feature_id FROM wt_kept_node_policy AS kp))
    ), wt_node_policy AS (
      SELECT np.product_feature_id, np.policy_id FROM wt_kept_node_policy AS np
      UNION
      SELECT dp.product_feature_id, dp.policy_id FROM wt_delegated_policy AS dp
    )
    SELECT DISTINCT n.product_feature_id
        , p.hash AS hash_value
        , COALESCE(cp.hash_value, '') AS common_hash_value
        , COALESCE(ep.hash_value, '') AS extra_hash_value
    FROM wt_node_policy AS n
    JOIN tb_policy AS p ON n.policy_id = p.policy_id
    LEFT JOIN tb_common_policy AS cp ON n.product_feature_id = cp.product_feature_id
    LEFT JOIN sp_get_mergeable_extra_policy_hash_list(i_node_id, i_private_ip) AS ep ON n.product_feature_id = ep.product_feature_id;
END;
$$;


ALTER FUNCTION public.sp_get_policy_hash_list(i_node_id bigint, i_private_ip inet) OWNER TO cppoltp;

--
-- Name: sp_get_policy_list(public.en_product_feature_id_type, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_policy_list(i_product_feature_id public.en_product_feature_id_type, i_admin_id text) RETURNS TABLE(product_feature_id public.en_product_feature_id_type, product_feature_name text, policy_id bigint, policy_name text, description text, policy_type public.en_policy_type, modified_time timestamp without time zone)
    LANGUAGE plpgsql
    AS $$

DECLARE
  v_manager_group_id bigint;
BEGIN

SELECT manager_group_id INTO v_manager_group_id FROM tb_admin WHERE admin_id = i_admin_id;

RETURN QUERY
  SELECT
    pf.product_feature_id AS product_feature_id
    , coalesce(pf.name,'n') AS product_feature_name
    , p.policy_id AS policy_id
    , p.name AS policy_name
    , p.description AS description
    , p.policy_type AS policy_type
    , p.modified_time AS modified_time
  FROM 
    tb_product_feature pf
  INNER JOIN 
    tb_policy p
  ON 
    pf.product_feature_id = p.product_feature_id
  INNER JOIN 
    (
      SELECT 
        tpfm.product_feature_id 
      FROM 
        tb_product_license tpl 
      INNER JOIN 
        tb_product_feature_map tpfm 
      ON 
        tpl.product_id = (CASE WHEN tpfm.product_id = 'AGENT' THEN 'EMS' ELSE tpfm.product_id END)
      WHERE
        tpl.expire_date > now()
    ) tpl
  ON
    pf.product_feature_id = tpl.product_feature_id
  INNER JOIN
    (
      SELECT
        a.product_feature_id
      FROM
        sp_get_policy_product_auth(i_admin_id) a
    ) pa
    ON
      pa.product_feature_id = pf.product_feature_id  
  WHERE 
    pf.product_feature_id = i_product_feature_id
  AND 
    p.policy_type <> 'FACTORY'
  AND
    v_manager_group_id = 1
  OR
    pf.product_feature_id = i_product_feature_id
  AND 
    p.policy_type <> 'FACTORY'
  AND
    (p.manager_group_id = v_manager_group_id OR p.manager_group_id = 1)
  ;

END;
$$;


ALTER FUNCTION public.sp_get_policy_list(i_product_feature_id public.en_product_feature_id_type, i_admin_id text) OWNER TO cppoltp;

