--
-- Name: sp_get_policy_product_auth(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_policy_product_auth(i_admin_id text) RETURNS TABLE(product_feature_id public.en_product_feature_id_type)
    LANGUAGE plpgsql
    AS $$
    BEGIN

      RETURN QUERY
    
        SELECT
            'AGENT_MGMT'::en_product_feature_id_type AS privilege_profile_id 
        FROM
            tb_admin ta
        INNER JOIN
            tb_privilege_profile tpp
        ON
            tpp.privilege_profile_id = ta.privilege_profile_id
        WHERE
            ta.admin_id = i_admin_id
        AND
            tpp.profile_body LIKE '%/policy/policy_SA_R%'
            
        UNION

        SELECT
            'V3NET_9.0_AV'::en_product_feature_id_type AS privilege_profile_id 
        FROM
            tb_admin ta
        INNER JOIN
            tb_privilege_profile tpp
        ON
            tpp.privilege_profile_id = ta.privilege_profile_id
        WHERE
            ta.admin_id = i_admin_id
        AND
            tpp.profile_body LIKE '%/policy/policy_V3W_R%'
            
        UNION

        SELECT
            'V3NET_LU_AV'::en_product_feature_id_type AS privilege_profile_id 
        FROM
            tb_admin ta
        INNER JOIN
            tb_privilege_profile tpp
        ON
            tpp.privilege_profile_id = ta.privilege_profile_id
        WHERE
            ta.admin_id = i_admin_id
        AND
            tpp.profile_body LIKE '%/policy/policy_V3L_R%'

        UNION

        SELECT
            'V3NET_LU_UPDATE'::en_product_feature_id_type AS privilege_profile_id 
        FROM
            tb_admin ta
        INNER JOIN
            tb_privilege_profile tpp
        ON
            tpp.privilege_profile_id = ta.privilege_profile_id
        WHERE
            ta.admin_id = i_admin_id
        AND
            tpp.profile_body LIKE '%/policy/policy_V3L_R%'
            
        UNION

        SELECT
            'HIPS_AGENT'::en_product_feature_id_type AS privilege_profile_id 
        FROM
            tb_admin ta
        INNER JOIN
            tb_privilege_profile tpp
        ON
            tpp.privilege_profile_id = ta.privilege_profile_id
        WHERE
            ta.admin_id = i_admin_id
        AND
            tpp.profile_body LIKE '%/policy/policy_HIPS_A_R%'
            
        UNION

        SELECT
            'HIPS_MGMT'::en_product_feature_id_type AS privilege_profile_id 
        FROM
            tb_admin ta
        INNER JOIN
            tb_privilege_profile tpp
        ON
            tpp.privilege_profile_id = ta.privilege_profile_id
        WHERE
            ta.admin_id = i_admin_id
        AND
            tpp.profile_body LIKE '%/policy/policy_HIPS_IPS_R%'
            
        UNION

        SELECT
            'HIPS_FW'::en_product_feature_id_type AS privilege_profile_id 
        FROM
            tb_admin ta
        INNER JOIN
            tb_privilege_profile tpp
        ON
            tpp.privilege_profile_id = ta.privilege_profile_id
        WHERE
            ta.admin_id = i_admin_id
        AND
            tpp.profile_body LIKE '%/policy/policy_HIPS_FW_R%'
            
        UNION

        SELECT
            'AC_AGENT'::en_product_feature_id_type AS privilege_profile_id 
        FROM
            tb_admin ta
        INNER JOIN
            tb_privilege_profile tpp
        ON
            tpp.privilege_profile_id = ta.privilege_profile_id
        WHERE
            ta.admin_id = i_admin_id
        AND
            tpp.profile_body LIKE '%/policy/policy_AC_A_R%'
            
        UNION

        SELECT
            'AC_MGMT'::en_product_feature_id_type AS privilege_profile_id 
        FROM
            tb_admin ta
        INNER JOIN
            tb_privilege_profile tpp
        ON
            tpp.privilege_profile_id = ta.privilege_profile_id
        WHERE
            ta.admin_id = i_admin_id
        AND
            tpp.profile_body LIKE '%/policy/policy_AC_PC_R%'
            
        UNION

        SELECT
            'IM_MGMT'::en_product_feature_id_type AS privilege_profile_id 
        FROM
            tb_admin ta
        INNER JOIN
            tb_privilege_profile tpp
        ON
            tpp.privilege_profile_id = ta.privilege_profile_id
        WHERE
            ta.admin_id = i_admin_id
        AND
            tpp.profile_body LIKE '%/policy/policy_AC_IM_R%'
            
        UNION

        SELECT
            'AMC_MGMT'::en_product_feature_id_type AS privilege_profile_id 
        FROM
            tb_admin ta
        INNER JOIN
            tb_privilege_profile tpp
        ON
            tpp.privilege_profile_id = ta.privilege_profile_id
        WHERE
            ta.admin_id = i_admin_id
        AND
            tpp.profile_body LIKE '%/policy/policy_AMC_R%'
            
            ;
    END;
$$;


