--
-- Name: sp_get_policy_target_filter(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_policy_target_filter(i_policy_id bigint) RETURNS TABLE(target_filter text)
    LANGUAGE plpgsql
    AS $$
BEGIN

  RETURN QUERY
  SELECT CASE WHEN p.filter = '{AGENT}'
              THEN '[]'
              ELSE (SELECT array_to_json(array_agg(row_to_json(tf)))::TEXT FROM (SELECT p.type, p.filter) tf)::text
         END AS target_filter
  FROM (SELECT 'PRODUCT_ID' AS type
              ,array_agg(pf.product_id) AS filter
        FROM tb_policy p
        JOIN tb_product_feature_map pf
        ON p.product_feature_id = pf.product_feature_id
        WHERE p.policy_id = i_policy_id) p;

END;
$$;


ALTER FUNCTION public.sp_get_policy_target_filter(i_policy_id bigint) OWNER TO cppoltp;

--
-- Name: sp_get_policy_task(bigint, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_policy_task(i_policy_id bigint, i_admin_id text) RETURNS TABLE(type text, target text)
    LANGUAGE plpgsql
    AS $$
BEGIN

  RETURN QUERY
  SELECT t.type
        ,t.target::text
  FROM tb_policy p
  LEFT JOIN (SELECT array_agg(tgp.group_id) AS target
                   ,tgp.policy_id
                   ,'GROUP' AS type
             FROM tb_group_policy tgp
             WHERE EXISTS (SELECT 1 FROM tb_group tg WHERE tg.group_id = tgp.group_id AND tg.is_removed IS FALSE)
             GROUP BY tgp.policy_id
             UNION ALL
             SELECT array_agg(tnp.node_id) AS target
                   ,tnp.policy_id
                   ,'NODE' AS type
             FROM tb_node_policy tnp
             WHERE EXISTS (SELECT 1 FROM tb_node n WHERE n.node_id = tnp.node_id AND n.is_removed IS FALSE)
               AND tnp.keep_agent_policy IS TRUE
             GROUP BY tnp.policy_id) t
  ON p.policy_id = t.policy_id
  WHERE t.target IS NOT NULL
	  AND p.policy_id = i_policy_id
;

END;
$$;


ALTER FUNCTION public.sp_get_policy_task(i_policy_id bigint, i_admin_id text) OWNER TO cppoltp;

