--
-- Name: sp_get_preprocess_auto_grouping_by_dept(bigint[], text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_preprocess_auto_grouping_by_dept(i_target_nodes bigint[], i_base_path text) RETURNS TABLE(node_id bigint, department text, is_modified_by_admin boolean, is_exceed_depth boolean, is_cloud_node boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_physical_type_group_path             text    := (SELECT sp_get_group_name_path(tg.group_id) FROM tb_group tg WHERE tg.group_type = 'PHYSICAL');
  v_max_group_depth                      int     := (SELECT tc.value::int FROM tb_config tc WHERE tc.config_group = 'GENERAL' AND tc.key = 'group_depth');

BEGIN

  IF (SELECT value FROM tb_config WHERE config_group = 'GROUPING' AND key = 'auto_grouping_type') = 'dept' THEN
    RETURN QUERY
        SELECT 
          tn.node_id AS node_id
          , tu.department AS department
          , tu.modified_by_admin AS is_modified_by_admin
          , CASE WHEN ARRAY_LENGTH((STRING_TO_ARRAY(REPLACE(CONCAT(BTRIM(v_physical_type_group_path, '/'), '/', BTRIM(i_base_path, '/'), '/', BTRIM(tu.department, '/')), '//', '/'), '/')), 1) > v_max_group_depth
              THEN TRUE
              ELSE FALSE
              END AS is_exceed_depth
          , sp_check_connect_cloud(tn.machine_uuid, tn.machine_type) -- [CWPP-6676] 클라우드 연동된 노드는 자동 그룹화 제외
        FROM 
          tb_node tn
        LEFT JOIN tb_user tu ON tn.node_id = tu.node_id
        WHERE
          tn.node_id = ANY(i_target_nodes);
  ELSE
    -- 담당 부서별 자동 그룹화가 아닌 경우, 모두 FALSE 반환.
    RETURN QUERY
      SELECT
        t.node_id AS node_id
        , '' AS department
        , FALSE AS is_modified_by_admin
        , FALSE AS is_exceed_depth
        , FALSE AS is_cloud_node
      FROM
        (SELECT UNNEST(i_target_nodes) AS node_id) AS t;
  END IF;
END;
$$;


ALTER FUNCTION public.sp_get_preprocess_auto_grouping_by_dept(i_target_nodes bigint[], i_base_path text) OWNER TO cppoltp;

