--
-- Name: sp_get_private_file_server_path(bigint, inet); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_private_file_server_path(i_node_id bigint, i_ip_connected inet) RETURNS TABLE(url text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

	RETURN QUERY
	WITH nat AS (
		SELECT is_nat = 'true' AS is_nat FROM sp_get_is_nat(i_ip_connected) t
	)
  SELECT
    t.scheme ||  CASE WHEN (SELECT is_nat FROM nat) THEN t.public_ip ELSE t.private_ip END || ':' || t.port AS url
  FROM  (
    SELECT
      CASE WHEN p.service_type = 'FILESERVER-HTTP' THEN 'http://' ELSE 'https://' END AS scheme
      , s.ip private_ip
      , s.public_ip public_ip
      , p.port
      FROM tb_file_update_server fs JOIN tb_server s ON fs.server_id = s.server_id, tb_service_port p
      WHERE fs.target_type = 'NODE'
      AND p.service_type IN ('FILESERVER-HTTP', 'FILESERVER-HTTPS')
      AND fs.target_id = i_node_id
  ) t;


END;
$$;


