    LANGUAGE plpgsql
    AS $$
DECLARE
  v_profile_type              en_privilege_profile_type;
BEGIN

  -- login_admin_id 의 권한 가져오기
  v_profile_type := sp_get_admin_privilege_type( i_login_admin_id );

  IF v_profile_type = 'ROOT_ADMIN' THEN
    RETURN QUERY
      SELECT
        p.privilege_profile_id::text
        , p.profile_type
        , p.profile_name
        , p.description
      FROM tb_privilege_profile AS p
      WHERE p.profile_type = 'CUSTOM_ADMIN';
  ELSE
    RETURN QUERY
      SELECT
        p.privilege_profile_id::text
        , p.profile_type
        , p.profile_name
        , p.description
      FROM tb_privilege_profile AS p
      WHERE p.privilege_profile_id = (SELECT a.privilege_profile_id FROM tb_admin AS a WHERE a.admin_id = i_login_admin_id)
        AND p.profile_type = 'CUSTOM_ADMIN';
  END IF;

END;
$$;


