--
-- Name: sp_get_procedure_info(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_procedure_info() RETURNS TABLE(procedure text, arguments text)
    LANGUAGE plpgsql
    AS $$
BEGIN
RETURN QUERY
SELECT  proname::text, case when pronargs = 0 then '()' else '(' || array_to_string(proargnames[1:pronargs], '=''%s'', ') || '=''%s'')' end as proargnames
FROM    pg_catalog.pg_namespace n
JOIN    pg_catalog.pg_proc p   ON    pronamespace = n.oid
WHERE   nspname = 'public' AND p.proname LIKE 'sp\_%';
END;
$$;


