--
-- Name: sp_get_product_auth_check(text, public.en_product_group_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_product_auth_check(i_product_auth text, i_product_group public.en_product_group_type) RETURNS TABLE(is_auth_ok boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE


BEGIN

  IF i_product_auth IS NULL THEN

    RETURN QUERY
    SELECT
      (CASE WHEN COUNT(DISTINCT p.product_group) > 0 THEN TRUE ELSE FALSE END)
    FROM
      tb_product_license pl
      JOIN tb_product p ON pl.product_id = p.product_id
    WHERE
      p.product_group = i_product_group;

  ELSE
    RETURN QUERY
    SELECT
      (CASE WHEN COUNT(DISTINCT p.product_group) > 0 THEN TRUE ELSE FALSE END)
    FROM
      tb_product_license pl
      JOIN tb_product p ON pl.product_id = p.product_id
    WHERE
      p.product_group = ANY(string_to_array(i_product_auth, ',')::en_product_group_type[])
      AND p.product_group = i_product_group;

  END IF;

END;
$$;


