-- Name: sp_get_product_feature_list(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_product_feature_list() RETURNS TABLE(product_feature_id public.en_product_feature_id_type, product_feature_name text)
    LANGUAGE plpgsql
    AS $$

BEGIN

