--
-- Name: sp_get_product_group_list(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_product_group_list() RETURNS TABLE(product_group text, product_id text, product_feature_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT p.product_group::TEXT
          ,p.product_id::TEXT
          ,pfm.product_feature_id::TEXT
    FROM tb_product as p
    JOIN tb_product_feature_map pfm
    ON p.product_id = pfm.product_id
    WHERE p.product_group = 'EMS'
    UNION ALL
    SELECT DISTINCT p.product_group::TEXT
          ,CASE WHEN p.product_group = 'V3' THEN NULL ELSE p.product_id::TEXT END
          ,CASE WHEN p.product_group = 'V3' THEN NULL ELSE pfm.product_feature_id::TEXT END
    FROM tb_product as p
    JOIN tb_product_feature_map pfm ON p.product_id = pfm.product_id
    WHERE p.product_group <> 'EMS'
      AND sp_exist_product_license(p.product_id);

END;
$$;


