--
-- Name: sp_get_product_list(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_product_list() RETURNS TABLE(product_id public.en_product_id_type, name text, description text, product_group public.en_product_group_type, is_server_product boolean, is_client_product boolean, managed boolean, is_manageable boolean, is_default boolean, product_code integer, license_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
RETURN QUERY
    SELECT
      p.product_id, -- 제품 ID
      p.name, -- 제품 명
      p.description, -- 설명
      p.product_group, -- 제품 그룹 ID
      p.is_server_product, -- 서버 제품 여부
      p.is_client_product, -- 클라이언트 제품 여부
      p.managed, -- 관리 대상 여부
      p.is_manageable, -- 관리 가능 여부
      p.is_default, -- 기본 제품 여부
      p.product_code, -- 제품 업데이트 코드
      p.license_id
    FROM tb_product as p
    WHERE p.product_id = 'AGENT'
    UNION ALL
    SELECT
      p.product_id, -- 제품 ID
      p.name, -- 제품 명
      p.description, -- 설명
      p.product_group, -- 제품 그룹 ID
      p.is_server_product, -- 서버 제품 여부
      p.is_client_product, -- 클라이언트 제품 여부
      p.managed, -- 관리 대상 여부
      p.is_manageable, -- 관리 가능 여부
      p.is_default, -- 기본 제품 여부
      p.product_code, -- 제품 업데이트 코드
      p.license_id
    FROM tb_product as p
    WHERE p.product_group NOT IN ('EMS', 'CNAPP')  -- CWPP-6820 : CNAPP 제외
      AND sp_exist_product_license(p.product_id);

END;
$$;


