    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
   SELECT
      tpp.product_pkg_id
      , tpp.pkg_type
      , tpp.product_id
      , tpp.install_ip
      , (SELECT ts.server_id FROM tb_server ts WHERE ip = tpp.install_ip) AS server_id
  FROM tb_product_pkg tpp
  WHERE tpp.pkg_status = 'SUCCESS'
   AND tpp.is_removed is false
