--
-- Name: sp_get_product_pkg(bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_product_pkg(i_task_id bigint[]) RETURNS TABLE(task_status public.en_task_status, task_id bigint, count bigint, node_id bigint, ip inet)
    LANGUAGE plpgsql
    AS $$
DECLARE
  e_task_id bigint;
BEGIN

FOREACH e_task_id IN ARRAY i_task_id
LOOP

  RETURN QUERY

  WITH
  s AS
  (
    SELECT DISTINCT
    tts.task_id,
    (
      CASE WHEN EXISTS
      (
        SELECT 1 FROM tb_task_target_status tts WHERE tts.task_id = e_task_id
        AND (tts.task_status = 'SENT' OR tts.task_status = 'WAITING' )
      )
      THEN 'WAITING'::en_task_status
      ELSE 'SUCCESS'::en_task_status
      END
    )AS task_status
    FROM tb_task_target_status tts
    WHERE tts.task_id = e_task_id
  ),
  c AS
  (
    SELECT COUNT(*) AS count, tts.task_id
    FROM tb_task_target_status tts
    WHERE tts.task_id = e_task_id
    GROUP BY tts.task_id
  )
  SELECT
    s.task_status::en_task_status
    ,s.task_id::bigint
    ,c.count
    ,ttsn.node_id
    ,ttsn.ip
  FROM (
    SELECT DISTINCT
      tts.task_id
      ,n.node_id
      ,n.ip
      ,row_number() OVER(PARTITION BY tts.task_id ORDER BY tts.task_id DESC) AS row_order
    FROM tb_task_target_status tts
    JOIN tb_node n ON tts.target_id = n.node_id
    WHERE tts.task_id = e_task_id
    AND tts.task_target_type = 'NODE'
    ORDER BY tts.task_id
  ) AS ttsn
  JOIN s USING (task_id)
  JOIN c USING (task_id)
  WHERE ttsn.row_order = 1
  ;

END LOOP;
END;
$$;


ALTER FUNCTION public.sp_get_product_pkg(i_task_id bigint[]) OWNER TO cppoltp;

--
-- Name: sp_get_product_pkg(bigint, public.en_product_id_type, public.en_platform_type, integer, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_product_pkg(i_node_id bigint, i_product_id public.en_product_id_type, i_platform_type public.en_platform_type, i_major integer, i_minor integer, i_bit integer, i_is_server boolean) RETURNS TABLE(license_no text, license_org text, license_user text, url text, http_port integer, https_port integer)
    LANGUAGE plpgsql
    AS $$
BEGIN

  RETURN QUERY
  WITH o AS (
  	SELECT VALUE license_org  FROM tb_config  WHERE config_group = 'SYS_INFO' AND key = 'company_name'
  )
  , u AS (
  	SELECT VALUE license_user  FROM tb_config  WHERE config_group = 'SYS_INFO'  AND key = 'user_name'
  )
  SELECT
    license.license_no::text      AS "license_no",
    o.license_org::text      AS "license_org",
    u.license_user::text      AS "license_user",
    pkg.path                AS "url",
    (SELECT tsp.port FROM tb_service_port tsp WHERE tsp.service_type = 'LBDIST-HTTP') AS http_port,
    (SELECT tsp.port FROM tb_service_port tsp WHERE tsp.service_type = 'LBDIST-HTTPS') AS https_port
  FROM o, u,
  	(SELECT product_id, unnest(platform_support) platform_type FROM tb_product) AS product
  	JOIN tb_product_license AS license  ON  product.product_id = license.product_id
  	JOIN tb_platform    AS platform ON platform.platform_type = product.platform_type
  	LEFT JOIN tb_product_pkg   AS pkg ON product.product_id = pkg.product_id AND platform.platform_type = pkg.platform_type
  WHERE  license.expire_date > now()
  	AND platform.is_supported IS TRUE
  	AND pkg.is_removed is false
  	AND product.product_id = i_product_id
  	AND license.product_id = i_product_id
  	AND platform.platform_type = i_platform_type
	AND platform.major = i_major
	AND platform.minor = i_minor
	AND platform.bit = i_bit
	AND platform.is_server = i_is_server
  LIMIT 1;

END;
$$;


ALTER FUNCTION public.sp_get_product_pkg(i_node_id bigint, i_product_id public.en_product_id_type, i_platform_type public.en_platform_type, i_major integer, i_minor integer, i_bit integer, i_is_server boolean) OWNER TO cppoltp;

--
-- Name: sp_get_product_pkg2(bigint, public.en_product_id_type, public.en_platform_type, integer, integer, integer, boolean, inet); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_product_pkg2(i_node_id bigint, i_product_id public.en_product_id_type, i_platform_type public.en_platform_type, i_major integer, i_minor integer, i_bit integer, i_is_server boolean, i_ip_connected inet) RETURNS TABLE(license_no text, license_org text, license_user text, url text)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
    SELECT
      license.license_no
      ,(SELECT VALUE license_org FROM tb_config WHERE config_group = 'SYS_INFO' AND key = 'company_name') AS license_org
    , (SELECT VALUE license_org FROM tb_config WHERE config_group = 'SYS_INFO' AND key = 'user_name') AS license_user
    , file_info.url
    FROM tb_product_license license, (
      SELECT
      *
      FROM sp_get_file_server_path(i_node_id, i_ip_connected, NULL, NULL, i_product_id, i_platform_type, i_major, i_minor, i_bit, i_is_server, NULL, NULL)
    ) file_info
    WHERE product_id = i_product_id
  ;
END;
$$;


