--
-- Name: sp_get_product_pkg_job(bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_product_pkg_job(i_product_pkg_id bigint[]) RETURNS TABLE(job_id text)
    LANGUAGE plpgsql
    AS $$

BEGIN

  RETURN QUERY
  SELECT array_agg(DISTINCT j.job_id)::text
  FROM (SELECT j.job_id
              ,j.type
              ,trim(json_array_elements(j.filter::json)::text, '"')::bigint AS filter
        FROM (SELECT j.job_id
                    ,trim((json_array_elements(j.target_filter::json) -> 'type')::text, '"') AS type
                    ,json_array_elements(j.target_filter::json) -> 'filter' AS filter
              FROM tb_job j
              WHERE j.target_filter IS NOT NULL) j
        WHERE j.type = 'PRODUCT_PKG_ID') j
  WHERE j.filter = ANY(i_product_pkg_id);

END;
$$;


ALTER FUNCTION public.sp_get_product_pkg_job(i_product_pkg_id bigint[]) OWNER TO cppoltp;

--
-- Name: sp_get_product_pkg_list(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_product_pkg_list(i_product_auth text) RETURNS TABLE(product_pkg_id text, product_id text, name text, version text, size text, modified_time text, platform_type text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_product_auth              en_product_group_type[];
BEGIN

  -- 권한 처리
  IF i_product_auth IS NOT NULL AND LENGTH(TRIM(i_product_auth)) > 0 THEN
    v_product_auth := STRING_TO_ARRAY(REPLACE(i_product_auth, ' ', ''), ',')::en_product_group_type[];
  ELSE
    SELECT ENUM_RANGE(null::en_product_group_type) INTO v_product_auth;
  END IF;

  RETURN QUERY
    SELECT
        pkg.product_pkg_id::text,
        pkg.product_id::text,
        pkg.name,
        pkg.version,
        pkg.size::text,
        pkg.modified_time::text,
        pkg.platform_type::text
    FROM
      tb_product_pkg pkg
    WHERE
      pkg.pkg_type = 'PRODUCT_INSTALL'
        AND pkg.is_removed IS FALSE
        AND EXISTS (
          SELECT
            1
          FROM
            tb_pkg_platform pp
            INNER JOIN tb_platform pf ON pf.platform_id = pp.platform_id
        WHERE
          pf.is_supported IS TRUE
          AND pp.product_pkg_id = pkg.product_pkg_id
        )
        AND EXISTS (
          SELECT
            1
        FROM
          tb_product_license AS pl
          JOIN tb_product p ON pl.product_id = p.product_id
        WHERE
          pl.product_id = pkg.product_id
          AND p.product_group = ANY(v_product_auth)
        )
    ORDER BY
      CASE WHEN pkg.platform_type = 'WINDOWS' THEN 1 ELSE 2 END ASC
      , CASE WHEN pkg.product_id = 'V3NET_9.0' OR pkg.product_id = 'V3NET_LU' THEN 1
        WHEN pkg.product_id = 'HIPS_CLIENT' THEN 2
        ELSE 3 END ASC;

END;
$$;


ALTER FUNCTION public.sp_get_product_pkg_list(i_product_auth text) OWNER TO cppoltp;

--
-- Name: sp_get_product_policy_list(public.en_product_feature_id_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_product_policy_list(i_product_feature_id public.en_product_feature_id_type) RETURNS TABLE(policy_id bigint, policy_name text)
    LANGUAGE plpgsql
    AS $$
BEGIN

  RETURN QUERY
  SELECT p.policy_id AS policy_id
        ,p.name AS policy_name
  FROM tb_product_feature pf
  JOIN tb_policy p
  ON pf.product_feature_id = p.product_feature_id
    AND p.ppolicy_id IS NULL
    AND p.policy_type <> 'FACTORY'
  WHERE pf.product_feature_id = i_product_feature_id;

END;
$$;


