--
-- Name: sp_get_product_status(bigint, public.en_product_id_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_product_status(i_node_id bigint, i_product_id public.en_product_id_type) RETURNS TABLE(node_id bigint, product_id public.en_product_id_type, product_version text, engine_version text, license_no text, license_user text, license_org text, install_time timestamp without time zone, realtime_status boolean, engine_update_time timestamp without time zone, last_scan_time timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN


    RETURN QUERY
      SELECT
       PRS.node_id                                /* 노드 ID */
      , PRS.product_id                            /* 제품 ID */
      , PRS.product_version                       /* 제품 버전 */
      , PRS.engine_version                        /* 엔진 버전 */
      , PRS.license_no                            /* 라이선스 번호 */
      , PRS.license_user                          /* 라이선스 사용자 */
      , PRS.license_org                           /* 라이선스 조직 */
      , PRS.install_time                          /* 설치 시각 */
      , PRS.realtime_status
      , PRS.engine_update_time
      , PRS.last_scan_time
      FROM tb_product_status AS PRS
      WHERE PRS.node_id = i_node_id
      AND PRS.product_id = i_product_id;

END;
$$;


ALTER FUNCTION public.sp_get_product_status(i_node_id bigint, i_product_id public.en_product_id_type) OWNER TO cppoltp;

--
-- Name: sp_get_product_update(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_product_update(i_node_id bigint) RETURNS TABLE(ses text, oes text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_ses_path                  text[];
  v_oes_path                  text[];
BEGIN

  -- SES_PATH 가져오기
  SELECT ARRAY_AGG(DISTINCT p.path) INTO v_ses_path
  FROM tb_product_pkg AS p
  WHERE p.pkg_type = 'UPDATE_SES'
    AND p.is_removed is false
    AND p.version = (SELECT c.value FROM tb_config AS c WHERE c.config_group = 'UPDATE_SERVICE' AND c.key = 'ses_engine_date');

  -- OES_PATH 가져오기
  SELECT ARRAY_AGG(DISTINCT p.path) INTO v_oes_path
  FROM tb_product_pkg AS p
  WHERE p.pkg_type = 'UPDATE_OES'
    AND p.is_removed is false
    AND p.version = (SELECT c.value FROM tb_config AS c WHERE c.config_group = 'UPDATE_SERVICE' AND c.key = 'oes_engine_date');


  RETURN QUERY
    SELECT t.ses_path, t.oes_path
    FROM UNNEST(v_ses_path, v_oes_path) AS t(ses_path, oes_path);

END;
$$;


ALTER FUNCTION public.sp_get_product_update(i_node_id bigint) OWNER TO cppoltp;

