--
-- Name: sp_get_product_version(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_product_version() RETURNS TABLE(product_id text, platform_type text, version text, build_number text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
        SELECT
            'CPPM' AS product_id
            , NULL AS platform_type
            , split_part(current_version, '-', 1) AS version
            , split_part(current_version, '-', 2) AS build_number
        FROM
            tb_server
        WHERE
            server_id = 1
            
        UNION ALL
        
        SELECT
            tpl.product_id::text AS product_id
            , tppi.platform_type::text AS platform_type
            , tppi.oes_version AS VERSION
            , CASE WHEN tppi.oes_build_date LIKE '%.%' THEN split_part(tppi.oes_build_date, '.', array_length(string_to_array(tppi.oes_build_date, '.'), 1))
                   ELSE tppi.oes_build_date
                   END AS build_number
        FROM
            (
                SELECT
                    CASE WHEN inner_tpl.product_id = 'EMS' THEN 'AGENT'
                         ELSE inner_tpl.product_id
                         END AS product_id
                FROM
                    tb_product_license inner_tpl
                WHERE
                    inner_tpl.expire_date > now()
            ) tpl
        INNER JOIN
            tb_product_patch_info tppi 
        ON
            tpl.product_id = tppi.product_id 
        ORDER BY
            product_id ASC;

END;
$$;


ALTER FUNCTION public.sp_get_product_version() OWNER TO cppoltp;

