--
-- Name: sp_get_raid_status(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_raid_status() RETURNS TABLE(server_id bigint, raid_state text, log_time timestamp without time zone)
    LANGUAGE plpgsql
    AS $$

BEGIN

RETURN QUERY
--raid 상태
SELECT sr.server_id AS server_id
      ,sr.raid_state AS raid_state
      ,sr.log_time AS log_time
FROM (SELECT sr.server_id AS server_id
            ,sr.raid_state AS raid_state
            ,sr.log_time AS log_time
            ,RANK() OVER(PARTITION BY sr.server_id ORDER BY sr.log_time DESC) AS log_order
      FROM tb_server_resource sr
     ) sr
WHERE sr.log_order = 1
;

END;
$$;


