--
-- Name: sp_get_register_agent_summary(bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_register_agent_summary(i_node_id bigint[]) RETURNS TABLE(all_count bigint, connected_count bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
  v_all_count bigint;
  v_connected_count bigint;
BEGIN

  v_all_count = array_length(i_node_id, 1);

  SELECT count(*)
  INTO v_connected_count
  FROM tb_node_status ns
  WHERE ns.node_id = ANY(i_node_id)
    AND ns.connection_status = 'CONNECTED'
    AND EXISTS (SELECT 1 FROM tb_node n WHERE n.node_id = ns.node_id AND n.is_removed is false AND n.platform_id IS NOT NULL);

  RETURN QUERY
  SELECT v_all_count AS all_count
        ,v_connected_count AS connected_count
;

END;
$$;


