-- Name: sp_get_release_package_os(text[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_release_package_os(i_platform_name text[]) RETURNS TABLE(platform_id public.en_platform_id_type)
    LANGUAGE plpgsql
    AS $$
BEGIN

  RETURN QUERY
    SELECT tp.platform_id
    FROM (
      SELECT * FROM unnest(i_platform_name)
    ) AS t(i)
    JOIN tb_platform tp ON tp.name ILIKE i || '%'
    WHERE tp.is_supported IS TRUE;

END;
$$;


