--
-- Name: sp_get_report_clean(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_report_clean() RETURNS TABLE(report_clean_interval text, schedule text, db_mgmt_time text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_interval                  text := '';
  v_schedule                  text := '';
  v_db_mgmt_time              text := '';
BEGIN

  v_interval := sp_get_config_group( 'REPORT_CLEAN', 'report_clean_interval' );

  SELECT s.schedule INTO v_schedule FROM tb_schedule AS s WHERE s.schedule_code = 'REPORT_CLEAN' AND s.schedule_code_index = 1;
  SELECT MAX(d.mgmt_time) INTO v_db_mgmt_time FROM tb_db_mgmt AS d WHERE d.db_mgmt_type = 'REPORT_CLEAN';

  RETURN QUERY
    SELECT v_interval, v_schedule, v_db_mgmt_time;

END;
$$;


