--
-- Name: sp_get_report_period_date_list(public.en_schedule_period_type, timestamp without time zone, timestamp without time zone, public.en_base_report_id_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_report_period_date_list(i_period_type public.en_schedule_period_type, i_period_start timestamp without time zone, i_period_end timestamp without time zone, i_base_report_id public.en_base_report_id_type) RETURNS TABLE(gap_count integer, date_array text[], trunc_text text, dateformat text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_date_array                text[];
  v_gap_count                INTEGER := 0;
  v_trunc_text                text := 'DAY';
  v_dateformat		      text := 'YYYY-MM-DD';
BEGIN
  IF i_period_type = 'YEARLY' THEN
    SELECT ARRAY_AGG(dtl.date)::text[] INTO v_date_array
      FROM (SELECT DATE(GENERATE_SERIES(i_period_start, i_period_end,'1 MONTH'))) dtl;
    v_trunc_text := 'MONTH';
  ELSIF i_period_type = 'MONTHLY' THEN
    IF i_base_report_id = 'AGENT_INSTALL_HISTORY' OR i_base_report_id = 'V3_INSTALL_HISTORY'
     OR i_base_report_id = 'MALWARE_DETECT_HISTORY' OR i_base_report_id = 'HIPS_DETECT_HISTORY'
     OR i_base_report_id = 'HIPS_FW_HISTORY' OR i_base_report_id = 'AC_BLOCK_HISTORY'
     OR i_base_report_id = 'MALWARE_NAME_TOP'
	 OR i_base_report_id = 'IM_HISTORY' THEN
        WITH date_series AS (
        SELECT DATE(GENERATE_SERIES(date_trunc('MONTH', current_date) + interval '-1 MONTH', date_trunc('MONTH', current_date) + interval '-1 DAY','1 DAY')) AS date
        )
        SELECT ARRAY_AGG(ds.date)::text[] INTO v_date_array
            FROM date_series ds;
        v_trunc_text := 'DAY';
    ELSE
        WITH date_series AS (
        SELECT DATE(GENERATE_SERIES(date_trunc('MONTH', current_date) + interval '-1 MONTH', date_trunc('MONTH', current_date) + interval '-1 DAY','1 DAY')) AS date
        )
        SELECT ARRAY_AGG(dtl.date)::text[] INTO v_date_array
		FROM(SELECT ds.date, extract(isodow from ds.date) as dotw
			FROM date_series ds) dtl
		WHERE dtl.dotw = 1;
        IF v_date_array[1]::date > i_period_start::date THEN
            v_date_array = array_prepend(((v_date_array[1]::date + interval '-1 WEEK')::date)::text, v_date_array);
        END IF;
        IF extract(isodow from i_period_end) = 7 THEN
            v_date_array = array_append(v_date_array, ((v_date_array[ARRAY_LENGTH(v_date_array, 1)]::date  + interval '+1 WEEK')::DATE)::text);
        END IF;
        v_gap_count := 1;
        v_trunc_text := 'WEEK';
    END IF;
  ELSIF i_period_type = 'WEEKLY' THEN
    SELECT ARRAY_AGG(dt1.date)::text[] INTO v_date_array
      FROM (SELECT DATE(GENERATE_SERIES(date_trunc('WEEK', current_date) + interval '-1 WEEK - 1 DAY', date_trunc('WEEK', current_date) + interval '-1 WEEK + 5 DAY' ,'1 DAY')) AS date) dt1;
    v_trunc_text := 'DAY';
  ELSIF i_period_type = 'LAST_24HR' THEN
    SELECT ARRAY_AGG(dt1.date) INTO v_date_array
      FROM (SELECT TO_CHAR(GENERATE_SERIES(date_trunc('HOUR', NOW()) + interval '-1 DAY + 1 HOUR', date_trunc('HOUR', NOW()),'1 HOUR'), 'YYYY-MM-DD HH24:00') AS date) dt1;
    v_trunc_text := 'HOUR';
    v_dateformat := 'YYYY-MM-DD HH24:00';
  ELSIF i_period_type = 'DAILY' THEN
    IF i_base_report_id = 'MALWARE_NAME_TOP' THEN
      SELECT ARRAY_AGG(dt1.date) INTO v_date_array
              FROM (SELECT TO_CHAR(date_trunc('DAY', current_date) + interval '-1 DAY', 'YYYY-MM-DD') AS date) dt1;
      v_trunc_text := 'HOUR';
      v_dateformat := 'YYYY-MM-DD';
    ELSE
      SELECT ARRAY_AGG(dt1.date) INTO v_date_array
              FROM (SELECT TO_CHAR(GENERATE_SERIES(date_trunc('DAY', current_date) + interval '-1 DAY', date_trunc('DAY', NOW()) + interval '-1 HOUR' ,'1 HOUR'), 'YYYY-MM-DD HH24:00') AS date) dt1;
    v_trunc_text := 'HOUR';
    v_dateformat := 'YYYY-MM-DD HH24:00';
    END IF;
  ELSIF i_period_type = 'CUSTOM_DAILY' THEN
    SELECT ARRAY_AGG(dt1.date)::text[] INTO v_date_array
        FROM (SELECT DATE(GENERATE_SERIES(DATE_TRUNC('DAY', i_period_start), DATE_TRUNC('DAY', i_period_end),'1 DAY')) AS date) dt1;
    v_trunc_text := 'DAY';
  ELSIF i_period_type = 'CUSTOM_WEEKLY' THEN
    SELECT ARRAY_AGG(dt1.date)::text[] INTO v_date_array
      FROM (SELECT DATE(GENERATE_SERIES(DATE_TRUNC('DAY', i_period_start), DATE_TRUNC('DAY', i_period_end),'1 DAY')) AS date) dt1;
    v_trunc_text := 'DAY';
  ELSIF i_period_type = 'CUSTOM_MONTHLY' THEN
    IF i_base_report_id = 'MALWARE_NAME_TOP' THEN
      SELECT ARRAY_AGG(dt1.date)::text[] INTO v_date_array
          FROM (SELECT DATE(GENERATE_SERIES(DATE_TRUNC('DAY', i_period_start), DATE_TRUNC('DAY', i_period_end),'1 DAY')) AS date) dt1;
      v_trunc_text := 'MONTH';
    ELSE
      IF DATE_TRUNC('MONTH', i_period_start) < DATE_TRUNC('MONTH', i_period_end) THEN
          SELECT ARRAY_AGG(dtl.date)::text[] INTO v_date_array
          FROM (SELECT DATE(GENERATE_SERIES(i_period_start, i_period_end,'1 MONTH'))) dtl;
        v_trunc_text := 'DAY';
      ELSE
    WITH date_series AS (
      SELECT DATE(GENERATE_SERIES(i_period_start, i_period_end,'1 DAY')) AS date
        )
        SELECT ARRAY_AGG(dtl.date)::text[] INTO v_date_array
          FROM(SELECT ds.date, extract(isodow from ds.date) as dotw
          FROM date_series ds) dtl
        WHERE dtl.dotw = 1;
        IF v_date_array[1]::date > i_period_start::date THEN
          v_date_array = array_prepend(((v_date_array[1]::date + interval '-1 WEEK')::date)::text, v_date_array);
        END IF;
        IF extract(isodow from i_period_end) = 7 THEN
          v_date_array = array_append(v_date_array, ((v_date_array[ARRAY_LENGTH(v_date_array, 1)]::date  + interval '+1 WEEK')::DATE)::text);
        END IF;
        v_gap_count := 1;
        v_trunc_text := 'WEEK';
      END IF;
    END IF;
  ELSIF i_period_type = 'CUSTOM_YEARLY' THEN
    SELECT ARRAY_AGG(dtl.date)::text[] INTO v_date_array
      FROM (SELECT DATE(GENERATE_SERIES(i_period_start, i_period_end,'1 MONTH'))) dtl;
    v_trunc_text := 'MONTH';
  ELSE
    SELECT ARRAY_AGG(dt1.date)::text[] INTO v_date_array
      FROM (SELECT DATE(GENERATE_SERIES(i_period_start, i_period_end,'1 DAY')) AS date) dt1;
  END IF;

  RETURN QUERY
  SELECT v_gap_count, v_date_array, v_trunc_text, v_dateformat;

END;
$$;


