--
-- Name: sp_get_report_schedule(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_report_schedule(i_report_schedule_id bigint) RETURNS TABLE(report_schedule_id text, schedule text, tenant_server bigint, now_time text)
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_tenant_server			BIGINT;
	v_now_time				TEXT;
BEGIN

	IF (i_report_schedule_id = 0) then
        RETURN QUERY
            SELECT
                rp.report_schedule_id ::text
                , rp.schedule
                , v_tenant_server
                , v_now_time
            FROM tb_report_schedule rp
            WHERE rp.report_type <> 'CORRELATION'
     		AND rp.is_removed = FALSE
            ORDER BY rp.report_schedule_id;
    ELSE
		SELECT
			tenant.tenant_server
			, to_char(now(), 'YYYYMMDDHH24MI') AS now_time
			INTO v_tenant_server, v_now_time
		FROM (
			SELECT
				tst.tenant_server, count(*) AS cnt
			FROM tb_schedule_trigger tst GROUP BY tst.tenant_server
		)tenant ORDER BY tenant.cnt LIMIT 1
		;

        RETURN QUERY
            SELECT
                rp.report_schedule_id ::text
                , rp.schedule
                , v_tenant_server
                , v_now_time
            FROM tb_report_schedule rp
            WHERE rp.report_schedule_id = i_report_schedule_id
            AND rp.report_type <> 'CORRELATION'
     		AND rp.is_removed = FALSE;
    END IF;

END;
$$;


ALTER FUNCTION public.sp_get_report_schedule(i_report_schedule_id bigint) OWNER TO cppoltp;

--
-- Name: sp_get_report_schedule_data(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_report_schedule_data() RETURNS TABLE(report_schedule_id text, report_type text, base_report_id text, query_report_id text, admin_id text, params text, schedule text, mail_alarm text, modified_time text, target text, target_name text, correlation_rule_id text, name text, description text, period_type text, period_start text, period_end text, schedule_type text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT rs.report_schedule_id::text, rs.report_type::text, COALESCE(rs.base_report_id::text, ''), COALESCE(rs.query_report_id::text, ''), rs.admin_id, COALESCE(rs.params, ''),
      rs.schedule, rs.mail_alarm::text, rs.modified_time::text,
      COALESCE(rs.target, ''),
      COALESCE((SELECT tg.name AS target_name FROM tb_group tg WHERE tg.group_id = COALESCE(rs.target::BIGINT, 0)), ''),
      COALESCE(rs.correlation_rule_id::text, ''), rs.name, rs.description,
      rs.period_type::text, rs.period_start::text, rs.period_end::text, rs.schedule_type::text
    FROM tb_report_schedule rs
    WHERE rs.is_removed = false;

END;
$$;


