--
-- Name: sp_get_report_schedule_data_info(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_report_schedule_data_info(i_report_schedule_id bigint) RETURNS TABLE(report_schedule_id text, report_type text, base_report_id text, query_report_id text, admin_id text, admin_group text, params text, schedule text, mail_alarm text, modified_time text, target text, target_name text, correlation_rule_id text, name text, description text, period_type text, period_start text, period_end text, schedule_type text, version text, user_mail text, email text, is_admin_mail text, is_user_mail text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT rs.report_schedule_id::text, rs.report_type::text, COALESCE(rs.base_report_id::text, ''), COALESCE(rs.query_report_id::text, ''), rs.admin_id, a.admin_group, COALESCE(rs.params, ''),
      rs.schedule, rs.mail_alarm::text, rs.modified_time::text,
      COALESCE(rs.target, ''),
      COALESCE((SELECT tg.name AS target_name FROM tb_group tg WHERE tg.group_id::text = COALESCE(rs.target, '0')), ''),
      COALESCE(rs.correlation_rule_id::text, ''), rs.name, rs.description,
      rs.period_type::text, rs.period_start::text, rs.period_end::text, rs.schedule_type::text,
      COALESCE((SELECT MAX(b.version) FROM tb_base_report_status b WHERE b.base_report_id = rs.base_report_id), '1')::text,
      rs.user_mail::text, a.email::text, rs.is_admin_mail::text, rs.is_user_mail::text
    FROM tb_report_schedule AS rs
    LEFT JOIN tb_admin AS a ON rs.admin_id = a.admin_id
    WHERE rs.report_schedule_id = i_report_schedule_id
      AND rs.is_removed = false;


END;
$$;


