--
-- Name: sp_get_report_schedule_detail(text, bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_report_schedule_detail(i_login_admin_id text, i_report_schedule_id bigint) RETURNS TABLE(report_schedule_id bigint, name text, description text, report_type public.en_report_type, base_report_id public.en_base_report_id_type, query_report_id bigint, admin_id text, period_type public.en_schedule_period_type, period_start timestamp without time zone, period_end timestamp without time zone, params text, target text, correlation_rule_id bigint, schedule text, mail_alarm boolean, modified_time timestamp without time zone, schedule_type public.en_schedule_type)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_profile_type              en_privilege_profile_type;
BEGIN

  -- login_admin_id 의 권한 가져오기
  SELECT p.profile_type INTO v_profile_type
  FROM tb_admin AS a
  INNER JOIN tb_privilege_profile AS p ON a.privilege_profile_id = p.privilege_profile_id
  WHERE a.admin_id = i_login_admin_id;

  -- 권한 체크
  IF v_profile_type <> 'ROOT_ADMIN' THEN
    IF (SELECT EXISTS (SELECT 1 FROM tb_report_schedule AS r WHERE r.report_schedule_id = i_report_schedule_id AND r.admin_id <> i_login_admin_id)) = true THEN
      RAISE EXCEPTION 'You do not have permission.(%)', i_query_report_id USING HINT = 'DB-00022';
    END IF;
  END IF;

  RETURN QUERY
    SELECT
        r.report_schedule_id
      , r.name
      , r.description
      , r.report_type
      , r.base_report_id
      , r.query_report_id
      , r.admin_id
      , r.period_type
      , r.period_start
      , r.period_end
      , r.params
      , r.target
      , r.correlation_rule_id
      , r.schedule
      , r.mail_alarm
      , r.modified_time
      , r.schedule_type
    FROM tb_report_schedule AS r
    WHERE r.report_schedule_id = i_report_schedule_id
      AND r.admin_id = CASE WHEN v_profile_type = 'ROOT_ADMIN' THEN r.admin_id ELSE i_login_admin_id END
      AND r.report_type <> 'CORRELATION'
      AND r.is_removed = FALSE;

END;
$$;


ALTER FUNCTION public.sp_get_report_schedule_detail(i_login_admin_id text, i_report_schedule_id bigint) OWNER TO cppoltp;

