--
-- Name: sp_get_report_schedule_id_array(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_report_schedule_id_array(i_login_admin_id text) RETURNS TABLE(report_schedule_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_profile_type              en_privilege_profile_type;
BEGIN

  -- login_admin_id 의 권한 가져오기
  SELECT p.profile_type INTO v_profile_type
  FROM tb_admin AS a
  JOIN tb_privilege_profile AS p ON a.privilege_profile_id = p.privilege_profile_id
  WHERE a.admin_id = i_login_admin_id;


  IF v_profile_type = 'ROOT_ADMIN' THEN
    RETURN QUERY
      SELECT STRING_AGG(DISTINCT '"' || rs.report_schedule_id::text || '"', ',')
      FROM tb_report_schedule AS rs
      LEFT JOIN tb_query_report AS q ON rs.query_report_id = q.query_report_id;
  ELSE
    RETURN QUERY
      SELECT STRING_AGG(DISTINCT '"' || rs.report_schedule_id::text || '"', ',')
      FROM tb_report_schedule AS rs
      LEFT JOIN tb_query_report AS q ON rs.query_report_id = q.query_report_id
      WHERE (rs.admin_id = i_login_admin_id
              OR (rs.query_report_id IS NOT NULL AND q.admin_id = i_login_admin_id));
  END IF;

END;
$$;


ALTER FUNCTION public.sp_get_report_schedule_id_array(i_login_admin_id text) OWNER TO cppoltp;

