--
-- Name: sp_get_schedule_trigger_list(bigint, public.en_execute_status, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_schedule_trigger_list(i_tenant_server bigint, i_execute_status public.en_execute_status, i_reserved_tenant text, i_retry_time text) RETURNS TABLE(trigger_id bigint, trigger_time text, job_id bigint, job_type public.en_schedule_job_type, reference_value text, schedule_code_index integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
	IF i_tenant_server = 0 THEN

		UPDATE tb_schedule_trigger
		SET
			reserved_tenant = i_reserved_tenant
			, execute_status = 'PROGRESS'
			, modified_time = now()
		WHERE
		tb_schedule_trigger.trigger_id IN (
			SELECT
				st.trigger_id
			FROM tb_schedule_trigger st
			WHERE st.execute_status = i_execute_status
			AND st.created_time < now() - (i_retry_time || ' minute')::INTERVAL
			AND char_length(st.trigger_time) = 12
			LIMIT 5
		);

		RETURN QUERY
			SELECT
				st.trigger_id
				, st.trigger_time
				, st.job_id
				, st.job_type
				, st.reference_value
				, CASE WHEN st.job_type = 'UNITY_JOB' THEN
					   	sch.schedule_code_index
				       ELSE
				       	0
				  END AS schedule_code_index
			FROM tb_schedule_trigger AS st
			LEFT OUTER join tb_schedule sch ON st.job_id = sch.schedule_id
			WHERE st.reserved_tenant = i_reserved_tenant
			AND st.execute_status = 'PROGRESS'
		;
	ELSE
		UPDATE tb_schedule_trigger
		SET
			reserved_tenant = i_reserved_tenant
			, execute_status = 'PROGRESS'
			, modified_time = now()
		WHERE tenant_server = i_tenant_server
			AND execute_status = i_execute_status
			AND created_time < now()
		;

    	RETURN QUERY
			SELECT
				st.trigger_id
				, st.trigger_time
				, st.job_id
				, st.job_type
				, st.reference_value
				, CASE WHEN st.job_type = 'UNITY_JOB' THEN
					   	sch.schedule_code_index
				       ELSE
				       	0
				  END AS schedule_code_index
			FROM tb_schedule_trigger AS st
			LEFT OUTER join tb_schedule sch ON st.job_id = sch.schedule_id
			WHERE st.tenant_server = i_tenant_server
				AND st.reserved_tenant = i_reserved_tenant
				AND st.execute_status = 'PROGRESS'
		;
    END IF;
END;
$$;


ALTER FUNCTION public.sp_get_schedule_trigger_list(i_tenant_server bigint, i_execute_status public.en_execute_status, i_reserved_tenant text, i_retry_time text) OWNER TO cppoltp;

--
-- Name: sp_get_scm_agent_policy_detail(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_scm_agent_policy_detail(i_policy_id bigint) RETURNS TABLE(product_feature_id public.en_product_feature_id_type, product_feature_name text, policy_id bigint, policy_name text, description text, policy_type public.en_policy_type, online_policy_body text, offline_policy_body text, use_offline_policy text, hash text, modified_time timestamp without time zone, group_id_array bigint[])
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_product_feature_id en_product_feature_id_type;

BEGIN

SELECT p.product_feature_id
INTO v_product_feature_id
FROM tb_policy p
WHERE p.policy_id = i_policy_id;

IF v_product_feature_id IS NULL THEN

  RAISE EXCEPTION 'policy_id (%) does not exist.', i_policy_id USING HINT = 'DB-00031';

ELSIF v_product_feature_id <> 'SCM_AGENT' THEN

  RAISE EXCEPTION 'policy_id (%) is not SCM_AGENT policy.', i_policy_id USING HINT = 'DB-00030';

END IF;

RETURN QUERY

--정책 상세
SELECT p.product_feature_id AS product_feature_id
      ,p.product_feature_name AS product_feature_name
      ,p.policy_id AS policy_id
      ,p.policy_name AS policy_name
      ,p.description AS description
      ,p.policy_type AS policy_type
      ,p.online_policy_body AS online_policy_body
      ,p.offline_policy_body AS offline_policy_body
      ,p.use_offline_policy AS use_offline_policy
      ,p.hash AS hash
      ,p.modified_time AS modified_time
      ,p.group_id_array AS group_id_array
FROM sp_get_policy_detail(i_policy_id) p
;

END;
$$;


