--
-- Name: sp_get_server(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_server(i_server_id bigint) RETURNS TABLE(server_id bigint, ip text, port integer)
    LANGUAGE plpgsql
    AS $$

BEGIN

RETURN QUERY
SELECT sv.server_id AS server_id
      ,sv.ip AS ip
      ,sp.port AS port
FROM tb_server sv
JOIN tb_service svc
ON sv.server_id = svc.server_id
  AND svc.service_type = 'TOMCAT-CONSOLE'
JOIN tb_service_port sp
ON svc.service_type = sp.service_type
WHERE sv.server_id = i_server_id;

END;
$$;


