--
-- Name: sp_get_server_resource(bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_server_resource(i_server_id bigint[]) RETURNS TABLE(is_over text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT
      (COUNT(1) > 0)::TEXT
    FROM (
      SELECT
        used_hdd, avail_hdd, log_time
        , ROW_NUMBER() OVER (PARTITION BY server_id ORDER BY log_time DESC) AS row_num
      FROM
        tb_server_resource
      WHERE
        server_id = ANY(i_server_id)
        AND log_time > (now() - INTERVAL '3 days')
      ) sr
    WHERE
      sr.row_num = 1
      AND (sr.used_hdd::NUMERIC(9,1) / (sr.used_hdd::NUMERIC(9,1) + sr.avail_hdd::NUMERIC(9,1))) * 100
        >=
        (SELECT VALUE FROM tb_config WHERE config_group = 'DB_CLEAN' AND key = 'db_clean_condition')::NUMERIC(9,1)
    ;

END;
$$;


