-- Name: sp_get_server_resource_list(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_server_resource_list() RETURNS TABLE(server_id bigint, log_time timestamp without time zone, used_mem bigint, avail_mem bigint, used_cpu bigint, avail_cpu bigint, used_hdd bigint, avail_hdd bigint, hdd_partition text, used_traffic bigint, smart_info text, raid_state text, db_size bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT
      s.server_id, s.log_time
      , s.used_mem, s.avail_mem
      , s.used_cpu, s.avail_cpu
      , s.used_hdd, s.avail_hdd, s.hdd_partition
      , s.used_traffic, s.smart_info, s.raid_state
      , (s.oltp_db_size + s.log_db_size)
    FROM (
      SELECT sr.server_id, sr.log_time
            , sr.used_mem, sr.avail_mem
            , sr.used_cpu, sr.avail_cpu
            , sr.used_hdd, sr.avail_hdd, sr.hdd_partition
            , sr.used_traffic, sr.smart_info, sr.raid_state
            , sr.oltp_db_size, sr.log_db_size
            , ROW_NUMBER() OVER(PARTITION BY sr.server_id ORDER BY sr.log_time DESC) AS row_num
      FROM tb_server_resource AS sr
      WHERE sr.log_time > (now() - Interval '3 days')
    ) AS s
    WHERE s.row_num = 1;

END;
$$;


