--
-- Name: sp_get_server_service_list(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_server_service_list() RETURNS TABLE(server_id text, name text, ip text, server_key text, server_status public.en_server_status, service_type public.en_service_type, count_type public.en_service_count_type, enabled text, static text, service_status public.en_service_status)
    LANGUAGE plpgsql
    AS $_$
DECLARE
BEGIN

  RETURN QUERY
    SELECT
      s.server_id::text
      , s.name
      , s.ip
      , s.server_key
      , s.server_status
      , st.service_type
      , sp.count_type
      , COALESCE(v.enabled, false)::text
      , CASE WHEN st.service_type = 'TOMCAT-AGENT' AND v.enabled IS TRUE AND v2.fileserver_http IS TRUE AND v2.fileserver_upload IS TRUE THEN 'true' ELSE COALESCE(v.static, false)::text END
      , COALESCE(v.service_status, 'ABNORMAL')
    FROM (
      SELECT UNNEST(enum_range(null::en_service_type)) AS service_type
    ) AS st
    JOIN tb_service_port AS sp ON sp.service_type = st.service_type AND sp.param_enabled IS TRUE
    CROSS JOIN tb_server AS s
    LEFT JOIN tb_service AS v ON s.server_id = v.server_id AND st.service_type = v.service_type
    LEFT JOIN (
      SELECT *
      FROM crosstab($func$
        SELECT server_id, service_type, enabled
        FROM (
          SELECT server_id, service_type, enabled, static FROM tb_service where enabled IS TRUE
        ) t
        ORDER BY 1, 2
      $func$,
      $func$
        VALUES ('FILESERVER-HTTP'), ('FILESERVER-UPLOAD')
      $func$)
      AS ct (
        server_id bigint, fileserver_http boolean, fileserver_upload boolean
      )
    ) AS v2 ON s.server_id = v2.server_id
    ORDER BY s.server_id, st.service_type;

END;
$_$;


