--
-- Name: sp_get_server_service_port_list(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_server_service_port_list(i_server_id bigint) RETURNS TABLE(server_id text, name text, server_ip text, service_type public.en_service_type, port text, count_type public.en_service_count_type, enabled text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  --v_exclude_service_type      en_service_type[] := ARRAY['EMS5CMD', 'CLUSTER-MANAGER']::en_service_type[];
BEGIN

  RETURN QUERY
    SELECT
      s.server_id::text
      , s.name
      , COALESCE((SELECT STRING_AGG(ss.ip::text, ',' ORDER BY ss.server_id) FROM tb_server AS ss INNER JOIN tb_service AS sv ON ss.server_id = sv.server_id AND sv.enabled IS TRUE WHERE sv.service_type = v.service_type),'0.0.0.0') AS server_ip
      , v.service_type
      , sp.port::text
      , sp.count_type
      , CASE WHEN v.enabled IS TRUE THEN '1' ELSE '0' END
    FROM tb_server AS s
    INNER JOIN tb_service AS v ON s.server_id = v.server_id
    INNER JOIN tb_service_port AS sp ON v.service_type = sp.service_type
    WHERE s.server_id = i_server_id;
      --AND v.service_type NOT IN (SELECT UNNEST(v_exclude_service_type));

END;
$$;


