--
-- Name: sp_get_server_update_info(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_server_update_info() RETURNS TABLE(v_current_version text, v_patch_version text, v_repo_list text, v_server_list text, v_protocol text, v_port text, v_repo_path text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_repo_path text;
  v_repo_val text;

  v_current_version text;
  v_patch_version text;
  v_server_list TEXT;
  v_port TEXT;
  v_protocol TEXT;
  v_r RECORD;
  v_idx INT;

BEGIN
  v_server_list = '';
  v_repo_list='';


  SELECT VALUE INTO v_current_version FROM tb_config WHERE config_group = 'UPDATE' AND KEY = 'server_version';
  v_current_version = v_current_version;

  SELECT max(patch_version) INTO v_patch_version FROM tb_server WHERE server_status NOT IN ( 'ROLE_PENDING');
  v_patch_version = v_patch_version;

--  SELECT VALUE INTO v_repo_val FROM tb_config WHERE config_group = 'UPDATE' AND KEY = 'yum_repo_path';
--    v_repo_path = v_repo_val;

  SELECT VALUE INTO v_repo_val FROM tb_config WHERE config_group = 'UPDATE' AND KEY = 'yum_patch_repo';
    -- v_repo_path = v_repo_path || v_repo_val;
    v_repo_path = v_repo_val;

    SELECT port INTO v_port FROM tb_service_port WHERE service_type = 'YUM';

    v_idx = 0;
  FOR v_r IN
    SELECT ip AS idip
    FROM tb_server
    WHERE patch_version = ( SELECT max(patch_version) FROM tb_server WHERE server_status NOT IN ( 'ROLE_PENDING'))
    AND server_status NOT IN ( 'ROLE_PENDING')
  LOOP
    IF v_idx = 0 then
      v_repo_list = concat(v_repo_list, v_r.idip);
    ELSE
      v_repo_list = concat(v_repo_list,'|', v_r.idip);
    END IF;
    v_idx = v_idx + 1;

  END LOOP;

  v_idx = 0;
  FOR v_r IN
    SELECT concat( server_id, ':', ip) AS idip
    FROM tb_server WHERE  server_status NOT IN ( 'ROLE_PENDING')
  LOOP
    IF v_idx = 0 then
      v_server_list = concat( v_server_list, v_r.idip );
    ELSE
      v_server_list = concat( v_server_list, '|', v_r.idip );
    END IF;
    v_idx = v_idx + 1;

  END LOOP;
  v_protocol = 'http';

RETURN QUERY
  SELECT v_current_version, v_patch_version, v_repo_list, v_server_list, v_protocol, v_port, v_repo_path;

END;
$$;


ALTER FUNCTION public.sp_get_server_update_info() OWNER TO cppoltp;

--
-- Name: sp_get_server_update_status(public.en_server_status_check); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_server_update_status(i_server_status_check public.en_server_status_check) RETURNS TABLE(server_status text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN


  IF i_server_status_check = 'update_status_check' THEN
    RETURN QUERY SELECT
          svr_u.update_status :: TEXT
      FROM tb_server svr_u
      GROUP BY svr_u.update_status
      ;
  ELSIF i_server_status_check <> 'role_status_check' THEN
    RETURN QUERY SELECT
          svr_r.role_status :: TEXT
      FROM tb_server svr_r
      GROUP BY svr_r.role_status
      ;
  ELSIF i_server_status_check <> 'port_status_check' THEN
    RETURN QUERY SELECT
          svr_p.role_status :: TEXT
      FROM tb_server svr_p
      GROUP BY svr_p.role_status
      ;
  END IF;

END;
$$;


ALTER FUNCTION public.sp_get_server_update_status(i_server_status_check public.en_server_status_check) OWNER TO cppoltp;

