CREATE FUNCTION public.sp_get_service_server(i_server_id bigint, i_service_type public.en_service_type) RETURNS TABLE(service_type public.en_service_type, server_id text, ip text, port text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT
      v.service_type
      , s.server_id::text
      , s.ip
      , sp.port::text
    FROM tb_server AS s
    INNER JOIN tb_service AS v ON s.server_id = v.server_id
    INNER JOIN tb_service_port AS sp ON v.service_type = sp.service_type
    WHERE v.enabled IS TRUE
      AND v.server_id = i_server_id
      AND v.service_type = i_service_type;

END;
$$;


