CREATE FUNCTION public.sp_get_shard_etl() RETURNS TABLE(etl_id bigint, step integer, etl_from public.en_etl_from, etl_to public.en_etl_to, etl_method public.en_etl_method, from_collection text, etl_query text, to_table text, to_column text, pre_from_proc text, pre_to_proc text, post_from_proc text, post_to_proc text, is_shard text, from_column text)
    LANGUAGE plpgsql
    AS $$
BEGIN
RETURN QUERY
select m.etl_id, m.step, m.etl_from, m.etl_to, m.etl_method, m.from_collection, m.etl_query, m.to_table, m.to_column,
m.pre_from_proc, m.pre_to_proc, m.post_from_proc, m.post_to_proc, m.is_shard::TEXT, m.from_column
from tb_etl_map m
WHERE m.enabled = TRUE
AND m.is_shard = TRUE
order by m.step asc, m.etl_id asc;
END;
$$;


