--
-- Name: sp_get_shard_range(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_shard_range(i_shard_uuid text) RETURNS TABLE(start_id bigint, end_id bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

RETURN query
UPDATE tb_shard_map m SET shard_uuid = i_shard_uuid, shard_status = 'RUNNING', start_time = now()
WHERE (m.start_id, m.end_id) = (
SELECT t.start_id, t.end_id FROM (
SELECT * FROM (SELECT m.start_id, m.end_id, coalesce(m.start_time, '2000-01-01') start_time FROM tb_shard_map m
WHERE shard_uuid = i_shard_uuid AND shard_status = 'READY' ORDER BY start_time LIMIT 1) t
UNION ALL
SELECT * FROM (SELECT m.start_id, m.end_id, coalesce(m.start_time, '2000-01-01') start_time FROM tb_shard_map m
WHERE shard_uuid IS NULL AND shard_status = 'READY' ORDER BY start_id LIMIT 1) t
) t
ORDER BY start_time
LIMIT 1)
RETURNING m.start_id, m.end_id;

END;
$$;


ALTER FUNCTION public.sp_get_shard_range(i_shard_uuid text) OWNER TO cppoltp;

--
-- Name: sp_get_sw_link_node_list(text, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_sw_link_node_list(i_sw_name text, i_publisher text, i_version text) RETURNS TABLE(node_id bigint[])
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
    RETURN QUERY
    SELECT array_agg(DISTINCT ns.node_id)
      FROM tb_node_sw ns
    WHERE ns.sw_name = i_sw_name
      AND ns.publisher = i_publisher
      AND ns.version = i_version
      AND EXISTS (SELECT 1 FROM tb_node n WHERE n.node_id = ns.node_id AND n.is_removed is false);

END;
$$;


ALTER FUNCTION public.sp_get_sw_link_node_list(i_sw_name text, i_publisher text, i_version text) OWNER TO cppoltp;

--
-- Name: sp_get_sw_list(bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_sw_list(i_group_id_arr bigint[]) RETURNS TABLE(sw_name text, total_count bigint, install_count bigint, version text, publisher text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_total_count BIGINT;
BEGIN
    
  SELECT count(*) INTO v_total_count
    FROM tb_node n
   WHERE n.is_removed IS FALSE; 

  RETURN QUERY
    SELECT ns.sw_name
       , v_total_count
       , coalesce(COUNT(*) , 0) install_count
       , ns.version
       , ns.publisher
    FROM tb_node_sw ns
    JOIN tb_node n
      ON ns.node_id = n.node_id
   WHERE n.is_removed IS FALSE
        AND n.group_id = ANY(i_group_id_arr)
   GROUP BY ns.sw_name, ns.publisher, ns.version
   ORDER BY ns.sw_name
  ;

END;
$$;


ALTER FUNCTION public.sp_get_sw_list(i_group_id_arr bigint[]) OWNER TO cppoltp;

