--
-- Name: sp_get_syncpackage_server(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_syncpackage_server(i_server_id bigint) RETURNS TABLE(server_ip text, product_pkg_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  package_record RECORD;
  package_cursor REFCURSOR;
BEGIN

 CREATE TEMPORARY TABLE temp_package_receive_server
 (
   ip TEXT,
   product_pkg_id text
 )
 ON COMMIT DROP;

  -- Open the cursor
  -- select package send server

  OPEN package_cursor FOR
  select SEND_SERVER.product_pkg_id from
  (select tb_pkg_server.product_pkg_id, min(tb_pkg_server.server_id) server_id from
  tb_pkg_server, tb_product_pkg
  where tb_pkg_server.product_pkg_id = tb_product_pkg.product_pkg_id
  and ( tb_product_pkg.pkg_type = 'WIN_AGENT_INSTALL' or
        tb_product_pkg.pkg_type = 'PRODUCT_INSTALL' or
        tb_product_pkg.pkg_type = 'LINUX_AGENT_INSTALL' or
        tb_product_pkg.pkg_type = 'WIN_AGENT_MASTER' or
        tb_product_pkg.pkg_type = 'LINUX_AGENT_INSTALL'
       )
  and tb_product_pkg.is_removed is false
  group by tb_pkg_server.product_pkg_id
  ) as SEND_SERVER
  where SEND_SERVER.server_id = i_server_id;


  LOOP
    -- fetch row into the film
    FETCH package_cursor INTO package_record;
    -- exit when no more row to fetch
    EXIT WHEN NOT FOUND;

    -- build the output

    select tb_server.ip, package_record.product_pkg_id
    from tb_server, tb_service
    where ( tb_service.service_type = 'FILESERVER-HTTP' and tb_service.enabled = 'true' )
    and tb_service.server_id not in
    ( select tb_pkg_server.server_id from tb_pkg_server where tb_pkg_server.product_pkg_id = package_record.product_pkg_id )
    and tb_server.server_id = tb_service.server_id;

  END LOOP;

  -- Close the cursor
  CLOSE package_cursor;

  RETURN QUERY select temp_package_receive_server.ip, temp_package_receive_server.product_pkg_id from temp_package_receive_server;

END;
$$;


ALTER FUNCTION public.sp_get_syncpackage_server(i_server_id bigint) OWNER TO cppoltp;

