--
-- Name: sp_get_system_resource(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_system_resource() RETURNS TABLE(server_id bigint, used_mem bigint, avail_mem bigint, used_hdd bigint, avail_hdd bigint, used_cpu bigint, avail_cpu bigint, used_traffic bigint, log_time timestamp without time zone)
    LANGUAGE plpgsql
    AS $$

BEGIN

RETURN QUERY
--시스템 리소스
SELECT sr.server_id AS server_id
      ,sr.used_mem AS used_mem
      ,sr.avail_mem AS avail_mem
      ,sr.used_hdd AS used_hdd
      ,sr.avail_hdd AS avail_hdd
      ,sr.used_cpu AS used_cpu
      ,sr.avail_cpu AS avail_cpu
      ,sr.used_traffic AS used_traffic
      ,sr.log_time AS log_time
FROM (SELECT sr.server_id AS server_id
            ,sr.used_mem AS used_mem
            ,sr.avail_mem AS avail_mem
            ,sr.used_hdd AS used_hdd
            ,sr.avail_hdd AS avail_hdd
            ,sr.used_cpu AS used_cpu
            ,sr.avail_cpu AS avail_cpu
            ,sr.used_traffic AS used_traffic
            ,sr.log_time AS log_time
            ,RANK() OVER(PARTITION BY sr.server_id ORDER BY sr.log_time DESC) AS log_order
      FROM tb_server_resource sr
     ) sr
WHERE sr.log_order = 1
;

END;
$$;


