--

CREATE FUNCTION public.sp_get_table_clean_config() RETURNS TABLE(db_clean_condition text, schedule text, db_mgmt_time text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_condition                 text := '';
  v_schedule                  text := '';
  v_db_mgmt_time              text := '';
BEGIN

  v_condition := sp_get_config_group( 'DB_CLEAN', 'db_clean_condition' );

  SELECT s.schedule INTO v_schedule  FROM tb_schedule AS s WHERE s.schedule_code = 'DB_CLEAN' AND schedule_code_index = 1;
  SELECT MAX(d.mgmt_time) INTO v_db_mgmt_time FROM tb_db_mgmt AS d WHERE d.db_mgmt_type = 'CLEANUP';

  RETURN QUERY
    SELECT v_condition, v_schedule, v_db_mgmt_time;

END;
$$;


