--
-- Name: sp_get_table_schema(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_table_schema(i_table text) RETURNS TABLE("Table" text, "Column" text, type text, pk text, nulls text, auto text, "Default" text, comments text)
    LANGUAGE plpgsql
    AS $$
#variable_conflict use_column
BEGIN

RETURN query
SELECT "Table"::text, "Column"::text, "Type"::text, "PK"::text, "Nulls"::text, "Auto"::text, "Default"::text, "Comments"::text FROM (
SELECT t.table_name AS "Header", '' AS "Table", -1 AS "Position", '' AS "Column", '' AS "Type", '' AS "PK", '' AS "Nulls", '' AS "Auto", '' AS "Default", '' AS "Comments"
FROM information_schema.tables t
WHERE t.table_schema  = 'public'
UNION ALL
SELECT t.table_name AS "Header",  t.table_name AS "Table", -1 AS "Position", '' AS "Column", '테이블' AS "Type", '' AS "PK", '' AS "Nulls", '' AS "Auto", '' AS "Default", ( SELECT pg_catalog.obj_description(c.oid) FROM pg_catalog.pg_class c
WHERE c.oid = (SELECT t.table_name::regclass::oid) AND c.relname = t.table_name ) AS "Comments"
FROM information_schema.tables t
WHERE t.table_schema  = 'public'
UNION ALL
SELECT cols.table_name, chr(128) /*cols.table_name*/, cols.ordinal_position, cols.column_name, cols.udt_name, CASE WHEN i.pk IS NULL THEN '' else i.pk end AS PK, CASE WHEN is_nullable = 'YES' THEN '' ELSE 'NO' END AS nulls, CASE WHEN column_default LIKE 'nextval%' THEN 'YES' ELSE '' end AS auto,
CASE WHEN column_default LIKE 'nextval%' THEN '' ELSE column_default end AS DEFAULT,
( SELECT pg_catalog.col_description(c.oid, cols.ordinal_position::int) FROM pg_catalog.pg_class c
WHERE c.oid = (SELECT cols.table_name::regclass::oid) AND c.relname = cols.table_name) as column_comment
FROM information_schema.columns cols
LEFT JOIN (
SELECT c.relname table_name, a.attname column_name, 'YES'::text PK
FROM pg_index i
JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = ANY(i.indkey)
JOIN pg_class c ON a.attrelid = c.oid
WHERE i.indisprimary = TRUE AND c.relname ilike 'tb\_%'
) i ON (cols.table_name, cols.column_name) = (i.table_name, i.column_name)
WHERE cols.table_schema  = 'public'
ORDER BY 1, 2, 3, 4
) t WHERE "Header" ilike i_table;

END;
$$;


ALTER FUNCTION public.sp_get_table_schema(i_table text) OWNER TO cppoltp;

--
-- Name: sp_get_task(text, bigint, bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_task(i_login_admin_id text, i_task_id bigint, i_instance_id bigint) RETURNS TABLE(job_id text, is_schedule text, admin_id text, logical_target text, correlation_rule_id text, onoff text, task_type public.en_task_type, task_order text, modified_time text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_profile_type    en_privilege_profile_type;
BEGIN

  -- login_admin_id 의 권한 가져오기
  v_profile_type := sp_get_admin_privilege_type( i_login_admin_id );

  -- 권한 체크
  IF v_profile_type IS NULL OR v_profile_type <> 'ROOT_ADMIN' THEN
    IF (SELECT j.admin_id FROM tb_job AS j WHERE j.job_id = (SELECT t.job_id FROM tb_task AS t WHERE t.task_id = i_task_id)) <> i_login_admin_id THEN
      RAISE EXCEPTION 'You do not have permission.(%)', i_task_id USING HINT = 'DB-00022';
    END IF;
  END IF;

  RETURN QUERY
    SELECT
      j.job_id::text
      , j.is_schedule::text
      , j.admin_id
      , j.logical_target
      , j.correlation_rule_id::text
      , j.onoff::text
      , t.task_type
      , t.task_order::text
      , CASE WHEN j.is_schedule = TRUE THEN (SELECT ti.modified_time FROM tb_task_instance AS ti WHERE ti.task_id = i_task_id AND ti.instance_id = i_instance_id) ELSE t.modified_time END::text
    FROM tb_job AS j
    INNER JOIN tb_task AS t ON j.job_id = t.job_id
    WHERE t.task_id = i_task_id;

END;
$$;


