CREATE FUNCTION public.sp_get_task_generate_report_list(i_task_id bigint) RETURNS TABLE(report_schedule_id text)
    LANGUAGE plpgsql
    AS $$

BEGIN

  RETURN QUERY
  SELECT trim(pl.report_schedule_id::text, '"') AS report_schedule_id
  FROM (SELECT payload::json -> 'report_schedule_id' AS report_schedule_id
        FROM (SELECT json_array_elements(payload::json) AS payload
              FROM tb_task_target tt
              WHERE tt.task_id = i_task_id) tt) pl;

END;
$$;


