--
-- Name: sp_get_task_id(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_task_id(i_job_id bigint) RETURNS TABLE(task_id bigint, task_type public.en_task_type, task_target_type public.en_task_target_type, target_filter text, task_target_product_id text, internal_payload text)
    LANGUAGE plpgsql
    AS $$
BEGIN

  RETURN QUERY
  SELECT t.task_id AS task_id
        ,tt.task_type AS task_type
        ,tt.task_target_type AS task_target_type
        ,j.target_filter AS target_filter
        ,tt.task_target_product_id::text AS task_target_product_id
        ,t.internal_payload AS internal_payload
  FROM tb_job j
  JOIN tb_task t
  ON j.job_id = t.job_id
  JOIN tb_task_type tt
  ON t.task_type = tt.task_type
  WHERE j.job_id = i_job_id
  ORDER BY t.task_order, t.task_type ASC;

END;
$$;


