-- Name: sp_get_task_instance(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_task_instance(i_task_id bigint) RETURNS TABLE(instance_id text)
    LANGUAGE plpgsql
    AS $$

BEGIN

RETURN QUERY
SELECT instance_id AS instance_id
FROM tb_task_instance
WHERE task_id = i_task_id
ORDER BY modified_time DESC
LIMIT 1;

END;
$$;


