--
-- Name: sp_get_task_list(text, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_task_list(i_login_admin_id text, i_from_modified_time timestamp without time zone, i_to_modified_time timestamp without time zone) RETURNS TABLE(job_id bigint, task_id bigint, instance_id bigint, task_type public.en_task_type, job_type text, admin_id text, logical_target text, server_context_payload text, console_context_payload text, modified_time timestamp without time zone, is_retry text, scan_type integer, collect_mode text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_profile_type              en_privilege_profile_type;
  v_response_retry_interval   integer := 0;
BEGIN

  -- login_admin_id 의 권한 가져오기
  v_profile_type := sp_get_admin_privilege_type( i_login_admin_id );

  -- 작업재시도 기간
  BEGIN
    SELECT c.value::integer INTO v_response_retry_interval
    FROM tb_config AS c
    WHERE c.config_group = 'SYS_INFO'
      AND c.key = 'response_retry_interval';
  EXCEPTION
    WHEN OTHERS THEN
      v_response_retry_interval := 0;
  END;


  IF v_profile_type = 'ROOT_ADMIN' THEN

    RETURN QUERY
      SELECT
        j.job_id
        , t.task_id
        , ti.instance_id
        , t.task_type
        , 'SCHEDULE' AS job_type
        , j.admin_id
        , j.logical_target
        , t.server_context_payload
        , t.console_context_payload
        , ti.modified_time
        , 'false' AS is_retry
        , CASE WHEN t.task_type != 'V3_STOP_SCAN'::en_task_type THEN NULL
            ELSE (
                    SELECT CASE
                           WHEN tn.machine_type = 'CONTAINER'
                               THEN ((sp_base64_decode((sp_base64_decode(payload)::json->>'payload')::json->>'command')::json->>'body')::json->>'scantype')::integer
                           ELSE
                               btrim(xpath('//CMD_TYPE/@scantype', sp_base64_decode((sp_base64_decode(payload)::json->>'payload')::json->>'command')::xml)::text, '{}')::integer
                           END 
                    FROM
                        tb_task_target ttt
                    INNER JOIN
                        tb_node tn
                    ON
                        tn.node_id = ttt.target_id
                    WHERE
                        ttt.task_id = t.task_id
                    AND
                        tn.is_removed IS FALSE
                    LIMIT 1
                ) END AS scan_type
        , CASE WHEN t.task_type != 'COLLECT_AHNREPORT_FILE' THEN NULL
            ELSE (SELECT COALESCE((sp_base64_decode(payload)::json->>'payload')::json->>'collect_mode', 'PRODUCT') FROM tb_task_target WHERE tb_task_target.task_id = t.task_id LIMIT 1) END AS collect_mode
      FROM tb_job AS j
      JOIN tb_task AS t ON j.job_id = t.job_id AND j.visible = TRUE AND j.is_schedule = TRUE
      JOIN tb_task_type AS tt ON t.task_type = tt.task_type AND sp_exist_license(CASE WHEN tt.task_target_product_id = 'AGENT' THEN 'EMS' ELSE tt.task_target_product_id END::en_product_group_type) = TRUE
      JOIN (
        SELECT ti.task_id, ti.instance_id, ti.modified_time, ROW_NUMBER() OVER(PARTITION BY ti.task_id ORDER BY ti.instance_id DESC) AS row_num
        FROM tb_task_instance AS ti
        WHERE ti.modified_time BETWEEN i_from_modified_time AND i_to_modified_time
      ) AS ti ON t.task_id = ti.task_id AND ti.row_num = 1
      UNION ALL
      SELECT
        j.job_id
        , t.task_id
        , 0 AS instance_id
        , t.task_type
        , CASE WHEN t.task_type = 'APPLY_POLICY' THEN 'APPLY_POLICY' ELSE 'COMMAND' END AS job_type
        , j.admin_id
        , j.logical_target
        , t.server_context_payload
        , t.console_context_payload
        , t.modified_time
        , ((now() - (v_response_retry_interval || 'Days')::interval) < t.modified_time)::text AS is_retry
        , CASE WHEN t.task_type != 'V3_STOP_SCAN'::en_task_type THEN NULL
            ELSE (
                    SELECT CASE
                           WHEN tn.machine_type = 'CONTAINER'
                               THEN ((sp_base64_decode((sp_base64_decode(payload)::json->>'payload')::json->>'command')::json->>'body')::json->>'scantype')::integer
                           ELSE
                               btrim(xpath('//CMD_TYPE/@scantype', sp_base64_decode((sp_base64_decode(payload)::json->>'payload')::json->>'command')::xml)::text, '{}')::integer
                           END 
                    FROM
                        tb_task_target ttt
                    INNER JOIN
                        tb_node tn
                    ON
                        tn.node_id = ttt.target_id
                    WHERE
                        ttt.task_id = t.task_id
                    AND
                        tn.is_removed IS FALSE
                    LIMIT 1
            ) END AS scan_type
        , CASE WHEN t.task_type != 'COLLECT_AHNREPORT_FILE' THEN NULL
            ELSE (SELECT COALESCE((sp_base64_decode(payload)::json->>'payload')::json->>'collect_mode', 'PRODUCT') FROM tb_task_target WHERE tb_task_target.task_id = t.task_id LIMIT 1) END AS collect_mode
      FROM tb_job AS j
      JOIN tb_task AS t ON j.job_id = t.job_id AND j.visible = TRUE AND j.is_schedule = FALSE AND j.correlation_rule_id IS NULL
      JOIN tb_task_type AS tt ON t.task_type = tt.task_type AND sp_exist_license(CASE WHEN tt.task_target_product_id = 'AGENT' THEN 'EMS' ELSE tt.task_target_product_id END::en_product_group_type) = TRUE     
      WHERE t.modified_time BETWEEN i_from_modified_time AND i_to_modified_time
      UNION ALL
      SELECT
        j.job_id
        , t.task_id
        , 0 AS instance_id
        , t.task_type
        , 'CORRELATION' AS job_type
        , j.admin_id
        , j.logical_target
        , t.server_context_payload
        , t.console_context_payload
        , t.modified_time
        , 'false' AS is_retry
        , CASE WHEN t.task_type != 'V3_STOP_SCAN'::en_task_type THEN NULL
            ELSE (
                    SELECT CASE
                           WHEN tn.machine_type = 'CONTAINER'
                               THEN ((sp_base64_decode((sp_base64_decode(payload)::json->>'payload')::json->>'command')::json->>'body')::json->>'scantype')::integer
                           ELSE
                               btrim(xpath('//CMD_TYPE/@scantype', sp_base64_decode((sp_base64_decode(payload)::json->>'payload')::json->>'command')::xml)::text, '{}')::integer
                           END 
                    FROM
                        tb_task_target ttt
                    INNER JOIN
                        tb_node tn
                    ON
                        tn.node_id = ttt.target_id
                    WHERE
                        ttt.task_id = t.task_id
                    AND
                        tn.is_removed IS FALSE
                    LIMIT 1
                  ) END AS scan_type
        , CASE WHEN t.task_type != 'COLLECT_AHNREPORT_FILE' THEN NULL
            ELSE (SELECT COALESCE((sp_base64_decode(payload)::json->>'payload')::json->>'collect_mode', 'PRODUCT') FROM tb_task_target WHERE tb_task_target.task_id = t.task_id LIMIT 1) END AS collect_mode
      FROM (
        SELECT
          j.correlation_rule_id
          , j.job_id
          , ROW_NUMBER() OVER(PARTITION BY j.correlation_rule_id ORDER BY j.job_id DESC) AS row_num
        FROM tb_job AS j
        JOIN tb_task AS t ON t.job_id = j.job_id AND j.visible = TRUE AND j.is_schedule = FALSE AND j.correlation_rule_id IS NOT NULL
        WHERE t.modified_time BETWEEN i_from_modified_time AND i_to_modified_time
      ) AS job
      JOIN tb_job AS j ON job.job_id = j.job_id AND job.row_num = 1
      JOIN tb_task AS t ON j.job_id = t.job_id
      JOIN tb_task_type AS tt ON tt.task_type = t.task_type AND sp_exist_license(CASE WHEN tt.task_target_product_id = 'AGENT' THEN 'EMS' ELSE tt.task_target_product_id END::en_product_group_type) = TRUE AND tt.task_target_type = 'NODE'
      ;

  ELSE
    RETURN QUERY
      SELECT
        j.job_id
        , t.task_id
        , ti.instance_id
        , t.task_type
        , 'SCHEDULE' AS job_type
        , j.admin_id
        , j.logical_target
        , t.server_context_payload
        , t.console_context_payload
        , ti.modified_time
        , 'false' AS is_retry
        , CASE WHEN t.task_type != 'V3_STOP_SCAN'::en_task_type THEN NULL
            ELSE (
                    SELECT CASE
                           WHEN tn.machine_type = 'CONTAINER'
                               THEN ((sp_base64_decode((sp_base64_decode(payload)::json->>'payload')::json->>'command')::json->>'body')::json->>'scantype')::integer
                           ELSE
                               btrim(xpath('//CMD_TYPE/@scantype', sp_base64_decode((sp_base64_decode(payload)::json->>'payload')::json->>'command')::xml)::text, '{}')::integer
                           END 
                    FROM
                        tb_task_target ttt
                    INNER JOIN
                        tb_node tn
                    ON
                        tn.node_id = ttt.target_id
                    WHERE
                        ttt.task_id = t.task_id
                    AND
                        tn.is_removed IS FALSE
                    LIMIT 1
            ) END AS scan_type
        , CASE WHEN t.task_type != 'COLLECT_AHNREPORT_FILE' THEN NULL
            ELSE (SELECT COALESCE((sp_base64_decode(payload)::json->>'payload')::json->>'collect_mode', 'PRODUCT') FROM tb_task_target WHERE tb_task_target.task_id = t.task_id LIMIT 1) END AS collect_mode
      FROM tb_job AS j
      JOIN tb_task AS t ON j.job_id = t.job_id AND j.visible = TRUE AND j.is_schedule = TRUE AND j.admin_id = i_login_admin_id
      JOIN tb_task_type AS tt ON t.task_type = tt.task_type AND sp_exist_license(CASE WHEN tt.task_target_product_id = 'AGENT' THEN 'EMS' ELSE tt.task_target_product_id END::en_product_group_type) = TRUE
      JOIN (
        SELECT ti.task_id, ti.instance_id, ti.modified_time, ROW_NUMBER() OVER(PARTITION BY ti.task_id ORDER BY ti.instance_id DESC) AS row_num
        FROM tb_task_instance AS ti
        WHERE ti.modified_time BETWEEN i_from_modified_time AND i_to_modified_time
      ) AS ti ON t.task_id = ti.task_id AND ti.row_num = 1
      UNION ALL
      SELECT
        j.job_id
        , t.task_id
        , 0 AS instance_id
        , t.task_type
        , CASE WHEN t.task_type = 'APPLY_POLICY' THEN 'APPLY_POLICY' ELSE 'COMMAND' END AS job_type
        , j.admin_id
        , j.logical_target
        , t.server_context_payload
        , t.console_context_payload
        , t.modified_time
        , ((now() - (v_response_retry_interval || 'Days')::interval) < t.modified_time)::text AS is_retry
        , CASE WHEN t.task_type != 'V3_STOP_SCAN'::en_task_type THEN NULL
            ELSE (
                    SELECT CASE
                           WHEN tn.machine_type = 'CONTAINER'
                               THEN ((sp_base64_decode((sp_base64_decode(payload)::json->>'payload')::json->>'command')::json->>'body')::json->>'scantype')::integer
                           ELSE
                               btrim(xpath('//CMD_TYPE/@scantype', sp_base64_decode((sp_base64_decode(payload)::json->>'payload')::json->>'command')::xml)::text, '{}')::integer
                           END 
                    FROM
                        tb_task_target ttt
                    INNER JOIN
                        tb_node tn
                    ON
                        tn.node_id = ttt.target_id
                    WHERE
                        ttt.task_id = t.task_id
                    AND
                        tn.is_removed IS FALSE
                    LIMIT 1
            ) END AS scan_type
        , CASE WHEN t.task_type != 'COLLECT_AHNREPORT_FILE' THEN NULL
            ELSE (SELECT COALESCE((sp_base64_decode(payload)::json->>'payload')::json->>'collect_mode', 'PRODUCT') FROM tb_task_target WHERE tb_task_target.task_id = t.task_id LIMIT 1) END AS collect_mode
      FROM tb_job AS j
      JOIN tb_task AS t ON j.job_id = t.job_id AND j.visible = TRUE AND j.is_schedule = FALSE AND j.correlation_rule_id IS NULL AND j.admin_id = i_login_admin_id
      JOIN tb_task_type AS tt ON t.task_type = tt.task_type AND sp_exist_license(CASE WHEN tt.task_target_product_id = 'AGENT' THEN 'EMS' ELSE tt.task_target_product_id END::en_product_group_type) = TRUE
      WHERE t.modified_time BETWEEN i_from_modified_time AND i_to_modified_time
      UNION ALL
      SELECT
        j.job_id
        , t.task_id
        , 0 AS instance_id
        , t.task_type
        , 'CORRELATION' AS job_type
        , j.admin_id
        , j.logical_target
        , t.server_context_payload
        , t.console_context_payload
        , t.modified_time
        , 'false' AS is_retry
        , CASE WHEN t.task_type != 'V3_STOP_SCAN'::en_task_type THEN NULL
            ELSE (
                    SELECT CASE
                           WHEN tn.machine_type = 'CONTAINER'
                               THEN ((sp_base64_decode((sp_base64_decode(payload)::json->>'payload')::json->>'command')::json->>'body')::json->>'scantype')::integer
                           ELSE
                               btrim(xpath('//CMD_TYPE/@scantype', sp_base64_decode((sp_base64_decode(payload)::json->>'payload')::json->>'command')::xml)::text, '{}')::integer
                           END 
                    FROM
                        tb_task_target ttt
                    INNER JOIN
                        tb_node tn
                    ON
                        tn.node_id = ttt.target_id
                    WHERE
                        ttt.task_id = t.task_id
                    AND
                        tn.is_removed IS FALSE
                    LIMIT 1
            ) END AS scan_type
        , CASE WHEN t.task_type != 'COLLECT_AHNREPORT_FILE' THEN NULL
            ELSE (SELECT COALESCE((sp_base64_decode(payload)::json->>'payload')::json->>'collect_mode', 'PRODUCT') FROM tb_task_target WHERE tb_task_target.task_id = t.task_id LIMIT 1) END AS collect_mode
      FROM (
        SELECT
          j.correlation_rule_id
          , j.job_id
          , ROW_NUMBER() OVER(PARTITION BY j.correlation_rule_id ORDER BY j.job_id DESC) AS row_num
        FROM tb_job AS j
        JOIN tb_task AS t ON t.job_id = j.job_id AND j.visible = TRUE AND j.is_schedule = FALSE AND j.correlation_rule_id IS NOT NULL AND j.admin_id = i_login_admin_id
        JOIN tb_task_type AS tt ON tt.task_type = t.task_type AND tt.task_target_type = 'NODE'
        WHERE t.modified_time BETWEEN i_from_modified_time AND i_to_modified_time
      ) AS job
      JOIN tb_job AS j ON job.job_id = j.job_id AND job.row_num = 1
      JOIN tb_task AS t ON j.job_id = t.job_id
      JOIN tb_task_type AS tt ON tt.task_type = t.task_type AND sp_exist_license(CASE WHEN tt.task_target_product_id = 'AGENT' THEN 'EMS' ELSE tt.task_target_product_id END::en_product_group_type) = TRUE AND tt.task_target_type = 'NODE'
      ;

  END IF;

END;
$$;


