--
-- Name: sp_get_task_notification_complete(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_task_notification_complete(i_task_id bigint) RETURNS TABLE(notification_id text)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_task_target_type text;
  v_notification_id text;

BEGIN

  SELECT tt.task_target_type::text
  INTO v_task_target_type
  FROM tb_task t
  JOIN tb_task_type tt
  ON t.task_type = tt.task_type
  WHERE t.task_id = i_task_id;

  IF v_task_target_type = 'NODE' THEN

    RETURN QUERY
    SELECT n.notification_id
    FROM tb_notification_center n
    WHERE n.notification_id = i_task_id::text || '_1';

  ELSIF v_task_target_type = 'SERVER' THEN

    RETURN QUERY
    SELECT n.notification_id
    FROM tb_notification_center n
    WHERE n.notification_id LIKE i_task_id::text || '%';

  END IF;

END;
$$;


ALTER FUNCTION public.sp_get_task_notification_complete(i_task_id bigint) OWNER TO cppoltp;

--
-- Name: sp_get_task_notification_list(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_task_notification_list(i_task_id bigint) RETURNS TABLE(admin_id text, message text)
    LANGUAGE plpgsql
    AS $$

BEGIN

  RETURN QUERY
  SELECT trim(pl.admin_id::text, '"') AS admin_id
        ,trim(pl.message::text, '"') AS message
  FROM (SELECT tt.payload -> 'admin_id' AS admin_id
              ,tt.payload -> 'message' AS message
        FROM (SELECT json_array_elements(payload::json) AS payload
              FROM tb_task_target tt
              WHERE tt.task_id = i_task_id) tt) pl;

END;
$$;


