--
-- Name: sp_get_task_push_data(bigint, public.en_task_type, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_task_push_data(i_task_id bigint, i_task_type public.en_task_type, i_target_id bigint[]) RETURNS TABLE(push_data text)
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_count bigint;
  v_additional text;
  v_task_target_type en_task_target_type;
  v_ip text;
  v_payload TEXT;

BEGIN

  -- AC/HIPS 명령은 push payload에 현재는 빈 값으로 전송되도록 처리
  IF i_task_type = 'AC_CHANGING_ACTION_MODE' OR i_task_type = 'AC_INITIALIZING_WHITELIST'
      OR i_task_type = 'AC_CHANGING_INVENTORY_POLICY' OR i_task_type = 'AC_UPDATE_PRODUCT'
      OR i_task_type = 'IPS_SIGNATURE_RECOMMENDATION' OR i_task_type = 'IPS_EMERGENCY_OFF'
      OR i_task_type = 'IPS_EMERGENCY_OFF_UNLOCK' OR i_task_type = 'HIPS_UPDATE_PRODUCT'

    THEN v_payload = '{}';

  END IF;

  SELECT tt.task_target_type
  INTO v_task_target_type
  FROM tb_task_type tt
  WHERE tt.task_type = i_task_type;  

  IF i_target_id IS NULL OR array_length(i_target_id, 1) > 1 THEN
    SELECT count(t.target_id) INTO v_count FROM tb_task_target t WHERE t.task_id = i_task_id;
   
  IF v_count = 1 THEN
    IF v_task_target_type = 'NODE' THEN
      SELECT
        '' AS computer_name
        , host(n.ip)::text
      INTO v_additional
          , v_ip
      FROM tb_node n
      WHERE n.node_id = (SELECT t.target_id
                         FROM tb_task_target t
                         WHERE t.task_id = i_task_id);
    ELSE
      SELECT s.ip
      INTO v_ip
      FROM tb_server s
      WHERE s.server_id = (SELECT t.target_id
                           FROM tb_task_target t
                           WHERE t.task_id = i_task_id);
    END IF;
  END IF;
  ELSE
    IF v_task_target_type = 'NODE' THEN
      SELECT
        '' AS computer_name
        , host(n.ip)::text
      INTO v_additional, v_ip
      FROM tb_node n
      WHERE n.node_id = i_target_id[1];
    ELSE
      SELECT s.ip
      INTO v_ip
      FROM tb_server s
      WHERE s.server_id = i_target_id[1];
    END IF;
  END IF;

  RETURN QUERY
      SELECT CASE WHEN i_task_type = 'DUPLICATED_TASK'::en_task_type OR i_task_type = 'DUPLICATED_TASK_LIST'::en_task_type THEN
      (SELECT REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE((SELECT ty.push_format FROM tb_task_type ty where task_type= i_task_type),
                '@task_id@', t.task_id::text),
                '@task_type@', (SELECT ty.task_type FROM tb_task_type ty where task_type= i_task_type)::text),
                '@ip@', COALESCE(v_ip, '')),
                '@additional@', COALESCE(v_additional, '')),
                '@payload@', CASE WHEN v_payload IS NOT NULL THEN v_payload
                                  WHEN COALESCE(t.logical_payload, '') = '' THEN '{}'
                                  ELSE REPLACE(t.logical_payload, '%', '') END),
                '@server_context_payload@', COALESCE(t.server_context_payload::text, '')),
                '@console_context_payload@', COALESCE(t.console_context_payload::text, ''))
            AS push_data
      FROM tb_task t
      WHERE t.task_id = i_task_id)
      ELSE
      (SELECT REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(ty.push_format,
                '@task_id@', t.task_id::text),
                '@task_type@', t.task_type::text),
                '@ip@', COALESCE(v_ip, '')),
                '@additional@', COALESCE(
                                          CASE WHEN t.task_type = 'V3_STOP_SCAN'::en_task_type THEN (
                                                                                                      SELECT
                                                                                                          CASE
                                                                                                              WHEN tn.machine_type = 'CONTAINER'
                                                                                                                  THEN (sp_base64_decode((sp_base64_decode(payload)::json->>'payload')::json->>'command')::json->>'body')::json->>'scantype'
                                                                                                              ELSE
                                                                                                                  btrim(xpath('//CMD_TYPE/@scantype', sp_base64_decode((sp_base64_decode(payload)::json->>'payload')::json->>'command')::xml)::text, '{}')::TEXT
                                                                                                              END
                                                                                                      FROM
                                                                                                          tb_task_target ttt
                                                                                                      INNER JOIN
                                                                                                          tb_node tn
                                                                                                      ON
                                                                                                          tn.node_id = ttt.target_id
                                                                                                      WHERE
                                                                                                          ttt.task_id = t.task_id
                                                                                                      AND
                                                                                                          tn.is_removed IS FALSE
                                                                                                      LIMIT 1
                                                                                                    )
                                          ELSE v_additional 
                                          END
                                         , '')),
                '@payload@', CASE WHEN v_payload IS NOT NULL THEN v_payload
                                  WHEN COALESCE(t.logical_payload, '') = '' THEN '{}'
                                  ELSE REPLACE(t.logical_payload, '%', '') END),
                '@server_context_payload@', COALESCE(t.server_context_payload::text, '')),
                '@console_context_payload@', COALESCE(t.console_context_payload::text, '""'))
            AS push_data
      FROM tb_task t
      JOIN tb_task_type ty
      ON t.task_type = ty.task_type
      WHERE t.task_id = i_task_id)
      END AS push_data;

  END;
$$;


