CREATE FUNCTION public.sp_get_task_schedule(i_job_id bigint) RETURNS TABLE(job_id bigint, schedule_detail text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
  SELECT
    sch.job_id
    , sch.schedule_detail
  FROM tb_job as sch
  WHERE sch.onoff = true
  AND sch.is_schedule = true
  AND sch.job_id = i_job_id
  ;

END;
$$;


