--
-- Name: sp_get_task_schedule_detail(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_task_schedule_detail(i_task_id bigint) RETURNS TABLE(task_id bigint, job_id bigint, task_type public.en_task_type, logical_payload text, internal_payload text, product_group public.en_product_group_type, create_time timestamp without time zone, modified_time timestamp without time zone, schedule_detail text, logical_target text, target_filter text, server_context text, console_context text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_task_target_product_id en_product_group_type;
  v_logical_payload text;
  v_product_group en_product_group_type;
BEGIN

  SELECT
    task.logical_payload
    , task_type.task_target_product_id
    INTO v_logical_payload, v_task_target_product_id
  FROM
    tb_task task
    INNER JOIN tb_task_type task_type ON task_type.task_type = task.task_type
  WHERE
    task.task_id = i_task_id;

  -- AC/HIPS 명령이 아닌 경우(기존 로직)
  IF v_task_target_product_id !=  'AC' AND v_task_target_product_id != 'HIPS' THEN
    CASE WHEN  (COALESCE(v_logical_payload, '')='') OR (COALESCE((v_logical_payload::json ->> 'product_feature_id'), '')='')
      THEN v_product_group := null;
      ELSE
        SELECT
          p.product_group INTO v_product_group
        FROM
          tb_product p
        WHERE
          p.product_id = (SELECT
                            product_id
                          FROM
                            tb_product_feature_map pfm
                          WHERE
                            pfm.product_feature_id = (v_logical_payload::json ->> 'product_feature_id')::en_product_feature_id_type
                          LIMIT 1
                        );
    END CASE;
  END IF;

  RETURN QUERY
    SELECT DISTINCT
      t.task_id
      , t.job_id
      , t.task_type
      , t.logical_payload
      , t.internal_payload
      , CASE WHEN v_task_target_product_id = 'AC' OR v_task_target_product_id = 'HIPS'
            THEN
              v_task_target_product_id
            ELSE
              v_product_group END AS product_group
      , t.create_time
      , t.modified_time
      , j.schedule_detail
      , j.logical_target
      , j.target_filter
      , t.server_context_payload server_context
      , t.console_context_payload
    FROM
      tb_task t
      JOIN tb_job j USING(job_id)
    WHERE
      t.task_id = i_task_id;

END;
$$;


ALTER FUNCTION public.sp_get_task_schedule_detail(i_task_id bigint) OWNER TO cppoltp;

--
-- Name: sp_get_task_schedule_list(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_task_schedule_list(i_admin_id text) RETURNS TABLE(task_id bigint, task_type public.en_task_type, job_id bigint, is_schedule boolean, schedule_detail text, logical_target text, modified_time timestamp without time zone, target_filter text, task_status text)
    LANGUAGE plpgsql
    AS $$

DECLARE
v_is_rootadmin BOOL;
BEGIN

-- ROOT_ADMIN 인 경우 전체 조회
SELECT COALESCE((SELECT profile_type = 'ROOT_ADMIN'
                   FROM tb_admin a
                  INNER JOIN tb_privilege_profile pp on a.privilege_profile_id = pp.privilege_profile_id
                  WHERE admin_id = i_admin_id
                 ), FALSE)
  INTO v_is_rootadmin
 ;

  RETURN QUERY
    WITH w_task_list AS (
      SELECT t.task_id,
             t.task_type,
         ( SELECT MAX(ti.modified_time) FROM tb_task_instance ti WHERE ti.task_id = t.task_id ) AS modified_time,
             j.job_id,
             j.is_schedule,
             j.schedule_detail,
             j.logical_target,
             ( SELECT MAX(ti.instance_id) FROM tb_task_instance ti WHERE ti.task_id = t.task_id ) AS instance_id,
             j.create_time,
             j.target_filter
        FROM tb_task t
        JOIN tb_job j USING (job_id)
       WHERE j.is_schedule = true
         AND j.visible = true
      AND j.admin_id = CASE WHEN v_is_rootadmin = TRUE THEN j.admin_id ELSE i_admin_id END
      AND j.schedule_detail != ''
      AND j.schedule_detail is not null
       --AND j.onoff = true
    )
    ,w_task_status_list AS (
      SELECT t.*,
             item_limit_moment IS NOT NULL AND now() > limit_date
             OR item_limit_moment IS NULL AND now() > basic_date
             AS is_complete
      FROM (
        SELECT t.task_id,
               (j.schedule_detail::json->'basic_moment')::json  AS item_basic_moment,
               (j.schedule_detail::json->'limit_moment')::json  AS item_limit_moment,
               to_timestamp(
                   lpad( COALESCE(j.schedule_detail::json->'basic_moment'->>'year', '')::text ,4 ,'0' )
                 ||lpad( COALESCE(j.schedule_detail::json->'basic_moment'->>'month', '')::text ,2 ,'0' )
                 ||lpad( COALESCE(j.schedule_detail::json->'basic_moment'->>'day', '')::text ,2 ,'0' )
                 ||lpad( COALESCE(j.schedule_detail::json->'basic_moment'->>'hour', '')::text ,2 ,'0' )
                 ||lpad( COALESCE(j.schedule_detail::json->'basic_moment'->>'minute', '')::text ,2 ,'0' )
                 ,'YYYYMMDDHH24MI'
               )                                               AS basic_date,
               to_timestamp(
                   lpad( COALESCE(j.schedule_detail::json->'limit_moment'->>'year', '')::text ,4 ,'0' )
                 ||lpad( COALESCE(j.schedule_detail::json->'limit_moment'->>'month', '')::text ,2 ,'0' )
                 ||lpad( COALESCE(j.schedule_detail::json->'limit_moment'->>'day', '')::text ,2 ,'0' )
                 ||lpad( COALESCE(j.schedule_detail::json->'limit_moment'->>'hour', '')::text ,2 ,'0' )
                 ||lpad( COALESCE(j.schedule_detail::json->'limit_moment'->>'minute', '')::text ,2 ,'0' )
                 ,'YYYYMMDDHH24MI'
               )                                               AS limit_date,
               extract( 'year' from now() )                    AS now_year
          FROM tb_task t
          JOIN tb_job j USING (job_id)
         WHERE j.is_schedule = true
           AND j.visible = true
      AND j.admin_id = CASE WHEN v_is_rootadmin = TRUE THEN j.admin_id ELSE i_admin_id END
      AND j.schedule_detail != ''
      AND j.schedule_detail is not null
         --AND j.onoff = true
      ) t
    )

    SELECT wt.task_id,
           wt.task_type,
           wt.job_id,
           wt.is_schedule,
           wt.schedule_detail,
           wt.logical_target,
           wt.modified_time,
           wt.target_filter,
           CASE WHEN wt.instance_id IS NOT NULL AND ws.is_complete = TRUE THEN 'COMPLETE'
                ELSE 'WAIT'
            END AS task_status
      from w_task_list        AS wt
      JOIN w_task_status_list AS ws USING (task_id)
      --,(select 1 from generate_series(1, 99)) a  ;
     ORDER BY coalesce(wt.modified_time, wt.create_time) desc
    ;

END;
$$;


