--
-- Name: sp_get_task_target(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_task_target(i_task_id bigint) RETURNS TABLE(task_id bigint, task_type public.en_task_type, task_target_type public.en_task_target_type, push_data text, target_id text)
    LANGUAGE plpgsql
    AS $$
BEGIN

  RETURN QUERY
  SELECT t.task_id AS task_id
        ,t.task_type AS task_type
        ,ty.task_target_type AS task_target_type
        ,t.push_data AS push_data
        ,array_agg(tt.target_id::bigint)::text AS target_id
  FROM tb_task t
  LEFT JOIN tb_task_target tt
  ON t.task_id = tt.task_id
  JOIN tb_task_type ty
  ON t.task_type = ty.task_type
  WHERE t.task_id = i_task_id
  GROUP BY t.task_id
          ,t.task_type
          ,ty.task_target_type
  ORDER BY t.task_order, t.task_type asc;
  END;
$$;


