--
-- Name: sp_get_task_target_agent_list(bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_task_target_agent_list(i_target_id bigint[]) RETURNS TABLE(target_id text, is_removed text, computer_name text, name text, department text, phone text, email text, empno text, description text, ip inet)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT
      t.target_id::text
      , n.is_removed::text
      , n.computer_name
      , u.name
      , u.department
      , u.phone
      , u.email
      , u.empno
      , u.description
      , n.ip
    FROM UNNEST(i_target_id) AS t(target_id)
    LEFT JOIN tb_node AS n ON t.target_id = n.node_id
    LEFT JOIN tb_user AS u ON t.target_id = u.node_id
    ORDER BY 1;

END;
$$;


