-- Name: sp_get_task_target_product_id(bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_task_target_product_id(i_target_id bigint[]) RETURNS TABLE(target_id text, product_id text)
    LANGUAGE plpgsql
    AS $$
BEGIN

  RETURN QUERY
  SELECT array_agg(pi.node_id)::text
        ,array_agg(pi.product_id)::text
  FROM tb_product_info pi
  JOIN tb_product p
  ON pi.product_id = p.product_id
    AND p.product_group= 'V3'
  WHERE pi.node_id = ANY(i_target_id);

END;
$$;


