-- Name: sp_get_task_target_status_fail_list(bigint[], bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_task_target_status_fail_list(i_task_id bigint[], i_instance_id bigint[]) RETURNS TABLE(task_id text, instance_id text, task_target_type public.en_task_target_type, target_id text, task_error text, client_time text, tz_offset text, server_time text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_task_status   en_task_status := 'FAIL';
BEGIN

  RETURN QUERY
    SELECT
      ts.task_id::text
      , ts.instance_id::text
      , ts.task_target_type
      , ts.target_id::text
      , ts.task_error
      , TO_CHAR(ts.client_time, 'YYYY-MM-DD HH24:MI:SS')
      , ts.tz_offset::text
      , TO_CHAR(ts.server_time, 'YYYY-MM-DD HH24:MI:SS')
    FROM tb_task_target_status AS ts
    WHERE (ts.task_id, ts.instance_id) IN (SELECT t.task_id, t.instance_id FROM UNNEST(i_task_id, i_instance_id) AS t(task_id, instance_id))
      AND ts.task_status = v_task_status
    ORDER BY ts.task_id;

END;
$$;


