--
-- Name: sp_get_task_target_status_list(bigint, bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_task_target_status_list(i_task_id bigint, i_instance_id bigint) RETURNS TABLE(task_target_type public.en_task_target_type, target_id text, task_status public.en_task_status, task_error text, client_time timestamp with time zone, tz_offset text, server_time timestamp with time zone, connection_status public.en_connection_status, scan_type integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT
      t.task_target_type
      , t.target_id::text
      , CASE WHEN t.task_type = 'SCM_CHECK' OR t.task_type = 'SCM_CHECK_CANCEL' THEN 
          CASE WHEN t.task_status = 'APPLY_START' THEN 'PASS_SUCCESS'
                WHEN t.task_status = 'APPLY_SUCCESS' THEN 'TASK_SUCCESS'
                WHEN t.task_status = 'APPLY_FAIL' THEN 'TASK_FAIL'
                ELSE t.task_status END
        ELSE t.task_status END AS task_status
      , t.task_error
      , t.client_time
      , t.tz_offset::text
      , t.server_time
      , COALESCE(ns.connection_status, 'DISCONNECTED'::en_connection_status) AS connection_status
      , CASE WHEN t.task_type != 'V3_STOP_SCAN'::en_task_type THEN NULL
        ELSE (
                SELECT CASE
                       WHEN tn.machine_type = 'CONTAINER'
                          THEN ((sp_base64_decode((sp_base64_decode(payload)::json->>'payload')::json->>'command')::json->>'body')::json->>'scantype')::integer
                       ELSE
                          btrim(xpath('//CMD_TYPE/@scantype', sp_base64_decode((sp_base64_decode(payload)::json->>'payload')::json->>'command')::xml)::text, '{}')::integer
                       END 
                FROM
                    tb_task_target ttt
                INNER JOIN
                    tb_node tn
                ON
                    tn.node_id = ttt.target_id
                WHERE
                    ttt.task_id = t.task_id
                AND
                    tn.is_removed IS FALSE
                LIMIT 1
              ) END AS scan_type
    FROM tb_task_target_status AS t
    LEFT JOIN tb_node_status AS ns ON t.target_id = ns.node_id 
    WHERE t.task_id = i_task_id
      AND t.instance_id = i_instance_id;

END;
$$;


ALTER FUNCTION public.sp_get_task_target_status_list(i_task_id bigint, i_instance_id bigint) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_task_target_status_list(i_task_id bigint, i_instance_id bigint); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_task_target_status_list(i_task_id bigint, i_instance_id bigint) IS '
@brief [SWK-SCI1012] 실행된 Task Status 목록 가져오기
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_task_target_status_summary_list(bigint[], bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_task_target_status_summary_list(i_task_id bigint[], i_instance_id bigint[]) RETURNS TABLE(task_id bigint, instance_id bigint, task_status text, task_endtime timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  IF ARRAY_LENGTH(i_task_id, 1) <> ARRAY_LENGTH(i_instance_id, 1) THEN
    RAISE EXCEPTION 'The length of the array is unequal.' USING HINT = 'DB-00020';
  END IF;

  RETURN QUERY
    SELECT
      "result".task_id as task_id
      , "result".instance_id as instance_id
      , CASE 
          -- 완료(중복)
          WHEN "result".duplicated_count > 0
            THEN 'DUPLICATED_TASK'  
          -- 미지원
          WHEN "result".unsupported_count > 0 AND "result".success_count = 0 AND "result".ing_count = 0 AND "result".fail_count = 0
            THEN 'UNSUPPORTED'  
          -- 진행중
          WHEN "result".ing_count > 0 
            THEN (ARRAY_REMOVE(ARRAY_REMOVE(ARRAY_REMOVE(ARRAY_REMOVE(ARRAY_REMOVE(ARRAY_REMOVE(ARRAY_REMOVE("result".task_status_array,'SUCCESS'),'FINISH'),'PASS_FAIL'),'FAIL'),'TASK_SUCCESS'),'TASK_FAIL'),'UNSUPPORTED'))[1]::TEXT
          -- 완료(성공)
          WHEN ("result".success_count + "result".ing_count + "result".fail_count + "result".unsupported_count) = "result".success_count
            THEN CASE WHEN "result".finish_count = "result".success_count AND "result".task_type = 'IPS_SIGNATURE_RECOMMENDATION' THEN 'FINISH' -- 시그니처 추천 명령 완료
            ELSE 'SUCCESS' END
          --완료(일부 성공)
          WHEN "result".success_count > 0 AND ("result".fail_count > 0 OR "result".unsupported_count > 0) AND  "result".ing_count = 0
            THEN 'SUCCESS_PART'
          -- 완료(실패)  
          WHEN "result".success_count = 0 AND "result".ing_count = 0 AND ("result".fail_count > 0 OR "result".unsupported_count > 0)
            THEN 'FAIL'
          --그 외 값  
          ELSE (ARRAY_REMOVE(ARRAY_REMOVE(ARRAY_REMOVE(ARRAY_REMOVE("result".task_status_array,'SUCCESS'),'FINISH'),'TASK_SUCCESS'),'TASK_FAIL'))[1]::text END AS task_status 
      , CASE WHEN "result".ing_count > 0 THEN NULL ELSE "result".server_time::timestamp END AS task_endtime
    FROM (
      SELECT
        task_target.task_id as task_id
        , task_target.instance_id as instance_id
        , task_target.task_type as task_type
        , SUM(CASE task_target.task_status WHEN 'FINISH' THEN task_count END) AS finish_count
        , SUM(CASE task_target.task_status WHEN 'SUCCESS' THEN task_count WHEN 'FINISH' THEN task_count WHEN 'TASK_SUCCESS' THEN task_count ELSE 0 END) AS success_count
        , SUM(CASE task_target.task_status WHEN 'FAIL' THEN task_count WHEN 'PASS_FAIL' THEN task_count WHEN 'APPLY_FAIL' THEN task_count WHEN 'TASK_FAIL' THEN task_count ELSE 0 END) AS fail_count
        , SUM(CASE task_target.task_status
            WHEN 'WAITING' THEN task_count
            WHEN 'PASS_SUCCESS' THEN task_count
            WHEN 'SENT' THEN task_count
            WHEN 'SENT_FAIL' THEN task_count
            WHEN 'GET' THEN task_count
            WHEN 'APPLY_START' THEN task_count  -- 시그니처 추천 명령 환경 수집 시작
            WHEN 'APPLY_SUCCESS' THEN task_count    -- 시그니처 추천 명령 환경 수집 완료
            WHEN 'SERVER_APPLY_START' THEN task_count   -- 시그니처 추천 명령 전달 시작
            ELSE 0 END) AS ing_count
        , SUM(CASE task_target.task_status WHEN 'DUPLICATED_TASK' THEN task_count ELSE 0 END) AS duplicated_count   
        , SUM(CASE task_target.task_status WHEN 'UNSUPPORTED' THEN task_count ELSE 0 END) AS unsupported_count
        , ARRAY_AGG(task_target.task_status) AS task_status_array
        , MAX(task_target.server_time) AS server_time
      FROM (
        SELECT
            list.task_id AS task_id
            , list.instance_id AS instance_id
            , target.task_type
            , CASE WHEN target.task_type = 'SCM_CHECK' OR target.task_type = 'SCM_CHECK_CANCEL' THEN 
                CASE WHEN target.task_status = 'APPLY_START' THEN 'PASS_SUCCESS'
                     WHEN target.task_status = 'APPLY_SUCCESS' THEN 'TASK_SUCCESS'
                     WHEN target.task_status = 'APPLY_FAIL' THEN 'TASK_FAIL'
                     ELSE target.task_status END
              ELSE COALESCE(target.task_status, 'SUCCESS') END AS task_status
            , COUNT(1) AS task_count
            , CASE WHEN COUNT(target) = 0 THEN (SELECT tt.modified_time FROM tb_task tt WHERE tt.task_id = list.task_id) -- [CWPP-7097] 대상이 없는 경우, 대응 완료 시간을 시작 시간과 동일하게 함.
                   ELSE MAX(target.server_time)
              END AS server_time 
          FROM (
            SELECT
              t.task_id AS task_id
              , t.instance_id AS instance_id
            FROM
              UNNEST(i_task_id, i_instance_id) AS t(task_id, instance_id)
            ) AS list
          LEFT JOIN tb_task_target_status target ON target.task_id = list.task_id AND target.instance_id = list.instance_id
          GROUP BY
            list.task_id, list.instance_id, target.task_type, target.task_status
      ) AS task_target
      GROUP BY
        task_target.task_id, task_target.instance_id, task_target.task_type
    ) AS "result";

END;
$$;


ALTER FUNCTION public.sp_get_task_target_status_summary_list(i_task_id bigint[], i_instance_id bigint[]) OWNER TO cppoltp;

