CREATE FUNCTION public.sp_get_task_type() RETURNS TABLE(task_type public.en_task_type, product_group public.en_product_group_type, task_target_type public.en_task_target_type, request_name text, interface_id text, payload_format text, task_target_product_id text, request_format_version text, request_from text, agent_task_type text, update_task_result text, is_correlation_task boolean)
    LANGUAGE plpgsql
    AS $$

BEGIN

RETURN QUERY

SELECT tt.task_type
      ,tt.product_group
      ,tt.task_target_type
      ,tt.request_name
      ,tt.interface_id
      ,tt.payload_format
      ,tt.task_target_product_id::text
      ,tt.request_format_version
      ,tt.request_from
      ,tt.agent_task_type
      ,tt.update_task_result
      ,tt.is_correlation_task
FROM tb_task_type AS tt
WHERE tt.is_correlation_task = TRUE
;

END;
$$;


