--

CREATE FUNCTION public.sp_get_task_type_product_id() RETURNS TABLE(task_type public.en_task_type, task_target_product_id text)
    LANGUAGE plpgsql
    AS $$
BEGIN

  RETURN QUERY
  SELECT DISTINCT tt.task_type
        ,CASE WHEN tt.task_target_product_id = 'AGENT' THEN tt.task_target_product_id::TEXT
              ELSE p.product_id::TEXT
         END AS task_target_product_id
  FROM tb_task_type tt
  LEFT JOIN tb_product p
  ON tt.task_target_product_id = p.product_group::TEXT
  WHERE tt.task_target_product_id <> 'EMS';

END;
$$;


