--
-- Name: sp_get_timeline(integer, public.en_timeline_target_type, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_timeline(i_period integer, i_target_type public.en_timeline_target_type, i_target text) RETURNS TABLE(item public.en_timeline_item, date date, value text)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_date date;

BEGIN

  v_date = current_date - i_period;

  RETURN QUERY
  SELECT t.item
        ,date(t.date) AS date
        ,t.value
  FROM tb_timeline_bak t
  WHERE t.target_type = i_target_type
    AND t.target = COALESCE(i_target, t.target)
    AND date(t.date) > v_date
    AND date(t.date) <= current_date;

END;
$$;


ALTER FUNCTION public.sp_get_timeline(i_period integer, i_target_type public.en_timeline_target_type, i_target text) OWNER TO cppoltp;

