--
-- Name: sp_get_unity_schedule(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_unity_schedule(i_schedule_id bigint) RETURNS TABLE(schedule_id text, schedule_code public.en_schedule_code, schedule_code_index text, schedule text, work_all text, execute_uri text, reference_value text, product_group public.en_product_group_type, tenant_server bigint, now_time text, enabled text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_tenant_server         BIGINT;
    v_now_time              TEXT;
BEGIN

    IF i_schedule_id = 0 THEN
        RETURN QUERY
            SELECT
                sch.schedule_id::text
                , sch.schedule_code
                , sch.schedule_code_index::text
                , sch.schedule
                , sch.work_all::text
                , sch.execute_uri
                , sch.reference_value
                , sch.product_group
                , v_tenant_server
                , v_now_time
                , sch.enabled :: text
            FROM tb_schedule AS sch       
            ORDER BY sch.schedule_id
            ;
    ELSE
        SELECT
            tenant.tenant_server
            , to_char(now(), 'YYYYMMDDHH24MI') AS now_time
            INTO v_tenant_server, v_now_time
        FROM (
            SELECT
                tst.tenant_server, count(*) AS cnt
            FROM tb_schedule_trigger tst GROUP BY tst.tenant_server
        )tenant ORDER BY tenant.cnt LIMIT 1
        ;

        RETURN QUERY
            SELECT
                sch.schedule_id::text
                , sch.schedule_code
                , sch.schedule_code_index::text
                , sch.schedule
                , sch.work_all::text
                , sch.execute_uri
                , sch.reference_value
                , sch.product_group
                , v_tenant_server
                , v_now_time
                , sch.enabled :: text
            FROM tb_schedule AS sch         
            WHERE sch.schedule_id = i_schedule_id
            ;
    END IF;

END;
$$;


ALTER FUNCTION public.sp_get_unity_schedule(i_schedule_id bigint) OWNER TO cppoltp;

--
-- Name: sp_get_update_pkg(character varying, public.en_pkg_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_update_pkg(i_server_ip character varying, i_pkg_type public.en_pkg_type) RETURNS TABLE(version text, path text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_server_count integer;
BEGIN
    IF( ( i_server_ip IS NULL ) or ( i_server_ip = '' ) ) THEN
      SELECT count(*) into v_server_count FROM tb_service where service_type = 'FILESERVER-HTTP' and enabled = 'true';
      --SELECT count(*) into v_server_count FROM tb_server;

      RETURN QUERY
      select max(update_pkg_table.version), ''::text from
      (
        SELECT tb_product_pkg.version, count(*) as server_count FROM tb_product_pkg, tb_pkg_server, tb_service
        WHERE tb_product_pkg.pkg_type = i_pkg_type and tb_product_pkg.product_pkg_id = tb_pkg_server.product_pkg_id
        AND tb_product_pkg.is_removed is false
        AND tb_pkg_server.server_id = tb_service.server_id AND tb_service.service_type = 'FILESERVER-HTTP' and tb_service.enabled = 'true'
        group by tb_product_pkg.version
      ) as update_pkg_table
      where server_count >= v_server_count;

    ELSE
      RETURN QUERY
      SELECT tb_product_pkg.version, tb_product_pkg.path FROM tb_product_pkg, tb_pkg_server, tb_server
      WHERE tb_product_pkg.pkg_type = i_pkg_type AND tb_product_pkg.product_pkg_id = tb_pkg_server.product_pkg_id and tb_pkg_server.server_id = tb_server.server_id AND tb_product_pkg.is_removed is false AND tb_server.ip = i_server_ip
      ORDER BY tb_product_pkg.version DESC;
    END IF;
END;
$$;


ALTER FUNCTION public.sp_get_update_pkg(i_server_ip character varying, i_pkg_type public.en_pkg_type) OWNER TO cppoltp;

--
-- Name: sp_get_update_pkg_list(public.en_pkg_type[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_update_pkg_list(i_pkg_type public.en_pkg_type[]) RETURNS TABLE(product_pkg_id text, ips text, port text, product_id text, version text, path text)
    LANGUAGE plpgsql
    AS $$

DECLARE
BEGIN
	RETURN QUERY
	SELECT
		product_pkg.product_pkg_id::text,
		server_info.ips,
		service_info.file_http_port::text,
		product_pkg.product_id::text,
		product_pkg.version,
		product_pkg.path
	FROM (SELECT
					(SELECT tsp.port FROM tb_service_port tsp
					 WHERE tsp.service_type = 'FILESERVER-HTTP') AS file_http_port) service_info,
			 (SELECT pkg.product_pkg_id AS product_pkg_id, string_agg(server.ip, ',') AS ips
			  FROM tb_pkg_server ps, tb_server server,
				     (SELECT DISTINCT ON (product_pkg.product_pkg_id)
						 		product_pkg.pkg_type,
								product_pkg.product_id,
								product_pkg.product_pkg_id,
								product_pkg.version,
								product_pkg.path
							FROM (SELECT
											tpp.product_pkg_id,
											tpp.pkg_type,
											tpp.product_id,
											tpp.version,
											tpp.path
									  FROM tb_product_pkg tpp
										WHERE tpp.is_removed is false AND tpp.pkg_type = ANY(i_pkg_type)
										ORDER BY tpp.modified_time DESC
										) product_pkg
							) pkg
				WHERE pkg.product_pkg_id = ps.product_pkg_id
					AND ps.server_id = server.server_id
					AND pkg.pkg_type = ANY(i_pkg_type)
				GROUP BY pkg.product_pkg_id
			) server_info,
			tb_product_pkg product_pkg
		WHERE server_info.product_pkg_id = product_pkg.product_pkg_id
		ORDER BY product_pkg.product_pkg_id DESC;
END;
$$;


ALTER FUNCTION public.sp_get_update_pkg_list(i_pkg_type public.en_pkg_type[]) OWNER TO cppoltp;

