--
-- Name: sp_get_upload_main_server_deploy(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_upload_main_server_deploy(i_file_size bigint) RETURNS TABLE(server_id bigint, server_ip text, is_use_upload text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_is_use_upload TEXT;
BEGIN
  IF (SELECT count(sr.server_id)
    FROM (SELECT sr.server_id AS server_id
                ,(sr.used_hdd + (i_file_size/(1024*1024)))*100/(sr.used_hdd + sr.avail_hdd) AS total_percent
                ,RANK() OVER(PARTITION BY sr.server_id ORDER BY sr.log_time DESC) AS log_order
          FROM tb_server_resource sr
         ) sr
    JOIN tb_server tsv ON sr.server_id = tsv.server_id
    JOIN tb_service tsvc ON sr.server_id = tsvc.server_id
    WHERE sr.log_order = 1
      AND tsv.server_id = 1
      AND tsvc.service_type = 'FILESERVER-UPLOAD'
        AND tsvc.enabled = TRUE
        AND sr.total_percent > 90) > 0
    THEN v_is_use_upload = 'false';
  ELSE v_is_use_upload = 'true';
  END IF;

  RETURN QUERY
    SELECT
      ts.server_id
      ,ts.ip AS server_ip
      ,v_is_use_upload
    FROM tb_server ts
    WHERE ts.server_id = 1;

END;
$$;


ALTER FUNCTION public.sp_get_upload_main_server_deploy(i_file_size bigint) OWNER TO cppoltp;

--
-- Name: sp_get_upload_server_deploy(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_upload_server_deploy(i_file_size bigint) RETURNS TABLE(server_id bigint, server_ip text, avail_hdd bigint, is_use_upload text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_is_use_upload TEXT;
BEGIN
  IF (SELECT count(sr.server_id)
    FROM (SELECT sr.server_id AS server_id
                ,(sr.used_hdd + (i_file_size/(1024*1024)))*100/(sr.used_hdd + sr.avail_hdd) AS total_percent
                ,RANK() OVER(PARTITION BY sr.server_id ORDER BY sr.log_time DESC) AS log_order
          FROM tb_server_resource sr
         ) sr
    JOIN tb_server tsv ON sr.server_id = tsv.server_id
    JOIN tb_service tsvc ON sr.server_id = tsvc.server_id
    WHERE sr.log_order = 1
      AND tsvc.service_type = 'FILESERVER-UPLOAD'
        AND tsvc.enabled = TRUE
        AND sr.total_percent > 90) > 0
    THEN v_is_use_upload = 'false';
  ELSE v_is_use_upload = 'true';
  END IF;

  RETURN QUERY
    SELECT
      sgusn.server_id
      ,sgusn.server_ip
      ,sgusn.avail_hdd
      ,v_is_use_upload
    FROM sp_get_upload_server_nomal(i_file_size) AS sgusn;

END;
$$;


ALTER FUNCTION public.sp_get_upload_server_deploy(i_file_size bigint) OWNER TO cppoltp;

--
-- Name: sp_get_upload_server_nomal(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_upload_server_nomal(i_file_size bigint) RETURNS TABLE(server_id bigint, server_ip text, avail_hdd bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

RETURN QUERY
--시스템 리소스
SELECT
  srd.server_id AS server_id
  ,srd.ip AS server_ip
  ,srd.avail_hdd AS avail_hdd
FROM (
  SELECT sr.server_id AS server_id
      ,tsv.ip
        ,sr.avail_hdd AS avail_hdd
      ,RANK() OVER(ORDER BY sr.avail_hdd DESC) AS hdd_order
      ,sr.total_percent AS total_percent
  FROM (SELECT sr.server_id AS server_id
              ,sr.used_hdd AS used_hdd
              ,sr.avail_hdd AS avail_hdd
              ,sr.log_time AS log_time
              ,(sr.used_hdd + (i_file_size/(1024*1024)))*100/(sr.used_hdd + sr.avail_hdd) AS total_percent
              ,RANK() OVER(PARTITION BY sr.server_id ORDER BY sr.log_time DESC) AS log_order
        FROM tb_server_resource sr
       ) sr
  JOIN tb_server tsv ON sr.server_id = tsv.server_id
  JOIN tb_service tsvc ON sr.server_id = tsvc.server_id
  WHERE sr.log_order = 1
    AND tsvc.service_type = 'FILESERVER-UPLOAD'
      AND tsvc.enabled = TRUE
      AND sr.total_percent < 90
) srd
WHERE srd.hdd_order = 1
;

END;
$$;


ALTER FUNCTION public.sp_get_upload_server_nomal(i_file_size bigint) OWNER TO cppoltp;

