--
-- Name: sp_get_user_table_shard_data(bigint, bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_user_table_shard_data(i_start_id bigint, i_end_id bigint) RETURNS TABLE(node_id text, name text, department text, phone text, email text, empno text, description text, modified_by_admin text, hash text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
RETURN QUERY
SELECT u.node_id::text, u.name::text, u.department::text, u.phone::text, u.email::text, u.empno::text, u.description::TEXT, u.modified_by_admin::TEXT,
md5(concat(u.node_id, u.name, u.department, u.phone, u.email, u.empno, u.description, u.modified_by_admin))
FROM tb_user u
WHERE u.node_id BETWEEN i_start_id AND i_end_id;
END;
$$;


ALTER FUNCTION public.sp_get_user_table_shard_data(i_start_id bigint, i_end_id bigint) OWNER TO cppoltp;

--
-- Name: sp_get_utc_time(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_utc_time(format text) RETURNS TABLE(utc_time text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

	IF format IS NOT NULL THEN
		RETURN QUERY
		SELECT to_char(now() at time zone 'UTC', format)  AS utc_time;
	ELSE
		RETURN QUERY
		--SELECT to_char(now() at time zone 'UTC', 'YYYY-MM-DD HH24:MI:SS ') || to_char(now(), 'OF00') AS utc_time;
		SELECT  to_char(now(), 'YYYY-MM-DD HH24:MI:SS OF00');

	END IF;

END;
$$;


ALTER FUNCTION public.sp_get_utc_time(format text) OWNER TO cppoltp;

--
-- Name: sp_get_v3_link_node_list(public.en_v3_link_param, public.en_product_id_type, public.en_platform_type[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_v3_link_node_list(i_link_type public.en_v3_link_param, i_product_id public.en_product_id_type, i_platforms public.en_platform_type[]) RETURNS TABLE(node_id bigint[])
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_node_id bigint[];
  v_engine_update_threshold bigint;
  v_platforms en_platform_type[] := COALESCE(i_platforms, '{WINDOWS,LINUX_UNIX,MAC}'::en_platform_type[]);
  v_oes_engine_date           timestamp := '9999.12.31'::timestamp;
  v_ses_engine_date           timestamp := '9999.12.31'::timestamp;
BEGIN

  IF i_link_type = 'INSTALL' THEN
    WITH node_product AS (
        SELECT n.node_id
        FROM tb_node n
            JOIN tb_platform platform ON platform.platform_id = n.platform_id
            JOIN tb_product_info pi ON pi.node_id = n.node_id
            JOIN (SELECT product_id, name, product_group, is_server_product, is_client_product, unnest(platform_support) platform_type FROM tb_product) p ON p.product_id = pi.product_id
        WHERE n.is_removed IS FALSE
          AND platform.is_supported IS TRUE
            AND p.product_id = i_product_id
            AND platform.platform_type = ANY(v_platforms)
        )
        SELECT array_agg(np.node_id) INTO v_node_id FROM node_product np;

  ELSIF i_link_type = 'NO_INSTALL' THEN
    SELECT
        array_agg(t.node_id) INTO v_node_id
    FROM 
        (
             WITH target AS (
              SELECT
                n.node_id, tp.platform_type, tp.is_server, n.machine_type
              FROM
                tb_node n
                JOIN tb_platform tp ON n.platform_id = tp.platform_id
              WHERE n.is_removed IS FALSE
                AND tp.is_supported IS TRUE
                AND tp.platform_type = ANY(v_platforms)
                AND n.machine_type != 'CONTAINER'
            ),
            container_target AS (
              SELECT
                n.node_id, tp.platform_type, tp.is_server, n.machine_type
              FROM
                tb_node n
                JOIN tb_platform tp ON n.platform_id = tp.platform_id
                LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = n.container_service_type
              WHERE n.is_removed IS FALSE
                AND tp.is_supported IS TRUE
                AND tp.platform_type = ANY(v_platforms)
                AND n.machine_type = 'CONTAINER'
                AND CASE WHEN i_product_id = 'AMC_CLIENT' AND is_amc_supported IS TRUE THEN TRUE
                         WHEN i_product_id = 'AC_CLIENT' AND is_ac_supported IS TRUE THEN TRUE
                         ELSE FALSE END
            )
            SELECT
              t.node_id
            FROM
              (SELECT
                product_id, name, product_group, is_server_product, is_client_product
                , unnest(platform_support) AS platform_type
              FROM
                tb_product
              ) p
                JOIN target t ON p.platform_type = t.platform_type
                LEFT JOIN tb_product_info pi ON p.product_id = pi.product_id AND pi.node_id = t.node_id
            WHERE
              (CASE WHEN t.is_server is true THEN is_server_product ELSE is_client_product END) IS TRUE
                AND p.product_id = i_product_id
                AND i_product_id IN ('V3NET_9.0', 'V3NET_LU','HIPS_CLIENT', 'AC_CLIENT')
              AND pi.node_id IS NULL
              
            UNION
            
            SELECT
              t.node_id
            FROM
              (SELECT
                product_id, name, product_group, is_server_product, is_client_product
                , unnest(platform_support) AS platform_type
              FROM
                tb_product
              ) p
                JOIN container_target t ON p.platform_type = t.platform_type
                LEFT JOIN tb_product_info pi ON p.product_id = pi.product_id AND pi.node_id = t.node_id
            WHERE
              (CASE WHEN t.is_server is true THEN is_server_product ELSE is_client_product END) IS TRUE
                AND p.product_id = i_product_id
                AND i_product_id IN ('AMC_CLIENT', 'AC_CLIENT')
              AND pi.node_id IS NULL
        ) t;
    
  ELSIF i_link_type = 'UNSUPPORTED' THEN
    WITH container_target AS (
      SELECT
        n.node_id, tp.platform_type, tp.is_server, n.machine_type
      FROM
        tb_node n
        JOIN tb_platform tp ON n.platform_id = tp.platform_id
        LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = n.container_service_type
      WHERE n.is_removed IS FALSE
        AND tp.is_supported IS TRUE
        AND tp.platform_type = ANY(v_platforms)
        AND n.machine_type = 'CONTAINER'
        AND CASE WHEN i_product_id = 'AMC_CLIENT' AND is_amc_supported IS FALSE THEN TRUE
                 WHEN i_product_id = 'AC_CLIENT' AND is_ac_supported IS FALSE THEN TRUE
                 ELSE FALSE END
    )
    SELECT
      array_agg(t.node_id) INTO v_node_id
    FROM
      (SELECT
        product_id, name, product_group, is_server_product, is_client_product
        , unnest(platform_support) AS platform_type
      FROM
        tb_product
      ) p
        JOIN container_target t ON p.platform_type = t.platform_type
        LEFT JOIN tb_product_info pi ON p.product_id = pi.product_id AND pi.node_id = t.node_id
    WHERE
      (CASE WHEN t.is_server is true THEN is_server_product ELSE is_client_product END) IS TRUE
        AND p.product_id = i_product_id
        AND i_product_id IN ('AMC_CLIENT', 'AC_CLIENT')
      AND pi.node_id IS NULL;

  ELSIF i_link_type = 'NEW_ENGINE' THEN

  -- 엔진 업데이트 임계치
  SELECT GREATEST(COALESCE(MAX(c.value), '0')::integer -1, 0) INTO v_engine_update_threshold
    FROM tb_config AS c
   WHERE c.config_group = 'AGENT_THRESHOLD' AND c.key = 'engine_update_threshold'
   ;

  -- 최신 엔진 버전(일자)
  SELECT TO_CHAR(SUBSTRING(MAX(case when key = 'oes_engine_date' THEN value END), 1, 10)::timestamp - (v_engine_update_threshold || ' day')::interval, 'YYYY.MM.DD')::timestamp AS oes_engine_date,
         TO_CHAR(SUBSTRING(MAX(case when key = 'ses_engine_date' THEN value END), 1, 10)::timestamp - (v_engine_update_threshold || ' day')::interval, 'YYYY.MM.DD')::timestamp AS ses_engine_date
    INTO v_oes_engine_date, v_ses_engine_date
    FROM tb_config AS c
   WHERE c.config_group = 'UPDATE_SERVICE'
   ;

    SELECT array_agg(vs.node_id)
    INTO v_node_id
    FROM (SELECT vs.node_id AS node_id
          FROM tb_v3_status vs
          JOIN tb_product_info pi ON vs.node_id = pi.node_id AND vs.product_id = pi.product_id
          WHERE vs.product_id = i_product_id
            AND vs.engine_type = 'SES'
            AND vs.engine_update_time >= v_ses_engine_date
          UNION ALL
          SELECT vs.node_id AS node_id
          FROM tb_v3_status vs
          JOIN tb_product_info pi ON vs.node_id = pi.node_id AND vs.product_id = pi.product_id
          WHERE vs.product_id = i_product_id
            AND vs.engine_type = 'OES'
            AND vs.engine_update_time >= v_oes_engine_date
          ) vs;

  ELSIF i_link_type = 'OLD_ENGINE' THEN

  -- 엔진 업데이트 임계치
  SELECT GREATEST(COALESCE(MAX(c.value), '0')::integer -1, 0) INTO v_engine_update_threshold
    FROM tb_config AS c
   WHERE c.config_group = 'AGENT_THRESHOLD' AND c.key = 'engine_update_threshold'
   ;

  -- 최신 엔진 버전(일자)
  SELECT TO_CHAR(SUBSTRING(MAX(case when key = 'oes_engine_date' THEN value END), 1, 10)::timestamp - (v_engine_update_threshold || ' day')::interval, 'YYYY.MM.DD')::timestamp AS oes_engine_date,
         TO_CHAR(SUBSTRING(MAX(case when key = 'ses_engine_date' THEN value END), 1, 10)::timestamp - (v_engine_update_threshold || ' day')::interval, 'YYYY.MM.DD')::timestamp AS ses_engine_date
    INTO v_oes_engine_date, v_ses_engine_date
    FROM tb_config AS c
   WHERE c.config_group = 'UPDATE_SERVICE'
   ;

    SELECT array_agg(vs.node_id)
    INTO v_node_id
    FROM (SELECT vs.node_id AS node_id
          FROM tb_v3_status vs
          JOIN tb_product_info pi ON vs.node_id = pi.node_id AND vs.product_id = pi.product_id
          WHERE vs.product_id = i_product_id
            AND vs.engine_type = 'SES'
            AND (vs.engine_update_time IS NULL OR vs.engine_update_time < v_ses_engine_date)
          UNION ALL
          SELECT vs.node_id AS node_id
          FROM tb_v3_status vs
          JOIN tb_product_info pi ON vs.node_id = pi.node_id AND vs.product_id = pi.product_id
          WHERE vs.product_id = i_product_id
            AND vs.engine_type = 'OES'
            AND (vs.engine_update_time IS NULL OR vs.engine_update_time < v_oes_engine_date)
          ) vs;

  ELSIF i_link_type = 'ON_REALTIME' THEN

    SELECT array_agg(vs.node_id)
    INTO v_node_id
    FROM tb_v3_status vs
    JOIN tb_product_info pi ON vs.node_id = pi.node_id AND vs.product_id = pi.product_id
    WHERE vs.product_id = i_product_id
      AND vs.realtime_status IS true;

  ELSIF i_link_type = 'OFF_REALTIME' THEN

    SELECT array_agg(vs.node_id)
    INTO v_node_id
    FROM tb_v3_status vs
    JOIN tb_product_info pi ON vs.node_id = pi.node_id AND vs.product_id = pi.product_id
    WHERE vs.product_id = i_product_id
      AND vs.realtime_status IS NOT true;

  ELSIF i_link_type = 'EXPIRED_LICENSE' THEN

    SELECT
        array_agg(vs.node_id)
    INTO
        v_node_id
    FROM
        (
        SELECT vs.node_id
        FROM (
            SELECT
                vs.node_id
                , vs.product_id
                , vs.product_version
                , vs.engine_version
                , CASE
                    WHEN vs.activation_code IS NOT NULL AND vs.activation_code != '' THEN vs.activation_code 
                    WHEN vs.license_no IS NOT NULL AND vs.license_no != '' THEN vs.license_no
                    ELSE NULL
                    END AS license_no
                , vs.license_user
                , vs.license_org
                , vs.server_time
                , vs.realtime_status
                , vs.engine_update_time
                , vs.last_scan_time
                , vs.tz_offset
                , vs.client_time
                , vs.integrity_status
                , vs.engine_type
                , vs.obj_id
                , vs.install_time
                , vs.realtime_status_mode
                , vs.last_quarantine_collect_time
                , vs.scan_status
                , vs.ckl_version
                , vs.comp_type
            FROM
                tb_v3_status vs
        ) vs
        JOIN tb_node n ON vs.node_id = n.node_id AND n.is_removed IS FALSE
        JOIN tb_product_info pi ON vs.node_id = pi.node_id AND vs.product_id = pi.product_id
        JOIN tb_platform tp ON n.platform_id = tp.platform_id
        LEFT JOIN tb_multi_license pl ON vs.product_id = pl.product_id AND vs.license_no = pl.license_no
        WHERE pl.expire_date < now()
        AND vs.product_id = i_product_id
        
        UNION ALL
        
        SELECT vs.node_id
        FROM (
            SELECT 
                ac.node_id
                , ac.product_id
                , ac.product_version
                , ac.service_status
                , ac.ac_status
                , ac.engine_version
                , ac.engine_update_time
                , ac.engine_type
                , ac.mode_begin_time
                , ac.mode_end_time
                , ac.engine_date
                , ac.execute_date
                , CASE
                    WHEN ac.activation_code IS NOT NULL AND ac.activation_code != '' THEN ac.activation_code 
                    WHEN ac.license_no IS NOT NULL AND ac.license_no != '' THEN ac.license_no
                    ELSE NULL
                    END AS license_no
                , ac.license_user
                , ac.license_org
                , ac.integrity_status
                , ac.install_time
                , ac.client_time
                , ac.tz_offset
                , ac.server_time
                , ac.engine_state
                , ac.im_enable
                , ac.im_enable_real_time
                , ac.im_engine_version
                , ac.im_manual_time
                , ac.ckl_version
            FROM
                tb_ac_status ac
        ) vs
        JOIN tb_node n ON vs.node_id = n.node_id AND n.is_removed IS FALSE
        JOIN tb_product_info pi ON vs.node_id = pi.node_id AND vs.product_id = pi.product_id
        JOIN tb_platform tp ON n.platform_id = tp.platform_id
        LEFT JOIN tb_multi_license pl ON vs.product_id = pl.product_id AND vs.license_no = pl.license_no
        WHERE pl.expire_date < now()
        AND vs.product_id = i_product_id
        AND tp.platform_type = ANY(v_platforms)
        
        UNION ALL
        
        SELECT vs.node_id
        FROM (
            SELECT
                hs.node_id
                , hs.product_id
                , hs.product_version
                , hs.service_status
                , hs.ips_status
                , hs.fw_status
                , hs.engine_version
                , hs.engine_update_time
                , hs.signature_version
                , hs.signature_count
                , hs.recommendation_status
                , hs.recommendation_date
                , CASE
                      WHEN hs.activation_code IS NOT NULL AND hs.activation_code != '' THEN hs.activation_code 
                      WHEN hs.license_no IS NOT NULL AND hs.license_no != '' THEN hs.license_no
                      ELSE NULL
                      END AS license_no
                , hs.license_user
                , hs.license_org
                , hs.integrity_status
                , hs.install_time
                , hs.client_time
                , hs.tz_offset
                , hs.server_time
                , hs.engine_state
                , hs.fw_network_running
                , hs.fw_block_nation_running
                , hs.fw_block_ip_running
                , hs.ssl_inspection_running
                , hs.ssl_inspection_init_time
                , hs.ssl_inspection_modified_time
                , hs.ssl_engine_mode
                , hs.ssl_engine_port
                , hs.ssl_engine_limit_session
            FROM
                tb_hips_status hs
        ) vs
        JOIN tb_node n ON vs.node_id = n.node_id AND n.is_removed IS FALSE
        JOIN tb_product_info pi ON vs.node_id = pi.node_id AND vs.product_id = pi.product_id
        JOIN tb_platform tp ON n.platform_id = tp.platform_id
        LEFT JOIN tb_multi_license pl ON vs.product_id = pl.product_id AND vs.license_no = pl.license_no
        WHERE pl.expire_date < now()
        AND vs.product_id = i_product_id
        AND tp.platform_type = ANY(v_platforms)
        ) vs;

  ELSIF i_link_type = 'INTEGRITY' THEN

  WITH target AS (
    SELECT n.node_id
    FROM tb_node n
        JOIN tb_platform tp ON n.platform_id = tp.platform_id
    WHERE n.is_removed IS FALSE
      AND tp.is_supported IS TRUE
        AND tp.platform_type = ANY(v_platforms)
  )
  ,integrity AS (
    SELECT s.node_id, s.product_id, s.integrity_status FROM tb_ac_status s
    WHERE s.node_id IN (SELECT t.node_id FROM target t)
    UNION ALL
    SELECT s.node_id, s.product_id, s.integrity_status FROM tb_hips_status s
    WHERE s.node_id IN (SELECT t.node_id FROM target t)
    UNION ALL
    SELECT s.node_id, s.product_id, s.integrity_status FROM tb_v3_status s
    WHERE s.node_id IN (SELECT t.node_id FROM target t)
  )
  SELECT array_agg(i.node_id)
  INTO v_node_id
  FROM integrity i
  WHERE i.product_id = i_product_id
    AND i.integrity_status <> 'NORMAL';

  ELSIF i_link_type = 'NEW_SIGNATURE' THEN
    WITH target AS (
        SELECT n.node_id
        FROM tb_node n
            JOIN tb_platform platform ON platform.platform_id = n.platform_id
            JOIN tb_product_info pi ON pi.node_id = n.node_id
            JOIN (SELECT product_id, name, product_group, is_server_product, is_client_product, unnest(platform_support) platform_type FROM tb_product) p ON p.product_id = pi.product_id
        WHERE n.is_removed IS FALSE
          AND platform.is_supported IS TRUE
            AND p.product_id = i_product_id
            AND platform.platform_type = ANY(i_platforms)
        )
    , recent_signature_version AS (
        SELECT version
        FROM tb_product_pkg
        WHERE is_removed IS FALSE AND pkg_type = 'IPS_DEFAULT_SIGNATURE'
        ORDER BY version DESC
    )
    SELECT array_agg(s.node_id)
    INTO v_node_id
    FROM tb_hips_status s
    WHERE s.node_id IN (SELECT t.node_id FROM target t)
        AND s.signature_version IN (SELECT version FROM recent_signature_version);

   ELSIF i_link_type = 'OLD_SIGNATURE' THEN
    WITH target AS (
        SELECT n.node_id
        FROM tb_node n
            JOIN tb_platform platform ON platform.platform_id = n.platform_id
            JOIN tb_product_info pi ON pi.node_id = n.node_id
            JOIN (SELECT product_id, name, product_group, is_server_product, is_client_product, unnest(platform_support) platform_type FROM tb_product) p ON p.product_id = pi.product_id
        WHERE n.is_removed IS FALSE
          AND platform.is_supported IS TRUE
            AND p.product_id = i_product_id
            AND platform.platform_type = ANY(i_platforms)
        )
    , recent_signature_version AS (
        SELECT version
        FROM tb_product_pkg
        WHERE is_removed IS FALSE AND pkg_type = 'IPS_DEFAULT_SIGNATURE'
        ORDER BY version DESC
    )
    SELECT array_agg(s.node_id)
    INTO v_node_id
    FROM tb_hips_status s
    WHERE s.node_id IN (SELECT t.node_id FROM target t)
        AND s.signature_version NOT IN (SELECT version FROM recent_signature_version);

   ELSIF i_link_type = 'NEW_SCM_RULE' THEN
    WITH target AS (
        SELECT n.node_id
        FROM tb_node n
            JOIN tb_platform platform ON platform.platform_id = n.platform_id
            JOIN tb_product_info pi ON pi.node_id = n.node_id
            JOIN (SELECT product_id, name, product_group, is_server_product, is_client_product, unnest(platform_support) platform_type FROM tb_product) p ON p.product_id = pi.product_id
        WHERE n.is_removed IS FALSE
          AND platform.is_supported IS TRUE
            AND p.product_id = i_product_id
            AND platform.platform_type = ANY(i_platforms)
        )
    , recent_rule_version AS (
        SELECT version
        FROM tb_product_pkg
        WHERE is_removed IS FALSE AND pkg_type = 'SCM_PREDEFINED'
    )
    SELECT array_agg(s.node_id)
    INTO v_node_id
    FROM tb_scm_status s
    WHERE s.node_id IN (SELECT t.node_id FROM target t)
        AND s.rule_version = (SELECT version FROM recent_rule_version);
        
   ELSIF i_link_type = 'OLD_SCM_RULE' THEN
    WITH target AS (
        SELECT n.node_id
        FROM tb_node n
            JOIN tb_platform platform ON platform.platform_id = n.platform_id
            JOIN tb_product_info pi ON pi.node_id = n.node_id
            JOIN (SELECT product_id, name, product_group, is_server_product, is_client_product, unnest(platform_support) platform_type FROM tb_product) p ON p.product_id = pi.product_id
        WHERE n.is_removed IS FALSE
          AND platform.is_supported IS TRUE
            AND p.product_id = i_product_id
            AND platform.platform_type = ANY(i_platforms)
        )
    , recent_rule_version AS (
        SELECT version
        FROM tb_product_pkg
        WHERE is_removed IS FALSE AND pkg_type = 'SCM_PREDEFINED'
    )
    SELECT array_agg(s.node_id)
    INTO v_node_id
    FROM tb_scm_status s
    WHERE s.node_id IN (SELECT t.node_id FROM target t)
        AND (s.rule_version != (SELECT version FROM recent_rule_version) OR s.rule_version IS NULL OR NOT EXISTS (SELECT 1 FROM recent_rule_version));

  END IF;

  RETURN QUERY
  SELECT COALESCE(v_node_id, '{}'::BIGINT[]);

END;
$$;


ALTER FUNCTION public.sp_get_v3_link_node_list(i_link_type public.en_v3_link_param, i_product_id public.en_product_id_type, i_platforms public.en_platform_type[]) OWNER TO cppoltp;

--
-- Name: sp_get_v3_linux_policy_detail(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_v3_linux_policy_detail(i_policy_id bigint) RETURNS TABLE(product_feature_id public.en_product_feature_id_type, product_feature_name text, policy_id bigint, policy_name text, description text, policy_type public.en_policy_type, online_policy_body text, offline_policy_body text, use_offline_policy text, update_online_policy_body text, update_offline_policy_body text, use_update_offline_policy text, hash text, modified_time timestamp without time zone, group_id_array bigint[])
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_product_feature_id en_product_feature_id_type;

BEGIN

SELECT p.product_feature_id
INTO v_product_feature_id
FROM tb_policy p
WHERE p.policy_id = i_policy_id;

IF v_product_feature_id IS NULL THEN

  RAISE EXCEPTION 'policy_id (%) does not exist.', i_policy_id USING HINT = 'DB-00031';

ELSIF v_product_feature_id <> 'V3NET_LU_AV' THEN

  RAISE EXCEPTION 'policy_id (%) is not V3NET_LU_AV policy.', i_policy_id USING HINT = 'DB-00030';

END IF;

RETURN QUERY

--정책 상세
SELECT p.product_feature_id AS product_feature_id
      ,p.product_feature_name AS product_feature_name
      ,p.policy_id AS policy_id
      ,p.policy_name AS policy_name
      ,p.description AS description
      ,p.policy_type AS policy_type
      ,p.online_policy_body AS online_policy_body
      ,p.offline_policy_body AS offline_policy_body
      ,p.use_offline_policy AS use_offline_policy
      ,up.online_policy_body AS update_online_policy_body
      ,up.offline_policy_body AS update_offline_policy_body
      ,COALESCE(up.use_offline_policy, false)::integer::text AS use_update_offline_policy
      ,p.hash AS hash
      ,p.modified_time AS modified_time
      ,p.group_id_array AS group_id_array
FROM sp_get_policy_detail(i_policy_id) p
LEFT JOIN tb_policy up
ON p.policy_id = up.ppolicy_id
  AND up.product_feature_id = 'V3NET_LU_UPDATE'
;

END;
$$;


ALTER FUNCTION public.sp_get_v3_linux_policy_detail(i_policy_id bigint) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_v3_linux_policy_detail(i_policy_id bigint); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_v3_linux_policy_detail(i_policy_id bigint) IS '
@brief [SWM-SCI1037] V3 LINUX 정책 내용 조회
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_v3_linux_policy_factory(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_v3_linux_policy_factory(i_admin_id text) RETURNS TABLE(policy_name text, product_feature_id public.en_product_feature_id_type, description text, online_policy_body text, offline_policy_body text, use_offline_policy text, update_online_policy_body text, update_offline_policy_body text, use_update_offline_policy text, hash text)
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_privilege_profile_auth boolean;
BEGIN

SELECT
    EXISTS (
        SELECT
            1
        FROM
            tb_admin ta
        INNER JOIN
            tb_privilege_profile tpp
        ON
            ta.privilege_profile_id = tpp.privilege_profile_id 
        WHERE
            tpp.profile_body LIKE '%"/policy/policy_V3L_W"%'
        AND
            ta.admin_id = i_admin_id
    ) INTO v_privilege_profile_auth;
	
IF v_privilege_profile_auth = FALSE THEN
  RAISE EXCEPTION 'You do not have permission to write policy' USING HINT = 'DB-00084';
END IF;

  --정책 공장초기화값 조회
  RETURN QUERY
  SELECT pf.policy_name AS policy_name
        ,pf.product_feature_id AS product_feature_id
        ,pf.description AS description
        ,pf.online_policy_body AS online_policy_body
        ,pf.offline_policy_body AS offline_policy_body
        ,pf.use_offline_policy AS use_offline_policy
        ,upf.online_policy_body AS update_online_policy_body
        ,upf.offline_policy_body AS update_offline_policy_body
        ,upf.use_offline_policy AS use_update_offline_policy
        ,pf.hash AS hash
  FROM sp_get_policy_factory('V3NET_LU_AV') pf
  JOIN sp_get_policy_factory('V3NET_LU_UPDATE') upf
  ON pf.policy_id = upf.ppolicy_id;

END;
$$;


ALTER FUNCTION public.sp_get_v3_linux_policy_factory(i_admin_id text) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_get_v3_linux_policy_factory(i_admin_id text); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_get_v3_linux_policy_factory(i_admin_id text) IS '
@brief [SWP-SCI1034] V3 LINUX 정책 공장초기화값 조회
@in -
@out -
@return - TABLE';


--
-- Name: sp_get_v3_malware_count(bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_v3_malware_count(i_node_id bigint[]) RETURNS TABLE(product_type text, product_id public.en_product_id_type, count bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

RETURN QUERY
--V3 설치 현황
SELECT CASE WHEN p.is_server_product = false THEN 'DESKTOP'
            WHEN p.is_server_product = true THEN 'SERVER'
            ELSE 'NULL'
       END AS product_type
      ,ps.product_id AS product_id
      ,count(*) AS count
FROM tb_v3_status ps
JOIN tb_product_info pi ON ps.node_id = pi.node_id AND pi.product_id = ps.product_id
JOIN tb_product p ON pi.product_id = p.product_id AND p.product_group = 'V3'
JOIN (SELECT pl.is_server
            ,n.node_id
      FROM tb_node n
      JOIN tb_platform pl ON n.platform_id = pl.platform_id
      WHERE pl.is_supported IS TRUE) pl
ON ps.node_id = pl.node_id
WHERE ps.node_id = ANY(i_node_id)
  AND EXISTS (SELECT 1 FROM tb_node n WHERE n.node_id = ps.node_id AND n.is_removed is false AND n.platform_id IS NOT NULL)
GROUP BY
      ps.product_id
     ,p.is_server_product
     ,pl.is_server

;

END;
$$;


ALTER FUNCTION public.sp_get_v3_malware_count(i_node_id bigint[]) OWNER TO cppoltp;

--
-- Name: sp_get_v3_management_summary_info(bigint, boolean, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_v3_management_summary_info(i_group_id bigint, i_is_include_all_sub_groups boolean, i_admin_id text) RETURNS TABLE(product_feature_id public.en_product_feature_id_type, count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
  IF i_is_include_all_sub_groups THEN
    RETURN QUERY
    SELECT
     PRF.product_feature_id
    , COUNT(*) AS cnt
    FROM tb_product AS PRD
    INNER JOIN tb_product_feature AS PRF
    ON PRD.product_id = PRF.product_id
    INNER JOIN tb_policy AS POL
    ON POL.product_feature_id = PRF.product_feature_id
    INNER JOIN tb_group_policy AS GRP
    ON POL.policy_id = GRP.policy_id
    INNER JOIN tb_group AS GRO
    ON GRO.group_id = GRP.group_id
    WHERE PRD.product_group = 'V3'
    AND GRO.group_id IN (
      SELECT
       unnest(sp_get_all_sub_group_list(i_group_id
          , true, i_admin_id)))
    GROUP BY PRF.product_feature_id;
  ELSE
    RETURN QUERY
    SELECT
     PRF.product_feature_id
    , COUNT(*) AS count
    FROM tb_product AS PRD
    INNER JOIN tb_product_feature AS PRF
    ON PRD.product_id = PRF.product_id
    INNER JOIN tb_policy AS POL
    ON POL.product_feature_id = PRF.product_feature_id
    INNER JOIN tb_group_policy AS GRP
    ON POL.policy_id = GRP.policy_id
    INNER JOIN tb_group AS GRO
    ON GRO.group_id = GRP.group_id
    WHERE GRO.group_id = i_group_id
    AND PRD.product_group = 'V3'
    GROUP BY PRF.product_feature_id;

  END IF;
END;
$$;


ALTER FUNCTION public.sp_get_v3_management_summary_info(i_group_id bigint, i_is_include_all_sub_groups boolean, i_admin_id text) OWNER TO cppoltp;

--
-- Name: sp_get_v3_net_policy_detail(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_v3_net_policy_detail(i_policy_id bigint) RETURNS TABLE(product_feature_id public.en_product_feature_id_type, product_feature_name text, policy_id bigint, policy_name text, description text, policy_type public.en_policy_type, online_policy_body text, offline_policy_body text, use_offline_policy text, hash text, modified_time timestamp without time zone, group_id_array bigint[])
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_product_feature_id en_product_feature_id_type;

BEGIN

SELECT p.product_feature_id
INTO v_product_feature_id
FROM tb_policy p
WHERE p.policy_id = i_policy_id;


IF v_product_feature_id IS NULL THEN

  RAISE EXCEPTION 'policy_id (%) does not exist.', i_policy_id USING HINT = 'DB-00031';

ELSIF v_product_feature_id <> 'V3NET_9.0_AV' THEN

  RAISE EXCEPTION 'policy_id (%) is not V3NET_9.0_AV policy.', i_policy_id USING HINT = 'DB-00030';

END IF;

RETURN QUERY

--정책 상세
SELECT p.product_feature_id AS product_feature_id
      ,p.product_feature_name AS product_feature_name
      ,p.policy_id AS policy_id
      ,p.policy_name AS policy_name
      ,p.description AS description
      ,p.policy_type AS policy_type
      ,p.online_policy_body AS online_policy_body
      ,p.offline_policy_body AS offline_policy_body
      ,p.use_offline_policy AS use_offline_policy
      ,p.hash AS hash
      ,p.modified_time AS modified_time
      ,p.group_id_array AS group_id_array
FROM sp_get_policy_detail(i_policy_id) p
;

END;
$$;


ALTER FUNCTION public.sp_get_v3_net_policy_detail(i_policy_id bigint) OWNER TO cppoltp;

