CREATE FUNCTION public.sp_get_v3_net_policy_factory(i_admin_id text) RETURNS TABLE(policy_name text, product_feature_id public.en_product_feature_id_type, description text, online_policy_body text, offline_policy_body text, use_offline_policy text, hash text)
