--
-- Name: sp_get_v3_product_count(text, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_v3_product_count(i_product_auth text, i_group_id_arr bigint[]) RETURNS TABLE(product_id public.en_product_id_type, platform_type public.en_platform_type, install_count bigint, no_install_count bigint, unsupported_count bigint, new_engine_count bigint, old_engine_count bigint, integrity_count bigint, on_realtime_count bigint, off_realtime_count bigint, expired_license_count bigint, new_rule_version_count bigint, old_rule_version_count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_node_count bigint;
  v_engine_update_threshold bigint;
  v_oes_engine_date timestamp := '9999.12.31'::timestamp;
  v_ses_engine_date timestamp := '9999.12.31'::timestamp;
  v_product_auth              en_product_group_type[];
BEGIN

  -- 권한 처리
  IF i_product_auth IS NOT NULL AND LENGTH(TRIM(i_product_auth)) > 0 THEN
    v_product_auth := STRING_TO_ARRAY(REPLACE(i_product_auth, ' ', ''), ',')::en_product_group_type[];
  ELSE
    SELECT ENUM_RANGE(null::en_product_group_type) INTO v_product_auth;
  END IF;

  -- 엔진 업데이트 임계치
  SELECT
    GREATEST(COALESCE(MAX(c.value), '0')::integer -1, 0) INTO v_engine_update_threshold
  FROM
    tb_config AS c
  WHERE
    c.config_group = 'AGENT_THRESHOLD' AND c.key = 'engine_update_threshold'
  ;

  -- 최신 엔진 버전(일자)
  SELECT
    TO_CHAR(SUBSTRING(MAX(case when key = 'oes_engine_date' THEN value END), 1, 10)::timestamp - (v_engine_update_threshold || ' day')::interval, 'YYYY.MM.DD')::timestamp AS oes_engine_date,
    TO_CHAR(SUBSTRING(MAX(case when key = 'ses_engine_date' THEN value END), 1, 10)::timestamp - (v_engine_update_threshold || ' day')::interval, 'YYYY.MM.DD')::timestamp AS ses_engine_date
    INTO v_oes_engine_date, v_ses_engine_date
  FROM
    tb_config AS c
  WHERE
    c.config_group = 'UPDATE_SERVICE'
  ;

  RETURN QUERY

    SELECT
      p.product_id AS product_id
      , p.platform_type AS platform_type
      -- 설치
      , SUM(CASE WHEN p.product_id IN ('V3NET_9.0','V3NET_LU') AND p.product_id = pi.product_id AND target.machine_type != 'CONTAINER' THEN 1
                 WHEN p.product_id = 'AMC_CLIENT' AND p.product_id = pi.product_id AND target.machine_type = 'CONTAINER' AND target.is_am_supported IS TRUE THEN 1
                 WHEN p.product_id NOT IN ('V3NET_9.0','V3NET_LU','AMC_CLIENT') AND p.product_id = pi.product_id AND vws.service_status IS NOT NULL THEN 1 
                 ELSE 0 END) AS install_count

      -- 미설치         
      , COUNT(CASE WHEN p.product_id IN ('V3NET_9.0','V3NET_LU') AND target.machine_type != 'CONTAINER' THEN 1
                   WHEN p.product_id = 'AMC_CLIENT' AND target.machine_type = 'CONTAINER' AND target.is_am_supported IS TRUE THEN 1
                   WHEN p.product_id = 'AC_CLIENT' AND target.machine_type = 'CONTAINER' AND target.is_ac_supported IS TRUE THEN 1
                   WHEN p.product_id = 'AC_CLIENT' AND target.machine_type != 'CONTAINER' AND target.is_ac_supported IS TRUE THEN 1
                   WHEN p.product_id NOT IN ('V3NET_9.0','V3NET_LU','AMC_CLIENT','AC_CLIENT') THEN 1
                   ELSE NULL END)
      - SUM(CASE WHEN p.product_id IN ('V3NET_9.0','V3NET_LU') AND p.product_id = pi.product_id AND target.machine_type != 'CONTAINER' THEN 1
                 WHEN p.product_id = 'AMC_CLIENT' AND p.product_id = pi.product_id AND target.machine_type = 'CONTAINER' AND target.is_am_supported IS TRUE THEN 1 
                 WHEN p.product_id = 'AC_CLIENT' AND p.product_id = pi.product_id AND target.machine_type = 'CONTAINER' AND target.is_ac_supported IS TRUE THEN 1 
                 WHEN p.product_id = 'AC_CLIENT' AND p.product_id = pi.product_id AND target.machine_type != 'CONTAINER' AND target.is_ac_supported IS TRUE THEN 1 
                 WHEN p.product_id NOT IN ('V3NET_9.0','V3NET_LU','AMC_CLIENT','AC_CLIENT') AND p.product_id = pi.product_id AND vws.service_status IS NOT NULL THEN 1 
                 ELSE 0 END) AS no_install_count
                 
      -- 미지원           
      , COUNT(CASE WHEN p.product_id = 'AMC_CLIENT' AND target.machine_type = 'CONTAINER' AND target.is_am_supported IS FALSE THEN 1
                   WHEN p.product_id = 'AC_CLIENT' AND target.machine_type = 'CONTAINER' AND target.is_ac_supported IS FALSE THEN 1
                   ELSE NULL END)
      - SUM(CASE WHEN p.product_id = 'AMC_CLIENT' AND p.product_id = pi.product_id AND target.machine_type = 'CONTAINER' AND target.is_am_supported IS FALSE THEN 1 
                 WHEN p.product_id = 'AC_CLIENT' AND p.product_id = pi.product_id AND target.machine_type = 'CONTAINER' AND target.is_ac_supported IS FALSE THEN 1 
                 ELSE 0 END) AS unsupported_count

      , SUM(CASE WHEN p.product_id = vws.product_id THEN vws.new_engine ELSE 0 END) AS new_engine_count
      , SUM(CASE WHEN p.product_id = vws.product_id THEN vws.old_engine ELSE 0 END) AS old_engine_count
      , SUM(CASE WHEN p.product_id = vws.product_id THEN vws.integrity_status ELSE 0 END) AS integrity_count
      , SUM(CASE WHEN p.product_id = vws.product_id THEN vws.on_realtime ELSE 0 END) AS on_realtime_count
      , SUM(CASE WHEN p.product_id = vws.product_id THEN vws.off_realtime ELSE 0 END) AS off_realtime_count
      , SUM(CASE WHEN p.product_id = vws.product_id THEN vws.expired_license ELSE 0 END) AS expired_license_count
      , SUM(CASE WHEN p.product_id = vws.product_id THEN vws.new_rule_version_count ELSE 0 END) AS new_rule_version_count
      , SUM(CASE WHEN p.product_id = vws.product_id THEN vws.old_rule_version_count ELSE 0 END) AS old_rule_version_count
    FROM
      (
        SELECT
          t.product_group AS product_group
          , t.product_id AS product_id
          , t.is_server_product AS is_server_product
          , t.is_client_product AS is_client_product
          , unnest(t.platform_support) AS platform_type
        FROM
          tb_product t
      ) p
      LEFT JOIN (
        SELECT
          n.node_id AS node_id
          , n.group_id AS group_id
          , n.machine_type AS machine_type
          , tp.platform_type AS platform_type
          , tp.is_server AS is_server
          , CASE WHEN n.machine_type != 'CONTAINER' THEN TRUE
                 WHEN n.machine_type = 'CONTAINER' AND tcp.is_amc_supported IS TRUE THEN TRUE
                 ELSE FALSE
            END AS is_am_supported
          , CASE WHEN n.machine_type != 'CONTAINER' THEN TRUE
                 WHEN n.machine_type = 'CONTAINER' AND tcp.is_hips_supported IS TRUE THEN TRUE
                 ELSE FALSE
            END AS is_hips_supported
          , CASE WHEN n.machine_type != 'CONTAINER' THEN TRUE
                 WHEN n.machine_type = 'CONTAINER' AND tcp.is_ac_supported IS TRUE THEN TRUE
                 ELSE FALSE
            END AS is_ac_supported
        FROM
          tb_node n
          JOIN tb_platform tp ON n.platform_id = tp.platform_id
          LEFT JOIN tb_container_platform tcp ON tcp.container_service_type = n.container_service_type
        WHERE
          n.is_removed is FALSE
          AND tp.is_supported IS TRUE
      ) target ON p.platform_type = target.platform_type
                    AND CASE WHEN target.is_server IS TRUE THEN is_server_product ELSE is_client_product END IS TRUE
      LEFT JOIN (
        -- V3 현황
        SELECT
          vs.node_id AS node_id
          , vs.product_id AS product_id
          , vs.license_no AS license_no
          , CASE WHEN
              vs.engine_update_time >= (CASE WHEN vs.engine_type = 'OES' THEN v_oes_engine_date WHEN vs.engine_type = 'SES' THEN v_ses_engine_date END)
            THEN 1
            ELSE 0 END AS new_engine  -- 최신 버전 엔진 여부
          , CASE WHEN
              vs.engine_update_time IS NULL OR (vs.engine_update_time < (CASE WHEN vs.engine_type = 'OES' THEN v_oes_engine_date WHEN vs.engine_type = 'SES' THEN v_ses_engine_date END))
            THEN 1
            ELSE 0 END AS old_engine  -- 구 버전 엔진 여부
          , CASE WHEN vs.integrity_status <> 'NORMAL' THEN 1 ELSE 0 END AS integrity_status
          , CASE WHEN vs.realtime_status IS TRUE THEN 1 ELSE 0 END AS on_realtime
          , CASE WHEN vs.realtime_status IS FALSE THEN 1 ELSE 0 END AS off_realtime
          , CASE WHEN pl.expire_date < NOW() THEN 1 ELSE 0 END AS expired_license
          , NULL AS service_status
          , 0 AS new_rule_version_count
          , 0 AS old_rule_version_count          
        FROM
          (
            SELECT
                vs.node_id
                , vs.product_id
                , vs.product_version
                , vs.engine_version
                , CASE
                    WHEN vs.activation_code IS NOT NULL AND vs.activation_code != '' THEN vs.activation_code 
                    WHEN vs.license_no IS NOT NULL AND vs.license_no != '' THEN vs.license_no
                    ELSE NULL
                    END AS license_no
                , vs.license_user
                , vs.license_org
                , vs.server_time
                , vs.realtime_status
                , vs.engine_update_time
                , vs.last_scan_time
                , vs.tz_offset
                , vs.client_time
                , vs.integrity_status
                , vs.engine_type
                , vs.obj_id
                , vs.install_time
                , vs.realtime_status_mode
                , vs.last_quarantine_collect_time
                , vs.scan_status
                , vs.ckl_version
                , vs.comp_type
            FROM
                tb_v3_status vs
          ) vs
          JOIN tb_product_info pi ON vs.node_id = pi.node_id AND vs.product_id = pi.product_id
          JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'V3'
          LEFT JOIN tb_multi_license pl ON vs.product_id = pl.product_id AND vs.license_no = pl.license_no
        WHERE
          sp_exist_license('V3')
        UNION ALL
        -- AC 현황
        SELECT
          ass.node_id AS node_id
          , ass.product_id AS product_id
          , ass.license_no AS license_no
          , 0 AS new_engine
          , 0 AS old_engine
          , CASE WHEN ass.integrity_status <> 'NORMAL' THEN 1 ELSE 0 END AS integrity_status
          , 0 AS on_realtime
          , 0 AS off_realtime
          , CASE WHEN pl.expire_date < NOW() THEN 1 ELSE 0 END AS expired_license
          , ass.service_status AS service_status  
          , 0 AS new_rule_version_count
          , 0 AS old_rule_version_count          
        FROM
          (
            SELECT 
                ac.node_id
                , ac.product_id
                , ac.product_version
                , ac.service_status
                , ac.ac_status
                , ac.engine_version
                , ac.engine_update_time
                , ac.engine_type
                , ac.mode_begin_time
                , ac.mode_end_time
                , ac.engine_date
                , ac.execute_date
                , CASE
                    WHEN ac.activation_code IS NOT NULL AND ac.activation_code != '' THEN ac.activation_code 
                    WHEN ac.license_no IS NOT NULL AND ac.license_no != '' THEN ac.license_no
                    ELSE NULL
                    END AS license_no
                , ac.license_user
                , ac.license_org
                , ac.integrity_status
                , ac.install_time
                , ac.client_time
                , ac.tz_offset
                , ac.server_time
                , ac.engine_state
                , ac.im_enable
                , ac.im_enable_real_time
                , ac.im_engine_version
                , ac.im_manual_time
                , ac.ckl_version
            FROM
                tb_ac_status ac
          ) ass
          JOIN tb_product_info pi ON ass.node_id = pi.node_id AND ass.product_id = pi.product_id
          JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'AC'
          LEFT JOIN tb_multi_license pl ON ass.product_id = pl.product_id AND ass.license_no = pl.license_no
        WHERE
          sp_exist_license('AC')
        UNION ALL
        -- HIPS 현황
        SELECT
          ass.node_id AS node_id
          , ass.product_id AS product_id
          , ass.license_no AS license_no
          , CASE WHEN
              ass.signature_version = (SELECT version FROM tb_product_pkg  WHERE is_removed IS FALSE AND pkg_type = 'IPS_DEFAULT_SIGNATURE' ORDER BY version DESC LIMIT 1)
            THEN 1
            ELSE 0 END AS new_engine  -- 최신 버전 엔진 여부
          , CASE WHEN
              ass.signature_version != (SELECT version FROM tb_product_pkg  WHERE is_removed IS FALSE AND pkg_type = 'IPS_DEFAULT_SIGNATURE' ORDER BY version DESC LIMIT 1)
              or ass.signature_version is null
            THEN 1
            ELSE 0 END AS old_engine  -- 구 버전 엔진 여부
          , CASE WHEN ass.integrity_status <> 'NORMAL' THEN 1 ELSE 0 END AS integrity_status
          , 0 AS on_realtime
          , 0 AS off_realtime
          , CASE WHEN pl.expire_date < NOW() THEN 1 ELSE 0 END AS expired_license
          , ass.service_status AS service_status 
          , 0 AS new_rule_version_count
          , 0 AS old_rule_version_count
        FROM
          (
            SELECT
                hs.node_id
                , hs.product_id
                , hs.product_version
                , hs.service_status
                , hs.ips_status
                , hs.fw_status
                , hs.engine_version
                , hs.engine_update_time
                , hs.signature_version
                , hs.signature_count
                , hs.recommendation_status
                , hs.recommendation_date
                , CASE
                      WHEN hs.activation_code IS NOT NULL AND hs.activation_code != '' THEN hs.activation_code 
                      WHEN hs.license_no IS NOT NULL AND hs.license_no != '' THEN hs.license_no
                      ELSE NULL
                      END AS license_no
                , hs.license_user
                , hs.license_org
                , hs.integrity_status
                , hs.install_time
                , hs.client_time
                , hs.tz_offset
                , hs.server_time
                , hs.engine_state
                , hs.fw_network_running
                , hs.fw_block_nation_running
                , hs.fw_block_ip_running
                , hs.ssl_inspection_running
                , hs.ssl_inspection_init_time
                , hs.ssl_inspection_modified_time
                , hs.ssl_engine_mode
                , hs.ssl_engine_port
                , hs.ssl_engine_limit_session
            FROM
                tb_hips_status hs
          ) ass
          JOIN tb_product_info pi ON ass.node_id = pi.node_id AND ass.product_id = pi.product_id
          JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'HIPS'
          LEFT JOIN tb_multi_license pl ON ass.product_id = pl.product_id AND ass.license_no = pl.license_no
        WHERE
          sp_exist_license('HIPS')
        UNION ALL
        -- SCM 현황
        SELECT
          ass.node_id AS node_id
          , ass.product_id AS product_id
          , ass.license_no AS license_no
          , 0 AS new_engine
          , 0 AS old_engine
          , CASE WHEN ass.integrity_status <> 'NORMAL' THEN 1 ELSE 0 END AS integrity_status
          , 0 AS on_realtime
          , 0 AS off_realtime
          , CASE WHEN pl.expire_date < NOW() THEN 1 ELSE 0 END AS expired_license
          , ass.service_status AS service_status        
          , CASE WHEN (SELECT 1 FROM tb_product_pkg tpp WHERE tpp.VERSION = ass.rule_version AND tpp.pkg_type = 'SCM_PREDEFINED' AND tpp.is_removed IS FALSE) = 1 THEN 1 ELSE 0 END AS new_rule_version_count
          , CASE WHEN (SELECT 1 FROM tb_product_pkg tpp WHERE tpp.VERSION = ass.rule_version AND tpp.pkg_type = 'SCM_PREDEFINED' AND tpp.is_removed IS FALSE) = 1 THEN 0 ELSE 1 END AS old_rule_version_count
        FROM
          tb_scm_status ass
          JOIN tb_product_info pi ON ass.node_id = pi.node_id AND ass.product_id = pi.product_id
          JOIN tb_product AS p ON p.product_id = pi.product_id AND p.product_group = 'SCM'
          LEFT JOIN tb_multi_license pl ON ass.product_id = pl.product_id AND ass.license_no = pl.license_no
        WHERE
          sp_exist_license('SCM')           
      ) vws ON p.product_id = vws.product_id AND vws.node_id = target.node_id
      LEFT JOIN tb_product_info pi ON p.product_id = pi.product_id AND pi.node_id = target.node_id
    WHERE
      p.product_group = ANY(v_product_auth)
      AND target.GROUP_id = ANY(i_group_id_arr)
    GROUP BY
      p.product_id
      , p.platform_type
  ;

END;
$$;


ALTER FUNCTION public.sp_get_v3_product_count(i_product_auth text, i_group_id_arr bigint[]) OWNER TO cppoltp;

--
-- Name: sp_get_v3master_config(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_v3master_config(i_v3_type text) RETURNS TABLE(query_group text, ahnlab_com_url text, seq text, locale text, file_seq text, file_name text)
    LANGUAGE plpgsql
    AS $_$
DECLARE
BEGIN
  RETURN QUERY
    SELECT ct.query_group, ct.ahnlab_com_url, ct.seq, ct.locale, ct.file_seq, ct.file_name
  FROM crosstab ($$
    SELECT 'query_group', config_key, config_value FROM (
      SELECT key AS config_key, value AS config_value FROM tb_config tc1 WHERE tc1.config_group = 'AHNLAB_COM_V3MASTER'
          UNION ALL
          SELECT 'file_seq', value FROM tb_config tc2
          WHERE tc2.config_group = 'AHNLAB_COM_V3MASTER_FILE_SEQ' AND tc2.key = $$||quote_literal(i_v3_type)||$$
          UNION ALL
          SELECT 'file_name', value FROM tb_config tc3
          WHERE tc3.config_group = 'AHNLAB_COM_V3MASTER_DOWNLOAD_FILE_NAME' AND tc3.key = $$||quote_literal(i_v3_type)||$$
  ) t ORDER BY 1
  $$,
  $$ VALUES ('ahnlab_com_url'), ('seq'), ('locale'), ('file_seq'), ('file_name')
  $$) AS ct ("query_group" TEXT, "ahnlab_com_url" text, "seq" text, "locale" text, "file_seq" text, "file_name" text);
END;
$_$;


