CREATE FUNCTION public.sp_get_vmagent_info(i_node_id bigint) RETURNS TABLE(integrated_server integer, vmagent_check integer, vmagent_count bigint, vmagent_index bigint, vmnode_count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
   check integer DEFAULT 0;
BEGIN
  RETURN QUERY
  SELECT 1 as integrated_server, vmhost.vmagent_check, count(tb_vmhost_node.host_id) as vmnode_count, vmhost.agent_index::bigint as vmagent_index, count(tb_vmhost_node.node_id) as vmagent_count FROM tb_vmhost_node,
  ( SELECT host_id, agent_index, ( CASE WHEN agent_index IS NOT NULL THEN 1 ELSE 0 END ) as vmagent_check FROM tb_vmhost_node where node_id = i_node_id ) AS vmhost
  WHERE tb_vmhost_node.host_id = vmhost.host_id
  GROUP BY vmhost.agent_index, vmhost.vmagent_check;

END;
$$;


