CREATE FUNCTION public.sp_get_widget(i_admin_id text) RETURNS TABLE(widget_id bigint, name text, group_id bigint, widget_layout text, correlation_rule_id bigint, admin_id text, widget_item_id bigint, widget_item_type public.en_widget_item_type, widget_item_layout text, modified_time text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY

   SELECT w.widget_id
         ,w.name
         ,w.group_id
         ,w.layout AS widget_layout
         ,w.correlation_rule_id
         ,w.admin_id
         ,wi.item_id AS widget_item_id
         ,wi.widget_item_type
         ,wi.layout AS widget_item_layout
         ,wi.modified_time ::text
    FROM tb_widget w
   INNER join tb_widget_item wi
      ON w.widget_id = wi.widget_id and w.admin_id = i_admin_id
   INNER join tb_admin a
      ON a.admin_id = w.admin_id
      ;

END;
$$;


