--
-- Name: sp_get_widget_data(text, bigint, public.en_widget_item_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_get_widget_data(i_login_admin_id text, i_widget_id bigint, i_widget_item_type public.en_widget_item_type) RETURNS TABLE(group_id text, correlation_rule_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  IF (NOT EXISTS (SELECT 1 FROM tb_widget AS w WHERE w.widget_id = i_widget_id)) THEN
    RETURN;
  ELSIF (NOT EXISTS (SELECT 1 FROM tb_widget AS w WHERE w.widget_id = i_widget_id AND w.admin_id = i_login_admin_id)) THEN
    RAISE EXCEPTION 'You do not have permission.' USING HINT = 'DB-00022';
  ELSIF (NOT EXISTS (SELECT 1 FROM tb_widget_item AS w WHERE w.widget_id = i_widget_id AND w.widget_item_type = i_widget_item_type)) THEN
    RAISE EXCEPTION 'Use after registration of the widget.' USING HINT = 'DB-00042';
  END IF;


  RETURN QUERY
    SELECT
      w.group_id::text
      , w.correlation_rule_id::text
    FROM tb_widget AS w
    WHERE w.widget_id = i_widget_id;

END;
$$;


