--
-- Name: sp_getpgagentlist(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_getpgagentlist() RETURNS TABLE(type xml)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
   -- SELECT xmlelement(name AgentList, XMLAGG(xmlelement(name Agent,
    SELECT xmlelement(name Agent,
    xmlattributes(t.node_id AS node_id,
                  t.connection_status,
                  t.ip AS IP,
            t.IP_Connected AS IP_Connected,
                  t.y AS year,
                  t.m AS month,
                  t.d AS day,
                  t.h AS hour,
                  t.min AS MINUTE,
                  t.sec AS second,
                  t.server_time AS server_time)
    )
    from
    (
        SELECT n.node_id,
               ns.connection_status,
               n.ip,
               n.IP_Connected,
        TEXT(date_part('year', ns.server_time)) y,
        TEXT(date_part('month', ns.server_time)) m,
        TEXT(date_part('day', ns.server_time)) d,
        TEXT(date_part('hour', ns.server_time)) h,
        TEXT(date_part('min', ns.server_time)) min,
        ceil(date_part('second', ns.server_time)) sec,
        to_char(ns.server_time at time zone 'UTC', 'YYYY-MM-DD HH24:MI:SS.MS') server_time
        FROM TB_NODE n, tb_node_status ns WHERE n.node_id = ns.node_id
        AND n.is_removed = FALSE
    ) t;
END;
$$;


