--
-- Name: sp_group_node_by_dept(text, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_group_node_by_dept(i_group_path text, i_target_nodes bigint[]) RETURNS TABLE(node_id bigint[])
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_base_group_id             bigint := (SELECT group_id FROM tb_group WHERE group_type = 'PHYSICAL' LIMIT 1);
  v_group_order               bigint := (SELECT MAX(group_order) + 1 FROM tb_group WHERE is_removed = FALSE);
  v_default_group_id          bigint := (SELECT group_id FROM tb_group WHERE group_type = 'DEFAULT' LIMIT 1);

  v_target                    bigint[];
BEGIN

  v_target := sp_preprocess_auto_grouping(i_target_nodes);

  IF v_target IS NOT NULL THEN
    -- get group_id from base group_path (create or get)
    v_base_group_id := sp_get_or_create_group_path(i_group_path, v_base_group_id, v_group_order);

    -- update group_id in tb_node that department is not null and not empty
    WITH wt_dept_list AS (
      SELECT u.department, sp_get_or_create_group_path(u.department, v_base_group_id, v_group_order) AS group_id
      FROM (
        SELECT DISTINCT BTRIM(u.department) AS department
        FROM tb_user AS u
        JOIN tb_node AS n ON u.node_id = n.node_id AND n.is_removed = FALSE
        WHERE u.node_id = ANY(v_target)
          AND u.department IS NOT NULL
          AND LENGTH(BTRIM(u.department)) > 0
      ) AS u
    ), wt_node_list AS (
      SELECT n.node_id, MAX(COALESCE(wt.group_id, v_default_group_id)) AS group_id
      FROM (
        SELECT n.node_id, BTRIM(u.department) AS department
        FROM tb_node AS n
        LEFT JOIN tb_user AS u ON n.node_id = u.node_id
        WHERE n.node_id = ANY(v_target)
          AND n.is_removed = FALSE
      ) AS n
      LEFT JOIN wt_dept_list AS wt ON n.department = wt.department
      GROUP BY n.node_id
    ), wt_update_node_list AS (
      UPDATE tb_node n
        SET group_id  = wt.group_id
      FROM wt_node_list AS wt
      WHERE n.node_id = wt.node_id
        AND n.group_id <> wt.group_id
      RETURNING n.node_id
    )
    SELECT ARRAY_AGG(wt.node_id) INTO v_target
    FROM wt_update_node_list AS wt;

    -- tb_node_policy 적용
    PERFORM sp_set_agent_policy_apply(v_target);

    -- tb_file_update_server 적용
    PERFORM sp_set_agent_file_update_server(v_target);
  END IF;

  RETURN QUERY
    SELECT v_target;

END;
$$;


ALTER FUNCTION public.sp_group_node_by_dept(i_group_path text, i_target_nodes bigint[]) OWNER TO cppoltp;

--
-- Name: sp_group_node_by_ipv4(text, bigint[], boolean, inet); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_group_node_by_ipv4(i_group_path text, i_target_nodes bigint[], i_by_connected boolean, i_mask inet) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_base_group_id             bigint := (SELECT group_id FROM tb_group WHERE group_type = 'PHYSICAL' LIMIT 1);
  v_group_order               bigint := (SELECT MAX(group_order) + 1 FROM tb_group WHERE is_removed = FALSE);
  v_default_group_id          bigint := (SELECT group_id FROM tb_group WHERE group_type = 'DEFAULT' LIMIT 1);

  v_target                    bigint[];
  v_group_id                  bigint[];
BEGIN

  v_target := sp_preprocess_auto_grouping(i_target_nodes);

  IF v_target IS NOT NULL THEN
    -- get group_id from base group_path (create or get)
    v_base_group_id := sp_get_or_create_group_path(i_group_path, v_base_group_id, v_group_order);

    WITH wt_node_ip AS (
      SELECT DISTINCT host(n.ip & i_mask) AS class
      FROM (
        SELECT n.node_id, CASE WHEN i_by_connected THEN n.ip_connected ELSE n.ip END AS ip
        FROM tb_node AS n
      ) AS n
      WHERE n.node_id = ANY(v_target)
        AND family(n.ip) = 4
    ),
    -- find existing class group
    wt_existing_group AS (
      SELECT g.group_id, g.name
      FROM tb_group AS g
      JOIN wt_node_ip AS wt ON g.name = wt.class
      WHERE g.pgroup_id = v_base_group_id
        AND g.is_removed = false
    ),
    -- recover removed bclass group
    wt_recovered_group AS (
      UPDATE tb_group g
        SET is_removed = false
      FROM wt_node_ip AS wt
      WHERE g.pgroup_id = v_base_group_id
        AND g.is_removed = true
        AND g.name = wt.class
      RETURNING group_id, name
    ),
    -- set group policy to default
    wt_recovered_group_policy AS (
      SELECT wt.group_id, gp.product_feature_id, gp.policy_id, now()
      FROM wt_recovered_group AS wt, tb_group_policy AS gp
      WHERE gp.group_id = v_base_group_id
      ON CONFLICT (group_id, product_feature_id) DO UPDATE SET policy_id = EXCLUDED.policy_id, modified_time = EXCLUDED.modified_time
    ),
    -- create new class tb_group
    wt_new_group AS (
      SELECT wt.class, v_base_group_id, 'GENERAL'::en_group_type, FALSE, v_group_order
      FROM wt_node_ip AS wt
      WHERE NOT EXISTS (
        SELECT group_id, name FROM wt_existing_group
        UNION
        SELECT group_id, name FROM wt_recovered_group
      )
      RETURNING group_id, name
    ),
    -- set group policy to default
    wt_new_group_policy AS (
      SELECT wt.group_id, gp.product_feature_id, gp.policy_id, now()
      FROM wt_new_group AS wt, tb_group_policy AS gp
      WHERE gp.group_id = v_base_group_id
      ON CONFLICT (group_id, product_feature_id) DO UPDATE SET policy_id = EXCLUDED.policy_id, modified_time = EXCLUDED.modified_time
    ),
    -- union all bclass group
    wt_class_group AS (
      SELECT group_id, name FROM wt_existing_group
      UNION
      SELECT group_id, name FROM wt_new_group
      UNION
      SELECT group_id, name FROM wt_recovered_group
    )
    UPDATE tb_node n
      SET group_id = wt.group_id
    FROM wt_class_group AS wt
    WHERE n.node_id = ANY(v_target)
      AND wt.name = host(CASE WHEN i_by_connected THEN ip_connected ELSE ip END & i_mask);

    -- to default group
    UPDATE tb_node n
      SET group_id = v_default_group_id
    WHERE n.node_id = ANY(v_target)
      AND family(CASE WHEN i_by_connected THEN ip_connected ELSE ip END) <> 4;

    -- tb_node_policy 적용
    PERFORM sp_set_agent_policy_apply(v_target);

    -- tb_file_update_server group 설정
    SELECT ARRAY_AGG(g.group_id) INTO v_group_id
    FROM (
      SELECT DISTINCT g.group_id
      FROM tb_node AS n
      JOIN tb_group AS g ON n.group_id = g.group_id
      WHERE n.node_id = ANY(v_target)
    ) AS g;

    PERFORM sp_set_group_file_update_server(v_group_id);

    -- tb_file_update_server 적용
    PERFORM sp_set_agent_file_update_server(v_target);
  END IF;

  RETURN v_target;

END;
$$;


ALTER FUNCTION public.sp_group_node_by_ipv4(i_group_path text, i_target_nodes bigint[], i_by_connected boolean, i_mask inet) OWNER TO cppoltp;

--
-- Name: sp_group_node_by_ipv4_b_c_class(text, bigint[], boolean); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_group_node_by_ipv4_b_c_class(i_group_path text, i_target_nodes bigint[], i_by_connected boolean) RETURNS TABLE(node_id bigint[])
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_base_group_id             bigint := (SELECT group_id FROM tb_group WHERE group_type = 'PHYSICAL' LIMIT 1);
  v_group_order               bigint := (SELECT MAX(group_order) + 1 FROM tb_group WHERE is_removed = FALSE);
  v_default_group_id          bigint := (SELECT group_id FROM tb_group WHERE group_type = 'DEFAULT' LIMIT 1);

  v_target                    bigint[];
  v_bclass_group_id           bigint[];
  v_cclass_group_id           bigint[];
BEGIN

  v_target := sp_preprocess_auto_grouping(i_target_nodes);

  IF v_target IS NOT NULL THEN
    -- get group_id from base group_path (create or get)
    v_base_group_id := sp_get_or_create_group_path(i_group_path, v_base_group_id, v_group_order);

    WITH wt_node_ip AS (
      SELECT DISTINCT host(ip & '255.255.255.0') AS cclass, host(ip & '255.255.0.0') AS bclass
      FROM (
        SELECT n.node_id, CASE WHEN i_by_connected THEN n.ip_connected ELSE n.ip END AS ip
        FROM tb_node n
      ) AS n
      WHERE n.node_id = ANY(v_target)
        AND family(n.ip) = 4
    ),
    -- find existing bclass group
    wt_existing_bclass_group AS (
      SELECT g.group_id, g.name, g.pgroup_id
      FROM tb_group AS g
      JOIN wt_node_ip AS wt ON g.name = wt.bclass
      WHERE g.pgroup_id = v_base_group_id
        AND g.is_removed = false
    ),
    -- recover removed bclass group
    wt_recovered_bclass_group AS (
      UPDATE tb_group g
        SET is_removed = false
      FROM wt_node_ip AS wt
      WHERE g.pgroup_id = v_base_group_id
        AND g.is_removed = true
        AND g.name = wt.bclass
      RETURNING group_id, name, pgroup_id
    ),
    -- create new bclass tb_group
    wt_new_bclass_group AS (
      SELECT ng.bclass, v_base_group_id, 'GENERAL'::en_group_type, FALSE, v_group_order
      FROM (
        SELECT DISTINCT wt.bclass
        FROM wt_node_ip AS wt
        EXCEPT
        SELECT name FROM wt_existing_bclass_group
        EXCEPT
        SELECT name FROM wt_recovered_bclass_group
      ) AS ng
      RETURNING group_id, name, pgroup_id
    ),
    -- union all bclass group
    wt_bclass_group AS (
      SELECT group_id, name, pgroup_id FROM wt_existing_bclass_group
      UNION
      SELECT group_id, name, pgroup_id FROM wt_new_bclass_group
      UNION
      SELECT group_id, name, pgroup_id FROM wt_recovered_bclass_group
    ),
    -- set group policy to default
    wt_bclass_group_policy AS (
      SELECT wt.group_id, gp.product_feature_id, gp.policy_id, now()
      FROM (
        SELECT wt.group_id, wt.pgroup_id FROM wt_new_bclass_group AS wt
        UNION
        SELECT wt.group_id, wt.pgroup_id FROM wt_recovered_bclass_group AS wt
      ) AS wt
      JOIN tb_group_policy AS gp ON gp.group_id = wt.pgroup_id
      ON CONFLICT (group_id, product_feature_id) DO UPDATE SET policy_id = EXCLUDED.policy_id, modified_time = EXCLUDED.modified_time
    ),
    -- find existing cclass group
    wt_existing_cclass_group AS (
      SELECT g.group_id, g.name, g.pgroup_id
      FROM tb_group AS g
      JOIN wt_node_ip AS wt ON g.pgroup_id = ANY(SELECT DISTINCT wt.group_id FROM wt_bclass_group AS wt) AND g.name = wt.cclass
      WHERE g.is_removed = false
    ),
    -- recover removed cclass group
    wt_recovered_cclass_group AS (
      UPDATE tb_group g
        SET is_removed = false
      FROM wt_node_ip AS wt
      JOIN wt_bclass_group AS b ON wt.bclass = b.name
      WHERE g.pgroup_id = b.group_id
        AND g.is_removed = true
        AND g.name = wt.cclass
      RETURNING g.group_id, g.name, g.pgroup_id
    ),
    -- create new cclass group
    wt_new_cclass_group AS (
      SELECT ng.cclass, ng.group_id, 'GENERAL'::en_group_type, FALSE, v_group_order
      FROM (
        SELECT DISTINCT wt.cclass, b.group_id
        FROM wt_node_ip AS wt
        JOIN wt_bclass_group AS b ON wt.bclass = b.name
        EXCEPT
        SELECT eg.name, eg.pgroup_id
        FROM wt_existing_cclass_group AS eg
        EXCEPT
        SELECT rg.name, rg.pgroup_id
        FROM wt_recovered_cclass_group AS rg
      ) AS ng
      RETURNING group_id, name, pgroup_id
    ),
    wt_cclass_group_policy AS (
      SELECT wt.group_id, gp.product_feature_id, gp.policy_id, now()
      FROM (
        SELECT wt.group_id, wt.pgroup_id FROM wt_new_cclass_group AS wt
        UNION
        SELECT wt.group_id, wt.pgroup_id FROM wt_recovered_cclass_group AS wt
      ) AS wt
      JOIN tb_group_policy AS gp ON gp.group_id = wt.pgroup_id
      ON CONFLICT (group_id, product_feature_id) DO UPDATE SET policy_id = EXCLUDED.policy_id, modified_time = EXCLUDED.modified_time
    ),
    -- union all cclass group
    wt_cclass_group AS (
      SELECT group_id, name, pgroup_id FROM wt_existing_cclass_group
      UNION
      SELECT group_id, name, pgroup_id FROM wt_new_cclass_group
      UNION
      SELECT group_id, name, pgroup_id FROM wt_recovered_cclass_group
    )
    UPDATE tb_node n
      SET group_id = wt.group_id
    FROM wt_cclass_group AS wt
    WHERE n.node_id = ANY(v_target)
      AND wt.name = host(CASE WHEN i_by_connected THEN n.ip_connected ELSE n.ip END & '255.255.255.0');

    -- to default group
    UPDATE tb_node n
      SET group_id = v_default_group_id
    WHERE n.node_id = ANY(v_target)
      AND family(CASE WHEN i_by_connected THEN n.ip_connected ELSE n.ip END) <> 4;


    -- 대상자 선정
    SELECT ARRAY_AGG(DISTINCT g.pgroup_id), ARRAY_AGG(DISTINCT g.group_id) INTO v_bclass_group_id, v_cclass_group_id
    FROM (
      SELECT DISTINCT g.pgroup_id, g.group_id
      FROM tb_node AS n
      JOIN tb_group AS g ON n.group_id = g.group_id
      WHERE n.node_id = ANY(v_target)
    ) AS g;


    -- tb_group_policy
    SELECT g.group_id, gp.product_feature_id, gp.policy_id, now()
    FROM tb_group AS g
    JOIN tb_group_policy AS gp ON g.pgroup_id = gp.group_id
    WHERE g.group_id = ANY(v_bclass_group_id) OR g.group_id = ANY(v_cclass_group_id)
    ON CONFLICT (group_id, product_feature_id) DO NOTHING;

    -- tb_node_policy 적용
    PERFORM sp_set_agent_policy_apply(v_target);


    -- 보조업데이트 서버 설정
    PERFORM sp_set_group_file_update_server(v_bclass_group_id);
    PERFORM sp_set_group_file_update_server(v_cclass_group_id);

    -- tb_file_update_server 적용
    PERFORM sp_set_agent_file_update_server(v_target);
  END IF;


  RETURN QUERY
    SELECT v_target;

END;
$$;


