-- Name: sp_if_condition(bigint[], text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_if_condition(i_object_id bigint[], i_original text, i_compare text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

	IF i_object_id IS NOT NULL THEN
		IF i_original IS NOT NULL THEN
			RETURN i_original;
		ELSE
			RETURN i_compare;
		END IF;
	ELSE
		IF i_compare IS NOT NULL THEN
			RETURN i_compare;
		ELSE
			RETURN i_original;
		END IF;
	END IF;

END;
$$;


