--
-- Name: sp_init_config_server(bigint, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_init_config_server(i_server_id bigint, i_ip text) RETURNS TABLE(server_id bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
v_server_id bigint;
v_r RECORD;
BEGIN

  IF ( SELECT count(1) FROM tb_server ) > 1 THEN
    UPDATE tb_server SET ip = i_ip WHERE server_id = i_server_id;
    RETURN QUERY
      SELECT i_server_id::bigint;
  ELSEIF ( SELECT count(1) FROM tb_server ) = 1 THEN
      -- change server ip
      SELECT t.server_id INTO v_server_id FROM tb_server t;
    UPDATE tb_server SET ip = i_ip;

    RETURN QUERY
      SELECT v_server_id::bigint;
  ELSE
      -- cleaning
    DELETE FROM tb_pkg_platform;
    DELETE FROM tb_pkg_platform;
    DELETE FROM tb_service;
    DELETE FROM tb_server;

    ALTER SEQUENCE tb_server_server_id_seq RESTART WITH 1;
    VALUES  ( 'MAIN', i_ip, '', now(), 'NORMAL')
    RETURNING tb_server.server_id INTO v_server_id;

     -- tb_service 등록
    FOR  v_r IN SELECT service_type FROM tb_service_port
    LOOP
      v_r.service_type,
      TRUE,
      now(),
      v_server_id,
      'ABNORMAL'
    );
    END LOOP;

    UPDATE tb_service SET static = TRUE WHERE service_type IN ( SELECT service_type FROM tb_service_port WHERE init_static IS TRUE OR always_static IS TRUE );

    UPDATE tb_server SET patch_version = ( SELECT value FROM  tb_config  WHERE config_group = 'UPDATE' AND KEY = 'server_version' ), current_version = ( SELECT value FROM  tb_config  WHERE config_group = 'UPDATE' AND KEY = 'server_version' );

      -- server_id를 리턴한다.
    RETURN QUERY
      SELECT v_server_id::bigint;
  END IF;
END;
$$;


ALTER FUNCTION public.sp_init_config_server(i_server_id bigint, i_ip text) OWNER TO cppoltp;

--
-- Name: sp_init_config_server_key(text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_init_config_server_key(i_ip text, i_server_key text) RETURNS TABLE(err_code text, err_msg text)
    LANGUAGE plpgsql
    AS $$
DECLARE
v_server_id bigint;

BEGIN

  IF NOT EXISTS ( SELECT 1 FROM tb_server WHERE ip = i_ip ) THEN
    RAISE EXCEPTION 'The server ip is not exists' USING HINT = 'DB-00027';
  END IF;

  UPDATE tb_server
  SET server_key = i_server_key, modified_time = now()
  WHERE ip = i_ip;

  RETURN QUERY
    SELECT 'DB-00000'::text, 'success'::text;
END;
$$;


ALTER FUNCTION public.sp_init_config_server_key(i_ip text, i_server_key text) OWNER TO cppoltp;

--
-- Name: sp_lock_inactive_admins(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_lock_inactive_admins(i_block_or_delete_on_long_term_inactivity text) RETURNS TABLE(admin_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  months_param integer;

BEGIN
  SELECT value::integer
  INTO months_param
  FROM tb_config
  WHERE config_group = 'LONG_TERM_INACTIVITY'
    AND key = 'set_long_term_inactivity_period';

    -- 삭제 또는 업데이트 전에 admin_id와 inactivity_period
  RETURN QUERY EXECUTE format(
    'SELECT admin_id
     FROM tb_admin
     WHERE login_time < NOW() - INTERVAL ''%s months''
	   OR modified_time < NOW() - INTERVAL ''%s months'' ',
    months_param, months_param
  );

  IF i_block_or_delete_on_long_term_inactivity = 'delete' THEN
    EXECUTE format(
      'DELETE FROM tb_admin
       WHERE login_time < NOW() - INTERVAL ''%s months''
	     OR modified_time < NOW() - INTERVAL ''%s months'' ',
      months_param, months_param
    );
  ELSE
    EXECUTE format(
      'UPDATE tb_admin
       SET lock_status = true, lock_type = ''LONG_TERM''
       WHERE login_time < NOW() - INTERVAL ''%s months''
	     OR modified_time < NOW() - INTERVAL ''%s months'' ',
      months_param, months_param
    );
  END IF;

END;
$$;


ALTER FUNCTION public.sp_lock_inactive_admins(i_block_or_delete_on_long_term_inactivity text) OWNER TO cppoltp;

--
-- Name: sp_make_email_contents(text, bigint[], public.en_correlation_condition_id_type[], text[], text, text, text, text[], boolean); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_make_email_contents(i_login_admin_id text, i_target_list bigint[], i_macro_type_list public.en_correlation_condition_id_type[], i_macro_value_list text[], i_mail_body text, i_correlation_name text, i_correlation_condition text, i_send_mail_list text[], i_is_admin boolean) RETURNS TABLE(mail_contents text)
    LANGUAGE plpgsql
    AS $_$

DECLARE
v_language en_language;
v_correlation_desc text;
v_user_name text;
v_department text;
v_mail_body text;
v_email_table_templete TEXT := '<table border=1 style="width:100%; margin:0; separate;border-spacing:0; outline:0;"><tr style="background-color:#E6E6E6">${macro_field}<th align="center">IP</th><th align="center">Computer Name</th><th align="center">${1}</th><th align="center">${2}</th></tr>${contents}</table>';

BEGIN

  SELECT a.language INTO v_language FROM tb_admin a WHERE a.admin_id = i_login_admin_id;


  -- TODO : 다국어 대응 나중에 디비 자원으로 변경 필요
  IF v_language = 'ko'::en_language THEN
    v_user_name := '사용자 이름';
    v_department := '부서';

  ELSEIF v_language = 'zh-Hans'::en_language THEN
    v_user_name := '用户 名';
    v_department := '部门';

  ELSEIF v_language = 'ja'::en_language THEN
    v_user_name := 'ユーザー名';
    v_department := '部門';

  ELSE
    v_user_name := 'USER NAME';
    v_department := 'DEPARTMENT';

  END IF;

  v_correlation_desc := (i_correlation_condition::json)->>(v_language::text);

  SELECT replace_recursive(i_mail_body,array[['${TITLE}',i_correlation_name], ['${CORRELATION_CONDITION}',v_correlation_desc]]) INTO v_mail_body;

  v_email_table_templete := replace(v_email_table_templete, '${1}', v_user_name);
  v_email_table_templete := replace(v_email_table_templete, '${2}', v_department);


  RETURN QUERY


  SELECT
    replace_recursive(v_mail_body, array_agg(array[macro_key, macro_value]))
  FROM
  (


    /* 메일 발송 유저 리스트 */
    SELECT
      '${USER_NAME}' AS macro_key
      , string_agg(email, ';') AS macro_value
    FROM
      UNNEST(i_send_mail_list) AS t(email)

    /* 유저 리스트 : 어드민일 경우 */
    UNION ALL
    SELECT DISTINCT
      org.macro_key
      , org.macro_value
    FROM(
      SELECT
        '${USER_LIST}' AS macro_key
        , replace(
            replace(v_email_table_templete, '${contents}', string_agg(
              concat('<tr>'
                , '<td align="center">', n.ip, '</td>'
                , '<td align="center">', n.computer_name, '</td>'
                , '<td align="center">', u.name, '</td>'
                , '<td align="center">', u.department, '</td>'
              , '</tr>'
              ), '')
            )
          , '${macro_field}'
          , '') AS macro_value
      FROM tb_node n
      LEFT JOIN tb_user u ON u.node_id = n.node_id
      WHERE EXISTS (
        SELECT 1 FROM UNNEST(i_target_list) AS t(node_id) WHERE t.node_id = n.node_id
      )
  ) org
    WHERE
      i_is_admin IS TRUE

    /* 유저 리스트 : 어드민이 아닐 경우 노출 제한 */
    UNION ALL
    SELECT
      '${USER_LIST}' AS macro_key
      , 'Limited information' AS macro_value
    WHERE
      i_is_admin IS FALSE


    /* 연계규칙 매크로 정보 */
    UNION ALL
    SELECT
      concat('${', t.cr_macro, '}') AS macro_keyword
      , replace(
          replace(v_email_table_templete, '${contents}', string_agg(
            concat('<tr>'
              , '<td align="center">', t.cr_value, '</td>'
              , '<td align="center">', t.ip, '</td>'
              , '<td align="center">', t.computer_name, '</td>'
              , '<td align="center">', u.name, '</td>'
              , '<td align="center">', u.department, '</td>'
            , '</tr>'
          ), '')
        )
        , '${macro_field}'
        , concat('<th align="center">', t.cr_macro, '</th>')
    ) AS macro_value
    FROM (
      SELECT
        cr_target
        , cr_macro
        , REPLACE(cr_value,';','<br>') AS cr_value
        , n.ip
        , n.computer_name
      FROM unnest( i_target_list, i_macro_type_list, i_macro_value_list ) t(cr_target, cr_macro, cr_value)
      JOIN tb_node n ON t.cr_target = n.node_id
    ) t
    LEFT JOIN tb_user u ON t.cr_target = u.node_id
    GROUP BY t.cr_macro


    /* 남은 매크로 공백 처리 */
    UNION ALL
    SELECT
      concat('${', t.macro, '}') AS macro_key
      , '' AS macro_value
    FROM
      UNNEST(ENUM_RANGE(NULL::en_correlation_condition_id_type)) t(macro)
    WHERE
      NOT EXISTS(
        SELECT cr.macro FROM UNNEST( i_macro_type_list ) cr(macro) WHERE t.macro = cr.macro
      )

  ) t

  ;


END;
$_$;


ALTER FUNCTION public.sp_make_email_contents(i_login_admin_id text, i_target_list bigint[], i_macro_type_list public.en_correlation_condition_id_type[], i_macro_value_list text[], i_mail_body text, i_correlation_name text, i_correlation_condition text, i_send_mail_list text[], i_is_admin boolean) OWNER TO cppoltp;

--
-- Name: sp_node_array_remove(bigint[], bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_node_array_remove(i_node_id bigint[], i_remove_node_id bigint[]) RETURNS text[]
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count                     text;
  v_node_id                   text;
BEGIN

  IF i_remove_node_id IS NULL THEN
    SELECT COUNT(1)::text, STRING_AGG(t.node_id::text, ',') FROM UNNEST(i_node_id) t(node_id) INTO v_count, v_node_id;
  ELSE
    SELECT COUNT(1)::text, STRING_AGG(t.node_id::text, ',') FROM UNNEST(i_node_id) t(node_id) WHERE NOT t.node_id = ANY(i_remove_node_id) INTO v_count, v_node_id;
  END IF;

  RETURN ARRAY[v_count, v_node_id];

END;
$$;


ALTER FUNCTION public.sp_node_array_remove(i_node_id bigint[], i_remove_node_id bigint[]) OWNER TO cppoltp;

--
-- Name: sp_preprocess_auto_grouping(bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_preprocess_auto_grouping(i_target_nodes bigint[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_config                    json;
  v_target                    bigint[];
  v_exception_node_id         bigint[];

  v_group_id                  bigint;
  v_virtual_default_group_id  bigint;
BEGIN

  SELECT jsonb_object_agg(key, value) INTO v_config FROM sp_get_config_group_list('GROUPING'::en_config_group);

  -- 자동그룹핑의 조건이 연결된 에이전트이고 예외그룹이 설정되어 있으면 노드 목록에서 예외 그룹에 속한 에이전트를 제외한다.
  IF v_config->>'auto_grouping_target' = 'connected_agent' AND COALESCE(v_config->>'auto_grouping_exception_group_id', '') <> '' THEN
    -- 예외그룹에 속한 에이전트 구하기
    FOREACH v_group_id IN ARRAY STRING_TO_ARRAY(v_config->>'auto_grouping_exception_group_id',',')::bigint[] LOOP
      SELECT ARRAY_CAT(v_exception_node_id, n.node_id::bigint[]) INTO v_exception_node_id
      FROM sp_get_group_node_list(v_group_id, TRUE, NULL) AS n;
    END LOOP;

    SELECT ARRAY_AGG(n.node_id) INTO v_target
    FROM UNNEST(i_target_nodes) AS n(node_id)
    WHERE NOT EXISTS (
      SELECT 1 FROM UNNEST(v_exception_node_id) AS t(node_id) WHERE t.node_id = n.node_id
    );
  ELSE
    v_target := i_target_nodes;
  END IF;

  RETURN v_target;

END;
$$;


ALTER FUNCTION public.sp_preprocess_auto_grouping(i_target_nodes bigint[]) OWNER TO cppoltp;

--
-- Name: sp_preprocess_tb_v3_device_log_obj_id(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_preprocess_tb_v3_device_log_obj_id() RETURNS TABLE(error_code text, error_msg text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_max_row_number            bigint;
  v_batch_sleep               integer;
BEGIN

  SELECT COALESCE(MAX(row_number), 0) INTO v_max_row_number
  FROM tb_v3_device_log_obj_id;

  WITH vw_log_obj_id AS (
    SELECT obj_id, ROW_NUMBER() OVER(ORDER BY obj_id) AS row_number
    FROM tb_pre_v3_device_log_obj_id
  )
  UPDATE tb_pre_v3_device_log_obj_id vl SET row_number = (lo.row_number + v_max_row_number)
  FROM vw_log_obj_id AS lo
  WHERE lo.obj_id = vl.obj_id;

  SELECT obj_id, row_number
  FROM tb_pre_v3_device_log_obj_id
  ON CONFLICT (obj_id) DO NOTHING;

  v_batch_sleep := sp_get_config_group_key_value('GENERAL', 'batch_sleep', '0')::integer;
  PERFORM pg_catalog.pg_sleep(v_batch_sleep);

  RETURN QUERY select '0'::text, 'SUCCESS'::text;

END;
$$;


ALTER FUNCTION public.sp_preprocess_tb_v3_device_log_obj_id() OWNER TO cppoltp;

