CREATE FUNCTION public.sp_query_dept_info(i_node_id bigint, i_query_type text, i_query_value text) RETURNS TABLE(department text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

-- return dummy data.
IF (i_query_type = 'DEPT_NAME') THEN

  RETURN QUERY
    SELECT
    u.department
    FROM
      tb_user u
    WHERE
      u.department ILIKE '%' || i_query_value || '%';
ELSE

  RETURN QUERY SELECT ''::text, ''::text, ''::text, ''::text, ''::text, 'false'::text;

END IF;

END;
$$;


