--
-- Name: sp_query_user_info(bigint, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_query_user_info(i_node_id bigint, i_query_type text, i_query_value text) RETURNS TABLE(name text, department text, phone text, email text, empno text, modified_by_admin text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

-- return dummy data.
IF (i_query_type = 'USER_NAME') THEN

  RETURN QUERY
    SELECT
      u.name
      , u.department
      , u.phone
      , u.email
      , u.empno
      , u.modified_by_admin::text
    FROM
      tb_user u
    WHERE
      u.name = i_query_value;

ELSEIF (i_query_type = 'EMP_NO') THEN

  RETURN QUERY
    SELECT
      u.name
      , u.department
      , u.phone
      , u.email
      , u.empno
      , u.modified_by_admin::text
    FROM
      tb_user u
    WHERE
      u.empno = i_query_value;

ELSE

  RETURN QUERY SELECT ''::text, ''::text, ''::text, ''::text, ''::text, 'false'::text;

END IF;

END;
$$;


ALTER FUNCTION public.sp_query_user_info(i_node_id bigint, i_query_type text, i_query_value text) OWNER TO cppoltp;

--
-- Name: sp_register_node(text, public.en_machine_type, text, inet); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_register_node(i_machine_uuid text, i_machine_type public.en_machine_type, i_group_id text, i_ip_connected inet) RETURNS TABLE(node_id text, otp_hint text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_node_id                   bigint    DEFAULT 0;
  v_install_time              timestamp;
  v_group_id                  bigint    DEFAULT CASE WHEN TRIM(i_group_id) = '' THEN 0 ELSE i_group_id::bigint END;
  v_default_group_id          bigint := (SELECT group_id FROM tb_group WHERE is_removed IS FALSE AND group_type = 'DEFAULT' LIMIT 1);
BEGIN

  -- group_id 처리하기
  IF (NOT EXISTS (SELECT 1 FROM tb_group AS g WHERE g.group_type = 'GENERAL' AND g.group_id = v_group_id AND sp_check_removed_group(g.group_id) = FALSE)) THEN
      v_group_id := v_default_group_id;
  END IF;

  -- 기본 등록여부 판단
  -- CWPP-2916 : 기존 node 등록여부 체크 시 machine_type 조건 제거( AND n.machine_type = i_machine_type )
  IF (NOT EXISTS (SELECT 1 FROM tb_node AS n WHERE n.machine_uuid = i_machine_uuid)) THEN
    -- open api로 등록한 case 체크
  	IF (EXISTS (SELECT 1 FROM tb_node AS n WHERE n.machine_uuid IS NULL AND n.machine_type IS NULL AND n.platform_id = 'UNKNOWN_EXTERNAL'::en_platform_id_type AND ip_connected = i_ip_connected)) THEN
	  	UPDATE tb_node
	  	SET machine_uuid = i_machine_uuid
	  		, machine_type = i_machine_type
        , group_id = CASE WHEN sp_check_removed_group(tb_node.group_id) THEN v_group_id ELSE tb_node.group_id END
	  		, install_time = now()
	  		, modified_time = now()
	  	WHERE	machine_uuid IS NULL 
	  	AND   	machine_type IS NULL 
	  	AND		platform_id = 'UNKNOWN_EXTERNAL'::en_platform_id_type
	  	AND		ip_connected = i_ip_connected
      RETURNING tb_node.node_id, tb_node.install_time, tb_node.group_id INTO v_node_id, v_install_time, v_group_id;
  	ELSE
	      machine_uuid, machine_type, group_id, ip_connected, platform_id, is_removed, install_time, modified_time
	    ) VALUES(
	      i_machine_uuid, i_machine_type, v_group_id, i_ip_connected, 'UNKNOWN', true, now(), now()
	    )
	    RETURNING tb_node.node_id, tb_node.install_time INTO v_node_id, v_install_time;
	
	    -- 클라우스 시스템 노드 상태 등록(tb.node_status)
	    IF i_machine_type = 'CLOUD_AWS' OR i_machine_type = 'CLOUD_AZURE' OR i_machine_type = 'CLOUD_ALIBABA' THEN
	        node_id, connection_status
	      ) VALUES (
	        v_node_id, 'UNINSTALLED'::en_connection_status);
	    END IF;
	
	    -- 에이전트 정책 INSERT
	      SELECT v_node_id, gp.product_feature_id, gp.policy_id, false, now()
	      FROM tb_group_policy gp
	      WHERE gp.group_id = v_group_id;
	  	END IF;
  	
  ELSE
    -- machine_uuid가 존재하면 node_id가 존재하므로
    -- (CWPP-3236) 중복 machine_uuid가 존재(CWPP-2916 적용전에 해당)할 수 있으므로 조건에 맞는 node_id 선택(조건 : is_removed, install_time), machine_type 업데이트
    SELECT target.node_id INTO v_node_id
    FROM (
      SELECT
        node.node_id AS node_id
        , ROW_NUMBER() OVER (PARTITION BY node.machine_uuid ORDER BY CASE WHEN node.is_removed IS FALSE THEN 1 ELSE 2 END ASC, node.install_time DESC) AS rnum
      FROM tb_node AS node
      WHERE node.machine_uuid = i_machine_uuid
    ) AS target
    WHERE target.rnum = 1;

    IF i_machine_type = 'CLOUD_AWS' OR i_machine_type = 'CLOUD_AZURE' OR i_machine_type = 'CLOUD_ALIBABA' THEN
      UPDATE tb_node
      SET
        group_id = CASE WHEN sp_check_removed_group(tb_node.group_id) THEN v_group_id ELSE tb_node.group_id END
        , ip_connected = i_ip_connected
        , is_removed = (CASE WHEN platform_id IS NULL THEN true ELSE false END)
        , removed_time = NULL
        , modified_time = NOW()
        , machine_type = i_machine_type
      WHERE machine_uuid = i_machine_uuid
        AND tb_node.node_id = v_node_id
      -- AND machine_type = i_machine_type -- CWPP-2916 : machine_type 조건 제거
      RETURNING tb_node.node_id, tb_node.install_time, tb_node.group_id INTO v_node_id, v_install_time, v_group_id;
    ELSE
      UPDATE tb_node
      SET group_id = (CASE WHEN sp_check_removed_group(tb_node.group_id) THEN v_group_id ELSE tb_node.group_id END)
        , ip_connected = i_ip_connected
        , is_removed = (CASE WHEN (platform_id IS NULL) OR (platform_id = 'UNKNOWN') THEN true ELSE false END) -- 물리시스템인 경우 UNKNOWN도 is_removed를 true로 처리
        , removed_time = NULL
        , modified_time = NOW()
        , machine_type = i_machine_type
      WHERE machine_uuid = i_machine_uuid
        AND tb_node.node_id = v_node_id
      -- AND machine_type = i_machine_type -- CWPP-2916 : machine_type 조건 제거
      RETURNING tb_node.node_id, tb_node.install_time, tb_node.group_id INTO v_node_id, v_install_time, v_group_id;
    END IF;

    UPDATE tb_node_policy np
    SET policy_id = gp.policy_id
    FROM tb_group_policy gp
    WHERE gp.group_id = v_group_id
      AND np.node_id = v_node_id
      AND np.product_feature_id = gp.product_feature_id
      AND NOT(np.keep_agent_policy);

  END IF;

  RETURN QUERY
    SELECT v_node_id::text, v_install_time::text;

END;
$$;


ALTER FUNCTION public.sp_register_node(i_machine_uuid text, i_machine_type public.en_machine_type, i_group_id text, i_ip_connected inet) OWNER TO cppoltp;

--
-- Name: sp_register_product(bigint, public.en_product_id_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_register_product(i_node_id bigint, i_product_id public.en_product_id_type) RETURNS TABLE(response integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_product_id                en_product_id_type[];
BEGIN

  SELECT ARRAY_AGG(p.product_id) INTO v_product_id FROM tb_product AS p WHERE p.product_group = 'V3';

  IF v_product_id @> ARRAY[i_product_id] THEN
    DELETE FROM tb_product_info WHERE node_id = i_node_id AND product_id = ANY(v_product_id) AND product_id <> i_product_id;
  END IF;

  ON CONFLICT (node_id, product_id) DO NOTHING;

  RETURN query SELECT 0 LIMIT 0;

END;
$$;


ALTER FUNCTION public.sp_register_product(i_node_id bigint, i_product_id public.en_product_id_type) OWNER TO cppoltp;

--
-- Name: sp_remove_ac_agent_policy(bigint, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_remove_ac_agent_policy(i_policy_id bigint, i_admin_id text) RETURNS TABLE(policy_id bigint, product_feature_id public.en_product_feature_id_type, group_id text, node_id text)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_product_feature_id en_product_feature_id_type;
  v_privilege_profile_auth boolean;

BEGIN

SELECT p.product_feature_id
INTO v_product_feature_id
FROM tb_policy p
WHERE p.policy_id = i_policy_id;

SELECT
    EXISTS (
        SELECT
            1
        FROM
            tb_admin ta
        INNER JOIN
            tb_privilege_profile tpp
        ON
            ta.privilege_profile_id = tpp.privilege_profile_id 
        WHERE
            tpp.profile_body LIKE '%"/policy/policy_AC_A_W"%'
        AND
            ta.admin_id = i_admin_id
    ) INTO v_privilege_profile_auth;

IF v_product_feature_id IS NULL THEN

  RAISE EXCEPTION 'policy_id (%) does not exist.', i_policy_id USING HINT = 'DB-00031';

ELSIF v_product_feature_id <> 'AC_AGENT' THEN

  RAISE EXCEPTION 'policy_id (%) is not AC_AGENT policy.', i_policy_id USING HINT = 'DB-00030';

END IF;

IF v_privilege_profile_auth = FALSE THEN
  RAISE EXCEPTION 'You do not have permission to delete policy' USING HINT = 'DB-00085';
END IF;

  RETURN QUERY
  SELECT rp.policy_id
        ,rp.product_feature_id
        ,rp.group_id
        ,rp.node_id
  FROM sp_remove_policy(i_policy_id) rp;

END;
$$;


