--
-- Name: sp_remove_admin(text, text[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_remove_admin(i_login_admin_id text, i_admin_id text[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_profile_type              en_privilege_profile_type;
BEGIN

  -- login_admin_id 의 권한 가져오기
  v_profile_type := sp_get_admin_privilege_type( i_login_admin_id );

  IF v_profile_type = 'TEMP_ADMIN' THEN
    IF i_login_admin_id <> 'cpp' THEN
      RAISE EXCEPTION 'You do not have permission.' USING HINT = 'DB-00022';
    END IF;
  ELSIF v_profile_type = 'PRODUCT_ADMIN' THEN
    IF (EXISTS (SELECT 1 FROM tb_admin AS a JOIN tb_privilege_profile AS p ON a.privilege_profile_id = p.privilege_profile_id WHERE a.admin_id = ANY(i_admin_id) AND p.profile_type <> 'SECMGR_ADMIN')) THEN
      RAISE EXCEPTION 'You do not have permission.' USING HINT = 'DB-00022';
    END IF;
  ELSIF v_profile_type IS NULL OR v_profile_type <> 'ROOT_ADMIN' THEN
    RAISE EXCEPTION 'You do not have permission.' USING HINT = 'DB-00022';
  END IF;

  FOR i IN 1..3 LOOP
        UPDATE tb_admin
        SET password = 0
        WHERE admin_id = ANY(i_admin_id);
  END LOOP;

  DELETE FROM tb_admin WHERE admin_id = ANY(i_admin_id);
  DELETE FROM tb_admin_pw_history WHERE admin_id = ANY(i_admin_id);
  DELETE FROM tb_login_fail_status WHERE admin_id = ANY(i_admin_id);
  UPDATE tb_correlation_rule SET custom_email = ARRAY_TO_STRING(array_diff(STRING_TO_ARRAY(custom_email, ';'), i_admin_id),';');

END;
$$;


