--

CREATE FUNCTION public.sp_remove_alert_template(i_alert_template_id bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE
BEGIN

  -- DB-00013 연계규칙에서 사용중인 건을 삭제 할 때
  IF (SELECT EXISTS (SELECT 1 FROM tb_correlation_rule AS cr WHERE cr.alert_template_id = i_alert_template_id )) THEN

    RAISE EXCEPTION 'alert template (%) cannot be removed.', i_alert_template_id USING HINT = 'DB-00013';

  ELSE

    DELETE
    FROM tb_alert_template AS at
    WHERE at.alert_template_id = i_alert_template_id;

  END IF;
END;
$$;


