--

CREATE FUNCTION public.sp_remove_artifacts_task_target(i_task_id bigint[], i_target_id bigint[], i_instance_id bigint[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

 DELETE FROM tb_task_target_status AS ts
 WHERE EXISTS (SELECT 1 
                 FROM UNNEST(i_task_id, i_target_id, i_instance_id) AS t(task_id, target_id, instance_id)
                WHERE ts.task_id = t.task_id AND ts.target_id = t.target_id AND ts.instance_id = t.instance_id); 
END;
$$;


