--

CREATE FUNCTION public.sp_remove_base_report_layout(i_login_admin_id text, i_base_report_id public.en_base_report_id_type, i_admin_id text[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_profile_type              en_privilege_profile_type;
BEGIN

  -- login_admin_id 의 권한 가져오기
  v_profile_type := sp_get_admin_privilege_type( i_login_admin_id );

  -- 권한 체크
  IF v_profile_type IS NULL OR v_profile_type <> 'ROOT_ADMIN' THEN
    IF (EXISTS (SELECT 1 FROM tb_base_report_layout AS b WHERE b.base_report_id = i_base_report_id AND b.admin_id = ANY(i_admin_id) AND b.admin_id <> i_login_admin_id)) THEN
      RAISE EXCEPTION 'You do not have permission.(%)', i_base_report_id USING HINT = 'DB-00022';
    END IF;
  END IF;


  DELETE FROM tb_base_report_layout WHERE base_report_id = i_base_report_id AND admin_id = ANY(i_admin_id);

END;
$$;


