--
-- Name: sp_remove_config_server(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_remove_config_server(i_server_id bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_server_status             en_server_status;
  v_service_count             integer := 0;
BEGIN

  -- 1. tb_server.server_status 가져오기
  SELECT s.server_status INTO v_server_status FROM tb_server AS s WHERE s.server_id = i_server_id;

  -- 2. tb_service 확인하기
  SELECT COUNT(1) INTO v_service_count
  FROM tb_service AS s
  WHERE s.server_id = i_server_id
    AND s.enabled IS TRUE
    AND NOT EXISTS (
      SELECT 1 FROM tb_service_port AS sp WHERE s.service_type = sp.service_type AND sp.count_type = 'ALL'
    );

  -- 서버 삭제시 해당 서버에 서비스가 등록되어 있으면 삭제 불가
  IF v_server_status <> 'ROLE_PENDING' OR v_service_count > 0 THEN
    RAISE EXCEPTION 'Service is registered on that server.' USING HINT = 'DB-00032';
  END IF;

  DELETE FROM tb_service WHERE server_id = i_server_id;
  DELETE FROM tb_server WHERE server_id = i_server_id;

END;
$$;


