--
-- Name: sp_remove_correlation_rule(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_remove_correlation_rule(i_correlation_rule_id bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE
BEGIN

/*
 * 1. tb_correlation_rule 연계규칙
 * 2. tb_correlation_task 연계규칙 대응 작업
 * 3. tb_correlation_rule_item 연계 규칙 항목
 * 4. tb_correlation_exclude 연계 규칙 대상 예외
 *
 * 5. tb_job
 * 6. tb_task
 * 7. tb_task_target
 */
  -- 1. tb_correlation_rule 연계규칙
--  IF (SELECT EXISTS (SELECT 1 FROM tb_correlation_rule AS cr WHERE cr.correlation_rule_id = i_correlation_rule_id )) THEN
-- 2. tb_correlation_task 연계규칙 대응 작업
IF (SELECT EXISTS (SELECT 1 FROM tb_correlation_task AS ct WHERE ct.correlation_rule_id = i_correlation_rule_id )) THEN
  DELETE
  FROM tb_correlation_task AS ct
  WHERE ct.correlation_rule_id = i_correlation_rule_id;
END IF;

-- 3. tb_correlation_rule_item 연계 규칙 항목
IF (SELECT EXISTS (SELECT 1 FROM tb_correlation_rule_item AS cri WHERE cri.correlation_rule_id = i_correlation_rule_id)) THEN
  DELETE
  FROM tb_correlation_rule_item AS cri
  WHERE cri.correlation_rule_id = i_correlation_rule_id;
END IF;

-- 4. tb_correlation_exclude 연계 규칙 대상 예외 ( exclude_type = 'NODE' : 2017.08.01현스팩상 예외대상은 에이전트단위로 등록되므로 where조건에 선언함 )
IF (SELECT EXISTS (SELECT 1 FROM tb_correlation_exclude AS ce WHERE ce.correlation_rule_id = i_correlation_rule_id AND ce.exclude_type = 'NODE' )) THEN
  DELETE
  FROM tb_correlation_exclude AS ce
  WHERE ce.correlation_rule_id = i_correlation_rule_id
  AND ce.exclude_type = 'NODE';
END IF;

-- 5. tb_job
IF (SELECT EXISTS (SELECT 1 FROM tb_job AS j WHERE j.correlation_rule_id = i_correlation_rule_id )) THEN

  -- 6. tb_task
  IF (SELECT EXISTS (SELECT 1 FROM tb_task AS t WHERE EXISTS( SELECT 1 FROM tb_job AS j WHERE j.correlation_rule_id  = i_correlation_rule_id  AND j.job_id = t.job_id ))) THEN
      -- 7. tb_task_target
    DELETE
    FROM tb_task_target AS tt
    WHERE EXISTS(
      SELECT 1
      FROM tb_task AS t
      WHERE EXISTS(
        SELECT 1
        FROM tb_job AS j
        WHERE j.correlation_rule_id  = i_correlation_rule_id
        AND j.job_id = t.job_id
      )
      AND t.task_id = tt.task_id
    );

    DELETE
    FROM tb_task AS t
    WHERE EXISTS(
      SELECT 1
      FROM tb_job AS j
      WHERE j.correlation_rule_id  = i_correlation_rule_id
      AND j.job_id = t.job_id
    );
  END IF;

  DELETE
  FROM tb_job AS j
  WHERE j.correlation_rule_id  = i_correlation_rule_id;
END IF;

-- 1. tb_correlation_rule 연계규칙
DELETE
FROM tb_correlation_rule AS cr
WHERE cr.correlation_rule_id = i_correlation_rule_id;
--  END IF;

  -- 연계 규칙 동기화 업데이트, shkang : 2018. 06. 28
  UPDATE tb_server SET need_correlation_refresh = true;

END;
$$;


