    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  -- admin_id 체크
  IF (EXISTS (SELECT 1 FROM tb_admin AS a WHERE a.privilege_profile_id = ANY(i_privilege_profile_id))) THEN
