--
-- Name: sp_remove_group(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_remove_group(i_group_id bigint) RETURNS TABLE(group_id text, node_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_group_type en_group_type;
  v_subgroup_count bigint;
  v_default_group_id bigint;
  v_node_id bigint[];

BEGIN

  SELECT g.group_type
  INTO v_group_type
  FROM tb_group g
  WHERE g.group_id = i_group_id;

  SELECT count(*)
  INTO v_subgroup_count
  FROM tb_group g
  WHERE g.pgroup_id = i_group_id
    AND g.is_removed IS NOT true;

  IF v_group_type IS NULL THEN

    RAISE EXCEPTION 'group does not exist.' USING HINT = 'DB-00011';

  ELSIF v_group_type = 'TOP' THEN

    RAISE EXCEPTION 'top group cannot remove.' USING HINT = 'DB-00010';

  ELSIF v_group_type <> 'GENERAL' THEN

    RAISE EXCEPTION 'group cannot remove.' USING HINT = 'DB-00004';

  ELSIF v_subgroup_count > 0 THEN

    RAISE EXCEPTION 'child group exist.' USING HINT = 'DB-00012';

  ELSE

    SELECT g.group_id
    INTO v_default_group_id
    FROM tb_group g
    WHERE g.group_type = 'DEFAULT';

    SELECT array_agg(n.node_id)
    INTO v_node_id
    FROM tb_node n
    WHERE n.group_id = i_group_id;

    -- 그룹에 설정된 보조 업데이트 서버 삭제
    DELETE FROM tb_file_update_server
    WHERE target_type = 'NODE'
      AND target_id = ANY(v_node_id);

    DELETE FROM tb_file_update_server
    WHERE target_type = 'GROUP'
      AND target_id = i_group_id;

    -- 그룹 UPDATE
    UPDATE tb_group g
    SET is_removed = true
    WHERE g.group_id = i_group_id;

  END IF;

  RETURN QUERY
  SELECT v_default_group_id::text, v_node_id::text;

END;
$$;


ALTER FUNCTION public.sp_remove_group(i_group_id bigint) OWNER TO cppoltp;

--
-- Name: sp_remove_group_node(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_remove_group_node(i_group_id bigint, i_node_id bigint[]) RETURNS TABLE(err_code text, err_msg text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_node_id    bigint;
BEGIN

-- 노드ID에서 그룹ID 삭제
FOREACH v_node_id IN ARRAY i_node_id
LOOP

  UPDATE tb_node
  SET group_id = null
  WHERE node_id = v_node_id
    AND is_removed = FALSE
    ;

END LOOP;

RETURN QUERY SELECT 'DB-00000'::text, 'success'::text;

END;
$$;


ALTER FUNCTION public.sp_remove_group_node(i_group_id bigint, i_node_id bigint[]) OWNER TO cppoltp;

--
-- Name: sp_remove_hips_agent_policy(bigint, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_remove_hips_agent_policy(i_policy_id bigint, i_admin_id text) RETURNS TABLE(policy_id bigint, product_feature_id public.en_product_feature_id_type, group_id text, node_id text)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_product_feature_id en_product_feature_id_type;
  v_privilege_profile_auth boolean;

BEGIN

SELECT p.product_feature_id
INTO v_product_feature_id
FROM tb_policy p
WHERE p.policy_id = i_policy_id;

SELECT
    EXISTS (
        SELECT
            1
        FROM
            tb_admin ta
        INNER JOIN
            tb_privilege_profile tpp
        ON
            ta.privilege_profile_id = tpp.privilege_profile_id 
        WHERE
            tpp.profile_body LIKE '%"/policy/policy_HIPS_A_W"%'
        AND
            ta.admin_id = i_admin_id
    ) INTO v_privilege_profile_auth;

IF v_product_feature_id IS NULL THEN

  RAISE EXCEPTION 'policy_id (%) does not exist.', i_policy_id USING HINT = 'DB-00031';

ELSIF v_product_feature_id <> 'HIPS_AGENT' THEN

  RAISE EXCEPTION 'policy_id (%) is not HIPS_AGENT policy.', i_policy_id USING HINT = 'DB-00030';

END IF;

IF v_privilege_profile_auth = FALSE THEN
  RAISE EXCEPTION 'You do not have permission to delete policy' USING HINT = 'DB-00085';
END IF;

  RETURN QUERY
  SELECT rp.policy_id
        ,rp.product_feature_id
        ,rp.group_id
        ,rp.node_id
  FROM sp_remove_policy(i_policy_id) rp;

END;
$$;


