     err_msg';


--
-- Name: sp_remove_policy(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_remove_policy(i_policy_id bigint) RETURNS TABLE(policy_id bigint, product_feature_id public.en_product_feature_id_type, group_id text, node_id text)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_agent_change text;
  v_policy_type en_policy_type;
  v_product_feature_id en_product_feature_id_type;
  v_default_policy_id bigint;
  v_group_id bigint[];
  v_node_id bigint[];

BEGIN

  SELECT p.policy_type, p.product_feature_id INTO v_policy_type, v_product_feature_id
  FROM tb_policy p
  WHERE p.policy_id = i_policy_id;

  IF v_policy_type = 'FACTORY' THEN
    RAISE EXCEPTION 'policy (%) cannot be removed.', i_policy_id USING HINT = 'DB-00026';
  ELSIF v_policy_type = 'DEFAULT' THEN
    RAISE EXCEPTION 'policy (%) cannot be removed.', i_policy_id USING HINT = 'DB-00027';
  END IF;

  -- 개별정책 처리여부
  SELECT c.value INTO v_agent_change
  FROM tb_config c
  WHERE c.config_group = 'GROUPING'
  AND c.key = 'apply_policy_on_group_change';

  -- 기본정책
  SELECT p.policy_id INTO v_default_policy_id
  FROM tb_policy p
  WHERE p.policy_type = 'DEFAULT'
    AND p.product_feature_id = v_product_feature_id;

  -- 삭제 여부에 관계없이 삭제할 정책을 사용하는 모든 그룹 조회
  SELECT array_agg(gp.group_id) INTO v_group_id
  FROM tb_group_policy gp
  WHERE gp.policy_id = i_policy_id;

  -- 삭제 여부에 관계없이 삭제할 정책을 사용하는 모든 에이전트 조회
  SELECT array_agg(np.node_id) INTO v_node_id
  FROM tb_node_policy np
  WHERE np.policy_id = i_policy_id;

  UPDATE tb_group_policy gp
  SET policy_id = v_default_policy_id
    , modified_time = NOW()
  WHERE gp.group_id IN (SELECT * FROM unnest(v_group_id))
    AND gp.product_feature_id = v_product_feature_id;

  UPDATE tb_node_policy np
  SET policy_id = v_default_policy_id
    , keep_agent_policy = FALSE
    , modified_time = NOW()
  WHERE np.node_id IN (SELECT * FROM unnest(v_node_id))
    AND np.product_feature_id = v_product_feature_id;

  --정책 삭제
  DELETE FROM tb_policy p
  WHERE p.policy_id = i_policy_id;

  RETURN QUERY
    SELECT v_default_policy_id, v_product_feature_id, v_group_id::text, v_node_id::text;

END;
$$;


ALTER FUNCTION public.sp_remove_policy(i_policy_id bigint) OWNER TO cppoltp;

