-- Name: sp_remove_query_report(text, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_remove_query_report(i_login_admin_id text, i_query_report_id bigint[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_profile_type              en_privilege_profile_type;
BEGIN

  -- login_admin_id 의 권한 가져오기
  v_profile_type := sp_get_admin_privilege_type( i_login_admin_id );

  -- 권한 체크
  IF v_profile_type IS NULL OR v_profile_type <> 'ROOT_ADMIN' THEN
    IF (EXISTS (SELECT 1 FROM tb_query_report AS q WHERE q.query_report_id = ANY(i_query_report_id) AND q.admin_id <> i_login_admin_id)) THEN
      RAISE EXCEPTION 'You do not have permission.(%)', i_query_report_id USING HINT = 'DB-00022';
    END IF;
  END IF;


  -- tb_report_schedule.is_removed = true 로 변경
  UPDATE tb_report_schedule SET is_removed = true WHERE query_report_id = ANY(i_query_report_id);

  DELETE FROM tb_query_report_item WHERE query_report_id = ANY(i_query_report_id);
  DELETE FROM tb_query_report WHERE query_report_id = ANY(i_query_report_id);

END;
$$;


