-- Name: sp_remove_report_schedule(text, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_remove_report_schedule(i_login_admin_id text, i_report_schedule_id bigint[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_profile_type              en_privilege_profile_type;
BEGIN

  -- login_admin_id 의 권한 가져오기
  v_profile_type := sp_get_admin_privilege_type( i_login_admin_id );

  -- 권한 체크
  IF v_profile_type IS NULL OR v_profile_type <> 'ROOT_ADMIN' THEN
    IF (SELECT EXISTS (SELECT 1 FROM tb_report_schedule AS r WHERE r.report_schedule_id = ANY(i_report_schedule_id) AND r.admin_id <> i_login_admin_id)) = true THEN
      RAISE EXCEPTION 'You do not have permission.(%)', i_report_schedule_id USING HINT = 'DB-00022';
    END IF;
  END IF;

  UPDATE tb_report_schedule AS r
    SET admin_id = i_login_admin_id, modified_time = now(), is_removed = TRUE
  WHERE r.admin_id = CASE WHEN v_profile_type = 'ROOT_ADMIN' THEN r.admin_id ELSE i_login_admin_id END
    AND r.report_schedule_id = ANY(i_report_schedule_id);

END;
$$;


