--
-- Name: sp_remove_task(text, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_remove_task(i_login_admin_id text, i_task_id bigint[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_job_id                    text;
  v_task_id                   text;
  v_job_id_array              bigint[];
  v_task_id_array             bigint[];
BEGIN

  PERFORM sp_check_task( i_login_admin_id, i_task_id, 'CANCEL' );

  -- 실시간 명령 가져오기
  BEGIN
    SELECT STRING_AGG(t.job_id::text, ','), STRING_AGG(t.task_id::text, ',') INTO v_job_id, v_task_id
    FROM tb_task AS t
    JOIN tb_job AS j ON t.job_id = j.job_id AND j.is_schedule = false
    WHERE t.task_id = ANY(i_task_id);
  EXCEPTION
    WHEN OTHERS THEN
      v_job_id := '';
      v_task_id := '';
  END;

  -- 실시간 명령 삭제
  IF v_job_id <> '' THEN
    v_job_id_array := STRING_TO_ARRAY(v_job_id, ',')::bigint[];
    v_task_id_array := STRING_TO_ARRAY(v_task_id, ',')::bigint[];

    DELETE FROM tb_task_target WHERE task_id = ANY(v_task_id_array);

    DELETE FROM tb_task WHERE task_id = ANY(v_task_id_array);

    DELETE FROM tb_job AS j
    WHERE j.job_id = ANY(v_job_id_array)
      AND NOT EXISTS (
        SELECT 1 FROM tb_task AS t WHERE t.job_id = j.job_id
      );
  END IF;

END;
$$;


ALTER FUNCTION public.sp_remove_task(i_login_admin_id text, i_task_id bigint[]) OWNER TO cppoltp;

