-- Name: FUNCTION sp_remove_task(i_login_admin_id text, i_task_id bigint[]); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_remove_task(i_login_admin_id text, i_task_id bigint[]) IS '
@brief [SWK-SCI1010] 실행된 Task 삭제하기
@in -
@out -
@return - void';


--
-- Name: sp_remove_task_schedule(text, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_remove_task_schedule(i_admin_id text, i_task_id bigint[]) RETURNS TABLE(del_count bigint, job_id bigint[], task_id bigint[], instance_id bigint[])
    LANGUAGE plpgsql
    AS $$

DECLARE
  v_del_cnt bigint;
  v_tb_job_id bigint[];
  v_tb_task_id bigint[];
  v_tb_instance_id bigint[];
BEGIN
  /* check : job_id */
  SELECT ARRAY_AGG(t.job_id) INTO v_tb_job_id FROM tb_task AS t WHERE t.task_id = ANY(i_task_id);

  /* check : is_schedule */
  IF EXISTS (SELECT 1 FROM tb_job as j WHERE j.is_schedule IS NOT TRUE AND j.job_id = ANY(v_tb_job_id)) THEN
    RAISE EXCEPTION 'request data is no scheduled job.' USING HINT = 'DB-90001';
  END IF ;

  /* check : privilege */
  IF NOT EXISTS (SELECT 1 FROM tb_admin JOIN tb_privilege_profile USING( privilege_profile_id ) WHERE profile_type = 'ROOT_ADMIN' AND admin_id = i_admin_id) AND
         EXISTS (SELECT 1 FROM tb_job as j WHERE j.admin_id <> i_admin_id AND j.job_id = ANY(v_tb_job_id))
  THEN
    RAISE EXCEPTION 'You do not have permission.(%)', i_task_id USING HINT = 'DB-00022';
  END IF ;

  /* get instance_id */
  SELECT ARRAY_AGG(ti.task_id), ARRAY_AGG(ti.instance_id)
   INTO v_tb_task_id, v_tb_instance_id
   FROM tb_task_instance AS ti
  WHERE ti.task_id = ANY(i_task_id) ;

  /* delete : tb_task_target */
  DELETE FROM tb_task_target AS tt WHERE tt.task_id = ANY(i_task_id);

  /* delete : tb_task_instance */
  DELETE FROM tb_task_instance AS ti WHERE ti.task_id = ANY(i_task_id);

  /* delete : tb_task */
  DELETE FROM tb_task AS t WHERE t.task_id = ANY(i_task_id);
  GET DIAGNOSTICS v_del_cnt = ROW_COUNT;

  /* delete : tb_job */
  DELETE FROM tb_job AS j WHERE j.job_id = ANY(v_tb_job_id) ;

  RETURN QUERY SELECT v_del_cnt, v_tb_job_id, v_tb_task_id, v_tb_instance_id;

END;
$$;


ALTER FUNCTION public.sp_remove_task_schedule(i_admin_id text, i_task_id bigint[]) OWNER TO cppoltp;

