--
-- Name: sp_remove_update_pkg(text, public.en_pkg_type, character varying); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_remove_update_pkg(i_server_ip text, i_pkg_type public.en_pkg_type, i_pkg_version character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_server_id bigint;
  v_product_pkg_id bigint;
BEGIN
  select server_id into v_server_id from tb_server where tb_server.ip = i_server_ip;
  select product_pkg_id into v_product_pkg_id FROM tb_product_pkg WHERE tb_product_pkg.pkg_type = i_pkg_type and tb_product_pkg.version = i_pkg_version and tb_product_pkg.is_removed is false;

  IF( ( v_server_id IS NOT NULL ) AND ( v_server_id IS NOT NULL ) ) THEN
    DELETE FROM tb_pkg_server
    WHERE tb_pkg_server.product_pkg_id = v_product_pkg_id and tb_pkg_server.server_id = v_server_id;

    IF NOT EXISTS (select 1 from tb_pkg_server where tb_pkg_server.product_pkg_id = v_product_pkg_id ) THEN
      -- DELETE FROM tb_product_pkg
      -- WHERE tb_product_pkg.product_pkg_id = v_product_pkg_id;
      UPDATE tb_product_pkg SET is_removed = TRUE
      WHERE tb_product_pkg.product_pkg_id = v_product_pkg_id;
    END IF;
  END IF;

END;
$$;


ALTER FUNCTION public.sp_remove_update_pkg(i_server_ip text, i_pkg_type public.en_pkg_type, i_pkg_version character varying) OWNER TO cppoltp;

