--
-- Name: sp_remove_v3_linux_policy(bigint, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_remove_v3_linux_policy(i_policy_id bigint, i_admin_id text) RETURNS TABLE(policy_id bigint, product_feature_id public.en_product_feature_id_type, group_id text, node_id text)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_product_feature_id en_product_feature_id_type;
  v_update_policy_id bigint;
  v_privilege_profile_auth boolean;

BEGIN

SELECT p.product_feature_id
INTO v_product_feature_id
FROM tb_policy p
WHERE p.policy_id = i_policy_id;

SELECT
    EXISTS (
        SELECT
            1
        FROM
            tb_admin ta
        INNER JOIN
            tb_privilege_profile tpp
        ON
            ta.privilege_profile_id = tpp.privilege_profile_id 
        WHERE
            tpp.profile_body LIKE '%"/policy/policy_V3L_W"%'
        AND
            ta.admin_id = i_admin_id
    ) INTO v_privilege_profile_auth;

IF v_product_feature_id IS NULL THEN

  RAISE EXCEPTION 'policy_id (%) does not exist.', i_policy_id USING HINT = 'DB-00031';

ELSIF v_product_feature_id <> 'V3NET_LU_AV' THEN

  RAISE EXCEPTION 'policy_id (%) is not V3NET_LU_AV policy.', i_policy_id USING HINT = 'DB-00030';

END IF;

IF v_privilege_profile_auth = FALSE THEN
  RAISE EXCEPTION 'You do not have permission to delete policy' USING HINT = 'DB-00085';
END IF;

  SELECT p.policy_id
  INTO v_update_policy_id
  FROM tb_policy p
  WHERE p.ppolicy_id = i_policy_id;

  RETURN QUERY
  SELECT rup.policy_id
        ,rup.product_feature_id
        ,rup.group_id
        ,rup.node_id
  FROM sp_remove_policy(v_update_policy_id) rup
  UNION ALL
  SELECT rp.policy_id
        ,rp.product_feature_id
        ,rp.group_id
        ,rp.node_id
  FROM sp_remove_policy(i_policy_id) rp;

END;
$$;


ALTER FUNCTION public.sp_remove_v3_linux_policy(i_policy_id bigint, i_admin_id text) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_remove_v3_linux_policy(i_policy_id bigint, i_admin_id text); Type: COMMENT; Schema: public; Owner: cppoltp
--

