--
-- Name: sp_remove_widget(bigint, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_remove_widget(i_widget_id bigint, i_dashboard_layout text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE

v_admin_id text;

BEGIN
    --admin_id 조회
    SELECT admin_id into v_admin_id
      FROM tb_widget
     WHERE widget_id = i_widget_id;

    -- tb_widget_item 삭제
    DELETE FROM tb_widget_item
     WHERE widget_id = i_widget_id;

    -- tb_widget 삭제
    DELETE FROM tb_widget
     WHERE widget_id = i_widget_id;

END;
$$;


ALTER FUNCTION public.sp_remove_widget(i_widget_id bigint, i_dashboard_layout text) OWNER TO cppoltp;

