CREATE FUNCTION public.sp_rename_enum_value(i_typename text, i_from text, i_to text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN

-- development helper proc
UPDATE pg_enum SET enumlabel = i_to
WHERE enumlabel = i_from AND enumtypid = (
SELECT oid FROM pg_type WHERE typname = i_typename
);

END;
$$;


