--
-- Name: sp_reset_non_shard_status(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_reset_non_shard_status(i_batch_uuid text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  UPDATE tb_etl_map SET batch_status = 'READY', start_time = null, end_time = null
  WHERE is_shard = FALSE
    AND (batch_uuid = i_batch_uuid OR batch_uuid IS NULL);

END;
$$;


ALTER FUNCTION public.sp_reset_non_shard_status(i_batch_uuid text) OWNER TO cppoltp;

--
-- Name: sp_reset_shard_status(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_reset_shard_status(i_shard_uuid text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  UPDATE tb_shard_map SET shard_status = 'READY' WHERE shard_uuid = i_shard_uuid;
  UPDATE tb_shard_map SET shard_status = 'READY', shard_uuid = null WHERE shard_uuid NOT IN (SELECT shard_uuid FROM tb_server);

  UPDATE tb_etl_map SET batch_status = 'READY', start_time = null, end_time = null
    WHERE is_shard = TRUE
      AND (batch_uuid = i_shard_uuid OR batch_uuid IS NULL);

END;
$$;


ALTER FUNCTION public.sp_reset_shard_status(i_shard_uuid text) OWNER TO cppoltp;

--
-- Name: sp_risk_group(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_risk_group() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_unconnected_period    BIGINT;
BEGIN
  SELECT tc.value::BIGINT INTO v_unconnected_period 
  FROM tb_config AS tc
  WHERE tc.config_group = 'AGENT_RISK_GROUP' AND tc.key = 'unconnected_period' LIMIT 1;

  UPDATE tb_node AS tn
   SET 
       group_id = (
       				SELECT group_id 
       			    FROM 
	       				tb_group 
	       			WHERE 
	       				group_type = 'GENERAL' AND name = '%DEFAULT_RISK_GROUP_NAME%'
	       			)
  FROM 
   		tb_node_status AS tns
  WHERE 
   		tn.node_id = tns.node_id 
  AND
        tns.connection_status = 'DISCONNECTED'
  AND 
  		now() - tns.server_time > concat(v_unconnected_period, 'day')::INTERVAL;		
END;
$$;


ALTER FUNCTION public.sp_risk_group() OWNER TO cppoltp;

