@out -
@return - void';


--
-- Name: sp_risk_group_clean(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_risk_group_clean() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_group_id BIGINT[];
BEGIN
   UPDATE 
 		tb_node AS tn
   SET is_removed = true
   FROM 
   		tb_group AS tg
   WHERE 
   		tn.group_id = tg.group_id 
   and
	   tg.group_type = 'GENERAL' AND tg.name = '%DEFAULT_RISK_GROUP_NAME%';
END;
$$;


