--
-- Name: sp_set_action_count(text, bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_action_count(i_action_name text, i_hit_count bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_update_cnt bigint;
BEGIN
  UPDATE tb_action_count
  SET
    hit_count = hit_count + i_hit_count
    , modified_time = now()
  WHERE action_name = i_action_name;
  GET DIAGNOSTICS v_update_cnt = ROW_COUNT;

  IF (v_update_cnt < 1) THEN
      action_name, hit_count, modified_time
    ) VALUES (
      i_action_name, i_hit_count, now()
    );
  END IF;
END;
$$;


ALTER FUNCTION public.sp_set_action_count(i_action_name text, i_hit_count bigint) OWNER TO cppoltp;

