ALTER FUNCTION public.sp_set_admin(i_login_admin_id text, i_admin_id text, i_password text, i_name text, i_privilege_profile_id bigint, i_manager_group_id bigint, i_product_auth public.en_product_group_type[], i_admin_group text, i_pw_due integer, i_connect_ip_range text, i_connect_dofw text, i_connect_time_start text, i_connect_time_end text, i_timeout_value integer, i_auth_wait_time integer, i_computer_name text, i_email text, i_phone text, i_use_otp boolean, i_description text) OWNER TO cppoltp;

--
-- Name: sp_set_admin(text, text, text, text, bigint, bigint, public.en_product_group_type[], text, integer, text, text, text, text, integer, integer, text, text, text, boolean, text, boolean); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_admin(i_login_admin_id text, i_admin_id text, i_password text, i_name text, i_privilege_profile_id bigint, i_manager_group_id bigint, i_product_auth public.en_product_group_type[], i_admin_group text, i_pw_due integer, i_connect_ip_range text, i_connect_dofw text, i_connect_time_start text, i_connect_time_end text, i_timeout_value integer, i_auth_wait_time integer, i_computer_name text, i_email text, i_phone text, i_use_otp boolean, i_description text, i_use_connect_ip boolean) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_profile_type              en_privilege_profile_type;
  v_admin_profile_type        en_privilege_profile_type;
  v_top_group_id              bigint;
  v_admin_group               text := i_admin_group;
  v_manager_group_id          bigint := i_manager_group_id;
  v_privilege_profile_id      bigint := i_privilege_profile_id;
BEGIN

  -- login_admin_id 의 권한 가져오기
  v_profile_type := sp_get_admin_privilege_type( i_login_admin_id );

  IF i_login_admin_id = 'cpp' OR v_profile_type IS NULL THEN
    RAISE EXCEPTION 'You do not have permission.' USING HINT = 'DB-00022';
  END IF;

  -- 변경하고자 하는 사용자가 서버관리자일때 서버관리자의 권한은 변경 못하도록 처리해야 한다.
  IF (SELECT COUNT(1) FROM tb_admin AS a JOIN tb_privilege_profile AS p ON p.privilege_profile_id = a.privilege_profile_id AND p.profile_type = 'ROOT_ADMIN') = 1 THEN
    IF (SELECT privilege_profile_id FROM tb_admin WHERE admin_id = i_admin_id) = (SELECT privilege_profile_id FROM tb_privilege_profile WHERE profile_type = 'ROOT_ADMIN' LIMIT 1)
      AND (SELECT privilege_profile_id FROM tb_admin WHERE admin_id = i_admin_id) <> i_privilege_profile_id THEN

      RAISE EXCEPTION 'You do not have permission.' USING HINT = 'DB-00022';
    END IF;
  END IF;
  
  -- 사용자 정의 관리자는 수정 권한 없음. CWPP-1486
  IF('CUSTOM_ADMIN') = (SELECT p.profile_type FROM tb_admin a JOIN tb_privilege_profile p ON (a.privilege_profile_id = p.privilege_profile_id) WHERE admin_id = i_login_admin_id) THEN
    RAISE EXCEPTION 'You do not have permission.' USING HINT = 'DB-00022';
  END IF;

  -- 패스워드 변경시 패스워드 변경
  IF i_password IS NOT NULL AND i_password <> '' THEN
    PERFORM sp_set_admin_password(i_admin_id, i_password);
  END IF;

  -- 최상위 그룹 가져오기
  SELECT g.group_id INTO v_top_group_id FROM tb_group AS g WHERE g.group_type = 'TOP' LIMIT 1;

  -- 등록할 사용자의 권한을 가져온다.
  SELECT p.profile_type INTO v_admin_profile_type
  FROM tb_privilege_profile AS p
  WHERE p.privilege_profile_id = v_privilege_profile_id;

  --  부서관리자, 보안 관리자, 라이선스 관리자는 1.0.11 부터 생성, 수정을 지원하지 않는다.
  IF v_admin_profile_type IN ('DEPT_ADMIN', 'SECMGR_ADMIN', 'PRODUCT_ADMIN') THEN
    RAISE EXCEPTION 'DEPT_ADMIN and SECMGR_ADMIN are users that are no longer supported.' USING HINT = 'DB-00082';
  END IF;

  -- 사용자정의관리자가 아니면 사용자그룹을 최상위로 셋팅한다.
  IF v_admin_profile_type = 'CUSTOM_ADMIN' THEN
    IF v_admin_group IS NULL OR v_admin_group = '' THEN
      RAISE EXCEPTION 'Management department code does not exist.' USING HINT = 'DB-00016';
    ELSIF v_top_group_id = ANY( SELECT t.group_id FROM UNNEST(STRING_TO_ARRAY(i_admin_group, ',')::bigint[]) AS t(group_id) ) THEN
      RAISE EXCEPTION 'This is the top-level department code.(%)', i_admin_group USING HINT = 'DB-00017';
    END IF;
  ELSE
    v_admin_group := v_top_group_id;
  END IF;

  IF v_admin_profile_type = 'CUSTOM_ADMIN' THEN
    IF (SELECT EXISTS (SELECT 1 FROM tb_manager_group WHERE group_id = v_manager_group_id)) = FALSE THEN
      RAISE EXCEPTION 'Manager Group does not exist.' USING HINT = 'DB-00086';
    END IF;

    IF v_manager_group_id = 1 THEN
      RAISE EXCEPTION 'Custom admin cannot be assigned manager group id 1' USING HINT = 'DB-00087';
    END IF;

    v_admin_group := (SELECT node_group FROM tb_manager_group WHERE group_id = v_manager_group_id);
  END IF;

  -- 초기 사용자 ,서버관리자(최상위) ,정책관리자 , 일반관리자는 manager_group_id 를 1로 설정한다.
  IF v_admin_profile_type IN ('TEMP_ADMIN', 'ROOT_ADMIN', 'POLICY_ADMIN', 'MONITOR_ADMIN') THEN
    v_manager_group_id := 1;
  END IF;

  IF v_profile_type = 'ROOT_ADMIN' THEN

    UPDATE tb_admin
      SET name = i_name                                 /* 관리자 이름 */
        , pw_due = i_pw_due                             /* 패스워드 만료 기간 */
        , privilege_profile_id = i_privilege_profile_id /* 권한 코드 ID */
        , product_auth = null
        , admin_group = v_admin_group                   /* 사용자 그룹 */
        , connect_ip_range = i_connect_ip_range         /* 접속 가능 IP 주소 범위 */
        , connect_dofw = i_connect_dofw                 /* 접속 가능 요일 */
        , connect_time_start = i_connect_time_start     /* 접속 가능 시작 시간 */
        , connect_time_end = i_connect_time_end         /* 접속 가능 종료 시간 */
        , timeout_value = i_timeout_value               /* 접속 Timeout 시간 */
        , auth_wait_time = i_auth_wait_time             /* 로그인 인증 보류 시간 */
        , computer_name = i_computer_name               /* 관리자 컴퓨터 이름 */
        , email = i_email                               /* 관리자 Email */
        , phone = i_phone                               /* 관리자 핸드폰 */
        , use_otp = i_use_otp                           /* OTP 사용여부 */
        , description = i_description                   /* 설명 */
        , modified_time = now()                         /* 데이터 갱신 최종 시간 */
        , use_connect_ip = i_use_connect_ip             /* 로그인 허용 IP 제한 사용 여부 */
        , manager_group_id = v_manager_group_id         /* tb_manager_group 테이블의 그룹 ID */
    WHERE admin_id = i_admin_id;

  ELSE

    UPDATE tb_admin
      SET name = i_name                                 /* 관리자 이름 */
        , email = i_email                               /* 관리자 Email */
        , phone = i_phone                               /* 관리자 핸드폰 */
        , description = i_description                   /* 설명 */
        , modified_time = now()                         /* 데이터 갱신 최종 시간 */
        , product_auth = null
        , manager_group_id = v_manager_group_id         /* tb_manager_group 테이블의 그룹 ID */
    WHERE admin_id = i_admin_id;

  END IF;

END;
$$;


