CREATE FUNCTION public.sp_set_admin_by_self(i_login_admin_id text, i_admin_id text, i_name text, i_email text, i_phone text, i_description text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  IF i_login_admin_id <> i_admin_id THEN
    RAISE EXCEPTION 'You do not have permission.' USING HINT = 'DB-00022';
  END IF;

  UPDATE tb_admin
    SET name = i_name                                 /* 관리자 이름 */
      , email = i_email                               /* 관리자 Email */
      , phone = i_phone                               /* 관리자 핸드폰 */
      , description = i_description                   /* 설명 */
      , modified_time = now()                         /* 데이터 갱신 최종 시간 */
  WHERE admin_id = i_admin_id;

END;
$$;


