--

CREATE FUNCTION public.sp_set_agent_alive(i_node_id bigint, i_connection_status public.en_connection_status) RETURNS TABLE(response integer)
    LANGUAGE plpgsql
    AS $$
BEGIN

  VALUES (i_node_id, i_connection_status, now())
  ON CONFLICT (node_id) DO UPDATE SET connection_status = EXCLUDED.connection_status, server_time = EXCLUDED.server_time;

  VALUES(now(), i_node_id)
  ON CONFLICT ON CONSTRAINT tb_node_alive_daily_history_pkey DO NOTHING;

  RETURN query SELECT 0 LIMIT 0;

END;
$$;


