--
-- Name: sp_set_agent_command(bigint, bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_agent_command(i_task_id bigint, i_instance_id bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_task_target_product_id text;
  v_task_target_type text;
  v_task_type text;
BEGIN

  SELECT tt.task_target_product_id::text
        ,tt.task_target_type::text
        ,t.task_type::text
  INTO v_task_target_product_id
      ,v_task_target_type
      ,v_task_type
  FROM tb_task t
  JOIN tb_task_type tt
  ON t.task_type = tt.task_type
  WHERE t.task_id = i_task_id;

  IF v_task_target_type = 'NODE' THEN

    UPDATE tb_task_target tta
    SET payload = t.payload
    FROM (SELECT t.task_id
            ,t.target_id
            ,regexp_replace(ENCODE(CONVERT_TO((SELECT row_to_json(task) FROM (SELECT t.task_id, t.task_type, t.payload, t.update_task_result, t. update_task_result_from_product, t.server_context) task)::text, 'UTF-8'), 'base64'), E'[\\n\\r]+', '', 'g') AS payload
      FROM (SELECT tt.request_format_version
              ,tt.request_from
              ,tt.request_name
              ,tt.interface_id
              ,t.task_id
              ,tta.target_id
              ,tt.task_encoding
              ,tt.agent_task_type AS task_type
              ,tta.payload::json AS payload
              ,COALESCE(tt.update_task_result, 'true')::BOOLEAN AS update_task_result
              ,COALESCE(tt.send_product_log, 'false')::BOOLEAN AS update_task_result_from_product
              ,(SELECT json_object(array_cat(array_agg(sc.key), ARRAY['task_type','instance_id']), array_cat(array_agg(sc.value), ARRAY[t.task_type::text, i_instance_id::text])) FROM json_each_text(t.server_context_payload::json) AS sc) AS server_context
            FROM tb_task t
            JOIN tb_task_target tta
            ON t.task_id = tta.task_id
            JOIN tb_node n
            ON tta.target_id = n.node_id
            JOIN tb_task_type tt
            ON tt.task_type = t.task_type
            WHERE t.task_id = i_task_id) t) t
    WHERE tta.task_id = t.task_id
      AND tta.target_id = t.target_id
      AND tta.task_id = i_task_id;

  END IF;

END;
$$;


ALTER FUNCTION public.sp_set_agent_command(i_task_id bigint, i_instance_id bigint) OWNER TO cppoltp;

--
-- Name: sp_set_agent_disconnected(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_agent_disconnected() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN

  WITH disconnected_node_list AS (  -- 미연결 에이전트 상태 변경
    UPDATE
      tb_node_status node_status
    SET
      connection_status = 'DISCONNECTED'
    WHERE
      node_status.server_time < NOW() - (60 || ' minute')::INTERVAL
      AND node_status.connection_status <> 'UNINSTALLED'
    RETURNING node_status.node_id
  )
  , update_ac_disconnted_list AS ( -- AC 제품 상태 변경
      UPDATE tb_ac_status ac_status
      SET
        service_status = 'OFF'::en_product_service_status
        , server_time = NOW()
      WHERE
        EXISTS (SELECT 1 FROM disconnected_node_list WHERE node_id = ac_status.node_id)
  )
  UPDATE	-- HIPS 제품 상태 변경
    tb_hips_status hips_status
  SET
    service_status = 'OFF'::en_product_service_status
    , server_time = NOW()
  WHERE
    EXISTS (SELECT 1 FROM disconnected_node_list WHERE node_id = hips_status.node_id);

END;
$$;


ALTER FUNCTION public.sp_set_agent_disconnected() OWNER TO cppoltp;

--
-- Name: sp_set_agent_file_update_server(bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_agent_file_update_server(i_node_id bigint[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  -- 보조 서버 업데이트
  DELETE FROM tb_file_update_server WHERE target_type = 'NODE' AND specified = FALSE AND target_id = ANY(i_node_id);

  SELECT fus_nd.node_id, 'NODE', fus_nd.server_id, FALSE
  FROM (
    SELECT n.node_id, fus.server_id
    FROM tb_node AS n
    JOIN tb_file_update_server AS fus ON fus.target_type = 'GROUP' AND n.group_id = fus.target_id
    WHERE n.node_id = ANY(i_node_id)
  ) AS fus_nd
  ON CONFLICT(target_id, target_type, server_id) DO NOTHING;

END;
$$;


ALTER FUNCTION public.sp_set_agent_file_update_server(i_node_id bigint[]) OWNER TO cppoltp;

--
-- Name: sp_set_agent_info(bigint, public.en_node_hash_type, text, inet, text, text, text, text, public.en_language, text[], text, integer, timestamp with time zone, integer, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, inet); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_agent_info(i_node_id bigint, i_node_hash_type public.en_node_hash_type, i_hash_value text, i_ip inet, i_nt_domain text, i_computer_name text, i_login_id text, i_platform_id text, i_os_language public.en_language, i_multinic text[], i_agent_version text, i_agent_port integer, i_agent_install_time timestamp with time zone, i_tz_offset integer, i_system_uuid text, i_edition_id text, i_release_id text, i_architecture text, i_need_kb text, i_installed_kb text, i_display_version text, i_build_number text, i_host_uuid text, i_client_id text, i_container_service_type text, i_container_env text, i_container_id text, i_os_type text, i_k8s_host_os text, i_ip_connected inet) RETURNS TABLE(response integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_platform_id               en_platform_id_type;

  -- 연동 방식
  v_condition_column          TEXT;
  v_condition_value           TEXT;
  v_ghost_agent_use           TEXT;
  v_ghost_node_id             BIGINT;

  -- 인사정보 설정값
  v_asset_config              JSON := (SELECT JSONB_OBJECT_AGG(key, value) FROM tb_config WHERE config_group = 'ASSET_INFO');
BEGIN

    -- 정의 되지 않은 OS 의 경우
    IF NOT EXISTS(SELECT 1 FROM unnest(enum_range(NULL::en_platform_id_type)) t(type) WHERE type::TEXT = i_platform_id) THEN
      v_platform_id = 'UNKNOWN';
    ELSE
      v_platform_id = i_platform_id;
    END IF
    ;

    -- grouping 정보 UPDATEho
    -- [!!] install_time 은 otp_hint 로 사용되므로 수정되면 안됨ne, u.email,
    UPDATE tb_node
    SET ip = CASE WHEN i_ip = '0.0.0.0'::inet THEN ip ELSE i_ip END
      , group_id = CASE WHEN i_ip = '0.0.0.0'::inet THEN
                            (SELECT g.group_id FROM tb_group AS g WHERE g.group_type = 'DEFAULT' LIMIT 1)
                        ELSE group_id END
      , ip_connected = i_ip_connected
      , mac = i_multinic[1]
      , nt_domain = i_nt_domain
      , computer_name = i_computer_name
      , login_id = i_login_id
      , platform_id = v_platform_id
      , os_language = i_os_language
      , agent_version = i_agent_version
      , agent_port = i_agent_port
      , agent_install_time = i_agent_install_time
      , tz_offset = i_tz_offset
      , modified_time = now()
      , is_removed = false
      , removed_time = null
      , ambass_cid = i_client_id
      , container_service_type = i_container_service_type
      , container_env = i_container_env
      , container_id =  i_container_id
      , k8s_host_os = i_k8s_host_os
    WHERE node_id = i_node_id
    ;
    -- multinic 정보 DELETEe_
    DELETE FROM tb_node_nic
    WHERE node_id = i_node_id
    ;

    -- multinic 정보 INSERTe_
    SELECT i_node_id, nic, i_ip, now() FROM unnest(i_multinic) nic;

    -- NODE_INFO 해시 INSERT i
    ON conflict (node_id, node_hash_type) DO UPDATE SET hash_value = EXCLUDED.hash_value, modified_time = EXCLUDED.modified_time;

	  -- [CWPP-5670] 인사 정보 저장
    IF v_asset_config ->> 'usage' = 'true' THEN
          WITH VALID_ASSET_LIST AS (
            SELECT
              CASE WHEN ip iS NOT NULL
              THEN
                CASE WHEN 
                    POSITION('-' IN ip) > 0 AND (SELECT IS_VALID_IP(ip_arr[1]) AND IS_VALID_IP(ip_arr[2]) FROM STRING_TO_ARRAY(ip, '-') ip_arr)  -- 범위 IP
                    OR POSITION('/' IN ip) > 0 AND IS_VALID_IP(ip) -- CIDR  
                    OR IS_VALID_IP(ip) -- 단일 IP
                  THEN ip
                  ELSE NULL
                  END
              ELSE NULL
              END AS ip
              , CASE WHEN IS_VALID_IP(connected_ip)
                THEN connected_ip
                ELSE NULL
                END AS connected_ip
              , mac
              , hostname
              , department
              , description
            FROM
              tb_external_asset_list
          )
            SELECT 
              i_node_id AS node_id
              , asset.department
              , asset.description
              , false
            FROM
              VALID_ASSET_LIST asset
            LEFT JOIN 
              tb_user tu
            ON
              node_id = i_node_id
            WHERE
              (
                (v_asset_config ->> 'primary_key' = 'IP'
                AND asset.ip IS NOT NULL
                AND CASE WHEN POSITION('-' IN asset.ip) > 0 -- 범위 IP
                    THEN (SELECT ip_arr[1]::inet <= i_ip AND ip_arr[2]::inet >= i_ip FROM STRING_TO_ARRAY(asset.ip, '-') ip_arr)
                    WHEN POSITION('/' IN asset.ip) > 0 -- CIDR
                    THEN asset.ip::inet >>= i_ip
                    ELSE asset.ip::inet = i_ip
                  END
                )
                OR (v_asset_config ->> 'primary_key' = 'CONNECTED_IP' AND asset.connected_ip = HOST(i_ip_connected))
                OR (v_asset_config ->> 'primary_key' = 'HOSTNAME' AND asset.hostname = i_computer_name)
                OR (v_asset_config ->> 'primary_key' = 'MAC' AND asset.mac = i_multinic[1])
              )
              AND COALESCE(tu.modified_by_admin, FALSE) != TRUE
            LIMIT 1
          ON CONFLICT (node_id) DO UPDATE SET
            department = EXCLUDED.department
            , description = EXCLUDED.description;
    END IF;

    RETURN query SELECT 0 LIMIT 0;

END;
$$;


