--
-- Name: sp_set_agent_policy_apply(bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_agent_policy_apply(i_node_id bigint[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_agent_change              text;
  v_product_feature_id        en_product_feature_id_type;
BEGIN

  v_agent_change := sp_get_config_group_key_value('GROUPING', 'apply_policy_on_group_change');

  IF v_agent_change = 'all' THEN

    SELECT p.node_id, p.product_feature_id, p.policy_id, false, now()
    FROM (
      SELECT n.node_id, gp.product_feature_id, gp.policy_id
      FROM tb_group_policy AS gp
      JOIN tb_node AS n ON n.node_id = ANY(i_node_id) AND n.group_id = gp.group_id
    ) AS p
    ON CONFLICT (node_id, product_feature_id) DO UPDATE SET policy_id = EXCLUDED.policy_id, keep_agent_policy = EXCLUDED.keep_agent_policy, modified_time = EXCLUDED.modified_time;

  ELSE

    UPDATE tb_node_policy np
      SET policy_id = p.policy_id
        , modified_time = now()
    FROM (
      SELECT np.node_id, gp.product_feature_id, gp.policy_id
      FROM tb_node_policy AS np
      JOIN tb_node AS n ON n.node_id = ANY(i_node_id) AND np.keep_agent_policy = false AND np.node_id = n.node_id
      JOIN tb_group_policy AS gp ON n.group_id = gp.group_id AND np.product_feature_id = gp.product_feature_id AND np.policy_id <> gp.policy_id
    ) AS p
    WHERE np.node_id = p.node_id
      AND np.product_feature_id = p.product_feature_id;

    SELECT p.node_id, p.product_feature_id, p.policy_id, false, now()
    FROM (
      SELECT n.node_id, gp.product_feature_id, gp.policy_id
      FROM tb_group_policy AS gp
      JOIN tb_node AS n ON n.node_id = ANY(i_node_id) AND n.group_id = gp.group_id
    ) AS p
    WHERE NOT EXISTS (
      SELECT 1
      FROM tb_node_policy AS np
      WHERE np.node_id = p.node_id
        AND np.product_feature_id = p.product_feature_id
    )
    ON CONFLICT ON CONSTRAINT tb_node_policy_pkey DO NOTHING;

  END IF;

END;
$$;


ALTER FUNCTION public.sp_set_agent_policy_apply(i_node_id bigint[]) OWNER TO cppoltp;

--
-- Name: sp_set_agent_risk_group(boolean, integer, boolean, integer); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_agent_risk_group(i_unconnected_use boolean, i_unconnected_period integer, i_risk_group_clean_use boolean, i_risk_group_clean_period integer) RETURNS TABLE(schedule_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_keys            text[];
  v_values          text[];
  v_schedule_id    text := null;
BEGIN

  v_keys := ARRAY[ 'unconnected_use', 'unconnected_period', 'risk_group_clean_use', 'risk_group_clean_period'];
  v_values := ARRAY[ i_unconnected_use::text, i_unconnected_period::text, i_risk_group_clean_use::text, i_risk_group_clean_period::text ];

  PERFORM sp_set_configs( 'AGENT_RISK_GROUP', v_keys, v_values );
  
  IF i_unconnected_use IS TRUE then
    v_schedule_id := sp_add_unity_schedule( 'EMS', 'GROUP_RISK_CLEAN', 1, '{"repeat":{"daily":1},"basic_moment":{"year":"0","month":"0","week":"0","day":"0","hour":3,"minute":0,"second":0}}', FALSE, '/api/console/config/grouping/risk_group', null );
  ELSE
    v_schedule_id := sp_set_unity_schedule_disabled( 'GROUP_RISK_CLEAN', 1);
  END IF;
  
  RETURN QUERY
  SELECT v_schedule_id;
  
END;
$$;


