--
-- Name: sp_set_alert_correlation_rule(bigint, public.en_correlation_type, boolean, integer, text, public.en_comparison_operator, boolean, bigint, boolean, boolean, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_alert_correlation_rule(i_correlation_rule_id bigint, i_correlation_type public.en_correlation_type, i_is_enabled boolean, i_schedule_flag integer, i_values text, i_comparison_operator public.en_comparison_operator, i_send_mail boolean, i_alert_template_id bigint, i_send_notice boolean, i_send_log boolean, i_custom_email text, i_admin_id text) RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE
BEGIN
  --시스템 연계규칙일 경우
  IF i_correlation_type = 'SYSTEM_ALERT' THEN
  UPDATE tb_correlation_rule_item
     SET values = i_values,
         comparison_operator = i_comparison_operator
   WHERE correlation_rule_id = i_correlation_rule_id
     AND intersect_set = 1;

  UPDATE tb_correlation_rule
     SET is_enabled = i_is_enabled,
         send_mail = i_send_mail,
         alert_template_id = i_alert_template_id,
         send_notice = i_send_notice,
         custom_email = i_custom_email,
         admin_id = i_admin_id,
         send_log = i_send_log,
         modified_time = now()
   WHERE correlation_rule_id = i_correlation_rule_id;


    --에이전트 연계규칙일 경우
    IF (EXISTS(SELECT 1 FROM tb_correlation_rule WHERE correlation_rule_id = i_correlation_rule_id AND name = 'LICENSE_EXPIRE')) THEN
      UPDATE tb_product_license SET correlation_alret_sent = false;
    END IF;


    IF (EXISTS(SELECT 1 FROM tb_correlation_rule WHERE correlation_rule_id = i_correlation_rule_id AND name = 'CERTIFICATE_EXPIRE')) THEN
      UPDATE tb_config SET value = false::text WHERE config_group = 'SYS_NET_CERT' AND key = 'correlation_alret_sent';
    END IF;


  --에이전트 연계규칙일 경우
  ELSE
  UPDATE tb_correlation_rule
     SET is_enabled = i_is_enabled,
         admin_id = i_admin_id,
         modified_time = now()
   WHERE correlation_rule_id = i_correlation_rule_id;
  END IF;

  -- 연계 규칙 동기화 업데이트, shkang : 2018. 07. 16
  UPDATE tb_server SET need_correlation_refresh = true;

END;
$$;


