--
-- Name: sp_set_alert_template(bigint, text, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_alert_template(i_alert_template_id bigint, i_name text, i_body text, i_image text) RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE
BEGIN

-- alert_template name dup check
IF ((SELECT count(1) FROM tb_alert_template AS a WHERE a.alert_template_id != i_alert_template_id  AND a.name = i_name) > 0) THEN
  RAISE EXCEPTION 'The alert_template name already exists.' USING HINT = 'DB-00043';
END IF;

  UPDATE tb_alert_template
     SET name=i_name
       , body=i_body
       , image=i_image
   WHERE alert_template_id=i_alert_template_id;

END;
