--
-- Name: sp_set_amc_mgmt_policy(bigint, text, text, text, text, boolean, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_amc_mgmt_policy(i_policy_id bigint, i_policy_name text, i_description text, i_online_policy_body text, i_offline_policy_body text, i_use_offline_policy boolean, i_hash text, i_admin_id text) RETURNS TABLE(policy_id bigint, policy_name text, product_feature_id public.en_product_feature_id_type, description text, online_policy_body text, offline_policy_body text, use_offline_policy text, hash text)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_product_feature_id en_product_feature_id_type;
  v_privilege_profile_auth boolean;

BEGIN

SELECT p.product_feature_id
INTO v_product_feature_id
FROM tb_policy p
WHERE p.policy_id = i_policy_id;

SELECT
    EXISTS (
        SELECT
            1
        FROM
            tb_admin ta
        INNER JOIN
            tb_privilege_profile tpp
        ON
            ta.privilege_profile_id = tpp.privilege_profile_id 
        WHERE
            tpp.profile_body LIKE '%"/policy/policy_AMC_W"%'
        AND
            ta.admin_id = i_admin_id
    ) INTO v_privilege_profile_auth;

IF v_product_feature_id IS NULL THEN

  RAISE EXCEPTION 'policy_id (%) does not exist.', i_policy_id USING HINT = 'DB-00031';

ELSIF v_product_feature_id <> 'AMC_MGMT' THEN

  RAISE EXCEPTION 'policy_id (%) is not AMC_MGMT policy.', i_policy_id USING HINT = 'DB-00030';

END IF;

IF v_privilege_profile_auth = FALSE THEN
  RAISE EXCEPTION 'You do not have permission to write policy' USING HINT = 'DB-00084';
END IF;

  RETURN QUERY
  SELECT p.policy_id AS policy_id
        ,p.policy_name AS policy_name
        ,p.product_feature_id AS product_feature_id
        ,p.description AS description
        ,p.online_policy_body AS online_policy_body
        ,p.offline_policy_body AS offline_policy_body
        ,p.use_offline_policy AS use_offline_policy
        ,p.hash AS hash
  FROM sp_set_policy(i_policy_id, i_policy_name, 'AMC_MGMT', i_description, i_online_policy_body,
                     i_offline_policy_body, i_use_offline_policy, i_hash) p;

END;
$$;


ALTER FUNCTION public.sp_set_amc_mgmt_policy(i_policy_id bigint, i_policy_name text, i_description text, i_online_policy_body text, i_offline_policy_body text, i_use_offline_policy boolean, i_hash text, i_admin_id text) OWNER TO cppoltp;

--
-- Name: sp_set_application(public.en_app_type, text, text, timestamp without time zone, bigint, inet, public.en_db_type, text, text, public.en_supply_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_application(i_app_type public.en_app_type, i_app_id text, i_app_key text, i_expire_date timestamp without time zone, i_session_timeout bigint, i_connect_ip inet, i_db_type public.en_db_type, i_query text, i_description text, i_supply_type public.en_supply_type) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

      values(i_app_id, i_app_key, i_app_type, now(), i_expire_date, i_session_timeout, concat('{',i_connect_ip,'}'), i_db_type, i_query, i_description, i_supply_type, now())
    ON CONFLICT (app_id)
  DO UPDATE SET
    app_key = i_app_key
    , app_type = i_app_type
    , from_date = now()
    , to_date = i_expire_date
    , expire_time = i_session_timeout
    , connect_ipaddr = concat('{',i_connect_ip,'}')
    , db_type = i_db_type
        , query = i_query
        , description = i_description
        , supply_type = i_supply_type
        , modified_time = now()
    ;
END;
$$;


