--
-- Name: sp_set_auto_grouping(bigint, text, public.en_machine_type, inet, text, text, text, public.en_platform_id_type, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_auto_grouping(i_node_id bigint, i_machine_uuid text, i_machine_type public.en_machine_type, i_ip inet, i_nt_domain text, i_computer_name text, i_login_id text, i_platform_id public.en_platform_id_type, i_multinic text) RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_nic_array text[];
  v_nic text;

BEGIN

  SELECT string_to_array(i_multinic,',') INTO v_nic_array;

  -- grouping 정보 UPDATE
  UPDATE tb_node
  SET machine_uuid = i_machine_uuid
     ,machine_type = i_machine_type
     ,ip = i_ip
     ,mac = v_nic_array[1]
     ,nt_domain = i_nt_domain
     ,computer_name = i_computer_name
     ,login_id = i_login_id
     ,platform_id = i_platform_id
     ,modified_time = now()
  WHERE node_id = i_node_id;

  -- multinic 정보 DELETE
  DELETE FROM tb_node_nic
  WHERE node_id = i_node_id;

  -- multinic 정보 INSERT
  FOREACH v_nic IN ARRAY v_nic_array
  LOOP

                node_id, mac, ip, modified_time)
        VALUES (i_node_id, v_nic, i_ip, now());

  END LOOP;

END;
$$;


