--
-- Name: sp_set_beginning_system_info(text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_beginning_system_info(i_license_no text, i_company_name text, i_user_name text, i_domain_name text, i_dns_server_ip_01 text, i_dns_server_ip_02 text, i_dns_server_ip_03 text, i_license_version text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_keys            text[];
  v_values          text[];
BEGIN

  IF (SELECT ARRAY_LENGTH(STRING_TO_ARRAY(i_domain_name, ' '), 1)) > 1 THEN
    RAISE EXCEPTION 'Domain name cannot include space.' USING HINT = 'DB-00046';
  END IF;

  -- 라이선스
  UPDATE tb_product_license
    SET is_master_license = FALSE, is_apply_license = FALSE
  WHERE product_id = 'EMS'AND is_master_license = TRUE;

    license_no, product_id, is_manageable_license, service_date, expire_date, version, expire_update_status, total_quantity
  ) VALUES(
    i_license_no, 'EMS', true, now(), (TO_CHAR(now(), 'YYYY-MM-DD')::timestamp + Interval '7 days' - INTERVAL '1 seconds'), i_license_version, 'READY', CASE WHEN i_license_version = '2.0' THEN 0 ELSE null END
  )
  ON CONFLICT(product_id) DO
  UPDATE SET
    license_no = EXCLUDED.license_no, is_manageable_license = EXCLUDED.is_manageable_license
    , service_date = EXCLUDED.service_date, expire_date = EXCLUDED.expire_date
    , version = EXCLUDED.version, expire_update_status = EXCLUDED.expire_update_status
    ;

    license_no, product_id, is_main_license, register_date, expire_date, version, expire_update_status, eula_agree_date, issue_quantity
  ) VALUES(
    i_license_no, 'EMS', true, now(), (TO_CHAR(now(), 'YYYY-MM-DD')::timestamp + Interval '7 days' - INTERVAL '1 seconds'), i_license_version, 'READY', now(), CASE WHEN i_license_version = '2.0' THEN 0 ELSE null END
  );

  -- 시스템 정보
  v_keys := ARRAY[ 'company_name', 'user_name', 'domain_name'
      , 'dns_server_ip_01', 'dns_server_ip_02', 'dns_server_ip_03' ];
  v_values := ARRAY[ TRIM(i_company_name), TRIM(i_user_name), TRIM(i_domain_name)
      , TRIM(i_dns_server_ip_01), TRIM(i_dns_server_ip_02), TRIM(i_dns_server_ip_03) ];

  PERFORM sp_set_configs( 'SYS_INFO', v_keys, v_values );

  -- 도메인명으로 그룹의 group_type = 'TOP' 으로 변경
  IF (EXISTS (SELECT 1 FROM tb_group AS g WHERE g.group_type = 'TOP')) THEN
    UPDATE tb_group
      SET name = i_domain_name
    WHERE group_type = 'TOP';
  ELSE
    VALUES( i_domain_name, 'TOP', false );
  END IF;

  -- 환경값 셋팅
  ON CONFLICT(config_group, key) DO UPDATE SET value = EXCLUDED.value, modified_time = EXCLUDED.modified_time;

END;
$$;


