CREATE FUNCTION public.sp_set_correlation_excute_update(i_correlation_rule_id bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN

  /*
      연계규칙 수행 시간을 업데이트 한다.
   EMS5-3714
   shkang, 2018.11.29
