--
-- Name: sp_set_correlation_rule(integer, integer, integer, integer, integer, bigint, text, boolean, text, integer, text, text, public.en_base_report_id_type, bigint, boolean, boolean, text, public.en_correlation_condition_id_type[], text[], public.en_comparison_operator[], integer[], bigint[], public.en_task_type[], bigint[], text[], boolean, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_correlation_rule(i_ud_cr integer, i_ud_cri integer, i_ud_ce integer, i_ud_ct integer, i_schedule_flag integer, i_correlation_rule_id bigint, i_name text, i_is_enabled boolean, i_schedule text, i_alarm_threshold integer, i_condition_text text, i_exclude_text text, i_base_report_id public.en_base_report_id_type, i_alert_template_id bigint, i_send_mail boolean, i_send_mail_to_target boolean, i_custom_email text, i_correlation_condition_id public.en_correlation_condition_id_type[], i_values text[], i_comparison_operator public.en_comparison_operator[], i_intersect_set integer[], i_target_id bigint[], i_task_type public.en_task_type[], i_task_order bigint[], i_payload_params text[], i_send_mail_to_target_agent boolean, i_admin_id text) RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE
  v_is_validation_pass boolean;
  v_validation_target_index integer;
  v_validation_values text[];
BEGIN

  --tb_correlation_rule 1:UPDATE
  IF i_ud_cr = 1 THEN

  -- correlation name dup check
  IF ((SELECT count(1) FROM tb_correlation_rule AS c WHERE c.correlation_rule_id != i_correlation_rule_id AND c.name = i_name) > 0) THEN
    RAISE EXCEPTION 'The correlation name already exists.' USING HINT = 'DB-00043';
  END IF;


  UPDATE tb_correlation_rule
  SET name                = i_name
     ,is_enabled          = i_is_enabled
     ,schedule            = i_schedule
     ,alarm_threshold     = i_alarm_threshold
     ,condition_text      = i_condition_text
     ,exclude_text        = i_exclude_text
     ,base_report_id      = i_base_report_id
     ,alert_template_id   = i_alert_template_id
     ,send_mail           = i_send_mail
     ,send_mail_to_target = i_send_mail_to_target
     ,custom_email        = i_custom_email
     ,admin_id            = i_admin_id
     ,modified_time       = now()
	 ,send_mail_to_target_agent = i_send_mail_to_target_agent
  WHERE correlation_rule_id = i_correlation_rule_id;
  ELSE
  UPDATE tb_correlation_rule
  SET modified_time       = now()
     ,admin_id            = i_admin_id
  WHERE correlation_rule_id = i_correlation_rule_id;
  END IF;

  --tb_correlation_rule_item 1:UPDATE, 2:DELETE
  IF i_ud_cri > 0 THEN
  DELETE
  FROM tb_correlation_rule_item AS cri
  WHERE cri.correlation_rule_id = i_correlation_rule_id;

    IF i_ud_cri = 1 THEN
      UPDATE tb_correlation_rule
    SET condition_text      = i_condition_text
       ,admin_id            = i_admin_id
       ,modified_time       = now()
    WHERE correlation_rule_id = i_correlation_rule_id;

                correlation_rule_id
               ,correlation_condition_id
               ,values
               ,comparison_operator
               ,intersect_set)
    SELECT i_correlation_rule_id
          ,t.correlation_condition_id
          ,t.values
          ,coalesce(t.comparison_operator,'=')
          ,t.intersect_set
    FROM unnest(i_correlation_condition_id
               ,i_values
               ,i_comparison_operator
               ,i_intersect_set)
    AS t(correlation_condition_id
        ,values
        ,comparison_operator
        ,intersect_set);
  END IF;
  END IF;

  --tb_correlation_exclude 1:UPDATE, 2:DELETE
  IF i_ud_ce > 0 THEN
  DELETE
  FROM tb_correlation_exclude AS ce
  WHERE ce.correlation_rule_id = i_correlation_rule_id
    AND ce.exclude_type = 'NODE';

  UPDATE tb_correlation_rule
  SET exclude_text        = i_exclude_text
     ,admin_id            = i_admin_id
     ,modified_time       = now()
  WHERE correlation_rule_id = i_correlation_rule_id;

    IF i_ud_ce = 1 THEN
    SELECT i_correlation_rule_id, t.target_id, 'NODE' FROM unnest(i_target_id) as t(target_id);
  END IF;
  END IF;
  --tb_correlation_task 1:UPDATE, 2:DELETE
  IF i_ud_ct > 0 THEN
  DELETE
  FROM tb_correlation_task AS ct
  WHERE ct.correlation_rule_id = i_correlation_rule_id;

    IF i_ud_ct = 1 THEN
    SELECT i_correlation_rule_id, t.task_type, t.task_order, t.payload_params FROM unnest(i_task_type, i_task_order, i_payload_params) as t(task_type, task_order, payload_params);
  END IF;
  END IF;

  -- 연계 규칙 동기화 업데이트, shkang : 2018. 06. 28
  UPDATE tb_server SET need_correlation_refresh = true;

END;
$$;


ALTER FUNCTION public.sp_set_correlation_rule(i_ud_cr integer, i_ud_cri integer, i_ud_ce integer, i_ud_ct integer, i_schedule_flag integer, i_correlation_rule_id bigint, i_name text, i_is_enabled boolean, i_schedule text, i_alarm_threshold integer, i_condition_text text, i_exclude_text text, i_base_report_id public.en_base_report_id_type, i_alert_template_id bigint, i_send_mail boolean, i_send_mail_to_target boolean, i_custom_email text, i_correlation_condition_id public.en_correlation_condition_id_type[], i_values text[], i_comparison_operator public.en_comparison_operator[], i_intersect_set integer[], i_target_id bigint[], i_task_type public.en_task_type[], i_task_order bigint[], i_payload_params text[], i_send_mail_to_target_agent boolean, i_admin_id text) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_set_correlation_rule(i_ud_cr integer, i_ud_cri integer, i_ud_ce integer, i_ud_ct integer, i_schedule_flag integer, i_correlation_rule_id bigint, i_name text, i_is_enabled boolean, i_schedule text, i_alarm_threshold integer, i_condition_text text, i_exclude_text text, i_base_report_id public.en_base_report_id_type, i_alert_template_id bigint, i_send_mail boolean, i_send_mail_to_target boolean, i_custom_email text, i_correlation_condition_id public.en_correlation_condition_id_type[], i_values text[], i_comparison_operator public.en_comparison_operator[], i_intersect_set integer[], i_target_id bigint[], i_task_type public.en_task_type[], i_task_order bigint[], i_payload_params text[], i_send_mail_to_target_agent boolean, i_admin_id text); Type: COMMENT; Schema: public; Owner: cppoltp
