--
-- Name: sp_set_custom_privilege_profile(bigint, text, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_custom_privilege_profile(i_privilege_profile_id bigint, i_profile_name text, i_description text, i_profile_body text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  IF (EXISTS (SELECT 1 FROM tb_privilege_profile AS p WHERE p.privilege_profile_id <> i_privilege_profile_id AND p.profile_name = i_profile_name)) THEN
    RAISE EXCEPTION 'The name is already registered.(%)', i_profile_name USING HINT = 'DB-00037';
  END IF;

  UPDATE tb_privilege_profile
    SET profile_name = i_profile_name
      , description = i_description
      , profile_body = i_profile_body
      , modified_time = now()
  WHERE privilege_profile_id = i_privilege_profile_id
    AND profile_type = 'CUSTOM_ADMIN';

END;
$$;


