--
-- Name: sp_set_db_backup_config(boolean, text, integer, boolean, text, text, integer, boolean, text, text, text, text[], boolean, text, text, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_db_backup_config(i_backup_local_disk_use boolean, i_backup_local_disk_path text, i_backup_local_disk_max integer, i_backup_ftp_use boolean, i_backup_ftp_type text, i_backup_ftp_ip text, i_backup_ftp_port integer, i_backup_ftp_ssl_use boolean, i_backup_ftp_id text, i_backup_ftp_pw text, i_backup_ftp_path text, i_backup_schedule text[], i_backup_s3_use boolean, i_backup_s3_bucket text, i_backup_s3_access_key text, i_backup_s3_secret_access_key text, i_backup_conceal_key text) RETURNS TABLE(schedule_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_keys                      text[];
  v_values                    text[];

  v_startpoint                integer := 11;
BEGIN

  v_keys := ARRAY[ 'backup_local_disk_use', 'backup_local_disk_path', 'backup_local_disk_max', 'backup_ftp_use', 'backup_ftp_type'
      , 'backup_ftp_ip', 'backup_ftp_port', 'backup_ftp_ssl_use', 'backup_ftp_id', 'backup_ftp_pw', 'backup_ftp_path'
      , 'backup_schedule_01', 'backup_schedule_02', 'backup_schedule_03'
      , 'backup_s3_use', 'backup_s3_bucket', 'backup_s3_access_key', 'backup_s3_secret_access_key', 'backup_conceal_key' ];
  v_values := ARRAY[ i_backup_local_disk_use::text, TRIM(i_backup_local_disk_path), i_backup_local_disk_max::text, i_backup_ftp_use::text, i_backup_ftp_type
      , TRIM(i_backup_ftp_ip), i_backup_ftp_port::text, i_backup_ftp_ssl_use::text, TRIM(i_backup_ftp_id), TRIM(i_backup_ftp_pw), TRIM(i_backup_ftp_path)
      , NULL, NULL, NULL
      , i_backup_s3_use::text, i_backup_s3_bucket::text, i_backup_s3_access_key::text, i_backup_s3_secret_access_key::text, i_backup_conceal_key::text ];

  -- 스케줄 초기화
  PERFORM sp_set_unity_schedule_disabled( 'DB_BACKUP' );

  FOR i IN 1..3 LOOP
    -- DB config 셋팅
    v_values[ i + v_startpoint ] := i_backup_schedule[i];

    -- 스케줄 관리
    IF i_backup_schedule[i] IS NOT NULL AND LENGTH(i_backup_schedule[i]) > 0 THEN
      PERFORM sp_add_unity_schedule( 'EMS', 'DB_BACKUP', i, i_backup_schedule[i], true, '/api/console/config/db/backup/execute', null );
    END IF;
  END LOOP;

  PERFORM sp_set_configs( 'DB_BACKUP', v_keys, v_values );


  RETURN QUERY
    SELECT STRING_AGG(s.schedule_id::text, ',') FROM tb_schedule AS s WHERE s.schedule_code = 'DB_BACKUP';

END;
$$;


