DECLARE
  v_server_id bigint;
BEGIN
  select server_id into v_server_id from tb_server where tb_server.ip = i_server_ip;

  IF( v_server_id IS NOT NULL ) THEN
    IF( i_db_mgmt_type = 'BACKUP' ) THEN
    END IF;

    IF( i_db_mgmt_type = 'CLEANUP' ) THEN
      IF (SELECT NOT EXISTS (SELECT 1 FROM tb_db_mgmt WHERE db_mgmt_type = 'CLEANUP' and db_type = i_db_type and server_id = v_server_id)) THEN
      ELSE
        UPDATE tb_db_mgmt
        SET mgmt_time = now()
        where db_mgmt_type = 'CLEANUP' and db_type = i_db_type and server_id = v_server_id;
      END IF;
    END IF;

    IF( i_db_mgmt_type = 'REPORT_CLEAN' ) THEN
    END IF;
  END IF;
END;
$$;


