--
-- Name: sp_set_distribution_config(integer, integer, boolean, text, text[], text[], text[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_distribution_config(i_concurrent_session_cnt integer, i_speed_limit integer, i_dist_update_forbid_use boolean, i_dist_update_forbid_day text, i_dist_update_forbid_hour text[], i_dist_allow_ip text[], i_dist_deny_ip text[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_keys            text[];
  v_values          text[];
  v_index           integer   DEFAULT 0;
  v_hour            text;
BEGIN

  v_keys := ARRAY[ 'concurrent_session_cnt', 'speed_limit', 'dist_update_forbid_use', 'dist_update_forbid_day'
      , 'update_forbid_time_01', 'update_forbid_time_02', 'update_forbid_time_03', 'update_forbid_time_04', 'update_forbid_time_05' ];
  v_values := ARRAY[ i_concurrent_session_cnt::text, i_speed_limit::text, i_dist_update_forbid_use::text, TRIM(i_dist_update_forbid_day)
      , NULL, NULL, NULL, NULL, NULL ];

  FOREACH v_hour IN ARRAY i_dist_update_forbid_hour LOOP
    EXIT WHEN v_index = 5;

    v_index := v_index + 1;
    v_values[ 4 + v_index] := v_hour;
  END LOOP;

  PERFORM sp_set_configs( 'DISTRIBUTION', v_keys, v_values );


  -- 배포 대역 설정 삭제
  DELETE FROM tb_dist_range_config;

  -- 배포 허용 대역 설정 등록
    SELECT t.ip, true FROM UNNEST(i_dist_allow_ip) AS t(ip);

  -- 배포 차단 대역 설정 등록
    SELECT t.ip, false FROM UNNEST(i_dist_deny_ip) AS t(ip);

END;
$$;


