--
-- Name: sp_set_domain_setting_state(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_domain_setting_state(i_value text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_node_id         bigint    DEFAULT 0;
BEGIN

  -- 기본 등록여부 판단
  IF (SELECT EXISTS (SELECT 1 FROM tb_config AS n WHERE n.config_group = 'domain_setting' AND n.key = 'setting_state')) = false THEN
      config_group
      , key
      , value
      , modified_time
    )
    VALUES
    (
      'domain_setting'
      , 'setting_state'
      , i_value
      , now()
    );
  ELSE
    UPDATE tb_config
    SET
      value = i_value
      , modified_time = now()
    WHERE config_group = 'domain_setting'
    AND key = 'setting_state';
  END IF;


END;
$$;


