--
-- Name: sp_set_each_ac_agent_policy_apply(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_each_ac_agent_policy_apply(i_policy_id bigint, i_node_id bigint[]) RETURNS TABLE(policy_id bigint, product_feature_id public.en_product_feature_id_type, node_id text)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_product_feature_id en_product_feature_id_type;

BEGIN

SELECT p.product_feature_id
INTO v_product_feature_id
FROM tb_policy p
WHERE p.policy_id = i_policy_id;

IF v_product_feature_id IS NULL THEN

  RAISE EXCEPTION 'policy_id (%) does not exist.', i_policy_id USING HINT = 'DB-00031';

ELSIF v_product_feature_id <> 'AC_AGENT' THEN

  RAISE EXCEPTION 'policy_id (%) is not AC_AGENT policy.', i_policy_id USING HINT = 'DB-00030';

END IF;

  RETURN QUERY
  SELECT np.policy_id AS policy_id
        ,np.product_feature_id AS product_feature_id
        ,np.node_id AS node_id
  FROM sp_set_each_policy_apply(i_policy_id, i_node_id) np;

END;
$$;


