--
-- Name: sp_set_each_policy_apply(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_each_policy_apply(i_policy_id bigint, i_node_id bigint[]) RETURNS TABLE(policy_id bigint, product_feature_id public.en_product_feature_id_type, node_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_product_feature_id en_product_feature_id_type;

BEGIN

  SELECT p.product_feature_id
  INTO v_product_feature_id
  FROM tb_policy p
  WHERE p.policy_id = i_policy_id;

  UPDATE tb_node_policy np
  SET policy_id = i_policy_id
     ,keep_agent_policy = true
     ,modified_time = now()
  WHERE np.node_id = ANY(i_node_id)
    AND np.product_feature_id = v_product_feature_id
    AND EXISTS (SELECT 1 FROM tb_node n WHERE n.node_id = np.node_id AND is_removed is false);

  RETURN QUERY
  SELECT np.policy_id AS policy_id
        ,np.product_feature_id AS product_feature_id
        ,array_agg(np.node_id)::text AS node_id
  FROM tb_node_policy np
  WHERE np.node_id = ANY(i_node_id)
    AND np.product_feature_id = v_product_feature_id
    AND EXISTS (SELECT 1 FROM tb_node n WHERE n.node_id = np.node_id AND is_removed is false)
  GROUP BY
        np.policy_id
       ,np.product_feature_id;

END;
$$;


