--
-- Name: sp_set_file_update_server(bigint, public.en_file_update_target_type, bigint[], text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_file_update_server(i_target_id bigint, i_target_type public.en_file_update_target_type, i_server_id bigint[], i_admin_id text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_group_id                  bigint[];
  v_server_id                 bigint;
BEGIN

  IF i_target_type = 'GROUP' THEN
  -- [GROUP]
    SELECT t.all_sub_group_id INTO v_group_id
    FROM sp_get_all_sub_group_list(i_target_id, true, i_admin_id) AS t;

    -- delete node : 주의 specified true인 경우 삭제 하지 않는다.
    DELETE FROM tb_file_update_server
    WHERE target_type = 'NODE'
      AND specified = false
      AND target_id = ANY(SELECT n.node_id FROM tb_node AS n WHERE n.group_id = ANY(v_group_id));

    -- delete group;
    DELETE FROM tb_file_update_server
    WHERE target_type = 'GROUP'
      AND target_id = ANY(v_group_id);

    -- 선택된 서버 저장 (insert group)
      SELECT g.group_id, 'GROUP', s.server_id, false
      FROM UNNEST(v_group_id) AS g(group_id)
      CROSS JOIN UNNEST(i_server_id) AS s(server_id)
      WHERE s.server_id > 0
    ON CONFLICT(target_id, target_type, server_id) DO NOTHING;

    -- 선택된 서버 저장 (insert node)
      SELECT n.node_id, 'NODE', s.server_id, false
      FROM UNNEST(i_server_id) AS s(server_id)
      CROSS JOIN (
        SELECT n.node_id
        FROM tb_node AS n
        WHERE n.group_id = ANY(v_group_id)
          AND NOT(n.node_id = ANY(
                SELECT ifus.target_id
                FROM tb_file_update_server ifus
                WHERE ifus.target_type = 'NODE'
                  AND ifus.target_id = ANY(SELECT nd.node_id FROM tb_node nd WHERE nd.group_id = ANY(v_group_id))
                  AND ifus.specified = true)
            )
      ) AS n
      WHERE s.server_id > 0
    ON CONFLICT(target_id, target_type, server_id) DO NOTHING;

  ------------------------------------------------------------------------------------------
  ELSE
  -- [NODE]
    -- delete node
    DELETE FROM tb_file_update_server
    WHERE target_type = 'NODE'
      AND target_id = i_target_id;

    -- 선택된 서버 저장
      SELECT t.node_id, 'NODE', s.server_id, true
      FROM UNNEST(ARRAY[i_target_id]) AS t(node_id)
      CROSS JOIN UNNEST(i_server_id) AS s(server_id)
      WHERE s.server_id > 0
    ON CONFLICT(target_id, target_type, server_id) DO NOTHING;

  ------------------------------------------------------------------------------------------
  END IF;

END;
$$;


ALTER FUNCTION public.sp_set_file_update_server(i_target_id bigint, i_target_type public.en_file_update_target_type, i_server_id bigint[], i_admin_id text) OWNER TO cppoltp;

--
-- Name: sp_set_group(bigint, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_group(i_group_id bigint, i_name text) RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_pgroup_id bigint;
  v_group_type en_group_type;
  v_dgroup_type en_group_type;
  v_duplicate_count bigint;
  v_space boolean;
  v_subgroups    bigint;

BEGIN

SELECT group_type, pgroup_id
INTO v_group_type, v_pgroup_id
FROM tb_group
WHERE group_id = i_group_id;

SELECT count(group_id)
      ,group_type
INTO v_duplicate_count
    ,v_dgroup_type
FROM sp_get_duplicate_group_name(v_pgroup_id, i_name)
WHERE group_id <> i_group_id
GROUP BY group_type;

SELECT COALESCE(REPLACE(i_name, ' ', ''), '') = ''
INTO v_space;

IF v_group_type IS NULL THEN

  RAISE EXCEPTION 'group does not exist.' USING HINT = 'DB-00011';

ELSIF v_dgroup_type = 'TOP' THEN

  RAISE EXCEPTION 'group name already in use for top group.' USING HINT = 'DB-00007';

ELSIF v_duplicate_count > 0 THEN

  RAISE EXCEPTION 'group name already exist.' USING HINT = 'DB-00005';

ELSIF v_space THEN

  RAISE EXCEPTION 'group name cannot include space.' USING HINT = 'DB-00009';

ELSIF v_group_type = 'TOP' THEN

  RAISE EXCEPTION 'top group name cannot modify.' USING HINT = 'DB-00013';

ELSIF v_group_type <> 'GENERAL' THEN

  RAISE EXCEPTION 'group name cannot modify.' USING HINT = 'DB-00008';

ELSE

  -- 그룹 UPDATE
  UPDATE tb_group
  SET name = i_name
  WHERE group_id = i_group_id;

END IF;

END;
$$;


