--
-- Name: sp_set_group_by_file_update_server(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_group_by_file_update_server() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

    SELECT n.node_id, 'NODE', f.server_id, false
    FROM tb_node AS n
    JOIN (
      SELECT f.target_id AS group_id, f.server_id
      FROM tb_file_update_server AS f
      WHERE f.target_type = 'GROUP'
    ) AS f ON n.group_id = f.group_id
  ON CONFLICT(target_id, target_type, server_id) DO NOTHING;

END;
$$;


ALTER FUNCTION public.sp_set_group_by_file_update_server() OWNER TO cppoltp;

--
-- Name: sp_set_group_file_update_server(bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_group_file_update_server(i_group_id bigint[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

    SELECT g.group_id, 'GROUP', f.server_id, specified
    FROM tb_file_update_server AS f
    JOIN tb_group AS g ON g.group_id = ANY(i_group_id) AND f.target_type = 'GROUP' AND f.target_id = g.pgroup_id
  ON CONFLICT(target_id, target_type, server_id) DO NOTHING;

END;
$$;


