--
-- Name: sp_set_group_order(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_group_order() RETURNS TABLE(err_code text, err_msg text)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_pgroup_id_array bigint[];
  v_pgroup_id bigint;

BEGIN

  -- pgroup_id 목록 조회
  SELECT ARRAY_AGG(DISTINCT pgroup_id)
  INTO v_pgroup_id_array
  FROM tb_group;

  -- pgroup_id 별 하위그룹의 group_order 정리
  FOREACH v_pgroup_id IN ARRAY v_pgroup_id_array
  LOOP

    WITH group_list AS (
      SELECT g.group_id
            ,g.name
            ,RANK() OVER(PARTITION BY g.pgroup_id ORDER BY g.new_order, g.group_order, g.group_id) AS group_order
      FROM (SELECT group_id
                  ,name
                  ,pgroup_id
                  ,group_order
                  ,CASE group_order
                     WHEN -1 THEN 1
                     WHEN -2 THEN 3
                     ELSE 2
                   END AS new_order
            FROM tb_group
            WHERE pgroup_id = v_pgroup_id) AS g
    )
    UPDATE tb_group g
    SET group_order = gl.group_order
    FROM group_list AS gl
    WHERE g.group_id = gl.group_id;

  END LOOP;

  -- 그룹 정렬 flag OFF
  UPDATE tb_config
  SET value = 'OFF'
  WHERE config_group = 'GROUP_ORDER'
    AND key = 'update_flag';

RETURN QUERY SELECT 'DB-00000'::text, 'success'::text;

END;
$$;


ALTER FUNCTION public.sp_set_group_order() OWNER TO cppoltp;

