@brief 그룹 정렬
@in -
@out -
@return - TABLE';


--
-- Name: sp_set_group_order_setting(text, text, text[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_group_order_setting(i_new_group_position text, i_select_order text, i_user_order text[]) RETURNS TABLE(err_code text, err_msg text)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_keys text[];
  v_values text[];
  v_user_order text;
  con_group_id CONSTANT integer := 1;
  con_group_order CONSTANT integer := 2;

BEGIN

  v_keys := ARRAY['new_group_position','select_order'];
  v_values := ARRAY[TRIM(i_new_group_position),TRIM(i_select_order)];

  PERFORM sp_set_configs('GROUP_ORDER', v_keys, v_values);

  IF i_select_order = 'USER' THEN

    -- GROUP_ORDER UPDATE
    FOREACH v_user_order IN ARRAY i_user_order LOOP

      UPDATE tb_group
      SET group_order = split_part(v_user_order, ',', con_group_order)::bigint
      WHERE group_id = split_part(v_user_order, ',', con_group_id)::bigint;

    END LOOP;

  END IF;

  RETURN QUERY SELECT 'DB-00000'::text, 'success'::text;

END;
$$;


