--
-- Name: sp_set_group_policy_apply(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_group_policy_apply(i_policy_id bigint, i_group_id bigint[]) RETURNS TABLE(policy_id bigint, product_feature_id public.en_product_feature_id_type, node_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_product_feature_id en_product_feature_id_type;
  v_agent_change text;

BEGIN

  SELECT value
  INTO v_agent_change
  FROM tb_config
  WHERE config_group = 'GROUPING'
  AND key = 'apply_policy_on_group_change';

  SELECT p.product_feature_id
  INTO v_product_feature_id
  FROM tb_policy p
  WHERE p.policy_id = i_policy_id;

  --그룹 정책 적용
  UPDATE tb_group_policy gp
  SET policy_id = i_policy_id
     ,modified_time = now()
  WHERE gp.group_id = ANY(i_group_id)
    AND gp.product_feature_id = v_product_feature_id;

  UPDATE tb_node_policy np
  SET policy_id = i_policy_id
     ,keep_agent_policy = false
     ,modified_time = now()
  WHERE np.node_id IN (SELECT n.node_id
                       FROM tb_node n
                       WHERE n.group_id = ANY(i_group_id)
                       AND n.is_removed = FALSE)
    AND np.product_feature_id = v_product_feature_id
    AND CASE v_agent_change
          WHEN 'all_but_agent_policy' THEN
            np.keep_agent_policy = false
          ELSE 1=1
        END;

  RETURN QUERY
  SELECT np.policy_id AS policy_id
        ,np.product_feature_id AS product_feature_id
        ,array_agg(np.node_id)::text AS node_id
  FROM tb_node_policy np
  WHERE np.node_id IN (SELECT n.node_id
                       FROM tb_node n
                       WHERE n.group_id = ANY(i_group_id)
                       AND n.is_removed = FALSE)
    AND np.product_feature_id = v_product_feature_id
    AND CASE v_agent_change
          WHEN 'all_but_agent_policy' THEN
            np.keep_agent_policy = false
          ELSE 1=1
        END
  GROUP BY
        np.policy_id
       ,np.product_feature_id;

END;
$$;


ALTER FUNCTION public.sp_set_group_policy_apply(i_policy_id bigint, i_group_id bigint[]) OWNER TO cppoltp;

--
-- Name: sp_set_group_policy_apply_all(bigint, bigint[], bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_group_policy_apply_all(i_policy_id bigint, i_group_id bigint[], i_exception_node_id bigint[]) RETURNS TABLE(node_id bigint[])
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_product_feature_id en_product_feature_id_type;
  v_agent_change text;

BEGIN

  SELECT p.product_feature_id
  INTO v_product_feature_id
  FROM tb_policy p
  WHERE p.policy_id = i_policy_id;

  --그룹 정책 적용
  UPDATE tb_group_policy gp
  SET policy_id = i_policy_id
     ,modified_time = now()
  WHERE gp.group_id = ANY(i_group_id)
    AND gp.product_feature_id = v_product_feature_id;

  UPDATE tb_node_policy np
  SET policy_id = i_policy_id
     ,keep_agent_policy = false
     ,modified_time = now()
  WHERE np.node_id IN (SELECT n.node_id
                       FROM tb_node n
                       WHERE n.group_id = ANY(i_group_id)
                       AND n.is_removed = FALSE)
    AND np.node_id NOT IN (SELECT * FROM unnest(i_exception_node_id))
    AND np.product_feature_id = v_product_feature_id;

  RETURN QUERY
  SELECT array_agg(np.node_id)
  FROM tb_node_policy np
  WHERE np.node_id IN (SELECT n.node_id
                       FROM tb_node n
                       WHERE n.group_id = ANY(i_group_id)
                       AND n.is_removed = FALSE)
    AND np.node_id NOT IN (SELECT * FROM unnest(i_exception_node_id))
    AND np.product_feature_id = v_product_feature_id;

END;
$$;


ALTER FUNCTION public.sp_set_group_policy_apply_all(i_policy_id bigint, i_group_id bigint[], i_exception_node_id bigint[]) OWNER TO cppoltp;

