CREATE FUNCTION public.sp_set_group_v3_linux_policy_apply(i_policy_id bigint, i_group_id bigint[]) RETURNS TABLE(policy_id bigint, product_feature_id public.en_product_feature_id_type, node_id text)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_product_feature_id en_product_feature_id_type;
  v_update_policy_id bigint;

BEGIN

SELECT p.product_feature_id
INTO v_product_feature_id
FROM tb_policy p
WHERE p.policy_id = i_policy_id;

IF v_product_feature_id IS NULL THEN

  RAISE EXCEPTION 'policy_id (%) does not exist.', i_policy_id USING HINT = 'DB-00031';

ELSIF v_product_feature_id <> 'V3NET_LU_AV' THEN

  RAISE EXCEPTION 'policy_id (%) is not V3NET_LU_AV policy.', i_policy_id USING HINT = 'DB-00030';

END IF;

  SELECT p.policy_id
  INTO v_update_policy_id
  FROM tb_policy p
  WHERE p.ppolicy_id = i_policy_id;

  RETURN QUERY
  SELECT gp.policy_id AS policy_id
        ,gp.product_feature_id AS product_feature_id
        ,gp.node_id AS node_id
  FROM sp_set_group_policy_apply(i_policy_id, i_group_id) gp
  UNION ALL
  SELECT gup.policy_id AS policy_id
        ,gup.product_feature_id AS product_feature_id
        ,gup.node_id AS node_id
  FROM sp_set_group_policy_apply(v_update_policy_id, i_group_id) gup;

END;
$$;


