--
-- Name: sp_set_grouping_config(boolean, text, text, text, text, text, boolean, integer); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_grouping_config(i_auto_grouping_use boolean, i_auto_grouping_type text, i_auto_grouping_path text, i_auto_grouping_target text, i_auto_grouping_condition text, i_apply_policy_on_group_change text, i_empty_group_clean_use boolean, i_empty_group_clean_interval integer) RETURNS TABLE(schedule_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_keys            text[];
  v_values          text[];
  v_schedule_id    text := null;
BEGIN

  v_keys := ARRAY[ 'auto_grouping_use', 'auto_grouping_type', 'auto_grouping_path', 'auto_grouping_target', 'auto_grouping_condition'
      , 'apply_policy_on_group_change', 'empty_group_clean_use', 'empty_group_clean_interval' ];
  v_values := ARRAY[ i_auto_grouping_use::text, TRIM(i_auto_grouping_type), TRIM(i_auto_grouping_path), TRIM(i_auto_grouping_target), TRIM(i_auto_grouping_condition)
      , TRIM(i_apply_policy_on_group_change) , i_empty_group_clean_use::text, i_empty_group_clean_interval::text ];

  PERFORM sp_set_configs( 'GROUPING', v_keys, v_values );

  IF i_empty_group_clean_use IS TRUE THEN
    v_schedule_id := sp_add_unity_schedule( 'EMS', 'GROUP_CLEAN', 1, '{"repeat":{"daily":'||i_empty_group_clean_interval||'},"basic_moment":{"year":"0","month":"0","week":"0","day":"0","hour":1,"minute":0,"second":0}}', FALSE, '/api/console/config/grouping/empty_group_clean', null );
  ELSE
    v_schedule_id := sp_set_unity_schedule_disabled( 'GROUP_CLEAN' );
  END IF;

  RETURN QUERY
  SELECT v_schedule_id;

END;
$$;


