--
-- Name: sp_set_license(text, public.en_product_id_type, public.en_license_sub_type, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_license(i_license_no text, i_product_id public.en_product_id_type, i_sub_type public.en_license_sub_type, i_remove_license_no text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_expire_date               timestamp := NULL;
BEGIN

  PERFORM sp_remove_license(i_remove_license_no,i_product_id);

  IF i_product_id = 'EMS' THEN
    v_expire_date := now() + Interval '7 days';
  END IF;

  VALUES( i_license_no, i_product_id, TRUE, now(), i_sub_type, v_expire_date );

END;
$$;


