--
-- Name: sp_set_log_configs(public.en_product_group_type[], public.en_log_type[], boolean[], integer); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_log_configs(i_product_group public.en_product_group_type[], i_log_type public.en_log_type[], i_send boolean[], i_send_log_interval integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_keys            text[];
  v_values          text[];
BEGIN

  IF ARRAY_LENGTH(i_product_group, 1) <> ARRAY_LENGTH(i_log_type, 1) OR ARRAY_LENGTH(i_log_type, 1) <> ARRAY_LENGTH(i_send, 1) THEN
    RAISE EXCEPTION 'The length of the array is unequal.' USING HINT = 'DB-00020';
  END IF;

  v_keys := ARRAY[ 'send_log_interval' ];
  v_values := ARRAY[ i_send_log_interval::text ];

  PERFORM sp_set_configs( 'AGENT_SEND_LOG', v_keys, v_values );


    SELECT t.log_type, t.send, t.product_group FROM UNNEST(i_product_group, i_log_type, i_send) AS t(product_group, log_type, send)
  ON CONFLICT(log_type) DO UPDATE SET send = EXCLUDED.send, product_group_type = EXCLUDED.product_group_type;

END;
$$;


ALTER FUNCTION public.sp_set_log_configs(i_product_group public.en_product_group_type[], i_log_type public.en_log_type[], i_send boolean[], i_send_log_interval integer) OWNER TO cppoltp;

