--
-- Name: sp_set_login_fail(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_login_fail(i_admin_id text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

    admin_id,
    fail_count,
    login_time
  )
  VALUES
  (
    i_admin_id,
    1,
    now()
  )
  ON CONFLICT (admin_id) do UPDATE SET
    fail_count = tb_login_fail_status.fail_count + 1,
    login_time = now()
;

END;
$$;


ALTER FUNCTION public.sp_set_login_fail(i_admin_id text) OWNER TO cppoltp;

--
-- Name: sp_set_login_status(text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_login_status(i_admin_id text, i_token text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

    DELETE FROM tb_login_status
	WHERE admin_id = i_admin_id;

		admin_id,
		ip,
		name,
		privilege_profile_id,
		login_time,
		computer_name,
		token
	)
	SELECT
		ta1.admin_id,
		ta1.connect_ipaddr,
		ta1.name,
		ta1.privilege_profile_id,
		now(),
		ta1.computer_name,
		i_token
	FROM tb_admin ta1
	WHERE ta1.admin_id = i_admin_id
    ;

END;
$$;


