CREATE FUNCTION public.sp_set_mail_server(i_mail_conceal_key text, i_mail_server_ip text, i_mail_server_port integer, i_mail_server_ssl_use boolean, i_mail_server_id text, i_mail_server_pw text, i_mail_server_sender text, i_otp_use boolean, i_mail_server_pw_check boolean, i_is_beginning boolean) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_keys            text[];
  v_values          text[];
BEGIN

  v_keys := ARRAY[ 'mail_conceal_key', 'mail_server_ip', 'mail_server_port', 'mail_server_ssl_use', 'mail_server_id', 'mail_server_pw', 'mail_server_sender', 'otp_use' ];
  v_values := ARRAY[ i_mail_conceal_key::text, TRIM(i_mail_server_ip), i_mail_server_port::text, i_mail_server_ssl_use::text, TRIM(i_mail_server_id), TRIM(i_mail_server_pw), TRIM(i_mail_server_sender), i_otp_use::text ];

  -- 비밀번호 변경여부 체크
  IF i_mail_server_pw_check = true THEN
	v_keys := ARRAY[ 'mail_conceal_key', 'mail_server_ip', 'mail_server_port', 'mail_server_ssl_use', 'mail_server_id', 'mail_server_pw', 'mail_server_sender', 'otp_use' ];
	v_values := ARRAY[ i_mail_conceal_key::text, TRIM(i_mail_server_ip), i_mail_server_port::text, i_mail_server_ssl_use::text, TRIM(i_mail_server_id), TRIM(i_mail_server_pw), TRIM(i_mail_server_sender), i_otp_use::text ];
  ELSE
	v_keys := ARRAY[ 'mail_conceal_key', 'mail_server_ip', 'mail_server_port', 'mail_server_ssl_use', 'mail_server_id', 'mail_server_sender', 'otp_use' ];
	v_values := ARRAY[ i_mail_conceal_key::text, TRIM(i_mail_server_ip), i_mail_server_port::text, i_mail_server_ssl_use::text, TRIM(i_mail_server_id),  TRIM(i_mail_server_sender), i_otp_use::text ];
  END IF;

  PERFORM sp_set_configs( 'MAIL_SERVER', v_keys, v_values );

  -- 환경값 셋팅
  IF i_is_beginning = true THEN
    ON CONFLICT(config_group, key) DO UPDATE SET value = EXCLUDED.value, modified_time = EXCLUDED.modified_time;
  END IF;

END;
$$;


ALTER FUNCTION public.sp_set_mail_server(i_mail_conceal_key text, i_mail_server_ip text, i_mail_server_port integer, i_mail_server_ssl_use boolean, i_mail_server_id text, i_mail_server_pw text, i_mail_server_sender text, i_otp_use boolean, i_mail_server_pw_check boolean, i_is_beginning boolean) OWNER TO cppoltp;

--
-- Name: sp_set_manual_config(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_manual_config(i_manual_type text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_keys            text[];
  v_values          text[];
BEGIN

  v_keys := ARRAY[ 'manual_type' ];
  v_values := ARRAY[ TRIM(i_manual_type) ];

  PERFORM sp_set_configs( 'MANUAL', v_keys, v_values );

END;
$$;


ALTER FUNCTION public.sp_set_manual_config(i_manual_type text) OWNER TO cppoltp;

