--
-- Name: sp_set_master_server_version(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_master_server_version(i_patch_version text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
  update tb_config SET value = i_patch_version WHERE config_group = 'UPDATE' AND KEY = 'server_version';
  update tb_config SET value = i_patch_version WHERE config_group = 'UPDATE' AND KEY = 'admin_version';

  -- 업데이트시에는 최신 패치 버전도 최종적으로 동일하게 업데이트 해줘야 한다.
  UPDATE tb_server SET patch_version = i_patch_version WHERE patch_version IS NOT NULL AND patch_version <> i_patch_version;

END;
$$;


ALTER FUNCTION public.sp_set_master_server_version(i_patch_version text) OWNER TO cppoltp;

--
-- Name: sp_set_mergeable_common_policy(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_mergeable_common_policy(i_site_auth_key text) RETURNS TABLE(product_feature_id text, target_filter text)
    LANGUAGE plpgsql
    AS $_$
DECLARE
BEGIN

  RETURN QUERY
    WITH private_lbdist_http AS (
      SELECT concat('http://', s.ip, ':', ( SELECT sp.port FROM tb_service_port sp WHERE sp.service_type = sv.service_type ), '/') AS server_lbdist_http
      FROM tb_server s, tb_service sv
      WHERE s.server_id = sv.server_id AND sv.service_type = 'LBDIST-HTTP' AND sv.enabled = TRUE AND sv.static = TRUE
    )
    , private_lbdist_http_list AS (
      SELECT array_to_string(array_agg(concat('http://', s.ip, ':', ( SELECT sp.port FROM tb_service_port sp WHERE sp.service_type = sv.service_type ), '/')),',') AS server_lbdist_http_list
      FROM tb_server s, tb_service sv
      WHERE s.server_id = sv.server_id AND sv.service_type = 'LBDIST-HTTP' AND sv.enabled = TRUE
    )
    , engine_update AS (
      /* ========================================================================================================================= 엔진 업데이트 정보 */
      SELECT MAX(CASE WHEN es.pkg_type = 'UPDATE_OES' THEN es.url ELSE '' END) AS oes_url
            , MAX(CASE WHEN es.pkg_type = 'UPDATE_SES' THEN es.url ELSE '' END) AS ses_url
            , MAX(CASE WHEN es.pkg_type = 'UPDATE_OES' THEN es.url_list ELSE '' END) AS oes_url_list
            , MAX(CASE WHEN es.pkg_type = 'UPDATE_SES' THEN es.url_list ELSE '' END) AS ses_url_list
      FROM (
        SELECT
          pkg_type
          , concat(sp_get_lbdist_http(false), path) AS url
          , REPLACE(array_to_string(ARRAY(SELECT unnest(string_to_array((sp_get_lbdist_http(true)), ','))||path), ','), ',', '","') AS url_list
        FROM tb_product_pkg
        WHERE pkg_type = 'UPDATE_OES'
          AND is_removed = false
          AND version = (SELECT c.value FROM tb_config AS c WHERE c.config_group = 'UPDATE_SERVICE' AND c.key = 'oes_engine_date')
        UNION ALL
        SELECT
          pkg_type
          , concat(sp_get_lbdist_http(false), path) AS url
          , REPLACE(array_to_string(ARRAY(SELECT unnest(string_to_array((sp_get_lbdist_http(true)), ','))||path), ','), ',', '","') AS url_list
        FROM tb_product_pkg
        WHERE pkg_type = 'UPDATE_SES'
          AND is_removed = false
          AND version = (SELECT c.value FROM tb_config AS c WHERE c.config_group = 'UPDATE_SERVICE' AND c.key = 'ses_engine_date')
      ) es
    )
    , engine_update_private AS (
      /* ========================================================================================================================= 엔진 업데이트 정보(사설망) */
      SELECT MAX(CASE WHEN es.pkg_type = 'UPDATE_OES' THEN es.url ELSE '' END) AS oes_url
            , MAX(CASE WHEN es.pkg_type = 'UPDATE_SES' THEN es.url ELSE '' END) AS ses_url
            , MAX(CASE WHEN es.pkg_type = 'UPDATE_OES' THEN es.url_list ELSE '' END) AS oes_url_list
            , MAX(CASE WHEN es.pkg_type = 'UPDATE_SES' THEN es.url_list ELSE '' END) AS ses_url_list
      FROM (
        SELECT
          pkg_type
          , concat((SELECT server_lbdist_http FROM private_lbdist_http), path) AS url
          , REPLACE(array_to_string(ARRAY(SELECT unnest(string_to_array((SELECT server_lbdist_http_list FROM private_lbdist_http_list), ','))||path), ','), ',', '","') AS url_list
        FROM tb_product_pkg
        WHERE pkg_type = 'UPDATE_OES'
          AND is_removed = false
          AND version = (SELECT c.value FROM tb_config AS c WHERE c.config_group = 'UPDATE_SERVICE' AND c.key = 'oes_engine_date')
        UNION ALL
        SELECT pkg_type
          , concat((SELECT server_lbdist_http FROM private_lbdist_http), path) AS url
          , REPLACE(array_to_string(ARRAY(SELECT unnest(string_to_array((SELECT server_lbdist_http_list FROM private_lbdist_http_list), ','))||path), ','), ',', '","') AS url_list
        FROM tb_product_pkg
        WHERE pkg_type = 'UPDATE_SES'
          AND is_removed = false
          AND version = (SELECT c.value FROM tb_config AS c WHERE c.config_group = 'UPDATE_SERVICE' AND c.key = 'ses_engine_date')
      ) es
    )
    , ip4 AS (
      /* ========================================================================================================================= IP4 정보 */
      SELECT COALESCE(array_to_json(array_agg(row_to_json(sv))),'[]')::text AS info
      FROM (
        SELECT (CASE WHEN (SELECT tc.value FROM tb_config tc WHERE tc.config_group = 'NETWORK' AND tc.key = 'use_nat') = 'true' THEN s.public_ip ELSE s.ip END),
              (SELECT sp.port FROM tb_service_port sp WHERE sp.service_type = sv.service_type) AS port
        FROM tb_server s, tb_service sv
        WHERE s.server_id = sv.server_id AND sv.service_type = 'LBAGENT' AND sv.enabled = true
        ORDER BY sv.static DESC
      ) sv
    )
    , ip4_private AS (
      /* ========================================================================================================================= IP4 정보(사설망) */
      SELECT COALESCE(array_to_json(array_agg(row_to_json(sv))),'[]')::text AS info
      FROM (
        SELECT s.ip, (SELECT sp.port FROM tb_service_port sp WHERE sp.service_type = sv.service_type) AS port
        FROM tb_server s, tb_service sv
        WHERE s.server_id = sv.server_id AND sv.service_type = 'LBAGENT' AND sv.enabled = true
        ORDER BY sv.static DESC
      ) sv
    )
    , license_info as (
      /* ========================================================================================================================= 라이센스 정보 */
      SELECT
        product_id
        , JSON_BUILD_OBJECT('license_no', CASE WHEN version IS NULL OR version != '2.0' THEN license_no ELSE NULL END, 'license_org', company_name, 'license_user', user_name)::text AS license_data
        , JSON_BUILD_OBJECT('activation_code', CASE WHEN version = '2.0' THEN license_no ELSE NULL END, 'license_org', company_name, 'license_user', user_name)::text AS license_data_v2
      FROM (
        SELECT
          CASE WHEN p.product_id = 'EMS' THEN 'AGENT' ELSE p.product_id END product_id
          , l.license_no, c.company_name, c.user_name, l.version
        FROM
          tb_product p
          LEFT JOIN (
            SELECT
              product_id, license_no, "version"
            FROM (
              SELECT
                product_id, license_no, "version"
                , ROW_NUMBER() OVER(PARTITION BY product_id ORDER BY expire_date DESC) AS order_by_expired
              FROM tb_product_license
            ) l
                  WHERE
                    l.order_by_expired = 1
              ) l ON p.product_id = l.product_id
              , (
                SELECT MAX(CASE WHEN key = 'company_name' THEN value END) AS company_name, MAX(CASE WHEN key = 'user_name' THEN value end) AS user_name
                FROM tb_config
                WHERE config_group = 'SYS_INFO'
                  AND key IN ('company_name', 'user_name')
              ) c
              WHERE p.product_id NOT IN ('AGENT')
            ) r
    )
    , hips_geo_db_update AS (
    	SELECT
    		array_to_json(coalesce(array_agg(t.geo_db_update), '{}'::json[]))::TEXT AS geo_db_update
    	FROM
	    	(SELECT
	    		json_build_object(
	    			'geo_db_url', concat(sp_get_lbdist_http(FALSE), path) || '/' || name
	    			, 'geo_db_hash', content_hash_value
	    			, 'geo_db_hash_algorithm', lower(content_hash_algorithm::TEXT)
	    			, 'geo_db_enc_algorithm', lower(enc_algorithm::TEXT)
	    			, 'geo_db_enc_key', enc_key
	    		) AS geo_db_update
	    	FROM tb_product_pkg
	    	WHERE pkg_type = 'IPS_GEO_DB' AND is_removed IS FALSE
	    	ORDER BY modified_time DESC
	    	LIMIT 1) t
    )
    , hips_geo_db_update_private AS (
    	SELECT
    		array_to_json(coalesce(array_agg(t.geo_db_update), '{}'::json[]))::TEXT AS geo_db_update
    	FROM
    		(SELECT
    			json_build_object(
    				'geo_db_url', concat((SELECT server_lbdist_http FROM private_lbdist_http), path) || '/' || name
    				, 'geo_db_hash', content_hash_value
    				, 'geo_db_hash_algorithm', lower(content_hash_algorithm::TEXT)
	    			, 'geo_db_enc_algorithm', lower(enc_algorithm::TEXT)
	    			, 'geo_db_enc_key', enc_key
    			) AS geo_db_update
    		FROM tb_product_pkg
    		WHERE pkg_type = 'IPS_GEO_DB' AND is_removed IS FALSE
    		ORDER BY modified_time DESC
    		LIMIT 1) t
    )
    , hips_user_geo_db AS (
    	SELECT array_to_json(coalesce(array_agg(t.user_geo_db), '{}'::json[]))::TEXT AS user_geo_db
    	FROM
    		(SELECT	json_build_object('code', country_code, 'ip', access_ip) AS user_geo_db	FROM tb_user_country_settings) t
    )
    , hips_default_signature_update AS (
    	SELECT array_to_json(coalesce(array_agg(t.signature), '{}'::json[]))::TEXT signature
    	FROM
	    	(SELECT
	    		json_build_object(
					'signature_url', concat(sp_get_lbdist_http(FALSE), path) || '/' || name
					, 'signature_hash', content_hash_value
					, 'signature_hash_algorithm', lower(content_hash_algorithm::TEXT)
					, 'signature_enc_algorithm', lower(enc_algorithm::TEXT)
					, 'signature_enc_key', enc_key
				) AS signature
	    	FROM tb_product_pkg
	    	WHERE pkg_type = 'IPS_DEFAULT_SIGNATURE' AND is_removed IS FALSE
	    	ORDER BY modified_time DESC
	    	LIMIT 1) t
    )
    , hips_default_signature_update_private AS (
    	SELECT
    		array_to_json(coalesce(array_agg(t.signature), '{}'::json[]))::TEXT AS signature
    	FROM
    		(SELECT
    			json_build_object(
    				'signature_url', concat((SELECT server_lbdist_http FROM private_lbdist_http), path) || '/' || name
    				, 'signature_hash', content_hash_value
    				, 'signature_hash_algorithm', lower(content_hash_algorithm::TEXT)
					, 'signature_enc_algorithm', lower(enc_algorithm::TEXT)
					, 'signature_enc_key', enc_key
    			) AS signature
    		FROM tb_product_pkg
    		WHERE pkg_type = 'IPS_DEFAULT_SIGNATURE' AND is_removed IS FALSE
    		ORDER BY modified_time DESC
	    	LIMIT 1) t
    )
    , hips_user_signature_update AS (
    	SELECT
    		array_to_json(coalesce(array_agg(t.signature), '{}'::json[]))::TEXT signature
    	FROM
	    	(SELECT
	    		json_build_object(
	    			'signature_url', concat(sp_get_lbdist_http(FALSE), path) || '/' || name
	    			, 'signature_hash', content_hash_value
	    			, 'signature_hash_algorithm', lower(content_hash_algorithm::TEXT)
	    			, 'signature_enc_algorithm', lower(enc_algorithm::TEXT)
	    			, 'signature_enc_key', enc_key
	    		) AS signature
	    	FROM tb_product_pkg
	    	WHERE pkg_type = 'IPS_USER_SIGNATURE' AND is_removed IS FALSE
	    	ORDER BY modified_time DESC
	    	LIMIT 1) t
    )
    , hips_user_signature_update_private AS (
    	SELECT
    		array_to_json(coalesce(array_agg(t.signature), '{}'::json[]))::TEXT AS signature
    	FROM
    		(SELECT
    			json_build_object(
    				'signature_url', concat((SELECT server_lbdist_http FROM private_lbdist_http), path) || '/' || name
    				, 'signature_hash', content_hash_value
    				, 'signature_hash_algorithm', lower(content_hash_algorithm::TEXT)
	    			, 'signature_enc_algorithm', lower(enc_algorithm::TEXT)
	    			, 'signature_enc_key', enc_key
    			) AS signature
    		FROM tb_product_pkg
    		WHERE pkg_type = 'IPS_USER_SIGNATURE' AND is_removed IS FALSE
    		ORDER BY modified_time DESC
    		LIMIT 1) t
    )
    , im_predefined_update AS (
      SELECT
        array_to_json(coalesce(array_agg(t.im_predefined), '{}'::json[]))::TEXT im_predefined
      FROM
        (SELECT
          json_build_object(
            'rule_url', concat(sp_get_lbdist_http(FALSE), path) || '/' || name
            , 'rule_hash', content_hash_value
            , 'rule_hash_algorithm', lower(content_hash_algorithm::TEXT)
            , 'rule_enc_algorithm', lower(enc_algorithm::TEXT)
            , 'rule_enc_key', enc_key
          ) AS im_predefined
        FROM tb_product_pkg
        WHERE pkg_type = 'IM_PREDEFINED' AND is_removed IS FALSE
        ORDER BY modified_time DESC
        LIMIT 1) t
    )
    , im_predefined_update_private AS (
      SELECT
        array_to_json(coalesce(array_agg(t.im_predefined), '{}'::json[]))::TEXT im_predefined
      FROM
        (SELECT
          json_build_object(
            'rule_url', concat((SELECT server_lbdist_http FROM private_lbdist_http), path) || '/' || name
            , 'rule_hash', content_hash_value
            , 'rule_hash_algorithm', lower(content_hash_algorithm::TEXT)
            , 'rule_enc_algorithm', lower(enc_algorithm::TEXT)
            , 'rule_enc_key', enc_key
          ) AS im_predefined
        FROM tb_product_pkg
        WHERE pkg_type = 'IM_PREDEFINED' AND is_removed IS FALSE
        ORDER BY modified_time DESC
        LIMIT 1) t
    )
    , im_userdefined_update AS (
      SELECT
        array_to_json(coalesce(array_agg(t.im_userdefined), '{}'::json[]))::TEXT im_userdefined
      FROM
        (SELECT
          json_build_object(
            'rule_url', concat(sp_get_lbdist_http(FALSE), path) || '/' || name
            , 'rule_hash', content_hash_value
            , 'rule_hash_algorithm', lower(content_hash_algorithm::TEXT)
            , 'rule_enc_algorithm', lower(enc_algorithm::TEXT)
            , 'rule_enc_key', enc_key
          ) AS im_userdefined
        FROM tb_product_pkg
        WHERE pkg_type = 'IM_USERDEFINED' AND is_removed IS FALSE
        ORDER BY modified_time DESC
        LIMIT 1) t
    )
    , im_userdefined_update_private AS (
      SELECT
        array_to_json(coalesce(array_agg(t.im_userdefined), '{}'::json[]))::TEXT im_userdefined
      FROM
        (SELECT
          json_build_object(
            'rule_url', concat((SELECT server_lbdist_http FROM private_lbdist_http), path) || '/' || name
            , 'rule_hash', content_hash_value
            , 'rule_hash_algorithm', lower(content_hash_algorithm::TEXT)
            , 'rule_enc_algorithm', lower(enc_algorithm::TEXT)
            , 'rule_enc_key', enc_key
          ) AS im_userdefined
        FROM tb_product_pkg
        WHERE pkg_type = 'IM_USERDEFINED' AND is_removed IS FALSE
        ORDER BY modified_time DESC
        LIMIT 1) t
    )
    , scm_predefined_update AS (
      SELECT
        array_to_json(coalesce(array_agg(t.scm_predefined), '{}'::json[]))::TEXT scm_predefined
      FROM
        (SELECT
          json_build_object(
            'rule_version', version
            , 'rule_url', concat(sp_get_lbdist_http(FALSE), path) || '/' || name
            , 'rule_hash', content_hash_value
            , 'rule_hash_algorithm', lower(content_hash_algorithm::TEXT)
          ) AS scm_predefined
        FROM tb_product_pkg
        WHERE pkg_type = 'SCM_PREDEFINED' AND is_removed IS FALSE
        ORDER BY modified_time DESC
        LIMIT 1) t
    )
    , scm_predefined_update_private AS (
      SELECT
        array_to_json(coalesce(array_agg(t.scm_predefined), '{}'::json[]))::TEXT scm_predefined
      FROM
        (SELECT
          json_build_object(
            'rule_version', version
            , 'rule_url', concat((SELECT server_lbdist_http FROM private_lbdist_http), path) || '/' || name
            , 'rule_hash', content_hash_value
            , 'rule_hash_algorithm', lower(content_hash_algorithm::TEXT)
          ) AS scm_predefined
        FROM tb_product_pkg
        WHERE pkg_type = 'SCM_PREDEFINED' AND is_removed IS FALSE
        ORDER BY modified_time DESC
        LIMIT 1) t
    )
    , scm_userdefined_update AS (
      SELECT
        array_to_json(coalesce(array_agg(t.scm_userdefined), '{}'::json[]))::TEXT scm_userdefined
      FROM
        (SELECT
          json_build_object(
            'rule_version', version
            , 'rule_url', concat(sp_get_lbdist_http(FALSE), path) || '/' || name
            , 'rule_hash', content_hash_value
            , 'rule_hash_algorithm', lower(content_hash_algorithm::TEXT)
          ) AS scm_userdefined
        FROM tb_product_pkg
        WHERE pkg_type = 'SCM_USERDEFINED' AND is_removed IS FALSE
        ORDER BY modified_time DESC
        LIMIT 1) t
    )
    , scm_userdefined_update_private AS (
      SELECT
        array_to_json(coalesce(array_agg(t.scm_userdefined), '{}'::json[]))::TEXT scm_userdefined
      FROM
        (SELECT
          json_build_object(
            'rule_version', version
            , 'rule_url', concat((SELECT server_lbdist_http FROM private_lbdist_http), path) || '/' || name
            , 'rule_hash', content_hash_value
            , 'rule_hash_algorithm', lower(content_hash_algorithm::TEXT)
          ) AS scm_userdefined
        FROM tb_product_pkg
        WHERE pkg_type = 'SCM_USERDEFINED' AND is_removed IS FALSE
        ORDER BY modified_time DESC
        LIMIT 1) t
    )
    ,pg_server_config AS (
    	SELECT COALESCE(array_to_json(array_agg(addr)),'[]')::text AS pg_server
        FROM (
        	SELECT concat(ip, ':', port) AS addr
        	FROM tb_pg_server
        	WHERE pg_service_status IN ('REDIRECT', 'SIMULATION')
        ) sv
    )
    , log_filter_config AS (
		SELECT json_object(lf.log_type, lf.send)::text AS log_filter
		FROM (
			SELECT array_agg(lc.log_type)::TEXT[] AS log_type, array_agg(NOT(lc.send))::TEXT[] AS send
			FROM (SELECT log_type, send AND sp_check_license(product_group_type) AS send FROM tb_log_config) lc
		) lf
	)
	, metering_config AS (
		SELECT mc.value AS metering
		FROM (
			SELECT value as value FROM tb_config WHERE config_group = 'METERING' AND key = 'metering_setting'
		) mc
	)
	, scheduler_config AS (
		SELECT json_object_agg(p.product_id, p.json_data)::text AS schedule
		FROM (
			SELECT p.product_id,
			CASE WHEN p.software_info_is_use THEN
			  json_build_object('upload_event_log', json_build_object('is_use', p.event_log_is_use, 'type', p.event_log_type, 'cycle', p.event_log_cycle)
			      , 'metering_send', (SELECT value::json FROM tb_config WHERE config_group = 'METERING' AND key = 'metering_send'))
			ELSE
			  json_build_object('upload_event_log', json_build_object('is_use', p.event_log_is_use, 'type', p.event_log_type, 'cycle', p.event_log_cycle)
			      , 'upload_software_info', json_build_object('is_use', p.software_info_is_use, 'type', p.software_info_type, 'cycle', p.software_info_cycle)
			      , 'metering_send', (SELECT value::json FROM tb_config WHERE config_group = 'METERING' AND key = 'metering_send'))
			END AS json_data
			FROM (
				SELECT product_id, TRUE AS event_log_is_use, 'cycle' AS event_log_type, concat(sp_get_config_group('AGENT_SEND_LOG', 'send_log_interval'),'m') AS event_log_cycle
		    		, TRUE AS software_info_is_use, 'cycle' AS software_info_type, concat(sp_get_config_group('AGENT_SEND_LOG', 'send_log_interval'),'m') AS software_info_cycle
				FROM tb_product AS p
				WHERE product_id = 'AGENT' 	AND p.is_upload_event_log IS TRUE
			) AS p
			UNION ALL
			SELECT p.product_id, json_build_object('upload_event_log', json_build_object('is_use', p.event_log_is_use, 'type', p.event_log_type, 'cycle', p.event_log_cycle)) AS json_data
			FROM (
				SELECT product_id, TRUE AS event_log_is_use, 'cycle' AS event_log_type, concat(sp_get_config_group('AGENT_SEND_LOG', 'send_log_interval'),'m') AS event_log_cycle
				FROM tb_product AS p
				WHERE product_id != 'AGENT'	AND p.is_upload_event_log IS TRUE
			) AS p
		) p
	)
  , manage_product_list AS (
    SELECT
      json_data.key AS product_id
      , json_data.value::boolean AS is_managed
    FROM
      (SELECT value FROM tb_config WHERE config_group = 'AGENT_MANAGE_PRODUCT' AND key = 'manage_product') AS config, json_each_text(config.value::json) AS json_data
  )
  , add_manage_product AS (
		SELECT
      CASE WHEN ARRAY_AGG(product_id) IS NULL THEN JSON_BUILD_ARRAY()::TEXT
      ELSE ARRAY_TO_JSON(ARRAY_AGG(product_id))::TEXT END AS product_id_list
    FROM manage_product_list
    WHERE is_managed IS TRUE
	)
  , delete_manage_product AS (
    SELECT
      CASE WHEN ARRAY_AGG(product_id) IS NULL THEN JSON_BUILD_ARRAY()::TEXT
      ELSE ARRAY_TO_JSON(ARRAY_AGG(product_id))::TEXT END AS product_id_list
    FROM manage_product_list
    WHERE is_managed IS FALSE
  )
  , hips_recommendationpack AS (
    	SELECT
    		array_to_json(coalesce(array_agg(t.recommendationpack), '{}'::json[]))::TEXT recommendationpack
    	FROM
	    	(SELECT
	    		json_build_object(
	    			'recommendationpack_type', 'reserved'
	    			, 'recommendationpack_url', concat(sp_get_lbdist_http(FALSE), path) || '/' || name
	    			, 'recommendationpack_hash', content_hash_value
	    			, 'recommendationpack_hash_algorithm', lower(content_hash_algorithm::TEXT)
	    			, 'recommendationpack_enc_key', enc_key
	    			, 'recommendationpack_enc_algorithm', lower(enc_algorithm::TEXT)
	    		) AS recommendationpack
	    	FROM tb_product_pkg
	    	WHERE pkg_type = 'IPS_DEFAULT_OVAL' AND is_removed IS FALSE
	    	ORDER BY modified_time DESC
	    	LIMIT 1) t
    )
    , hips_recommendationpack_private AS (
    	SELECT
    		array_to_json(coalesce(array_agg(t.recommendationpack), '{}'::json[]))::TEXT recommendationpack
    	FROM
	    	(SELECT
	    		json_build_object(
	    			'recommendationpack_type', 'reserved'
	    			, 'recommendationpack_url', concat((SELECT server_lbdist_http FROM private_lbdist_http), path) || '/' || name
	    			, 'recommendationpack_hash', content_hash_value
	    			, 'recommendationpack_hash_algorithm', lower(content_hash_algorithm::TEXT)
	    			, 'recommendationpack_enc_key', enc_key
	    			, 'recommendationpack_enc_algorithm', lower(enc_algorithm::TEXT)
	    		) AS recommendationpack
	    	FROM tb_product_pkg
	    	WHERE pkg_type = 'IPS_DEFAULT_OVAL' AND is_removed IS FALSE
	    	ORDER BY modified_time DESC
	    	LIMIT 1) t
    )
    , hips_mgmt_recommendation AS (
      SELECT
