              , '\${HIPS_LICENSE_DATA}', COALESCE((SELECT license_data FROM license_info WHERE product_id = 'HIPS_CLIENT'), '{"license_no" : null, "license_org" : null, "license_user" : null}'), 'g')
              , '\${V3NET_LU_LICENSE_DATA}', COALESCE((SELECT license_data FROM license_info WHERE product_id = 'V3NET_LU'), '{"license_no" : null, "license_org" : null, "license_user" : null}'), 'g')
              , '\${AGENT_LICENSE_DATA_V2}', COALESCE((SELECT license_data_v2 FROM license_info WHERE product_id = 'AGENT'), '{"activation_code" : null, "license_org" : null, "license_user" : null}'), 'g')
              , '\${V3NET_9.0_LICENSE_DATA_V2}', COALESCE((SELECT license_data_v2 FROM license_info WHERE product_id = 'V3NET_9.0'), '{"activation_code" : null, "license_org" : null, "license_user" : null}'), 'g')
              , '\${AC_LICENSE_DATA_V2}', COALESCE((SELECT license_data_v2 FROM license_info WHERE product_id = 'AC_CLIENT'), '{"activation_code" : null, "license_org" : null, "license_user" : null}'), 'g')
              , '\${HIPS_LICENSE_DATA_V2}', COALESCE((SELECT license_data_v2 FROM license_info WHERE product_id = 'HIPS_CLIENT'), '{"activation_code" : null, "license_org" : null, "license_user" : null}'), 'g')
              , '\${V3NET_LU_LICENSE_DATA_V2}', COALESCE((SELECT license_data_v2 FROM license_info WHERE product_id = 'V3NET_LU'), '{"activation_code" : null, "license_org" : null, "license_user" : null}'), 'g')
              , '\${AMC_LICENSE_DATA_V2}', COALESCE((SELECT license_data_v2 FROM license_info WHERE product_id = 'AMC_CLIENT'), '{"activation_code" : null, "license_org" : null, "license_user" : null}'), 'g')
              , '\${PG_SERVER}', (SELECT pg_server FROM pg_server_config), 'g')
              , '\${LOG_FILTER_CONFIG}', (SELECT log_filter FROM log_filter_config), 'g')
              , '\${METERING_CONFIG}', (SELECT metering FROM metering_config), 'g')
              , '\${SCHEDULE_CONFIG}', (SELECT schedule FROM scheduler_config), 'g')
              , '\${LOG_SEND_HIPS_AGENT}', (SELECT (send AND sp_exist_license(product_group_type))::TEXT FROM tb_log_config WHERE log_type = 'HIPS_AGENT_EVENT'), 'g')
              , '\${LOG_SEND_HIPS_DETECT}', (SELECT (send AND sp_exist_license(product_group_type))::TEXT FROM tb_log_config WHERE log_type = 'HIPS_EVENT'), 'g')
              , '\${LOG_SEND_HIPS_FW}', (SELECT (send AND sp_exist_license(product_group_type))::TEXT FROM tb_log_config WHERE log_type = 'FW_EVENT'), 'g')
              , '\${LOG_SEND_AC_AGENT}', (SELECT (send AND sp_exist_license(product_group_type))::TEXT FROM tb_log_config WHERE log_type = 'AC_AGENT_EVENT'), 'g')
              , '\${LOG_SEND_AC_EXEC}', (SELECT (send AND sp_exist_license(product_group_type))::TEXT FROM tb_log_config WHERE log_type = 'AC_EVENT'), 'g')
              , '\${LOG_SEND_AC_ACCESS}', (SELECT (send AND sp_exist_license(product_group_type))::TEXT FROM tb_log_config WHERE log_type = 'AC_EVENT'), 'g')
              , '\${LOG_SEND_AC_IM}', (SELECT (send AND sp_exist_license(product_group_type))::TEXT FROM tb_log_config WHERE log_type = 'AC_IM_EVENT'), 'g')
              , '\${ADD_MANAGE_PRODUCT}', (SELECT product_id_list FROM add_manage_product), 'g')
              , '\${DELETE_MANAGE_PRODUCT}', (SELECT product_id_list FROM delete_manage_product), 'g')
              , '\${LOG_SEND_SCM_AGENT}', (SELECT (send AND sp_exist_license(product_group_type))::TEXT FROM tb_log_config WHERE log_type = 'SCM_AGENT'), 'g')
              , '\${LOG_SEND_SCM_SCAN}', (SELECT (send AND sp_exist_license(product_group_type))::TEXT FROM tb_log_config WHERE log_type = 'SCM_SCAN'), 'g')
              , '\${SCM_PREDEFINED_RULE}', COALESCE((SELECT scm_predefined FROM scm_predefined_update), ''), 'g')
              , '\${SCM_USERDEFINED_RULE}', COALESCE((SELECT scm_userdefined FROM scm_userdefined_update), ''), 'g')
              , '\${SCM_LICENSE_DATA}', COALESCE((SELECT license_data FROM license_info WHERE product_id = 'SCM_CLIENT'), '{"license_no" : null, "license_org" : null, "license_user" : null}'), 'g')
              , '\${HIPS_RECOMMENDATIONPACK}', COALESCE((SELECT recommendationpack FROM hips_recommendationpack), ''), 'g')
              , '\${HIPS_RECOMMENDATION}', (SELECT hips_mgmt_recommendation FROM hips_mgmt_recommendation)::TEXT, 'g')
        ) new_policy_data,
        sp_base64_encode(
          REGEXP_REPLACE(
          REGEXP_REPLACE(
          REGEXP_REPLACE(
          REGEXP_REPLACE(
          REGEXP_REPLACE(
          REGEXP_REPLACE(
          REGEXP_REPLACE(
