          REGEXP_REPLACE(
          REGEXP_REPLACE(
          REGEXP_REPLACE(
          REGEXP_REPLACE(
          REGEXP_REPLACE(
          REGEXP_REPLACE(
          REGEXP_REPLACE(
          REGEXP_REPLACE(
          REGEXP_REPLACE(
          REGEXP_REPLACE(
          REGEXP_REPLACE(
          REGEXP_REPLACE(d.new_policy_data
            , '\${ENGINE_UPDATE_OES}', COALESCE((SELECT oes_url FROM engine_update_private), ''), 'g')
              , '\${ENGINE_UPDATE_SES}', COALESCE((SELECT ses_url FROM engine_update_private), ''), 'g')
              , '\${AMC_LICENSE_DATA}', COALESCE((SELECT license_data FROM license_info WHERE product_id = 'AMC_CLIENT'), '{"license_no" : null, "license_org" : null, "license_user" : null}'), 'g')
			        , '\${LOG_SEND_AMC_ALERT}', (SELECT (send AND sp_exist_license(product_group_type))::TEXT FROM tb_log_config WHERE log_type = 'V3_ALERT'), 'g')
		          , '\${LOG_SEND_AMC_SS}', (SELECT (send AND sp_exist_license(product_group_type))::TEXT FROM tb_log_config WHERE log_type = 'V3_SS'), 'g')
			        , '\${LOG_SEND_AMC_IS}', (SELECT (send AND sp_exist_license(product_group_type))::TEXT FROM tb_log_config WHERE log_type = 'V3_IS'), 'g')
			        , '\${LOG_SEND_AMC_SUP}', (SELECT (send AND sp_exist_license(product_group_type))::TEXT FROM tb_log_config WHERE log_type = 'V3_SUP'), 'g')
              , '\${LOG_SEND_AMC_DEVICE}', (SELECT (send AND sp_exist_license(product_group_type))::TEXT FROM tb_log_config WHERE log_type = 'V3_DEVICE'), 'g')
			        , '\${LOG_SEND_AMC_QUAR}', (SELECT (send AND sp_exist_license(product_group_type))::TEXT FROM tb_log_config WHERE log_type = 'V3_QUAR'), 'g')
              , '\${ENGINE_UPDATE_OES_LIST}', COALESCE((SELECT oes_url_list FROM engine_update_private), ''), 'g')
              , '\${ENGINE_UPDATE_SES_LIST}', COALESCE((SELECT ses_url_list FROM engine_update_private), ''), 'g')
              , '\${IP4_INFO}', (SELECT info FROM ip4_private), 'g')
              , '\${HIPS_GEO_DB}', COALESCE((SELECT geo_db_update FROM hips_geo_db_update_private), ''), 'g')
              , '\${HIPS_USER_GEO_DB}', COALESCE((SELECT user_geo_db FROM hips_user_geo_db), ''), 'g')
              , '\${HIPS_DEFAULT_SIGNATURE}', COALESCE((SELECT signature FROM hips_default_signature_update_private), ''), 'g')
              , '\${HIPS_USER_SIGNATURE}', COALESCE((SELECT signature FROM hips_user_signature_update_private), ''), 'g')
              , '\${IM_PREDEFINED_RULE}', COALESCE((SELECT im_predefined FROM im_predefined_update_private), ''), 'g')
              , '\${IM_USERDEFINED_RULE}', COALESCE((SELECT im_userdefined FROM im_userdefined_update_private), ''), 'g')
              , '\${SITE_AUTH_KEY}', COALESCE((SELECT i_site_auth_key), ''), 'g')
              , '\${AGENT_MGMT_KEY}', COALESCE((SELECT CONCAT('AGENT_MGMT_', value, '_KEY') AS value FROM tb_config WHERE config_group = 'AGENT_MGMT_KEY' AND "key" = 'agent_mgmt_key'), ''), 'g')
              , '\${AGENT_LICENSE_DATA}', COALESCE((SELECT license_data FROM license_info WHERE product_id = 'AGENT'), '{"license_no" : null, "license_org" : null, "license_user" : null}'), 'g')
              , '\${V3NET_9.0_LICENSE_DATA}', COALESCE((SELECT license_data FROM license_info WHERE product_id = 'V3NET_9.0'), '{"license_no" : null, "license_org" : null, "license_user" : null}'), 'g')
              , '\${AC_LICENSE_DATA}', COALESCE((SELECT license_data FROM license_info WHERE product_id = 'AC_CLIENT'), '{"license_no" : null, "license_org" : null, "license_user" : null}'), 'g')
              , '\${HIPS_LICENSE_DATA}', COALESCE((SELECT license_data FROM license_info WHERE product_id = 'HIPS_CLIENT'), '{"license_no" : null, "license_org" : null, "license_user" : null}'), 'g')
              , '\${V3NET_LU_LICENSE_DATA}', COALESCE((SELECT license_data FROM license_info WHERE product_id = 'V3NET_LU'), '{"license_no" : null, "license_org" : null, "license_user" : null}'), 'g')
              , '\${AGENT_LICENSE_DATA_V2}', COALESCE((SELECT license_data_v2 FROM license_info WHERE product_id = 'AGENT'), '{"license_no" : null, "license_org" : null, "license_user" : null}'), 'g')
              , '\${V3NET_9.0_LICENSE_DATA_V2}', COALESCE((SELECT license_data_v2 FROM license_info WHERE product_id = 'V3NET_9.0'), '{"license_no" : null, "license_org" : null, "license_user" : null}'), 'g')
              , '\${AC_LICENSE_DATA_V2}', COALESCE((SELECT license_data_v2 FROM license_info WHERE product_id = 'AC_CLIENT'), '{"license_no" : null, "license_org" : null, "license_user" : null}'), 'g')
              , '\${HIPS_LICENSE_DATA_V2}', COALESCE((SELECT license_data_v2 FROM license_info WHERE product_id = 'HIPS_CLIENT'), '{"license_no" : null, "license_org" : null, "license_user" : null}'), 'g')
              , '\${V3NET_LU_LICENSE_DATA_V2}', COALESCE((SELECT license_data_v2 FROM license_info WHERE product_id = 'V3NET_LU'), '{"license_no" : null, "license_org" : null, "license_user" : null}'), 'g')
              , '\${AMC_LICENSE_DATA_V2}', COALESCE((SELECT license_data_v2 FROM license_info WHERE product_id = 'AMC_CLIENT'), '{"license_no" : null, "license_org" : null, "license_user" : null}'), 'g')
              , '\${PG_SERVER}', (SELECT pg_server FROM pg_server_config), 'g')
              , '\${LOG_FILTER_CONFIG}', (SELECT log_filter FROM log_filter_config), 'g')
              , '\${METERING_CONFIG}', (SELECT metering FROM metering_config), 'g')
              , '\${SCHEDULE_CONFIG}', (SELECT schedule FROM scheduler_config), 'g')
              , '\${LOG_SEND_HIPS_AGENT}', (SELECT (send AND sp_exist_license(product_group_type))::TEXT FROM tb_log_config WHERE log_type = 'HIPS_AGENT_EVENT'), 'g')
              , '\${LOG_SEND_HIPS_DETECT}', (SELECT (send AND sp_exist_license(product_group_type))::TEXT FROM tb_log_config WHERE log_type = 'HIPS_EVENT'), 'g')
              , '\${LOG_SEND_HIPS_FW}', (SELECT (send AND sp_exist_license(product_group_type))::TEXT FROM tb_log_config WHERE log_type = 'FW_EVENT'), 'g')
              , '\${LOG_SEND_AC_AGENT}', (SELECT (send AND sp_exist_license(product_group_type))::TEXT FROM tb_log_config WHERE log_type = 'AC_AGENT_EVENT'), 'g')
              , '\${LOG_SEND_AC_EXEC}', (SELECT (send AND sp_exist_license(product_group_type))::TEXT FROM tb_log_config WHERE log_type = 'AC_EVENT'), 'g')
              , '\${LOG_SEND_AC_ACCESS}', (SELECT (send AND sp_exist_license(product_group_type))::TEXT FROM tb_log_config WHERE log_type = 'AC_EVENT'), 'g')
              , '\${LOG_SEND_AC_IM}', (SELECT (send AND sp_exist_license(product_group_type))::TEXT FROM tb_log_config WHERE log_type = 'AC_IM_EVENT'), 'g')
              , '\${ADD_MANAGE_PRODUCT}', (SELECT product_id_list FROM add_manage_product), 'g')
              , '\${DELETE_MANAGE_PRODUCT}', (SELECT product_id_list FROM delete_manage_product), 'g')
              , '\${LOG_SEND_SCM_AGENT}', (SELECT (send AND sp_exist_license(product_group_type))::TEXT FROM tb_log_config WHERE log_type = 'SCM_AGENT'), 'g')
              , '\${LOG_SEND_SCM_SCAN}', (SELECT (send AND sp_exist_license(product_group_type))::TEXT FROM tb_log_config WHERE log_type = 'SCM_SCAN'), 'g')
              , '\${SCM_PREDEFINED_RULE}', COALESCE((SELECT scm_predefined FROM scm_predefined_update_private), ''), 'g')
              , '\${SCM_USERDEFINED_RULE}', COALESCE((SELECT scm_userdefined FROM scm_userdefined_update_private), ''), 'g')
              , '\${SCM_LICENSE_DATA}', COALESCE((SELECT license_data FROM license_info WHERE product_id = 'SCM_CLIENT'), '{"license_no" : null, "license_org" : null, "license_user" : null}'), 'g')
              , '\${HIPS_RECOMMENDATIONPACK}', COALESCE((SELECT recommendationpack FROM hips_recommendationpack_private), ''), 'g')
              , '\${HIPS_RECOMMENDATION}', (SELECT hips_mgmt_recommendation FROM hips_mgmt_recommendation)::TEXT, 'g')

        ) new_policy_data_private
      FROM (
          SELECT
            cp.product_feature_id
            , cp.online_policy_data
            , cp.private_policy_data
            , online_policy_format AS new_policy_data
          FROM tb_common_policy cp
          WHERE cp.product_feature_id IN ('AGENT_MGMT', 'V3NET_9.0_AV','V3NET_LU_UPDATE', 'HIPS_AGENT', 'HIPS_MGMT', 'AC_AGENT','IM_MGMT', 'SCM_MGMT', 'SCM_AGENT', 'AMC_MGMT')
      ) d
    ), updated_rows AS (
      /* ========================================================================================================================= update value */
      UPDATE tb_common_policy p
          SET online_policy_data  = comp.new_policy_data,
              offline_policy_data = comp.new_policy_data,
              private_policy_data = comp.new_policy_data_private,
              hash_value = md5(concat(comp.new_policy_data, comp.new_policy_data)::text)
      FROM comparison comp
      WHERE p.product_feature_id = comp.product_feature_id
        AND ((COALESCE(comp.online_policy_data,'') != comp.new_policy_data) OR (COALESCE(comp.private_policy_data,'') != comp.new_policy_data_private))
      RETURNING p.product_feature_id
    )
    SELECT u.product_feature_id::text
          , CASE WHEN u.product_feature_id = 'AGENT_MGMT' THEN '[]' ELSE json_build_array(json_build_object('type','PRODUCT_ID','filter',json_agg(pfm.product_id)))::text END
    FROM updated_rows u
    JOIN tb_product_feature_map pfm ON u.product_feature_id = pfm.product_feature_id
    GROUP BY u.product_feature_id;

END;
$_$;


