CREATE FUNCTION public.sp_set_multi_admin_password(i_admin_id text, i_password text, i_encrypted_password text, i_current_password text, i_error_message text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  UPDATE tb_temp_admin_temp
    SET admin_pwd = i_encrypted_password
      , error_message = i_error_message
  WHERE admin_id = i_admin_id
    AND password = i_password;

END;
$$;


ALTER FUNCTION public.sp_set_multi_admin_password(i_admin_id text, i_password text, i_encrypted_password text, i_current_password text, i_error_message text) OWNER TO cppoltp;

