--
-- Name: sp_set_net_cert_mgmt_customer(text, text, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_net_cert_mgmt_customer(i_cert_server_cert_name text, i_cert_privatekey_name text, i_cert_privatekey_pw text, i_cert_chainca_cert_name text, i_cert_schedule text, i_cert_conceal_key text, i_password_change boolean) RETURNS TABLE(schedule_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_keys                      text[];
  v_values                    text[];

  v_schedule_id               text := null;
BEGIN

  v_keys := ARRAY[ 'cert_new_type', 'cert_schedule', 'cert_apply_status', 'cert_server_cert_name', 'cert_privatekey_name', 'cert_privatekey_pw', 'cert_chainca_cert_name', 'cert_conceal_key' ];
  v_values := ARRAY[ 'site', TRIM(i_cert_schedule), '1', i_cert_server_cert_name, i_cert_privatekey_name, i_cert_privatekey_pw, i_cert_chainca_cert_name, i_cert_conceal_key ];

  PERFORM sp_set_configs( 'SYS_NET_CERT', v_keys, v_values );


  -- 스케줄 관리
  IF i_cert_schedule IS NULL OR TRIM(i_cert_schedule) = '' THEN
    v_schedule_id := sp_set_unity_schedule_disabled( 'EPP_CERT' );
  ELSE
    v_schedule_id := sp_add_unity_schedule( 'EMS', 'EPP_CERT', 1, i_cert_schedule, true, '/api/console/config/certificate/customer/execute', null );
  END IF;


  RETURN QUERY
    SELECT v_schedule_id;

END;
$$;


ALTER FUNCTION public.sp_set_net_cert_mgmt_customer(i_cert_server_cert_name text, i_cert_privatekey_name text, i_cert_privatekey_pw text, i_cert_chainca_cert_name text, i_cert_schedule text, i_cert_conceal_key text, i_password_change boolean) OWNER TO cppoltp;

--
-- Name: sp_set_net_cert_mgmt_epp(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_net_cert_mgmt_epp(i_cert_schedule text) RETURNS TABLE(schedule_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_keys                      text[];
  v_values                    text[];
  execute_url                 text;

  v_flag                      text := null;
  v_schedule_id               text := null;
BEGIN

  v_keys := ARRAY[ 'cert_new_type', 'cert_schedule', 'cert_apply_status' ];
  v_values := ARRAY[ 'epp', TRIM(i_cert_schedule), '1' ];

  PERFORM sp_set_configs( 'SYS_NET_CERT', v_keys, v_values );
 
 IF (SELECT value FROM tb_config WHERE config_group = 'SYS_NET_CERT' AND "key" = 'cert_issue_type') = 'AUTOMATIC' THEN
 	execute_url = '/api/console/config/certificate/epp/execute/auto';  
 ELSE
 	execute_url = '/api/console/config/certificate/epp/execute';
 END IF;

  -- 스케줄 관리
  IF i_cert_schedule IS NULL OR TRIM(i_cert_schedule) = '' THEN
    v_schedule_id := sp_set_unity_schedule_disabled( 'EPP_CERT' );
  ELSE
    v_schedule_id := sp_add_unity_schedule( 'EMS', 'EPP_CERT', 1, i_cert_schedule, true, execute_url, null );
  END IF;

  RETURN QUERY
    SELECT v_schedule_id;

END;
$$;


ALTER FUNCTION public.sp_set_net_cert_mgmt_epp(i_cert_schedule text) OWNER TO cppoltp;

