--
-- Name: sp_set_node_connection(bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_node_connection(i_node_id bigint[]) RETURNS void
    LANGUAGE plpgsql
    AS $$

BEGIN

  UPDATE tb_node_status
  SET connection_status = 'DISCONNECTED'
  WHERE node_id = ANY(i_node_id)
  AND   connection_status <> 'UNINSTALLED';

END;
$$;


ALTER FUNCTION public.sp_set_node_connection(i_node_id bigint[]) OWNER TO cppoltp;

--
-- Name: sp_set_node_hash(bigint, public.en_node_hash_type, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_node_hash(i_node_id bigint, i_node_hash_type public.en_node_hash_type, i_hash_value text) RETURNS TABLE(err_code text, err_msg text)
    LANGUAGE plpgsql
    AS $$
DECLARE
      v_affected_cnt int;
    BEGIN

      INSERT
        INTO tb_node_hash ( node_id                       /* 노드 ID */
        , node_hash_type                    /* 해시 타입 */
        , hash_value                        /* 해시 값 */
        , modified_time )
      VALUES ( i_node_id
        , i_node_hash_type
        , i_hash_value
        , now()) ON CONFLICT (node_id
        , node_hash_type) DO
      UPDATE
      SET hash_value = EXCLUDED.hash_value                  /* 해시 값 */
      , modified_time = now();                    /* 변경 시각 */

      GET DIAGNOSTICS v_affected_cnt = ROW_COUNT;

      IF v_affected_cnt = 1 THEN
        RETURN QUERY SELECT '0'::text, 'ok'::text;
      END IF;

    END;
$$;


ALTER FUNCTION public.sp_set_node_hash(i_node_id bigint, i_node_hash_type public.en_node_hash_type, i_hash_value text) OWNER TO cppoltp;

--
-- Name: sp_set_notification_center(public.en_notification_type, text, public.en_notification_sub_type, public.en_notification_status_type, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_notification_center(i_notification_type public.en_notification_type, i_notification_id text, i_notification_sub_type public.en_notification_sub_type, i_notification_status public.en_notification_status_type, i_message text, i_admin_id text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  IF i_notification_sub_type NOT IN ('DELETE_AGENT') THEN

                notification_type, notification_id, notification_sub_type, notification_status,
                message, admin_id, admin_ip, modified_time)
    SELECT i_notification_type
          ,i_notification_id
          ,i_notification_sub_type
          ,i_notification_status
          ,replace(i_message, '\', '')
          ,i_admin_id
          ,a.connect_ipaddr
          ,now()
    FROM tb_admin a
    WHERE a.admin_id = i_admin_id
    ON CONFLICT (notification_type, notification_id)
    DO UPDATE
    SET notification_status = EXCLUDED.notification_status
       ,message = EXCLUDED.message
       ,admin_id = EXCLUDED.admin_id
       ,admin_ip = EXCLUDED.admin_ip
       ,modified_time = EXCLUDED.modified_time;

  ELSE

                notification_type, notification_id, notification_sub_type, notification_status,
                message, admin_id, admin_ip, modified_time)
    SELECT i_notification_type
          ,(SELECT coalesce((max(notification_id::BIGINT) + 1)::TEXT, '1') FROM tb_notification_center WHERE notification_sub_type = i_notification_sub_type)
          ,i_notification_sub_type
          ,i_notification_status
          ,replace(i_message, '\', '')
          ,i_admin_id
          ,a.connect_ipaddr
          ,now()
    FROM tb_admin a
    WHERE a.admin_id = i_admin_id;

  END IF;

END;
$$;


ALTER FUNCTION public.sp_set_notification_center(i_notification_type public.en_notification_type, i_notification_id text, i_notification_sub_type public.en_notification_sub_type, i_notification_status public.en_notification_status_type, i_message text, i_admin_id text) OWNER TO cppoltp;

