--
-- Name: sp_set_policy(bigint, text, public.en_product_feature_id_type, text, text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_policy(i_policy_id bigint, i_name text, i_product_feature_id public.en_product_feature_id_type, i_description text, i_online_policy_body text, i_offline_policy_body text, i_use_offline_policy boolean, i_hash text) RETURNS TABLE(policy_id bigint, policy_name text, product_feature_id public.en_product_feature_id_type, description text, online_policy_body text, offline_policy_body text, use_offline_policy text, hash text)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_policy_type en_policy_type;
  v_policy_name text;
  v_is_updated boolean;

BEGIN

  SELECT p.policy_type
  INTO v_policy_type
  FROM tb_policy p
  WHERE p.policy_id = i_policy_id;

  IF v_policy_type = 'FACTORY' THEN

    RAISE EXCEPTION 'policy (%) cannot be modified.', i_policy_id USING HINT = 'DB-00026';

  ELSIF (SELECT count(*) FROM tb_policy p WHERE p.policy_id <> i_policy_id AND p.name = i_name) > 0 THEN

    SELECT i_name || to_char(now(), '.YYYYMMDD.HH24MISS') INTO v_policy_name;

  ELSE

    SELECT i_name INTO v_policy_name;

  END IF;

  SELECT CASE
           WHEN p.hash = CONCAT(i_hash, i_policy_id::TEXT) THEN false
           ELSE true
         END AS is_updated
  INTO v_is_updated
  FROM tb_policy p
  WHERE p.policy_id = i_policy_id;

  --정책 수정
  UPDATE tb_policy p
  SET name = v_policy_name
     ,description = i_description
     ,online_policy_body = i_online_policy_body
     ,offline_policy_body = i_offline_policy_body
     ,use_offline_policy = i_use_offline_policy
     ,hash = CONCAT(i_hash, i_policy_id::TEXT)
     ,modified_time = now()
     ,is_updated = v_is_updated
  WHERE p.policy_id = i_policy_id;

  RETURN QUERY
  SELECT p.policy_id AS policy_id
        ,p.name AS policy_name
        ,p.product_feature_id AS product_feature_id
        ,p.description AS description
        ,p.online_policy_body AS online_policy_body
        ,COALESCE(p.offline_policy_body, '') AS offline_policy_body
        ,COALESCE(p.use_offline_policy, false)::integer::text AS use_offline_policy
        ,COALESCE(p.hash, '') AS hash
  FROM tb_policy p
  WHERE p.policy_id = i_policy_id;

END;
$$;


ALTER FUNCTION public.sp_set_policy(i_policy_id bigint, i_name text, i_product_feature_id public.en_product_feature_id_type, i_description text, i_online_policy_body text, i_offline_policy_body text, i_use_offline_policy boolean, i_hash text) OWNER TO cppoltp;

