--
-- Name: sp_set_policy_schedule(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_policy_schedule(i_task_id bigint) RETURNS TABLE(policy_id text, target_id text, product_feature_id public.en_product_feature_id_type)
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_agent_change text;
  v_target_id bigint[];
  v_logical_payload text;
  v_internal_payload text;
  v_product_feature_id en_product_feature_id_type;
  v_policy_id bigint;
  v_logical_target json;
  v_type text;
  v_group_id bigint[];
  v_group_id_array bigint[];
  v_keep_agent_policy boolean;
  v_return_target_id bigint[];
  v_is_updated boolean;
  v_is_all boolean;

BEGIN

  SELECT c.value
  INTO v_agent_change
  FROM tb_config c
  WHERE c.config_group = 'GROUPING'
  AND c.key = 'apply_policy_on_group_change';

  SELECT array_agg(tta.target_id)
        ,t.logical_payload
        ,t.internal_payload
  INTO v_target_id
      ,v_logical_payload
      ,v_internal_payload
  FROM tb_task t
  LEFT JOIN tb_task_target tta
  ON t.task_id = tta.task_id
  WHERE t.task_id = i_task_id
  GROUP BY
        t.logical_payload
       ,t.internal_payload;

  SELECT trim(pf_id::text, '"')::en_product_feature_id_type AS pf_id
  INTO v_product_feature_id
  FROM (SELECT v_logical_payload::json -> 'product_feature_id' AS pf_id) AS pf_id;

  SELECT trim(po_id::text, '"')::bigint AS po_id
  INTO v_policy_id
  FROM (SELECT v_internal_payload::json -> 'policy_id' AS po_id) AS po_id;

  SELECT trim(ip.po_id::text, '"')::bigint AS po_id
        ,COALESCE(trim(ip.is_up::text, '"')::boolean, false) AS is_up
        ,COALESCE(trim(ip.is_all::text, '"')::boolean, false) AS is_all
        ,COALESCE(trim(ip.is_keep_agent_policy::text, '"')::boolean, false) AS is_keep_agent_policy
  INTO v_policy_id
      ,v_is_updated
      ,v_is_all
      ,v_keep_agent_policy
  FROM (SELECT v_internal_payload::json -> 'policy_id' AS po_id
              ,v_internal_payload::json -> 'is_updated' AS is_up
              ,v_internal_payload::json -> 'is_all' AS is_all
              ,v_internal_payload::json -> 'is_keep_agent_policy' AS is_keep_agent_policy) AS ip;

  FOR v_logical_target IN

    -- logical_target 조회
    SELECT json_array_elements(logical_target::json) AS logical_target
    FROM tb_job
    WHERE job_id = (SELECT job_id FROM tb_task WHERE task_id = i_task_id)

  LOOP

    -- target_id 추출
    SELECT trim(type::text, '"')
    INTO v_type
    FROM (SELECT v_logical_target::json -> 'type' AS type) AS type;

    -- 그룹 정책 적용
    IF v_type = 'GROUP' THEN

      SELECT array_agg(trim(target::text, '"')::bigint) AS target
      INTO v_group_id
      FROM json_array_elements((SELECT v_logical_target::json -> 'target' AS target)::json) AS target;

      IF v_is_all THEN

        -- 하위그룹 추출
        WITH RECURSIVE group_list (group_id, name, pgroup_id, group_type, is_removed, level, grp_path, cycle)
        AS (
        SELECT g.group_id
              ,g.name
              ,g.pgroup_id
              ,g.group_type
              ,g.is_removed
              ,0
              ,ARRAY[g.group_id]
              ,false
        FROM tb_group g
        WHERE g.group_id IN (SELECT * FROM unnest(v_group_id))
        UNION ALL
        SELECT g.group_id
              ,g.name
              ,g.pgroup_id
              ,g.group_type
              ,g.is_removed
              ,gl.level + 1
              ,gl.grp_path || g.group_id
              ,g.group_id = ANY(gl.grp_path)
        FROM tb_group g
        JOIN group_list gl
          ON g.pgroup_id = gl.group_id
          AND NOT cycle)
        SELECT array_agg(gl.group_id)
        INTO v_group_id_array
        FROM group_list gl
        WHERE gl.is_removed IS NOT true;

      ELSE

        SELECT array_agg(g.group_id)
        INTO v_group_id_array
        FROM tb_group g
        WHERE g.group_id IN (SELECT * FROM unnest(v_group_id))
          AND g.is_removed IS NOT true;

      END IF;

      --  tb_group_policy gp
      UPDATE tb_group_policy gp
      SET policy_id = v_policy_id
         ,modified_time = now()
      WHERE gp.group_id IN (SELECT g.group_id
                            FROM tb_group g
                            WHERE g.group_id IN (SELECT * FROM unnest(v_group_id_array))
                              AND g.is_removed = FALSE)
        AND gp.product_feature_id = v_product_feature_id;

      -- 해당 정책을 사용하지 않는 대상을 추출
      SELECT
        array_agg(np.node_id) INTO v_return_target_id
      FROM
        tb_node_policy np
      INNER JOIN (
        SELECT n.node_id
        FROM tb_node n
        WHERE
          EXISTS (
            SELECT 1
            FROM UNNEST(v_target_id) AS node_list (node_id)
            WHERE node_list.node_id = n.node_id
          )
          AND
          EXISTS (
            SELECT 1
            FROM tb_group g
            WHERE
              EXISTS (
                SELECT 1
                FROM UNNEST(v_group_id_array) AS target_group (group_id)
                WHERE target_group.group_id = g.group_id
              )
              AND g.is_removed IS FALSE
              AND g.group_id = n.group_id
          )
      ) AS target_node ON target_node.node_id = np.node_id
      WHERE
        np.product_feature_id = v_product_feature_id
        AND
          -- v_is_updated : 정책 내용 변경 여부
          CASE WHEN v_is_updated THEN TRUE	-- 모든 노드 포함
          ELSE np.policy_id <> v_policy_id END	 -- 정책 아이디가 다른 노드만 포함
        AND
          -- 설정 > 그룹 설정 > 기본 그룹 설정 내 "그룹 정책 설정"에 따른 처리
          -- "기존 개별 정책 유지"
          CASE WHEN v_agent_change = 'all_but_agent_policy' THEN np.keep_agent_policy IS FALSE -- 개별 정책을 사용하고 있지 않은 노드만 포함
          ELSE TRUE END	-- "그룹 정책 적용" (그룹 내 모든 노드 포함)
      ;

    -- 개별 정책 적용
    ELSE

      -- 해당 정책을 사용하지 않는 대상을 추출
      SELECT array_agg(np.node_id)
      INTO v_return_target_id
      FROM tb_node_policy np
      WHERE
        EXISTS (
            SELECT 1
            FROM UNNEST(v_target_id) AS node_list (node_id)
            WHERE node_list.node_id = np.node_id
        )
        AND np.product_feature_id = v_product_feature_id
        AND
            CASE WHEN v_is_updated THEN TRUE
            ELSE np.policy_id <> v_policy_id END
        ;

    END IF;

  END LOOP;
  
  IF v_return_target_id != NULL THEN
    -- update tb_node_policy
    -- 기존에 가지고 있는 정책이 적용할 정책과 같은 경우(개별 정책 여부만 변경)
    UPDATE tb_node_policy np
    SET keep_agent_policy = v_keep_agent_policy
      , modified_time = NOW()
    WHERE
      EXISTS (
        SELECT 1
        FROM (
          SELECT tb_task_target.target_id AS node_id
        FROM tb_task_target
        WHERE task_id = i_task_id
          AND NOT EXISTS (
            SELECT 1
            FROM UNNEST(v_return_target_id) AS node_list (node_id)
            WHERE tb_task_target.target_id = node_id
          )
        ) AS except_node_list
        WHERE except_node_list.node_id = np.node_id
      )
      AND np.product_feature_id = v_product_feature_id
    ;
  END IF;
  
 -- 기존에 가지고 있는 정책이 적용할 정책과 다른 경우(정책 아이디/개별 정책 여부 둘다 변경)
  UPDATE tb_node_policy np
    SET policy_id = v_policy_id
      ,keep_agent_policy = v_keep_agent_policy
      ,modified_time = now()
    WHERE
      EXISTS (
            SELECT 1
            FROM UNNEST(v_return_target_id) AS node_list (node_id)
            WHERE node_list.node_id = np.node_id
      )
      AND np.product_feature_id = v_product_feature_id;
  
  RETURN QUERY SELECT v_policy_id::text, v_return_target_id::text, v_product_feature_id;

END;
$$;


ALTER FUNCTION public.sp_set_policy_schedule(i_task_id bigint) OWNER TO cppoltp;

--
-- Name: sp_set_policy_status_applying(public.en_product_feature_id_type, bigint[], bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_policy_status_applying(i_product_feature_id public.en_product_feature_id_type, i_node_id bigint[], i_policy_id bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$

BEGIN

  SELECT t.node_id
        ,i_product_feature_id
        ,i_policy_id
        ,'APPLYING'
        ,now()
  FROM unnest(i_node_id) AS t(node_id)
  ON CONFLICT (node_id, product_feature_id)
  DO UPDATE
  SET policy_id = EXCLUDED.policy_id
     ,policy_status = EXCLUDED.policy_status
     ,server_time = EXCLUDED.server_time;

END;
$$;


ALTER FUNCTION public.sp_set_policy_status_applying(i_product_feature_id public.en_product_feature_id_type, i_node_id bigint[], i_policy_id bigint) OWNER TO cppoltp;

--
-- Name: sp_set_policy_update_status(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_policy_update_status(i_policy_id bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN

  UPDATE tb_policy p
  SET is_updated = false
  WHERE p.policy_id = i_policy_id;

END;
$$;


ALTER FUNCTION public.sp_set_policy_update_status(i_policy_id bigint) OWNER TO cppoltp;

--
-- Name: sp_set_product_install_pkg(text, public.en_pkg_type, text, text, public.en_product_id_type, text, text, bigint, public.en_platform_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_product_install_pkg(i_name text, i_pkg_type public.en_pkg_type, i_version text, i_path text, i_product_id public.en_product_id_type, i_description text, i_install_ip text, i_size bigint, i_platform public.en_platform_type) RETURNS TABLE(product_id bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_product_pkg_id bigint := 0;

BEGIN

    --product_pkg_id
    name
    , pkg_type
    , version
    , path
    , pkg_status
    , product_id
    --, language
    , description
    --, mpsetup_hash
    , modified_time
    , delta_update
    , apply_engine
    , apply_patch
    , install_ip
    , size
    --, server_id
    , platform_type
    , is_removed
  ) VALUES (
    i_name
    , i_pkg_type::en_pkg_type
    , i_version
    , i_path
    , 'SUCCESS'
    , i_product_id::en_product_id_type
    --, NULL
    , i_description
    --, i_mpsetup_hash
    , now()
    , TRUE
    , TRUE
    , TRUE
    --, 0
    , i_install_ip
    , i_size
    , i_platform
    , FALSE
  ) RETURNING product_pkg_id INTO v_product_pkg_id
  ;

RETURN QUERY SELECT v_product_pkg_id;

END;
$$;


ALTER FUNCTION public.sp_set_product_install_pkg(i_name text, i_pkg_type public.en_pkg_type, i_version text, i_path text, i_product_id public.en_product_id_type, i_description text, i_install_ip text, i_size bigint, i_platform public.en_platform_type) OWNER TO cppoltp;

--
-- Name: sp_set_product_pkg(text, public.en_pkg_type, text, text, public.en_product_id_type, text, text, boolean, boolean, boolean, text, bigint, public.en_platform_type, text[], public.en_hash_algorithm, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_product_pkg(i_name text, i_pkg_type public.en_pkg_type, i_version text, i_path text, i_product_id public.en_product_id_type, i_description text, i_mpsetup_hash text, i_delta_update_use boolean, i_apply_engine_set boolean, i_apply_patch_set boolean, i_install_ip text, i_size bigint, i_platform_type public.en_platform_type, i_platforms text[], i_hash_algorithm public.en_hash_algorithm, i_detail text) RETURNS TABLE(product_pkg_id bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_product_pkg_id bigint;
BEGIN
  IF(i_pkg_type = 'UPDATE_SES' OR i_pkg_type = 'UPDATE_OES')
   THEN
    -- UPDATE_SES, UPDATE_OES의 경우 같은 type의 파일이 존재 하면 해당 내용을 없데이트 한다.
    IF(SELECT COUNT(tppif.product_pkg_id) FROM tb_product_pkg tppif WHERE pkg_type = i_pkg_type AND is_removed is false) > 0 THEN
      -- pkg server 삭제
        DELETE FROM tb_pkg_server AS dps WHERE dps.product_pkg_id = (SELECT tppif.product_pkg_id FROM tb_product_pkg tppif WHERE pkg_type = i_pkg_type AND tppif.is_removed is false);
      -- update
        UPDATE tb_product_pkg AS utpp
        SET
          path = i_path
          , name = i_name
          , version = i_version
          , pkg_status = 'SUCCESS'
          , mpsetup_hash = i_mpsetup_hash
          , modified_time = now()
          , install_ip = i_install_ip
          , size = i_size
          , hash_algorithm = i_hash_algorithm
      , detail = i_detail
      WHERE pkg_type = i_pkg_type
      RETURNING utpp.product_pkg_id INTO v_product_pkg_id;
      RETURN QUERY SELECT v_product_pkg_id;
    ELSE
          --product_pkg_id : seq
          name
          , pkg_type
          , version
          , path
          , pkg_status
          , product_id
          , description
          , mpsetup_hash
          , modified_time
          , delta_update
          , apply_engine
          , apply_patch
          , install_ip
          , size
          , platform_type
          , hash_algorithm
          , is_removed
      , detail
        )
        VALUES
        (
          i_name                                                    -- 패키지 명
          , i_pkg_type                                              -- 패키지 타입
          , i_version                                               -- 패키지 버전
          , i_path                                                  -- 패키지 경로
          , 'SUCCESS'                                               -- 패키지 상태
          , i_product_id                                            -- 제품 ID
          , i_description                                             -- 설명
          , i_mpsetup_hash                                            -- mpsetup 해시
          , now()                                                       -- 변경 시각
          , i_delta_update_use                                          -- 델타업데이트 사용 여부
          , i_apply_engine_set                                          -- 엔진셋 적용 여부
          , i_apply_patch_set                                           -- 패치셋 적용 여부
          , i_install_ip                                              -- 설치 IP
          , i_size                                                    -- 패키지 사이즈
          , i_platform_type                                           -- OS플랫폼 타입
          , i_hash_algorithm                                          -- hash 알고리즘
          , FALSE                                                      -- 삭제여부
      , i_detail
        )RETURNING pp.product_pkg_id INTO v_product_pkg_id;
        RETURN QUERY SELECT v_product_pkg_id;
    END IF;

  ELSIF(i_pkg_type = 'WIN_AGENT_INSTALL' OR i_pkg_type = 'WIN_AGENT_MASTER' OR i_pkg_type = 'LINUX_AGENT_INSTALL' OR i_pkg_type = 'LINUX_AGENT_MASTER') THEN

        --product_pkg_id : seq
        name
        , pkg_type
        , version
        , path
        , pkg_status
        , product_id
        , description
        , mpsetup_hash
        , modified_time
        , delta_update
        , apply_engine
        , apply_patch
        , install_ip
        , size
        , platform_type
        , hash_algorithm
        , is_removed
    , detail
      )
      VALUES
      (
        i_name                                                    -- 패키지 명
        , i_pkg_type                                              -- 패키지 타입
        , i_version                                               -- 패키지 버전
        , i_path                                                  -- 패키지 경로
        , 'SUCCESS'                                               -- 패키지 상태
        , i_product_id                                            -- 제품 ID
        , i_description                                             -- 설명
        , i_mpsetup_hash                                            -- mpsetup 해시
        , now()                                                       -- 변경 시각
        , i_delta_update_use                                          -- 델타업데이트 사용 여부
        , i_apply_engine_set                                          -- 엔진셋 적용 여부
        , i_apply_patch_set                                           -- 패치셋 적용 여부
        , i_install_ip                                              -- 설치 IP
        , i_size                                                    -- 패키지 사이즈
        , i_platform_type                                           -- OS플랫폼 타입
        , i_hash_algorithm                                          -- hash 알고리즘
        , FALSE                                                      -- 삭제여부
    , i_detail
      )RETURNING pp.product_pkg_id INTO v_product_pkg_id;

      RETURN QUERY SELECT v_product_pkg_id;

  ELSE

    IF(SELECT COUNT(tppif.product_pkg_id) FROM tb_product_pkg tppif WHERE tppif.pkg_type = i_pkg_type AND tppif.product_id = i_product_id AND platform_type = i_platform_type AND tppif.is_removed is false) > 0 THEN

      UPDATE tb_product_pkg
        SET is_removed = TRUE
      WHERE pkg_type = i_pkg_type
        AND product_id = i_product_id;

  END IF;

        --product_pkg_id : seq
        name
        , pkg_type
        , version
        , path
        , pkg_status
        , product_id
        , description
        , mpsetup_hash
        , modified_time
        , delta_update
        , apply_engine
        , apply_patch
        , install_ip
        , size
        , platform_type
        , hash_algorithm
        , is_removed
    , detail
  ) VALUES (
        i_name                                                    -- 패키지 명
        , i_pkg_type                                              -- 패키지 타입
        , i_version                                               -- 패키지 버전
        , i_path                                                  -- 패키지 경로
        , 'SUCCESS'                                               -- 패키지 상태
        , i_product_id                                            -- 제품 ID
        , i_description                                             -- 설명
        , i_mpsetup_hash                                            -- mpsetup 해시
        , now()                                                       -- 변경 시각
        , i_delta_update_use                                          -- 델타업데이트 사용 여부
        , i_apply_engine_set                                          -- 엔진셋 적용 여부
        , i_apply_patch_set                                           -- 패치셋 적용 여부
        , i_install_ip                                              -- 설치 IP
        , i_size                                                    -- 패키지 사이즈
        , i_platform_type                                           -- OS플랫폼 타입
        , i_hash_algorithm                                          -- hash 알고리즘
        , FALSE                                                     -- 삭제여부
    , i_detail
  )RETURNING pp.product_pkg_id INTO v_product_pkg_id;

        product_pkg_id,
        platform_id,
        modified_time
    )
  SELECT v_product_pkg_id, p.platform_id, now()
  FROM UNNEST(array[i_platforms]) AS t(name)
  INNER JOIN tb_platform AS p ON p.name = t.name
  WHERE p.is_supported IS TRUE;

  RETURN QUERY SELECT v_product_pkg_id;

  END IF;

END;
$$;


ALTER FUNCTION public.sp_set_product_pkg(i_name text, i_pkg_type public.en_pkg_type, i_version text, i_path text, i_product_id public.en_product_id_type, i_description text, i_mpsetup_hash text, i_delta_update_use boolean, i_apply_engine_set boolean, i_apply_patch_set boolean, i_install_ip text, i_size bigint, i_platform_type public.en_platform_type, i_platforms text[], i_hash_algorithm public.en_hash_algorithm, i_detail text) OWNER TO cppoltp;

--
-- Name: sp_set_product_pkg_bit(text, public.en_pkg_type, text, text, public.en_product_id_type, text, text, boolean, boolean, boolean, text, bigint, public.en_platform_type, text[], public.en_hash_algorithm); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_product_pkg_bit(i_name text, i_pkg_type public.en_pkg_type, i_version text, i_path text, i_product_id public.en_product_id_type, i_description text, i_mpsetup_hash text, i_delta_update_use boolean, i_apply_engine_set boolean, i_apply_patch_set boolean, i_install_ip text, i_size bigint, i_platform_type public.en_platform_type, i_platforms text[], i_hash_algorithm public.en_hash_algorithm) RETURNS TABLE(product_pkg_id bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_product_pkg_id bigint;
BEGIN
  IF(i_pkg_type = 'UPDATE_SES' OR i_pkg_type = 'UPDATE_OES')
   THEN
    -- UPDATE_SES, UPDATE_OES의 경우 같은 type의 파일이 존재 하면 해당 내용을 없데이트 한다.
    SELECT tppif.product_pkg_id INTO v_product_pkg_id FROM tb_product_pkg tppif WHERE pkg_type = i_pkg_type;
    IF(v_product_pkg_id IS NOT NULL) THEN
      -- pkg server 삭제
        DELETE FROM tb_pkg_server AS dps WHERE dps.product_pkg_id = v_product_pkg_id;
      -- update
        UPDATE tb_product_pkg AS utpp
        SET
          path = i_path
          , name = i_name
          , version = i_version
          , pkg_status = 'SUCCESS'
          , mpsetup_hash = i_mpsetup_hash
          , modified_time = now()
          , install_ip = i_install_ip
          , size = i_size
          , hash_algorithm = i_hash_algorithm
      WHERE pkg_type = i_pkg_type;
      RETURN QUERY SELECT v_product_pkg_id;
    ELSE
          --product_pkg_id : seq
          name
          , pkg_type
          , version
          , path
          , pkg_status
          , product_id
          , description
          , mpsetup_hash
          , modified_time
          , delta_update
          , apply_engine
          , apply_patch
          , install_ip
          , size
          , platform_type
          , hash_algorithm
          , is_removed
        )
        VALUES
        (
          i_name                                                    -- 패키지 명
          , i_pkg_type                                              -- 패키지 타입
          , i_version                                               -- 패키지 버전
          , i_path                                                  -- 패키지 경로
          , 'SUCCESS'                                               -- 패키지 상태
          , i_product_id                                            -- 제품 ID
          , i_description                                             -- 설명
          , i_mpsetup_hash                                            -- mpsetup 해시
          , now()                                                       -- 변경 시각
          , i_delta_update_use                                          -- 델타업데이트 사용 여부
          , i_apply_engine_set                                          -- 엔진셋 적용 여부
          , i_apply_patch_set                                           -- 패치셋 적용 여부
          , i_install_ip                                              -- 설치 IP
          , i_size                                                    -- 패키지 사이즈
          , i_platform_type                                           -- OS플랫폼 타입
          , i_hash_algorithm                                          -- hash 알고리즘
          , FALSE
        )
        RETURNING pp.product_pkg_id INTO v_product_pkg_id;
        RETURN QUERY SELECT v_product_pkg_id;
    END IF;

  ELSIF(i_pkg_type = 'WIN_AGENT_INSTALL' OR i_pkg_type = 'LINUX_AGENT_INSTALL' OR i_pkg_type = 'LINUX_AGENT_MASTER' OR i_pkg_type = 'WIN_AGENT_MASTER') THEN

        --product_pkg_id : seq
        name
        , pkg_type
        , version
        , path
        , pkg_status
        , product_id
        , description
        , mpsetup_hash
        , modified_time
        , delta_update
        , apply_engine
        , apply_patch
        , install_ip
        , size
        , platform_type
        , hash_algorithm
        , is_removed
      )
      VALUES
      (
        i_name                                                    -- 패키지 명
        , i_pkg_type                                              -- 패키지 타입
        , i_version                                               -- 패키지 버전
        , i_path                                                  -- 패키지 경로
        , 'SUCCESS'                                               -- 패키지 상태
        , i_product_id                                            -- 제품 ID
        , i_description                                             -- 설명
        , i_mpsetup_hash                                            -- mpsetup 해시
        , now()                                                       -- 변경 시각
        , i_delta_update_use                                          -- 델타업데이트 사용 여부
        , i_apply_engine_set                                          -- 엔진셋 적용 여부
        , i_apply_patch_set                                           -- 패치셋 적용 여부
        , i_install_ip                                              -- 설치 IP
        , i_size                                                    -- 패키지 사이즈
        , i_platform_type                                           -- OS플랫폼 타입
        , i_hash_algorithm                                          -- hash 알고리즘
        , FALSE                                                     -- 삭제여부
      )
      RETURNING pp.product_pkg_id INTO v_product_pkg_id;
      RETURN QUERY SELECT v_product_pkg_id;

  ELSE

  SELECT DISTINCT(tppp.product_pkg_id) INTO v_product_pkg_id
    FROM tb_product_pkg tppp
    JOIN tb_pkg_platform tpp2 ON tppp.product_pkg_id = tpp2.product_pkg_id
  JOIN tb_platform tp2 ON tpp2.platform_id = tp2.platform_id
  WHERE tp2.is_supported IS TRUE AND pkg_type = i_pkg_type AND tp2.name in (SELECT unnest(i_platforms))
    AND tppp.is_removed is false;

    IF(v_product_pkg_id IS NOT NULL) THEN

      DELETE FROM tb_pkg_server AS tps WHERE tps.product_pkg_id = v_product_pkg_id;
      DELETE FROM tb_pkg_platform AS tpp WHERE tpp.product_pkg_id = v_product_pkg_id;

      UPDATE tb_product_pkg AS utpp
        SET
          name = i_name
          , pkg_type = i_pkg_type
          , version = i_version
          , path = i_path
          , description = i_description
          , mpsetup_hash = i_mpsetup_hash
          , modified_time = now()
          , delta_update = i_delta_update_use
          , apply_engine = i_apply_engine_set
          , apply_patch = i_apply_patch_set
          , install_ip = i_install_ip
          , size = i_size
          , platform_type = i_platform_type
          , hash_algorithm = i_hash_algorithm
      WHERE pkg_type = i_pkg_type
        AND product_id = i_product_id;
      RETURN QUERY SELECT v_product_pkg_id;

          product_pkg_id,
          platform_id,
          modified_time
      )
      SELECT v_product_pkg_id, p.platform_id, now()
      FROM UNNEST(array[i_platforms]) AS t(name)
      INNER JOIN tb_platform AS p ON p.name = t.name
      WHERE p.is_supported IS TRUE;

      RETURN QUERY SELECT v_product_pkg_id;

    ELSE

        --product_pkg_id : seq
        name
        , pkg_type
        , version
        , path
        , pkg_status
        , product_id
        , description
        , mpsetup_hash
        , modified_time
        , delta_update
        , apply_engine
        , apply_patch
        , install_ip
        , size
        , platform_type
        , hash_algorithm
        , is_removed
      )
      VALUES
      (
        i_name                                                    -- 패키지 명
        , i_pkg_type                                              -- 패키지 타입
        , i_version                                               -- 패키지 버전
        , i_path                                                  -- 패키지 경로
        , 'SUCCESS'                                               -- 패키지 상태
        , i_product_id                                            -- 제품 ID
        , i_description                                             -- 설명
        , i_mpsetup_hash                                            -- mpsetup 해시
        , now()                                                       -- 변경 시각
        , i_delta_update_use                                          -- 델타업데이트 사용 여부
        , i_apply_engine_set                                          -- 엔진셋 적용 여부
        , i_apply_patch_set                                           -- 패치셋 적용 여부
        , i_install_ip                                              -- 설치 IP
        , i_size                                                    -- 패키지 사이즈
        , i_platform_type                                           -- OS플랫폼 타입
        , i_hash_algorithm                                          -- hash 알고리즘
        , FALSE                                                     -- 삭제여부
      )
      RETURNING pp.product_pkg_id INTO v_product_pkg_id;
        product_pkg_id,
        platform_id,
        modified_time
      )
      SELECT v_product_pkg_id, p.platform_id, now()
      FROM UNNEST(array[i_platforms]) AS t(name)
      INNER JOIN tb_platform AS p ON p.name = t.name
      WHERE p.is_supported IS TRUE;

      RETURN QUERY SELECT v_product_pkg_id;
    END IF;

  END IF;

END;
$$;


ALTER FUNCTION public.sp_set_product_pkg_bit(i_name text, i_pkg_type public.en_pkg_type, i_version text, i_path text, i_product_id public.en_product_id_type, i_description text, i_mpsetup_hash text, i_delta_update_use boolean, i_apply_engine_set boolean, i_apply_patch_set boolean, i_install_ip text, i_size bigint, i_platform_type public.en_platform_type, i_platforms text[], i_hash_algorithm public.en_hash_algorithm) OWNER TO cppoltp;

--
-- Name: sp_set_query_report(text, bigint, text, text, text[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_query_report(i_login_admin_id text, i_query_report_id bigint, i_name text, i_description text, i_query_report_item text[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_profile_type              en_privilege_profile_type;

  row_query_report_item       text[];
  idx                         integer := 0;

  con_column_length           CONSTANT integer := 6;
  con_report_item_type        CONSTANT integer := 1;
  con_report_graph_type       CONSTANT integer := 2;
  con_query                   CONSTANT integer := 3;
  con_db_type                 CONSTANT integer := 4;
  con_graph_title             CONSTANT integer := 5;
  con_graph_color             CONSTANT integer := 6;
BEGIN

  -- login_admin_id 의 권한 가져오기
  v_profile_type := sp_get_admin_privilege_type( i_login_admin_id );

  -- 권한 체크
  IF v_profile_type IS NULL OR v_profile_type <> 'ROOT_ADMIN' THEN
    IF (SELECT EXISTS (SELECT 1 FROM tb_query_report AS q WHERE q.query_report_id = i_query_report_id AND q.admin_id <> i_login_admin_id)) = true THEN
      RAISE EXCEPTION 'You do not have permission.(%)', i_query_report_id USING HINT = 'DB-00022';
    END IF;
  END IF;


  --컬럼 길이 체크하기
  IF ARRAY_LENGTH(i_query_report_item, 2) <> con_column_length THEN
    RAISE EXCEPTION 'Different column array lengths.' USING HINT = 'DB-00020';
  END IF;

  -- 명칭 중복 체크
  IF (SELECT EXISTS (SELECT 1 FROM tb_query_report AS q WHERE q.admin_id = (SELECT qr.admin_id FROM tb_query_report AS qr WHERE qr.query_report_id = i_query_report_id) AND q.query_report_id <> i_query_report_id AND q.name = i_name)) = true THEN
    RAISE EXCEPTION 'The name is already registered.(%)', i_name USING HINT = 'DB-00037';
  END IF;

  -- tb_query_report 수정
  UPDATE tb_query_report
    SET name = i_name
      , description = i_description
  WHERE query_report_id = i_query_report_id;

  -- tb_query_report_item 삭제
  DELETE FROM tb_query_report_item WHERE query_report_id = i_query_report_id;

  -- tb_query_report_item 등록
  FOREACH row_query_report_item SLICE 1 IN ARRAY i_query_report_item LOOP
    idx := idx + 1;

      query_report_id, item_order
      , report_item_type, report_graph_type, query
      , db_type, graph_title, graph_color
    ) VALUES(
      i_query_report_id, idx
      , row_query_report_item[con_report_item_type]::en_report_item_type, row_query_report_item[con_report_graph_type]::en_report_graph_type, row_query_report_item[con_query]
      , row_query_report_item[con_db_type]::en_db_type, row_query_report_item[con_graph_title], row_query_report_item[con_graph_color]
    );

  END LOOP;

END;
$$;


