--
-- Name: sp_set_report_schedule(text, bigint, public.en_report_type, public.en_base_report_id_type, bigint, public.en_schedule_period_type, timestamp without time zone, timestamp without time zone, text[], text, boolean, text, bigint, text, text, public.en_schedule_type, text, boolean, boolean); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_report_schedule(i_login_admin_id text, i_report_schedule_id bigint, i_report_type public.en_report_type, i_base_report_id public.en_base_report_id_type, i_query_report_id bigint, i_period_type public.en_schedule_period_type, i_period_start timestamp without time zone, i_period_end timestamp without time zone, i_params text[], i_schedule text, i_mail_alarm boolean, i_target text, i_correlation_rule_id bigint, i_name text, i_description text, i_schedule_type public.en_schedule_type, i_user_mail text, i_is_admin_mail boolean, i_is_user_mail boolean) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_profile_type              en_privilege_profile_type;
BEGIN

  -- login_admin_id 의 권한 가져오기
  v_profile_type := sp_get_admin_privilege_type( i_login_admin_id );

  -- 권한 체크
  IF v_profile_type IS NULL OR v_profile_type <> 'ROOT_ADMIN' THEN
    IF (SELECT EXISTS (SELECT 1 FROM tb_report_schedule AS r WHERE r.report_schedule_id = i_report_schedule_id AND r.admin_id <> i_login_admin_id)) = true THEN
      RAISE EXCEPTION 'You do not have permission.(%)', i_report_schedule_id USING HINT = 'DB-00022';
    END IF;
  END IF;

  IF ( i_correlation_rule_id IS NULL OR EXISTS (SELECT 1 FROM tb_correlation_rule cr WHERE cr.correlation_rule_id = i_correlation_rule_id AND cr.correlation_type = 'GENERAL')) THEN
    UPDATE tb_report_schedule
      SET report_type = i_report_type
        , base_report_id = i_base_report_id
        , query_report_id = i_query_report_id
        , admin_id = i_login_admin_id
        , period_type = COALESCE(i_period_type, COALESCE((SELECT default_period_type FROM tb_base_report WHERE base_report_id = i_base_report_id),'LATEST'))
        , period_start = i_period_start
        , period_end = i_period_end
        , params = i_params
        , schedule = i_schedule
        , mail_alarm = i_mail_alarm
        , modified_time = now()
        , target = i_target
        , correlation_rule_id = i_correlation_rule_id
        , name = i_name
        , description = i_description
        , schedule_type = i_schedule_type
        , user_mail = i_user_mail
        , is_admin_mail = i_is_admin_mail
        , is_user_mail = i_is_user_mail
    WHERE report_schedule_id = i_report_schedule_id
      AND admin_id = CASE WHEN v_profile_type = 'ROOT_ADMIN' THEN admin_id ELSE i_login_admin_id END
      AND report_type <> 'CORRELATION'
      AND is_removed = FALSE;
  ELSE
    RAISE EXCEPTION 'Correlation type is not general.' USING HINT = 'DB-00061';
  END IF;

END;
$$;


