--
-- Name: sp_set_schedule_enabled_migration(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_schedule_enabled_migration() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

    WITH set_file_sync AS (
        UPDATE tb_schedule
        SET enabled = (
                         SELECT CASE WHEN count(tsv.server_id) > 1 THEN true
                                     ELSE false END AS schedule_code
                         FROM tb_server tsv
                             INNER JOIN tb_service tsc
                                 ON tsc.server_id = tsv.server_id
                         WHERE tsc.service_type = 'FILESERVER-UPLOAD'     
                           AND enabled IS true
                      )
        WHERE schedule_code = 'FILE_SYNC'::en_schedule_code
    )
    UPDATE tb_schedule
    SET enabled = false
    WHERE schedule_id IN (SELECT schedule_id
                          FROM tb_schedule sc
                          WHERE sc.schedule_code IN ( 
                                                        SELECT CASE c.config_group WHEN 'UPDATE' THEN 'EPP_UPDATE'::en_schedule_code
                                                                                   WHEN 'UPDATE_HIPS_SIGNATURE' THEN 'UPDATE_HIPS_SIGNATURE'::en_schedule_code
                                                                                   WHEN 'UPDATE_COUNTRY' THEN 'UPDATE_COUNTRY'::en_schedule_code
                                                                                   WHEN 'UPDATE_IM' THEN 'UPDATE_IM'::en_schedule_code
                                                                                   WHEN 'UPDATE_SCM' THEN 'UPDATE_SCM'::en_schedule_code
                                                                                   END AS schedule_code    
                                                        FROM (
                                                                SELECT config_group
                                                                FROM tb_config AS c
                                                                WHERE config_group = 'UPDATE'
                                                                    AND KEY = 'update_server_type'
                                                                    AND value = 'ems'
                                                                UNION ALL 
                                                                SELECT config_group AS config_group
                                                                FROM tb_config AS c
                                                                WHERE config_group IN ('UPDATE_HIPS_SIGNATURE','UPDATE_COUNTRY','UPDATE_IM','UPDATE_SCM')
                                                                    AND KEY = 'ahnlab'
                                                                    AND c.value::json->>'update_server_type' = 'ems'
                                                              ) c
                                                     )
                         );

END;
$$;


