--
-- Name: sp_set_schedule_trigger(bigint, public.en_execute_status, integer); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_schedule_trigger(i_trigger_id bigint, i_execute_status public.en_execute_status, i_delete_day integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  UPDATE tb_schedule_trigger
  SET
    execute_status = i_execute_status
    , modified_time = now()
  WHERE trigger_id = i_trigger_id;


  DELETE FROM tb_schedule_trigger
  WHERE modified_time < current_date - i_delete_day
    AND execute_status = 'SUCCESS';
END;
$$;


