--
-- Name: sp_set_scm_agent_policy(bigint, text, text, text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_scm_agent_policy(i_policy_id bigint, i_policy_name text, i_description text, i_online_policy_body text, i_offline_policy_body text, i_use_offline_policy boolean, i_hash text) RETURNS TABLE(policy_id bigint, policy_name text, product_feature_id public.en_product_feature_id_type, description text, online_policy_body text, offline_policy_body text, use_offline_policy text, hash text)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_product_feature_id en_product_feature_id_type;

BEGIN

SELECT p.product_feature_id
INTO v_product_feature_id
FROM tb_policy p
WHERE p.policy_id = i_policy_id;

IF v_product_feature_id IS NULL THEN

  RAISE EXCEPTION 'policy_id (%) does not exist.', i_policy_id USING HINT = 'DB-00031';

ELSIF v_product_feature_id <> 'SCM_AGENT' THEN

  RAISE EXCEPTION 'policy_id (%) is not SCM_AGENT policy.', i_policy_id USING HINT = 'DB-00030';

END IF;

  RETURN QUERY
  SELECT p.policy_id AS policy_id
        ,p.policy_name AS policy_name
        ,p.product_feature_id AS product_feature_id
        ,p.description AS description
        ,p.online_policy_body AS online_policy_body
        ,p.offline_policy_body AS offline_policy_body
        ,p.use_offline_policy AS use_offline_policy
        ,p.hash AS hash
  FROM sp_set_policy(i_policy_id, i_policy_name, 'SCM_AGENT', i_description, i_online_policy_body,
                     i_offline_policy_body, i_use_offline_policy, i_hash) p;

END;
$$;


