--
-- Name: sp_set_server_hardware_spec(text, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_server_hardware_spec(i_cpu text, i_server_ip text, i_instance_type text) RETURNS void
    LANGUAGE plpgsql
    AS $$
  DECLARE
    v_server_id		BIGINT;
    v_server_model  TEXT;
  BEGIN
    SELECT server_id INTO v_server_id FROM tb_server WHERE ip=i_server_ip;
    IF (SELECT count(*) FROM tb_service WHERE server_id = v_server_id AND service_type = 'DB-EPPOLTP' AND enabled = true) THEN
      v_server_model = 'CPP_ALL';
		ELSE
      v_server_model = 'CPP_PART';
		END IF;
		UPDATE
      tb_server
		SET
      model_no=v_server_model, cpu_desc=i_cpu, instance_type=i_instance_type
		WHERE
      server_id = v_server_id;

END;
$$;


