--
-- Name: sp_set_server_ip(text[], text[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_server_ip(i_old_ip text[], i_now_ip text[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

	UPDATE tb_server
	SET
		ip = t.now_ip
		, modified_time = now()
	FROM (
		SELECT
			t.old_ip, t.now_ip
		FROM UNNEST(i_old_ip, i_now_ip) AS t(old_ip, now_ip)
	) AS t
	WHERE tb_server.ip = t.old_ip
	;
END;
$$;


