--
-- Name: sp_set_server_service(text[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_server_service(i_server_service_rows text[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_service_type              en_service_type[];
  v_count_type                en_service_count_type[];
  v_service_count             integer[];

  v_server_service_data       text[];
  v_server_list               bigint[];
  v_server_id_list            bigint[] := ARRAY[]::bigint[];
  v_service_type_list         en_service_type[] := ARRAY[]::en_service_type[];

  con_column_length           CONSTANT integer := 2;
  con_server_id               CONSTANT integer := 1;
  con_service_type            CONSTANT integer := 2;

  con_service_count_type_ALL  CONSTANT en_service_count_type := 'ALL';
  con_service_count_type_ONE  CONSTANT en_service_count_type := 'ONE';
  con_service_count_type_ZERO_ONE  CONSTANT en_service_count_type := 'ZERO_OR_ONE';
  con_service_count_type_MORE CONSTANT en_service_count_type := 'ONE_OR_MORE';
  con_service_count_type_ZERO CONSTANT en_service_count_type := 'ZERO_OR_MORE';

  v_count                     integer;
  v_static_server_id_list     bigint[];
  v_static_service_type_list  en_service_type[];
BEGIN

  -- 현재 설정 작업진행중이면 저장불가
  IF (SELECT EXISTS (SELECT 1 FROM tb_server AS s WHERE s.role_status = 'APPLYING')) = true THEN
    RAISE EXCEPTION 'Service Setup in progress for the server.' USING HINT = 'DB-00044';
  END IF;

  -- 컬럼 길이 체크하기
  IF ARRAY_LENGTH(i_server_service_rows, 2) <> con_column_length THEN
    RAISE EXCEPTION 'Different column array lengths.' USING HINT = 'DB-00018';
  END IF;

  -- 서비스 정보 가져오기
  SELECT ARRAY_AGG(sp.service_type), ARRAY_AGG(sp.count_type), ARRAY_AGG(0) INTO v_service_type, v_count_type, v_service_count
  FROM tb_service_port AS sp
  WHERE sp.param_enabled IS TRUE;


  -- 서비스 정보 설정 갯수 더하기
  FOREACH v_server_service_data SLICE 1 IN ARRAY i_server_service_rows LOOP
    SELECT ARRAY_CAT(v_server_id_list, ARRAY[v_server_service_data[con_server_id]::bigint]) INTO v_server_id_list;
    SELECT ARRAY_CAT(v_service_type_list, ARRAY[v_server_service_data[con_service_type]::en_service_type]) INTO v_service_type_list;

    FOR v_idx IN 1 .. ARRAY_LENGTH(v_service_type, 1) LOOP
      IF v_server_service_data[con_service_type]::en_service_type = v_service_type[v_idx] THEN
        v_service_count[v_idx] := v_service_count[v_idx] + 1;
        EXIT;
      END IF;
    END LOOP;
  END LOOP;

  -- 서비스 세팅 갯수 체크해서 에러 발생시키기
  FOR v_idx IN 1 .. ARRAY_LENGTH(v_service_type, 1) LOOP

    IF v_count_type[v_idx] = con_service_count_type_ONE THEN
      IF v_service_count[v_idx] = 0 OR v_service_count[v_idx] > 1 THEN
        RAISE EXCEPTION 'The "%" service can set only one server.', v_service_type[v_idx] USING HINT = 'DB-00028';
      END IF;
    ELSIF v_count_type[v_idx] = con_service_count_type_MORE THEN
      IF v_service_count[v_idx] = 0 THEN
        RAISE EXCEPTION 'The "%" service must be set to one or more servers.', v_service_type[v_idx] USING HINT = 'DB-00029';
      END IF;
    ELSIF v_count_type[v_idx] = con_service_count_type_ZERO_ONE THEN
      IF v_service_count[v_idx] > 1 THEN
        RAISE EXCEPTION 'The "%" service must be set to zero or one servers.', v_service_type[v_idx] USING HINT = 'DB-00048';
      END IF;
    END IF;
  END LOOP;

  -- 기존에 tb_service_port.static = true 로 되어 있는 것 중에 tb_service 에 셋팅되어 있는 것은 반드시 파라미터로 넘어와야 한다.
  SELECT COUNT(1) INTO v_count
  FROM tb_service AS s
  WHERE s.enabled IS TRUE AND s.static IS TRUE
    AND NOT EXISTS (
      SELECT 1 FROM UNNEST(v_server_id_list, v_service_type_list) t(server_id, service_type) WHERE t.server_id = s.server_id AND t.service_type = s.service_type
    )
    AND NOT EXISTS (
      SELECT 1 FROM tb_service_port AS sp WHERE sp.service_type = s.service_type AND sp.param_enabled IS NOT TRUE
    );
  IF v_count > 0 THEN
    RAISE EXCEPTION 'Unchecked services must be selected.' USING HINT = 'DB-00040';
  END IF;

  -- 파라미터로 입력받은 서버 중복 제거
  SELECT ARRAY_AGG(s.server_id) INTO v_server_list
  FROM (
    SELECT DISTINCT t.server_id FROM UNNEST(v_server_id_list) t(server_id) ORDER BY 1
  ) AS s;

  -- tb_service 에 등록된 서비스 중에 static = true 인 것은 유지하기
  SELECT ARRAY_AGG(s.server_id), ARRAY_AGG(s.service_type) INTO v_static_server_id_list, v_static_service_type_list
  FROM tb_service AS s
  WHERE s.static IS TRUE;

  -- tb_server 기준으로 서비스 추가 및 변경 하기 tb_service.enabled = false
    SELECT s.server_id, t.service_type, FALSE, FALSE, 'NORMAL', now()
    FROM tb_server AS s
    CROSS JOIN UNNEST(enum_range(null::en_service_type)) AS t(service_type)
  ON CONFLICT(server_id, service_type) DO UPDATE SET enabled = EXCLUDED.enabled, static = EXCLUDED.static, service_status = EXCLUDED.service_status, modified_time = now();

  -- 파라미터로 받는 서비스 enabled = true 로 변경하기
  UPDATE tb_service
    SET enabled = true
  WHERE EXISTS (
    SELECT 1 FROM UNNEST(v_server_id_list, v_service_type_list) t(server_id, service_type) WHERE t.server_id = tb_service.server_id AND t.service_type = tb_service.service_type
  );

  -- tb_service 에 등록되었던 서비스 중에 static = true인 것 셋팅하기
  UPDATE tb_service
    SET
     -- enabled = TRUE,
      static = true
  WHERE EXISTS (
    SELECT 1 FROM UNNEST(v_static_server_id_list, v_static_service_type_list) t(server_id, service_type)
    WHERE t.server_id = tb_service.server_id AND t.service_type = tb_service.service_type
  );

  -- 파라미터로 받은것 중에서 static = true 셋팅하기(service_id 가 가장 작은것)
  UPDATE tb_service
    SET static = true
  WHERE server_id = (SELECT MIN(s.server_id) FROM tb_service AS s WHERE s.service_type = tb_service.service_type AND s.enabled = true)
    AND EXISTS (
      SELECT 1 FROM tb_service_port AS sp WHERE sp.service_type = tb_service.service_type AND ( sp.always_static IS TRUE OR sp.init_static IS TRUE ) AND sp.dep_service_type IS NULL
    );

  -- 파라미터로 받지 않은것 중에서 static = true 셋팅하기(service_id 가 가장 작은것)
  UPDATE tb_service
    SET
    --enabled = true,
    static = true
  WHERE server_id = v_server_list[1]
    AND EXISTS (
      SELECT 1 FROM tb_service_port AS sp WHERE sp.service_type = tb_service.service_type AND ( sp.always_static IS TRUE OR sp.init_static IS TRUE ) AND sp.dep_service_type IS NULL AND tb_service.enabled = false
    );

  -- tb_service_port의 count_type='ALL'인 경우 전체서버의 서비스의 enabled = true 로 변경하기
  UPDATE tb_service
    SET enabled = true
  WHERE EXISTS (
    SELECT 1 FROM tb_service_port AS sp WHERE sp.service_type = tb_service.service_type AND sp.count_type = 'ALL'
  );

  -- dependency service_type 같이 enabled 맞춰주기
  UPDATE tb_service
    SET enabled = true
  FROM (
    SELECT sp.service_type, s.server_id
    FROM tb_service_port AS sp
    JOIN tb_service AS s ON s.service_type = sp.dep_service_type AND s.enabled = true
  ) AS s
  WHERE tb_service.server_id = s.server_id
    AND tb_service.service_type = s.service_type;

  -- always_static = true 셋팅하기
  UPDATE tb_service
    SET static = true
  WHERE enabled = true
    AND static = false
    AND EXISTS (
      SELECT 1 FROM tb_service_port AS sp WHERE sp.service_type = tb_service.service_type AND sp.always_static IS TRUE
    );

  -- NOSQL-CONFIGSVR1 ~~ 3 셋팅하기
  IF ARRAY_LENGTH(v_server_list, 1) < 3 THEN
    UPDATE tb_service
      SET enabled = true
    WHERE server_id = v_server_list[1]
      AND service_type IN ('NOSQL-CONFIGSVR1', 'NOSQL-CONFIGSVR2', 'NOSQL-CONFIGSVR3');
  ELSE
    FOR v_idx IN 1 .. 3 LOOP
      UPDATE tb_service
        SET enabled = true
      WHERE server_id = v_server_list[v_idx]
        AND service_type = ('NOSQL-CONFIGSVR' || v_idx)::en_service_type;
    END LOOP;
  END IF;

END;
$$;


ALTER FUNCTION public.sp_set_server_service(i_server_service_rows text[]) OWNER TO cppoltp;

--
-- Name: sp_set_server_version(bigint, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_server_version(i_server_id bigint, i_col text, i_patch_version text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
  IF i_patch_version = 'NULL' THEN
    i_patch_version = NULL;
  END IF;

  IF i_col = 'current_version' then
    UPDATE tb_server SET current_version = i_patch_version WHERE server_id = i_server_id;
  ELSEIF i_col = 'patch_version' then
    UPDATE tb_server SET patch_version = NULL;
    UPDATE tb_server SET patch_version = i_patch_version WHERE server_id = i_server_id;
  ELSEIF i_col = 'all_version' THEN
    UPDATE tb_server SET current_version = i_patch_version, patch_version = i_patch_version WHERE server_id = i_server_id;
  END IF;
END;
$$;


ALTER FUNCTION public.sp_set_server_version(i_server_id bigint, i_col text, i_patch_version text) OWNER TO cppoltp;

--
-- Name: sp_set_service_port(public.en_service_type[], integer[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_service_port(i_service_type public.en_service_type[], i_port integer[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count_type                en_service_count_type := 'ONE';
BEGIN

  -- 현재 설정 작업진행중이면 저장불가
  IF (SELECT EXISTS (SELECT 1 FROM tb_server AS s WHERE s.role_status = 'APPLYING')) = true THEN
    RAISE EXCEPTION 'Service Setup in progress for the server.' USING HINT = 'DB-00044';
  END IF;

  IF ARRAY_LENGTH(i_service_type, 1) <> ARRAY_LENGTH(i_port, 1) THEN
    RAISE EXCEPTION 'The length of the array is unequal.' USING HINT = 'DB-00020';
  END IF;

    SELECT t.service_type, t.port, v_count_type FROM UNNEST(i_service_type, i_port) AS t(service_type, port) WHERE t.service_type NOT IN ('TOMCAT-AGENT','ZOOKEEPER-SERVER1','ZOOKEEPER-SERVER2','ZOOKEEPER-SERVICE','KAFKA')
  ON CONFLICT(service_type) DO UPDATE SET port = EXCLUDED.port;

END;
$$;


ALTER FUNCTION public.sp_set_service_port(i_service_type public.en_service_type[], i_port integer[]) OWNER TO cppoltp;

--
-- Name: sp_set_system_eula(public.en_product_group_type, boolean, boolean); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_system_eula(i_product_group public.en_product_group_type, i_eula_agree boolean, i_is_beginning boolean) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_keys                      text[];
  v_values                    text[];
BEGIN

  v_keys := ARRAY[ 'eula_agree_' || i_product_group ];
  v_values := ARRAY[ i_eula_agree::text ];

  PERFORM sp_set_configs( 'EULA', v_keys, v_values );

  -- 환경값 셋팅
  IF i_is_beginning = true THEN
    ON CONFLICT(config_group, key) DO UPDATE SET value = EXCLUDED.value, modified_time = EXCLUDED.modified_time;
  END IF;

END;
$$;


