CREATE FUNCTION public.sp_set_system_info(i_company_name text, i_user_name text, i_domain_name text, i_response_retry_interval integer, i_intergrity_scan_schedule text) RETURNS TABLE(schedule_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE

BEGIN

  RETURN QUERY
    SELECT * FROM sp_set_system_info(i_company_name, i_user_name, i_domain_name, false, NULL, NULL, NULL, NULL, i_response_retry_interval, i_intergrity_scan_schedule);

END;
$$;


ALTER FUNCTION public.sp_set_system_info(i_company_name text, i_user_name text, i_domain_name text, i_response_retry_interval integer, i_intergrity_scan_schedule text) OWNER TO cppoltp;

--
-- Name: sp_set_system_info(text, text, text, boolean, text, text, text, text, integer, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_system_info(i_company_name text, i_user_name text, i_domain_name text, i_time_server_use boolean, i_time_server_ip text, i_dns_server_ip_01 text, i_dns_server_ip_02 text, i_dns_server_ip_03 text, i_response_retry_interval integer, i_intergrity_scan_schedule text) RETURNS TABLE(schedule_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_keys                      text[];
  v_values                    text[];

  v_schedule_id               text := null;
BEGIN

  IF (SELECT ARRAY_LENGTH(STRING_TO_ARRAY(i_domain_name, ' '), 1)) > 1 THEN
    RAISE EXCEPTION 'Domain name cannot include space.' USING HINT = 'DB-00046';
  END IF;

  v_keys := ARRAY[ 'company_name', 'user_name', 'domain_name', 'time_server_use', 'time_server_ip'
      , 'dns_server_ip_01', 'dns_server_ip_02', 'dns_server_ip_03', 'response_retry_interval', 'intergrity_scan_schedule' ];
  v_values := ARRAY[ TRIM(i_company_name), TRIM(i_user_name), TRIM(i_domain_name), i_time_server_use::text, TRIM(i_time_server_ip)
      , TRIM(i_dns_server_ip_01), TRIM(i_dns_server_ip_02), TRIM(i_dns_server_ip_03), i_response_retry_interval::text, i_intergrity_scan_schedule ];

  PERFORM sp_set_configs( 'SYS_INFO', v_keys, v_values );


  -- 도메인명으로 그룹의 group_type = 'TOP' 으로 변경
  IF (EXISTS (SELECT 1 FROM tb_group AS g WHERE g.group_type = 'TOP')) THEN
    UPDATE tb_group
      SET name = i_domain_name
    WHERE group_type = 'TOP';
  ELSE
  END IF;


  -- 서버 무결성 체크 스케줄
  v_schedule_id := sp_add_unity_schedule( 'EMS', 'SERVER_INTEGRITY_SCAN', 1, i_intergrity_scan_schedule, true, '/api/console/config/system/execute', null );


  RETURN QUERY
    SELECT v_schedule_id;

END;
$$;


ALTER FUNCTION public.sp_set_system_info(i_company_name text, i_user_name text, i_domain_name text, i_time_server_use boolean, i_time_server_ip text, i_dns_server_ip_01 text, i_dns_server_ip_02 text, i_dns_server_ip_03 text, i_response_retry_interval integer, i_intergrity_scan_schedule text) OWNER TO cppoltp;

--
-- Name: sp_set_table_clean_config(text, integer, public.en_clean_table_type[], boolean[], public.en_product_group_type[], bigint[], text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_table_clean_config(i_db_clean_type text, i_db_clean_condition integer, i_clean_table public.en_clean_table_type[], i_clean boolean[], i_product_group public.en_product_group_type[], i_storage_limit_date bigint[], i_opensearch_date_threshold text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_keys            text[];
  v_values          text[];
BEGIN

  IF ARRAY_LENGTH(i_clean_table, 1) <> ARRAY_LENGTH(i_clean, 1)
    AND ARRAY_LENGTH(i_clean, 1) <> ARRAY_LENGTH(i_product_group, 1)
    AND ARRAY_LENGTH(i_product_group, 1) <> ARRAY_LENGTH(i_storage_limit_date, 1)
  THEN
    RAISE EXCEPTION 'The length of the array is unequal.' USING HINT = 'DB-00020';
  END IF;

  v_keys := ARRAY[ 'db_clean_type' ];
  v_values := ARRAY[ i_db_clean_type ];

  PERFORM sp_set_configs( 'DB_CLEAN', v_keys, v_values );

  v_keys := ARRAY[ 'db_clean_condition' ];
  v_values := ARRAY[ i_db_clean_condition::text ];

  PERFORM sp_set_configs( 'DB_CLEAN', v_keys, v_values );

  v_keys := ARRAY[ 'opensearch_date_threshold' ];
  v_values := ARRAY[ i_opensearch_date_threshold::text ];

  PERFORM sp_set_configs( 'DB_CLEAN', v_keys, v_values );

  UPDATE tb_table_clean_config SET clean = FALSE;

    SELECT t.clean_table, t.clean, t.product_group, storage_limit_date FROM UNNEST(i_clean_table, i_clean, i_product_group, i_storage_limit_date) AS t(clean_table, clean, product_group, storage_limit_date)
  ON CONFLICT(clean_table) DO UPDATE SET (clean, storage_limit_date) = (EXCLUDED.clean , EXCLUDED.storage_limit_date);

END;
$$;


ALTER FUNCTION public.sp_set_table_clean_config(i_db_clean_type text, i_db_clean_condition integer, i_clean_table public.en_clean_table_type[], i_clean boolean[], i_product_group public.en_product_group_type[], i_storage_limit_date bigint[], i_opensearch_date_threshold text) OWNER TO cppoltp;

