--

CREATE FUNCTION public.sp_set_task_favorite_list(i_admin_id text, i_task_menu_layout text[]) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE
  v_cnt int := 0;

BEGIN

  UPDATE tb_admin
     SET task_menu_layout = i_task_menu_layout
   WHERE admin_id = i_admin_id
  ;

  GET DIAGNOSTICS v_cnt = ROW_COUNT;
  return v_cnt;

END;
$$;


