--
-- Name: sp_set_task_schedule(bigint, public.en_task_type, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_task_schedule(i_task_id bigint, i_task_type public.en_task_type, i_logical_target text, i_target_filter text, i_schedule_detail text, i_logical_payload text, i_internal_payload text, server_context text, console_context text, i_admin_id text) RETURNS TABLE(job_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_tb_job_id bigint;
  v_tb_admin_id text;
  v_tb_is_schedule boolean;
  v_tb_profile_type text;
  v_lu_update_task_id bigint;
  v_lu_update_job_id bigint;
  v_policy_id bigint;
  v_internal_payload TEXT := i_internal_payload;
BEGIN

  IF i_task_type = 'APPLY_POLICY' AND NOT((COALESCE(v_internal_payload, '')='') OR (COALESCE((v_internal_payload::json ->> 'policy_id'), '')='')) THEN

    v_policy_id := (v_internal_payload::json ->> 'policy_id')::bigint;

    v_internal_payload := (v_internal_payload::jsonb || ('{"is_updated":false,"is_all":false,"is_keep_agent_policy":' || CASE WHEN (SELECT (json_array_elements(i_logical_target::json) ->> 'type') = 'GROUP') THEN 'false' ELSE 'true' END || '}')::jsonb)::text;

  END IF;

  /* get : job info */
  --SELECT t.job_id INTO v_tb_job_id FROM tb_task AS t WHERE t.task_id = i_task_id ;
  SELECT t.job_id, j.admin_id, j.is_schedule
    INTO v_tb_job_id, v_tb_admin_id, v_tb_is_schedule
    FROM tb_task AS t
    JOIN tb_job AS j USING(job_id)
   WHERE t.task_id = i_task_id
   limit 1;

  /* get : user info */
  SELECT profile_type
    INTO v_tb_profile_type
    FROM tb_admin AS ta
    JOIN tb_privilege_profile AS tp USING( privilege_profile_id )
   WHERE ta.admin_id = i_admin_id;

  /* get : LU UPDATE policy info */
  SELECT t.task_id, t.job_id
  INTO v_lu_update_task_id, v_lu_update_job_id
  FROM tb_task t
  WHERE create_time = ( SELECT create_time FROM tb_task WHERE task_id = i_task_id )
  AND (COALESCE(internal_payload, '') <> '')
  AND (COALESCE((internal_payload::json ->> 'policy_id'), '') <> '')
  AND (internal_payload::json ->> 'policy_id')::bigint =
  (
    SELECT policy_id FROM tb_policy WHERE ppolicy_id =
    (SELECT (internal_payload::json ->> 'policy_id')::bigint FROM tb_task WHERE task_id = i_task_id)
  )
  ;

  /* check : is_schedule */
  IF v_tb_is_schedule IS NOT TRUE THEN
    RAISE EXCEPTION 'request data is no scheduled job.' USING HINT = 'DB-90001';
  END IF ;

  /* check : privilege */
  IF v_tb_profile_type IS NULL OR (v_tb_profile_type <> 'ROOT_ADMIN' AND v_tb_admin_id <> i_admin_id) THEN
    RAISE EXCEPTION 'You do not have permission.(%)', i_task_id USING HINT = 'DB-00022';
  END IF ;

  /* update tb_task */
  UPDATE tb_task AS t
  SET
    modified_time     = now(),
    logical_payload   = i_logical_payload,
    internal_payload   = v_internal_payload,
    server_context_payload = server_context,
    console_context_payload = console_context
  WHERE t.task_id       = i_task_id
  ;

  /* update tb_job */
  UPDATE tb_job AS j
  SET
    modified_time     = now(),
    schedule_detail   = i_schedule_detail,
    logical_target    = i_logical_target,
    target_filter    = i_target_filter
    --correlation_rule_id
    --onoff
    --visible
  WHERE j.job_id        = v_tb_job_id
  ;

  /* update tb_task for lu update */
  UPDATE tb_task AS t
  SET
    modified_time     = now(),
    internal_payload   =
    jsonb_set(internal_payload::jsonb,'{policy_id}', to_jsonb(
    (SELECT policy_id FROM tb_policy WHERE ppolicy_id = (v_internal_payload::json ->> 'policy_id')::bigint)
  ))::TEXT,
    server_context_payload = server_context
  WHERE t.task_id       = v_lu_update_task_id
  ;

  /* update tb_job for lu update */
  UPDATE tb_job AS j
  SET
    modified_time     = now(),
    schedule_detail   = i_schedule_detail,
    logical_target    = i_logical_target,
    target_filter    = i_target_filter
    --correlation_rule_id
    --onoff
    --visible
  WHERE j.job_id        = v_lu_update_job_id
  ;

  RETURN QUERY
  SELECT R.JOB_ID
  FROM (
  SELECT v_tb_job_id::text AS JOB_ID
  UNION ALL
  SELECT v_lu_update_job_id::text AS JOB_ID
  ) R
  WHERE R.JOB_ID IS NOT NULL
  ;

END;
$$;


ALTER FUNCTION public.sp_set_task_schedule(i_task_id bigint, i_task_type public.en_task_type, i_logical_target text, i_target_filter text, i_schedule_detail text, i_logical_payload text, i_internal_payload text, server_context text, console_context text, i_admin_id text) OWNER TO cppoltp;

--
-- Name: sp_set_task_target(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_task_target(i_task_id bigint, i_exception_node_id bigint[]) RETURNS TABLE(err_code text, err_msg text, include_monitor boolean, target_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_logical_target json;
  v_type text;
  v_target_id bigint[];
  v_ip_range inet[2];
  v_ip_cidr_array cidr[];
  v_ip_cidr cidr;
  v_include_monitor boolean DEFAULT false;

BEGIN

  -- 기존 데이터 삭제
  DELETE
  FROM tb_task_target
  WHERE task_id = i_task_id;

  FOR v_logical_target IN
    -- logical_target 조회
    SELECT json_array_elements(logical_target::json) AS logical_target
    FROM tb_job
    WHERE job_id = (SELECT job_id
                    FROM tb_task
                    WHERE task_id = i_task_id)
  LOOP

    -- target_id 추출
    SELECT trim(type::text, '"')
    INTO v_type
    FROM (SELECT v_logical_target::json -> 'type' AS type) AS type;

    IF v_type = 'IP_SINGLE' THEN

      SELECT array_cat(v_target_id, array_agg(node_id))
      INTO v_target_id
      FROM tb_node
      WHERE ip IN (SELECT trim(target::text, '"') AS target
                   FROM json_array_elements((SELECT v_logical_target::json -> 'target' AS target)::json) AS target)
        AND node_id NOT IN (SELECT * FROM unnest(i_exception_node_id))
        AND is_removed = false
        ;

    ELSIF v_type = 'IP_RANGE' THEN

      SELECT array_agg(trim(target::text, '"')::inet)
      INTO v_ip_range
      FROM json_array_elements((SELECT v_logical_target::json -> 'target' AS target)::json) AS target;

      SELECT array_cat(v_target_id, array_agg(node_id))
      INTO v_target_id
      FROM tb_node
      WHERE ip BETWEEN v_ip_range[0] AND v_ip_range[1]
        AND node_id NOT IN (SELECT * FROM unnest(i_exception_node_id))
        AND is_removed = false
        ;

    ELSIF v_type = 'IP_CIDR' THEN

      SELECT array_agg(trim(target::text, '"')::cidr)
      INTO v_ip_cidr_array
      FROM json_array_elements((SELECT v_logical_target::json -> 'target' AS target)::json) AS target;

      FOREACH v_ip_cidr IN ARRAY v_ip_cidr_array
      LOOP

        SELECT array_cat(v_target_id, array_agg(node_id))
        INTO v_target_id
        FROM tb_node
        WHERE ip::inet <<= v_ip_cidr
          AND node_id NOT IN (SELECT * FROM unnest(i_exception_node_id))
          AND is_removed = false
          ;

      END LOOP;

    ELSIF v_type = 'GROUP' THEN

      SELECT array_cat(v_target_id, array_agg(node_id))
      INTO v_target_id
      FROM tb_node
      WHERE group_id IN (SELECT trim(target::text, '"')::bigint AS target
                         FROM json_array_elements((SELECT v_logical_target::json -> 'target' AS target)::json) AS target)
        AND node_id NOT IN (SELECT * FROM unnest(i_exception_node_id))
        AND is_removed = false
        ;

    ELSIF v_type = 'NODE' THEN

      SELECT array_cat(v_target_id, array_agg(node_id))
      INTO v_target_id
      FROM tb_node
      WHERE node_id IN (SELECT trim(target::text, '"')::bigint AS target
                        FROM json_array_elements((SELECT v_logical_target::json -> 'target' AS target)::json) AS target)
        AND node_id NOT IN (SELECT * FROM unnest(i_exception_node_id))
        AND is_removed = false
        ;

    ELSIF v_type = 'PLATFORM' THEN

      SELECT array_cat(v_target_id, array_agg(node_id))
      INTO v_target_id
      FROM tb_node
      WHERE platform_id IN (SELECT trim(target::text, '"')::en_platform_id_type AS target
                              FROM json_array_elements((SELECT v_logical_target::json -> 'target' AS target)::json) AS target)
        AND node_id NOT IN (SELECT * FROM unnest(i_exception_node_id))
        AND is_removed = false
        ;

    ELSIF v_type = 'MONITOR' THEN

      v_include_monitor = true;

    END IF;

  END LOOP;

  IF (SELECT array_length(v_target_id, 1)) > 0 THEN

    SELECT array_agg(DISTINCT target)
    INTO v_target_id
    FROM unnest(v_target_id) target;

    SELECT t.task_id
          ,unnest(v_target_id)
          ,t.logical_payload
          ,now()
    FROM tb_task t
    WHERE t.task_id = i_task_id;

  END IF;

  RETURN QUERY SELECT 'DB-00000'::text, 'success'::text, v_include_monitor, v_target_id::text;

END;
$$;


ALTER FUNCTION public.sp_set_task_target(i_task_id bigint, i_exception_node_id bigint[]) OWNER TO cppoltp;

--
-- Name: sp_set_task_target_filter(text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_task_target_filter(i_target_filter text) RETURNS TABLE(target_id bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_target_filter json;
  v_type text;
  v_target_id bigint[];

BEGIN

  SELECT array_agg(n.node_id)
  INTO v_target_id
  FROM tb_node n
  WHERE n.is_removed = FALSE;

  IF i_target_filter IS NOT NULL AND i_target_filter <> '' THEN

    FOR v_target_filter IN
      -- target_filter 조회
      SELECT json_array_elements(i_target_filter::json) AS target_filter

    LOOP

      -- target_id 추출
      SELECT trim(type::text, '"')
      INTO v_type
      FROM (SELECT v_target_filter::json -> 'type' AS type) AS type;

      IF v_type = 'PRODUCT_ID' THEN
        -- (CWPP-6500) CWPP-3624 이슈 관련 처리 로직 추가
        SELECT ARRAY_AGG(target.node_id) INTO v_target_id
        FROM (
            WITH target_node_ids AS (
              SELECT node_id
              FROM UNNEST(v_target_id) AS node_ids(node_id)
            )
            -- 에이전트 미설치 체크
            SELECT tb_node.node_id
            FROM tb_node
            WHERE
              EXISTS (SELECT 1 FROM target_node_ids WHERE target_node_ids.node_id = tb_node.node_id)
              AND tb_node.machine_uuid IS NULL
            UNION
            -- 제품 설치 여부 체크
            SELECT tb_product_info.node_id
            FROM tb_product_info
            WHERE
              EXISTS (SELECT 1 FROM target_node_ids WHERE target_node_ids.node_id = tb_product_info.node_id)
              AND tb_product_info.product_id IN (SELECT trim(filter::text, '"')::en_product_id_type AS filter
                                                  FROM json_array_elements((SELECT v_target_filter::json -> 'filter' AS filter)::json) AS filter)
        ) AS target;

      ELSIF v_type = 'PRODUCT_PKG_ID' THEN

        WITH pkg_platform_type AS (
            SELECT
                EXISTS (
                    SELECT
                        1
                    FROM
                        tb_pkg_platform pp
                    INNER JOIN
                        tb_platform tp 
                    ON
                        pp.platform_id = tp.platform_id 
                    WHERE
                        tp.platform_type = 'WINDOWS'
                    AND
                        pp.product_pkg_id IN (SELECT trim(filter::text, '"')::integer AS filter
                                                FROM json_array_elements((SELECT v_target_filter::json -> 'filter' AS filter)::json) AS filter)
                    ) AS is_windows_pkg
        )
        SELECT ARRAY(SELECT unnest(v_target_id)
                     INTERSECT
                     SELECT unnest(array_agg(n.node_id)))
        INTO v_target_id
        FROM tb_node n
        INNER JOIN tb_platform tp ON n.platform_id = tp.platform_id
        WHERE
              (tp.platform_type = 'LINUX_UNIX' AND (SELECT is_windows_pkg = FALSE FROM pkg_platform_type))
        OR
              EXISTS (SELECT 1
                      FROM tb_pkg_platform pp
                      WHERE pp.platform_id = n.platform_id
                        AND pp.product_pkg_id IN (SELECT trim(filter::text, '"')::integer AS filter
                                                  FROM json_array_elements((SELECT v_target_filter::json -> 'filter' AS filter)::json) AS filter));

      ELSIF v_type = 'PLATFORM_PKG_GROUP' THEN

        SELECT ARRAY(SELECT unnest(v_target_id)
                     INTERSECT
                     SELECT unnest(array_agg(n.node_id)))
        INTO v_target_id
        FROM tb_node n
        WHERE EXISTS (SELECT 1
                      FROM tb_platform p
                      WHERE p.is_supported IS TRUE
                        AND p.platform_id = n.platform_id
                        AND p.platform_pkg_group IN (SELECT trim(filter::text, '"')::en_platform_id_type AS filter
                                                     FROM json_array_elements((SELECT v_target_filter::json -> 'filter' AS filter)::json) AS filter));

      END IF;

    END LOOP;

  END IF;

  RETURN QUERY
  SELECT t.target_id
  FROM unnest(v_target_id) AS t(target_id);

END;
$$;


ALTER FUNCTION public.sp_set_task_target_filter(i_target_filter text) OWNER TO cppoltp;

--
-- Name: sp_set_task_target_filter_connection(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_task_target_filter_connection() RETURNS TABLE(target_id text)
    LANGUAGE plpgsql
    AS $$

BEGIN

  RETURN QUERY
  SELECT array_agg(DISTINCT ns.node_id)
  FROM tb_node_status ns
  WHERE ns.connection_status = 'CONNECTED'
    AND EXISTS (SELECT 1 FROM tb_node n WHERE n.node_id = ns.node_id AND n.is_removed is false);

END;
$$;


ALTER FUNCTION public.sp_set_task_target_filter_connection() OWNER TO cppoltp;

--
-- Name: sp_set_task_target_in_target_id(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_task_target_in_target_id(i_task_id bigint, i_target_id bigint[]) RETURNS TABLE(target_id text)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_target_id bigint[];
  v_target_filter text;

BEGIN

  SELECT j.target_filter
  INTO v_target_filter
  FROM tb_job j
  JOIN tb_task t
  ON j.job_id = t.job_id
    AND t.task_id = i_task_id;

  SELECT ARRAY(SELECT unnest(i_target_id)
               INTERSECT
               SELECT unnest(array_agg(tf.target_id)))
  INTO v_target_id
  FROM sp_set_task_target_filter(v_target_filter) tf;

  SELECT DISTINCT t.task_id
        ,unnest(v_target_id)
        ,(CASE WHEN COALESCE(t.logical_payload, '') = '' THEN '{}' ELSE t.logical_payload END)::text
        ,now()
  FROM tb_task t
  WHERE t.task_id = i_task_id
  ON CONFLICT(task_id, target_id) DO NOTHING;

  RETURN QUERY SELECT v_target_id::text;

END;
$$;


ALTER FUNCTION public.sp_set_task_target_in_target_id(i_task_id bigint, i_target_id bigint[]) OWNER TO cppoltp;

--
-- Name: FUNCTION sp_set_task_target_in_target_id(i_task_id bigint, i_target_id bigint[]); Type: COMMENT; Schema: public; Owner: cppoltp
--

COMMENT ON FUNCTION public.sp_set_task_target_in_target_id(i_task_id bigint, i_target_id bigint[]) IS '
@brief 작업 대상 생성 - target_id 직접 입력
@in -
@out -
@return - TABLE';


--
-- Name: sp_set_task_target_node(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_task_target_node(i_task_id bigint) RETURNS TABLE(target_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE

  v_logical_target json;
  v_type text;
  v_target_id bigint[];
  v_ip_range inet[2];
  v_ip_cidr_array cidr[];
  v_ip_cidr cidr;
  v_node_id_array bigint[];
  v_platform_id_array en_platform_id_type[];
  v_group_id bigint;
  v_group_id_array bigint[];
  v_target_filter text;
  v_admin_id text;
  v_is_policy boolean;
  v_task_type text;

BEGIN

  -- 기존 데이터 삭제
  DELETE
  FROM tb_task_target
  WHERE task_id = i_task_id;

  -- task 정보 확인
  SELECT
    task_type 
    , CASE WHEN task_type = 'APPLY_POLICY' THEN FALSE  -- [CWPP-2611] 정책 적용은 하위그룹까지 적용하지 않고, 선택된 그룹만 적용한다
        ELSE TRUE END AS is_policy
    INTO v_task_type, v_is_policy
  FROM tb_task
  WHERE task_id = i_task_id;

  FOR v_logical_target IN
    -- logical_target 조회
    SELECT json_array_elements(logical_target::json) AS logical_target
    FROM tb_job
    WHERE job_id = (SELECT job_id
                    FROM tb_task
                    WHERE task_id = i_task_id)
  LOOP

    -- target_id 추출
    SELECT trim(type::text, '"')
    INTO v_type
    FROM (SELECT v_logical_target::json -> 'type' AS type) AS type;

    IF v_type = 'IP_SINGLE' THEN

      SELECT array_cat(v_target_id, array_agg(node_id))
      INTO v_target_id
      FROM tb_node
      WHERE ip IN (SELECT trim(target::text, '"')::inet AS target
                   FROM json_array_elements((SELECT v_logical_target::json -> 'target' AS target)::json) AS target)
      ;

    ELSIF v_type = 'IP_RANGE' THEN

      SELECT array_agg(trim(target::text, '"')::inet)
      INTO v_ip_range
      FROM json_array_elements((SELECT v_logical_target::json -> 'target' AS target)::json) AS target;

      SELECT array_cat(v_target_id, array_agg(node_id))
      INTO v_target_id
      FROM tb_node
      WHERE ip BETWEEN v_ip_range[1] AND v_ip_range[2];

    ELSIF v_type = 'IP_CIDR' THEN

      SELECT array_agg(trim(target::text, '"')::cidr)
      INTO v_ip_cidr_array
      FROM json_array_elements((SELECT v_logical_target::json -> 'target' AS target)::json) AS target;

      FOREACH v_ip_cidr IN ARRAY v_ip_cidr_array
      LOOP

        SELECT array_cat(v_target_id, array_agg(node_id))
        INTO v_target_id
        FROM tb_node
        WHERE ip::inet <<= v_ip_cidr;

      END LOOP;

    ELSIF v_type = 'GROUP' THEN

      SELECT array_agg(trim(target::text, '"')::bigint) AS target
      INTO v_group_id_array
      FROM json_array_elements((SELECT v_logical_target::json -> 'target' AS target)::json) AS target;

      SELECT j.admin_id
      INTO v_admin_id
      FROM tb_job j
      WHERE j.job_id = (SELECT t.job_id
                        FROM tb_task t
                        WHERE t.task_id = i_task_id);                      

      FOREACH v_group_id IN ARRAY v_group_id_array
      LOOP

          SELECT array_cat(v_target_id, n.node_id::BIGINT[])
          INTO v_target_id
          FROM (
              SELECT CASE WHEN array_agg(n_table.node_id)::TEXT IS NULL THEN '{}'
                          ELSE array_agg(n_table.node_id)::TEXT 
                          END AS node_id
              FROM (
                  SELECT REGEXP_SPLIT_TO_TABLE(node_string.node_id,',')::BIGINT AS node_id
                  FROM (
                      SELECT  CASE WHEN sg.node_id = '{}' THEN NULL
                              ELSE replace(replace(sg.node_id,'{',''),'}','')
                              END AS node_id
                      FROM sp_get_group_node_list(v_group_id, v_is_policy, v_admin_id) sg
                      ) node_string
                  ) n_table
              WHERE NOT EXISTS ( -- [CWPP-1391] AWS, AZURE 중 Agent가 UNINSTALL이면 수행 대상에서 제외, CWPP-3624 이슈로 인한 추가 수정
              			SELECT 1
                        FROM (
                            SELECT node.node_id
                            FROM tb_node node
                                INNER JOIN tb_node_status node_status ON node_status.node_id = node.node_id AND node_status.connection_status = 'UNINSTALLED'
                                INNER JOIN (
                                    SELECT instance_id AS cloud_id FROM tb_cloud_aws_instance
                                    UNION
                                    SELECT vm_id AS cloud_id FROM tb_cloud_azure_vm
                                    UNION
                                    SELECT instance_id AS cloud_id FROM tb_cloud_alibaba_instance
                                ) cloud_list ON UPPER(cloud_list.cloud_id) = UPPER(node.machine_uuid)
                            ) cloud_node
                        WHERE cloud_node.node_id = n_table.node_id
                    )
              ) n;

      END LOOP;

    ELSIF v_type = 'NODE' THEN

      SELECT array_cat(v_target_id, array_agg(n.node_id))
      INTO v_target_id
      FROM tb_node n
        LEFT JOIN tb_node_status tns
            ON tns.node_id = n.node_id      
      WHERE n.node_id IN (SELECT trim(target::text, '"')::bigint AS target
                        FROM json_array_elements((SELECT v_logical_target::json -> 'target' AS target)::json) AS target)
            AND tns.connection_status != 'UNINSTALLED'
      ;

    ELSIF v_type = 'PLATFORM' THEN

      SELECT array_agg(platform_id)
      INTO v_platform_id_array
      FROM tb_platform
      WHERE is_supported IS TRUE AND platform_group IN (SELECT trim(target::text, '"')::en_platform_id_type AS target
                               FROM json_array_elements((SELECT v_logical_target::json -> 'target' AS target)::json) AS target);

      SELECT array_cat(v_target_id, array_agg(node_id))
      INTO v_target_id
      FROM tb_node
      WHERE platform_id IN (SELECT * FROM unnest(v_platform_id_array));

    ELSIF v_type = 'DEPT' THEN

      SELECT array_agg(node_id)
      INTO v_node_id_array
      FROM tb_user
      WHERE department IN (SELECT trim(target::text, '"') AS target
                           FROM json_array_elements((SELECT v_logical_target::json -> 'target' AS target)::json) AS target);

      SELECT array_cat(v_target_id, array_agg(node_id))
      INTO v_target_id
      FROM tb_node
      WHERE node_id IN (SELECT * FROM unnest(v_node_id_array));
    END IF;

  END LOOP;

  IF (SELECT array_length(v_target_id, 1)) > 0 THEN
    SELECT j.target_filter INTO v_target_filter
    FROM tb_job j
      JOIN tb_task t ON j.job_id = t.job_id AND t.task_id = i_task_id;
    
    -- (CWPP-3624) 이슈 처리에 따른 정책 적용 task는 제품 설치 여부를 체크하지 않도록 처리하는 로직은 sp_set_task_target_filter으로 이동(CWPP-6500)
    SELECT ARRAY(SELECT unnest(v_target_id)
        INTERSECT
        SELECT unnest(array_agg(tf.target_id))) INTO v_target_id
      FROM sp_set_task_target_filter(v_target_filter) tf;
    
    SELECT i_task_id
          ,unnest(v_target_id)
          ,(
        CASE WHEN COALESCE(t.logical_payload, '') = '' THEN '{}'
        ELSE --t.logical_payload
            CASE WHEN COALESCE(t.logical_payload::json ->> 'send_time', '') = '' THEN t.logical_payload
            ELSE
                jsonb_set(t.logical_payload::jsonb,'{send_time}', to_jsonb(to_char(now(), 'YYYY-MM-DD HH24:MI:SS OF00')))::text
            END
        END
          )::text
          ,now()
    FROM tb_task t
    WHERE t.task_id = i_task_id;

  END IF;

  RETURN QUERY SELECT v_target_id::text;

END;
$$;


ALTER FUNCTION public.sp_set_task_target_node(i_task_id bigint) OWNER TO cppoltp;

--
-- Name: sp_set_task_target_payload(bigint, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_task_target_payload(i_task_id bigint, i_payload text) RETURNS void
    LANGUAGE plpgsql
    AS $$

BEGIN

  UPDATE tb_task
  SET logical_payload = i_payload
  WHERE task_id = i_task_id;

  UPDATE tb_task_target
  SET payload = i_payload
  WHERE task_id = i_task_id;

END;
$$;


ALTER FUNCTION public.sp_set_task_target_payload(i_task_id bigint, i_payload text) OWNER TO cppoltp;

--
-- Name: sp_set_task_target_replace_v3_payload(bigint, bigint[], public.en_product_id_type[]); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_task_target_replace_v3_payload(i_task_id bigint, i_target_id bigint[], i_product_id public.en_product_id_type[]) RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE
  v_payload_format text;
  v_payload_split text[];
  v_payload text;

BEGIN

  UPDATE tb_task_target tta
  SET payload = tp.payload
     ,modified_time = now()
  FROM (
        SELECT tta.task_id
              ,tta.target_id
              , CASE WHEN t.task_type = 'V3_EXEC_SCAN' AND (tp.product_id = 'V3NET_LU' OR tp.product_id = 'V3NET_9.0')
                     THEN jsonb_set(replace(tta.payload, '%v', tp.product_id)::jsonb, '{command}', '"PFRSSU5JVFlfQ01EPjxDTURfVFlQRSBiYWNrZ3JvdW5kPSIxIiBjYW5jZWxidG49IjEiIGF1dG9jdXJlPSIxIiBjcHVvcHRpb249IjEiPlZJUlVTX0JBU0lDX1NDQU48L0NNRF9UWVBFPjwvVFJJTklUWV9DTUQ+"'::jsonb, true)::text
                     
                     WHEN t.task_type = 'V3_EXEC_SCAN' AND tp.product_id = 'AMC_CLIENT'
                     THEN jsonb_set(replace(tta.payload, '%v', tp.product_id)::jsonb, '{command}', '"eyJoZWFkZXIiOnsidmVyc2lvbiI6IjEiLCJ0eXBlIjoiVklSVVNfQkFTSUNfU0NBTiJ9LCJib2R5Ijp7ImJhY2tncm91bmQiOiIxIiwiY2FuY2VsYnRuIjoiMSIsImF1dG9jdXJlIjoiMSIsImNwdW9wdGlvbiI6IjEiLCJzZWxlY3RlZHNjYW4iOiIwIiwic2Nhbl9wYXRoIjpbXX19"'::jsonb, true)::text
                     
                     ELSE replace(tta.payload, '%v', tp.product_id)::text
                     END AS payload
                FROM (SELECT unnest(i_target_id) AS target_id
                            ,unnest(i_product_id)::text AS product_id) tp
        INNER JOIN
            tb_task_target tta
        ON
            tp.target_id = tta.target_id
        AND
            tta.task_id = i_task_id
        INNER JOIN
            tb_task t
        ON
            tta.task_id = t.task_id
        INNER JOIN
            tb_task_type tt
        ON
            t.task_type = tt.task_type
        ) tp
  WHERE tta.task_id = tp.task_id
    AND tta.target_id = tp.target_id;

  UPDATE tb_task
  SET logical_payload = REPLACE(logical_payload, '%v', i_product_id[1]::text)
     ,server_context_payload = REPLACE(server_context_payload, '%v', i_product_id[1]::text)
     ,console_context_payload = REPLACE(console_context_payload, '%v', i_product_id[1]::text)
  WHERE task_id = i_task_id
    AND task_type IN ('V3_REMOVE_PRODUCT', 'UPDATE_PRODUCT') ;

END;
$$;


ALTER FUNCTION public.sp_set_task_target_replace_v3_payload(i_task_id bigint, i_target_id bigint[], i_product_id public.en_product_id_type[]) OWNER TO cppoltp;

--
-- Name: sp_set_task_target_server(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_task_target_server(i_task_id bigint) RETURNS TABLE(err_code text, err_msg text, target_id text)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_logical_target json;
  v_type text;
  v_target_id bigint[];

BEGIN

  -- 기존 데이터 삭제
  DELETE
  FROM tb_task_target
  WHERE task_id = i_task_id;

  FOR v_logical_target IN
    -- logical_target 조회
    SELECT json_array_elements(logical_target::json) AS logical_target
    FROM tb_job
    WHERE job_id = (SELECT job_id
                    FROM tb_task
                    WHERE task_id = i_task_id)
  LOOP

    -- target_id 추출
    SELECT trim(type::text, '"')
    INTO v_type
    FROM (SELECT v_logical_target::json -> 'type' AS type) AS type;

    IF v_type = 'SERVER' THEN

      SELECT array_cat(v_target_id, array_agg(s.server_id))
      INTO v_target_id
      FROM tb_server s
      WHERE s.server_id IN (SELECT trim(target::text, '"')::bigint AS target
                            FROM json_array_elements((SELECT v_logical_target::json -> 'target' AS target)::json) AS target);

    ELSIF v_type = 'SERVER_ANYONE' THEN

      SELECT array_agg(0)
      INTO v_target_id;

    ELSIF v_type = 'SERVER_ALL' THEN

      SELECT array_agg(s.server_id)
      INTO v_target_id
      FROM tb_server s;
    END IF;

  END LOOP;

  IF (SELECT array_length(v_target_id, 1)) > 0 THEN

    SELECT array_agg(DISTINCT t.target_id)
    INTO v_target_id
    FROM unnest(v_target_id) t(target_id);

    SELECT t.task_id
          ,unnest(v_target_id)
          ,t.logical_payload
          ,now()
    FROM tb_task t
    WHERE t.task_id = i_task_id;

  END IF;

  RETURN QUERY SELECT 'DB-00000'::text, 'success'::text, v_target_id::text;

END;
$$;


