--
-- Name: sp_set_unity_schedule_disabled(public.en_schedule_code, integer); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_unity_schedule_disabled(i_schedule_code public.en_schedule_code, i_schedule_index integer DEFAULT NULL::integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_schedule_id               bigint[];
  v_schedule_index            integer[];
BEGIN

  IF i_schedule_index IS NULL THEN
    SELECT ARRAY_AGG(s.schedule_code_index) INTO v_schedule_index FROM tb_schedule AS s WHERE s.schedule_code = i_schedule_code;
  ELSE
    v_schedule_index := ARRAY[i_schedule_index]::integer[];
  END IF;

  SELECT ARRAY_AGG(s.schedule_id) INTO v_schedule_id FROM tb_schedule AS s WHERE s.schedule_code = i_schedule_code AND s.schedule_code_index = ANY(v_schedule_index);

  UPDATE tb_schedule
    SET schedule = '{}'
      , enabled = false
      , modified_time = now()
  WHERE schedule_id = ANY(v_schedule_id);

  RETURN STRING_AGG(t.schedule_id::text, ',') FROM UNNEST(v_schedule_id) AS t(schedule_id);

END;
$$;


