--
-- Name: sp_set_update_pkg(text, public.en_pkg_type, character varying, character varying); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_update_pkg(i_server_ip text, i_pkg_type public.en_pkg_type, i_pkg_version character varying, i_pkg_path character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_server_id bigint;
  v_version varchar;
  v_product_pkg_id bigint;
BEGIN

  select server_id into v_server_id from tb_server where tb_server.ip = i_server_ip;

  LOCK TABLE tb_product_pkg IN ACCESS EXCLUSIVE MODE;

  IF( v_server_id IS NOT NULL ) THEN

      SELECT i_pkg_type, i_pkg_version, i_pkg_path, 'update', 'ahnlab update', now(), FALSE
      WHERE NOT EXISTS (SELECT pkg_type, version,  path FROM tb_product_pkg WHERE tb_product_pkg.pkg_type = i_pkg_type and tb_product_pkg.version = i_pkg_version and tb_product_pkg.path =  i_pkg_path AND tb_product_pkg.is_removed is FALSE);

    SELECT product_pkg_id into v_product_pkg_id FROM tb_product_pkg WHERE tb_product_pkg.pkg_type = i_pkg_type and tb_product_pkg.version = i_pkg_version and tb_product_pkg.path =  i_pkg_path;

    PERFORM sp_set_pkg_server(v_product_pkg_id, v_server_id);

    IF EXISTS ( SELECT * FROM tb_service where tb_service.server_id = v_server_id AND tb_service.service_type = 'FILESERVER-HTTP' and tb_service.enabled = 'true' ) THEN
      select version into v_version from sp_get_update_pkg('', i_pkg_type);

      IF( i_pkg_type = 'UPDATE_OES' ) THEN
        PERFORM sp_set_configs('UPDATE_SERVICE', ARRAY['oes_engine_date'], ARRAY[v_version] );
      ELSE
        PERFORM sp_set_configs('UPDATE_SERVICE', ARRAY['ses_engine_date'], ARRAY[v_version] );
      END IF;
    END IF;

  END IF;

END;
$$;


ALTER FUNCTION public.sp_set_update_pkg(i_server_ip text, i_pkg_type public.en_pkg_type, i_pkg_version character varying, i_pkg_path character varying) OWNER TO cppoltp;

