--

CREATE FUNCTION public.sp_set_user_info(i_node_id bigint, i_name text, i_department text, i_phone text, i_email text, i_description text, i_modified_by_admin boolean) RETURNS TABLE(response integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
  -- 연동 방식
  v_condition_column    TEXT;
  v_condition_value   TEXT;
BEGIN

    node_id
    , name
    , department
    , phone
    , email
    , description
    , modified_by_admin
  )
  VALUES
  (
    i_node_id
    , i_name
    , i_department
    , i_phone
    , i_email
    , i_description
    , i_modified_by_admin
  )
  ON CONFLICT (node_id) 
  DO UPDATE SET
    name = EXCLUDED.name
    , department = EXCLUDED.department
    , phone = EXCLUDED.phone
    , email = EXCLUDED.email
    , description = EXCLUDED.description
    , modified_by_admin = EXCLUDED.modified_by_admin;

  RETURN query SELECT 0 LIMIT 0;

END;
$$;


