--
-- Name: sp_set_v3_linux_policy(bigint, text, text, text, text, boolean, text, text, boolean, text, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_v3_linux_policy(i_policy_id bigint, i_policy_name text, i_description text, i_online_policy_body text, i_offline_policy_body text, i_use_offline_policy boolean, i_update_online_policy_body text, i_update_offline_policy_body text, i_use_update_offline_policy boolean, i_hash text, i_admin_id text) RETURNS TABLE(policy_id bigint, policy_name text, product_feature_id public.en_product_feature_id_type, description text, online_policy_body text, offline_policy_body text, use_offline_policy text, hash text)
    LANGUAGE plpgsql
    AS $$

DECLARE

  v_product_feature_id en_product_feature_id_type;
  v_update_policy_id bigint;
  v_privilege_profile_auth boolean;

BEGIN

SELECT p.product_feature_id
INTO v_product_feature_id
FROM tb_policy p
WHERE p.policy_id = i_policy_id;

SELECT
    EXISTS (
        SELECT
            1
        FROM
            tb_admin ta
        INNER JOIN
            tb_privilege_profile tpp
        ON
            ta.privilege_profile_id = tpp.privilege_profile_id 
        WHERE
            tpp.profile_body LIKE '%"/policy/policy_V3L_W"%'
        AND
            ta.admin_id = i_admin_id
    ) INTO v_privilege_profile_auth;

IF v_product_feature_id IS NULL THEN

  RAISE EXCEPTION 'policy_id (%) does not exist.', i_policy_id USING HINT = 'DB-00031';

ELSIF v_product_feature_id <> 'V3NET_LU_AV' THEN

  RAISE EXCEPTION 'policy_id (%) is not V3NET_LU_AV policy.', i_policy_id USING HINT = 'DB-00030';

END IF;

IF v_privilege_profile_auth = FALSE THEN
  RAISE EXCEPTION 'You do not have permission to write policy' USING HINT = 'DB-00084';
END IF;

  SELECT p.policy_id
  INTO v_update_policy_id
  FROM tb_policy p
  WHERE p.ppolicy_id = i_policy_id;

  RETURN QUERY
  --정책 수정
  SELECT p.policy_id AS policy_id
        ,p.policy_name AS policy_name
        ,p.product_feature_id AS product_feature_id
        ,p.description AS description
        ,p.online_policy_body AS online_policy_body
        ,p.offline_policy_body AS offline_policy_body
        ,p.use_offline_policy::integer::text AS use_offline_policy
        ,p.hash AS hash
  FROM sp_set_policy(i_policy_id, i_policy_name, 'V3NET_LU_AV', i_description, i_online_policy_body,
                        i_offline_policy_body, i_use_offline_policy, i_hash) p
  UNION ALL
  SELECT up.policy_id AS policy_id
        ,up.policy_name AS policy_name
        ,up.product_feature_id AS product_feature_id
        ,up.description AS description
        ,up.online_policy_body AS online_policy_body
        ,up.offline_policy_body AS offline_policy_body
        ,up.use_offline_policy AS use_offline_policy
        ,up.hash AS hash
  FROM sp_set_policy(v_update_policy_id, i_policy_name || '_update', 'V3NET_LU_UPDATE', i_description || '_update', i_update_online_policy_body,
                        i_update_offline_policy_body, i_use_update_offline_policy, (i_hash || '1')::text) up;

END;
$$;


