    LANGUAGE plpgsql
    AS $$

DECLARE

  v_product_feature_id en_product_feature_id_type;
  v_privilege_profile_auth boolean;

BEGIN

SELECT p.product_feature_id
INTO v_product_feature_id
FROM tb_policy p
WHERE p.policy_id = i_policy_id;

SELECT
    EXISTS (
        SELECT
            1
        FROM
            tb_admin ta
        INNER JOIN
            tb_privilege_profile tpp
        ON
            ta.privilege_profile_id = tpp.privilege_profile_id 
        WHERE
            tpp.profile_body LIKE '%"/policy/policy_V3W_W"%'
        AND
            ta.admin_id = i_admin_id
    ) INTO v_privilege_profile_auth;

IF v_product_feature_id IS NULL THEN

  RAISE EXCEPTION 'policy_id (%) does not exist.', i_policy_id USING HINT = 'DB-00031';

ELSIF v_product_feature_id <> 'V3NET_9.0_AV' THEN

  RAISE EXCEPTION 'policy_id (%) is not V3NET_9.0_AV policy.', i_policy_id USING HINT = 'DB-00030';

END IF;

IF v_privilege_profile_auth = FALSE THEN
  RAISE EXCEPTION 'You do not have permission to write policy' USING HINT = 'DB-00084';
END IF;

  RETURN QUERY
  SELECT p.policy_id AS policy_id
        ,p.policy_name AS policy_name
        ,p.product_feature_id AS product_feature_id
        ,p.description AS description
        ,p.online_policy_body AS online_policy_body
        ,p.offline_policy_body AS offline_policy_body
        ,p.use_offline_policy AS use_offline_policy
        ,p.hash AS hash
  FROM sp_set_policy(i_policy_id, i_policy_name, 'V3NET_9.0_AV', i_description, i_online_policy_body,
                     i_offline_policy_body, i_use_offline_policy, i_hash) p;

END;
$$;


