--
-- Name: sp_set_v3_pkg_update(boolean, boolean, text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_v3_pkg_update(i_v3_pkg_update_use boolean, i_v3_pkg_auto_update_use boolean, i_v3_pkg_update_schedule text) RETURNS TABLE(schedule_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_keys                      text[];
  v_values                    text[];
  v_index                     integer := 0;
  v_time                      text;

  v_schedule_id               text := null;
BEGIN

  v_keys := ARRAY[ 'v3_pkg_update_use', 'v3_pkg_auto_update_use', 'v3_pkg_update_schedule'];
  v_values := ARRAY[ i_v3_pkg_update_use::text, i_v3_pkg_auto_update_use::text, i_v3_pkg_update_schedule];

  PERFORM sp_set_configs( 'V3_PKG_UPDATE', v_keys, v_values );


  -- 스케줄 ID 관리
  IF i_v3_pkg_auto_update_use = true THEN
    v_schedule_id := sp_add_unity_schedule( 'V3', 'V3_PKG_UPDATE', 1, i_v3_pkg_update_schedule, true, '/api/console/ems/update/ahnlabcom/product', null );
  ELSE
    v_schedule_id := sp_set_unity_schedule_disabled( 'V3_PKG_UPDATE' );
  END IF;


  RETURN QUERY
    SELECT v_schedule_id;

END;
$$;


