--
-- Name: sp_set_widget(bigint[], text[], text[], bigint[], bigint[], text[], text[], text); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_set_widget(i_widget_id bigint[], i_widget_layout text[], i_name text[], i_group_id bigint[], i_correlation_rule_id bigint[], i_widget_item_type text[], i_widget_item_layout text[], i_admin_id text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_widget_id         bigint    DEFAULT 0;
  v_widget_item_type_array  text[];
  v_widget_item_layout_array  text[];
BEGIN


  --컬럼 길이 체크하기
  IF ARRAY_LENGTH(i_widget_layout, 1) <> ARRAY_LENGTH(i_widget_item_layout, 1) THEN
    RAISE EXCEPTION 'Different column array lengths.' USING HINT = 'DB-00020';
  END IF;


  FOR i IN 1..array_length(i_widget_layout, 1)
  LOOP

  --widget_item  길이 체크
  v_widget_item_type_array := regexp_split_to_array(replace(i_widget_item_type[i], ' ', ''), '\|');
  v_widget_item_layout_array := regexp_split_to_array(replace(i_widget_item_layout[i], ' ', ''), '\|');

  IF ARRAY_LENGTH(v_widget_item_type_array, 1) <> ARRAY_LENGTH(v_widget_item_layout_array, 1)
  THEN
    RAISE EXCEPTION 'Different column array lengths.' USING HINT = 'DB-00020';
  END IF;

  IF i_widget_id[i] IS NULL THEN

    --tb_widget insert
     name
    ,group_id
    ,layout
    ,correlation_rule_id
    ,admin_id)
  VALUES  (i_name[i]
          ,i_group_id[i]
    ,i_widget_layout[i]
    ,i_correlation_rule_id[i]
    ,i_admin_id)
  RETURNING tb_widget.widget_id INTO v_widget_id;

  ELSE

  DELETE FROM tb_widget_item
   WHERE widget_id = i_widget_id[i];

  UPDATE tb_widget
     SET  name = i_name[i]
         ,group_id = i_group_id[i]
         ,layout = i_widget_layout[i]
         ,correlation_rule_id = i_correlation_rule_id[i]
   WHERE widget_id = i_widget_id[i];

  SELECT i_widget_id[i] into v_widget_id;

  END IF;

  --tb_widget_item insert
     widget_id
    ,widget_item_type
    ,layout
    ,modified_time)
  SELECT v_widget_id
        ,t.widget_item_type::en_widget_item_type
        ,t.layout
        ,now()
    FROM unnest(
         v_widget_item_type_array
        ,v_widget_item_layout_array)
      AS t(widget_item_type
          ,layout);

  END LOOP;

END;
$$;


