--

CREATE FUNCTION public.sp_sp_get_node_list(i_srch_word text) RETURNS TABLE(node_id bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  RETURN QUERY
    SELECT node.node_id
    FROM tb_node node
    WHERE
      node.is_removed = false
      AND node.node_id ||' '||
  node.ip ||' '||
  node.mac ||' '||
  /*tb_node_nic.mac*/
  node.nt_domain
  LIKE '%'|| i_srch_word ||'%'

    UNION
    SELECT usr.node_id
    FROM tb_user usr LEFT JOIN tb_node node ON usr.node_id = node.node_id
    WHERE
      node.is_removed = false
      AND usr.name ||' '||
  usr.email ||' '||
  usr.empno ||' '||
  usr.department
  LIKE '%'|| i_srch_word ||'%'

--로그인한 사용자
--IP 주소 범위
--운영체제
--컴퓨터이름

;

END;
$$;


