--
-- Name: sp_unregister_node(bigint, text, public.en_machine_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_unregister_node(i_node_id bigint, i_machine_uuid text, i_machine_type public.en_machine_type) RETURNS TABLE(response integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_is_connect_cloud boolean;	-- 클라우드 계정 연동 상태 여부
BEGIN
	
	-- 유효한 에이전트 인지 판단 : CWPP-2916 : machine_type 조건 제거( and n.machine_type = i_machine_type )
	IF (NOT EXISTS (SELECT 1 FROM tb_node AS n WHERE n.node_id = i_node_id AND n.machine_uuid = i_machine_uuid AND n.is_removed IS FALSE)) THEN
		RETURN query SELECT 0 LIMIT 0;
		--  RAISE EXCEPTION 'Invalid node_id(%)', i_node_id USING HINT = 'DB-00014';
	END IF;
	
	-- 클라우드 계정 연동 상태 확인(CWPP-3241)
	SELECT * INTO v_is_connect_cloud FROM sp_check_connect_cloud(i_machine_uuid, i_machine_type);
	
	IF v_is_connect_cloud THEN
		UPDATE
			tb_node_status
		SET
			connection_status = 'UNINSTALLED'::en_connection_status
			, server_time = NOW()
		WHERE
			node_id = i_node_id;
	ELSE
		UPDATE
			tb_node
		SET
			is_removed = TRUE
			, removed_time = NOW()
			, modified_time = NOW()
		WHERE node_id = i_node_id;
	END IF;
	
	-- 보안 제품 설치 정보 삭제
	PERFORM sp_unregister_product(i_node_id, NULL);
	
	RETURN query SELECT 0 LIMIT 0;
END;
$$;


ALTER FUNCTION public.sp_unregister_node(i_node_id bigint, i_machine_uuid text, i_machine_type public.en_machine_type) OWNER TO cppoltp;

--
-- Name: sp_unregister_product(bigint, public.en_product_id_type); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_unregister_product(i_node_id bigint, i_product_id public.en_product_id_type) RETURNS TABLE(response integer)
    LANGUAGE plpgsql
    AS $$
  DECLARE
  BEGIN
    
    IF i_product_id IS NOT NULL THEN  -- 기존 로직
      DELETE FROM tb_product_info WHERE node_id = i_node_id AND product_id = i_product_id;
    ELSE  -- CWPP-1682 추가
      DELETE FROM tb_product_info WHERE node_id = i_node_id;
    END IF;

    RETURN query SELECT 0 LIMIT 0;

  END;
$$;


ALTER FUNCTION public.sp_unregister_product(i_node_id bigint, i_product_id public.en_product_id_type) OWNER TO cppoltp;

--
-- Name: sp_update_correlation_phase(bigint); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_update_correlation_phase(i_correlation_rule_id bigint) RETURNS TABLE(error_code text, error_msg text)
    LANGUAGE plpgsql
    AS $_$
DECLARE v_phase bigint;
BEGIN

select phase into v_phase from tb_olap_correlation_phase where correlation_rule_id = i_correlation_rule_id;

if v_phase is null then
  v_phase = 0;
end if;

on conflict (correlation_rule_id) do update set phase = excluded.phase, modified_time = now();

execute 'update tb_correlation_result set phase = $1 where correlation_rule_id = $2 and phase = 0' using v_phase+1, i_correlation_rule_id;
execute 'delete from tb_correlation_result where correlation_rule_id = $1 and phase < $2 - 10' using i_correlation_rule_id, v_phase;

RETURN QUERY select '0'::text, 'SUCCESS'::text;

END;
$_$;


ALTER FUNCTION public.sp_update_correlation_phase(i_correlation_rule_id bigint) OWNER TO cppoltp;

