-- Name: sp_update_shard_map(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.sp_update_shard_map() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

  SELECT s+1, s+100, 'READY'
  FROM (
    SELECT generate_series(0, MAX(node_id) / 100)*100 AS s
    FROM tb_node
    WHERE is_removed = false
  ) t
  ON CONFLICT(start_id, end_id) DO UPDATE SET shard_status = EXCLUDED.shard_status;

END;
$$;


