--
-- Name: ssp_change_object_owner(character varying, character varying); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.ssp_change_object_owner(in_schema character varying, new_owner character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  object_types VARCHAR[];
  object_classes VARCHAR[];
  object_type record;

  r record;
BEGIN
  object_types = '{type,table,sequence,index,table,view}';
  object_classes = '{c,t,S,i,r,v}';

  FOR object_type IN
      SELECT unnest(object_types) type_name,
                unnest(object_classes) code
  loop
    FOR r IN
      EXECUTE '
          select n.nspname, c.relname
          from pg_class c, pg_namespace n
          where n.oid = c.relnamespace
            and nspname = ''' || in_schema || '''
            and relkind = ''' || object_type.code || ''''
    loop
      raise notice 'Changing ownership of % %.% to %',
                  object_type.type_name,
                  r.nspname, r.relname, new_owner;
      EXECUTE
        'alter ' || object_type.type_name || ' '
                 || r.nspname || '.' || r.relname
                 || ' owner to ' || new_owner;
    END loop;
  END loop;

  FOR r IN
    SELECT  p.proname, n.nspname,
       pg_catalog.pg_get_function_identity_arguments(p.oid) args
    FROM    pg_catalog.pg_namespace n
    JOIN    pg_catalog.pg_proc p
    ON      p.pronamespace = n.oid
    WHERE   n.nspname = in_schema
  LOOP
    raise notice 'Changing ownership of function %.%(%) to %',
                 r.nspname, r.proname, r.args, new_owner;
    EXECUTE
       'alter function ' || r.nspname || '.' || r.proname ||
       '(' || r.args || ') owner to ' || new_owner;
  END LOOP;

  FOR r IN
    SELECT *
    FROM pg_catalog.pg_namespace n
    JOIN pg_catalog.pg_ts_dict d
      ON d.dictnamespace = n.oid
    WHERE n.nspname = in_schema
  LOOP
    EXECUTE
       'alter text search dictionary ' || r.nspname || '.' || r.dictname ||
       ' owner to ' || new_owner;
  END LOOP;
END;
$$;


ALTER FUNCTION public.ssp_change_object_owner(in_schema character varying, new_owner character varying) OWNER TO cppoltp;

--
-- Name: ssp_change_sequence_nextval(character varying); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.ssp_change_sequence_nextval(in_schema character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  object_types VARCHAR[];
  object_classes VARCHAR[];
  object_type record;
  r record;
  BEGIN
    FOR r IN
      EXECUTE 'SELECT se.relname, co.column_name, co.table_name FROM information_schema.columns co,
       ( select c.relname
         from pg_class c, pg_namespace n
         where n.oid = c.relnamespace
         and nspname = ''public''
         and relkind =  ''S'' ) se
         where co.column_default LIKE ''%'' || se.relname || ''%'''
    loop
      EXECUTE
        'SELECT setval('''||r.relname||''', (SELECT MAX('||r.column_name||') FROM '||r.table_name||'))';
    END loop;
END;
$$;


ALTER FUNCTION public.ssp_change_sequence_nextval(in_schema character varying) OWNER TO cppoltp;

