--
-- Name: ssp_func_all_drop_over_11(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.ssp_func_all_drop_over_11() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
r RECORD;
BEGIN
  FOR r IN
   SELECT 'DROP '
    || CASE WHEN p.prokind = 'a' THEN 'AGGREGATE ' ELSE 'FUNCTION ' END
    || quote_ident(n.nspname) || '.' || quote_ident(p.proname) || '('
    || pg_catalog.pg_get_function_identity_arguments(p.oid) || ');' AS stmt
  FROM   pg_catalog.pg_proc p
  JOIN   pg_catalog.pg_namespace n ON n.oid = p.pronamespace
  WHERE  n.nspname = 'public'                     -- schema name (optional)
  AND    p.proname ILIKE 'sp_%'              -- function name
  -- AND pg_catalog.pg_function_is_visible(p.oid) -- function visible to user
  ORDER  BY 1
  LOOP
    EXECUTE r.stmt;
  END LOOP;

END;
$$;


ALTER FUNCTION public.ssp_func_all_drop_over_11() OWNER TO cppoltp;

--
-- Name: ssp_func_all_drop_under_10(); Type: FUNCTION; Schema: public; Owner: cppoltp
--

CREATE FUNCTION public.ssp_func_all_drop_under_10() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
r RECORD;
BEGIN
  FOR r IN
   SELECT 'DROP '
    || CASE WHEN p.proisagg THEN 'AGGREGATE ' ELSE 'FUNCTION ' END
    || quote_ident(n.nspname) || '.' || quote_ident(p.proname) || '('
    || pg_catalog.pg_get_function_identity_arguments(p.oid) || ');' AS stmt
  FROM   pg_catalog.pg_proc p
  JOIN   pg_catalog.pg_namespace n ON n.oid = p.pronamespace
  WHERE  n.nspname = 'public'                     -- schema name (optional)
  AND    p.proname ILIKE 'sp_%'              -- function name
  -- AND pg_catalog.pg_function_is_visible(p.oid) -- function visible to user
  ORDER  BY 1
  LOOP
    EXECUTE r.stmt;
  END LOOP;
 
END;
$$;


