--
-- Name: vw_ac_status; Type: VIEW; Schema: public; Owner: cppoltp
--

CREATE VIEW public.vw_ac_status AS
 SELECT ac.node_id,
    ac.product_id,
    ac.product_version,
    ac.service_status,
    ac.ac_status,
    ac.engine_version,
    ac.ckl_version,
    ac.engine_update_time,
    ac.engine_type,
    ac.mode_begin_time,
    ac.mode_end_time,
    ac.engine_date,
    ac.execute_date,
    ac.license_no,
    ac.license_user,
    ac.license_org,
    ac.integrity_status,
    ac.install_time,
    ac.client_time,
    ac.tz_offset,
    ac.server_time,
    ac.engine_state,
    ac.im_enable,
    ac.im_enable_real_time,
    ac.im_engine_version,
    ac.im_manual_time,
    ac.activation_code
   FROM (public.tb_ac_status ac
     JOIN public.tb_product_info pi ON (((ac.node_id = pi.node_id) AND (ac.product_id = pi.product_id))));


ALTER TABLE public.vw_ac_status OWNER TO cppoltp;

