--

CREATE VIEW public.vw_node_status AS
 SELECT tb_node_status.node_id,
    tb_node_status.connection_status,
    tb_node_status.server_time,
    tb_node_status.integrity_status,
    tb_node_status.tz_offset,
    tb_node_status.client_time,
    tb_node_status.license_no,
    tb_node_status.license_user,
    tb_node_status.license_org,
    tb_node_status.activation_code
   FROM public.tb_node_status;


