--
-- Name: vw_policy_status; Type: VIEW; Schema: public; Owner: cppoltp
--

CREATE VIEW public.vw_policy_status AS
 SELECT ps.node_id,
    ps.product_feature_id,
    ps.policy_status,
    ps.server_time,
    ps.tz_offset,
    ps.apply_time,
    ps.policy_id,
    pf.product_id
   FROM ((public.tb_policy_status ps
     JOIN public.tb_product_feature_map pf ON ((ps.product_feature_id = pf.product_feature_id)))
     JOIN public.tb_product_info pi ON (((ps.node_id = pi.node_id) AND (pf.product_id = pi.product_id))))
  WHERE (pf.product_id <> 'AGENT'::public.en_product_id_type)
UNION ALL
 SELECT ps.node_id,
    ps.product_feature_id,
    ps.policy_status,
    ps.server_time,
    ps.tz_offset,
    ps.apply_time,
    ps.policy_id,
    pf.product_id
   FROM (public.tb_policy_status ps
     JOIN public.tb_product_feature_map pf ON ((ps.product_feature_id = pf.product_feature_id)))
  WHERE (pf.product_id = 'AGENT'::public.en_product_id_type);


